main :: IO ()
main = do
  exampleFiles       <- findByExtension [".wok"] "test/examples"
  resolveFiles       <- findByExtension [".wok"] "test/resolve-examples"
  typecheckFiles     <- findByExtension [".wok"] "test/typecheck-examples"
  typecheckBadFiles  <- findByExtension [".wok"] "test/typecheck-fail-examples"
  anfFiles           <- findByExtension [".wok"] "test/typecheck-examples"
  typedAnfFiles      <- findByExtension [".wok"] "test/typecheck-examples"
  runFiles           <- findByExtension [".wok"] "test/run-examples"
  multFiles          <- findByExtension [".wok"] "test/multiplicity-examples"
  multFailFiles      <- findByExtension [".wok"] "test/multiplicity-fail-examples"
  perceusFiles       <- findByExtension [".wok"] "test/rc-examples"
  -- M2b-1 (Task 2): STATIC-ONLY handler corpus. These programs perform effects, so
  -- they cannot run on the RC store until the handler runtime lands (Tasks 3-5); they
  -- are wired ONLY to the static Perceus golden + balance-lint groups (NOT the
  -- RC-differential / heap-accounting groups, which execute the program).
  perceusHandlerFiles <- findByExtension [".wok"] "test/rc-perceus-handler"
  -- M2b-1 (Task 3+): handler programs that RUN on the RC store. As the handler
  -- runtime lands incrementally (Task 3 = install + return-arm; Tasks 4-5 = op
  -- dispatch + resume), each admitted program is wired to the RC-differential
  -- (Suite A) and heap-accounting (Suite B) groups, the same as 'test/rc-examples'.
  rcM2bFiles <- findByExtension [".wok"] "test/rc-m2b"
  -- M3-b (Task 3): STORED-CONTINUATION corpus. These programs route a captured
  -- continuation through a runtime cell (@__cont_store@/@__cont_take@), which the
  -- boundary guard ('firstOrderNoHandlerViolations') still REJECTS as an escaping
  -- resume until the store-route admission lands (Task 4). So they are wired NOT to
  -- the guard-gated 'rc differential'/'rc stats' corpus groups (which would
  -- 'assertFailure'), but to a dedicated group ('rcM3StoreTests') that runs the
  -- differential + heap-balance oracle via 'runModuleRCUnchecked' --- exactly the
  -- bypass the M2a-1 guard-rejected programs use ('assertRcAgrees'). When Task 4
  -- admits the route, these move into the auto-discovered corpus.
  rcM3Files <- findByExtension [".wok"] "test/rc-m3"
  -- FBIP S2 (Task 5): the in-place-reuse corpus. Kept out of the auto-discovered
  -- corpus (lives under 'test/rc-c-backend', its own directory) and listed
  -- explicitly so the FBIP parity + targeted assertions reference each file by
  -- name. Fed to 'rcCBackendParity' for the output + abstract==C + balance-lint
  -- parity check.
  -- Slice A Array corpus: programs importing Array that exercise the seven
  -- ops end-to-end through both the reference interpreter and the RC interpreter.
  -- These are handler-free (no Handle/ROp), so they go into the same differential
  -- (Suite A) and heap-accounting (Suite B) groups as 'test/rc-examples'.
  rcArrayFiles <- findByExtension [".wok"] "test/rc-array"
  -- Slice A Array out-of-bounds error corpus: programs that INTENTIONALLY trigger a
  -- PrimError (e.g. Array.index out of bounds). Both interpreters return Left, so
  -- 'rcDifferentialHarness' treats the pair as AGREEMENT (both-fail = pass). These
  -- programs must NOT go into the stats or C-backend-parity groups, which call
  -- 'assertFailure' on any Left result.
  rcArrayOobFiles <- findByExtension [".wok"] "test/rc-array-oob"
  -- Region Slice R1 (Task 6): the differential-oracle corpus for the arena
  -- routing pass.  All four programs are HANDLER-FREE (the module-level fence
  -- in 'planRegions' is therefore lifted and arena routing fires).  They are
  -- wired to the same 'rc differential' and 'rc stats' groups as the regular
  -- corpus, and also to 'rcCBackendParity' (abstract==C on all stats incl.
  -- 'arena_bytes'/'arena_peak'). A dedicated 'rcRegionCorpusTests' group
  -- additionally asserts the arena-specific invariants per-file.
  rcRegionFiles <- findByExtension [".wok"] "test/rc-region"
  -- String Slice E1 (Task 4): the differential-oracle corpus for the six String
  -- ops. Programs are handler-free and string-only (no Array import, to avoid
  -- the known length/index name conflict). Wired to the rc differential + rc stats
  -- + rcCBackendParity groups, matching the Array corpus pattern.
  rcStringFiles    <- findByExtension [".wok"] "test/rc-string"
  -- String OOB error corpus: programs that intentionally trigger a PrimError.
  -- Wired to rcDifferential only (both-fail = agreement).
  rcStringOobFiles <- findByExtension [".wok"] "test/rc-string-oob"
  -- String Slice E5 (Task 4): foldChars/decodeCharAt/charWidthAt/singleton corpus.
  -- Wired to rc differential + rc stats + rcCBackendParity + run-golden groups.
  rcStringFoldFiles <- findByExtension [".wok"] "test/rc-string-fold"
  -- Bytes Slice E6: the differential-oracle corpus for the six Bytes ops plus
  -- eqBytes.  Programs are handler-free.  Wired to rc differential + rc stats +
  -- rcCBackendParity groups, matching the String corpus pattern.
  rcBytesFiles    <- findByExtension [".wok"] "test/rc-bytes"
  -- Bytes OOB/error corpus: programs that intentionally trigger a PrimError
  -- (index out of bounds, fromList value > 255).  Wired to rcDifferential only
  -- (both-fail = agreement), matching the Array/String OOB pattern.
  rcBytesOobFiles <- findByExtension [".wok"] "test/rc-bytes-oob"
  -- FFI bytes-in Slice 1: deterministic producer corpus (__ffi_demo_copy /
  -- __ffi_demo_adopt).  Programs are handler-free.  Wired to rc differential +
  -- rc stats + C-backend parity, matching the rc-bytes pattern.
  rcFfiBytesFiles <- findByExtension [".wok"] "test/rc-ffi-bytes"
  -- FFI Slice 2 Task 6: real libc calls (memchr / strndup) via RForeignCall.
  -- Programs are handler-free. Wired to rc differential + rc stats + C-backend
  -- parity; also has a dedicated 3-backend parity + adopt saving pin group.
  rcFfiForeignFiles <- findByExtension [".wok"] "test/rc-ffi-foreign"
  -- FFI Slice 3 Task 3: Borrow read prims (length/byteAt/slice/memchr) + the
  -- Bytes.copy escape hatch, exercised over the internal __borrow_demo test
  -- fixture (a static deterministic buffer). Programs are handler-free.
  -- Wired to rc differential + rc stats + C-backend parity, matching the
  -- rc-ffi-bytes / rc-ffi-foreign corpus pattern; this is the foundation
  -- Task 5 (family-liveness) builds on, so it must be under the oracle first.
  -- FFI Slice 3 Task 6 negative controls in test/rc-borrow/. Two families, both
  -- excluded from the clean-path corpus groups (rc differential / rc stats / parity /
  -- close-count) because those RUN their file and a negative control is rejected, not
  -- runnable:
  --   * `death-*.wok`  : a Borrow that escapes its lending activation via one of the
  --     five non-continuation routes. REJECTED at compile time with a CarrierEscape in
  --     a normal build (the death-test compile-reject group below), and turned into a
  --     GENUINE ASan use-after-free under the test-only `ffi-borrow-noescape-negctrl`
  --     mutation (driven by scripts/asan-runtime.sh).
  --   * `contstore-*.wok` : the stored-continuation route (Q4). NOT a CarrierEscape and
  --     NOT a runnable UAF -- it is rejected at the M3 continuation-escape boundary
  --     (`firstOrderNoHandlerViolations`); see the dedicated assertion below.
  rcBorrowAllFiles <- findByExtension [".wok"] "test/rc-borrow"
  let isDeathFile      = isPrefixOf "death-" . takeBaseName
      isContStoreFile  = isPrefixOf "contstore-" . takeBaseName
      isNegControlFile f = isDeathFile f || isContStoreFile f
      rcBorrowDeathFiles     = filter isDeathFile rcBorrowAllFiles
      rcBorrowContStoreFiles = filter isContStoreFile rcBorrowAllFiles
      rcBorrowFiles          = filter (not . isNegControlFile) rcBorrowAllFiles
  -- FFI Slice 4 Task 4: the owned-INTO-C move-out corpus. The directory ALSO
  -- holds the Task-1 `coherence-*.wok` compile-reject fixtures (wired by explicit
  -- name below) and, later, the Task-6 `death-*.wok` mutation controls -- neither
  -- is a runnable positive; the runnable move-out corpus is everything else.
  rcFfiOwnedAllFiles <- findByExtension [".wok"] "test/rc-ffi-owned"
  let rcFfiOwnedRunFiles =
        filter (\f -> let b = takeBaseName f
                      in not (isPrefixOf "coherence-" b)
                         && not (isPrefixOf "death-" b))
               rcFfiOwnedAllFiles
  -- S3: env-gated parser-vs-parser differential over the corpus
  -- intersection (spec D7). WOK_WOKPARSE=path/to/wokparse enables it;
  -- unset, 'buildSexpDifferentialGroup' emits a single skip notice.
  wokparseEnv <- lookupEnv "WOK_WOKPARSE"
  sexpDifferentialGroup <- buildSexpDifferentialGroup wokparseEnv
  sexpReorderGroup <- buildSexpReorderGroup wokparseEnv
  sexpReorderPropertyGroup <- buildSexpReorderPropertyGroup wokparseEnv
  defaultMain $ testGroup "wok"
    [ testGroup "parse golden"
        [ goldenVsString (takeBaseName f) (goldenFor f) (parseToBS f)
        | f <- exampleFiles
        ]
    , fixityTests
    , resolveTests
    , typesSmokeTests
    , constraintTypesTests
    , envSmokeTests
    , envOverlayTests
    , sexpReadTests
    , sexpSurfaceTests
    , sexpLoaderTests
    , sexpDifferentialGroup
    , sexpReorderGroup
    , sexpReorderPropertyGroup
    , sourceOriginTests
    , preludeTests
    , modPathTests
    , importParseTests
    , qualifiedAccessTests
    , qualifiedImportPipelineTests
    , monadSmokeTests
    , unifyWalksTests
    , unifyTests
    , generalizeTests
    , zonkTests
    , builtinsTests
    , translateTests
    , dataTests
    , effectDeclTests
    , effectSigTests
    , namedInstanceTests
    , carrierRuleTests
    , effectGrammarTests
    , effectOpTests
    , effectHandlerTests
    , handlerValueTests
    , effectPressureTests
    , closedByDefaultTests
    , lambdaEffectScopingTests
    , ioGroundEffectTests
    , patternTests
    , exprBasicTests
    , exprLetTests
    , inferTypedTests
    , resumeBinderTypeTests
    , typedDeclBodyTests
    , clauseArityTests
    , unsupportedHeadTests
    , typedDeclClauseTests
    , programTests
    , bodylessSigTests
    , loaderTests
    , crossModuleFixityTests
    , crossModuleNameConflictTests
    , crossModuleRowParamTests
    , bodylessUserWarningTests
    , rowUnifyTests
    , recordDeclTests
    , typeLevelExtTests
    , recordConstructionTests
    , fieldAccessTests
    , recordPatternTests
    , rowShadowTests
    , forgottenResumeTests
    , patternCoverageTests
    , matchWarningTests
    , blockLayoutTests
    , irNameTests
    , anfTests
    , interpValueTests
    , interpPrimTests
    , utf8Tests
    , interpCafTests
    , interpMachineTests
    , interpEffectTests
    , oneShotOracleTests
    , interpEntryTests
    , interpWholeProgramTests
    , elaborateBasicTests
    , elaborateControlTests
    , elaborateRecordsTests
    , elaborateEffectsTests
    , elaborateModuleTests
    , typedAstTests
    , classParseTests
    , foreignModuleParseTests
    , foreignResolutionTests
    , foreignReferenceTests
    , foreignIoDischargeTests
    , externGateTests
    , classEnvTests
    , classRegisterTests
    , constraintAccumTests
    , solveTests
    , eqInferTests
    , eqDesugarTests
    , eqElaborateTests
    , matchCompilerTests
    , matchCoverageTests
    , multiplicityUnitTests
    , rcStoreTests
    , rcDropTests
    , rcIncrefTests
    , rcM3NodeTests
    , rcArrayNodeTests
    , rcArrayCCellTests
    , rcStringNodeTests
    , rcStringViewNodeTests
    , rcStringCCellTests
    , rcForeignBytesStoreTests
    , rcInlineStringTests
    , rcInlineStringSlotTests
    , rcArrayPrimTests
    , rcStringPrimTests
    , regionRoutingTests
    , rcSliceRoutingTests
    , rcSliceDeathTests
    , rcSliceAdversarialTests
    , wokRcHeapTests
    , wokRcReuseTests
    , wokRcReservedTests
    , wokRcReuseIrTests
    , rcReusePairingTests
    , rcMachineTests
    , rcModuleTests
    , rcLetRecTests
    , rcM2a1BaselineTests
    , rcM2a1LintTests
    , rcM2a1AliasTests
    , rcM2a1SiblingDropTests
    , borrowOnCallTests
    , sharedEnvEvalTests
    , testGroup "resolve golden"
        [ goldenVsString (takeBaseName f) (resolveGoldenFor f) (resolveToBS f)
        | f <- resolveFiles
        ]
    , testGroup "typecheck success golden"
        [ goldenVsString (takeBaseName f) (typecheckGoldenFor f) (typecheckSuccessHarness f)
        | f <- typecheckFiles
        ]
    , testGroup "typecheck fail golden"
        [ goldenVsString (takeBaseName f) (typecheckFailGoldenFor f) (typecheckFailHarness f)
        | f <- typecheckBadFiles
        ]
    , testGroup "anf golden"
        [ goldenVsString (takeBaseName f) (anfGoldenFor f) (anfElaborateHarness f)
        | f <- anfFiles
        ]
    , testGroup "typed-anf golden"
        [ goldenVsString (takeBaseName f) (typedAnfGoldenFor f) (typedAnfElaborateHarness f)
        | f <- typedAnfFiles
        ]
    , testGroup "run golden"
        [ goldenVsString (takeBaseName f) (runGoldenFor f) (runProgramHarness f)
        | f <- runFiles ++ rcStringFoldFiles
        ]
    , testGroup "multiplicity golden"
        [ goldenVsString (takeBaseName f) (multGoldenFor f) (multDumpHarness f)
        | f <- multFiles ]
    , testGroup "multiplicity fail golden"
        [ goldenVsString (takeBaseName f) (multFailGoldenFor f) (multFailHarness f)
        | f <- multFailFiles ]
    , multiplicityM3RedCheck
    , testGroup "perceus golden"
        [ goldenVsString (takeBaseName f) (perceusGoldenFor f) (perceusDumpHarness f)
        | f <- perceusFiles ]
    , testGroup "perceus lint"
        [ testCase (takeBaseName f) (perceusLintHarness f)
        | f <- perceusFiles ]
    -- M2b-1 (Task 2): STATIC-ONLY handler corpus --- the instrumented dump (golden)
    -- and the balance lint, but NOT the RC-run groups (no handler runtime yet).
    , testGroup "perceus handler golden"
        [ goldenVsString (takeBaseName f) (perceusHandlerGoldenFor f) (perceusDumpHarness f)
        | f <- perceusHandlerFiles ]
    , testGroup "perceus handler lint"
        [ testCase (takeBaseName f) (perceusLintHarness f)
        | f <- perceusHandlerFiles ]
    , testGroup "rc differential"
        [ testCase (takeBaseName f) (rcDifferentialHarness f)
        | f <- perceusFiles ++ rcM2bFiles ++ rcArrayFiles ++ rcArrayOobFiles ++ rcRegionFiles
            ++ rcStringFiles ++ rcStringOobFiles ++ rcStringFoldFiles
            ++ rcBytesFiles ++ rcBytesOobFiles ]
    , testGroup "rc stats"
        [ testGroup "heap accounting"
            [ testCase (takeBaseName f) (rcStatsHarness f)
            | f <- perceusFiles ++ rcM2bFiles ++ rcArrayFiles ++ rcRegionFiles ++ rcStringFiles ++ rcStringFoldFiles
                ++ rcBytesFiles ]
        , testGroup "golden"
            [ goldenVsString (takeBaseName f) (rcStatsGoldenFor f) (rcStatsDumpHarness f)
            | f <- perceusFiles ]
        ]
    , rcTeethTests perceusFiles
    , rcDeepListTests
    -- C-backend differential oracle (Task 3): the WHOLE in-scope corpus run
    -- through both the abstract heap and the C heap, asserting output + alloc-stat
    -- parity; plus targeted cross-heap/fallback/deep tests and the slot
    -- encode/decode round-trip property.
    , rcCBackendParity (perceusFiles ++ rcM2bFiles ++ rcFbipFiles ++ rcArrayFiles ++ rcRegionFiles
        ++ rcStringFiles ++ rcStringFoldFiles ++ rcBytesFiles)
    , rcCBackendTargeted
    , rcFbipTargeted
    , rcFbipFaultInjection
    , rcCBackendSlotProperty
    , rcPropertyTests
    , rcM2a1PropertyTests
    , rcM2bPropertyTests
    , rcArrayPropertyTests
    , rcStringPropertyTests
    , rcInlineStringPropertyTests
    , rcStringViewPropertyTests
    , rcBytesPropertyTests
    , bytesValidatorAgreementTests
    , rcArraySliceCTests
    -- M3 SOUNDNESS RED-CHECK INVENTORY (five independent floors post-H1/H2
    -- hardening; each test group verifies the floor bites when disabled):
    --
    -- (M3-a) once-sink: 'multiplicityM3RedCheck' (group "multiplicity m3 red-check")
    --   Strip @__cont_store@ from 'onceSinkNames' and the store-once arm flips
    --   to omega (@MultishotResume@ error). Reverts Task 1.
    --
    -- (M3-b / cycle, runtime) carrier-wall: 'rcM3CarrierWallTests'
    --   (group "m3 cycle red-check (carrier-wall is load-bearing)")
    --   Disable the runtime carrier-wall check in @__cont_store@ and a cyclic
    --   store + subsequent drop double-frees the owned set. Reverts Task 4.
    --   Also contains the H1 static fresh-local rule tests: neuter
    --   'scCellIsFresh' in 'storeRouteCells' and the op-arg-cell store +
    --   nested-handler store flip from rejected to admitted.
    --
    -- (M3-b / cycle, H2 subsumed) 2-cell cycle: 'rcM3TwoCellCycleSubsumedTests'
    --   (group "m3 #4: 2-cell cycle is SUBSUMED by H1's static fresh-local rule")
    --   Single-level runtime check alone misses a 2-cell cycle (gap is real),
    --   but H1 rejects any non-fresh-local cell before the cycle can form.
    --
    -- (M3-b / double-resume) rc==1 floor: 'rcM3DoubleResumeTests'
    --   (group "m3 double-resume red-check (rc==1 floor is load-bearing)")
    --   Neuter @moveOutCont@'s rc==1 assert and a second resume becomes a
    --   silent double-free (the floor fires at rc==2 on the FIRST resume
    --   attempt, before any frame is spliced). Also covers Task-3 no-incref.
    --
    -- (M3-b / owned-set, H2) raw-vs-named non-dedup: 'rcM3RawVsNamedOwnedSetTests'
    --   (group "m3 #5: raw-vs-named owned-set per-entry free is load-bearing")
    --   Naive dedup of the owned set collapses [A,A] to [A], freeing rc 2->1
    --   and leaving the cell LIVE (a leak). Per-entry free is required.
    , rcM3PropertyTests
    , rcReclaimTests
    , rcArenaStoreTests
    , rcRegionCorpusTests
    , rcRegionNegativeControl
    , rcEffectSafetyTests
    , rcM2bRejectTests
    , rcM3StoreTests rcM3Files
    , rcM3RejectTests
    , rcM3AdmitTests
    , rcM3CarrierWallTests
    , rcM3TwoCellCycleSubsumedTests
    , rcM3RawVsNamedOwnedSetTests
    , rcM3DoubleResumeTests
    , rcM2bResumeEscapeTests
    , rvRecMemberRepTests
    , rcM2b1FragmentTests
    , rcM2b2ContinuationOwnedTests
    -- FFI bytes-in Slice 1: dedicated group so `-p "ffi bytes"` selects it.
    -- Runs rc differential + rc stats + C-heap parity for rcFfiBytesFiles;
    -- mirrors the rc-bytes corpus wiring.
    , testGroup "ffi bytes"
        [ testGroup "rc differential"
            [ testCase (takeBaseName f) (rcDifferentialHarness f)
            | f <- rcFfiBytesFiles ]
        , testGroup "rc stats"
            [ testCase (takeBaseName f) (rcStatsHarness f)
            | f <- rcFfiBytesFiles ]
        , rcCBackendParity rcFfiBytesFiles
        , rcFfiBytesZeroCopySavingPin
        , rcFfiBytesSoundness
        , rcBytesChecksumTests
        ]
    -- FFI Slice 2 Task 6: real libc memchr/strndup + borrow-out + adopt oracle.
    -- Runs rc differential + rc stats + C-heap parity; dedicated group also pins
    -- the adopt zero-copy saving and the 3-backend output parity.
    , testGroup "rc-ffi-foreign"
        [ testGroup "rc differential"
            [ testCase (takeBaseName f) (rcDifferentialHarness f)
            | f <- rcFfiForeignFiles ]
        , testGroup "rc stats"
            [ testCase (takeBaseName f) (rcStatsHarness f)
            | f <- rcFfiForeignFiles ]
        , rcCBackendParity rcFfiForeignFiles
        , rcFfiForeignParity
        , rcFfiForeignSoundness
        ]
    -- FFI Slice 3 Task 3: Borrow read prims + Bytes.copy escape hatch, over
    -- the internal __borrow_demo fixture. Runs rc differential + rc stats +
    -- C-heap parity, mirroring the rc-ffi-bytes / rc-ffi-foreign wiring
    -- exactly. This closes the Task-3 review finding: prior to this group,
    -- the read prims had no committed RC-backend coverage even though they
    -- are correct (reproduced green ad hoc); Task 5 (family-liveness) builds
    -- directly on borrowSliceRC's CHeap slice path, so this is the
    -- foundation that must be under the oracle first.
    , testGroup "rc-borrow"
        [ testGroup "rc differential"
            [ testCase (takeBaseName f) (rcDifferentialHarness f)
            | f <- rcBorrowFiles ]
        , testGroup "rc stats"
            [ testCase (takeBaseName f) (rcStatsHarness f)
            | f <- rcBorrowFiles ]
        , rcCBackendParity rcBorrowFiles
        -- FFI Slice 3 Task 5: the ABSOLUTE foreign-borrow close count per malloc'd-
        -- producer program, pinned on BOTH backends. Parity (above) proves abstract ==
        -- C, but 0 == 0 would also pass if the close silently vanished on both; this
        -- pins the real N (exactly one close per lent buffer). Programs that use only
        -- the static __borrow_demo intrinsic lend nothing -> 0 closes.
        , testGroup "borrow close-count"
            [ testCase (takeBaseName f) (rcBorrowCloseCount f n)
            | (f, n) <- borrowCloseCounts ]
        -- FFI Slice 3 xhigh review Fix 1: the OBSERVABLE off-heap borrow-lent peak
        -- characterization (the TCO/deep-loop activation-scoped-close limitation).
        , testGroup "borrow lent-peak (TCO/deep-loop characterization)"
            [ testCase "17-tail-loop-borrow-lent-peak: 8 iterations x 65536 bytes accumulate (activation-scoped close)"
                (rcBorrowLentPeak "test/rc-borrow/17-tail-loop-borrow-lent-peak.wok" (8 * 65536)) ]
        -- FFI Slice 3 Task 6 (death-test matrix, compile-reject half / vacuity guard
        -- step 1). Each `death-*.wok` is the EXACT program scripts/asan-runtime.sh runs
        -- under the `ffi-borrow-noescape-negctrl` mutation to produce a genuine ASan
        -- use-after-free; here we pin that WITHOUT the mutation each is rejected at
        -- compile time with a CarrierEscape. Asserting the same program is normally
        -- rejected is what makes the mutation-confirmed UAF non-vacuous.
        , testGroup "borrow death-test compile-reject"
            [ testCase (takeBaseName f) (borrowDeathCompileRejects f)
            | f <- rcBorrowDeathFiles ]
        -- FFI Slice 3 Task 6 (stored-continuation route, Q4). The carrier rule does
        -- NOT independently fire here (a Borrow captured by a continuation is not
        -- surface-visible). The load-bearing guard is the M3 continuation-escape
        -- boundary: a captured continuation may not escape its op-arm body except into
        -- a `__cont_store` cell. This pins that a borrow-capturing continuation which
        -- escapes (alias-then-store) is REJECTED at that boundary -- so the borrow
        -- cannot ride a continuation out of its lending activation.
        , testGroup "borrow cont-store route (M3-boundary reject)"
            [ testCase (takeBaseName f) (borrowContStoreBoundaryRejects f)
            | f <- rcBorrowContStoreFiles ]
        -- FFI Slice 3 Task 7: the zero-copy saving pin (differential, not
        -- tautological -- see the group's doc comment above its definition).
        , rcBorrowZeroCopySavingPin
        ]
    -- FFI Slice 4 Task 4: the owned-INTO-C move-out router corpus. Mirrors the
    -- rc-ffi-foreign wiring exactly (rc differential = pure-ref vs RC-abstract;
    -- rc stats = alloc/free balance + stLive baseline; rcCBackendParity =
    -- RC-abstract vs RC-CHeap), giving 3-backend checksum parity plus the
    -- accounting balance for BOTH router branches. 00-consume-unique exercises
    -- the rc==1 MOVE (free once, 0 copy bytes); 01-consume-shared exercises the
    -- rc>1 COPY (fresh boundary buffer freed, original decremented and still
    -- readable -- the `length b` after the consume, whose success in the
    -- differential run IS the "original still readable" assertion).
    , testGroup "rc-ffi-owned"
        [ testGroup "rc differential"
            [ testCase (takeBaseName f) (rcDifferentialHarness f)
            | f <- rcFfiOwnedRunFiles ]
        , testGroup "rc stats"
            [ testCase (takeBaseName f) (rcStatsHarness f)
            | f <- rcFfiOwnedRunFiles ]
        , rcCBackendParity rcFfiOwnedRunFiles
        ]
    -- FFI Slice 4 Task 1: the compile-time owned-arg coherence gates. These lock
    -- down the surface-`owned` <=> blessed-`MoveOut` invariant the Task 4 router
    -- relies on: one POSITIVE anchor plus each of the three rejection directions,
    -- asserting on the specific TypeError constructor (not merely "some error").
    , testGroup "FFI Slice 4: owned-arg coherence"
        [ testCase "owned Bytes on a MoveOut-blessed sink type-checks"
            (ffiOwnedCoherenceAccepts
               "test/rc-ffi-owned/coherence-ok-owned-bytes.wok")
        , testCase "owned on a non-Bytes param -> ForeignOwnedArgNotBytes"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-not-bytes.wok"
               "ForeignOwnedArgNotBytes")
        , testCase "owned param with no blessed MoveOut -> ForeignOwnedArgNotBlessed"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-not-blessed.wok"
               "ForeignOwnedArgNotBlessed")
        , testCase "blessed MoveOut but no surface owned -> ForeignBlessedMoveOutNeedsOwned"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-moveout-needs-owned.wok"
               "ForeignBlessedMoveOutNeedsOwned")
        -- Regression pin: a PARENTHESIZED-tail arrow (`A -> (B -> C)`, parsed
        -- `TFun A (TParen (TFun B C))`) is type-identical to `A -> B -> C`. Before
        -- `argTransfers` unwrapped `TParen` in its spine walk, the walk truncated
        -- at the paren and dropped position 1's `owned`, bypassing this gate.
        , testCase "parenthesized-tail arrow doesn't bypass the gate -> ForeignOwnedArgNotBlessed"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-paren-arrow.wok"
               "ForeignOwnedArgNotBlessed")
        -- Regression pin: an arrow-TAIL `owned` (`Bytes -> owned (Bytes -> U64)`,
        -- parsed `TFun Bytes (TOwned (TParen (TFun Bytes U64)))`) places `owned`
        -- on a return type, not a parameter head, so it must be rejected as
        -- misplaced rather than silently reinterpreted as another parameter
        -- (the pre-fix behavior: `owned` was unconditionally transparent in
        -- `translateSig`, so this was type-identical to `Bytes -> Bytes -> U64`,
        -- arity 2, and previously rejected -- for the wrong reason -- as
        -- `ForeignBlessedMoveOutNeedsOwned`). See the fixture's own comment.
        , testCase "arrow-tail owned is rejected as misplaced -> OwnedModifierMisplaced"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-arrow-tail.wok"
               "OwnedModifierMisplaced")
        -- Diagnostic-defect regression (verified live): `owned` in an ORDINARY
        -- (non-foreign) signature used to be silently stripped by
        -- `translateSig`'s unconditional `TOwned` unwrap and compile away with
        -- no effect. `owned` is foreign-boundary-only metadata; it must now be
        -- a compile error everywhere else.
        , testCase "owned in ordinary (non-foreign) code -> OwnedModifierMisplaced"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-ordinary-code.wok"
               "OwnedModifierMisplaced")
        -- Diagnostic-defect regression: `owned` in a NON-parameter position of
        -- a foreign member (here, the RETURN type) used to be silently
        -- swallowed with no coherence check at all. `classifyOwnedParams` only
        -- strips `owned` from a parameter head, so a return-position `owned`
        -- now reaches `translateSig` untouched and is rejected.
        , testCase "owned on a foreign member's return type -> OwnedModifierMisplaced"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-return-misplaced.wok"
               "OwnedModifierMisplaced")
        -- Diagnostic-defect regression: `owned` NESTED inside a compound
        -- parameter type (`[owned Bytes]`) rather than at the parameter head
        -- itself. Also previously silently swallowed; now rejected.
        , testCase "owned nested inside a compound parameter type -> OwnedModifierMisplaced"
            (ffiOwnedCoherenceRejects
               "test/rc-ffi-owned/coherence-owned-nested-misplaced.wok"
               "OwnedModifierMisplaced")
        ]
    -- FFI Slice 4 Task 5: the owned-INTO-C move-out router, differentially
    -- fuzzed over RANDOM 'Bytes' contents (the Task 4 corpus above only pins
    -- two FIXED programs). See 'ffiOwnedIntoCPropertyTests' for the mechanism.
    , ffiOwnedIntoCPropertyTests
    ]

-- | (program, expected close count) for the malloc'd-producer corpus (FFI Slice 3
-- Task 5). Each `Demo.lendBuffer` that executes mallocs ONE buffer freed by ONE
-- activation-exit close; a slice shares the base buffer and adds no close.
borrowCloseCounts :: [(FilePath, Int)]
borrowCloseCounts =
  [ ("test/rc-borrow/07-foreign-lendbuffer.wok",        1)  -- one lend
  , ("test/rc-borrow/08-foreign-lendbuffer-clamp.wok",  2)  -- two lends (neg + over-large)
  , ("test/rc-borrow/09-malloc-lend-slice.wok",         1)  -- one lend + a slice (base closed once)
  , ("test/rc-borrow/10-case-arm-lend.wok",             2)  -- scrutinee lend + taken-arm lend
  , ("test/rc-borrow/11-recursion-per-activation.wok",  3)  -- one lend per lending activation (n=3,2,1)
  , ("test/rc-borrow/14-foreign-lendbuffer-huge-negative-clamp.wok", 1)  -- one lend (empty read)
  , ("test/rc-borrow/17-tail-loop-borrow-lent-peak.wok",  8)  -- one lend per loop iteration (n=8..1)
  ]

-- ---------------------------------------------------------------------------
-- FFI Slice 3 xhigh review Fix 1: OBSERVABLE off-heap borrow-lent peak.
--
-- '17-tail-loop-borrow-lent-peak.wok' lends a fresh 65536-byte buffer on each of
-- 8 TAIL-recursive loop iterations. The activation-scoped close (Task 5, KEPT
-- AS-IS by this fix -- family-liveness is a deferred optimization, not this fix's
-- job) frees iteration i's buffer only when iteration i's OWN lending activation
-- returns, which does not happen until the WHOLE chain of tail calls unwinds
-- (each recursive call nests inside the current activation's body). So all 8
-- lent buffers are live SIMULTANEOUSLY at the deepest point even though TCO
-- means the interpreter's own call stack never grows -- an O(N) peak that was
-- previously INVISIBLE to the oracle (the malloc'd buffers touch no wok_rc
-- stat). 'stBorrowLentPeak' now pins this exactly, on both backends.
-- ---------------------------------------------------------------------------

-- | Assert the off-heap borrow-lent high-water mark ('St.stBorrowLentPeak') for a
-- borrow-lending program, on BOTH backends (CHeap really mallocs; AbstractHeap
-- charges the same logical size, exactly like 'St.stCloses').
rcBorrowLentPeak :: FilePath -> Word64 -> Assertion
rcBorrowLentPeak path expected = do
  (absR, cR, _cAllocs, _cPeakBytes) <- withBothBackends path
  case (absR, cR) of
    (Right a, Right c) -> do
      assertEqual (path <> ": borrowLentPeak (AbstractHeap)")
        expected (St.stBorrowLentPeak (RCM.rcStats a))
      assertEqual (path <> ": borrowLentPeak (CHeap)")
        expected (St.stBorrowLentPeak (RCM.rcStats c))
    (Left e, _) -> assertFailure (path <> ": abstract backend FAILED: " <> show e)
    (_, Left e) -> assertFailure (path <> ": C backend FAILED: " <> show e)

-- ---------------------------------------------------------------------------
-- FFI Slice 3 Task 7: zero-copy saving pin.
--
-- Two DIFFERENT programs over the IDENTICAL source (`Demo.lendBuffer 4096`):
--   * '12-saving-borrow-read.wok' (PROGRAM A) reads the borrow via
--     `length`/`byteAt` only, with NO `Bytes.copy`. The borrow view is a
--     fixed 24 B 0xFFFA handle; the malloc'd 4096-byte buffer sits off the
--     wok_rc books (Task 5), so A's peak_bytes charges ONLY the handle.
--   * '13-saving-copy.wok' (PROGRAM B) reads the SAME `length`/`byteAt`
--     prefix, then ALSO calls `copy` (materializing an owned WokBytes) and
--     reads it (`eqBytes c c` -- a self-compare that DUPs the same cell
--     rather than allocating a second one, so exactly one copy is charged).
--     B's peak_bytes therefore charges the 24 B handle PLUS an n-byte
--     on-heap WokBytes copy.
--
-- The pin: peak_bytes(B) - peak_bytes(A) == the SAME charge
-- 'St.wouldBeCBytes' assigns an n-byte 'NBytes' value -- COMPUTED from the
-- store-layer formula, not a hardcoded magic number -- checked on BOTH the
-- C heap (ground truth 'wok_stat_peak_bytes', via 'withBothBackends') and
-- the abstract heap (must agree, per the existing 'rc-c-backend-parity'
-- peak_bytes-parity invariant already run over this corpus).
--
-- NON-VACUITY: this is a DIFFERENTIAL measurement across two genuinely
-- different programs on the SAME data, not a path compared to itself. If
-- `Bytes.copy` were ever changed to a zero-copy alias (no allocation), B's
-- peak_bytes would collapse to A's (24 B) and BOTH the vacuity-guard
-- inequality and the exact-delta equality below would fail. The vacuity
-- guard is asserted FIRST and independently of the exact-delta arithmetic,
-- so a regression that merely shrinks (rather than eliminates) the delta is
-- also caught by the equality, while a regression that eliminates it
-- entirely trips the strict inequality first with a clearer message.
-- ---------------------------------------------------------------------------

rcBorrowZeroCopySavingPin :: TestTree
rcBorrowZeroCopySavingPin = testGroup "borrow zero-copy saving pin"
  [ testCase "12-saving-borrow-read vs 13-saving-copy: peak_bytes delta == n-byte WokBytes charge" $ do
      (absA, cA, _, cPeakA) <- withBothBackends "test/rc-borrow/12-saving-borrow-read.wok"
      (absB, cB, _, cPeakB) <- withBothBackends "test/rc-borrow/13-saving-copy.wok"
      case (absA, cA, absB, cB) of
        (Right ra, Right _, Right rb, Right _) -> do
          let n              = 4096 :: Int
              expectedCharge = St.wouldBeCBytes (St.NBytes (BS.replicate n 0))
              absPeakA       = St.stPeakBytes (RCM.rcStats ra)
              absPeakB       = St.stPeakBytes (RCM.rcStats rb)
              cPeakA'        = fromIntegral cPeakA :: Int
              cPeakB'        = fromIntegral cPeakB :: Int
          -- Vacuity guard FIRST: the two programs must have genuinely
          -- different heap footprints on identical source data.
          assertBool
            ("vacuity guard: peak_bytes(copy)=" <> show cPeakB'
              <> " must exceed peak_bytes(borrow)=" <> show cPeakA'
              <> " -- the two programs must genuinely differ on identical data")
            (cPeakB' > cPeakA')
          -- The differential pin, on the C heap (ground truth allocator).
          assertEqual "CHeap: peak_bytes(copy) - peak_bytes(borrow) == n-byte WokBytes charge"
            expectedCharge (cPeakB' - cPeakA')
          -- The same pin on the abstract heap (must agree with CHeap; the
          -- existing rc-c-backend-parity group over this corpus already
          -- pins abstract peak_bytes == C peak_bytes per-file, so this is
          -- belt-and-suspenders on the DELTA specifically).
          assertEqual "AbstractHeap: peak_bytes(copy) - peak_bytes(borrow) == n-byte WokBytes charge"
            expectedCharge (absPeakB - absPeakA)
          -- Concrete numbers pinned (not just the delta), so a future
          -- regression to either side's absolute charge is also caught.
          assertEqual "CHeap peak_bytes(borrow) == 24 (fixed 0xFFFA handle, buffer off-heap)"
            (24 :: Int) cPeakA'
          assertEqual "CHeap peak_bytes(copy) == handle (24 B) + n-byte WokBytes charge"
            (24 + expectedCharge) cPeakB'
        (Left e, _, _, _) -> assertFailure ("program A (borrow-read) abstract backend FAILED: " <> show e)
        (_, Left e, _, _) -> assertFailure ("program A (borrow-read) C backend FAILED: " <> show e)
        (_, _, Left e, _) -> assertFailure ("program B (Bytes.copy) abstract backend FAILED: " <> show e)
        (_, _, _, Left e) -> assertFailure ("program B (Bytes.copy) C backend FAILED: " <> show e)
  ]

