-- | Bottom-up generic transform (syb's @everywhere@, inlined so the
-- test suite needs no extra dependency).
sexpEverywhere :: Data a => (forall b. Data b => b -> b) -> a -> a
sexpEverywhere f = f . gmapT (sexpEverywhere f)

-- | Apply a monomorphic rewrite wherever the generic traversal hits its
-- type; identity everywhere else.
sexpAdapt :: (Data a, Data b) => (b -> b) -> a -> a
sexpAdapt f x = Data.Maybe.fromMaybe x (cast . f =<< cast x)

sexpNormalize :: Module -> Module
sexpNormalize = sexpEverywhere step
  where
    step :: forall c. Data c => c -> c
    step =
      sexpAdapt stripE . sexpAdapt stripP . sexpAdapt stripAP . sexpAdapt stripT
        . sexpAdapt zeroInt . sexpAdapt zeroCon . sexpAdapt zeroVar . sexpAdapt zeroSym

    -- A zero-tail chain node is denotationally its head: v1's grammar
    -- funnels EVERY Exp-level parse through `EExpr head [tails]`, while
    -- the mapper builds EExpr only for a real E_Chain -- both mean the
    -- bare head when the tail list is empty.
    stripE (Abs.EParen e)    = e
    stripE (Abs.EExpr e [])  = e
    stripE e                 = e

    -- A parenthesized pattern standing where any Pat fits.
    stripP (Abs.PAtom (Abs.APParen p)) = p
    stripP p                           = p

    -- A parenthesized ATOM standing where an atom fits. An APParen
    -- around a non-atomic pattern is structurally REQUIRED (both paths
    -- must produce it) and stays.
    stripAP (Abs.APParen (Abs.PAtom a)) = a
    stripAP a                           = a

    stripT (Abs.TParen t) = t
    stripT t              = t

    zeroInt (Abs.WokInt (_, t)) = Abs.WokInt ((0, 0), t)
    zeroCon (Abs.ConId  (_, t)) = Abs.ConId  ((0, 0), t)
    zeroVar (Abs.VarId  (_, t)) = Abs.VarId  ((0, 0), t)
    zeroSym (Abs.VarSym (_, t)) = Abs.VarSym ((0, 0), t)

-- | First structural divergence between two normalized `show`s, with a
-- window of context on each side.
sexpShowDiffExcerpt :: String -> String -> String
sexpShowDiffExcerpt wokN sexpN =
  let common   = length (takeWhile id (zipWith (==) wokN sexpN))
      start    = max 0 (common - 80)
      window s = take 240 (drop start s)
  in "first divergence at show-position " ++ show common ++ ":\n"
       ++ "  wok:  ..." ++ window wokN ++ "\n"
       ++ "  sexp: ..." ++ window sexpN

-- | The ONE shared differential comparator, used by both the
-- Sexp.Surface end-to-end fixtures and the Sexp.Differential corpus
-- group: normalized structural equality, compared as `show`. On
-- mismatch the failure message carries the tree-diff excerpt AND both
-- printTree renderings. printTree is failure-message CONTEXT only,
-- never a secondary assertion: as an assertion it is strictly noisier
-- (it re-fails on the redundant parens normalization deliberately
-- forgives) while adding no structural signal `show` does not already
-- carry.
sexpAssertNormalizedEq
  :: String   -- ^ context: which file / fixture
  -> Module   -- ^ the wok-path (v1-parsed) tree
  -> Module   -- ^ the sexp-path (mapped) tree
  -> Assertion
sexpAssertNormalizedEq what wokT sexpT = do
  let wokN  = show (sexpNormalize wokT)
      sexpN = show (sexpNormalize sexpT)
  if sexpN == wokN
    then pure ()
    else assertFailure $ unlines
      [ what ++ ": normalized ASTs differ"
      , sexpShowDiffExcerpt wokN sexpN
      , "printTree (wok path):  " ++ Pr.printTree wokT
      , "printTree (sexp path): " ++ Pr.printTree sexpT
      ]

-- | Both parse paths of one corpus file must agree structurally after
-- the same reordering: `wokparse -sexp F` -> Read -> Surface vs
-- `Wok.Parsing.parse F` (spec D7, single-file form). The fixture dumps in
-- test/sexp-fixtures were produced by `grammar/c/wokparse -sexp`.
sexpSurfaceEndToEnd :: FixityTable -> String -> TestTree
sexpSurfaceEndToEnd table name =
  testCase (name ++ " maps to the v1 parse (post-reorder, normalized)") $ do
    dumpTxt <- TIO.readFile ("test/sexp-fixtures/" ++ name ++ ".sexp")
    srcTxt  <- TIO.readFile ("test/typecheck-examples/" ++ name ++ ".wok")
    datum   <- either (\e -> assertFailure ("reader rejected the dump: " ++ show e))
                      pure (Sexp.readSExp dumpTxt)
    mapped  <- either (\e -> assertFailure ("surface mapping failed: " ++ show e))
                      pure (Surface.surfaceModule datum)
    wokR    <- either (\e -> assertFailure ("reorder (wok path): " ++ show e))
                      pure (reorderModuleWith table (parseSrc srcTxt))
    sexpR   <- either (\e -> assertFailure ("reorder (sexp path): " ++ show e))
                      pure (reorderModuleWith table mapped)
    sexpAssertNormalizedEq name wokR sexpR

-- The fixity table 02-arithmetic's chains need. The corpus file itself
-- declares none (the compiler takes them from the prelude); both paths
-- get the SAME table, so the comparison stays fair.
sexpArithFixities :: FixityTable
sexpArithFixities =
  case buildFixityTable
         (parseSrc "module F\nfixity + left\nfixity * left tighter than +\n") of
    Right t -> t
    Left e  -> error ("sexpArithFixities: " ++ show e)

sexpSurfaceTests :: TestTree
sexpSurfaceTests = testGroup "Sexp.Surface"
  [ -- The five family-strictness dumps of grammar/c/test/test_sexpr.c
    -- (~line 120), ported verbatim: the mapper must be exactly as strict
    -- about FAMILIES as the C reader, and exactly as permissive about the
    -- two legal subsumptions (STMT accepts EXPR, BINDLHS accepts LHS|PAT).
    testGroup "family strictness (ported from test_sexpr.c)"
      [ testCase "a clean equation maps (and prints as `f = a`)" $
          surfaceShouldPrint
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Var \"a\") (seq))))"
            "f = a"

      , testCase "a TYPE in an expression slot is malformed" $
          surfaceShouldMalform
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (T_Var \"a\") (seq))))"

      , testCase "an EXPRESSION where a left-hand side belongs is malformed" $
          surfaceShouldMalform
            "(W_File (seq (D_Equation (E_Var \"f\") (E_Var \"a\") (seq))))"

      , testCase "an EXPRESSION in a pattern sequence is malformed" $
          surfaceShouldMalform
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq (E_Var \"x\"))) (E_Var \"a\") (seq))))"

      -- The two subsumption dumps are WELL-FORMED (the C reader accepts
      -- them); their constructs then land on v1 gaps, not on malformed.
      , testCase "STMT-accepts-EXPR subsumption is well-formed; S_Use then gaps" $
          surfaceShouldGapAt "S_Use"
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Block (seq (S_Use (seq (H_UseBind \"a\" \"b\"))) (E_Var \"a\"))) (seq))))"

      , testCase "BINDLHS-accepts-PAT subsumption is well-formed; a wildcard bind then gaps" $
          surfaceShouldGapAt "H_Bind"
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_LetIn (H_Bind (P_Wild) (E_Var \"a\")) (E_Var \"a\")) (seq))))"
      ]

  -- D5: the literal decoders, unit-tested directly. Inputs are the RAW
  -- SOURCE LEXEMES a WFC_TEXT field carries -- wok quotes included.
  , testGroup "literal decoders"
      [ testCase "plain string body" $
          Surface.decodeStringLexeme "\"abc\"" @?= Right "abc"
      , testCase "empty string" $
          Surface.decodeStringLexeme "\"\"" @?= Right ""
      , testCase "\\n \\t \\r decode" $
          Surface.decodeStringLexeme "\"a\\nb\\tc\\rd\"" @?= Right "a\nb\tc\rd"
      , testCase "\\\\ and \\\" and \\' decode" $
          Surface.decodeStringLexeme "\"a\\\\b\\\"c\\'d\"" @?= Right "a\\b\"c'd"
      , testCase "\\x41 decodes to A" $
          Surface.decodeStringLexeme "\"\\x41\"" @?= Right "A"
      , testCase "\\0 decodes to NUL" $
          Surface.decodeStringLexeme "\"\\0\"" @?= Right "\NUL"
      , testCase "\\x with one hex digit is rejected" $
          case Surface.decodeStringLexeme "\"\\x4\"" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      , testCase "unknown escape \\q is rejected" $
          case Surface.decodeStringLexeme "\"\\q\"" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      , testCase "a lexeme without its quotes is rejected" $
          case Surface.decodeStringLexeme "abc" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      , testCase "an unescaped interior quote is rejected" $
          case Surface.decodeStringLexeme "\"a\"b\"" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      , testCase "plain char" $
          Surface.decodeCharLexeme "'a'" @?= Right 'a'
      , testCase "escaped char forms" $ do
          Surface.decodeCharLexeme "'\\n'"   @?= Right '\n'
          Surface.decodeCharLexeme "'\\''"   @?= Right '\''
          Surface.decodeCharLexeme "'\\\\'"  @?= Right '\\'
          Surface.decodeCharLexeme "'\\x41'" @?= Right 'A'
      , testCase "a two-character char literal is rejected" $
          case Surface.decodeCharLexeme "'ab'" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      , testCase "an empty char literal is rejected" $
          case Surface.decodeCharLexeme "''" of
            Left _  -> pure ()
            Right r -> assertFailure ("expected rejection, got: " ++ show r)
      ]

  -- R1 against v1's post-retrofit arm surface: PLAIN -> HUArm with
  -- arity-many binders; CONTROL -> HOnceUArm with the continuation appended
  -- as the (arity+1)-th binder (both sides declare one-shot); RETURN
  -- (bare variable) -> HRetArm; VAR -> HParamV; ABORT -> gap.
  , testGroup "handler clause mapping (R1)"
      [ testCase "PLAIN + CONTROL + RETURN clauses map onto v1 arm forms" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_HandleIn \"\" (E_Handler \"Ask\" (seq (H_Clause 1 \"ask\" (seq (P_Var \"q\")) \"k\" (E_Var \"q\")) (H_Clause 2 \"\" (seq (P_Var \"v\")) \"\" (E_Var \"v\")))) (E_App (E_Var \"g\") (E_Unit))) (seq))))"
          case r of
            Right m -> Pr.printTree m
              @?= Pr.printTree (parseSrc "f = with Ask { once ask q k -> q; return v -> v } g ()")
            Left e -> assertFailure ("expected a full mapping, got: " ++ show e)

      , testCase "a lowercase install label + VAR clause map to EWithNamedH/HParamV" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_HandleIn \"st\" (E_Handler \"Ask\" (seq (H_Clause 3 \"cur\" (seq) \"\" (E_Int 0)) (H_Clause 0 \"ask\" (seq) \"\" (E_Var \"cur\")))) (E_Var \"x\")) (seq))))"
          case r of
            Right m -> Pr.printTree m
              @?= Pr.printTree (parseSrc "f = with st = Ask { var cur = 0; ask -> cur } in x")
            Left e -> assertFailure ("expected a full mapping, got: " ++ show e)

      , testCase "an ABORT clause is a SexpGap (v1 has no abort)" $
          surfaceShouldGapAt "H_Clause"
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_HandleIn \"\" (E_Handler \"Except\" (seq (H_Clause 4 \"throw\" (seq (P_Var \"e\")) \"\" (E_Var \"e\")))) (E_Var \"x\")) (seq))))"
      ]

  -- D6: well-formed v2 constructs v1 cannot express fire named gaps.
  , testGroup "v2-only constructs are SexpGap"
      [ testCase "D_Alias: v1 has no type-alias declaration" $
          surfaceShouldGapAt "D_Alias"
            "(W_File (seq (D_Alias \"T\" (seq) (T_Unit))))"

      , testCase "E_Assign: v1 has no := surface" $
          surfaceShouldGapAt "E_Assign"
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Assign (E_Var \"x\") (E_Var \"y\")) (seq))))"

      , testCase "E_UseIn: v1 has no use-rebind form" $
          surfaceShouldGapAt "E_UseIn"
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_UseIn (seq (H_UseBind \"a\" \"b\")) (E_Var \"x\")) (seq))))"

      , testCase "a real v2 dump (01-state-cell) gaps at E_Assign (:= arm)" $ do
          -- The gap FRONTIER moved with phase 2 of the prelude-v2 epic: the
          -- handler VALUE now maps (EHandlerV), so the first unmappable
          -- construct in accept/01 is its `cur := x` arm -- the := surface
          -- the epic explicitly defers.
          dumpTxt <- TIO.readFile "test/sexp-fixtures/v2-01-state-cell.sexp"
          surfaceShouldGapAt "E_Assign" dumpTxt
      ]

  -- The T_With row-attachment fix: the row belongs to the INNERMOST
  -- arrow (Infer.hs is the authority; printTree renders both
  -- attachments identically, so these compare NORMALIZED structure).
  , testGroup "T_With row attachment (innermost arrow)"
      [ testCase "a row over an arrow chain lands on the innermost arrow" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Sig (seq (H_SigName \"mk\" #f)) (T_With (T_Fun (T_Con (N_ModPath (seq (N_Name \"U64\" #t)))) (T_Fun (T_Unit) (T_Con (N_ModPath (seq (N_Name \"U64\" #t)))))) (seq (H_RowEntry 0 \"\" (some (T_Con (N_ModPath (seq (N_Name \"Conc\" #t)))))))) #f)))"
          case r of
            Right m -> sexpAssertNormalizedEq "T_With innermost attachment"
                         (parseSrc "mk : U64 -> () -> U64 with Conc") m
            Left e -> assertFailure ("expected a full mapping, got: " ++ show e)

      , testCase "a parenthesized T_With codomain (a distinct dump node) still maps" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Sig (seq (H_SigName \"mk\" #f)) (T_With (T_Fun (T_Con (N_ModPath (seq (N_Name \"U64\" #t)))) (T_With (T_Fun (T_Unit) (T_Con (N_ModPath (seq (N_Name \"U64\" #t))))) (seq (H_RowEntry 0 \"\" (some (T_Con (N_ModPath (seq (N_Name \"Conc\" #t))))))))) (seq (H_RowEntry 0 \"\" (some (T_Con (N_ModPath (seq (N_Name \"IO\" #t)))))))) #f)))"
          case r of
            Right m -> sexpAssertNormalizedEq "nested T_With codomain"
                         (parseSrc "mk : U64 -> (() -> U64 with Conc) with IO") m
            Left e -> assertFailure ("expected a full mapping, got: " ++ show e)
      ]

  -- Greedy-bodied operands must be re-wrapped where v1's grammar would
  -- have required source parens: compared as printTree, since the
  -- EParen node is exactly what is under test.
  , testGroup "greedy operand wrapping (chain head / chain rhs / dot receiver)"
      [ testCase "a greedy-bodied chain HEAD is wrapped" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Chain (E_If (E_Var \"c\") (E_Int 1) (E_Int 2)) (seq (H_ChainOp \"+\" #f (E_Int 3)))) (seq))))"
          case r of
            Right m -> Pr.printTree m @?= Pr.printTree (parseSrc "f = (if c then 1 else 2) + 3")
            Left e  -> assertFailure ("expected a full mapping, got: " ++ show e)

      , testCase "a greedy-bodied chain RHS is wrapped" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Chain (E_Var \"x\") (seq (H_ChainOp \"+\" #f (E_If (E_Var \"c\") (E_Int 1) (E_Int 2))) (H_ChainOp \"+\" #f (E_Int 3)))) (seq))))"
          case r of
            Right m -> Pr.printTree m @?= Pr.printTree (parseSrc "f = x + (if c then 1 else 2) + 3")
            Left e  -> assertFailure ("expected a full mapping, got: " ++ show e)

      , testCase "a greedy-bodied DOT receiver is wrapped" $ do
          r <- surfaceOfText
            "(W_File (seq (D_Equation (L_Prefix \"f\" #f (seq)) (E_Dot (E_Lambda (seq (P_Var \"x\")) (E_Var \"x\")) \"g\" #f) (seq))))"
          case r of
            Right m -> Pr.printTree m @?= Pr.printTree (parseSrc "f = (\\ x -> x) . g")
            Left e  -> assertFailure ("expected a full mapping, got: " ++ show e)
      ]

  -- D7 (single-file form): real dumps from the C front end reproduce the
  -- v1 parse of the same source, compared with the shared normalized
  -- structural comparator.
  , testGroup "end-to-end vs the v1 parser"
      [ sexpSurfaceEndToEnd emptyFixityTable "01-identity"
      , sexpSurfaceEndToEnd sexpArithFixities "02-arithmetic"
      , sexpSurfaceEndToEnd emptyFixityTable "04-maybe"
      , sexpSurfaceEndToEnd emptyFixityTable "08-patterns"
      , sexpSurfaceEndToEnd emptyFixityTable "09-higher-order"
      , sexpSurfaceEndToEnd emptyFixityTable "11-unit"
      ]
  ]

-- ---------------------------------------------------------------------
-- Wok.Loader (S2): the `.sexp` dispatch branch in parseAndPrep
-- ---------------------------------------------------------------------

-- The six corpus files with BOTH a v1 twin and a mapper-clean dump (the
-- same set the "end-to-end vs the v1 parser" group above exercises).
sexpLoaderCorpus :: [String]
sexpLoaderCorpus =
  ["01-identity", "02-arithmetic", "04-maybe", "08-patterns", "09-higher-order", "11-unit"]

-- Position-erased identity of a warning: the sexp path's SourceSpan points
-- into the .sexp dump text (spec D4), never the original .wok source, so a
-- literal Eq on TC.Warning would fail on position alone even when the two
-- paths agree on substance. Compare identity instead, the same way the
-- oracle contract already does for errors (spec D4/D8).
warningIdentity :: TC.Warning -> String
warningIdentity w = case w of
  TC.BodylessBinding name _ -> "BodylessBinding " ++ T.unpack name
  TC.RowShadow _ label outer inner ->
    "RowShadow " ++ T.unpack label ++ " " ++ show outer ++ " " ++ show inner
  TC.NonExhaustiveRecordPattern _ tag -> "NonExhaustiveRecordPattern " ++ T.unpack tag
  TC.NonExhaustiveMatch _ name -> "NonExhaustiveMatch " ++ T.unpack name
  TC.RedundantClause _ name idx -> "RedundantClause " ++ T.unpack name ++ " " ++ show idx
  TC.ForgottenResume _ eff op -> "ForgottenResume " ++ T.unpack eff ++ " " ++ T.unpack op
  TC.QualifierShadowsExisting qual src ns ->
    "QualifierShadowsExisting " ++ T.unpack qual ++ " " ++ T.unpack src ++ " " ++ T.unpack ns

sexpLoaderTests :: TestTree
sexpLoaderTests = testGroup "Sexp.Loader"
  [ testGroup "loadProgram: module name + imports match the .wok twin"
      [ testCase name $ do
          sexpR <- Loader.loadProgram ("test/sexp-fixtures/" ++ name ++ ".sexp") []
          wokR  <- Loader.loadProgram ("test/typecheck-examples/" ++ name ++ ".wok") []
          case (sexpR, wokR) of
            (Right (sexpEntry, sexpMs), Right (wokEntry, wokMs)) -> do
              sexpEntry @?= wokEntry
              case ( Data.List.find ((== sexpEntry) . Loader.lmName) sexpMs
                   , Data.List.find ((== wokEntry) . Loader.lmName) wokMs
                   ) of
                (Just sexpLm, Just wokLm) ->
                  map Loader.isModule (Loader.lmImports sexpLm)
                    @?= map Loader.isModule (Loader.lmImports wokLm)
                _ -> assertFailure "entry module missing from its own loaded module list"
            (Left e, _) -> assertFailure ("sexp load failed: " ++ show e)
            (_, Left e) -> assertFailure ("wok load failed: " ++ show e)
      | name <- sexpLoaderCorpus
      ]

  , testGroup "full pipeline: typecheckProgram schemes + warning identity match the .wok twin"
      [ testCase name $ do
          sexpSchemes <- typecheckSuccessHarness ("test/sexp-fixtures/" ++ name ++ ".sexp")
          wokSchemes  <- typecheckSuccessHarness ("test/typecheck-examples/" ++ name ++ ".wok")
          sexpSchemes @?= wokSchemes
          sexpR <- Loader.loadProgram ("test/sexp-fixtures/" ++ name ++ ".sexp") []
          wokR  <- Loader.loadProgram ("test/typecheck-examples/" ++ name ++ ".wok") []
          case (sexpR, wokR) of
            (Right (sexpEntry, sexpMs), Right (wokEntry, wokMs)) ->
              case ( Pipeline.typecheckProgram sexpEntry sexpMs
                   , Pipeline.typecheckProgram wokEntry wokMs
                   ) of
                (Right (_, sexpWarnings), Right (_, wokWarnings)) ->
                  map warningIdentity sexpWarnings @?= map warningIdentity wokWarnings
                (Left e, _) -> assertFailure ("sexp typecheck failed: " ++ e)
                (_, Left e) -> assertFailure ("wok typecheck failed: " ++ e)
            (Left e, _) -> assertFailure ("sexp load failed: " ++ show e)
            (_, Left e) -> assertFailure ("wok load failed: " ++ show e)
      | name <- sexpLoaderCorpus
      ]

  , testCase "a syntactically broken .sexp entry surfaces LoadParseError pointing into the .sexp file" $ do
      result <- Loader.loadProgram "test/sexp-fixtures/broken-unterminated.sexp" []
      case result of
        Left (Loader.LoadParseError path msg) -> do
          path @?= "test/sexp-fixtures/broken-unterminated.sexp"
          assertBool
            ("expected the message to carry a line:col position into the .sexp file, got: " ++ msg)
            (":" `Data.List.isInfixOf` msg)
        Left other -> assertFailure ("expected LoadParseError, got: " ++ show other)
        Right _    -> assertFailure "expected the broken dump to be rejected"
  ]

-- ---------------------------------------------------------------------
-- Sexp.Differential (S3): env-gated parser-vs-parser differential over
-- the corpus intersection (spec D7). WOK_WOKPARSE=path/to/wokparse
-- enables the group; unset, the group is a single always-passing notice
-- so CI without a C toolchain stays green (spec S3 acceptance).
-- ---------------------------------------------------------------------

-- | Gap LABELS this group tolerates on an EXCLUDED file. Keyed to the
-- stable construct label 'Surface.SexpGap' carries -- one label per
-- distinct gap RULE in the mapper -- NOT to the node tag: the tag is
-- whatever innermost node a rule fires on (a refutable let gaps at
-- H_Bind, an upper name in an import list at N_Name), so a tag-keyed
-- list both goes stale and lets a NEW gap rule hide under an
-- already-listed broad tag (H_Clause alone covers both the abort gap
-- and the pattern-return gap). Every entry below is one emission site
-- in Wok.Sexp.Surface, commented with the spec-inventory construct it
-- represents; a label OUTSIDE this set is a NEW finding, not a silent
-- skip, and fails the summary.
sexpDifferentialAllowedGapLabels :: Set.Set Text
sexpDifferentialAllowedGapLabels = Set.fromList
  [ -- category (c): no v1 equivalent, unconditional gaps
    "type-alias-decl"              -- D_Alias: v1 has no type-alias declaration
  , "use-rebind"                   -- E_UseIn: no `use x as label` rebind expression
  , "frame-slot-assign"            -- E_Assign: no `:=` assignment surface
  , "statement-handle"             -- S_Handle: no statement-form handler install
  , "statement-use"                -- S_Use: no use-rebind statement
  , "statement-discard"            -- S_Discard: no discarded-expression sequencing
  , "mid-block-expression"         -- E_Block: no non-final expression statement
  , "block-without-final-expr"     -- E_Block ending in a non-expression statement
    -- category (b): documented gap sub-cases of otherwise-mapped tags
  , "import-list-plus-alias"       -- D_Import: v1 ImportMod is one-of list/alias
  , "import-list-upper-name"       -- D_Import list entry: v1 lists are vars-only
  , "row-kinded-decl-param"        -- H_TyParam (row e) on effect/class decls
  , "class-extern-sig"             -- D_Class body: extern signature
  , "class-default-where"          -- D_Class default equation with a where-block
  , "class-body-decl-kind"         -- D_Class body: any other decl kind
  , "instance-method-where"        -- D_Instance method with a where-block
  , "instance-body-decl-kind"      -- D_Instance body: any other decl kind
  , "qualified-constraint-head"    -- instance context with a qualified class head
  , "non-constraint-context"       -- instance context not of `Class Type*` shape
  , "where-extern-sig"             -- where-block: extern signature
  , "where-decl-kind"              -- where-block: any other decl kind
  , "lend-transfer"                -- T_Transfer lend: no borrow-tier type spelling
  , "copy-transfer"                -- T_Transfer copy: v1 spells copy by omission
  , "non-arrow-with"               -- T_With over a non-arrow body
  , "row-var-not-tail"             -- H_RowEntry: row variable not in tail position
  , "role-row-entry"               -- H_RowEntry role obligation `(name : Eff)`
  , "qualified-effect-atom"        -- effect atom with a qualified head
  , "non-constructor-effect-atom"  -- effect atom not of `ConId Type*` shape
  , "qualified-record-pattern-head"-- P_Record with a qualified constructor head
  , "general-negation"             -- E_Neg of a non-integer-literal operand
  , "refutable-let-binding"        -- H_Bind lhs beyond eqn/var/tuple (e.g. `_`)
  , "qualified-record-head"        -- E_Record with a qualified constructor head
  , "computed-record-head"         -- E_Record head neither bare nor qualified constructor
  , "foreign-slot-label"           -- E_HandleIn literal install under a designation slot /= the effect
  , "slot-label-value-install"     -- E_HandleIn: slot label uncheckable against a non-literal handler
  , "pattern-return-clause"        -- H_Clause RETURN binding a pattern
  , "abort-clause"                 -- H_Clause ABORT (v1 spells never-resume via a dropped k)
  ]

-- | Files EXCLUDED despite a clean sexp mapping -- ONE remaining entry.
-- Keyed by 'takeBaseName'. History: this set once held 14 files in four
-- categories; the fix round dissolved three of the categories:
--
--   * REDUNDANT-PARENS LOSS (7 files: 11-eq-option, 14-eq-signed-option,
--     15-eq-u32, as-pattern-nested, coro-escape, coro-multi-driver,
--     03-expressions) -- dissolved by the normalized structural
--     comparator ('sexpAssertNormalizedEq'), which is deliberately blind
--     to optional grouping v2 does not retain. 03-expressions' PARSE
--     GOLDEN still byte-embeds its parens: see
--     'sexpParseGoldenEmbedsParens'.
--
--   * "POSITION-SENSITIVE TYPECHECK DIVERGENCE" (5 files:
--     conc-await-multi, conc-chan-order, conc-parall, coro-step-range,
--     coro-step-zip) -- the theory was OVERTURNED: positions were
--     irrelevant. The real cause was a T_With mapper bug (the effect row
--     attached to the OUTERMOST arrow where v1 and Infer.hs attach it to
--     the INNERMOST), invisible to the then-printTree comparator because
--     printTree renders both attachments as the same text. Fixed in
--     Wok.Sexp.Surface ('mapWithArrow'); all five files re-entered fully.
--
--   * NO V1 TWIN (13-data-lowercase-error) -- reclassified: v1's own
--     parser rejects the source, so there are not two parses to diverge;
--     see 'sexpNoV1Twin'.
--
-- What remains:
--
--   * conc-carrier-transport-rejected: POSITION-ONLY ERROR-SPAN
--     MISMATCH, expected per spec D4 ("the oracle harness compares error
--     identity ... never spans"). Both paths reject with the SAME error
--     constructor (CarrierEscape), but the run golden embeds the full
--     'Show' of the error including its span, and a sexp-path span
--     points into the dump text, never the .wok source. Re-admitting it
--     would require span-stripping the rendered error inside the golden
--     comparison; the rendering has no machine-delimited span syntax to
--     strip cleanly, so the exclusion stays and the file remains covered
--     by its own wok-path run-golden test.
sexpKnownDivergences :: Set.Set FilePath
sexpKnownDivergences = Set.fromList
  [ "conc-carrier-transport-rejected"
  ]

-- | Files the C front end accepts but v1's OWN parser rejects (a
-- lowercase type name; `once` in identifier position, a clause keyword
-- in v1 but an ordinary identifier in v2): there is no v1 tree to
-- differ from, so calling them a "divergence" was dishonest. Each gets
-- a dedicated test pinning exactly this state: the sexp path maps
-- cleanly (it classified into the intersection to get here) while
-- `parse` still rejects the source. If v1 ever learns to parse one,
-- that test FAILS, forcing promotion into the real differential.
sexpNoV1Twin :: Set.Set FilePath
sexpNoV1Twin = Set.fromList
  [ "13-data-lowercase-error"
  , "43-clause-keywords-rejected"
  ]

-- | ParseOnly files whose PARSE golden byte-embeds redundant source
-- parens (03-expressions.wok's `parens = (1)`): the normalized tree
-- assertion (a) runs and must pass, but the golden byte comparison (b)
-- is skipped -- the v2 dump carries no paren nodes at all, so the
-- mapped tree can never byte-reproduce a golden that spells them.
sexpParseGoldenEmbedsParens :: Set.Set FilePath
sexpParseGoldenEmbedsParens = Set.fromList
  [ "03-expressions"
  ]

-- | Pinned per-dir discovery expectation: (intersection count,
-- excluded basenames -- C-parse rejections plus mapper gaps). Asserted
-- EXACTLY by the summary test. Corpus growth, a wokparse grammar
-- change, or a new mapper gap all require updating this pin by hand:
-- that is deliberate -- coverage changes must be visible in review,
-- never a silently shrinking intersection.
sexpExpectedPerDir :: [(FilePath, (Int, [FilePath]))]
sexpExpectedPerDir =
  [ ("test/typecheck-examples", (29,
      ["13-records","14-record-extension","15-record-patterns","16-multi-constructor-records","18-nominal-distinction","19-block-form-records","20-effects-decl","21-effects-arrow","22-effects-pure","23-effects-calls","24-effects-handle","25-effects-di","26-with-handler","28-with-header","43-state-param","44-named-instance","caf-local-inherits-ambient","conc-payload-recursive-ok","conc-surface","coro-pure-tail","coro-residual-handled","coro-residual-multi","par-residual-log","row-param-bare","row-param-box","rung2-nested-fn-ok","user-data-step-not-carrier"]))
  , ("test/examples", (7,
      ["02-decls","04-lambda-let-case-if","05-patterns","06-types-data","07-where","08-infix-lhs","09-layout","11-warts","12-conid-split","14-modules","15-projection","16-reserved","17-reserved-error","19-operator-sigs","20-effects-syntax","26-typeclass","26-with-handler","27-with-header","28-with-named","40-extern-coro-types","41-row-kinded-params"]))
  , ("test/run-examples", (51,
      ["07-effect-ask","16-exn-abort","17-choice-multishot","18-value-op","19-exn-never","25-lint-forgotten-warn","26-lint-discard-wildcard","27-lint-escaping","28-bounded-multishot-arith","29-bounded-multishot-prefix","30-bounded-multishot-let","31-bounded-generator-splice","32-bounded-control-single","33-bounded-nested-multishot","34-bounded-reshape-unpack","35-bounded-header","36-bounded-autoresume","37-known-reentrant-multishot-limitation","40-state-param","41-state-writer-nested","42-writer-state-nested","45-with-in-sugar","46-std-control-mtl","49-named-instance","50-two-cells","51-sum-prod","52-aliasing","53-mixed-row","56-named-multishot","57-named-answers-ambient","58-named-state-reader","59-named-two-state-reader","59-once-arity-both-readings","60-named-state-writer","as-pattern-single","borrow-foreign-lend","borrow-malloc-lend","borrow-read","conc-foreign-sequential-await","conc-nested-own-handles","coro-pure-tail","coro-residual-handled","coro-residual-multi","handler-helper-resume","handler-multiline-body","handler-multiline-nested","local-decl-both-directions","local-fn-sees-value","multiline-handler","multiline-handler-state","par-residual-log","row-param-bare","row-param-box","user-cons-name"]))
  , ("docs/redesign/examples/accept", (5,
      ["01-state-cell","02-two-cells","03-ambient-mtl","04-generator","06-use-bridge","09-activation-independence","10-abort-except"]))
  ]

-- | The four dispatch kinds spec S3 lists, keyed to how each corpus dir's
-- existing golden group renders its output.
data SexpKind
  = SexpTypecheck -- test/typecheck-examples: typecheck success golden
  | SexpParseOnly -- test/examples: parse golden (print/reparse round-trip)
  | SexpRun       -- test/run-examples: run golden (elaborate + interpret)
  | SexpV2Ingest  -- docs/redesign/examples/accept: no golden, no .wok twin parse
  deriving (Eq, Show)

sexpCorpusDirs :: [(FilePath, SexpKind)]
sexpCorpusDirs =
  [ ("test/typecheck-examples", SexpTypecheck)
  , ("test/examples", SexpParseOnly)
  , ("test/run-examples", SexpRun)
  , ("docs/redesign/examples/accept", SexpV2Ingest)
  ]

-- | Per-file discovery outcome (spec S3's discovery rules). A gap
-- exclusion carries the innermost tag AND the stable construct label
-- (the label is what the allowlist is keyed on).
data SexpOutcome
  = SexpIntersection FilePath SexpKind Module
  | SexpExcludedReject FilePath
  | SexpExcludedGap FilePath Text Text
  | SexpMalformed FilePath String

-- | Run `wokparse -sexp F` ONCE (spec S3: never batch) and classify per
-- the discovery rules: nonzero exit -> C-parse rejection; a SexpGap ->
-- gap exclusion; any OTHER reader/mapper error -> a malformed dump the C
-- front end produced, which is a real bug and becomes a FAILING test,
-- never a skip; a clean mapping -> an intersection file.
classifySexpFile :: FilePath -> SexpKind -> FilePath -> IO SexpOutcome
classifySexpFile wokparseBin kind f = do
  (code, out, _err) <- readProcessWithExitCode wokparseBin ["-sexp", f] ""
  case code of
    ExitFailure _ -> pure (SexpExcludedReject f)
    ExitSuccess -> case Sexp.readSExp (T.pack out) of
      Left e -> pure (SexpMalformed f
        ("the reader rejected a dump the C front end emitted: " ++ show e))
      Right datum -> case Surface.surfaceModule datum of
        Left (Surface.SexpGap _ tag label _) -> pure (SexpExcludedGap f tag label)
        Left (Surface.MalformedDump p msg) -> pure (SexpMalformed f
          ("the mapper rejected a dump the C front end emitted, at "
            ++ show p ++ ": " ++ T.unpack msg))
        Right mapped -> pure (SexpIntersection f kind mapped)

-- | Export fixity table per module name, folded in TOPOLOGICAL order
-- (dependencies first, matching what 'Loader.loadProgram' already
-- returns). Mirrors 'Wok.Pipeline.runPipelineFold''s per-module fold, but
-- ONLY the fixity dimension: each module's export table is its own
-- 'DFixity' decls overlaid on the merge of its direct imports' export
-- tables. Built from exported primitives only ('overlayFixities',
-- 'lmFixities', 'lmImports') since 'Wok.Pipeline' does not expose the
-- per-module table it computes internally.
sexpExportFixities :: [Loader.LoadedModule] -> Map.Map Text FixityTable
sexpExportFixities = foldl step Map.empty
  where
    step acc m =
      let importedFixs = [ Map.findWithDefault emptyFixityTable (Loader.isModule s) acc
                          | s <- Loader.lmImports m ]
          importsFix = Data.Either.fromRight emptyFixityTable
                         (Control.Monad.foldM overlayFixities emptyFixityTable importedFixs)
          exportFix  = Data.Either.fromRight importsFix (overlayFixities importsFix (Loader.lmFixities m))
      in Map.insert (Loader.lmName m) exportFix acc

-- | Build the sexp path's entry 'Loader.LoadedModule' directly from the
-- already-mapped v1 'Module' -- no disk write (spec S3: no .sexp
-- intermediate files; the dump text is only ever held in memory).
-- Mirrors 'Wok.Loader.parseAndPrep''s shape (name / fixities / imports)
-- without needing that function exported: the module header, 'DFixity'
-- decls, and 'DImport' decls all come from the SAME mapped tree the
-- reader+mapper already validated. 'synthPath' is a display-only tag
-- (never read from disk), used the way 'Wok.SourceOrigin.UserFile'
-- already tags any user-file-derived module.
sexpEntryLoadedModule :: FilePath -> Module -> Either String Loader.LoadedModule
sexpEntryLoadedModule synthPath mapped@(Module decls) = do
  name <- case decls of
    (DModule mp : _) -> Right (I.modPathText mp)
    _                -> Left "sexp-mapped module has no leading DModule decl"
  fixities <- either (Left . show) Right (buildFixityTable mapped)
  let imports = [ Loader.ImportSpec (I.modPathText mp) imod | DImport mp imod <- decls ]
  Right Loader.LoadedModule
    { Loader.lmName     = name
    , Loader.lmOrigin   = SO.UserFile synthPath
    , Loader.lmAst      = mapped
    , Loader.lmImports  = imports
    , Loader.lmFixities = fixities
    }

-- | Assertion (a) (spec D7/S3): the sexp-mapped module and the v1 parse
-- of the SAME source print identically after reordering with the SAME
-- external (import-derived) fixity table. Mirrors 'sexpSurfaceEndToEnd'
-- above, but DERIVES the external table from the actual module graph
-- (via 'sexpExportFixities') instead of a hand-picked one: the general
-- corpus, unlike the six S1/S2 fixtures, leans on prelude-declared
-- operators (`+`, `*`, ...), not just per-file 'DFixity' decls.
sexpAssertTreeEq :: FilePath -> Module -> Assertion
sexpAssertTreeEq f mapped = do
  wokLoad <- Loader.loadProgram f []
  case wokLoad of
    Left e -> assertFailure ("wok-path loadProgram failed: " ++ show e)
    Right loaded -> sexpAssertTreeEq' f mapped loaded

-- | Primed variant of 'sexpAssertTreeEq': takes an ALREADY-LOADED wok-path
-- module graph instead of calling 'Loader.loadProgram' itself. Used by
-- 'sexpBuildFileTest' to share a single load with 'sexpAssertGolden'' for
-- the same file, instead of each assertion re-reading and re-parsing the
-- six embedded preludes independently.
sexpAssertTreeEq'
  :: FilePath -> Module -> (Loader.ModuleName, [Loader.LoadedModule]) -> Assertion
sexpAssertTreeEq' f mapped (entryName, ms) = do
  srcTxt <- TIO.readFile f
  case parse srcTxt of
    Left e -> assertFailure ("v1 parse of " ++ f ++ " failed: " ++ e)
    Right wokAst ->
      case Data.List.find ((== entryName) . Loader.lmName) ms of
        Nothing -> assertFailure "entry module missing from its own loaded module list"
        Just entryLM -> do
          let exportMap  = sexpExportFixities ms
              importsFix = Data.Either.fromRight emptyFixityTable
                (Control.Monad.foldM overlayFixities emptyFixityTable
                  [ Map.findWithDefault emptyFixityTable (Loader.isModule s) exportMap
                  | s <- Loader.lmImports entryLM ])
          case (reorderModuleWith importsFix wokAst, reorderModuleWith importsFix mapped) of
            (Right wokR, Right sexpR) -> sexpAssertNormalizedEq f wokR sexpR
            (Left e, _) -> assertFailure ("wok-path reorder failed: " ++ show e)
            (_, Left e) -> assertFailure ("sexp-path reorder failed: " ++ show e)

-- | Assertion (a) for 'SexpParseOnly' files: these are standalone SNIPPETS
-- under test/examples (no `module` header, no real imports, and often no
-- `fixity` decls for the operators they use -- their OWN golden group,
-- "parse golden", tests them with bare 'parse'/'printTree', NEVER
-- reordered and never through 'Loader.loadProgram'). Routing them through
-- 'sexpAssertTreeEq''s full Loader+reorder machinery both rejects them
-- with 'LoadNoModuleHeader' (no module header) AND can fail reordering
-- outright on an undeclared operator (e.g. 03-expressions.wok's bare `+`)
-- that plain 'parse' never needed resolved. So this compares the RAW,
-- UNREORDERED trees directly, at the same level their own golden already
-- does.
sexpAssertTreeEqFragment :: FilePath -> Module -> Assertion
sexpAssertTreeEqFragment f mapped = do
  srcTxt <- TIO.readFile f
  case parse srcTxt of
    Left e -> assertFailure ("v1 parse of " ++ f ++ " failed: " ++ e)
    Right wokAst -> sexpAssertNormalizedEq f wokAst mapped

-- | Assertion (b) (spec S3): golden equality against the file's EXISTING
-- golden, using the SAME rendering its corpus already golden-tests with
-- ('renderModuleRoundTrip' / 'renderSchemesBS' / 'renderElaborateAndRun'
-- -- the exact functions 'parseToBS' / 'typecheckSuccessHarness' /
-- 'runProgramHarness' call). For 'SexpTypecheck'/'SexpRun' this runs the
-- SAME 'Loader.LoadedModule' list the wok-path golden test builds, with
-- only the entry module swapped for its sexp-mapped counterpart --
-- preludes are shared (spec R3: preludes stay v1 on both paths).
sexpAssertGolden :: FilePath -> SexpKind -> Module -> Assertion
sexpAssertGolden f SexpParseOnly mapped = do
  expected <- BS.readFile (goldenFor f)
  BL.toStrict (renderModuleRoundTrip mapped) @?= expected
sexpAssertGolden f kind mapped = do
  wokLoad <- Loader.loadProgram f []
  case wokLoad of
    Left e -> assertFailure ("wok-path loadProgram failed: " ++ show e)
    Right loaded -> sexpAssertGolden' f kind mapped loaded

-- | Primed variant of 'sexpAssertGolden' for the non-'SexpParseOnly'
-- kinds: takes an ALREADY-LOADED wok-path module graph instead of calling
-- 'Loader.loadProgram' itself (see 'sexpAssertTreeEq'' for why). Not
-- defined for 'SexpParseOnly' since that clause never loads anything.
sexpAssertGolden'
  :: FilePath -> SexpKind -> Module -> (Loader.ModuleName, [Loader.LoadedModule]) -> Assertion
sexpAssertGolden' f kind mapped (entryName, ms) =
  case sexpEntryLoadedModule (f ++ ".sexp-synth") mapped of
    Left e -> assertFailure ("building the sexp entry LoadedModule failed: " ++ e)
    Right sexpLM -> do
      let sexpMs = [ if Loader.lmName lm == entryName then sexpLM else lm | lm <- ms ]
      case kind of
        SexpTypecheck -> do
          expected <- BS.readFile (typecheckGoldenFor f)
          let actual = case Pipeline.typecheckProgram entryName sexpMs of
                Left s             -> BL.pack ("pipeline: " ++ s ++ "\n")
                Right (decls, _ws) -> renderSchemesBS decls
          BL.toStrict actual @?= expected
        SexpRun -> do
          expected <- BS.readFile (runGoldenFor f)
          let actual = renderElaborateAndRun (Pipeline.elaborateProgramFull entryName sexpMs)
          BL.toStrict actual @?= expected
        _ -> assertFailure "sexpAssertGolden': unreachable kind (ParseOnly handled above, V2Ingest has no golden)"

-- | The six embedded preludes, extracted from any successful
-- 'Loader.loadProgram' call (it always loads all six regardless of what
-- the entry imports -- see 'Wok.Loader.loadProgram''s definition). Used
-- for the v2-accept-corpus files ('SexpV2Ingest'): their .wok twin does
-- not parse under v1 (the Haskell parser rejects 11 of 12, spec's corpus
-- audit), so there is no v1-path 'loadProgram' call to borrow a module
-- graph from for those files -- only the shared prelude ENVIRONMENT
-- (spec R3) is reusable, identified by 'SO.Embedded' origin rather than
-- by name so it does not depend on the throwaway entry's identity.
sexpPreludeModules :: IO (Either Loader.LoaderError [Loader.LoadedModule])
sexpPreludeModules = do
  r <- Loader.loadProgram "test/typecheck-examples/01-identity.wok" []
  pure (fmap (filter ((== SO.Embedded) . Loader.lmOrigin) . snd) r)

-- | The v2-ingest assertion (spec S3): no golden, no .wok twin tree to
-- compare against -- just that ingestion succeeds and typechecking
-- produces SOME result (success or a genuine type error) WITHOUT a
-- Haskell-level crash. Forces the same rendering 'sexpAssertGolden' would
-- diff, inside 'Control.Exception.try', so a partial-function crash deep
-- in the mapper or typechecker is reported as a failure, not silently
-- passed by laziness.
sexpAssertV2Ingest :: FilePath -> Module -> Assertion
sexpAssertV2Ingest f mapped = do
  preludesR <- sexpPreludeModules
  case preludesR of
    Left e -> assertFailure ("loading the shared preludes failed: " ++ show e)
    Right preludeLMs ->
      case sexpEntryLoadedModule (f ++ ".v2-sexp-synth") mapped of
        Left e -> assertFailure ("building the sexp entry LoadedModule failed: " ++ e)
        Right sexpLM -> do
          let rendered = case Pipeline.typecheckProgram (Loader.lmName sexpLM) (preludeLMs ++ [sexpLM]) of
                Left e'            -> BL.pack ("pipeline: " ++ e' ++ "\n")
                Right (decls, _ws) -> renderSchemesBS decls
          forced <- Control.Exception.try
                      (Control.Exception.evaluate (BS.length (BL.toStrict rendered)))
                    :: IO (Either Control.Exception.SomeException Int)
          case forced of
            Left ex -> assertFailure ("v2-ingest: typechecking crashed: " ++ show ex)
            Right _ -> pure ()

sexpBuildFileTest :: FilePath -> SexpKind -> Module -> TestTree
sexpBuildFileTest f SexpV2Ingest mapped =
  testCase (takeBaseName f ++ " (v2-ingest)") (sexpAssertV2Ingest f mapped)
sexpBuildFileTest f SexpParseOnly mapped
  | takeBaseName f `Set.member` sexpNoV1Twin =
      -- Reaching this arm means the sexp mapping SUCCEEDED (the file
      -- classified into the intersection); the pinned claim is that v1
      -- still cannot parse the source, so there is no tree to diff.
      testCase (takeBaseName f ++ " (v2-only: v1 must keep rejecting)") $ do
        srcTxt <- TIO.readFile f
        case parse srcTxt of
          Left _  -> pure ()
          Right _ -> assertFailure
            (f ++ " now parses under v1: remove it from sexpNoV1Twin and \
                  \promote it into the real differential")
  | takeBaseName f `Set.member` sexpParseGoldenEmbedsParens =
      testCase (takeBaseName f ++ " (normalized tree only; parse golden embeds parens)")
        (sexpAssertTreeEqFragment f mapped)
  | otherwise =
      testCase (takeBaseName f) $ do
        sexpAssertTreeEqFragment f mapped
        sexpAssertGolden f SexpParseOnly mapped
sexpBuildFileTest f kind mapped =
  testCase (takeBaseName f) $ do
    wokLoad <- Loader.loadProgram f []
    case wokLoad of
      Left e -> assertFailure ("wok-path loadProgram failed: " ++ show e)
      Right loaded -> do
        sexpAssertTreeEq' f mapped loaded
        sexpAssertGolden' f kind mapped loaded

-- | The whole env-gated group. Unset WOK_WOKPARSE => a single
-- always-passing notice so CI without a C toolchain stays green. Set =>
-- discover + classify each corpus file (one 'wokparse' invocation per
-- file, spec S3: never batch), build one test per intersection file, one
-- FAILING test per malformed dump, and a summary testCase that prints the
-- per-dir counts and hard-asserts every observed gap tag is one the spec
-- documents (spec S3 acceptance: "every exclusion is either a recorded
-- SexpGap or a recorded C-parse rejection -- no silent skips").
buildSexpDifferentialGroup :: Maybe FilePath -> IO TestTree
buildSexpDifferentialGroup Nothing =
  pure $ testGroup "Sexp.Differential"
    [ testCase "skipped (WOK_WOKPARSE unset)" $
        putStrLn
          ( "Sexp.Differential skipped: set WOK_WOKPARSE=/path/to/wokparse to run "
            ++ "the parser-vs-parser differential over the corpus intersection (spec D7/S3)." )
    ]
buildSexpDifferentialGroup (Just wokparseBin) = do
  perDir <- Control.Monad.forM sexpCorpusDirs $ \(dir, kind) -> do
    files    <- findByExtension [".wok"] dir
    outcomes <- Control.Monad.forM (Data.List.sort files) (classifySexpFile wokparseBin kind)
    pure (dir, outcomes)

  let intersectionOf os = [ (f, kind, m) | SexpIntersection f kind m <- os ]
      isKnownDivergence f = takeBaseName f `Set.member` sexpKnownDivergences

      malformedTests =
        [ testCase (takeBaseName f ++ " (malformed dump: a C-front-end/mapper bug, not a skip)")
            (assertFailure msg)
        | (_, os) <- perDir
        , SexpMalformed f msg <- os
        ]

      perFileTests =
        [ sexpBuildFileTest f kind m
        | (_, os) <- perDir
        , (f, kind, m) <- intersectionOf os
        , not (isKnownDivergence f)
        ]

      badGaps =
        [ (f, tag, label)
        | (_, os) <- perDir
        , SexpExcludedGap f tag label <- os
        , label `Set.notMember` sexpDifferentialAllowedGapLabels
        ]

      summary = testCase "corpus intersection summary (pinned)" $ do
        actuals <- Control.Monad.forM perDir $ \(dir, os) -> do
          let inter     = intersectionOf os
              n         = length inter
              rejectSet = Set.fromList [ takeBaseName f | SexpExcludedReject f <- os ]
              gapSet    = Set.fromList [ takeBaseName f | SexpExcludedGap f _ _ <- os ]
              excluded  = rejectSet `Set.union` gapSet
              nDiverged = length [ () | (f, _, _) <- inter, isKnownDivergence f ]
          putStrLn
            ( dir ++ ": intersection=" ++ show n
              ++ " excluded-c-reject=" ++ show (Set.size rejectSet)
              ++ " excluded-gap=" ++ show (Set.size gapSet)
              ++ " excluded-known-divergence=" ++ show nDiverged )
          pure (dir, n, excluded)
        -- Corpus growth (or a wokparse/mapper behavior change) must
        -- update the 'sexpExpectedPerDir' pins by hand -- that is the
        -- point: a silent slide of a file from "differentially tested"
        -- to "excluded" is exactly the coverage regression this
        -- catches, and it is pinned as a SET so a same-count swap
        -- cannot hide either.
        let mismatches =
              [ msg
              | (dir, n, excluded) <- actuals
              , msg <- case lookup dir sexpExpectedPerDir of
                  Nothing -> ["no pinned expectation for corpus dir " ++ dir]
                  Just (expectedN, expectedExcludedL) ->
                    let expectedExcluded = Set.fromList expectedExcludedL
                    in [ unlines
                           [ dir ++ ": corpus discovery drifted from its pin"
                           , "  pinned intersection=" ++ show expectedN ++ ", actual=" ++ show n
                           , "  newly excluded:      " ++ show (Set.toList (excluded Set.\\ expectedExcluded))
                           , "  no longer excluded:  " ++ show (Set.toList (expectedExcluded Set.\\ excluded))
                           , "  full actual excluded set (paste into sexpExpectedPerDir if intended):"
                           , "  " ++ show (Set.toList excluded)
                           ]
                       | expectedN /= n || expectedExcluded /= excluded
                       ]
              ]
        Control.Monad.unless (null mismatches)
          (assertFailure (intercalate "\n" mismatches))
        assertBool
          ("gap label(s) outside the mapper's documented gap rules: " ++ show badGaps)
          (null badGaps)

  pure $ testGroup "Sexp.Differential" (perFileTests ++ malformedTests ++ [summary])

-- ---------------------------------------------------------------------
-- Sexp.Reorder: env-gated differential for the C reorder pass
-- (docs/superpowers/specs/2026-08-07-sexp-reorder-pass.md), over the
-- purpose-built fixtures in test/sexp-reorder-fixtures. Same WOK_WOKPARSE
-- gate and skip-notice convention as 'buildSexpDifferentialGroup'.
--
-- Two pipelines per accept fixture:
--   A: wokparse -sexp -reorder FILE  -> Sexp.Read -> Surface           (no Haskell reordering)
--   B: wokparse -sexp FILE           -> Sexp.Read -> Surface -> Wok.Reordering.reorderModule
-- asserted structurally equal, plus idempotence of 'reorderModule' on A.
--
-- Reject fixtures assert the VERDICT agrees (C rejects <=> reorderModule
-- returns Left), never the message (spec: "chain-level agreement on the
-- message is NOT required, only the verdict").
-- ---------------------------------------------------------------------

sexpReorderFixtureDir :: FilePath
sexpReorderFixtureDir = "test/sexp-reorder-fixtures"

-- | Filenames make the expected verdict visible without opening the file
-- (prompt convention): a "reject-" prefix means `wokparse -sexp -reorder`
-- must fail on it; every other fixture must be accepted.
sexpReorderExpectsReject :: FilePath -> Bool
sexpReorderExpectsReject f = "reject-" `Data.List.isPrefixOf` takeBaseName f

-- | The reorder differential's structural comparator. Verification note:
-- 'sexpNormalize' ALREADY collapses every 'EParen' unconditionally (its
-- 'stripE' clause, defined above) -- which is exactly the treatment this
-- group needs. wok_reorder.c's own header comment records that this AST
-- has no paren node at all ("no wrapper is built; the s-expression dump
-- makes the nesting visible through bracket structure alone"), so the
-- C-reordered dump never contains one, while Haskell's 'combineInfix'
-- (src/Wok/Reordering.hs) wraps a nested chain operand in 'EParen' before
-- re-nesting it. So THIS group needs no extra stripping step beyond what
-- 'sexpNormalize' already does for every other sexp differential group --
-- 'sexpNormalizeReorder' is a documented alias, not a new transform, and
-- 'sexpNormalize' itself (and its existing callers' semantics) is
-- untouched.
sexpNormalizeReorder :: Module -> Module
sexpNormalizeReorder = sexpNormalize

-- | Assert pipeline A (wokparse -sexp -reorder, mapped, no Haskell
-- reordering) and pipeline B (wokparse -sexp flat, mapped, THEN
-- 'Wok.Reordering.reorderModule') agree after 'sexpNormalizeReorder'.
-- Mirrors 'sexpAssertNormalizedEq''s shape and reuses 'sexpShowDiffExcerpt'
-- for the failure-message diff excerpt; the two trees here are A/B
-- (neither is the un-reordered v1 parse 'sexpAssertNormalizedEq' compares
-- against), so the labels are spelled out instead of reusing its wording.
sexpReorderAssertEq :: String -> Module -> Module -> Assertion
sexpReorderAssertEq what treeA treeB = do
  let normA = show (sexpNormalizeReorder treeA)
      normB = show (sexpNormalizeReorder treeB)
  if normA == normB
    then pure ()
    else assertFailure $ unlines
      [ what ++ ": normalized ASTs differ"
      , "  (first label below = pipeline A: wokparse -sexp -reorder;"
        ++ " second = pipeline B: wokparse -sexp + Haskell reorderModule)"
      , sexpShowDiffExcerpt normA normB
      , "printTree (A): " ++ Pr.printTree treeA
      , "printTree (B): " ++ Pr.printTree treeB
      ]

-- | Run `wokparse` with the given extra flags over one file and require a
-- clean exit; on a nonzero exit, fail with the process's stderr+stdout as
-- context. One invocation per call, matching 'classifySexpFile''s
-- "never batch" convention.
sexpReorderRunOk :: FilePath -> [String] -> FilePath -> String -> IO Module
sexpReorderRunOk wokparseBin flags f context = do
  (code, out, err) <- readProcessWithExitCode wokparseBin (flags ++ [f]) ""
  case code of
    ExitFailure _ -> assertFailure (context ++ ": expected a clean exit, got a fault:\n" ++ err ++ out)
    ExitSuccess -> do
      datum <- either (\e -> assertFailure (context ++ ": reader rejected the dump: " ++ show e))
                      pure (Sexp.readSExp (T.pack out))
      either (\e -> assertFailure (context ++ ": surface mapping failed: " ++ show e))
             pure (Surface.surfaceModule datum)

-- | An accept fixture: pipeline A vs pipeline B must agree structurally,
-- and 'reorderModule' on A must be idempotent (a resolved chain already
-- carries only singleton ops seqs).
sexpReorderAcceptTest :: FilePath -> FilePath -> TestTree
sexpReorderAcceptTest wokparseBin f = testCase (takeBaseName f) $ do
  moduleA <- sexpReorderRunOk wokparseBin ["-sexp", "-reorder"] f
               (f ++ " (pipeline A: wokparse -sexp -reorder)")
  flatModule <- sexpReorderRunOk wokparseBin ["-sexp"] f
               (f ++ " (pipeline B base: wokparse -sexp, flat)")
  case reorderModule flatModule of
    Left es -> assertFailure
      (f ++ ": Haskell reorderModule rejected the flat-mapped tree, but the C \
            \reorder pass accepted it (verdict mismatch): " ++ show es)
    Right rmB -> do
      sexpReorderAssertEq f moduleA (reorderedAst rmB)
      case reorderModule moduleA of
        Left es -> assertFailure
          (f ++ ": reorderModule on the already-reordered tree A failed \
                \(idempotence should be a no-op): " ++ show es)
        Right rmA -> sexpReorderAssertEq (f ++ " (idempotence)") moduleA (reorderedAst rmA)

-- | A reject fixture: `wokparse -sexp -reorder` must fault, AND
-- 'reorderModule' on the flat-mapped tree must return 'Left' -- verdict
-- agreement only (spec: message agreement is not required). The flat
-- `wokparse -sexp` (no -reorder) must still parse cleanly, so the fixture
-- is confirmed to be resolve-clean apart from its intended fixity fault,
-- not accidentally exercising some other rejection.
sexpReorderRejectTest :: FilePath -> FilePath -> TestTree
sexpReorderRejectTest wokparseBin f = testCase (takeBaseName f) $ do
  (codeA, outA, _errA) <- readProcessWithExitCode wokparseBin ["-sexp", "-reorder", f] ""
  case codeA of
    ExitSuccess -> assertFailure
      (f ++ ": expected `wokparse -sexp -reorder` to reject this file, but it \
            \produced a dump:\n" ++ outA)
    ExitFailure _ -> do
      flatModule <- sexpReorderRunOk wokparseBin ["-sexp"] f
        (f ++ ": the flat `wokparse -sexp` (no -reorder) must still parse cleanly, \
              \so the rejection under test is the reorder/fixity fault, not some \
              \other parse problem")
      case reorderModule flatModule of
        Right _ -> assertFailure
          (f ++ ": `wokparse -sexp -reorder` rejected this file, but Haskell's \
                \reorderModule accepted the flat-mapped tree (verdict mismatch)")
        Left _  -> pure ()

buildSexpReorderGroup :: Maybe FilePath -> IO TestTree
buildSexpReorderGroup Nothing =
  pure $ testGroup "Sexp.Reorder"
    [ testCase "skipped (WOK_WOKPARSE unset)" $
        putStrLn
          ( "Sexp.Reorder skipped: set WOK_WOKPARSE=/path/to/wokparse to run "
            ++ "the reorder-pass differential over " ++ sexpReorderFixtureDir
            ++ " (docs/superpowers/specs/2026-08-07-sexp-reorder-pass.md)." )
    ]
buildSexpReorderGroup (Just wokparseBin) = do
  files <- findByExtension [".wok"] sexpReorderFixtureDir
  let build f
        | sexpReorderExpectsReject f = sexpReorderRejectTest wokparseBin f
        | otherwise                  = sexpReorderAcceptTest wokparseBin f
  pure $ testGroup "Sexp.Reorder" [ build f | f <- Data.List.sort files ]

-- ---------------------------------------------------------------------
-- Sexp.Reorder.Property: the "QuickCheck generator" bullet of the
-- differential contract (docs/superpowers/specs/2026-08-07-sexp-reorder-pass.md,
-- "The differential contract (Haskell side)"). The 77 scheme goldens and the
-- purpose-built fixtures above use Base operators with no in-file `fixity`,
-- so they only exercise the error path (every chain is "undeclared
-- operator"). This group generates random fixity DAGs x random chains so the
-- ACCEPT path -- tree-shape agreement between the C reorder pass and
-- 'Wok.Reordering.reorderModule' -- gets exercised too. Same WOK_WOKPARSE
-- gate, same skip-notice convention, and reuses every process-invocation and
-- comparison helper the fixture-based group above defines (never
-- re-implements process plumbing).
-- ---------------------------------------------------------------------

-- | Fixed pool of known-good operator spellings. Verified by hand against
-- `wokparse -sexp -reorder` before being wired in here (each symbol lexes as
-- one 'VarSym' token per grammar/Wok.cf's character class, and `dot` is a
-- valid backtick-infix 'VarId'): every entry round-trips through a
-- one-operator chain with its own `fixity` declaration. `$` needed the
-- check most, since `\` is also a 'VarSym' character (lambda's sigil is a
-- separate token) -- confirmed clean.
sexpReorderOpPoolSym :: [String]
sexpReorderOpPoolSym = ["+", "-", "*", "/", "^", "$", "<>", "<+>"]

sexpReorderOpPoolAlpha :: [String]
sexpReorderOpPoolAlpha = ["dot"]

-- | The full pool (9 operators): 2-6 of these get declared per generated
-- case, the rest stay available as neighbour-only / undeclared-operator
-- fault material.
sexpReorderOpPool :: [String]
sexpReorderOpPool = sexpReorderOpPoolSym ++ sexpReorderOpPoolAlpha

-- | Alpha operators print backtick-infix in a chain (`` `dot` ``); symbol
-- operators print bare. Both spellings are bare (no backticks) on the LEFT
-- side of a `fixity` declaration and inside `tighter than`/`looser than`
-- (grammar: 'FixName' is a bare 'VarSym' or bare 'VarId', backtick-quoting
-- is an 'InfixOp'-only surface, confirmed by test/sexp-reorder-fixtures/backtick-declared.wok).
sexpReorderIsAlphaOp :: String -> Bool
sexpReorderIsAlphaOp = (`elem` sexpReorderOpPoolAlpha)

data GenAssoc = GenLeftAssoc | GenRightAssoc
  deriving (Show)

-- | One operator's own `fixity` declaration: its associativity plus zero or
-- more "tighter than" targets. A target is usually another declared
-- operator's name, but occasionally (the neighbour-only fault,
-- test/sexp-reorder-fixtures/reject-neighbour-only.wok's shape) a name with
-- no declaration of its own anywhere in the file.
data GenFixityDecl = GenFixityDecl
  { gfdName    :: String
  , gfdAssoc   :: GenAssoc
  , gfdTighter :: [String]
  } deriving (Show)

-- | Where the generated chain sits: at the top of the single equation, or
-- nested one level under a lambda / case alternative, mirroring
-- nested-chain-lambda.wok / nested-chain-case-arm.wok.
data GenNesting = GenFlat | GenUnderLambda | GenUnderCaseArm
  deriving (Eq, Show)

-- | One generated case: a random fixity table over 2-6 pool operators
-- (random assoc each, a DAG of "tighter than" edges built only from lower
-- to higher index over a shuffled sub-pool so acyclicity is by
-- construction -- the spec's own note that both sides then compute their
-- OWN closure over it) x a random chain of 1-8 operator occurrences (mostly
-- declared, occasionally a name absent from the table entirely). Operand
-- VALUES never matter to this property (only chain SHAPE does), so the
-- printer fills them in deterministically as ascending integer literals --
-- this sidesteps the "unbound variable pollutes the verdict" trap the
-- prompt calls out, without giving up any structural coverage.
data GenReorderCase = GenReorderCase
  { grcDecls    :: [GenFixityDecl]
  , grcChainOps :: [String]
  , grcNesting  :: GenNesting
  } deriving (Show)

instance QC.Arbitrary GenReorderCase where
  arbitrary = do
    k <- choose (2, 6)
    shuffled <- QC.shuffle sexpReorderOpPool
    let selected       = take k shuffled
        undeclaredPool = drop k shuffled  -- always >= 3: pool has 9, k <= 6
    assocs <- QC.vectorOf k (elements [GenLeftAssoc, GenRightAssoc])
    let indexed = zip [0 :: Int ..] selected
        pairs   = [ (i, nj) | (i, _) <- indexed, (j, nj) <- indexed, j > i ]
    -- A tighter-than edge only ever runs from a lower shuffled index to a
    -- higher one, so however many of these fire, the result is acyclic by
    -- construction; 'compareOps' on both sides computes its own reachability
    -- closure over whatever subset survives.
    edgeFlags <- mapM (const (frequency [(2, pure True), (3, pure False)])) pairs
    let edgesByOwner = Map.fromListWith (++)
          [ (i, [nj]) | ((i, nj), True) <- zip pairs edgeFlags ]
    -- Neighbour-only fault (small probability): one declared operator gets
    -- an extra "tighter than X" where X carries no `fixity` of its own.
    neighbourFault <- frequency [(1, pure True), (6, pure False)]
    extraEdge <-
      if neighbourFault && not (null undeclaredPool)
        then do
          ownerIdx <- choose (0, k - 1)
          target   <- elements undeclaredPool
          pure (Just (ownerIdx, target))
        else pure Nothing
    let extraFor i = case extraEdge of
          Just (oi, t) | oi == i -> [t]
          _                      -> []
        decls =
          [ GenFixityDecl name assoc (Map.findWithDefault [] i edgesByOwner ++ extraFor i)
          | (i, name, assoc) <- zip3 [0 :: Int ..] selected assocs
          ]
    -- Chain: 1-8 occurrences, mostly declared operators; a small slice from
    -- the undeclared pool exercises the "undeclared operator in chain"
    -- fault directly (independent of the neighbour-only fault above).
    n <- choose (1, 8)
    chainOps <- QC.vectorOf n
      (frequency
        [ (85, elements selected)
        , (15, elements (if null undeclaredPool then selected else undeclaredPool))
        ])
    nesting <- elements [GenFlat, GenUnderLambda, GenUnderCaseArm]
    pure (GenReorderCase decls chainOps nesting)

  -- Shrinking matters more than volume (spec): drop one declared operator,
  -- drop one chain occurrence (never down to zero -- an empty chain is not
  -- an infix chain at all), drop one "tighter than" edge, or flatten the
  -- nesting -- one independent step at a time, so QuickCheck's shrink loop
  -- converges to a minimal reproducer over repeated rounds.
  shrink (GenReorderCase decls chainOps nesting) =
       [ GenReorderCase ds chainOps nesting | ds <- dropOneOf decls ]
    ++ [ GenReorderCase decls cs nesting | cs <- dropOneOf chainOps, not (null cs) ]
    ++ [ GenReorderCase (dropOneTighterEdge decls) chainOps nesting
       | any (not . null . gfdTighter) decls ]
    ++ [ GenReorderCase decls chainOps GenFlat | nesting /= GenFlat ]
    where
      dropOneOf xs = [ take i xs ++ drop (i + 1) xs | i <- [0 .. length xs - 1] ]
      dropOneTighterEdge ds = case break (not . null . gfdTighter) ds of
        (pre, GenFixityDecl nm a (_ : ts) : post) -> pre ++ GenFixityDecl nm a ts : post
        _                                          -> ds

-- | Emit a self-contained wok SOURCE file for a generated case, matching the
-- accepted surface in test/sexp-reorder-fixtures/: zero or more `fixity`
-- lines (blank-line separated from the definition when there are any --
-- matching reject-undeclared-operator.wok's zero-decl shape when there are
-- none), then a single equation whose body is the chain, flat or nested one
-- level under a lambda / case alternative.
sexpReorderPrintCase :: GenReorderCase -> String
sexpReorderPrintCase (GenReorderCase decls chainOps nesting) = case decls of
  [] -> sexpReorderPrintDef nesting chain
  _  -> unlines (map sexpReorderPrintDecl decls) ++ "\n" ++ sexpReorderPrintDef nesting chain
  where
    chain = sexpReorderPrintChain chainOps

sexpReorderPrintDecl :: GenFixityDecl -> String
sexpReorderPrintDecl (GenFixityDecl name assoc tighter) =
  "fixity " ++ name ++ " " ++ sexpReorderPrintAssoc assoc
    ++ concatMap (\t -> " tighter than " ++ t) tighter

sexpReorderPrintAssoc :: GenAssoc -> String
sexpReorderPrintAssoc GenLeftAssoc  = "left"
sexpReorderPrintAssoc GenRightAssoc = "right"

-- | @n@ operator occurrences need @n + 1@ operands; ascending integer
-- literals (0, 1, 2, ...) are always resolve-clean and their VALUES are
-- irrelevant to a fixity/shape property, so there is no reason to randomize
-- them.
sexpReorderPrintChain :: [String] -> String
sexpReorderPrintChain ops = unwords (interleave operands (map sexpReorderPrintOp ops))
  where
    operands = map show [0 .. length ops]
    interleave (o : os) (p : ps) = o : p : interleave os ps
    interleave (o : _)  []       = [o]
    interleave []       _        = []

sexpReorderPrintOp :: String -> String
sexpReorderPrintOp op
  | sexpReorderIsAlphaOp op = "`" ++ op ++ "`"
  | otherwise               = op

sexpReorderPrintDef :: GenNesting -> String -> String
sexpReorderPrintDef GenFlat        chain = "f = " ++ chain ++ "\n"
sexpReorderPrintDef GenUnderLambda chain = "f = \\x -> " ++ chain ++ "\n"
sexpReorderPrintDef GenUnderCaseArm chain =
  "f = case 0 of\n  0 -> " ++ chain ++ "\n  n -> n\n"

-- | Read a `wokparse -sexp[-reorder]` dump back into a 'Module' via the same
-- Sexp.Read + Surface path every other differential group uses. Returns
-- 'Left' instead of failing the test outright: the property distinguishes a
-- generator bug (this should never happen for syntactically well-formed
-- generated input) from a genuine C/Haskell divergence.
sexpReorderReadDump :: String -> Either String Module
sexpReorderReadDump out =
  case Sexp.readSExp (T.pack out) of
    Left e      -> Left ("reader rejected the dump: " ++ show e)
    Right datum -> case Surface.surfaceModule datum of
      Left e2 -> Left ("surface mapping failed: " ++ show e2)
      Right m -> Right m

-- | One 'wokparse' invocation over generated source text, via a fresh
-- unique temp path (parallel-safe, unconditionally cleaned up) -- the same
-- one-file-per-invocation convention 'sexpReorderRunOk' and
-- 'runSourceWith' use elsewhere in this file (batched wokparse loops are
-- flaky in this sandbox).
sexpReorderRunGenerated
  :: FilePath -> [String] -> String -> IO (ExitCode, String, String)
sexpReorderRunGenerated wokparseBin flags src = do
  u <- newUnique
  let path = "test/.sexp-reorder-prop-tmp-" <> show (hashUnique u) <> ".wok"
  Control.Exception.finally
    (do writeFile path src
        readProcessWithExitCode wokparseBin (flags ++ [path]) "")
    (removeFileIfExists path)

-- | Pure verdict-and-structure judgement given both pipelines' raw process
-- results, for one generated case. All IO stays in 'sexpReorderPropertyCase'
-- (spawning wokparse, writing the temp file); this function is where the
-- property's actual logic lives.
--
--   1. Verdict agreement: pipeline A's exit code vs 'reorderModule' on the
--      flat-mapped tree (Left <=> reject). A mismatch fails with both
--      verdicts and the generated source in the counterexample.
--   2. When both accept: pipeline A's mapped tree, normalized, must equal
--      pipeline B's ('reorderModule' on the flat tree), normalized. Plus
--      idempotence: 'reorderModule' on pipeline A's already-reordered tree
--      must be a no-op.
sexpReorderJudge
  :: String                      -- ^ generated source, for the counterexample report
  -> (ExitCode, String, String)  -- ^ pipeline A: wokparse -sexp -reorder
  -> (ExitCode, String, String)  -- ^ pipeline B base: wokparse -sexp (flat)
  -> Property
sexpReorderJudge src (codeA, outA, errA) (codeFlat, outFlat, errFlat) =
  QC.classify cAccepts     "C accepts" $
  QC.classify (not cAccepts) "C rejects" $
  case flatResult of
    Left msg          -> counterexample (report ("GENERATOR BUG: " ++ msg)) False
    Right flatModule ->
      let hVerdict  = reorderModule flatModule
          hAccepts  = either (const False) (const True) hVerdict
          verdictOk = counterexample
            (report
              ( "verdict mismatch: C " ++ verdictWord cAccepts
                ++ ", Haskell " ++ verdictWord hAccepts
                ++ either ((" -- " ++) . show) (const "") hVerdict ))
            (cAccepts == hAccepts)
      in verdictOk .&&.
         (if cAccepts && hAccepts
            then sexpReorderJudgeAccepted src outA hVerdict
            else property True)
  where
    cAccepts = codeA == ExitSuccess
    flatResult
      | codeFlat /= ExitSuccess = Left ("flat `wokparse -sexp` rejected the file: " ++ errFlat)
      | otherwise               = sexpReorderReadDump outFlat
    verdictWord accepted = if accepted then "accepts" else "rejects"
    report note = unlines
      [ "generated source:"
      , src
      , "pipeline A (-reorder) stderr: " ++ errA
      , note
      ]

-- | The accept-side checks: pipeline A/B structural agreement, then
-- idempotence of 'reorderModule' on pipeline A's already-reordered tree.
sexpReorderJudgeAccepted
  :: String -> String -> Either [ReorderError] ReorderedModule -> Property
sexpReorderJudgeAccepted src outA hVerdict = case (sexpReorderReadDump outA, hVerdict) of
  (Left msg, _) ->
    counterexample ("GENERATOR BUG: pipeline A dump failed to map: " ++ msg ++ "\n" ++ src) False
  (_, Left _) ->
    counterexample "unreachable: hVerdict was Left under cAccepts && hAccepts" False
  (Right moduleA, Right rmB) ->
    let normA = show (sexpNormalizeReorder moduleA)
        normB = show (sexpNormalizeReorder (reorderedAst rmB))
        eqAB  = counterexample
          ("pipeline A/B normalized trees differ:\n" ++ sexpShowDiffExcerpt normA normB ++ "\n" ++ src)
          (normA == normB)
        idem = case reorderModule moduleA of
          Left es -> counterexample
            ("idempotence failed: reorderModule on pipeline A's tree returned Left: "
              ++ show es ++ "\n" ++ src) False
          Right rmA ->
            let normIdem = show (sexpNormalizeReorder (reorderedAst rmA))
            in counterexample
                 ("idempotence mismatch:\n" ++ sexpShowDiffExcerpt normA normIdem ++ "\n" ++ src)
                 (normA == normIdem)
    in eqAB .&&. idem

-- | One generated case, end to end: print, run both pipelines once each,
-- judge.
sexpReorderPropertyCase :: FilePath -> GenReorderCase -> Property
sexpReorderPropertyCase wokparseBin gc = QC.ioProperty $ do
  let src = sexpReorderPrintCase gc
  resA    <- sexpReorderRunGenerated wokparseBin ["-sexp", "-reorder"] src
  resFlat <- sexpReorderRunGenerated wokparseBin ["-sexp"] src
  pure (sexpReorderJudge src resA resFlat)

-- | Registration: same WOK_WOKPARSE gate and skip-notice convention as
-- 'buildSexpReorderGroup'. 150 cases by default (spec: "Case count: 150 by
-- default... each case spawns wokparse twice; keep runtime sane").
buildSexpReorderPropertyGroup :: Maybe FilePath -> IO TestTree
buildSexpReorderPropertyGroup Nothing =
  pure $ testGroup "Sexp.Reorder.Property"
    [ testCase "skipped (WOK_WOKPARSE unset)" $
        putStrLn
          ( "Sexp.Reorder.Property skipped: set WOK_WOKPARSE=/path/to/wokparse to run "
            ++ "the reorder-pass QuickCheck differential "
            ++ "(docs/superpowers/specs/2026-08-07-sexp-reorder-pass.md)." )
    ]
buildSexpReorderPropertyGroup (Just wokparseBin) =
  pure $ localOption (QuickCheckTests 150) $
    testGroup "Sexp.Reorder.Property"
      [ testProperty "random fixity DAGs x random chains: C/Haskell verdict + tree agreement"
          (sexpReorderPropertyCase wokparseBin)
      ]

sourceOriginTests :: TestTree
sourceOriginTests = testGroup "Wok.SourceOrigin"
  [ testCase "originPath Embedded is the placeholder tag" $
      SO.originPath SO.Embedded @?= "<Base>"
  , testCase "originPath UserFile returns the path verbatim" $
      SO.originPath (SO.UserFile "foo/bar.wok") @?= "foo/bar.wok"
  ]

preludeTests :: TestTree
preludeTests = testGroup "Prelude"
  [ testCase "preludeName is Base" $
      Prelude.preludeName @?= T.pack "Base"
  , testCase "preludeSource is non-empty" $ do
      src <- Prelude.preludeSource
      assertBool "expected non-empty preludeSource" (T.length src > 0)
  , testCase "preludeSource contains a module header" $ do
      src <- Prelude.preludeSource
      assertBool "expected `module Base` in source"
                 (T.isInfixOf (T.pack "module Base") src)
  ]

modPathTests :: TestTree
modPathTests = testGroup "modPath"
  [ testCase "modPathText on bare ConId" $
      let mp = Abs.MPName (Abs.ConId ((1, 1), T.pack "Foo"))
      in I.modPathText mp @?= T.pack "Foo"

  , testCase "modPathText on single dot" $
      let mp = Abs.MPDot (Abs.MPName (Abs.ConId ((1, 1), T.pack "A")))
                         (Abs.ConId ((1, 5), T.pack "B"))
      in I.modPathText mp @?= T.pack "A.B"

  , testCase "modPathText on double dot" $
      let mp = Abs.MPDot
                 (Abs.MPDot (Abs.MPName (Abs.ConId ((1, 1), T.pack "A")))
                            (Abs.ConId ((1, 3), T.pack "B")))
                 (Abs.ConId ((1, 5), T.pack "C"))
      in I.modPathText mp @?= T.pack "A.B.C"

  , testCase "modPathPos returns leftmost ConId position" $
      let mp = Abs.MPDot (Abs.MPName (Abs.ConId ((42, 7), T.pack "Std")))
                         (Abs.ConId ((42, 11), T.pack "Base"))
      in I.modPathPos mp @?= (42, 7)
  ]

-- ---------------------------------------------------------------------
-- Parser-level tests for the qualified-imports-minimal surface syntax.
-- Phase A: verify the Alex/Happy output parses the three new import forms
-- (plain, list, alias) and REJECTS the as+list combination at the grammar
-- level (Q1: structural impossibility). The ImportMod field is ignored by
-- the loader at this phase; these tests pin the AST shape so later phases
-- can rely on it.
-- ---------------------------------------------------------------------

-- | Extract the first DImport's (ModPath, ImportMod) from a decl list.
importDeclOf :: [Decl] -> Maybe (ModPath, ImportMod)
importDeclOf [] = Nothing
importDeclOf (DImport mp im : _) = Just (mp, im)
importDeclOf (_ : rest) = importDeclOf rest

-- | Position-insensitive summary of an ImportMod, for equality testing.
-- * IMPlain        -> "plain"
-- * IMList [..]    -> "list:" ++ intercalate "," names
-- * IMAs (ConId a) -> "as:"   ++ a
importModSummary :: ImportMod -> T.Text
importModSummary Abs.IMPlain                 = T.pack "plain"
importModSummary (Abs.IMList names)          =
  T.pack "list:" <> T.intercalate (T.pack ",") (map importNameText names)
importModSummary (Abs.IMAs (Abs.ConId (_, a))) = T.pack "as:" <> a

importNameText :: ImportName -> T.Text
importNameText (Abs.INVar (Abs.VarId (_, n))) = n

-- | Parse, pretty-print via Print.hs, re-parse, and assert the two
-- printed forms agree. Mirrors the parseToBS round-trip discipline.
roundTripParses :: T.Text -> Assertion
roundTripParses src =
  case parse src of
    Left err -> assertFailure ("initial parse failed: " ++ err)
    Right ast1 ->
      let printed1 = Pr.printTree ast1
      in case parse (T.pack printed1) of
           Left err -> assertFailure
             ("round-trip parse failed: " ++ err ++ "\n---printed---\n" ++ printed1)
           Right ast2
             | Pr.printTree ast2 == printed1 -> pure ()
             | otherwise -> assertFailure
                 ("round-trip mismatch\n---first---\n" ++ printed1
                  ++ "\n---second---\n" ++ Pr.printTree ast2)

importParseTests :: TestTree
importParseTests = testGroup "import-parse"
  [ testCase "import M parses to DImport with IMPlain" $
      let src = T.pack "module Main\nimport Base\n"
      in case parse src of
           Left err -> assertFailure ("parse failed: " ++ err)
           Right (Module decls) -> case importDeclOf decls of
             Just (mp, im) -> do
               I.modPathText mp @?= T.pack "Base"
               importModSummary im @?= T.pack "plain"
             Nothing -> assertFailure "no DImport decl found"

  , testCase "import M (x, y) parses to IMList [x, y]" $
      let src = T.pack "module Main\nimport Base (map, filter)\n"
      in case parse src of
           Left err -> assertFailure ("parse failed: " ++ err)
           Right (Module decls) -> case importDeclOf decls of
             Just (mp, im) -> do
               I.modPathText mp @?= T.pack "Base"
               importModSummary im @?= T.pack "list:map,filter"
             Nothing -> assertFailure "no DImport decl found"

  , testCase "import M () parses to IMList [] (empty list)" $
      let src = T.pack "module Main\nimport Base ()\n"
      in case parse src of
           Left err -> assertFailure ("parse failed: " ++ err)
           Right (Module decls) -> case importDeclOf decls of
             Just (mp, im) -> do
               I.modPathText mp @?= T.pack "Base"
               importModSummary im @?= T.pack "list:"
             Nothing -> assertFailure "no DImport decl found"

  , testCase "import M as A parses to IMAs A" $
      let src = T.pack "module Main\nimport Base as Base\n"
      in case parse src of
           Left err -> assertFailure ("parse failed: " ++ err)
           Right (Module decls) -> case importDeclOf decls of
             Just (mp, im) -> do
               I.modPathText mp @?= T.pack "Base"
               importModSummary im @?= T.pack "as:Base"
             Nothing -> assertFailure "no DImport decl found"

  , testCase "import M as A (x, y) is a PARSE ERROR (structural impossibility, Q1)" $ do
      -- The grammar's ImportMod is a single sum nonterminal: the parser cannot
      -- attach both a list and an alias. This must fail at parse time, not
      -- typecheck time.
      let src = T.pack "module Main\nimport Base as Base (map, filter)\n"
      case parse src of
        Left _  -> pure ()  -- expected: parse fails
        Right _ -> assertFailure
          "expected parse failure for `import M as A (x, y)` (Q1: structural impossibility)"

  , testCase "import round-trips through Print.hs (plain)" $
      roundTripParses (T.pack "module Main\nimport Base\n")

  , testCase "import round-trips through Print.hs (list)" $
      roundTripParses (T.pack "module Main\nimport Base (map, filter)\n")

  , testCase "import round-trips through Print.hs (alias)" $
      roundTripParses (T.pack "module Main\nimport Base as Base\n")

  , testCase "import round-trips through Print.hs (empty list)" $
      roundTripParses (T.pack "module Main\nimport Base ()\n")
  ]

-- ---------------------------------------------------------------------
-- Phase B: typechecker tests for qualified-value access, alias-only,
-- and explicit-list filter semantics. These exercise the envQualifiers
-- field, the pipeline's buildQualifierMap, and the Infer.hs qualifier-
-- first arm. Each test constructs a qualifier-bearing env directly (no
-- full pipeline) to isolate the typecheck behavior.
-- ---------------------------------------------------------------------

-- | Build an env with one registered qualifier exposing the given vars.
-- The env is seeded from B.initialEnv (so U64, Bool, etc. are in scope).
qualEnv :: T.Text -> T.Text -> [(T.Text, Ty.Scheme)] -> TE.Env
qualEnv qual src vars =
  B.initialEnv { TE.envQualifiers = Map.singleton qual (src, Map.fromList vars) }

-- | Parse a module source and typecheck it against the given env.
-- Returns the raw inferProgramWith result.
inferWith :: TE.Env -> T.Text -> Either TErr.TypeError (TE.Env, [I.TypedDecl], [TC.Warning])
inferWith env src =
  case parse src of
    Left err -> error ("parse failed in test: " ++ err)
    Right m  -> TC.inferProgramWith env (SO.UserFile "<test>") m

u64Scheme :: Ty.Scheme
u64Scheme = Ty.mkScheme [] (Ty.CTCon Ty.TcU64 [])

u64ToU64Scheme :: Ty.Scheme
u64ToU64Scheme = Ty.mkScheme []
  (Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty (Ty.CTCon Ty.TcU64 []))

qualifiedAccessTests :: TestTree
qualifiedAccessTests = testGroup "qualified-access"
  [ testCase "Foo.bar resolves when Foo is a registered qualifier" $
      let env = qualEnv (T.pack "Foo") (T.pack "Foo")
                  [ (T.pack "bar", u64Scheme) ]
          src = T.pack "module Main\nf : U64\nf = Foo.bar\n"
      in case inferWith env src of
           Right _  -> pure ()
           Left err -> assertFailure ("expected typecheck OK, got: " ++ show err)

  , testCase "Foo.add 1 resolves as a saturated qualified call" $
      let env = qualEnv (T.pack "Foo") (T.pack "Foo")
                  [ (T.pack "inc", u64ToU64Scheme) ]
          src = T.pack "module Main\nf : U64\nf = Foo.inc 1\n"
      in case inferWith env src of
           Right _  -> pure ()
           Left err -> assertFailure ("expected typecheck OK, got: " ++ show err)

  , testCase "Foo.bar fails when bar is not in Foo's vars" $
      let env = qualEnv (T.pack "Foo") (T.pack "Foo") []
          src = T.pack "module Main\nf : U64\nf = Foo.bar\n"
      in case inferWith env src of
           Left _  -> pure ()
           Right _ -> assertFailure "expected UnknownVar for Foo.bar (not in Foo)"

  , testCase "Foo.bar falls through when Foo is not a registered qualifier" $
      let env = B.initialEnv  -- no qualifiers
          src = T.pack "module Main\nf : U64\nf = Foo.bar\n"
      in case inferWith env src of
           Left _  -> pure ()
           Right _ -> assertFailure "expected failure (Foo not a qualifier/effect/foreign)"

  , testCase "alias-only: bare bar is NOT in scope when only F alias registered" $
      let env = qualEnv (T.pack "F") (T.pack "Foo")
                  [ (T.pack "bar", u64Scheme) ]
          src = T.pack "module Main\nf : U64\nf = bar\n"
      in case inferWith env src of
           Left _  -> pure ()
           Right _ -> assertFailure "expected UnknownVar for bare bar (alias-only)"

  , testCase "F.bar resolves under alias" $
      let env = qualEnv (T.pack "F") (T.pack "Foo")
                  [ (T.pack "bar", u64Scheme) ]
          src = T.pack "module Main\nf : U64\nf = F.bar\n"
      in case inferWith env src of
           Right _  -> pure ()
           Left err -> assertFailure ("expected typecheck OK for F.bar, got: " ++ show err)

  , testCase "Foo.bar fails when only F alias is registered (original name not a qualifier)" $
      let env = qualEnv (T.pack "F") (T.pack "Foo")
                  [ (T.pack "bar", u64Scheme) ]
          src = T.pack "module Main\nf : U64\nf = Foo.bar\n"
      in case inferWith env src of
           Left _  -> pure ()
           Right _ -> assertFailure "expected failure for Foo.bar (only F registered, not Foo)"

  , testCase "qualifier wins over a same-named foreign module in application position" $
      -- Name `M` registered as BOTH a qualifier (var `mem : U64 -> U64`) and a
      -- foreign module (member `mem : U64 -> U64 -> U64`, arity 2). Applying
      -- `M.mem 1` must resolve via the qualifier (one arg, U64 result). If the
      -- EApp arm consulted the foreign table first it would see arity 2 with one
      -- arg and reject with ForeignMemberPartialApp -- the pre-fix behavior.
      let memInfo = TE.ForeignMemberInfo
                      (Ty.mkScheme []
                        (Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty
                          (Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty
                            (Ty.CTCon Ty.TcU64 []))))
                      (T.pack "mem") False []
          fmi = TE.ForeignModuleInfo (T.pack "c") Nothing
                  (Map.fromList [(T.pack "mem", memInfo)])
          env = (qualEnv (T.pack "M") (T.pack "M") [ (T.pack "mem", u64ToU64Scheme) ])
                  { TE.envForeignModules = Map.singleton (T.pack "M") fmi }
          src = T.pack "module Main\nf : U64\nf = M.mem 1\n"
      in case inferWith env src of
           Right _  -> pure ()
           Left err -> assertFailure ("expected qualifier to win, got: " ++ show err)
  ]

-- ---------------------------------------------------------------------
-- End-to-end pipeline tests for qualified imports. Unlike
-- 'qualifiedAccessTests' (which builds envQualifiers directly), these run
-- the REAL Loader -> pipeline path so they exercise 'buildQualifierMap'
-- (single-seg plain / alias registration) and 'filterImportEnv' (the
-- unqualified-scope filter and alias name removal), plus the import-list
-- validation. A shared provider module `Prov` (13-qi-prov.wok) exports two
-- vars; each entry fixture is a distinct import scenario.
-- ---------------------------------------------------------------------

-- | Load an entry fixture (with Prov as the extra module), typecheck it via
-- the real pipeline, and hand the Either String result to the assertion.
withQiPipeline :: FilePath -> (Either String ([TC.TypedDecl], [TC.Warning]) -> Assertion) -> Assertion
withQiPipeline entry k = do
  res <- Loader.loadProgram entry ["test/loader-fixtures/13-qi-prov.wok"]
  case res of
    Left lerr -> assertFailure ("unexpected loader error: " ++ show lerr)
    Right (entryName, ms) -> k (Pipeline.typecheckProgram entryName ms)

qualifiedImportPipelineTests :: TestTree
qualifiedImportPipelineTests = testGroup "qualified-import-pipeline"
  [ testCase "import M (x): listed var is bare, unlisted reachable via qualifier" $
      withQiPipeline "test/loader-fixtures/13-qi-list-ok.wok" $ \r -> case r of
        Right _ -> pure ()
        Left s  -> assertFailure ("expected pipeline success, got: " ++ s)

  , testCase "import M (x): unlisted var is NOT in the unqualified scope" $
      withQiPipeline "test/loader-fixtures/13-qi-list-bare-fail.wok" $ \r -> case r of
        Left _  -> pure ()
        Right _ -> assertFailure "expected failure: bare `triple` is not in the import list"

  , testCase "import M as A: qualified A.x resolves" $
      withQiPipeline "test/loader-fixtures/13-qi-alias-ok.wok" $ \r -> case r of
        Right _ -> pure ()
        Left s  -> assertFailure ("expected pipeline success, got: " ++ s)

  , testCase "import M as A: bare names are NOT in scope" $
      withQiPipeline "test/loader-fixtures/13-qi-alias-bare-fail.wok" $ \r -> case r of
        Left _  -> pure ()
        Right _ -> assertFailure "expected failure: alias import puts no bare names in scope"

  , testCase "import M (plain single-seg): registers M as a qualifier" $
      withQiPipeline "test/loader-fixtures/13-qi-plain-qualifier.wok" $ \r -> case r of
        Right _ -> pure ()
        Left s  -> assertFailure ("expected pipeline success, got: " ++ s)

  , testCase "import M (typo): unknown import-list entry is a pipeline error" $
      withQiPipeline "test/loader-fixtures/13-qi-list-unknown.wok" $ \r -> case r of
        Left s
          | "import list" `Data.List.isInfixOf` s
            && "nosuchvar" `Data.List.isInfixOf` s -> pure ()
          | otherwise -> assertFailure ("wrong error for unknown import-list entry: " ++ s)
        Right _ -> assertFailure "expected failure: `nosuchvar` is not exported by Prov"
  ]

monadSmokeTests :: TestTree
monadSmokeTests = testGroup "Wok.TypeChecking.Monad"
  [ testCase "freshUniq returns increasing values" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.freshUniq
            b <- TM.freshUniq
            c <- TM.freshUniq
            pure (a, b, c)
      in case result of
           Right t -> t @?= (0, 1, 2)
           Left e  -> assertFailure (show e)
  , testCase "enterLevel bumps then restores" $
      let result = TM.runTC_ TE.emptyEnv $ do
            l0 <- TM.currentLevel
            l1 <- TM.enterLevel TM.currentLevel
            l2 <- TM.currentLevel
            pure (l0, l1, l2)
      in case result of
           Right t -> t @?= (Ty.Level 0, Ty.Level 1, Ty.Level 0)
           Left e  -> assertFailure (show e)
  , testCase "freshTVar runs without error" $
      let result = TM.runTC_ TE.emptyEnv $ do
            _ <- TM.enterLevel (TM.freshTVar Ty.KStar)
            pure ()
      in case result of
           Right () -> pure ()
           Left e -> assertFailure (show e)
  , testCase "throwError caught as Left" $
      let result :: Either TErr.TypeError ()
          result = TM.runTC_ TE.emptyEnv $
            throwError (TErr.UnknownVar Nothing (T.pack "x"))
      in case result of
           Left (TErr.UnknownVar _ _) -> pure ()
           _ -> assertFailure "expected UnknownVar"
  ]

unifyWalksTests :: TestTree
unifyWalksTests = testGroup "Wok.TypeChecking.Unify (walks)"
  [ testCase "freeze TCon Int" $
      let result = TM.runTC_ TE.emptyEnv $
            U.freeze (Ty.TCon Ty.TcU64 [])
      in case result of
           Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
           Left e   -> assertFailure ("expected Right, got: " ++ show e)
  , testCase "freeze fresh TVar produces CTGen" $
      let result = TM.runTC_ TE.emptyEnv $ do
            t <- TM.freshTVar Ty.KStar
            U.freeze t
      in case result of
           Right (Ty.CTGen _) -> pure ()
           _ -> assertFailure ("expected CTGen, got " ++ show result)
  , testCase "occursAdjust fires when target appears" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.freshTVar Ty.KStar
            case a of
              Ty.TVar ref -> U.occursAdjust Nothing ref (Ty.Level 0)
                              (Ty.TCon Ty.TcList [a])
              _ -> error "expected TVar"
      in case result of
           Left (TErr.OccursCheck _ _ _) -> pure ()
           _ -> assertFailure ("expected OccursCheck, got "
                              ++ either show (const "Right ()") result)
  ]

unifyTests :: TestTree
unifyTests = testGroup "Wok.TypeChecking.Unify (unify)"
  [ testCase "identical TCon unifies" $
      let result = TM.runTC_ TE.emptyEnv $
            U.unify Nothing (Ty.TCon Ty.TcU64 []) (Ty.TCon Ty.TcU64 [])
      in case result of
           Right () -> pure ()
           Left e -> assertFailure (show e)
  , testCase "mismatched TCons fail" $
      let result = TM.runTC_ TE.emptyEnv $
            U.unify Nothing (Ty.TCon Ty.TcU64 []) (Ty.TCon Ty.TcBool [])
      in case result of
           Left (TErr.Mismatch _ _ _) -> pure ()
           _ -> assertFailure
                  ("expected Mismatch, got "
                  ++ either show (const "Right ()") result)
  , testCase "fresh TVar unifies with concrete type" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.freshTVar Ty.KStar
            U.unify Nothing a (Ty.TCon Ty.TcU64 [])
            U.freeze a
      in case result of
           Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
           Left e -> assertFailure (show e)
  , testCase "TArr unifies (with empty effect row)" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.freshTVar Ty.KStar
            U.unify Nothing
              (Ty.TArr a Ty.RowEmpty (Ty.TCon Ty.TcBool []))
              (Ty.TArr (Ty.TCon Ty.TcU64 []) Ty.RowEmpty (Ty.TCon Ty.TcBool []))
            U.freeze a
      in case result of
           Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
           Left e -> assertFailure (show e)
  , testCase "occurs check fires (a ~ List a)" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.freshTVar Ty.KStar
            U.unify Nothing a (Ty.TCon Ty.TcList [a])
      in case result of
           Left (TErr.OccursCheck _ _ _) -> pure ()
           _ -> assertFailure
                  ("expected OccursCheck, got "
                  ++ either show (const "Right ()") result)
  ]

tableOf :: Text -> (FixityTable -> Assertion) -> Assertion
tableOf src k =
  case buildFixityTable (parseSrc src) of
    Right t  -> k t
    Left err -> assertFailure $ "expected Right, got: " ++ show err

builtinsTests :: TestTree
builtinsTests = testGroup "Wok.TypeChecking.Builtins + Base"
  -- Builtins.initialEnv is the irreducible pre-env: only the tycons that
  -- can't be spelled in surface Wok (U64, (), [], (,)...(,..,)). Everything
  -- else (Bool, Option, +, ++, ...) lives in Base; these tests load the
  -- prelude via stdBaseExtendedEnv to verify the user-visible contract.
  [ testCase "U64, (), [], tuple tycons in irreducible Builtins" $ do
      case TE.lookupTyCon (T.pack "U64") B.initialEnv of
        Just info -> TE.tcKind info @?= Ty.KStar
        Nothing -> assertFailure "U64 missing"
      case TE.lookupTyCon (T.pack "()") B.initialEnv of
        Just info -> TE.tcArity info @?= 0
        Nothing -> assertFailure "() missing"
      case TE.lookupTyCon (T.pack "[]") B.initialEnv of
        Just info -> TE.tcArity info @?= 1
        Nothing -> assertFailure "list missing"
  , testCase "Builtins has NO Bool/True/False/+/++ (Base owns them)" $ do
      TE.lookupTyCon (T.pack "Bool") B.initialEnv @?= Nothing
      TE.lookupCon   (T.pack "True") B.initialEnv @?= Nothing
      TE.lookupVar   (T.pack "+")    B.initialEnv @?= Nothing
      TE.lookupVar   (T.pack "++")   B.initialEnv @?= Nothing
  , testCase "Base: Bool tycon with True/False cons" $ do
      env <- stdBaseExtendedEnv
      case TE.lookupTyCon (T.pack "Bool") env of
        Just info -> do
          TE.tcArity info @?= 0
          TE.tcCons info @?= [T.pack "True", T.pack "False"]
        Nothing -> assertFailure "Bool missing"
  , testCase "Base: True/False are constructors of Bool" $ do
      env <- stdBaseExtendedEnv
      case TE.lookupCon (T.pack "True") env of
        Just info -> TE.conTyCon info @?= T.pack "Bool"
        Nothing -> assertFailure "True missing"
  , testCase "Base: + has scheme U64 -> U64 -> U64" $ do
      env <- stdBaseExtendedEnv
      case TE.lookupVar (T.pack "+") env of
        Just (Ty.Scheme [] _ body) -> case body of
          Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty
            (Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty (Ty.CTCon Ty.TcU64 [])) ->
              pure ()
          _ -> assertFailure ("unexpected body: " ++ show body)
        _ -> assertFailure "+ missing or has quantifiers"
  , testCase "Base: ++ has one type quantifier" $ do
      env <- stdBaseExtendedEnv
      case TE.lookupVar (T.pack "++") env of
        Just (Ty.Scheme [(_, Ty.KStar)] _ _) -> pure ()
        _ -> assertFailure "++ has wrong quantifier count"
  , testCase "tuple constructors up to arity 16" $ do
      case TE.lookupTyCon (T.pack "(,)") B.initialEnv of
        Just info -> TE.tcArity info @?= 2
        Nothing -> assertFailure "2-tuple missing"
      case TE.lookupTyCon (T.pack "(,,,,,,,,,,,,,,,)") B.initialEnv of
        Just info -> TE.tcArity info @?= 16
        Nothing -> assertFailure "16-tuple missing"
  ]

translateTests :: TestTree
translateTests = testGroup "Wok.TypeChecking.Infer (translateSig)"
  [ testCase "U64 -> U64 translates to monotype" $
      let int = Abs.TCon (Abs.MPName (Abs.ConId ((0,0), T.pack "U64")))
          ty  = Abs.TFun int int
          result = TM.runTC_ B.initialEnv (I.translateSig B.initialEnv ty)
      in case result of
           Right s -> s @?= Ty.mkScheme []
                            (Ty.CTArr (Ty.CTCon Ty.TcU64 []) Ty.CREmpty
                                      (Ty.CTCon Ty.TcU64 []))
           Left e -> assertFailure (show e)
  , testCase "a -> a translates to forall a. a -> a" $
      let var = Abs.TVar (Abs.VarId ((0,0), T.pack "a"))
          ty  = Abs.TFun var var
          result = TM.runTC_ B.initialEnv (I.translateSig B.initialEnv ty)
      in case result of
           Right (Ty.Scheme [(0, Ty.KStar)] _
                    (Ty.CTArr (Ty.CTGen 0) Ty.CREmpty (Ty.CTGen 0))) ->
             pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  , testCase "[a] translates to forall a. [a]" $
      let var = Abs.TVar (Abs.VarId ((0,0), T.pack "a"))
          result = TM.runTC_ B.initialEnv (I.translateSig B.initialEnv (Abs.TList var))
      in case result of
           Right (Ty.Scheme [(0, Ty.KStar)] _ (Ty.CTCon Ty.TcList [Ty.CTGen 0])) ->
             pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  , testCase "unknown tycon errors" $
      let unk = Abs.TCon (Abs.MPName (Abs.ConId ((0,0), T.pack "Frob")))
          result = TM.runTC_ B.initialEnv (I.translateSig B.initialEnv unk)
      in case result of
           Left (TErr.UnknownTyCon _ _) -> pure ()
           _ -> assertFailure ("expected UnknownTyCon, got "
                              ++ either show (const "Right") result)
  ]

generalizeTests :: TestTree
generalizeTests = testGroup "Wok.TypeChecking.Infer (generalize/instantiate)"
  [ testCase "generalize Int yields no quantifiers" $
      let result = TM.runTC_ TE.emptyEnv $
            I.generalize (Ty.TCon Ty.TcU64 [])
      in case result of
           Right s -> s @?= Ty.mkScheme [] (Ty.CTCon Ty.TcU64 [])
           Left e -> assertFailure (show e)
  , testCase "generalize fresh a -> a yields forall a. a -> a" $
      let result = TM.runTC_ TE.emptyEnv $ do
            a <- TM.enterLevel (TM.freshTVar Ty.KStar)
            I.generalize (Ty.TArr a Ty.RowEmpty a)
      in case result of
           Right (Ty.Scheme [(i, Ty.KStar)] _
                    (Ty.CTArr (Ty.CTGen j) Ty.CREmpty (Ty.CTGen k)))
             | i == j && j == k -> pure ()
           other -> assertFailure ("unexpected scheme: " ++ show other)
  , testCase "instantiate forall a. a -> a yields shared TVar" $
      let s = Ty.mkScheme [(0, Ty.KStar)]
                (Ty.CTArr (Ty.CTGen 0) Ty.CREmpty (Ty.CTGen 0))
          result = TM.runTC_ TE.emptyEnv $ do
            t <- I.instantiate s
            case t of
              Ty.TArr (Ty.TVar r1) Ty.RowEmpty (Ty.TVar r2) ->
                pure (r1 == r2)
              _ -> pure False
      in case result of
           Right True -> pure ()
           Right False -> assertFailure "expected shared TVar refs but they differed"
           Left e -> assertFailure (show e)
  ]

zonkTests :: TestTree
zonkTests = testGroup "Zonk"
  [ testCase "polymorphic body node shares the scheme's CTGen domain" $
      -- Mirror real use: the binding's RHS var lives one level deeper than
      -- the level at which we generalize, so 'a' is generalizable.
      let r = TM.runTC_ B.initialEnv $ do
                a <- TM.enterLevel (TM.freshTVar Ty.KStar)          -- the 'a' of id
                let fnTy = Ty.TArr a Ty.RowEmpty a
                    tree = Typed.Texp a (Typed.TVar (T.pack "x"))   -- body: x : a
                (sch, tree', _cs) <- I.generalizeTyped fnTy tree []
                let Typed.Texp ann _ = tree'
                pure (Ty.schemeBody sch, ann)
      in case r of
           Right (Ty.CTArr d _ _, ann) -> ann @?= d   -- node type == domain
           other -> assertFailure (show other)
  , testCase "monomorphic node freezes to concrete CType" $
      let r = TM.runTC_ B.initialEnv $ do
                let tree = Typed.Texp (Ty.TCon Ty.TcU64 []) (Typed.TLitI 1)
                (_, Typed.Texp ann _, _cs) <- I.generalizeTyped (Ty.TCon Ty.TcU64 []) tree []
                pure ann
      in case r of
           Right ann -> ann @?= Ty.CTCon Ty.TcU64 []
           Left e    -> assertFailure (show e)
  ]

-- | Assert that inferExprW builds typed nodes with the right constructor
-- shape. We inspect the TexpF structure (annotations carry mutable Type s and
-- are awkward to compare, so we match on node shape and concrete literals).
-- ---------------------------------------------------------------------------
-- Resume-binder-type property tests (spec 2026-06-19).
--
-- The resume binder of every handler op arm must be typed as the continuation
-- arrow `T -> R` (always boxed), NOT the answer type `R`. Typing it `R`
-- mis-marks an unboxed-answer continuation as unboxed, so the Perceus pass omits
-- its drop on a discard arm and the captured owned set leaks. These run in
-- memory (parse -> reorder -> inferProgramWith B.initialEnv) over builtins-only
-- handler programs and inspect the typed 'TOpArm' resume-type field. The
-- Core-level 'genProgram' generates no handlers, so it cannot cover this; this
-- is the type-layer net.

-- | A representative type with its source text, a sample literal, its CType, and
-- whether it is boxed (reference-counted). Spans unboxed scalars and boxed lists.
data RTy = RTy
  { rtyText  :: String
  , rtyLit   :: String
  , rtyCType :: Ty.CType
  , rtyBoxed :: Bool
  }
  deriving (Show)

reprTys :: [RTy]
reprTys =
  [ RTy "U64"     "0"     (Ty.CTCon Ty.TcU64 [])                                      False
  , RTy "()"      "()"    (Ty.CTCon Ty.TcUnit [])                                     False
  , RTy "String"  "\"s\"" (Ty.CTCon Ty.TcString [])                                   False
  , RTy "[U64]"   "[0]"   (Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []])                 True
  , RTy "[[U64]]" "[[0]]" (Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]]) True
  ]

data ArmShape = DiscardNamed | DiscardWild | ApplyNamed | AutoResume
  deriving (Show, Eq, Enum, Bounded)

-- | A self-contained, well-typed handler module using only builtin types. The op
-- result type @tRes@ (= T) and the handler answer type @rAns@ (= R) vary
-- independently, as does the arm shape and whether the handler is AMBIENT
-- (@with { E.op ... } e@, elaborated via 'inferHandler') or NAMED
-- (@with self = E { ... } in@, via 'inferNamedHandler') -- both inference paths
-- thread the resume type. No 'Base' import, so 'B.initialEnv' suffices for
-- the in-memory typecheck.
renderHandlerSrc :: Bool -> RTy -> RTy -> ArmShape -> String
renderHandlerSrc ambient tRes rAns shape
  | ambient = unlines
      [ "module Main"
      , "effect E = { fire : U64 -> " ++ rtyText tRes ++ " }"
      , "prog : () -> " ++ rtyText rAns ++ " with E"
      , "prog u = let x = E.fire 0 in " ++ rtyLit rAns
      , "run : (() -> " ++ rtyText rAns ++ " with E + eff e) -> " ++ rtyText rAns ++ " with eff e"
      , "run c = with { " ++ arm "E." ++ " ; return v -> v } c ()"
      , "main : " ++ rtyText rAns
      , "main = run prog"
      ]
  | otherwise = unlines
      [ "module Main"
      , "effect E = { fire : U64 -> " ++ rtyText tRes ++ " }"
      , "prog : E -> " ++ rtyText rAns ++ " with E"
      , "prog e = let u = e.fire 0 in " ++ rtyLit rAns
      , "run : (E -> " ++ rtyText rAns ++ " with E + eff e) -> " ++ rtyText rAns ++ " with eff e"
      , "run c = with self = E { " ++ arm "" ++ " ; return v -> v } in c self"
      , "main : " ++ rtyText rAns
      , "main = run prog"
      ]
  where
    -- The clause kind is DECLARED, so the keyword precedes the head and any
    -- qualifier: `once E.fire n k -> ...`. The three continuation-binding
    -- shapes bind arity + 1 patterns and so must say `once`; AutoResume binds
    -- exactly the arity and stays plain.
    arm qual = case shape of
      DiscardNamed -> "once " ++ qual ++ "fire n k -> " ++ rtyLit rAns
      DiscardWild  -> "once " ++ qual ++ "fire n _ -> " ++ rtyLit rAns
      ApplyNamed   -> "once " ++ qual ++ "fire n k -> k (" ++ rtyLit tRes ++ ")"
      AutoResume   -> qual ++ "fire n -> " ++ rtyLit tRes

genHandlerSrc :: Gen (String, Bool, RTy, RTy, ArmShape)
genHandlerSrc = do
  ambient <- elements [False, True]
  tRes    <- elements reprTys
  rAns    <- elements reprTys
  shape   <- elements [minBound .. maxBound]
  pure (renderHandlerSrc ambient tRes rAns shape, ambient, tRes, rAns, shape)

-- | Parse + reorder + infer a self-contained module under the builtins env;
-- returns the output env (for in-memory elaboration in P3) and the typed decls.
typeCheckSrc :: String -> Either String (TE.Env, [TC.TypedDecl])
typeCheckSrc src =
  case parse (T.pack src) of
    Left e    -> Left ("parse: " ++ e)
    Right ast -> case reorderModule ast of
      Left es  -> Left ("reorder: " ++ show es)
      Right rm -> case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
        Left e             -> Left ("infer: " ++ show e)
        Right (env, ds, _) -> Right (env, ds)

-- | Every 'TOpArm' resume-type annotation reachable in the inferred decls.
resumeTysOf :: [TC.TypedDecl] -> [Ty.CType]
resumeTysOf = concatMap (concatMap (goE . snd) . TC.tdClauses)
  where
    goE (Typed.Texp _ f) = goF f
    goF f = case f of
      Typed.TApp h as            -> goE h ++ concatMap goE as
      Typed.TLam _ e             -> goE e
      Typed.TIf a b c            -> goE a ++ goE b ++ goE c
      Typed.TTuple es            -> concatMap goE es
      Typed.TList es             -> concatMap goE es
      Typed.TProj e _            -> goE e
      Typed.TPerformOn e _ _     -> goE e
      Typed.TRecord _ fs         -> concatMap (goE . snd) fs
      Typed.TRecordExt _ e fs    -> goE e ++ concatMap (goE . snd) fs
      Typed.TLet ds e            -> concatMap goLD ds ++ goE e
      Typed.TCase e alts         -> goE e ++ concatMap goAlt alts
      Typed.THandle e arms       -> goE e ++ concatMap goArm arms
      Typed.TWithNamedH _ arms e -> concatMap goArm arms ++ goE e
      _                          -> []
    goArm (Typed.TOpArm _ _ _ _ rty b) = rty : goE b
    goArm (Typed.TReturnArm _ b)       = goE b
    goArm (Typed.TParamArm _ e)        = goE e
    goAlt (Typed.TAlt _ ds e)          = concatMap goLD ds ++ goE e
    goLD (Typed.TLocalDecl _ _ e)      = goE e

-- | The resume binder type of every elaborated 'Anf.OpArm' in a Core module
-- (the Elaborate-layer counterpart of 'resumeTysOf', for the P3 agreement check).
coreResumeTysOf :: Anf.CoreModule -> [Ty.CType]
coreResumeTysOf cm = concatMap (goE . Anf.tbBody) (Anf.cmBinds cm)
  where
    goE e = case e of
      Anf.Let _ rhs b      -> goR rhs ++ goE b
      Anf.LetRec ds b      -> concatMap (\(_, _, db) -> goE db) ds ++ goE b
      Anf.LetJoin _ _ jb b -> goE jb ++ goE b
      Anf.Case _ alts      -> concatMap goAlt alts
      Anf.Handle e' h      -> goE e' ++ concatMap goOp (Anf.hOps h)
      _                    -> []
    goR rhs = case rhs of
      Anf.RLam _ b -> goE b
      _            -> []
    goOp oa = Anf.bndType (Anf.oaResume oa) : goE (Anf.oaBody oa)
    goAlt (Anf.AltCon _ _ b) = goE b
    goAlt (Anf.AltLit _ b)   = goE b
    goAlt (Anf.AltDefault b) = goE b

-- | The (domain, codomain) of a single arrow, ignoring its effect row; 'Nothing'
-- for a non-arrow. Used to check @resume : T -> R@ on BOTH the domain T and the
-- codomain R (a wrong-but-boxed @R -> R@ must NOT pass).
arrowParts :: Ty.CType -> Maybe (Ty.CType, Ty.CType)
arrowParts (Ty.CTArr a _ b) = Just (a, b)
arrowParts _                = Nothing

resumeBinderTypeTests :: TestTree
resumeBinderTypeTests = testGroup "resumeBinderType"
  [ testProperty "P1: every resume binder is a boxed arrow (T -> R)" $
      QC.forAll genHandlerSrc $ \(src, ambient, _tRes, rAns, shape) ->
        checkCoverage $
        cover 20 (rtyBoxed rAns)       "boxed answer"   $
        cover 20 (not (rtyBoxed rAns)) "unboxed answer" $
        cover 10 (shape == DiscardNamed || shape == DiscardWild) "discard arm" $
        cover 10 (shape == ApplyNamed  || shape == AutoResume)   "resuming arm" $
        cover 20 ambient        "ambient handler" $
        cover 20 (not ambient)  "named handler"   $
          case typeCheckSrc src of
            Left e        -> counterexample ("typecheck failed (generator bug):\n" ++ src ++ "\n" ++ e) False
            Right (_, ds) ->
              let rtys = resumeTysOf ds
              in counterexample ("resume types: " ++ show rtys ++ "\nsrc:\n" ++ src)
                   (not (null rtys) && all isArrowBoxed rtys)
  , testProperty "P2: resume binder is the continuation type T -> R (domain AND codomain)" $
      QC.forAll genHandlerSrc $ \(src, _ambient, tRes, rAns, _shape) ->
        case typeCheckSrc src of
          Left _        -> property True   -- typecheck failures are P1's job to report
          Right (_, ds) -> conjoin
            [ counterexample
                ("resume " ++ show rty ++ " /= " ++ rtyText tRes ++ " -> " ++ rtyText rAns ++ "\n" ++ src)
                (arrowParts rty == Just (rtyCType tRes, rtyCType rAns))
            | rty <- resumeTysOf ds ]
  , testProperty "P3: elaborated resume binder agrees with the inferred type (boxed T -> R)" $
      QC.forAll genHandlerSrc $ \(src, _ambient, tRes, rAns, _shape) ->
        case typeCheckSrc src of
          Left _          -> property True
          Right (env, ds) ->
            let core = coreResumeTysOf (elaborateModule (T.pack "Main") Set.empty env ds)
            in counterexample ("elaborated resume types: " ++ show core ++ "\n" ++ src)
                 (not (null core)
                  && all (\t -> Esc.isBoxedType t && arrowParts t == Just (rtyCType tRes, rtyCType rAns)) core)
  , testProperty "P4: any arrow type is boxed" $
      QC.forAll genArrow Esc.isBoxedType
  ]
  where
    isArrowBoxed t@(Ty.CTArr _ _ _) = Esc.isBoxedType t
    isArrowBoxed _                  = False
    genArrow :: Gen Ty.CType
    genArrow = do
      a <- elements [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcUnit [], Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]]
      b <- elements [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcString []]
      pure (Ty.CTArr a Ty.CREmpty b)

inferTypedTests :: TestTree
inferTypedTests = testGroup "InferTyped"
  [ testCase "literal 1 yields Texp _ (TLitI 1)" $
      let r = TM.runTC_ B.initialEnv $ do
                (_, Typed.Texp _ node) <-
                  I.inferExprW Map.empty (Abs.ELitI (Abs.WokInt ((0,0), T.pack "1")))
                pure $ case node of
                  Typed.TLitI 1 -> True
                  _             -> False
      in case r of
           Right True -> pure ()
           other      -> assertFailure ("unexpected node: " ++ show other)
  , testCase "unit yields Texp _ TUnit" $
      let r = TM.runTC_ B.initialEnv $ do
                (_, Typed.Texp _ node) <- I.inferExprW Map.empty Abs.EUnit
                pure $ case node of
                  Typed.TUnit -> True
                  _           -> False
      in case r of
           Right True -> pure ()
           other      -> assertFailure ("unexpected node: " ++ show other)
  , testCase "f x yields Texp _ (TApp (Texp _ (TVar f)) [Texp _ (TVar x)])" $
      let r = TM.runTC_ B.initialEnv $ do
                xa <- TM.freshTVar Ty.KStar
                -- f : x -> r so the application is well typed.
                rv <- TM.freshTVar Ty.KStar
                let mono = Map.fromList
                      [ (T.pack "f", Ty.TArr xa Ty.RowEmpty rv)
                      , (T.pack "x", xa) ]
                    app = Abs.EApp
                            (Abs.EVar (Abs.VarId ((0,0), T.pack "f")))
                            (Abs.EVar (Abs.VarId ((0,0), T.pack "x")))
                (_, Typed.Texp _ node) <- I.inferExprW mono app
                pure $ case node of
                  Typed.TApp (Typed.Texp _ (Typed.TVar fn))
                             [Typed.Texp _ (Typed.TVar xn)] ->
                    fn == T.pack "f" && xn == T.pack "x"
                  _ -> False
      in case r of
           Right True -> pure ()
           other      -> assertFailure ("unexpected node: " ++ show other)
  , testCase "lambda yields Texp _ (TLam [TPVar x] (TVar x))" $
      let lam = Abs.ELam [Abs.APVar (Abs.VarId ((0,0), T.pack "x"))]
                  (Abs.EVar (Abs.VarId ((0,0), T.pack "x")))
          r = TM.runTC_ B.initialEnv $ do
                (_, Typed.Texp _ node) <- I.inferExprW Map.empty lam
                pure $ case node of
                  Typed.TLam [Typed.Tpat _ (Typed.TPVar p)]
                             (Typed.Texp _ (Typed.TVar b)) ->
                    p == T.pack "x" && b == T.pack "x"
                  _ -> False
      in case r of
           Right True -> pure ()
           other      -> assertFailure ("unexpected node: " ++ show other)
  ]

typedDeclBodyTests :: TestTree
typedDeclBodyTests = testGroup "TypedDeclBody"
  [ testCase "id x = x: scheme forall a. a -> a, body+params share CTGen" $
      case parse (T.pack "id x = x\n") of
        Left err -> assertFailure ("parse: " ++ err)
        Right ast -> case reorderModule ast of
          Left es -> assertFailure ("reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
              Left e -> assertFailure ("typecheck: " ++ show e)
              Right (_env, decls, _ws) ->
                case [ d | d <- decls, TC.tdName d == T.pack "id" ] of
                  [] -> assertFailure "no TypedDecl for id"
                  (d : _) ->
                    case TC.tdScheme d of
                      Ty.Scheme [_] _ (Ty.CTArr (Ty.CTGen i) _ (Ty.CTGen j))
                        | i == j ->
                          case TC.tdClauses d of
                            [([Typed.Tpat (Ty.CTGen pIdx) (Typed.TPVar nm)],
                              Typed.Texp bodyAnn _)] -> do
                                 -- one clause, one quantifier, arrow a -> a
                                 -- body's root annotation is the domain CTGen i
                                 bodyAnn @?= Ty.CTGen i
                                 pIdx @?= i
                                 nm @?= T.pack "x"
                            other ->
                                 assertFailure ("unexpected tdClauses: " ++ show other)
                      other ->
                        assertFailure ("unexpected scheme: " ++ show other)
  , testCase "f x = let g y = y in x: node-only poly var does not leak into scheme" $
      -- 'g' is a let-bound polymorphic helper whose type does not escape into
      -- f's type. f's scheme must be exactly forall a. a -> a (one quantifier).
      -- Under the old code, freezing g's body node 'y : b' recorded a spurious
      -- second quantifier, yielding forall a b. a -> a.
      case parse (T.pack "f x = let g y = y in x\n") of
        Left err -> assertFailure ("parse: " ++ err)
        Right ast -> case reorderModule ast of
          Left es -> assertFailure ("reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
              Left e -> assertFailure ("typecheck: " ++ show e)
              Right (_env, decls, _ws) ->
                case [ d | d <- decls, TC.tdName d == T.pack "f" ] of
                  [] -> assertFailure "no TypedDecl for f"
                  (d : _) ->
                    case TC.tdScheme d of
                      sch@(Ty.Scheme _ _ (Ty.CTArr (Ty.CTGen i) _ (Ty.CTGen j)))
                        | i == j -> do
                          -- exactly one quantifier; the node-only 'b' did not leak
                          length (Ty.schemeVars sch) @?= 1
                      other ->
                        assertFailure ("unexpected scheme: " ++ show other)
  ]

-- | Equations for the same name that disagree on argument count are rejected
-- with 'ClauseArityMismatch'. The arity check runs before inference, so it
-- works on a self-contained module using only builtin types.
clauseArityTests :: TestTree
clauseArityTests = testGroup "ClauseArity"
  [ testCase "equations disagreeing on arity are rejected" $
      assertModuleFailsWith isClauseArity $ T.unlines
        [ T.pack "f : U64 -> U64 -> U64"
        , T.pack "f 0 = 0"
        , T.pack "f x y = y" ]
  , testCase "equations agreeing on arity are accepted" $
      assertModuleTypechecks $ T.unlines
        [ T.pack "f : U64 -> U64 -> U64"
        , T.pack "f 0 y = y"
        , T.pack "f x y = y" ]
  ]
  where
    isClauseArity e = case e of
      TErr.ClauseArityMismatch{} -> True
      _                          -> False

-- | Head-pattern shapes the match compiler cannot lower (record-constructor
-- patterns and non-empty list literals in a routed-through-match head) are
-- rejected at typecheck time with a clean 'UnsupportedHeadPattern', BEFORE any
-- coverage warning fires. Single-clause record heads take the cheap projection
-- path and must still type-check.
unsupportedHeadTests :: TestTree
unsupportedHeadTests = testGroup "UnsupportedHead"
  [ testCase "multi-clause record-constructor head is a clean type error" $ do
      let src = T.unlines
            [ T.pack "data Box = Box { v : U64 }"
            , T.pack "f : Box -> U64"
            , T.pack "f (Box { v = 0 }) = 0"
            , T.pack "f (Box { v = x }) = x" ]
      assertNoRedundantBeforeUnsupported src

  , testCase "non-empty list literal head is a clean type error" $ do
      let src = T.unlines
            [ T.pack "g : [U64] -> U64"
            , T.pack "g [1, 2] = 1"
            , T.pack "g _      = 0" ]
      assertNoRedundantBeforeUnsupported src

  , testCase "single-clause record head still type-checks (cheap path preserved)" $ do
      let src = T.unlines
            [ T.pack "data Box = Box { v : U64 }"
            , T.pack "getV : Box -> U64"
            , T.pack "getV (Box { v = x }) = x" ]
      assertModuleTypechecks src
  ]
  where
    -- Run with UserFile origin (the origin that WOULD emit coverage warnings)
    -- and assert the result is the clean UnsupportedHeadPattern error -- the
    -- error short-circuits inference, so no RedundantClause/NonExhaustiveMatch
    -- warning can ever precede it.
    assertNoRedundantBeforeUnsupported src =
      case parse src of
        Left err  -> assertFailure ("parse: " ++ err)
        Right ast -> case reorderModule ast of
          Left es -> assertFailure ("reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv (SO.UserFile "<test>")
                   (reorderedAst rm) of
              Left TErr.UnsupportedHeadPattern{} -> pure ()
              Left e  -> assertFailure ("expected UnsupportedHeadPattern, got: " ++ show e)
              Right _ -> assertFailure "expected UnsupportedHeadPattern, got success"

-- | A multi-clause function keeps EVERY clause on its 'TypedDecl' (the
-- finalizer no longer drops all-but-first). A single-clause binding round-trips
-- as a one-element clause list.
typedDeclClauseTests :: TestTree
typedDeclClauseTests = testGroup "typedDeclClause"
  [ testCase "two-clause function carries two clauses" $
      withDeclsFor (T.unlines
        [ T.pack "data Nat = Z | S Nat"
        , T.pack "f : Nat -> U64"
        , T.pack "f Z = 0"
        , T.pack "f (S n) = 1" ]) (T.pack "f") $ \d ->
          length (TC.tdClauses d) @?= 2
  , testCase "single-clause binding round-trips as one clause" $
      withDeclsFor (T.pack "id x = x\n") (T.pack "id") $ \d ->
          length (TC.tdClauses d) @?= 1
  , testCase "zero-arg value round-trips as one empty-param clause" $
      withDeclsFor (T.pack "answer = 42\n") (T.pack "answer") $ \d ->
          case TC.tdClauses d of
            [([], _)] -> pure ()
            other     -> assertFailure ("unexpected clauses: " ++ show other)
  ]
  where
    withDeclsFor src nm k =
      case parse src of
        Left err -> assertFailure ("parse: " ++ err)
        Right ast -> case reorderModule ast of
          Left es -> assertFailure ("reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
              Left e -> assertFailure ("typecheck: " ++ show e)
              Right (_env, decls, _ws) ->
                case [ d | d <- decls, TC.tdName d == nm ] of
                  []      -> assertFailure ("no TypedDecl for " ++ T.unpack nm)
                  (d : _) -> k d

-- | Parse, reorder, and typecheck a whole module; assert it succeeds.
assertModuleTypechecks :: Text -> Assertion
assertModuleTypechecks src =
  case parse src of
    Left err -> assertFailure ("parse: " ++ err)
    Right ast -> case reorderModule ast of
      Left es -> assertFailure ("reorder: " ++ show es)
      Right rm -> case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
        Left e        -> assertFailure ("typecheck: " ++ show e)
        Right _       -> pure ()

-- | Parse, reorder, and typecheck a module; assert it fails with an error
-- matching the predicate.
assertModuleFailsWith :: (TErr.TypeError -> Bool) -> Text -> Assertion
assertModuleFailsWith p src =
  case parse src of
    Left err -> assertFailure ("parse: " ++ err)
    Right ast -> case reorderModule ast of
      Left es -> assertFailure ("reorder: " ++ show es)
      Right rm -> case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
        Left e | p e       -> pure ()
               | otherwise -> assertFailure ("wrong error: " ++ show e)
        Right _            -> assertFailure "expected a type error, got success"

effectDeclTests :: TestTree
effectDeclTests = testGroup "Wok.TypeChecking.EffectDecl"
  [ testCase "inline effect decl typechecks" $
      assertModuleTypechecks $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = { read : String -> String, write : String -> () }"
        ]

  , testCase "block-form effect decl typechecks" $
      assertModuleTypechecks $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = {"
        , T.pack "  read : String -> String"
        , T.pack "  write : String -> ()"
        , T.pack "}"
        ]

  , testCase "parameterized effect decl (State a) typechecks" $
      assertModuleTypechecks $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect State a = {"
        , T.pack "  get : () -> a"
        , T.pack "  set : a -> ()"
        , T.pack "}"
        ]

  , testCase "duplicate operation name is rejected" $
      assertModuleFailsWith isDuplicateOperation $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = { read : String -> String, read : String -> () }"
        ]

  , -- #7: the `..`-polarity rule applies to OPERATION types too, not just
    -- top-level signatures -- an anonymous tail in a parameter position is
    -- rejected here as well, so `..` cannot escape the check via an op type.
    testCase "anonymous .. in an operation parameter is rejected" $
      assertModuleFailsWith isAnonRowTailInParam $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = { write : String -> () }"
        , T.pack "effect Weird = { run : (() -> () with IO + ..) -> () }"
        ]

  , -- #7 (data-field path): the same chokepoint (translateConArg) also covers
    -- record-field types, so an anonymous `..` in a field's function-parameter
    -- position is rejected too -- `..` cannot escape via a data declaration.
    testCase "anonymous .. in a data-field parameter is rejected" $
      assertModuleFailsWith isAnonRowTailInParam $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = { write : String -> () }"
        , T.pack "data Box = Box { f : (() -> () with IO + ..) -> () }"
        ]
  ]
  where
    isDuplicateOperation TErr.DuplicateOperation{} = True
    isDuplicateOperation _                         = False
    isAnonRowTailInParam TErr.AnonRowTailInParam{} = True
    isAnonRowTailInParam _                         = False

-- | Typecheck a module and return the inferred scheme of a top-level name,
-- rendered via prettyScheme. Exercises with-clause translation + printing.
schemeOf :: [Text] -> Text -> Either String Text
schemeOf declLines name =
  let src = T.unlines (T.pack "module Main" : declLines)
  in case parse src of
       Left err -> Left ("parse: " ++ err)
       Right ast -> case reorderModule ast of
         Left es -> Left ("reorder: " ++ show es)
         Right rm -> case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
           Left e -> Left ("typecheck: " ++ show e)
           Right (env, _, _) -> case TE.lookupVar name env of
             Just sch -> Right (TC.prettyScheme sch)
             Nothing  -> Left ("not registered: " ++ T.unpack name)

effectSigTests :: TestTree
effectSigTests = testGroup "Wok.TypeChecking.EffectSig"
  [ testCase "closed single effect: with IO" $
      schemeOf
        [ T.pack "effect IO = { read : String -> String, write : String -> () }"
        , T.pack "greet : String -> () with IO"
        ]
        (T.pack "greet")
        @?= Right (T.pack "String -> () with IO")

  , testCase "multiple effects: with IO + Logger" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "effect Logger = { log : String -> () }"
        , T.pack "multi : () -> () with IO + Logger"
        ]
        (T.pack "multi")
        @?= Right (T.pack "() -> () with IO + Logger")

  , testCase "named tail shared across positions: with IO + eff e" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "runIO : (() -> a with IO + eff e) -> a with eff e"
        ]
        (T.pack "runIO")
        @?= Right (T.pack "forall b a. (() -> b with IO + eff a) -> b with eff a")

  , testCase "anonymous tail: with IO + .." $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "logIt : () -> () with IO + .."
        ]
        (T.pack "logIt")
        @?= Right (T.pack "forall a. () -> () with IO + eff a")

  , testCase "parameterized effect atom (State U64)" $
      schemeOf
        [ T.pack "effect State a = { get : () -> a, set : a -> () }"
        , T.pack "stateful : () -> U64 with State U64"
        ]
        (T.pack "stateful")
        @?= Right (T.pack "() -> U64 with State")

  , testCase "undeclared effect in with-clause is rejected" $
      case schemeOf [T.pack "bad : () -> () with FooBar"] (T.pack "bad") of
        Left msg -> assertBool ("expected MissingEffectDecl, got: " ++ msg)
                      ("MissingEffectDecl" `isInfixOfStr` msg)
        Right s  -> assertFailure ("expected error, got: " ++ T.unpack s)

  , testCase "eff and row vars of the same name do not collapse" $
      case schemeOf
             [ T.pack "data Point = Point { x : U64, y : U64 }"
             , T.pack "effect IO = { write : String -> () }"
             , T.pack "mix : Point + row r -> () with IO + eff r"
             ]
             (T.pack "mix") of
        Left msg -> assertFailure ("expected success, got: " ++ msg)
        Right _  -> pure ()
  ]
  where
    isInfixOfStr needle hay = T.pack needle `T.isInfixOf` T.pack hay

-- Named effect instances (Task 3): an effect name in TYPE position is an
-- instance-handle type; the dot accessor is type-directed (handle -> named
-- perform off the instance, NOT the ambient row; record -> field; unresolved ->
-- ambiguous-accessor error); and the two named `with` forms infer. These run
-- through `schemeOf` (inference only) since lowering is Task 4.
namedInstanceTests :: TestTree
namedInstanceTests = testGroup "Wok.TypeChecking.NamedInstance"
  [ testGroup "effect-as-type + type-directed perform"
      [ -- A handle-typed parameter: `count.set`/`count.get` are NAMED performs
        -- off the instance, so they do NOT add `State` to the ambient row.
        testCase "named perform off a handle param stays off the row" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "prog : State U64 -> State U64 -> ()"
            , T.pack "prog count total = let b = count.set count.get in total.set total.get"
            ]
            (T.pack "prog")
            @?= Right (T.pack "State U64 -> State U64 -> ()")

      , -- The op's result type ties to the handle's OWN type argument (the U64
        -- in `State U64`): `b.get : U64` feeds `a.set : U64 -> ()`, so both
        -- handles tie to U64 independently.
        testCase "two same-typed handles tie independently to U64" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "sumProd : State U64 -> State U64 -> ()"
            , T.pack "sumProd a b = a.set b.get"
            ]
            (T.pack "sumProd")
            @?= Right (T.pack "State U64 -> State U64 -> ()")

      , -- A handle-typed parameter coexists with an ambient effect row: the
        -- named perform stays off the row, leaving only `IO` on the arrow.
        testCase "handle param coexists with an ambient IO row" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "effect IO = { write : String -> () }"
            , T.pack "logged : State U64 -> () with IO"
            , T.pack "logged s = let b = s.set s.get in IO.write \"bumped\""
            ]
            (T.pack "logged")
            @?= Right (T.pack "State U64 -> () with IO")

      , -- Record projection still dispatches by type (regression guard for the
        -- type-directed dot). The nominal row is printed by prettyScheme.
        testCase "record field projection still works (regression)" $
          schemeOf
            [ T.pack "data Point = Point { x : U64, y : U64 }"
            , T.pack "getX : Point -> U64"
            , T.pack "getX p = p.x"
            ]
            (T.pack "getX")
            @?= Right (T.pack "Point { x,y, } -> U64")
      ]

  , testGroup "ambiguous accessor (unannotated receiver)"
      [ testCase "unannotated `c.get` is an ambiguous-accessor error" $
          case schemeOf
                 [ T.pack "effect State s = { get : s, set : s -> () }"
                 , T.pack "bump c = c.get"
                 ]
                 (T.pack "bump") of
            Left msg -> assertBool ("expected AmbiguousAccessor, got: " ++ msg)
                          (T.pack "AmbiguousAccessor" `T.isInfixOf` T.pack msg)
            Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)
      ]

  , testGroup "named with-forms"
      [ -- EWithNamedH: a named primitive handler. `s.get`/`s.set` in the body
        -- are named performs routed to `s`; the body's other ambient effects
        -- (none here) flow out. The whole `with` yields the body's value type.
        testCase "named primitive handler binds self and infers the body" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "runLocal : U64 -> U64"
            , T.pack "runLocal i = with s = State { get -> i ; once set x k -> k () ; return v -> v } in s.get"
            ]
            (T.pack "runLocal")
            @?= Right (T.pack "U64 -> U64")

      , -- GUARDRAIL for the deliberate no-`&` design: capability binders are
        -- plain names (`with x = ...`). There is no `&` sigil token, so a
        -- `with &x = ...` header must fail to parse. Locks the surface syntax
        -- decision (see effect-surface-syntax-final / at-token-reserved memos).
        testCase "a sigil-prefixed capability binder (with &x) fails to parse" $
          case parse (T.pack "module Main\nmain = with &x = state 0 in x") of
            Left _  -> pure ()
            Right _ -> assertFailure "expected a parse error for `with &x`, got a successful parse"
      ]
  ]

-- | The carrier rule (named effect instances, §4.3): a second-class escape check
-- run after inference. A handle (or a closure capturing one) may appear only as
-- a perform receiver or in a handle-typed parameter slot; anywhere else it is
-- rejected. The golden fail-examples 51-54 pin the four canonical REJECT cases
-- end-to-end (through the runner desugar); these unit tests lock the ALLOW path
-- (which must keep type-checking) and the soundness case (a handle through a
-- polymorphic parameter still escapes), plus the inline-form rejections.
carrierRuleTests :: TestTree
carrierRuleTests = testGroup "Wok.TypeChecking.CarrierRule"
  [ testGroup "ALLOW (must still type-check)"
      [ -- Performs through a handle parameter return non-handle values; nothing
        -- escapes. (Same shape as the prog/sumProd named-instance tests.)
        testCase "performs through a handle param do not escape" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "prog : State U64 -> State U64 -> ()"
            , T.pack "prog count total = let b = count.set count.get in total.set total.get"
            ]
            (T.pack "prog")
            @?= Right (T.pack "State U64 -> State U64 -> ()")

      , -- A handle passed into a handle-typed parameter slot (condition 2).
        testCase "passing handles to handle-typed params is allowed" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "prog : State U64 -> State U64 -> ()"
            , T.pack "prog count total = total.set count.get"
            , T.pack "caller : State U64 -> State U64 -> ()"
            , T.pack "caller x y = prog x y"
            ]
            (T.pack "caller")
            @?= Right (T.pack "State U64 -> State U64 -> ()")

      , -- A closure capturing a handle, USED LOCALLY (called, never returned or
        -- stored), is allowed. The final result is a U64, not a carrier.
        testCase "a local closure capturing a handle, used in place, is allowed" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "prog : State U64 -> U64"
            , T.pack "prog count = let f = \\x -> count.set x in let z = f 5 in count.get"
            ]
            (T.pack "prog")
            @?= Right (T.pack "State U64 -> U64")

      , -- A PARTIAL APPLICATION capturing a handle, used locally (called, never
        -- returned or stored), is allowed — mirrors the literal-closure case.
        -- `peek count : () -> U64` captures `count` but is invoked in place; only
        -- the U64 result escapes.
        testCase "a local partial application capturing a handle, used in place, is allowed" $
          schemeOf
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "peek : State U64 -> () -> U64"
            , T.pack "peek c u = c.get"
            , T.pack "prog : State U64 -> U64"
            , T.pack "prog count = let f = peek count in let v = f () in v"
            ]
            (T.pack "prog")
            @?= Right (T.pack "State U64 -> U64")

      , testCase "carrier predicates consult the tcCarrier marker set" $ do
          let carrierTys = Set.fromList [T.pack "H"]
              hApplied   = Ty.CTCon (Ty.TcUser (T.pack "H")) [Ty.CTCon Ty.TcU64 []]
              other      = Ty.CTCon (Ty.TcUser (T.pack "Other")) []
              effHandle  = Ty.CTCon (Ty.TcEffect (T.pack "State")) [Ty.CTCon Ty.TcU64 []]
          Carrier.isHandleType        carrierTys hApplied @?= True
          Carrier.isAffineCarrierType carrierTys hApplied @?= True
          Carrier.isHandleType        carrierTys other    @?= False
          Carrier.isAffineCarrierType carrierTys other    @?= False
          Carrier.isHandleType        Set.empty  effHandle @?= True
          Carrier.isAffineCarrierType Set.empty  effHandle @?= False
      ]

  , testGroup "REJECT (carrier escapes its scope)"
      [ -- A bare handle returned.
        testCase "returning a bare handle escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "leak : State U64 -> State U64"
            , T.pack "leak c = c"
            ]
            (T.pack "leak")

      , -- A handle stored in a constructor (a polymorphic slot).
        testCase "storing a handle in a constructor escapes" $
          assertCarrierEscape
            [ T.pack "data Box a = Box a"
            , T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "leak : State U64 -> Box (State U64)"
            , T.pack "leak c = Box c"
            ]
            (T.pack "leak")

      , -- A handle collected into a list.
        testCase "collecting handles in a list escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "leak : State U64 -> State U64 -> [State U64]"
            , T.pack "leak a b = [a, b]"
            ]
            (T.pack "leak")

      , -- A returned closure capturing a handle.
        testCase "returning a closure that captures a handle escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "leak : State U64 -> (U64 -> ())"
            , T.pack "leak count = \\x -> count.set x"
            ]
            (T.pack "leak")

      , -- A partial application capturing a handle, let-bound and then RETURNED
        -- (the C1 bug): `peek count : () -> U64` closes over `count`; returning it
        -- lets the handle outlive its scope. Must be rejected like a returned
        -- lambda.
        testCase "returning a let-bound partial application that captures a handle escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "peek : State U64 -> () -> U64"
            , T.pack "peek c u = c.get"
            , T.pack "leak : State U64 -> (() -> U64)"
            , T.pack "leak count = let f = peek count in f"
            ]
            (T.pack "leak")

      , -- A partial application capturing a handle, returned DIRECTLY (no
        -- let-binder). Same escape, caught at the partial application's own
        -- position.
        testCase "returning a partial application that captures a handle escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "peek : State U64 -> () -> U64"
            , T.pack "peek c u = c.get"
            , T.pack "leak : State U64 -> (() -> U64)"
            , T.pack "leak count = peek count"
            ]
            (T.pack "leak")

      , -- SOUNDNESS: a handle passed to a POLYMORPHIC parameter escapes, even
        -- though the call-site arrow looks handle-typed. The declared (generic)
        -- param of `identity` is a type variable, NOT a handle slot.
        testCase "a handle through a polymorphic parameter still escapes" $
          assertCarrierEscape
            [ T.pack "effect State s = { get : s, set : s -> () }"
            , T.pack "identity : a -> a"
            , T.pack "identity x = x"
            , T.pack "leak : State U64 -> State U64"
            , T.pack "leak c = identity c"
            ]
            (T.pack "leak")
      ]
  ]
  where
    assertCarrierEscape declLines name =
      case schemeOf declLines name of
        Left msg
          | T.pack "CarrierEscape" `T.isInfixOf` T.pack msg -> pure ()
          | otherwise -> assertFailure ("expected CarrierEscape, got: " ++ msg)
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)

-- The eff/row domain split is enforced by the grammar, not the typechecker:
-- `eff` only appears in an EffectRow (right of `with`) and `row` only in a
-- RowContrib (right of type-level `+`). Mixing them is therefore a parse error.
-- These tests lock that invariant (so there is no need for a RowDomainMismatch
-- type error).
effectGrammarTests :: TestTree
effectGrammarTests = testGroup "effect/row domain split (grammar)"
  [ testCase "an eff var in a record tail fails to parse" $
      assertParseFails (T.pack "module Main\nf : Point + eff e -> ()\n")
  , testCase "a row var in a with-clause fails to parse" $
      assertParseFails $ T.unlines
        [ T.pack "module Main"
        , T.pack "effect IO = { write : String -> () }"
        , T.pack "g : () -> () with row r"
        ]
  ]
  where
    assertParseFails src = case parse src of
      Left _  -> pure ()
      Right _ -> assertFailure "expected a parse error, got a successful parse"

effectOpTests :: TestTree
effectOpTests = testGroup "Wok.TypeChecking.EffectOp"
  [ testCase "calling an operation infers its effect" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "shout s = IO.write s"
        ]
        (T.pack "shout")
        @?= Right (T.pack "String -> () with IO")

  , testCase "declared with IO + IO body typechecks" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "greet : String -> () with IO"
        , T.pack "greet s = IO.write s"
        ]
        (T.pack "greet")
        @?= Right (T.pack "String -> () with IO")

  , testCase "calling two effectful functions unions their effects" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "effect Logger = { log : String -> () }"
        , T.pack "useIO : () -> () with IO"
        , T.pack "useIO u = IO.write \"x\""
        , T.pack "useLog : () -> () with Logger"
        , T.pack "useLog u = Logger.log \"y\""
        , T.pack "both u = let a = useIO () in useLog ()"
        ]
        (T.pack "both")
        @?= Right (T.pack "forall a. a -> () with IO + Logger")

  , testCase "pure-declared body calling an operation is rejected" $
      case schemeOf
             [ T.pack "effect IO = { write : String -> () }"
             , T.pack "bad : String -> ()"
             , T.pack "bad s = IO.write s"
             ]
             (T.pack "bad") of
        Left _  -> pure ()  -- rejected (RowMismatch / UndischargedEffect)
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , testCase "unknown operation of a declared effect is rejected" $
      case schemeOf
             [ T.pack "effect IO = { write : String -> () }"
             , T.pack "bad s = IO.read s"
             ]
             (T.pack "bad") of
        Left msg -> assertBool ("expected UnknownOperation, got: " ++ msg)
                      (T.pack "UnknownOperation" `T.isInfixOf` T.pack msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  ]

effectHandlerTests :: TestTree
effectHandlerTests = testGroup "Wok.TypeChecking.EffectHandler"
  [ testCase "runIO discharges IO from the result row" $
      schemeOf
        [ T.pack "effect IO = { read : String -> String, write : String -> () }"
        , T.pack "runIO comp ="
        , T.pack "  with { IO.read p -> p"
        , T.pack "       ; IO.write m -> ()"
        , T.pack "       ; return v -> v }"
        , T.pack "  comp ()"
        ]
        (T.pack "runIO")
        @?= Right (T.pack "forall a. (() -> a) -> a")

  , testCase "effect-translating handler: Logger discharged, IO introduced" $
      schemeOf
        [ T.pack "effect Logger = { log : String -> () }"
        , T.pack "effect IO = { write : String -> () }"
        , T.pack "logToIO c ="
        , T.pack "  with { Logger.log m -> IO.write m"
        , T.pack "       ; return v -> v }"
        , T.pack "  c ()"
        ]
        (T.pack "logToIO")
        @?= Right (T.pack "forall a. (() -> a) -> a with IO")

  , testCase "non-exhaustive handler is rejected (HandlerCoverage)" $
      case schemeOf
             [ T.pack "effect IO = { read : String -> String, write : String -> () }"
             , T.pack "runIO comp ="
             , T.pack "  with { IO.read p -> p }"
             , T.pack "  comp ()"
             ]
             (T.pack "runIO") of
        Left msg -> assertBool ("expected HandlerCoverage, got: " ++ msg)
                      (T.pack "HandlerCoverage" `T.isInfixOf` T.pack msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , testCase "handler with no return arm: result is the handled type" $
      schemeOf
        [ T.pack "effect IO = { write : String -> () }"
        , T.pack "runIO comp ="
        , T.pack "  with { IO.write m -> () }"
        , T.pack "  comp ()"
        ]
        (T.pack "runIO")
        @?= Right (T.pack "forall a. (() -> a) -> a")
  ]

-- First-class handler values (item-4 promotion, State slice): the exposed
-- @Handler (E params) a b@ type and the install-site payload tying. The
-- reject cases are the teeth: before the tying fix, 'dischargeEffects'
-- dropped the row payload unforced, so a handler for @State U64@ installed
-- over a body performing @State.set "oops"@ typechecked and ran.
handlerValueTests :: TestTree
handlerValueTests = testGroup "Wok.TypeChecking.HandlerValue"
  [ testCase "zero-param handler value scheme: Handler E a a" $
      schemeOf
        [ "effect Ask = { ask : U64 }"
        , "mk = handler Ask { ask -> 41 ; return v -> v }"
        ]
        "mk"
        @?= Right "forall a. Handler Ask a a"

  , testCase "parameterized handler value scheme exposes the effect's param" $
      schemeOf
        [ "effect State s = { get : s, set : s -> () }"
        , "mk = handler State { get -> 7 ; once set x k -> k () ; return v -> v }"
        ]
        "mk"
        @?= Right "forall a. Handler (State U64) a a"

  , testCase "install-site tying: mistyped perform payload is rejected" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "main : U64"
             , "main ="
             , "  let h = handler State { get -> 0 ; once set x k -> k () ; return v -> v } in"
             , "  handle h in (let u = State.set \"oops\" in 1)"
             ])
      case r of
        Left err -> assertBool ("expected Mismatch, got: " ++ err)
                      ("Mismatch" `Data.List.isInfixOf` err)
        Right v  -> assertFailure ("expected rejection, got: " ++ T.unpack v)

  , testCase "install-site tying: well-typed payload accepted and runs" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "main : U64"
             , "main ="
             , "  let h = handler State { get -> 7 ; once set x k -> k () ; return v -> v } in"
             , "  handle h in (let u = State.set 5 in State.get + 1)"
             ])
      r @?= Right "8"

  , testCase "handler value missing an op arm is rejected (HandlerCoverage)" $
      case schemeOf
             [ "effect State s = { get : s, set : s -> () }"
             , "mk = handler State { get -> 7 ; return v -> v }"
             ]
             "mk" of
        Left msg -> assertBool ("expected HandlerCoverage, got: " ++ msg)
                      ("HandlerCoverage" `Data.List.isInfixOf` msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  -- var seeding (task B): the polymorphic runner shape the prelude migration
  -- needs -- seed from the construction scope, baton via two-arg resume.
  , testCase "runner scheme: seed arg flows into the Handler's param and answer" $
      schemeOf
        [ "effect State s = { get : s, set : s -> () }"
        , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> (v, s) }"
        ]
        "state"
        @?= Right "forall a b. a -> Handler (State a) b (b, a)"

  , testCase "var seeding: fused and value forms agree on a set/get round trip" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "runFused : (U64, U64)"
             , "runFused ="
             , "  with State { var s = 10 ; get -> s ; once set x k -> k x () ; return v -> (v, s) }"
             , "  (let u = State.set (State.get + 5) in State.get)"
             , "runValue : (U64, U64)"
             , "runValue ="
             , "  let h = handler State { var s = 10 ; get -> s ; once set x k -> k x () ; return v -> (v, s) } in"
             , "  handle h in (let u = State.set (State.get + 5) in State.get)"
             , "main : ((U64, U64), (U64, U64))"
             , "main = (runFused, runValue)"
             ])
      r @?= Right "((15, 15), (15, 15))"

  , testCase "var seeding: two installs of one value each start from the seed" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "useOnce h d = handle h in (let u = State.set (State.get + d) in State.get)"
             , "main : ((U64, U64), (U64, U64))"
             , "main ="
             , "  let h = handler State { var s = 10 ; get -> s ; once set x k -> k x () ; return v -> (v, s) } in"
             , "  (useOnce h 1, useOnce h 100)"
             ])
      r @?= Right "((11, 11), (110, 110))"

  -- Effect resolution from the handler's TYPE (task D): a concrete
  -- Handler E ... names its effect, so the body may perform other effects
  -- (residual flows out) or none at all -- both were errors when the effect
  -- could only be read off the body's row.
  , testCase "concrete handler: body may perform a second effect (residual)" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "effect Logger = { log : U64 -> () }"
             , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> (v, s) }"
             , "runBoth : () -> (U64, U64) with Logger"
             , "runBoth z = handle (state 5) in"
             , "  (let u = Logger.log (State.get) in"
             , "   let w = State.set 9 in State.get)"
             , "collect : (() -> a with Logger) -> a"
             , "collect c = with { Logger.log n -> () ; return v -> v } (c ())"
             , "main : (U64, U64)"
             , "main = collect runBoth"
             ])
      r @?= Right "(9, 9)"

  , testCase "concrete handler: pure body is legal; return arm still runs" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> (v, s) }"
             , "main : (U64, U64)"
             , "main = handle (state 5) in 42"
             ])
      r @?= Right "(42, 5)"

  -- Named install (task C, item-4 D5): `handle name = h in body` binds the
  -- role label; `name.op` id-routes to that activation. Two same-effect
  -- instances coexist -- the gap the named-instances feature left untested.
  , testCase "named install: two instances of one effect route apart" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> v }"
             , "main : (U64, U64)"
             , "main ="
             , "  handle a = state 1 in"
             , "  handle b = state 20 in"
             , "  (let u = a.set (a.get + b.get) in"
             , "   (a.get, b.get))"
             ])
      r @?= Right "(21, 20)"

  , testCase "named install: one handler value under two labels is two activations" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "main : (U64, U64)"
             , "main ="
             , "  let h = handler State { var s = 5 ; get -> s ; once set x k -> k x () ; return v -> v } in"
             , "  handle a = h in"
             , "  handle b = h in"
             , "  (let u = a.set 99 in (a.get, b.get))"
             ])
      r @?= Right "(99, 5)"

  -- Review round: a handler VALUE whose arms capture a second-class carrier
  -- escaped the carrier-escape analysis (ran to NoMatchingHandler at runtime
  -- where the byte-identical lambda was rejected statically).
  , testCase "handler value capturing an instance handle is a CarrierEscape" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "effect E = { ask : U64 }"
             , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> v }"
             , "mk = handle c = state 7 in handler E { ask -> c.get ; return v -> v }"
             , "main : U64"
             , "main = handle mk in E.ask"
             ])
      case r of
        Left err -> assertBool ("expected CarrierEscape, got: " ++ err)
                      ("CarrierEscape" `Data.List.isInfixOf` err)
        Right v  -> assertFailure ("expected rejection, got: " ++ T.unpack v)

  -- Review round: two arms for one operation were silently accepted; runtime
  -- dispatch first-matches, so the later arm was dead code with no diagnostic.
  , testCase "duplicate op arm is rejected (handler value)" $
      case schemeOf
             [ "effect Ask = { ask : U64 }"
             , "mk = handler Ask { ask -> 1 ; ask -> 2 ; return v -> v }"
             ]
             "mk" of
        Left msg -> assertBool ("expected DuplicateOpArm, got: " ++ msg)
                      ("DuplicateOpArm" `Data.List.isInfixOf` msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , testCase "duplicate op arm is rejected (fused ambient handler)" $
      case schemeOf
             [ "effect Ask = { ask : U64 }"
             , "run c = with { Ask.ask -> 1 ; Ask.ask -> 2 ; return v -> v } (c ())"
             ]
             "run" of
        Left msg -> assertBool ("expected DuplicateOpArm, got: " ++ msg)
                      ("DuplicateOpArm" `Data.List.isInfixOf` msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , testCase "named install of a polymorphic handler is rejected" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect Ask = { ask : U64 }"
             , "run f = handle c = f in c.ask"
             , "main : U64"
             , "main = run (handler Ask { ask -> 41 ; return v -> v })"
             ])
      case r of
        Left err -> assertBool ("expected UnsupportedFeature, got: " ++ err)
                      ("UnsupportedFeature" `Data.List.isInfixOf` err)
        Right v  -> assertFailure ("expected rejection, got: " ++ T.unpack v)

  -- Regression: a VALUE-POSITION install used to elaborate its body at the
  -- merge join, jumping PAST the KHandle frame -- the return arm silently
  -- never ran (this program printed (6, 50)). The body is now TRet-elaborated
  -- and the install thunk-wrapped, so the return arm's pair survives.
  , testCase "value-position install runs the return arm" $ do
      r <- runSourceToValueForced (T.unlines
             [ "module Main"
             , "import Base"
             , "effect State s = { get : s, set : s -> () }"
             , "state i = handler State { var s = i ; get -> s ; once set x k -> k x () ; return v -> (v, s) }"
             , "main : ((U64, U64), (U64, U64))"
             , "main ="
             , "  ( handle (state 3) in (let u = State.set (State.get * 2) in State.get)"
             , "  , handle (state 50) in State.get )"
             ])
      r @?= Right "((6, 6), (50, 50))"
  ]

-- Adversarial coverage for the effect system: the spec's acceptance criteria
-- that the happy-path fixtures do NOT exercise -- partial discharge, the
-- single-use-vs-threading rule (spec 136-151), multi-effect handlers, operation
-- mismatches, and the two known spec/impl divergences (handler effect-presence,
-- main row emptiness) pinned as characterization so a future change is forced
-- to update them deliberately.
effectPressureTests :: TestTree
effectPressureTests = testGroup "Wok.TypeChecking.EffectPressure"
  [ testGroup "discharge"
      [ testCase "handler discharges only the handled effect; residual flows out" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "effect Logger = { log : String -> () }"
            , "partial : (() -> a with IO + Logger + eff e) -> a with Logger + eff e"
            , "partial comp ="
            , "  with { IO.write m -> ()"
            , "       ; return v -> v }"
            , "  comp ()"
            ]
            "partial"
            @?= Right "forall b a. (() -> b with IO + Logger + eff a) -> b with Logger + eff a"

      , testCase "one handler discharges two effects at once" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "effect Logger = { log : String -> () }"
            , "runBoth : (() -> a with IO + Logger + eff e) -> a with eff e"
            , "runBoth comp ="
            , "  with { IO.write m -> ()"
            , "       ; Logger.log m -> ()"
            , "       ; return v -> v }"
            , "  comp ()"
            ]
            "runBoth"
            @?= Right "forall b a. (() -> b with IO + Logger + eff a) -> b with eff a"
      ]

  , testGroup "threading rule (.. is single-use; eff e threads)"
      [ -- spec 145: an anonymous `..` cannot thread, so it is rejected in a
        -- parameter (contravariant) position -- here the callback's `IO + ..`.
        -- A callback's effects could only be dropped via an anonymous tail;
        -- the user must name it (`eff e`) to carry them through.
        testCase "anonymous .. in a callback parameter is rejected (spec 145)" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "relay : (() -> a with IO + ..) -> a with IO + .."
            , "relay f = f ()"
            ]
            "relay"

      , testCase "named eff e threads a param tail to the result (accepted)" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "relay : (() -> a with IO + eff e) -> a with IO + eff e"
            , "relay f = f ()"
            ]
            "relay"
            @?= Right "forall b a. (() -> b with IO + eff a) -> b with IO + eff a"

      , -- spec 142: the same rule for records -- an anonymous `..` record tail in
        -- a parameter position is rejected; use `row r` (next test) to thread the
        -- input's extra fields through to the output.
        testCase "record .. in a parameter position is rejected (spec 142)" $
          schemeRejected
            [ "data Point = Point { x : U64, y : U64 }"
            , "preserveBad : Point + .. -> Point + .."
            , "preserveBad p = p"
            ]
            "preserveBad"

      , testCase "record row r threads input tail to output (accepted)" $
          case schemeOf
                 [ "data Point = Point { x : U64, y : U64 }"
                 , "preserveOk : Point + row r -> Point + row r"
                 , "preserveOk p = p"
                 ]
                 "preserveOk" of
            Left msg -> assertFailure ("expected success, got: " ++ msg)
            Right _  -> pure ()
      ]

  , testGroup "operation calls"
      [ testCase "two calls of the same effect union to a single label" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "twice u = let a = IO.write \"x\" in IO.write \"y\""
            ]
            "twice"
            @?= Right "forall a. a -> () with IO"

      , testCase "parameterized effect: get/set share the effect's type param" $
          case schemeOf
                 [ "effect State a = { get : () -> a, set : a -> () }"
                 , "incr u = let n = State.get () in State.set n"
                 ]
                 "incr" of
            Left msg -> assertFailure ("expected success, got: " ++ msg)
            Right _  -> pure ()

      , testCase "operation called with the wrong argument type is rejected" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "bad : () -> () with IO"
            , "bad u = IO.write 42"
            ]
            "bad"

      , -- Regression guard for the multi-arg arrow-placement fix: the parser
        -- attaches `with E` to the INNERMOST arrow (where a fully-applied
        -- curried function performs its effects), and the body's ambient is now
        -- seeded from that same arrow. A multi-arg effectful function therefore
        -- typechecks (it was wrongly rejected with UndischargedEffect before).
        testCase "multi-arg effectful function typechecks (effect on the innermost arrow)" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "f : U64 -> U64 -> () with IO"
            , "f x y = IO.write \"x\""
            ]
            "f"
            @?= Right "U64 -> U64 -> () with IO"

      , testCase "three-arg effectful function typechecks (deeper innermost arrow)" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "g : U64 -> U64 -> U64 -> () with IO"
            , "g x y z = IO.write \"x\""
            ]
            "g"
            @?= Right "U64 -> U64 -> U64 -> () with IO"

      , testCase "unsigned multi-arg effectful function infers the effect on the innermost arrow" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "h x y = IO.write x"
            ]
            "h"
            @?= Right "forall a. String -> a -> () with IO"
      ]

  , testGroup "handler arms"
      [ testCase "arm body type must match the operation's result type" $
          schemeRejected
            [ "effect IO = { read : String -> String }"
            , "bad comp ="
            , "  with { IO.read p -> 42"
            , "       ; return v -> v }"
            , "  comp ()"
            ]
            "bad"
      ]

  , testGroup "known spec/impl divergences (characterization)"
      [ -- Spec step 2 (handler typing): "each handled effect E must be present
        -- in rho." The current impl is lenient -- handling an effect the
        -- scrutinee never performs is silently accepted (the handled label is
        -- simply not found to discharge). Pinned here as ACCEPTED; this flips to
        -- a rejection if/when declaration-is-authority lands.
        testCase "handling an absent effect is currently accepted (spec wants reject)" $
          case schemeOf
                 [ "effect IO = { write : String -> () }"
                 , "effect Logger = { log : String -> () }"
                 , "vacuous : () -> () with Logger"
                 , "vacuous u = Logger.log \"x\""
                 , "weird c ="
                 , "  with { IO.write m -> ()"
                 , "       ; return v -> v }"
                 , "  vacuous ()"
                 ]
                 "weird" of
            Left msg -> assertFailure
                          ("currently expected to be ACCEPTED (lenient handler); got: " ++ msg)
            Right _  -> pure ()

        -- Spec line 230: "main must reduce to an empty effect row -- the
        -- compiler rejects a program with an unwired capability." v1 does not
        -- special-case main, so a main with a residual effect is accepted.
      , testCase "main with an unhandled effect is currently accepted (spec wants reject)" $
          assertModuleTypechecks $ T.unlines
            [ T.pack "module Main"
            , T.pack "effect IO = { write : String -> () }"
            , T.pack "main : () -> () with IO"
            , T.pack "main u = IO.write \"x\""
            ]
      ]
  ]
  where
    schemeRejected decls name = case schemeOf decls name of
      Left _  -> pure ()
      Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)

-- Maps the closed-by-default soundness boundary: the closed / inferred /
-- first-order core never lets an effect escape a type (it propagates the effect
-- into the caller's row, or rejects the call) -- but the `..` open-tail
-- escape hatch can DROP a parameter's effect. These tests prove the default is
-- sound and pin the single leak, so the link-tails redesign has a target.
closedByDefaultTests :: TestTree
closedByDefaultTests = testGroup "closed-by-default (soundness boundary)"
  [ testGroup "sound: closed / inferred / first-order never drops an effect"
      [ testCase "a function with no operation calls infers a pure (no `with`) type" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "k x y = x"
            ]
            "k"
            @?= Right "forall a b. a -> b -> a"

      , testCase "an effect propagates from a callee into an unsigned caller" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "useIO : () -> () with IO"
            , "useIO u = IO.write \"x\""
            , "caller u = useIO ()"
            ]
            "caller"
            @?= Right "forall a. a -> () with IO"

      , testCase "a pure-declared function that calls an effectful one is rejected" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "useIO : () -> () with IO"
            , "useIO u = IO.write \"x\""
            , "pureCaller : () -> ()"
            , "pureCaller u = useIO ()"
            ]
            "pureCaller"

      , testCase "a closed effect row rejects an operation it does not list" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "effect Logger = { log : String -> () }"
            , "f : () -> () with IO"
            , "f u = Logger.log \"x\""
            ]
            "f"

      , testCase "an unsigned HOF defaults to a pure callback (effectful arg rejected)" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "useIO : () -> () with IO"
            , "useIO u = IO.write \"x\""
            , "runThunk f = f ()"
            , "bad u = runThunk useIO"
            ]
            "bad"
      ]

  , testGroup "higher-order effect application (after the signed-binding polymorphism fix)"
      [ -- Once signed bindings are referenced via their instantiated signature
        -- (not a monomorphic placeholder), combinators can finally be APPLIED to
        -- concrete effectful arguments. The earlier RigidEscape over-rejection is
        -- gone, and `eff e` threads soundly. This is the payoff of the fix.

        -- Exact match: relaying a thunk performing exactly IO now type-checks.
        testCase "an eff e combinator applies to a concrete thunk (over-rejection fixed)" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "useIO : () -> () with IO"
            , "useIO u = IO.write \"x\""
            , "relayE : (() -> a with IO + eff e) -> a with IO + eff e"
            , "relayE f = f ()"
            , "good u = relayE useIO"
            ]
            "good"
            @?= Right "forall a. a -> () with IO"

      , -- The same fix in the LET/WHERE path (inferLetGroup), not just top level
        -- (inferTopLetGroup): a where-bound combinator applied to a concrete
        -- thunk also works. Before the fix this RigidEscaped here too.
        testCase "a where-bound eff e combinator applies to a concrete thunk" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "caller u = relayE useIO"
            , "  where"
            , "    relayE : (() -> a with IO + eff e) -> a with IO + eff e"
            , "    relayE f = f ()"
            , "    useIO : () -> () with IO"
            , "    useIO v = IO.write \"x\""
            ]
            "caller"
            @?= Right "forall a. a -> () with IO"

      , -- A thunk with an effect beyond the concrete part: `eff e` THREADS it to
        -- the caller's row -- the sound, intended behavior.
        testCase "eff e threads an extra concrete effect to the caller (sound)" $
          schemeOf
            [ "effect IO = { write : String -> () }"
            , "effect Logger = { log : String -> () }"
            , "relayE : (() -> a with IO + eff e) -> a with IO + eff e"
            , "relayE f = f ()"
            , "useIL : () -> () with IO + Logger"
            , "useIL u = let l = Logger.log \"x\" in IO.write \"y\""
            , "good u = relayE useIL"
            ]
            "good"
            @?= Right "forall a. a -> () with IO + Logger"

      , -- spec 145 (now enforced): the `..` relay is rejected at its DEFINITION
        -- (anonymous tail in the callback parameter), so the previously-reachable
        -- silent drop of Logger is gone -- the program no longer type-checks at
        -- all. `eff e` (above) is the sound way to thread a callback's effects.
        testCase ".. relay is rejected at its definition, so no silent drop is reachable (spec 145)" $
          schemeRejected
            [ "effect IO = { write : String -> () }"
            , "effect Logger = { log : String -> () }"
            , "relay : (() -> a with IO + ..) -> a with IO + .."
            , "relay f = f ()"
            , "useIL : () -> () with IO + Logger"
            , "useIL u = let l = Logger.log \"x\" in IO.write \"y\""
            , "bad u = relay useIL"
            ]
            "bad"
      ]
  ]
  where
    schemeRejected decls name = case schemeOf decls name of
      Left _  -> pure ()
      Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)

-- A lambda is a function: the effects its body performs belong to the lambda's
-- own arrow (performed when it is applied), not to the enclosing equation.
-- Before the fix, a lambda body's operation calls leaked into the enclosing
-- binding's effect row and the lambda value was typed as a pure arrow.
lambdaEffectScopingTests :: TestTree
lambdaEffectScopingTests = testGroup "lambda effect scoping"
  [ testCase "a lambda's effect rides its own arrow (matches the signature)" $
      schemeOf
        [ "effect IO = { write : String -> () }"
        , "w : String -> () with IO"
        , "w = \\v -> IO.write v"
        ]
        "w"
        @?= Right "String -> () with IO"

  , -- The decisive no-leak check: `mk` returns an effectful closure, so APPLYING
    -- `mk` (merely building the closure) performs no effect and `safe` -- which
    -- only builds it -- stays pure. Before the fix the lambda's IO leaked onto
    -- `mk`'s arrow, making `mk u` effectful and rejecting `safe` with
    -- UndischargedEffect.
    testCase "a lambda's effect does NOT leak to the enclosing binding" $
      schemeOf
        [ "effect IO = { write : String -> () }"
        , "mk u = \\v -> IO.write v"
        , "safe : () -> ()"
        , "safe u = let f = mk u in ()"
        ]
        "safe"
        @?= Right "() -> ()"

  , -- Regression for review finding #2 (same root cause): an equation with
    -- FEWER pattern parameters than its signature's arrows, taking the rest via
    -- a lambda body, now typechecks -- the lambda carries the declared effect on
    -- the inner arrow, matching the signature.
    testCase "equation with a lambda body and fewer params than sig arrows typechecks" $
      schemeOf
        [ "effect IO = { write : String -> () }"
        , "f : U64 -> U64 -> () with IO"
        , "f x = \\y -> IO.write \"z\""
        ]
        "f"
        @?= Right "U64 -> U64 -> () with IO"
  ]

-- IO ground effect (Task 2): IO is a built-in effect with no ops, never handled,
-- discharged by running the program.
ioGroundEffectTests :: TestTree
ioGroundEffectTests = testGroup "IO effect"
  [ testCase "a with IO signature type-checks (IO resolves as ground effect)" $
      schemeOf
        [ "f : U64 -> U64 with IO"
        , "f x = x"
        ]
        "f"
        @?= Right "U64 -> U64 with IO"

  , testCase "a with-handler targeting IO is rejected (IOEffectNotHandleable)" $
      case schemeOf
             [ "g x ="
             , "  with IO { return v -> v }"
             , "  x"
             ]
             "g" of
        Left msg -> assertBool ("expected IOEffectNotHandleable, got: " ++ msg)
                      (T.pack "IOEffectNotHandleable" `T.isInfixOf` T.pack msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , -- The NAMED-handler path (`with self = IO { ... } in ...`, via
    -- inferNamedHandler) must also reject the ground IO. The ambient path above
    -- exercises inferHandler; this drives inferNamedHandler with effName == "IO".
    testCase "a named handler targeting IO is rejected (IOEffectNotHandleable)" $
      case schemeOf
             [ "g x = with s = IO { return v -> v } in x"
             ]
             "g" of
        Left msg -> assertBool ("expected IOEffectNotHandleable, got: " ++ msg)
                      (T.pack "IOEffectNotHandleable" `T.isInfixOf` T.pack msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , testCase "a forgotten State effect still errors with UndischargedEffect (no regression)" $
      case schemeOf
             [ "effect State s = { get : s, set : s -> () }"
             , "bad : () -> U64"
             , "bad u = State.get ()"
             ]
             "bad" of
        Left msg -> assertBool ("expected UndischargedEffect, got: " ++ msg)
                      (T.pack "UndischargedEffect" `T.isInfixOf` T.pack msg)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , -- REGRESSION (Task 2 review): the IO ground-effect override must be scoped
    -- to IO ONLY. An entry module's env already contains the prelude effects it
    -- imported (State, Reader, ...), so a redeclaration of one of those must
    -- still be a DuplicateTyCon -- not silently overridden. We mimic the import
    -- by seeding `State` (with a non-empty op map) into the starting env and
    -- then redeclaring `effect State` via processEffectDecls.
    testCase "redeclaring an imported effect (State) is DuplicateTyCon (override scoped to IO)" $
      let pos = (0, 0)
          vc s = Abs.ConId (pos, T.pack s)
          vv s = Abs.VarId (pos, T.pack s)
          -- A pre-existing `State a` with one op `get : () -> a`, as if imported.
          importedState = TE.EffectInfo
            { TE.eiParams = [(0, Ty.KStar)]
            , TE.eiOps    = Map.fromList
                [ ( T.pack "get"
                  , Ty.mkScheme [(0, Ty.KStar)]
                      (Ty.CTArr (Ty.CTCon Ty.TcUnit []) Ty.CREmpty (Ty.CTGen 0)) )
                ]
            }
          env0 = TE.extendEffect (T.pack "State") importedState B.initialEnv
          -- The entry module redeclares `effect State s = { get : () -> s }`.
          getOp = Abs.RFType (vv "get")
                    (Abs.TFun Abs.TUnit (Abs.TVar (vv "s")))
          decl  = Abs.DEffect (vc "State") [vv "s"] [getOp]
          result = TM.runTC_ env0 $ I.processEffectDecls env0 [decl]
      in case result of
           Left TErr.DuplicateTyCon{} -> pure ()
           Left e  -> assertFailure ("expected DuplicateTyCon, got: " ++ show e)
           Right _ -> assertFailure
             "expected DuplicateTyCon for redeclared imported State, but it was accepted"

  , -- Positive control for the same code path: the ground IO (empty ops, seeded
    -- in initialEnv) IS overridable by a user `effect IO = { ... }`.
    testCase "redeclaring the ground IO with ops overrides it (no error)" $
      let pos = (0, 0)
          vc s = Abs.ConId (pos, T.pack s)
          vv s = Abs.VarId (pos, T.pack s)
          writeOp = Abs.RFType (vv "write")
                      (Abs.TFun (Abs.TCon (Abs.MPName (vc "String"))) Abs.TUnit)
          decl    = Abs.DEffect (vc "IO") [] [writeOp]
          result  = TM.runTC_ B.initialEnv $ I.processEffectDecls B.initialEnv [decl]
      in case result of
           Right env -> case TE.lookupEffect (T.pack "IO") env of
             Just ei -> Map.keys (TE.eiOps ei) @?= [T.pack "write"]
             Nothing -> assertFailure "IO missing after override"
           Left e   -> assertFailure ("expected IO override to succeed, got: " ++ show e)
  ]

dataTests :: TestTree
dataTests = testGroup "Wok.TypeChecking.Infer (data decls)"
  [ testCase "data Maybe a = Nothing | Just a registers correctly" $
      let pos = (0,0)
          vc s = Abs.ConId (pos, T.pack s)
          vv s = Abs.VarId (pos, T.pack s)
          tp s = Abs.TPPlain (vv s)
          decl = Abs.DData (vc "Maybe") [tp "a"]
                   [ Abs.ConDef (vc "Nothing") []
                   , Abs.ConDef (vc "Just") [Abs.TVar (vv "a")]
                   ]
          result = TM.runTC_ B.initialEnv $
                     I.processDataDecls B.initialEnv [decl]
      in case result of
           Right env -> do
             case TE.lookupTyCon (T.pack "Maybe") env of
               Just info -> do
                 TE.tcArity info @?= 1
                 TE.tcCons info @?= [T.pack "Nothing", T.pack "Just"]
               Nothing -> assertFailure "Maybe missing"
             case TE.lookupCon (T.pack "Just") env of
               Just info -> do
                 TE.conArity info @?= 1
                 TE.conTyCon info @?= T.pack "Maybe"
                 case TE.conScheme info of
                   Ty.Scheme [(0, Ty.KStar)] _ body ->
                     case body of
                       Ty.CTArr (Ty.CTGen 0) Ty.CREmpty
                         (Ty.CTCon (Ty.TcUser tn) [Ty.CTGen 0])
                           | tn == T.pack "Maybe" -> pure ()
                       _ -> assertFailure ("Just body: " ++ show body)
                   _ -> assertFailure "Just scheme malformed"
               Nothing -> assertFailure "Just missing"
           Left e -> assertFailure (show e)
  , testCase "duplicate tycon (vs Base Bool) errors" $ do
      env <- stdBaseExtendedEnv
      let pos = (0,0)
          vc s = Abs.ConId (pos, T.pack s)
          decl = Abs.DData (vc "Bool") [] []
          result = TM.runTC_ env $ I.processDataDecls env [decl]
      case result of
        Left (TErr.DuplicateTyCon _ _) -> pure ()
        _ -> assertFailure
                ("expected DuplicateTyCon, got "
                ++ either show (const "Right") result)
  , testCase "extern data/type elaborate to carrier-marked tycons" $
      let pos = (0,0)
          vc s = Abs.ConId (pos, T.pack s)
          vv s = Abs.VarId (pos, T.pack s)
          tp s = Abs.TPPlain (vv s)
          -- extern type Susp a b r
          suspDecl = Abs.DExternType (vc "Susp") [tp "a", tp "b", tp "r"]
          -- extern data St a b r = Done r | More a (Susp a b r)
          stDecl = Abs.DExternData (vc "St") [tp "a", tp "b", tp "r"]
                     [ Abs.ConDef (vc "Done") [Abs.TVar (vv "r")]
                     , Abs.ConDef (vc "More")
                         [ Abs.TVar (vv "a")
                         , Abs.TApp
                             (Abs.TApp
                               (Abs.TApp
                                 (Abs.TCon (Abs.MPName (vc "Susp")))
                                 (Abs.TVar (vv "a")))
                               (Abs.TVar (vv "b")))
                             (Abs.TVar (vv "r"))
                         ]
                     ]
          -- data Plain a = MkPlain a
          plainDecl = Abs.DData (vc "Plain") [tp "a"]
                        [ Abs.ConDef (vc "MkPlain") [Abs.TVar (vv "a")] ]
          result = TM.runTC_ B.initialEnv $
                     I.processDataDecls B.initialEnv [suspDecl, stDecl, plainDecl]
      in case result of
           Right env -> do
             case TE.lookupTyCon (T.pack "Susp") env of
               Just info -> TE.tcCarrier info @?= True
               Nothing   -> assertFailure "Susp missing"
             case TE.lookupTyCon (T.pack "St") env of
               Just info -> do
                 TE.tcCarrier info @?= True
                 TE.tcCons info @?= [T.pack "Done", T.pack "More"]
               Nothing -> assertFailure "St missing"
             case TE.lookupTyCon (T.pack "Plain") env of
               Just info -> TE.tcCarrier info @?= False
               Nothing   -> assertFailure "Plain missing"
           Left e -> assertFailure (show e)
  , testCase "tcParamKinds: (row e) is KEffect, bare is KStar" $
      let pos = (0,0)
          vc s = Abs.ConId (pos, T.pack s)
          vv s = Abs.VarId (pos, T.pack s)
          -- data Box (row e) = Box U64
          boxDecl = Abs.DData (vc "Box") [Abs.TPRow (vv "e")]
                      [ Abs.ConDef (vc "Box")
                          [Abs.TCon (Abs.MPName (vc "U64"))] ]
          -- data Plain a = Plain a
          plainDecl = Abs.DData (vc "Plain") [Abs.TPPlain (vv "a")]
                        [ Abs.ConDef (vc "Plain") [Abs.TVar (vv "a")] ]
          result = TM.runTC_ B.initialEnv $
                     I.processDataDecls B.initialEnv [boxDecl, plainDecl]
      in case result of
           Right env -> do
             case TE.lookupTyCon (T.pack "Box") env of
               Just info -> TE.tcParamKinds info @?= [Ty.KEffect]
               Nothing   -> assertFailure "Box missing"
             case TE.lookupTyCon (T.pack "Plain") env of
               Just info -> TE.tcParamKinds info @?= [Ty.KStar]
               Nothing   -> assertFailure "Plain missing"
           Left e -> assertFailure (show e)
  ]

patternTests :: TestTree
patternTests = testGroup "Wok.TypeChecking.Infer (patterns)"
  [ testCase "var pattern returns fresh type and one binding" $
      let result = TM.runTC_ B.initialEnv $ do
            (t, bs, _) <- I.inferPat
              (Abs.PAtom (Abs.APVar (Abs.VarId ((0,0), T.pack "x"))))
            pure (length bs, case t of Ty.TVar _ -> True; _ -> False)
      in case result of
           Right (1, True) -> pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  , testCase "literal Int pattern" $
      let result = TM.runTC_ B.initialEnv $ do
            (t, _, _) <- I.inferPat
              (Abs.PAtom (Abs.APLitI
                (Abs.WokInt ((0,0), T.pack "5"))))
            U.freeze t
      in case result of
           Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
           Left e -> assertFailure (show e)
  , testCase "wildcard pattern returns fresh type, no bindings" $
      let result = TM.runTC_ B.initialEnv $ do
            (_, bs, _) <- I.inferPat (Abs.PAtom Abs.APWild)
            pure (length bs)
      in case result of
           Right 0 -> pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  , testCase "True nullary constructor pattern" $ do
      env <- stdBaseExtendedEnv
      let result = TM.runTC_ env $ do
            (t, _, _) <- I.inferPat (Abs.PAtom
              (Abs.APCon (Abs.MPName (Abs.ConId ((0,0), T.pack "True")))))
            U.freeze t
      case result of
        Right ct -> ct @?= Ty.CTCon Ty.TcBool []
        Left e -> assertFailure (show e)
  , testCase "tuple pattern (x, y) gives 2-tuple type and 2 bindings" $
      let pos = (0,0)
          vp s = Abs.PAtom (Abs.APVar (Abs.VarId (pos, T.pack s)))
          result = TM.runTC_ B.initialEnv $ do
            (t, bs, _) <- I.inferPat
              (Abs.PAtom (Abs.APTuple (vp "x") [vp "y"]))
            ct <- U.freeze t
            pure (ct, length bs)
      in case result of
           Right (Ty.CTCon (Ty.TcTuple 2) [_, _], 2) -> pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  ]

exprBasicTests :: TestTree
exprBasicTests = testGroup "ExprBasic"
  [ testCase "literal Int" $
      let result = TM.runTC_ B.initialEnv $ do
            t <- I.inferExpr (Abs.ELitI (Abs.WokInt ((0,0), T.pack "42")))
            U.freeze t
      in case result of
           Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
           Left e -> assertFailure (show e)
  , testCase "if True then 1 else 2 : Int" $ do
      env <- stdBaseExtendedEnv
      let true = Abs.ECon (Abs.ConId ((0,0), T.pack "True"))
          mkI s = Abs.ELitI (Abs.WokInt ((0,0), T.pack s))
          result = TM.runTC_ env $ do
            t <- I.inferExpr (Abs.EIf true (mkI "1") (mkI "2"))
            U.freeze t
      case result of
        Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
        Left e -> assertFailure (show e)
  , testCase "(+) 1 2 : Int" $ do
      env <- stdBaseExtendedEnv
      let plus = Abs.EParenOp (Abs.VarSym ((0,0), T.pack "+"))
          mkI s = Abs.ELitI (Abs.WokInt ((0,0), T.pack s))
          result = TM.runTC_ env $ do
            t <- I.inferExpr (Abs.EApp (Abs.EApp plus (mkI "1")) (mkI "2"))
            U.freeze t
      case result of
        Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
        Left e -> assertFailure (show e)
  , testCase "\\x -> x : a -> a" $
      let lam = Abs.ELam [Abs.APVar (Abs.VarId ((0,0), T.pack "x"))]
                  (Abs.EVar (Abs.VarId ((0,0), T.pack "x")))
          result = TM.runTC_ B.initialEnv $ do
            t <- I.inferExpr lam
            U.freeze t
      in case result of
           Right (Ty.CTArr (Ty.CTGen i) Ty.CREmpty (Ty.CTGen j)) | i == j -> pure ()
           other -> assertFailure ("unexpected: " ++ show other)
  , testCase "EProj on unknown var fails with UnknownVar" $
      let proj = Abs.EProj (Abs.EVar (Abs.VarId ((0,0), T.pack "x")))
                   (Abs.VarId ((0,0), T.pack "y"))
          result = TM.runTC_ B.initialEnv
                     (I.inferExpr proj >>= \t -> U.freeze t)
      in case result of
           Left (TErr.UnknownVar _ _) -> pure ()
           _ -> assertFailure
                  ("expected UnknownVar, got "
                  ++ either show (const "Right") result)
  ]

exprLetTests :: TestTree
exprLetTests = testGroup "ExprLet"
  [ testCase "let id = \\x -> x in (id 1, id True) : (Int, Bool)" $ do
      env <- stdBaseExtendedEnv
      let pos = (0,0)
          v s = Abs.VarId (pos, T.pack s)
          c s = Abs.ConId (pos, T.pack s)
          ldId = Abs.LDEqn
                   (Abs.LHSPre (Abs.FNBare (v "id")) [Abs.APVar (v "x")])
                   (Abs.EVar (v "x")) Abs.NoWhere
          one  = Abs.ELitI (Abs.WokInt (pos, T.pack "1"))
          true = Abs.ECon (c "True")
          body = Abs.ETuple
                   (Abs.EApp (Abs.EVar (v "id")) one)
                   [Abs.EApp (Abs.EVar (v "id")) true]
          result = TM.runTC_ env $ do
            t <- I.inferExpr (Abs.ELet [ldId] body)
            U.freeze t
      case result of
        Right ct -> ct @?= Ty.CTCon (Ty.TcTuple 2)
                           [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcBool []]
        Left e -> assertFailure (show e)
  , testCase "case True of True -> 1; False -> 0 : Int" $ do
      env <- stdBaseExtendedEnv
      let pos = (0,0)
          c s  = Abs.ConId (pos, T.pack s)
          mkI s = Abs.ELitI (Abs.WokInt (pos, T.pack s))
          true = Abs.ECon (c "True")
          altT = Abs.AltC (Abs.PAtom (Abs.APCon (Abs.MPName (c "True"))))
                          (mkI "1") Abs.NoWhere
          altF = Abs.AltC (Abs.PAtom (Abs.APCon (Abs.MPName (c "False"))))
                          (mkI "0") Abs.NoWhere
          result = TM.runTC_ env $ do
            t <- I.inferExpr (Abs.ECase true [altT, altF])
            U.freeze t
      case result of
        Right ct -> ct @?= Ty.CTCon Ty.TcU64 []
        Left e -> assertFailure (show e)
  , testCase "f x = let y = x in y : forall a. a -> a (escape via outer var)" $
      let src = T.pack "f x = let y = x in y\n"
          result = do
            parsed <- first ("parse: " ++) (parse src)
            reord  <- first (("reorder: " ++) . show) (reorderModule parsed)
            first (("typecheck: " ++) . show)
              (TC.inferProgram (reorderedAst reord))
      in case result of
           Right (_, [td]) ->
             case TC.tdScheme td of
               Ty.Scheme [(0, Ty.KStar)] _
                 (Ty.CTArr (Ty.CTGen 0) Ty.CREmpty (Ty.CTGen 0)) -> pure ()
               other -> assertFailure ("expected forall a. a -> a, got " ++ show other)
           Right (_, decls) ->
             assertFailure ("expected single f decl, got " ++ show (length decls))
           Left err -> assertFailure err
  ]

programTests :: TestTree
