bodylessSigTests :: TestTree
bodylessSigTests = testGroup "bodyless"
  [ testCase "bodyless top-level sig becomes a visible binding" $
      let src = T.pack "myConst : a -> a\n"
          result = case parse src of
            Right ast -> case reorderModule ast of
              Right rm -> TC.inferProgram (reorderedAst rm)
              Left  es -> Left (TErr.UnknownVar Nothing (T.pack ("setup: " ++ show es)))
            Left err -> Left (TErr.UnknownVar Nothing (T.pack ("setup: " ++ err)))
      in case result of
           Right (env, _) ->
             case TE.lookupVar (T.pack "myConst") env of
               Just s ->
                 case s of
                   Ty.Scheme [(_, Ty.KStar)] _
                     (Ty.CTArr (Ty.CTGen i) Ty.CREmpty (Ty.CTGen j))
                     | i == j -> pure ()
                   other -> assertFailure ("unexpected scheme: " ++ show other)
               Nothing -> assertFailure "myConst missing from env"
           Left e -> assertFailure ("unexpected error: " ++ show e)

  , testCase "UserFile bodyless sig emits exactly one warning" $
      let src = T.pack "myConst : a -> a\n"
          result = case parse src of
            Right ast -> case reorderModule ast of
              Right rm -> TC.inferProgramWith B.initialEnv
                            (SO.UserFile "<test>") (reorderedAst rm)
              Left  es -> error ("setup: " ++ show es)
            Left err -> error ("setup: " ++ err)
      in case result of
           Right (_env, _decls, warnings) ->
             case warnings of
               [TC.BodylessBinding n _] -> n @?= T.pack "myConst"
               other -> assertFailure ("expected one BodylessBinding, got: " ++ show other)
           Left e -> assertFailure ("unexpected error: " ++ show e)

  , testCase "Embedded bodyless sig emits zero warnings" $
      let src = T.pack "myConst : a -> a\n"
          result = case parse src of
            Right ast -> case reorderModule ast of
              Right rm -> TC.inferProgramWith B.initialEnv
                            SO.Embedded (reorderedAst rm)
              Left  es -> error ("setup: " ++ show es)
            Left err -> error ("setup: " ++ err)
      in case result of
           Right (_, _, []) -> pure ()
           Right (_, _, ws) -> assertFailure ("expected no warnings, got: " ++ show ws)
           Left e -> assertFailure ("unexpected error: " ++ show e)

  , testCase "multi-name bodyless sig emits one warning per name" $
      let src = T.pack "a, b, c : U64\n"
          result = case parse src of
            Right ast -> case reorderModule ast of
              Right rm -> TC.inferProgramWith B.initialEnv
                            (SO.UserFile "<test>") (reorderedAst rm)
              Left  es -> error ("setup: " ++ show es)
            Left err -> error ("setup: " ++ err)
      in case result of
           Right (_, _, warnings) ->
             length warnings @?= 3
           Left e -> assertFailure ("unexpected error: " ++ show e)

  , testCase "sig + matching equation: scheme honored via freezeSig path" $
      -- Regression guard: ensure sig+eqn still routes through finalizeGroup
      -- (which applies freezeSig), not through the bodyless-sig path.
      let src = T.pack "myConst : a -> a\nmyConst x = x\n"
          result = case parse src of
            Right ast -> case reorderModule ast of
              Right rm -> TC.inferProgramWith B.initialEnv
                            (SO.UserFile "<test>") (reorderedAst rm)
              Left  es -> error ("setup: " ++ show es)
            Left err -> error ("setup: " ++ err)
      in case result of
           Right (_, _, warnings) -> do
             -- Sig+eqn must NOT emit a bodyless warning:
             warnings @?= []
             -- (Optionally lock in the inferred scheme via the env lookup,
             -- but warnings = [] is the load-bearing assertion for this guard.)
           Left e -> assertFailure ("unexpected error: " ++ show e)
  ]

loaderTests :: TestTree
loaderTests = testGroup "loader"
  [ testCase "loads entry + embedded preludes; topo order is Prelude first" $ do
      res <- Loader.loadProgram "test/loader-fixtures/01-entry-imports-base.wok" []
      case res of
        Right (entryName, modules) -> do
          entryName @?= T.pack "Main"
          -- The embedded preludes are always loaded: Base, Control
          -- (imports Base), Array (imports Base), String,
          -- Bytes, and Borrow. Base must come first (nothing it
          -- depends on); the others follow in some dependency-valid order.
          -- Assert the leading prelude + the full set rather than a brittle
          -- exact permutation of the tail.
          let names = map Loader.lmName modules
          case names of
            (n0 : _) -> n0 @?= T.pack "Base"
            []       -> assertFailure "expected a non-empty module list"
          Data.List.sort names @?=
            Data.List.sort
              [ T.pack "Base", T.pack "Control"
              , T.pack "Array", T.pack "String"
              , T.pack "Bytes", T.pack "Borrow", T.pack "Main" ]
        Left err -> assertFailure ("unexpected error: " ++ show err)

  , testCase "rejects file missing a module header" $ do
      res <- Loader.loadProgram "test/loader-fixtures/02-no-header.wok" []
      case res of
        Left (Loader.LoadNoModuleHeader p) ->
          p @?= "test/loader-fixtures/02-no-header.wok"
        other -> assertFailure ("expected LoadNoModuleHeader, got: " ++ show other)

  , testCase "rejects import of unknown module" $ do
      res <- Loader.loadProgram "test/loader-fixtures/03-unknown-import.wok" []
      case res of
        Left (Loader.LoadImportUnknown importer target) -> do
          importer @?= T.pack "Main"
          target   @?= T.pack "Foo.Bar"
        other -> assertFailure ("expected LoadImportUnknown, got: " ++ show other)

  , testCase "detects two-module import cycle" $ do
      res <- Loader.loadProgram
               "test/loader-fixtures/04-cycle-a.wok"
               ["test/loader-fixtures/04-cycle-b.wok"]
      case res of
        Left (Loader.LoadImportCycle ms) ->
          Data.List.sort ms @?= Data.List.sort [T.pack "A", T.pack "B"]
        other -> assertFailure ("expected LoadImportCycle, got: " ++ show other)

  , testCase "detects self-import cycle" $ do
      res <- Loader.loadProgram "test/loader-fixtures/05-self-import.wok" []
      case res of
        Left (Loader.LoadImportCycle ms) ->
          ms @?= [T.pack "Main"]
        other -> assertFailure ("expected LoadImportCycle, got: " ++ show other)

  , testCase "rejects two files declaring same module name" $ do
      res <- Loader.loadProgram
               "test/loader-fixtures/06-dup-a.wok"
               ["test/loader-fixtures/06-dup-b.wok"]
      case res of
        Left (Loader.LoadDuplicateModule n _ _) -> n @?= T.pack "Dup"
        other -> assertFailure ("expected LoadDuplicateModule, got: " ++ show other)

  , testCase "rejects missing entry file" $ do
      res <- Loader.loadProgram "test/loader-fixtures/does-not-exist.wok" []
      case res of
        Left (Loader.LoadFileMissing p) ->
          p @?= "test/loader-fixtures/does-not-exist.wok"
        other -> assertFailure ("expected LoadFileMissing, got: " ++ show other)

  , testCase "reports non-missing IO errors as LoadFileError (e.g. EISDIR)" $ do
      -- Pointing at a directory triggers an IO error that is NOT
      -- isDoesNotExistError, so we expect the new LoadFileError variant.
      res <- Loader.loadProgram "test/loader-fixtures" []
      case res of
        Left (Loader.LoadFileError p _) ->
          p @?= "test/loader-fixtures"
        other -> assertFailure ("expected LoadFileError, got: " ++ show other)
  ]

-- ---------------------------------------------------------------------
-- Multi-module Loader-tier integration tests
--
-- These exercise the multi-module Loader -> reorder -> typecheck
-- pipeline end-to-end. Together with `loaderTests` (which covers
-- parse/dep-graph errors at the Loader stage), they cover:
--   * cross-module fixity overlay (entry's reordering sees imports'
--     fixity tables);
--   * cross-module fixity REDECLARATION (importer redeclaring an
--     imported fixity surfaces as a pipeline reorder error);
--   * cross-module name conflict (two imports exporting the same
--     name surfaces as an env-merge error);
--   * BodylessBinding warning at pipeline level for UserFile origin;
--   * silent bodyless-sigs for Embedded (Base) origin.
-- ---------------------------------------------------------------------

crossModuleFixityTests :: TestTree
crossModuleFixityTests = testGroup "crossModuleFixity"
  [ testCase "external fixity table influences entry reassociation" $ do
      -- Extra declares `fixity ## left tighter than +` (and `(##) : ...`
      -- so the typechecker can find the operator scheme). Entry uses
      -- `a + b ## c` and Base provides `+`. The cross-module fixity
      -- overlay is what makes the chain unambiguous: without it the
      -- reorder pass cannot relate `+` and `##` and surfaces
      -- `IncomparableOps`. Thus "typecheck succeeds" is the load-bearing
      -- assertion for cross-module-fixity threading.
      res <- Loader.loadProgram
               "test/loader-fixtures/07-cross-fixity-entry.wok"
               ["test/loader-fixtures/07-cross-fixity-extra.wok"]
      case res of
        Right (entryName, ms) -> do
          entryName @?= T.pack "Main"
          case Pipeline.typecheckProgram entryName ms of
            Right (decls, _) ->
              assertBool "expected 'result' in entry's decls"
                         (any ((== T.pack "result") . TC.tdName) decls)
            Left s -> assertFailure ("expected pipeline success, got: " ++ s)
        Left lerr -> assertFailure ("expected loader success, got: " ++ show lerr)

  , testCase "entry redeclaring an imported fixity surfaces as conflict" $ do
      -- Base declares `fixity + left`. Entry tries to redeclare it.
      -- `reorderModuleWith` overlays the imported fixity table with the
      -- module's own table; the collision yields a RedeclaredOp error
      -- mentioning `+`.
      res <- Loader.loadProgram
               "test/loader-fixtures/08-cross-fixity-redecl.wok"
               []
      case res of
        Right (entryName, ms) ->
          case Pipeline.typecheckProgram entryName ms of
            Left s | "+" `Data.List.isInfixOf` s -> pure ()
            other -> assertFailure
                       ("expected fixity conflict mentioning '+', got: "
                        ++ show other)
        Left lerr -> assertFailure ("loader unexpectedly failed: " ++ show lerr)
  ]

crossModuleNameConflictTests :: TestTree
crossModuleNameConflictTests = testGroup "crossModuleNameConflict"
  [ testCase "two imports exporting same name fail with env conflict" $ do
      -- A defines `foo : U64`, B defines `foo : U64` (SAME type, different
      -- body). The entry imports both; the env overlay in
      -- `Pipeline.typecheckProgram` detects two distinct ORIGINS for `foo`
      -- (modules A and B) and returns a Left containing "env merge in ".
      --
      -- This exercises binding provenance: env-merge flags a shared var
      -- when its defining modules differ, even when the stored `Scheme`s are
      -- identical. (Same-origin overlaps -- a diamond re-export -- still
      -- merge silently.) Byte-identical re-exported builtin tycons also
      -- merge silently; the surfaced collision is the cross-module `foo`.
      res <- Loader.loadProgram
               "test/loader-fixtures/09-name-conflict-entry.wok"
               [ "test/loader-fixtures/09-name-conflict-a.wok"
               , "test/loader-fixtures/09-name-conflict-b.wok"
               ]
      case res of
        Right (entryName, ms) ->
          case Pipeline.typecheckProgram entryName ms of
            Left s | "env merge in " `Data.List.isInfixOf` s -> pure ()
            other -> assertFailure
                       ("expected an env-merge conflict, got: "
                        ++ show other)
        Left lerr -> assertFailure ("loader unexpectedly failed: " ++ show lerr)
  ]

-- A cross-module instantiation of an inferred row-polymorphic scheme must not
-- panic. RowParamDef exports `mkbox : forall (e : row). Box e` (unsigned, so its
-- scheme is built by freezeQuantify). Bug #5 was that freezeQuantify froze the
-- generalizable row var to its raw global uniq as an UNRECORDED CTGen, leaving it
-- out of the stored scheme's quantifier list; the importing module then
-- instantiated it and crashed `instantiate: dangling CTGen`. Whole-program
-- elaboration succeeding (a Right) is the load-bearing assertion.
crossModuleRowParamTests :: TestTree
crossModuleRowParamTests = testGroup "crossModuleRowParam"
  [ testCase "cross-module use of an inferred row-poly scheme does not dangle" $ do
      res <- Loader.loadProgram
               "test/loader-fixtures/12-row-param-use.wok"
               [ "test/loader-fixtures/12-row-param-def.wok" ]
      case res of
        Right (entryName, ms) ->
          case Pipeline.elaborateProgram entryName ms of
            Right _  -> pure ()
            Left s   -> assertFailure ("expected pipeline success, got: " ++ s)
        Left lerr -> assertFailure ("loader unexpectedly failed: " ++ show lerr)
  ]

bodylessUserWarningTests :: TestTree
bodylessUserWarningTests = testGroup "bodylessUser"
  [ testCase "user-file bodyless sig produces BodylessBinding warning at pipeline level" $ do
      res <- Loader.loadProgram "test/loader-fixtures/10-bodyless-user.wok" []
      case res of
        Right (entryName, ms) ->
          case Pipeline.typecheckProgram entryName ms of
            Right (_, warnings) ->
              case warnings of
                [TC.BodylessBinding n _] -> n @?= T.pack "foo"
                other -> assertFailure
                           ("expected 1 BodylessBinding foo, got: " ++ show other)
            Left s -> assertFailure ("pipeline unexpectedly failed: " ++ s)
        Left lerr -> assertFailure ("loader unexpectedly failed: " ++ show lerr)

  , testCase "silentBodyless: Base bodyless sigs produce zero pipeline warnings" $ do
      -- Base has many bodyless sigs ((+), (-), (*), ...). They MUST
      -- be silent because the loader marks Base with Origin=Embedded.
      -- The entry has no bodyless sigs of its own. Expect zero warnings.
      res <- Loader.loadProgram "test/loader-fixtures/11-bodyless-silent-prelude.wok" []
      case res of
        Right (entryName, ms) ->
          case Pipeline.typecheckProgram entryName ms of
            Right (_, []) -> pure ()
            Right (_, ws) -> assertFailure ("expected no warnings, got: " ++ show ws)
            Left s -> assertFailure ("pipeline unexpectedly failed: " ++ s)
        Left lerr -> assertFailure ("loader unexpectedly failed: " ++ show lerr)
  ]

-- ---------------------------------------------------------------------
-- Row unification tests (Leijen 2005 scoped-label algorithm)
-- ---------------------------------------------------------------------

-- | Run a TC action in a fresh ST context, returning Either TypeError a.
runUnify :: (forall s. TM.TC s a) -> Either TErr.TypeError a
runUnify action = TM.runTC_ TE.emptyEnv action

-- | Build a row from a list of (label, type) pairs.
mkRow :: [(T.Text, Ty.Type s)] -> Ty.Row s
mkRow = foldr (\(l, t) acc -> Ty.RowExtend l t acc) Ty.RowEmpty

rowUnifyTests :: TestTree
rowUnifyTests = testGroup "RowUnify"
  [ testCase "RowEmpty ~ RowEmpty unifies" $
      let result = runUnify $
            U.unifyRow Nothing Ty.RowEmpty Ty.RowEmpty
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "{x:U64} ~ {x:U64} unifies" $
      let result = runUnify $ do
            let r1 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty
                r2 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty
            U.unifyRow Nothing r1 r2
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "{x:U64} ~ {x:Bool} fails with RowMismatch or Mismatch" $
      let result = runUnify $ do
            let r1 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty
                r2 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcBool []) Ty.RowEmpty
            U.unifyRow Nothing r1 r2
      in case result of
           Left (TErr.Mismatch _ _ _) -> pure ()
           Left (TErr.RowMismatch _ _ _) -> pure ()
           _ -> assertFailure ("expected Mismatch or RowMismatch, got: " ++ show result)

  , testCase "{x:U64, y:Bool} ~ {y:Bool, x:U64} unifies (permutation)" $
      -- Leijen permits reordering: same labels, different extension order.
      let result = runUnify $ do
            let r1 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 [])
                       (Ty.RowExtend (T.pack "y") (Ty.TCon Ty.TcBool []) Ty.RowEmpty)
                r2 = Ty.RowExtend (T.pack "y") (Ty.TCon Ty.TcBool [])
                       (Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty)
            U.unifyRow Nothing r1 r2
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "row variable extends to add label" $
      -- Given fresh RowVar r, unify (RowVar r) with {x : U64}. After: r is bound.
      let result = runUnify $ do
            rVar <- TM.freshRVar
            let row = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty
            U.unifyRow Nothing rVar row
            -- Force rVar to check it was bound
            forced <- U.force rVar
            U.freeze forced
      in case result of
           Right cr -> assertBool "expected CRExtend x ..." $
             case cr of
               Ty.CRExtend lbl (Ty.CTCon Ty.TcU64 []) _ -> lbl == T.pack "x"
               _ -> False
           Left e -> assertFailure ("expected Right, got: " ++ show e)

  , testCase "row variable unifies with RowEmpty" $
      let result = runUnify $ do
            rVar <- TM.freshRVar
            U.unifyRow Nothing rVar Ty.RowEmpty
            forced <- U.force rVar
            U.freeze forced
      in case result of
           Right Ty.CREmpty -> pure ()
           Right cr -> assertFailure ("expected CREmpty, got: " ++ show cr)
           Left e -> assertFailure ("expected Right, got: " ++ show e)

  , testCase "rewriteRowStrict refuses RowVar" $
      -- rewriteRowStrict should throw UnknownField when given a RowVar.
      let result :: Either TErr.TypeError (Ty.CType, Ty.CRow)
          result = runUnify $ do
            rVar <- TM.freshRVar
            (ty, rest) <- U.rewriteRowStrict Nothing (T.pack "x") rVar
            ct <- U.freeze ty
            cr <- U.freeze rest
            pure (ct, cr)
      in case result of
           Left (TErr.UnknownField _ _ lbl) -> lbl @?= T.pack "x"
           _ -> assertFailure ("expected UnknownField, got: " ++ show result)

  , testCase "rewriteRow on RowVar allocates fresh field and tail" $
      -- rewriteRow should succeed on RowVar by allocating fresh vars.
      let result = runUnify $ do
            rVar <- TM.freshRVar
            (ty, _tail) <- U.rewriteRow Nothing (T.pack "x") rVar
            U.freeze ty
      in case result of
           Right (Ty.CTGen _) -> pure ()
           Right ct -> assertFailure ("expected CTGen (fresh), got: " ++ show ct)
           Left e -> assertFailure ("expected Right, got: " ++ show e)

  , testCase "scoped labels: {x:U64, x:Bool} stays distinct" $
      -- Two same-name labels coexist. Unifying a row with itself should succeed.
      let result = runUnify $ do
            let row = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 [])
                        (Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcBool []) Ty.RowEmpty)
            U.unifyRow Nothing row row
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "scoped labels: rewriteRow returns outermost, inner survives in tail" $
      -- rewriteRow on {x:U64, x:Bool} for label "x" must return the OUTERMOST
      -- field (U64) and leave the inner {x:Bool} intact in the tail.
      let result = runUnify $ do
            let row = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 [])
                        (Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcBool []) Ty.RowEmpty)
            (ty, rest) <- U.rewriteRow Nothing (T.pack "x") row
            ct  <- U.freeze ty
            cr  <- U.freeze rest
            pure (ct, cr)
      in case result of
           Right (Ty.CTCon Ty.TcU64 [], Ty.CRExtend lbl (Ty.CTCon Ty.TcBool []) Ty.CREmpty)
             | lbl == T.pack "x" -> pure ()
           Right other ->
             assertFailure ("expected (CTCon TcU64 [], CRExtend x (CTCon TcBool []) CREmpty), got: " ++ show other)
           Left e -> assertFailure ("expected Right, got: " ++ show e)

  , testCase "occurs check: r := {x : r} is rejected" $
      -- Setup: fresh row var r (a TVar of kind KEffect). Attempt to bind r to
      -- RowExtend "x" someType r. After the kinded-Ty merge rows are ordinary
      -- TVars, but a self-cycle on a KEffect var still reports RowOccursCheck
      -- (distinct from OccursCheck for KStar type-var cycles).
      let result = runUnify $ do
            rVar <- TM.freshRVar
            case rVar of
              Ty.TVar ref -> do
                let cyclicRow = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) rVar
                U.unifyVar Nothing ref cyclicRow
              _ -> error "expected TVar from freshRVar"
      in case result of
           Left (TErr.RowOccursCheck _ _ _) -> pure ()
           _ -> assertFailure ("expected RowOccursCheck (cycle), got: " ++ show result)

  , testCase "TRecord tag mismatch fails with NominalMismatch" $
      let result = runUnify $ do
            let r1 = Ty.TRecord (T.pack "Point") Ty.RowEmpty
                r2 = Ty.TRecord (T.pack "Line") Ty.RowEmpty
            U.unify Nothing r1 r2
      in case result of
           Left (TErr.NominalMismatch _ t1 t2) -> do
             t1 @?= T.pack "Point"
             t2 @?= T.pack "Line"
           _ -> assertFailure ("expected NominalMismatch, got: " ++ show result)

  , testCase "TRecord same tag with matching rows unifies" $
      let result = runUnify $ do
            let row = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) Ty.RowEmpty
                r1 = Ty.TRecord (T.pack "Point") row
                r2 = Ty.TRecord (T.pack "Point") row
            U.unify Nothing r1 r2
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "RowVar ~ RowVar (same ref) unifies trivially" $
      let result = runUnify $ do
            rVar <- TM.freshRVar
            U.unifyRow Nothing rVar rVar
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "two distinct RowVars are unified by binding one to the other" $
      let result = runUnify $ do
            r1 <- TM.freshRVar
            r2 <- TM.freshRVar
            U.unifyRow Nothing r1 r2
            -- Both should now freeze to the same row gen (CTGen, KEffect)
            cr1 <- U.freeze r1
            cr2 <- U.freeze r2
            pure (cr1, cr2)
      in case result of
           Right (cr1, cr2) -> cr1 @?= cr2
           Left e -> assertFailure ("expected Right, got: " ++ show e)

  -- Kinded representation (Slice A): behaviours the surface language can't yet
  -- exercise. Pure unit tests against the merged kinded `Type s`.

  , testCase "kinded representation: shared-structure rows unify via merged unify" $
      -- Post-merge, rows are ordinary KEffect Types and unifyRow is an alias of
      -- unify. {x:U64 | r1} ~ {x:U64 | r2} (fresh row tails) must still unify
      -- via the inlined Leijen algorithm.
      let result = runUnify $ do
            r1 <- TM.freshRVar
            r2 <- TM.freshRVar
            let row1 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) r1
                row2 = Ty.RowExtend (T.pack "x") (Ty.TCon Ty.TcU64 []) r2
            U.unify Nothing row1 row2
      in case result of
           Right () -> pure ()
           Left e -> assertFailure ("expected Right (), got: " ++ show e)

  , testCase "kinded representation: KStar var vs KEffect row is KindMismatch" $
      -- Unifying a KStar meta var with a row (kind KEffect) must throw.
      let result = runUnify $ do
            a <- TM.freshTVar Ty.KStar
            U.unify Nothing a Ty.RowEmpty
      in case result of
           Left (TErr.KindMismatch _ _ _) -> pure ()
           _ -> assertFailure ("expected KindMismatch, got: " ++ show result)

  , testCase "kinded representation: freeze round-trips a row-bearing arrow" $
      -- freeze must handle a row in the arrow's effect slot, producing the
      -- closed row constructors CRExtend/CREmpty.
      let result = runUnify $
            U.freeze
              (Ty.TArr (Ty.TCon Ty.TcUnit [])
                 (Ty.RowExtend (T.pack "Log") (Ty.TCon Ty.TcUnit []) Ty.RowEmpty)
                 (Ty.TCon Ty.TcUnit []))
      in case result of
           Right (Ty.CTArr _ (Ty.CRExtend lbl _ Ty.CREmpty) _)
             | lbl == T.pack "Log" -> pure ()
           Right ct -> assertFailure ("expected CTArr _ (CRExtend Log _ CREmpty) _, got: " ++ show ct)
           Left e -> assertFailure ("expected Right, got: " ++ show e)
  ]

-- ---------------------------------------------------------------------
-- Record data-decl processing tests (Task 4)
-- ---------------------------------------------------------------------

-- | Parse a source fragment containing only data decls (no module header)
-- and run processDataDecls against the given environment.
runDataDeclsIn :: TE.Env -> Text -> Either TErr.TypeError TE.Env
runDataDeclsIn env src =
  case parse (T.pack "module Main\n" `T.append` src) of
    Left e -> Left (TErr.UnsupportedFeature Nothing (T.pack ("parse: " ++ e)))
    Right ast ->
      let decls = case ast of Abs.Module ds -> ds
      in TM.runTC_ env (I.processDataDecls env decls)

-- | Convenience wrapper using the minimal builtins env (no Base).
runDataDecls :: Text -> Either TErr.TypeError TE.Env
runDataDecls = runDataDeclsIn B.initialEnv

recordDeclTests :: TestTree
recordDeclTests = testGroup "RecordDecl"
  [ testCase "register named-form Point in envRecordCons and envTyCons" $ do
      case runDataDecls (T.pack "data Point = Point { x : U64, y : U64 }") of
        Left e  -> assertFailure ("unexpected error: " ++ show e)
        Right env -> do
          case TE.lookupRecordCon (T.pack "Point") env of
            Nothing   -> assertFailure "Point not in envRecordCons"
            Just info -> do
              TE.rcTag info @?= T.pack "Point"
              length (TE.rcFields info) @?= 2
          case TE.lookupTyCon (T.pack "Point") env of
            Nothing -> assertFailure "Point not in envTyCons"
            Just _  -> pure ()
          -- Must NOT be in the positional (curried) constructor namespace.
          TE.lookupCon (T.pack "Point") env @?= Nothing

  , testCase "elided form is equivalent to named form" $ do
      case runDataDecls (T.pack "data Point = { x : U64, y : U64 }") of
        Left e  -> assertFailure ("unexpected error: " ++ show e)
        Right env ->
          case TE.lookupRecordCon (T.pack "Point") env of
            Nothing   -> assertFailure "Point not in envRecordCons"
            Just info -> do
              -- Tag must be filled in from the data-type name.
              TE.rcTag info @?= T.pack "Point"
              length (TE.rcFields info) @?= 2

  , testCase "elision in multi-constructor decl is rejected" $ do
      case runDataDecls (T.pack "data Shape = { x : U64 } | Square { side : U64 }") of
        Left _  -> pure ()   -- any error is acceptable
        Right _ -> assertFailure "expected an error for elision in multi-con decl"

  , testCase "same field name across two constructors is rejected" $ do
      case runDataDecls (T.pack "data X = A { x : U64 } | B { x : U64 }") of
        Left _  -> pure ()
        Right _ -> assertFailure "expected an error for duplicate field name"

  , testCase "mixed positional and record constructors in one decl" $ do
      baseEnv <- stdBaseExtendedEnv
      -- Use a distinct name to avoid clashing with Base's Result/Ok/Err.
      let src = T.pack "data Outcome a e = Good a | Bad { code : U64, flag : Bool }"
      case runDataDeclsIn baseEnv src of
        Left e  -> assertFailure ("unexpected error: " ++ show e)
        Right env -> do
          -- Good is positional (curried scheme) only.
          case TE.lookupCon (T.pack "Good") env of
            Nothing -> assertFailure "Good not in envCons"
            Just _  -> pure ()
          TE.lookupRecordCon (T.pack "Good") env @?= Nothing
          -- Bad is record-only.
          case TE.lookupRecordCon (T.pack "Bad") env of
            Nothing -> assertFailure "Bad not in envRecordCons"
            Just _  -> pure ()
          TE.lookupCon (T.pack "Bad") env @?= Nothing

  , testCase "polymorphic record constructor carries type params" $ do
      case runDataDecls (T.pack "data Container a = Container { value : a }") of
        Left e  -> assertFailure ("unexpected error: " ++ show e)
        Right env ->
          case TE.lookupRecordCon (T.pack "Container") env of
            Nothing   -> assertFailure "Container not in envRecordCons"
            Just info -> do
              length (TE.rcFields info) @?= 1
              length (TE.rcParams info) @?= 1
  ]

-- ---------------------------------------------------------------------
-- Type-level + elaboration tests (Task 8)
-- ---------------------------------------------------------------------

-- | Build an env with Point defined and run translateSig on the given type.
-- Returns the Scheme or the TypeError.
translateSigInPointEnv :: Abs.Type -> Either TErr.TypeError Ty.Scheme
translateSigInPointEnv ty =
  case runDataDecls (T.pack "data Point = Point { x : U64, y : U64 }") of
    Left e -> Left e
    Right env ->
      TM.runTC_ env (I.translateSig env ty)

-- | Helper: build an Abs.Type for `Point` (a TCon).
mkPointTy :: Abs.Type
mkPointTy = Abs.TCon (Abs.MPName (Abs.ConId ((0,0), T.pack "Point")))

-- | Helper: build a VarSym.
mkVarSym :: String -> Abs.VarSym
mkVarSym s = Abs.VarSym ((0,0), T.pack s)

-- | Helper: build a RCAnon from a list of (name, type) pairs.
mkRCAnon :: [(String, Abs.Type)] -> Abs.RowContrib
mkRCAnon fields =
  Abs.RCAnon [ Abs.RFType (Abs.VarId ((0,0), T.pack n)) ty | (n, ty) <- fields ]

-- | Helper: U64 type.
mkU64 :: Abs.Type
mkU64 = Abs.TCon (Abs.MPName (Abs.ConId ((0,0), T.pack "U64")))

-- | Helper: build RCVar for a named row variable.
mkRCVar :: String -> Abs.RowContrib
mkRCVar s = Abs.RCVar (Abs.VarId ((0,0), T.pack s))

-- | Extract the fields from a CTRecord's CRow into a list of label names.
cRowLabels :: Ty.CRow -> [T.Text]
cRowLabels Ty.CREmpty = []
cRowLabels (Ty.CRExtend l _ rest) = l : cRowLabels rest
cRowLabels (Ty.CTGen _) = []
cRowLabels _ = []  -- non-row CType: no labels (cannot occur in a row position)

typeLevelExtTests :: TestTree
typeLevelExtTests = testGroup "TypeLevelExtension"
  [ testCase "concrete extension translates to TRecord with merged fields" $ do
      -- Point + { score : U64 } should yield CTRecord "Point" with x, y, score
      let ty = Abs.TExtend mkPointTy (mkVarSym "+")
                 (mkRCAnon [("score", mkU64)])
      case translateSigInPointEnv ty of
        Left e -> assertFailure ("unexpected error: " ++ show e)
        Right (Ty.Scheme _ _ (Ty.CTRecord tag row)) -> do
          tag @?= T.pack "Point"
          let labels = cRowLabels row
          -- score is prepended (outermost), x and y come from Point's fields
          length labels @?= 3
          case labels of
            (l0 : _) -> l0 @?= T.pack "score"
            []       -> assertFailure "expected non-empty labels"
          T.pack "x" `elem` labels @? "expected x in row"
          T.pack "y" `elem` labels @? "expected y in row"
        Right other -> assertFailure ("expected CTRecord scheme, got: " ++ show other)

  , testCase "row variable extension translates to CTRecord with row-gen (CTGen) tail" $ do
      -- Point + row r should yield CTRecord "Point" (x, y, r)
      let ty = Abs.TExtend mkPointTy (mkVarSym "+") (mkRCVar "r")
      case translateSigInPointEnv ty of
        Left e -> assertFailure ("unexpected error: " ++ show e)
        Right (Ty.Scheme qs _ (Ty.CTRecord tag row)) -> do
          tag @?= T.pack "Point"
          -- The row should end with a row-gen (CTGen, KEffect) for the row variable
          let hasRowVar (Ty.CTGen _) = True
              hasRowVar Ty.CREmpty   = False
              hasRowVar (Ty.CRExtend _ _ rest) = hasRowVar rest
              hasRowVar _            = False
          hasRowVar row @? "expected row variable (CTGen) in row"
          -- There should be exactly one KEffect quantifier for the row var
          let rowQs = [ i | (i, Ty.KEffect) <- qs ]
          length rowQs @?= 1
        Right other -> assertFailure ("expected CTRecord scheme, got: " ++ show other)

  , testCase "two uses of same row var share one row-gen (CTGen) slot" $ do
      -- (Point + row r) -> (Point + row r): both `r` should map to same index
      let extTy = Abs.TExtend mkPointTy (mkVarSym "+") (mkRCVar "r")
          ty    = Abs.TFun extTy extTy
      case translateSigInPointEnv ty of
        Left e -> assertFailure ("unexpected error: " ++ show e)
        Right (Ty.Scheme qs _ _) -> do
          -- Exactly one KEffect slot (one row var `r`)
          let rowQs = [ i | (i, Ty.KEffect) <- qs ]
          length rowQs @?= 1

  , testCase "non-plus operator rejected with NonPlusTypeOp" $ do
      -- Point - { score : U64 } should fail with NonPlusTypeOp
      let ty = Abs.TExtend mkPointTy (mkVarSym "-")
                 (mkRCAnon [("score", mkU64)])
      case translateSigInPointEnv ty of
        Left (TErr.NonPlusTypeOp _ sym) -> sym @?= T.pack "-"
        Left other -> assertFailure ("expected NonPlusTypeOp, got: " ++ show other)
        Right _ -> assertFailure "expected error, got Right"

  , testCase "plain TCon for record type produces CTRecord" $ do
      -- Just referencing `Point` in a sig should produce CTRecord "Point" {...}
      case translateSigInPointEnv mkPointTy of
        Left e -> assertFailure ("unexpected error: " ++ show e)
        Right (Ty.Scheme _ _ (Ty.CTRecord tag row)) -> do
          tag @?= T.pack "Point"
          let labels = cRowLabels row
          length labels @?= 2
          T.pack "x" `elem` labels @? "expected x"
          T.pack "y" `elem` labels @? "expected y"
        Right other -> assertFailure ("expected CTRecord, got: " ++ show other)

  , testCase "chained extension Point + { score } + { color } works" $ do
      -- (Point + { score : U64 }) + { color : U64 }
      let step1 = Abs.TExtend mkPointTy (mkVarSym "+")
                    (mkRCAnon [("score", mkU64)])
          ty    = Abs.TExtend step1 (mkVarSym "+")
                    (mkRCAnon [("color", mkU64)])
      case translateSigInPointEnv ty of
        Left e -> assertFailure ("unexpected error: " ++ show e)
        Right (Ty.Scheme _ _ (Ty.CTRecord tag row)) -> do
          tag @?= T.pack "Point"
          let labels = cRowLabels row
          length labels @?= 4
          T.pack "x"     `elem` labels @? "expected x"
          T.pack "y"     `elem` labels @? "expected y"
          T.pack "score" `elem` labels @? "expected score"
          T.pack "color" `elem` labels @? "expected color"
        Right other -> assertFailure ("expected CTRecord, got: " ++ show other)

  , testCase "anonymous record { x : U64 } outside + is a parse error" $ do
      -- The grammar's RowContrib is only reachable from TExtend.
      -- A standalone `{ x : U64 }` in a type position does NOT parse as a type.
      -- Verify by checking that the source doesn't produce a valid parse
      -- when { ... } appears as a top-level type.
      -- (This is a grammar-level guarantee, not an elaborator one.)
      -- We use parseSrc via parse on a sig that would need that form.
      -- `f : { x : U64 } -> U64` should fail to parse.
      let src = T.pack "module Main\nf : { x : U64 } -> U64\nf r = 0\n"
      case parse src of
        Left _  -> pure ()  -- expected: parse fails
        Right _ -> assertFailure "expected parse failure for standalone { } in type position"

  , testCase "bare row var without row keyword is a parse error" $ do
      -- `f : Point + r -> U64` where r has no `row` prefix should fail to parse.
      -- The grammar requires `row VarId` for RCVar.
      let src = T.pack "module Main\ndata Point = Point { x : U64, y : U64 }\nf : Point + r -> U64\nf p = 0\n"
      case parse src of
        Left _  -> pure ()  -- expected: parse fails
        Right _ -> assertFailure "expected parse failure for bare row var without `row` keyword"
  ]

-- ---------------------------------------------------------------------
-- Record construction inference tests (Task 5)
-- ---------------------------------------------------------------------

-- | Preamble that defines Point for record construction tests.
pointDecl :: T.Text
pointDecl = T.pack "data Point = Point { x : U64, y : U64 }\n"

-- | Run the full typecheck pipeline on the given source (no module header
-- needed; inferProgram accepts raw decl lists). Returns Right scheme list
-- or Left error.
runTypecheckSrc :: T.Text -> Either String [(T.Text, Ty.Scheme)]
runTypecheckSrc src =
  case parse src of
    Left e -> Left ("parse: " ++ e)
    Right ast ->
      case reorderModule ast of
        Left es -> Left ("reorder: " ++ show es)
        Right rm ->
          case TC.inferProgram (reorderedAst rm) of
            Left e -> Left ("typecheck: " ++ show e)
            Right (_, decls) -> Right [ (TC.tdName d, TC.tdScheme d) | d <- decls ]

-- | Expect a source to typecheck without error.
expectOK :: T.Text -> Assertion
expectOK src =
  case runTypecheckSrc src of
    Right _ -> pure ()
    Left e  -> assertFailure ("expected success but got: " ++ e)

-- | Expect a source to fail typechecking (any error).
expectError :: T.Text -> Assertion
expectError src =
  case runTypecheckSrc src of
    Left _  -> pure ()
    Right _ -> assertFailure "expected typecheck error but got success"

-- | Expect a source to fail typechecking with an error message containing
-- the given substring.
expectErrorContaining :: T.Text -> String -> Assertion
expectErrorContaining src substr =
  case runTypecheckSrc src of
    Left e  -> assertBool
                 ("expected error containing " ++ show substr ++ " but got: " ++ e)
                 (substr `Data.List.isInfixOf` e)
    Right _ -> assertFailure ("expected error containing " ++ show substr ++ " but got success")

recordConstructionTests :: TestTree
recordConstructionTests = testGroup "RecordConstruction"
  [ testCase "closed Point infers as TRecord Point" $ do
      let src = pointDecl <> T.pack "p = Point { x = 1, y = 2 }\n"
      case runTypecheckSrc src of
        Left e -> assertFailure ("unexpected error: " ++ e)
        Right decls ->
          case lookup (T.pack "p") decls of
            Nothing -> assertFailure "p not in decls"
            Just (Ty.Scheme [] _ (Ty.CTRecord tag row)) -> do
              tag @?= T.pack "Point"
              let labels = cRowLabels row
              Data.List.sort labels @?= Data.List.sort [T.pack "x", T.pack "y"]
            Just other -> assertFailure ("unexpected scheme: " ++ show other)

  , testCase "extras without sig produce UnknownField error" $ do
      let src = pointDecl <> T.pack "p = Point { x = 1, y = 2, z = 3 }\n"
      expectError src

  , testCase "spread-only copies Point" $ do
      let src = pointDecl
             <> T.pack "origin = Point { x = 0, y = 0 }\n"
             <> T.pack "copy = Point { ..origin }\n"
      expectOK src

  , testCase "spread with same-type override typechecks" $ do
      let src = pointDecl
             <> T.pack "origin = Point { x = 0, y = 0 }\n"
             <> T.pack "moved = Point { ..origin, x = 99 }\n"
      expectOK src

  , testCase "spread with type-mismatch override errors" $ do
      let src = pointDecl
             <> T.pack "origin = Point { x = 0, y = 0 }\n"
             <> T.pack "broken = Point { ..origin, x = \"hi\" }\n"
      expectError src

  , testCase "record constructor not a value" $
      expectErrorContaining
        (pointDecl <> T.pack "f = Point\n")
        "RecordConstructorNotAValue"

  , testCase "record constructor positional application errors" $
      expectErrorContaining
        (pointDecl <> T.pack "z = Point 1\n")
        "RecordConstructorNeedsBraces"

  , testCase "positional constructor stays first-class" $ do
      -- Define a positional constructor in the same source and verify it
      -- can be used as a first-class value (no RecordConstructorNotAValue).
      let src = T.pack "data Wrap = Wrap U64\nf = Wrap\n"
      case runTypecheckSrc src of
        Left e  -> assertFailure ("expected success, got: " ++ e)
        Right _ -> pure ()

  , testCase "missing field errors" $ do
      let src = pointDecl <> T.pack "p = Point { x = 1 }\n"
      expectError src

  , testCase "nominal tag mismatch in spread errors" $ do
      -- Line must define two different record types and try to spread wrong one.
      -- Since we only have Point in this test, verify that spreading a
      -- non-record-type expression produces NotARecord.
      let src = pointDecl
             <> T.pack "bad = Point { ..1 }\n"
      expectError src

  , testCase "sig with extension allows extras" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "named : Point + { score : U64 }"
            , "named = Point { x = 0, y = 0, score = 99 }"
            ]
      expectOK src

  , testCase "sig with extension rejects unrelated extras" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "named : Point + { score : U64 }"
            , "named = Point { x = 0, y = 0, score = 99, color = 1 }"
            ]
      expectError src

  , testCase "sig with extension spread plus addition" $ do
      -- withScore p s = Point { ..p, score = s }
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "withScore : Point -> U64 -> Point + { score : U64 }"
            , "withScore p s = Point { ..p, score = s }"
            ]
      expectOK src

  , testCase "sig with extension spread addition rejects unrelated field" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "withScore : Point -> U64 -> Point + { score : U64 }"
            , "withScore p s = Point { ..p, score = s, color = 1 }"
            ]
      expectError src
  ]

fieldAccessTests :: TestTree
fieldAccessTests = testGroup "FieldAccess"
  [ testCase "p.x on Point returns U64" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "getX : Point -> U64"
        , "getX p = p.x"
        ]

  , testCase "p.score on Point + concrete extension" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "getScore : Point + { score : U64 } -> U64"
        , "getScore p = p.score"
        ]

  , testCase "p.x on Point + row r (declared field accessible)" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "getX : Point + row r -> U64"
        , "getX p = p.x"
        ]

  , testCase "p.score on Point + row r errors with UnknownField" $
      expectErrorContaining
        ( T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "getScore : Point + row r -> U64"
            , "getScore p = p.score"
            ]
        )
        "UnknownField"

  , testCase "p.x on non-record errors with NotARecord" $
      expectErrorContaining
        ( T.unlines
            [ "f : U64 -> U64"
            , "f p = p.x"
            ]
        )
        "NotARecord"
  ]

recordPatternTests :: TestTree
recordPatternTests = testGroup "RecordPattern"
  [ testCase "strict pattern matches Point" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "describe : Point -> U64"
        , "describe p = case p of"
        , "  Point { x = a, y = b } -> a"
        ]

  , testCase "strict pattern bindings have correct types" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "getX : Point -> U64"
        , "getX p = case p of"
        , "  Point { x = a, y = _ } -> a"
        , "getY : Point -> U64"
        , "getY p = case p of"
        , "  Point { x = _, y = b } -> b"
        ]

  , testCase "strict pattern rejects extended scrutinee" $
      expectError $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "f : Point + { z : U64 } -> U64"
        , "f p = case p of"
        , "  Point { x = a, y = b } -> a"
        ]

  , testCase "open pattern matches Point + extension" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "g : Point + row r -> U64"
        , "g p = case p of"
        , "  Point { x = a, y = b, .. } -> a"
        ]

  , testCase "open pattern with subset of declared fields" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "getX : Point + row r -> U64"
        , "getX p = case p of"
        , "  Point { x = a, .. } -> a"
        ]

  , testCase "pure wild pattern matches any Point-tagged record" $
      expectOK $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "h : Point + row r -> U64"
        , "h p = case p of"
        , "  Point { .. } -> 0"
        ]

  , testCase "named row-tail capture is deferred to v2" $
      expectErrorContaining
        ( T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "k p = case p of"
            , "  Point { x = a, ..rest } -> a"
            ]
        )
        "NamedRowTailCaptureDeferred"

  , testCase "strict pattern with unknown field errors" $
      expectError $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "f p = case p of"
        , "  Point { x = a, y = b, z = c } -> a"
        ]

  , testCase "strict pattern with missing field errors" $
      expectError $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "f p = case p of"
        , "  Point { x = a } -> a"
        ]
  ]

-- | Run typechecking and return (decls, warnings) or fail with a message.
-- Used by RowShadow tests.
expectOKWithWarnings :: T.Text -> IO ([(T.Text, Ty.Scheme)], [TC.Warning])
expectOKWithWarnings src =
  case parse src of
    Left e -> assertFailure ("parse error: " ++ e) >> undefined
    Right ast ->
      case reorderModule ast of
        Left es -> assertFailure ("reorder error: " ++ show es) >> undefined
        Right rm ->
          case TC.inferProgramWith B.initialEnv (SO.UserFile "<test>") (reorderedAst rm) of
            Left e -> assertFailure ("typecheck error: " ++ show e) >> undefined
            Right (_, decls, ws) ->
              pure ([ (TC.tdName d, TC.tdScheme d) | d <- decls ], ws)

-- ---------------------------------------------------------------------------
-- Row-shadow warning tests
-- ---------------------------------------------------------------------------

rowShadowTests :: TestTree
rowShadowTests = testGroup "RowShadow"
  [ testCase "no warning when no label collision" $ do
      -- g1 called on Point + { color : U64 }: no 'tag' in caller's row
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "g1 : Point + row r -> Point + row r + { tag : U64 }"
            , "g1 p = Point { ..p, tag = 0 }"
            , "clean : Point + { color : U64 }"
            , "clean = Point { x = 0, y = 0, color = 1 }"
            , "result = g1 clean"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let shadows = [ w | w@(TC.RowShadow _ lbl _ _) <- warnings, lbl == T.pack "tag" ]
      length shadows @?= 0

  , testCase "warning emitted when caller's row has same label as function's addition" $ do
      -- g1 called on Point + { tag : U64 }: 'tag' collides with the added 'tag : U64'
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "g1 : Point + row r -> Point + row r + { tag : U64 }"
            , "g1 p = Point { ..p, tag = 0 }"
            , "weird : Point + { tag : U64 }"
            , "weird = Point { x = 0, y = 0, tag = 42 }"
            , "result = g1 weird"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let shadows = [ w | w@(TC.RowShadow _ lbl _ _) <- warnings, lbl == T.pack "tag" ]
      -- Exactly one, not duplicated: the same shadow is reachable through more
      -- than one unification, but runTC dedups identical warnings (#3).
      assertEqual ("expected exactly one RowShadow on 'tag', got warnings: " ++ show warnings)
                  1 (length shadows)

  , testCase "collision program still typechecks (warning is informational)" $ do
      -- Same as above: must not fail with a TypeError
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "g1 : Point + row r -> Point + row r + { tag : U64 }"
            , "g1 p = Point { ..p, tag = 0 }"
            , "weird : Point + { tag : U64 }"
            , "weird = Point { x = 0, y = 0, tag = 42 }"
            , "result = g1 weird"
            ]
      expectOK src

  , testCase "warning identifies the colliding label" $ do
      let src = T.unlines
            [ "data Box = Box { val : U64 }"
            , "addScore : Box + row r -> Box + row r + { score : U64 }"
            , "addScore b = Box { ..b, score = 0 }"
            , "already : Box + { score : U64 }"
            , "already = Box { val = 1, score = 99 }"
            , "result = addScore already"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let shadows = [ lbl | TC.RowShadow _ lbl _ _ <- warnings ]
      assertBool ("expected 'score' in shadow labels, got: " ++ show shadows)
                 (T.pack "score" `elem` shadows)
  ]

-- ---------------------------------------------------------------------------
-- Forgotten-resume lint tests
-- ---------------------------------------------------------------------------

forgottenResumeTests :: TestTree
forgottenResumeTests = testGroup "ForgottenResume"
  [ testCase "named unreferenced binder on returning op warns" $ do
      -- `once State.get k -> 0`: get : s is a returning op and k is never used.
      let src = T.unlines
            [ "module Main", "import Base"
            , "effect State s = { get : s }"
            , "prog : () -> U64 with State U64"
            , "prog u = State.get"
            , "main : U64"
            , "main ="
            , "  with { once State.get k -> 0"
            , "         ; return v -> v }"
            , "  prog ()" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.ForgottenResume _ _ _ <- ws ] @?= 1

  , testCase "wildcard binder suppresses" $ do
      -- `once State.get _ -> 0`: explicit intentional discard; no warning.
      let src = T.unlines
            [ "module Main", "import Base"
            , "effect State s = { get : s }"
            , "prog : () -> U64 with State U64"
            , "prog u = State.get"
            , "main : U64"
            , "main ="
            , "  with { once State.get _ -> 0"
            , "         ; return v -> v }"
            , "  prog ()" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.ForgottenResume _ _ _ <- ws ] @?= 0

  , testCase "Never-result op is exempt" $ do
      -- `throw : U64 -> Never`: a non-returning op never resumes, so a
      -- named-but-unused binder is fine. (Avoid Bool/if: the `import Base`
      -- line is parsed but silently dropped by the inferProgramWith path, so
      -- Base names are NOT in scope -- only B.initialEnv primitives are.)
      let src = T.unlines
            [ "module Main", "import Base"
            , "effect Exn = { throw : U64 -> Never }"
            , "risky : () -> U64 with Exn"
            , "risky u = Exn.throw 1"
            , "main : U64"
            , "main ="
            , "  with { once Exn.throw code k -> 0"
            , "         ; return v -> v }"
            , "  risky ()" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.ForgottenResume _ _ _ <- ws ] @?= 0

  , testCase "referenced binder does not warn" $ do
      -- `once State.get k -> k 0`: the continuation is used, so the arm resumes.
      let src = T.unlines
            [ "module Main", "import Base"
            , "effect State s = { get : s }"
            , "prog : () -> U64 with State U64"
            , "prog u = State.get"
            , "main : U64"
            , "main ="
            , "  with { once State.get k -> k 0"
            , "         ; return v -> v }"
            , "  prog ()" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.ForgottenResume _ _ _ <- ws ] @?= 0
  ]

-- ---------------------------------------------------------------------------
-- Pattern coverage tests
-- ---------------------------------------------------------------------------

patternCoverageTests :: TestTree
patternCoverageTests = testGroup "PatternCoverage"
  [ testCase "strict-only arms over open scrutinee warns" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "f : Point + row r -> U64"
            , "f p = case p of"
            , "  Point { x = a, y = b } -> a"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let nonExh = [ w | w@(TC.NonExhaustiveRecordPattern _ tag) <- warnings
                       , tag == T.pack "Point" ]
      length nonExh @?= 1

  , testCase "open arm satisfies coverage" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "g : Point + row r -> U64"
            , "g p = case p of"
            , "  Point { x = a, y = b, .. } -> a"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let nonExh = [ w | w@(TC.NonExhaustiveRecordPattern _ _) <- warnings ]
      length nonExh @?= 0

  , testCase "strict arm on closed scrutinee — no warning" $ do
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "h : Point -> U64"
            , "h p = case p of"
            , "  Point { x = a, y = b } -> a"
            ]
      (_, warnings) <- expectOKWithWarnings src
      let nonExh = [ w | w@(TC.NonExhaustiveRecordPattern _ _) <- warnings ]
      length nonExh @?= 0

  , testCase "strict arm stays reachable (no unreachable warning)" $
      -- Verify that strict arms over an open scrutinee do NOT cause an
      -- unreachable-arm warning; they remain reachable when r := RowEmpty.
      -- The only warning emitted is NonExhaustiveRecordPattern (tested above).
      let src = T.unlines
            [ "data Point = Point { x : U64, y : U64 }"
            , "f : Point + row r -> U64"
            , "f p = case p of"
            , "  Point { x = a, y = b } -> a"
            ]
          -- The codebase has no UnreachableArm variant; this predicate is
          -- intentionally False for all current Warning constructors,
          -- locking in the design decision that strict arms stay reachable.
          isUnreachable :: TC.Warning -> Bool
          isUnreachable _ = False
      in do
        (_, warnings) <- expectOKWithWarnings src
        let unreachable = filter isUnreachable warnings
        length unreachable @?= 0
  ]

-- ---------------------------------------------------------------------------
-- Match warning tests (non-exhaustive heads + redundant clauses)
-- ---------------------------------------------------------------------------

matchWarningTests :: TestTree
matchWarningTests = testGroup "MatchWarnings"
  [ testCase "partial single clause warns non-exhaustive" $ do
      let src = T.unlines
            [ "module Main", "import Base"
            , "safeHead : [U64] -> U64"
            , "safeHead (x :: xs) = x" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.NonExhaustiveMatch _ n <- ws, n == T.pack "safeHead" ] @?= 1

  , testCase "total function: no non-exhaustive warning" $ do
      let src = T.unlines
            [ "module Main", "import Base"
            , "isNil : [U64] -> U64"
            , "isNil []        = 1"
            , "isNil (x :: xs) = 0" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.NonExhaustiveMatch _ _ <- ws ] @?= 0

  , testCase "shadowed clause warns redundant" $ do
      let src = T.unlines
            [ "module Main", "import Base"
            , "f : U64 -> U64"
            , "f x = x"
            , "f 0 = 0" ]
      (_, ws) <- expectOKWithWarnings src
      length [ () | TErr.RedundantClause _ n _ <- ws, n == T.pack "f" ] @?= 1

  , testCase "as-pattern head: coverage unchanged (still non-exhaustive)" $ do
      -- A single-clause head that only matches `Some` is non-exhaustive whether
      -- or not it carries an as-pattern; an as-pattern covers exactly what its
      -- inner pattern covers, so the diagnostic must be identical.
      let withAs = T.unlines
            [ "module Main", "import Base"
            , "data Opt a = Non | Som a"
            , "f : Opt U64 -> U64"
            , "f (Som x) as w = x" ]
          without = T.unlines
            [ "module Main", "import Base"
            , "data Opt a = Non | Som a"
            , "f : Opt U64 -> U64"
            , "f (Som x) = x" ]
      (_, wsAs)  <- expectOKWithWarnings withAs
      (_, wsNot) <- expectOKWithWarnings without
      let count ws = length [ () | TErr.NonExhaustiveMatch _ n <- ws, n == T.pack "f" ]
      count wsAs  @?= 1
      count wsAs  @?= count wsNot
  ]

-- ---------------------------------------------------------------------------
-- BlockLayout tests
-- ---------------------------------------------------------------------------

-- | Assert that the given source parses without errors.
shouldParse :: Text -> Assertion
shouldParse src =
  case parse src of
    Right _   -> pure ()
    Left  err -> assertFailure ("expected successful parse, got: " ++ err)

blockLayoutTests :: TestTree
blockLayoutTests = testGroup "BlockLayout"
  [ testCase "inline decl unchanged" $
      shouldParse "data Point = Point { x : U64, y : U64 }\n"

  , testCase "block decl (named)" $
      shouldParse $ T.unlines
        [ "data Point = Point {"
        , "  x : U64"
        , "  y : U64"
        , "}"
        ]

  , testCase "block decl (elided)" $
      shouldParse $ T.unlines
        [ "data Point = {"
        , "  x : U64"
        , "  y : U64"
        , "}"
        ]

  , testCase "mixed comma + newline in decl" $
      shouldParse $ T.unlines
        [ "data Big = Big {"
        , "  name : String, age : U64"
        , "  score : U64"
        , "}"
        ]

  , testCase "trailing comma + newline in value: no double comma" $
      -- Regression: a literal `,` at end of one field's line must NOT
      -- get a second virtual `,` inserted before the next field on the
      -- following line.
      shouldParse $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "p = Point {"
        , "  x = 1,"
        , "  y = 2"
        , "}"
        ]

  , testCase "trailing comma on every field (incl. last) + newlines" $
      shouldParse $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "p = Point {"
        , "  x = 1,"
        , "  y = 2,"
        , "}"
        ]

  , testCase "inline value construction unchanged" $
      shouldParse "data Point = Point { x : U64, y : U64 }\np = Point { x = 1, y = 2 }\n"

  , testCase "block value construction" $
      shouldParse $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "p = Point {"
        , "  x = 1"
        , "  y = 2"
        , "}"
        ]

  , testCase "block pattern" $
      shouldParse $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "f p = case p of"
        , "  Point {"
        , "    x = a"
        , "    y = b"
        , "  } -> a"
        ]

  , testCase "nested record literals" $
      shouldParse $ T.unlines
        [ "data Inner = Inner { a : U64, b : U64 }"
        , "data Outer = Outer { inner : Inner, tag : U64 }"
        , "o = Outer {"
        , "  inner = Inner {"
        , "    a = 1"
        , "    b = 2"
        , "  }"
        , "  tag = 99"
        , "}"
        ]

  , testCase "block open-row pattern" $
      shouldParse $ T.unlines
        [ "data Point = Point { x : U64, y : U64 }"
        , "f p = case p of"
        , "  Point {"
        , "    x = a"
        , "    .."
        , "  } -> a"
        ]
  ]

irNameTests :: TestTree
irNameTests = testGroup "IRName"
  [ testCase "same unique, different hint => equal" $
      let (a, b) = runFresh $ do
            u <- freshUnique
            pure (Name (T.pack "x") u, Name (T.pack "y") u)
      in a @?= b
  , testCase "different unique => unequal" $
      let (a, b) = runFresh $ do
            x <- freshName (T.pack "x")
            y <- freshName (T.pack "x")
            pure (x, y)
      in assertBool "distinct" (a /= b)
  , testCase "supply is monotonic and deterministic" $
      let us = runFresh (mapM (const freshUnique) [1 :: Int .. 3])
      in us @?= [Unique 0, Unique 1, Unique 2]
  ]

anfTests :: TestTree
anfTests = testGroup "Anf"
  [ testCase "render: f x = let r = x in case r of { 0 -> 1; _ -> r }" $
      let cm = runFresh $ do
            nf <- freshName (T.pack "f")
            nx <- freshName (T.pack "x")
            nr <- freshName (T.pack "r")
            let xBndr = Anf.Binder nx Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])
                rBndr = Anf.Binder nr Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])
                body  = Anf.Let rBndr
                          (Anf.RAtom (Anf.AVar nx))
                          (Anf.Case (Anf.AVar nr)
                            [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 1)))
                            , Anf.AltDefault (Anf.Ret (Anf.AVar nr))
                            ])
            pure $ Anf.CoreModule
              [ Anf.TopBind nf [xBndr] body ]
          expected = T.intercalate (T.pack "\n")
            [ T.pack "f x ="
            , T.pack "  let r = x"
            , T.pack "  case r of"
            , T.pack "    0 -> 1"
            , T.pack "    _ -> r"
            ]
      in Anf.prettyModule cm @?= expected

  , testCase "collision disambiguation: two distinct x binders get x.N suffixes" $
      let (rendered0, rendered1) = runFresh $ do
            nx0 <- freshName (T.pack "x")
            nx1 <- freshName (T.pack "x")
            let b0 = Anf.Binder nx0 Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])
                -- let x.N0 = x.N1 in x.N0
                e  = Anf.Let b0 (Anf.RAtom (Anf.AVar nx1)) (Anf.Ret (Anf.AVar nx0))
                txt = Anf.prettyExpr e
                -- txt = "let X = Y\nZ"
                -- first word after "let " is b0's rendering
                -- last word of first line (after "= ") is nx1's rendering
                ws  = T.words txt
                -- ws = ["let", rb0, "=", rb1, ...]
                rb0w = case drop 1 ws of { (w:_) -> w; [] -> T.pack "" }
                rb1w = case drop 3 ws of { (w:_) -> w; [] -> T.pack "" }
            pure (rb0w, rb1w)
      in do
        assertBool "both start with x" $
          T.pack "x" `T.isPrefixOf` rendered0 && T.pack "x" `T.isPrefixOf` rendered1
        assertBool "rendered names differ" (rendered0 /= rendered1)

  , testCase "prettyModuleTyped: binder renders as name : type" $
      let cm = runFresh $ do
            nf <- freshName (T.pack "f")
            nx <- freshName (T.pack "x")
            let xBndr = Anf.Binder nx Anf.Unrestricted (Ty.CTCon Ty.TcU64 [])
                body  = Anf.Ret (Anf.AVar nx)
            pure $ Anf.CoreModule
              [ Anf.TopBind nf [xBndr] body ]
          rendered = Anf.prettyModuleTyped cm
      in assertBool ("expected 'x : U64' in: " ++ T.unpack rendered)
                    (T.isInfixOf (T.pack "x : U64") rendered)

  , testCase "freeVarsExpr includes op-arm free vars" $ do
      let x   = Name (T.pack "x") (Unique 9001)
          k   = Name (T.pack "k") (Unique 9002)
          v   = Name (T.pack "v") (Unique 9003)
          u64 = Ty.CTCon Ty.TcU64 []
          h = Handler (Binder v Unrestricted u64, Ret (AVar v))
                      [ OpArm (T.pack "E") (T.pack "op") [] (Binder k Unrestricted u64)
                              (Ret (AVar x)) ]
                      Nothing Nothing Nothing
          e = Handle (Ret (ALit (LInt 0))) h
      Set.member (Unique 9001) (freeVarsExpr e) @?= True
      Set.member (Unique 9002) (freeVarsExpr e) @?= False
      Set.member (Unique 9003) (freeVarsExpr e) @?= False
  ]

interpValueTests :: TestTree
interpValueTests = testGroup "InterpValue"
  [ testCase "render int" $
      IV.renderValue (IV.VLit (Anf.LInt 42)) @?= T.pack "42"
  , testCase "render unit" $
      IV.renderValue (IV.VLit Anf.LUnit) @?= T.pack "()"
  , testCase "render True" $
      IV.renderValue (IV.VCon (T.pack "True") []) @?= T.pack "True"
  , testCase "render empty list" $
      IV.renderValue (IV.VCon (T.pack "Nil") []) @?= T.pack "[]"
  , testCase "render cons list [1, 2]" $
      let lst = IV.VCon (T.pack "Cons")
                  [ IV.VLit (Anf.LInt 1)
                  , IV.VCon (T.pack "Cons") [IV.VLit (Anf.LInt 2), IV.VCon (T.pack "Nil") []] ]
      in IV.renderValue lst @?= T.pack "[1, 2]"
  , testCase "render tuple (1, 2)" $
      IV.renderValue (IV.VCon (T.pack "Tuple2") [IV.VLit (Anf.LInt 1), IV.VLit (Anf.LInt 2)])
        @?= T.pack "(1, 2)"
  , testCase "render saturated constructor" $
      IV.renderValue (IV.VCon (T.pack "Some") [IV.VLit (Anf.LInt 7)])
        @?= T.pack "Some(7)"
  , testCase "resolveAtom: local binding wins by Unique" $
      let n  = runFresh (freshName (T.pack "x"))
          sc = IV.Scope (Map.fromList [(Name.nameUniq n, IV.VLit (Anf.LInt 9))]) Map.empty
      in case IV.resolveAtom Map.empty sc (Anf.AVar n) of
           Right v -> IV.renderValue v @?= T.pack "9"
           Left e  -> assertFailure (show e)
  , testCase "missing binder colliding with a prim errors UnboundVar" $
      -- A binder named "+" whose Unique is NOT in the runtime env. With the old
      -- by-hint fallback this silently returned the + prim (the latent bug #12);
      -- without it this is a loud UnboundVar. The prim table DOES carry "+", so
      -- the only thing distinguishing UnboundVar from VPrim is the absence of the
      -- fallback.
      let missing = Name (T.pack "+") (Unique 999999)
      in case IV.resolveAtom IP.primTable (IV.Scope Map.empty Map.empty)
                (Anf.AVar missing) of
           Left (IV.UnboundVar _) -> pure ()
           other -> assertFailure
                      ("missing binder must be UnboundVar, got " <> show other)
  , testCase "resolveAtom: unbound errors" $
      let n = runFresh (freshName (T.pack "ghost"))
      in IV.resolveAtom Map.empty IV.emptyScope (Anf.AVar n)
           @?= Left (IV.UnboundVar (T.pack "ghost"))
  , testCase "APrim resolves via the prim table" $
      case IV.resolveAtom IP.primTable (IV.Scope Map.empty Map.empty)
             (Anf.APrim (T.pack "Base", T.pack "+")) of
        Right (IV.VPrim _) -> pure ()
        other -> assertFailure ("APrim + should resolve to a VPrim, got " <> show other)
  ]

-- ---------------------------------------------------------------------------
-- Interp prim tests

-- | Invoke a reference interpreter prim by @(module, name)@ with fully-applied args.
runPrim :: (Text, Text) -> [IV.Value] -> Either IV.RuntimeError IV.PrimResult
runPrim key args =
  case Map.lookup key IP.primTable of
    Nothing -> Left (IV.UnboundVar (snd key))
    Just p  -> IV.primFn p args

li :: Integer -> IV.Value
li = IV.VLit . Anf.LInt

interpPrimTests :: TestTree
interpPrimTests = testGroup "InterpPrim"
  [ testCase "table has exactly the bodyless operators" $
      Data.List.sort (Map.keys IP.primTable)
        @?= Data.List.sort
              ( map (T.pack "Base",)
                  ["+","-","*","/","div","mod","eqU64","eqU32","u32","&&","||","++","$","eqString","eqBytes"]
              ++ map (T.pack "Control",)
                  ["__coro_susp","__coro_unwrap","__coro_resume","__coro_done"
                  ,"__coro_cancel","__coerce","__drive_conc"
                  ,"__cont_cell_new","__cont_store","__cont_take"]
              ++ map (T.pack "Array",)
                  ["new","fromList","toList","index","length","set","resize"]
              ++ map (T.pack "String",)
                  ["length","index","byteLength","byteAt","append"
                  ,"indexOfFromRaw","hash","editDistance","slice","byteSlice"
                  ,"decodeCharAt","charWidthAt","singleton"]
              ++ map (T.pack "Bytes",)
                  ["fromList","toList","length","index","fromBytes","toBytes"
                  ,"__ffi_demo_copy","__ffi_demo_adopt"]
              ++ map (T.pack "Borrow",)
                  ["length","byteAt","slice","memchr","copy","__borrow_demo"]
              )
  , testCase "addition" $
      case runPrim (T.pack "Base", T.pack "+") [li 2, li 3] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "5"
        other -> assertFailure (show2 other)
  , testCase "equality true" $
      case runPrim (T.pack "Base", T.pack "eqU64") [li 4, li 4] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "True"
        other -> assertFailure (show2 other)
  , testCase "equality false" $
      case runPrim (T.pack "Base", T.pack "eqU64") [li 4, li 5] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "False"
        other -> assertFailure (show2 other)
  , testCase "u32 equality" $
      case runPrim (T.pack "Base", T.pack "eqU32") [li 4, li 4] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "True"
        other -> assertFailure (show2 other)
  , testCase "u32 conversion is identity on the value" $
      case runPrim (T.pack "Base", T.pack "u32") [li 7] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "7"
        other -> assertFailure (show2 other)
  , testCase "boolean and" $
      case runPrim (T.pack "Base", T.pack "&&") [IV.VCon (T.pack "True") [], IV.VCon (T.pack "False") []] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "False"
        other -> assertFailure (show2 other)
  , testCase "division (non-negative)" $
      case runPrim (T.pack "Base", T.pack "/") [li 7, li 2] of
        Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "3"
        other -> assertFailure (show2 other)
  , testCase "division by zero is a PrimError" $
      case runPrim (T.pack "Base", T.pack "div") [li 1, li 0] of
        Left (IV.PrimError _) -> pure ()
        other -> assertFailure (show2 other)
  , testCase "list append" $
      let mkList = foldr (\x acc -> IV.VCon (T.pack "Cons") [li x, acc]) (IV.VCon (T.pack "Nil") [])
      in case runPrim (T.pack "Base", T.pack "++") [mkList [1,2], mkList [3]] of
           Right (IV.PRDone v) -> IV.renderValue v @?= T.pack "[1, 2, 3]"
           other -> assertFailure (show2 other)
  , testCase "dollar requests an application" $
      case runPrim (T.pack "Base", T.pack "$") [IV.VCon (T.pack "K") [], li 1] of
        Right (IV.PRApply (IV.VCon t []) [arg]) -> do
          t @?= T.pack "K"
          IV.renderValue arg @?= T.pack "1"
        other -> assertFailure (show2 other)
  -- ------------------------------------------------------------------
  -- Overflow regression (Finding 1), reference side: index/new/set/resize
  -- with index >= 2^63 must raise PrimError on the reference interpreter,
  -- symmetrically with the RC interpreter. The pre-fix behaviour was
  -- fromInteger wrapping to a negative Int, making bounds checks pass.
  -- ------------------------------------------------------------------
  , testCase "Ref overflow: index 2^63 raises PrimError (out of range)" $
      let arr = IV.VCon (T.pack "Array") [li 0, li 1, li 2]
          idx = li (2^(63 :: Int))
      in case runPrim (T.pack "Array", T.pack "index") [arr, idx] of
           Left (IV.PrimError m)
             | T.pack "out of range" `T.isInfixOf` m -> pure ()
           Left e  -> assertFailure ("Ref overflow index: expected PrimError out-of-range, got: " <> show e)
           Right _ -> assertFailure "Ref overflow index: prim succeeded unexpectedly with 2^63"
  , testCase "Ref overflow: new size 2^63 raises PrimError (out of range)" $
      let kv = li (2^(63 :: Int))
      in case runPrim (T.pack "Array", T.pack "new") [kv, li 0] of
           Left (IV.PrimError m)
             | T.pack "out of range" `T.isInfixOf` m -> pure ()
           Left e  -> assertFailure ("Ref overflow new: expected PrimError out-of-range, got: " <> show e)
           Right _ -> assertFailure "Ref overflow new: prim succeeded unexpectedly with 2^63"
  , testCase "Ref overflow: set index 2^63 raises PrimError (out of range)" $
      let arr = IV.VCon (T.pack "Array") [li 0, li 1, li 2]
          idx = li (2^(63 :: Int))
      in case runPrim (T.pack "Array", T.pack "set") [arr, idx, li 99] of
           Left (IV.PrimError m)
             | T.pack "out of range" `T.isInfixOf` m -> pure ()
           Left e  -> assertFailure ("Ref overflow set: expected PrimError out-of-range, got: " <> show e)
           Right _ -> assertFailure "Ref overflow set: prim succeeded unexpectedly with 2^63"
  , testCase "Ref overflow: resize size 2^63 raises PrimError (out of range)" $
      let arr = IV.VCon (T.pack "Array") [li 0, li 1]
          mv  = li (2^(63 :: Int))
      in case runPrim (T.pack "Array", T.pack "resize") [arr, mv, li 0] of
           Left (IV.PrimError m)
             | T.pack "out of range" `T.isInfixOf` m -> pure ()
           Left e  -> assertFailure ("Ref overflow resize: expected PrimError out-of-range, got: " <> show e)
           Right _ -> assertFailure "Ref overflow resize: prim succeeded unexpectedly with 2^63"
  ]
  where
    show2 (Left e)  = "Left " <> show e
    show2 (Right _) = "Right <prim-result>"

-- ---------------------------------------------------------------------------
-- UTF-8 validation

utf8Tests :: TestTree
utf8Tests = testGroup "Wok.Interp.Utf8.validateUtf8"
  [ it "accepts valid UTF-8 (incl. empty)" $ do
      Utf8.validateUtf8 (BS.pack [])                     `shouldBe` True
      Utf8.validateUtf8 (BS.pack [0x41])                 `shouldBe` True
      Utf8.validateUtf8 (BS.pack [0xC3,0xA9])            `shouldBe` True   -- é
      Utf8.validateUtf8 (BS.pack [0xE2,0x82,0xAC])       `shouldBe` True   -- €
      Utf8.validateUtf8 (BS.pack [0xF0,0x9F,0x98,0x80])  `shouldBe` True   -- emoji
  , it "rejects the four ill-formedness classes + truncated" $ do
      Utf8.validateUtf8 (BS.pack [0xC0,0x80])            `shouldBe` False  -- overlong
      Utf8.validateUtf8 (BS.pack [0x80])                 `shouldBe` False  -- lone continuation
      Utf8.validateUtf8 (BS.pack [0xF7,0xBF,0xBF,0xBF])  `shouldBe` False  -- > U+10FFFF
      Utf8.validateUtf8 (BS.pack [0xED,0xA0,0x80])       `shouldBe` False  -- lone surrogate
      Utf8.validateUtf8 (BS.pack [0xE2,0x82])            `shouldBe` False  -- truncated
  ]
  where
    it = testCase
    shouldBe = (@?=)

-- ---------------------------------------------------------------------------
-- CAF (0-arity top-level bind) evaluation

interpCafTests :: TestTree
interpCafTests = testGroup "InterpCaf"
  [ testCase "0-arity top-level constant is forced and shared" $
      -- module: answer = 42 ; main = answer
      let answer = Anf.TopBind (mkCafName "answer" 0) []
                     (Anf.Ret (Anf.ALit (Anf.LInt 42)))
          mainB  = Anf.TopBind (mkCafName "main" 1) []
                     (Anf.Ret (Anf.AVar (mkCafName "answer" 0)))
          cm = Anf.CoreModule [answer, mainB]
      in Interp.runModule cm @?= Right (IV.VLit (Anf.LInt 42))
  ]
  where
    mkCafName hint u = Name (T.pack hint) (Unique u)

-- ---------------------------------------------------------------------------
-- CEK machine tests

interpMachineTests :: TestTree
interpMachineTests = testGroup "InterpMachine"
  [ testCase "Ret literal" $
      assertEval Map.empty (Anf.Ret (Anf.ALit (Anf.LInt 7))) (T.pack "7")

  , testCase "let then ret" $
      let (e, _) = runFresh $ do
            x <- freshName (T.pack "x")
            let b = Anf.Binder x Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])
            pure (Anf.Let b (Anf.RAtom (Anf.ALit (Anf.LInt 3))) (Anf.Ret (Anf.AVar x)), x)
      in assertEval Map.empty e (T.pack "3")

  , testCase "primitive application 2 + 3" $
      let e = runFresh $ do
            t <- freshName (T.pack "t")
            let b = Anf.Binder t Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])
            pure (Anf.Let b (Anf.RApp (primAtom (T.pack "+")) [Anf.ALit (Anf.LInt 2), Anf.ALit (Anf.LInt 3)])
                            (Anf.Ret (Anf.AVar t)))
      in assertEval Map.empty e (T.pack "5")

  , testCase "closure: identity applied to 9" $
      -- let id = \x -> x ; let r = id 9 ; ret r
      let e = runFresh $ do
            x  <- freshName (T.pack "x")
            i  <- freshName (T.pack "id")
            r  <- freshName (T.pack "r")
            let lam = Anf.RLam [Anf.Binder x Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] (Anf.Ret (Anf.AVar x))
            pure $ Anf.Let (Anf.Binder i Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) lam
                     (Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                              (Anf.RApp (Anf.AVar i) [Anf.ALit (Anf.LInt 9)])
                              (Anf.Ret (Anf.AVar r)))
      in assertEval Map.empty e (T.pack "9")

  , testCase "currying: (\\x y -> x) applied to one arg is a value, then applied again" $
      -- let k = \x y -> x ; let k1 = k 1 ; let r = k1 2 ; ret r
      let e = runFresh $ do
            x <- freshName (T.pack "x"); y <- freshName (T.pack "y")
            k <- freshName (T.pack "k"); k1 <- freshName (T.pack "k1"); r <- freshName (T.pack "r")
            let lam = Anf.RLam [Anf.Binder x Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Binder y Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])]
                               (Anf.Ret (Anf.AVar x))
            pure $ Anf.Let (Anf.Binder k Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) lam
                     (Anf.Let (Anf.Binder k1 Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) (Anf.RApp (Anf.AVar k) [Anf.ALit (Anf.LInt 1)])
                       (Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) (Anf.RApp (Anf.AVar k1) [Anf.ALit (Anf.LInt 2)])
                         (Anf.Ret (Anf.AVar r))))
      in assertEval Map.empty e (T.pack "1")

  , testCase "over-application: a closure returning a closure, applied to extra args" $
      -- let f = \x -> (let g = \y -> x in ret g)   -- f : a -> (b -> a)
      -- let r = f 1 2                                -- 2 args, f takes 1 -> over-application
      -- ret r                                        -- inner closure applied to 2, returns x = 1
      let e = runFresh $ do
            x <- freshName (T.pack "x"); y <- freshName (T.pack "y")
            g <- freshName (T.pack "g"); f <- freshName (T.pack "f"); r <- freshName (T.pack "r")
            let inner = Anf.RLam [Anf.Binder y Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] (Anf.Ret (Anf.AVar x))
                outerBody = Anf.Let (Anf.Binder g Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) inner (Anf.Ret (Anf.AVar g))
                outer = Anf.RLam [Anf.Binder x Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] outerBody
            pure $ Anf.Let (Anf.Binder f Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) outer
                     (Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                              (Anf.RApp (Anf.AVar f) [Anf.ALit (Anf.LInt 1), Anf.ALit (Anf.LInt 2)])
                              (Anf.Ret (Anf.AVar r)))
      in assertEval Map.empty e (T.pack "1")

  , testCase "case on literal selects the matching arm" $
      let e = Anf.Case (Anf.ALit (Anf.LInt 0))
                [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 100)))
                , Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 200))) ]
      in assertEval Map.empty e (T.pack "100")

  , testCase "case on constructor binds fields" $
      -- case (Pair 1 2) of Pair a b -> b
      let e = runFresh $ do
            a <- freshName (T.pack "a"); b <- freshName (T.pack "b"); p <- freshName (T.pack "p")
            pure $ Anf.Let (Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                     (Anf.RCon (T.pack "Pair") [Anf.ALit (Anf.LInt 1), Anf.ALit (Anf.LInt 2)])
                     (Anf.Case (Anf.AVar p)
                       [ Anf.AltCon (T.pack "Pair")
                           [Anf.Binder a Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Binder b Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])]
                           (Anf.Ret (Anf.AVar b)) ])
      in assertEval Map.empty e (T.pack "2")

  , testCase "record projection returns each field by label (order-independent invariant)" $
      -- Invariant: projecting label L on a record returns exactly the atom bound
      -- to L, for EVERY label, regardless of field insertion order. Fields are
      -- declared in non-sorted order with distinct values, so a position-based
      -- (rather than label-based) projection bug returns the wrong number and is
      -- caught. Missing label must be a clean BadProjection, not a crash.
      let proj label = runFresh $ do
            r <- freshName (T.pack "r"); p <- freshName (T.pack "p")
            pure $ Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                     (Anf.RRecord (T.pack "T")
                        [ (T.pack "c", Anf.ALit (Anf.LInt 30))
                        , (T.pack "a", Anf.ALit (Anf.LInt 10))
                        , (T.pack "b", Anf.ALit (Anf.LInt 20)) ])
                     (Anf.Let (Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.RProj label (Anf.AVar r))
                        (Anf.Ret (Anf.AVar p)))
          check label expected =
            case IM.evalExprWith Map.empty (proj label) of
              Right v -> IV.renderValue v @?= expected
              Left e  -> assertFailure ("projection " <> T.unpack label <> " failed: " <> show e)
      in do
        check (T.pack "a") (T.pack "10")
        check (T.pack "b") (T.pack "20")
        check (T.pack "c") (T.pack "30")
        case IM.evalExprWith Map.empty (proj (T.pack "zzz")) of
          Left (IV.BadProjection l) -> l @?= T.pack "zzz"
          other -> assertFailure ("expected BadProjection, got " <> show other)

  , testCase "letrec: countdown sums to 0 via recursion (even/odd style)" $
      -- letrec loop n = case n of { 0 -> 0 ; _ -> loop (n-1) } ; ret (loop 3)
      let e = runFresh $ do
            loop <- freshName (T.pack "loop"); n <- freshName (T.pack "n")
            t    <- freshName (T.pack "t")
            r    <- freshName (T.pack "r")
            let body = Anf.Case (Anf.AVar n)
                  [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 0)))
                  , Anf.AltDefault
                      (Anf.Let (Anf.Binder t Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.RApp (primAtom (T.pack "-")) [Anf.AVar n, Anf.ALit (Anf.LInt 1)])
                        (Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                          (Anf.RApp (Anf.AVar loop) [Anf.AVar t])
                          (Anf.Ret (Anf.AVar r)))) ]
            top <- freshName (T.pack "out")
            pure $ Anf.LetRec [(Anf.Binder loop Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), [Anf.Binder n Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])], body)]
                     (Anf.Let (Anf.Binder top Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                       (Anf.RApp (Anf.AVar loop) [Anf.ALit (Anf.LInt 3)])
                       (Anf.Ret (Anf.AVar top)))
      in assertEval Map.empty e (T.pack "0")

  , testCase "letjoin/jump merges branches" $
      -- join j(r) = ret r ; case 1 of { 0 -> jump j 10 ; _ -> jump j 20 }
      let e = runFresh $ do
            j <- freshJoin; r <- freshName (T.pack "r")
            pure $ Anf.LetJoin j [Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] (Anf.Ret (Anf.AVar r))
                     (Anf.Case (Anf.ALit (Anf.LInt 1))
                       [ Anf.AltLit (Anf.LInt 0) (Anf.Jump j [Anf.ALit (Anf.LInt 10)])
                       , Anf.AltDefault (Anf.Jump j [Anf.ALit (Anf.LInt 20)]) ])
      in assertEval Map.empty e (T.pack "20")

  , testCase "non-exhaustive case errors" $
      let e = Anf.Case (Anf.ALit (Anf.LInt 5)) [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 1))) ]
      in case IM.evalExprWith Map.empty e of
           Left (IV.NonExhaustiveCase _) -> pure ()
           other -> assertFailure ("expected NonExhaustiveCase, got " <> show other)
  ]
  where
    assertEval env e expected =
      case IM.evalExprWith env e of
        Right v -> IV.renderValue v @?= expected
        Left err -> assertFailure ("eval failed: " <> show err)

-- ---------------------------------------------------------------------------
-- interpEffectTests

interpEffectTests :: TestTree
interpEffectTests = testGroup "InterpEffect"
  [ testCase "auto-resume: handler returns the resumed downstream value" $
      -- handle ( let a = Ask.ask () in ret a ) of
      --   Ask.ask(p, resume) -> let res = resume 41 in ret res
      --   return v -> v
      let e = runFresh $ do
            a <- freshName (T.pack "a")
            p <- freshName (T.pack "p"); resume <- freshName (T.pack "resume")
            res <- freshName (T.pack "res"); v <- freshName (T.pack "v")
            let comp = Anf.Let (Anf.Binder a Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                         (Anf.ROp Nothing (T.pack "Ask") (T.pack "ask") [Anf.ALit Anf.LUnit])
                         (Anf.Ret (Anf.AVar a))
                arm = Anf.OpArm (T.pack "Ask") (T.pack "ask")
                        [Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])]
                        (Anf.Binder resume Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.Let (Anf.Binder res Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                          (Anf.RApp (Anf.AVar resume) [Anf.ALit (Anf.LInt 41)])
                          (Anf.Ret (Anf.AVar res)))
                hdlr = Anf.Handler (Anf.Binder v Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Ret (Anf.AVar v)) [arm] Nothing Nothing Nothing
            pure (Anf.Handle comp hdlr)
      in assertEval Map.empty e (T.pack "41")

  , testCase "return arm transforms a normally-completing computation" $
      -- handle (ret 5) of return v -> let r = v + 100 ; ret r   (no ops)
      let e = runFresh $ do
            v <- freshName (T.pack "v"); r <- freshName (T.pack "r")
            let retArm = Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                           (Anf.RApp (primAtom (T.pack "+")) [Anf.AVar v, Anf.ALit (Anf.LInt 100)])
                           (Anf.Ret (Anf.AVar r))
                hdlr = Anf.Handler (Anf.Binder v Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), retArm) [] Nothing Nothing Nothing
            pure (Anf.Handle (Anf.Ret (Anf.ALit (Anf.LInt 5))) hdlr)
      in assertEval Map.empty e (T.pack "105")

  , testCase "abort: arm ignores resume and returns its own value" $
      -- handle ( let a = Abort.abort () in ret a ) of
      --   Abort.abort(p, resume) -> ret 7      (resume unused)
      --   return v -> v
      let e = runFresh $ do
            a <- freshName (T.pack "a"); p <- freshName (T.pack "p")
            resume <- freshName (T.pack "resume"); v <- freshName (T.pack "v")
            let comp = Anf.Let (Anf.Binder a Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                         (Anf.ROp Nothing (T.pack "Abort") (T.pack "abort") [Anf.ALit Anf.LUnit])
                         (Anf.Ret (Anf.AVar a))
                arm = Anf.OpArm (T.pack "Abort") (T.pack "abort")
                        [Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])]
                        (Anf.Binder resume Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.Ret (Anf.ALit (Anf.LInt 7)))
                hdlr = Anf.Handler (Anf.Binder v Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Ret (Anf.AVar v)) [arm] Nothing Nothing Nothing
            pure (Anf.Handle comp hdlr)
      in assertEval Map.empty e (T.pack "7")

  , testCase "multi-shot: resume invoked twice, results summed" $ do
      -- handle ( let b = Flip.flip () in case b of { 0 -> ret 10 ; _ -> ret 20 } ) of
      --   Flip.flip(p, resume) ->
      --       let r0 = resume 0 in let r1 = resume 1 in let s = r0 + r1 in ret s
      --   return v -> v
      -- resume 0 -> downstream picks 10 ; resume 1 -> downstream picks 20 ; sum 30.
      --
      -- MODE-DEPENDENT expectation (one-shot spec section 9). This hand-built
      -- IR bypasses the frontend's static one-shot law, so it is the machine's
      -- multi-shot capability characterization AND the runtime oracle's
      -- end-to-end negative control, in one fixture:
      --   * default (oracle off): the machine's free multi-shot semantics run
      --     both resumes -> 30;
      --   * under WOK_DEBUG_ONESHOT=1 (scripts/oneshot-oracle.sh runs the
      --     whole suite this way): the second resume of the SAME captured
      --     continuation must abort with OneShotViolation -- this mutation-
      --     confirms the oracle through the full dispatchOp/enter path.
      oracleOn <- (== Just "1") <$> lookupEnv "WOK_DEBUG_ONESHOT"
      let e = runFresh $ do
            b <- freshName (T.pack "b"); p <- freshName (T.pack "p")
            resume <- freshName (T.pack "resume")
            r0 <- freshName (T.pack "r0"); r1 <- freshName (T.pack "r1")
            s <- freshName (T.pack "s"); v <- freshName (T.pack "v")
            let comp = Anf.Let (Anf.Binder b Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                         (Anf.ROp Nothing (T.pack "Flip") (T.pack "flip") [Anf.ALit Anf.LUnit])
                         (Anf.Case (Anf.AVar b)
                           [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 10)))
                           , Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 20))) ])
                armBody =
                  Anf.Let (Anf.Binder r0 Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) (Anf.RApp (Anf.AVar resume) [Anf.ALit (Anf.LInt 0)])
                    (Anf.Let (Anf.Binder r1 Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) (Anf.RApp (Anf.AVar resume) [Anf.ALit (Anf.LInt 1)])
                      (Anf.Let (Anf.Binder s Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) (Anf.RApp (primAtom (T.pack "+")) [Anf.AVar r0, Anf.AVar r1])
                        (Anf.Ret (Anf.AVar s))))
                arm = Anf.OpArm (T.pack "Flip") (T.pack "flip")
                        [Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] (Anf.Binder resume Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])) armBody
                hdlr = Anf.Handler (Anf.Binder v Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Ret (Anf.AVar v)) [arm] Nothing Nothing Nothing
            pure (Anf.Handle comp hdlr)
      if oracleOn
        then case IM.evalExprWith Map.empty e of
          Left IV.OneShotViolation -> pure ()
          other -> assertFailure
            ("oracle on: second resume must abort OneShotViolation, got " <> show other)
        else assertEval Map.empty e (T.pack "30")

  , testCase "deep handler: handler is re-installed so a SECOND op is still handled" $
      -- handle ( let x = E.op () in let y = E.op () in let s = x + y in ret s ) of
      --   E.op(p, resume) -> let r = resume 1 in ret r       (single auto-resume)
      --   return v -> v
      -- The computation performs E.op TWICE in sequence. The second op only
      -- finds a handler because resume re-installs the KHandle frame (deep
      -- semantics). A broken re-install surfaces NoMatchingHandler on the
      -- second op, so the expected value 2 (= 1 + 1) is the discriminator.
      -- Low-effort: reuses the auto-resume arm shape; no multi-shot machinery.
      let e = runFresh $ do
            x <- freshName (T.pack "x"); y <- freshName (T.pack "y"); s <- freshName (T.pack "s")
            p <- freshName (T.pack "p"); resume <- freshName (T.pack "resume")
            r <- freshName (T.pack "r"); v <- freshName (T.pack "v")
            let comp =
                  Anf.Let (Anf.Binder x Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                    (Anf.ROp Nothing (T.pack "E") (T.pack "op") [Anf.ALit Anf.LUnit])
                    (Anf.Let (Anf.Binder y Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                      (Anf.ROp Nothing (T.pack "E") (T.pack "op") [Anf.ALit Anf.LUnit])
                      (Anf.Let (Anf.Binder s Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.RApp (primAtom (T.pack "+")) [Anf.AVar x, Anf.AVar y])
                        (Anf.Ret (Anf.AVar s))))
                arm = Anf.OpArm (T.pack "E") (T.pack "op")
                        [Anf.Binder p Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])] (Anf.Binder resume Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                        (Anf.Let (Anf.Binder r Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                          (Anf.RApp (Anf.AVar resume) [Anf.ALit (Anf.LInt 1)])
                          (Anf.Ret (Anf.AVar r)))
                hdlr = Anf.Handler (Anf.Binder v Anf.Unrestricted (Ty.CTCon Ty.TcUnit []), Anf.Ret (Anf.AVar v)) [arm] Nothing Nothing Nothing
            pure (Anf.Handle comp hdlr)
      in assertEval Map.empty e (T.pack "2")

  , testCase "named instance routes past nearest handler to its own handler" $
      -- Outer handler is NAMED (self-binder sb); inner handler is ambient.
      -- Both handle E.op. Inside the inner handler's scope we perform E.op
      -- THROUGH the outer instance (ROp (Just (AVar sb))). Ambient routing
      -- would hit the inner handler (-> 1); named routing must skip it and
      -- reach the outer (-> 2). The discriminator is the returned value 2.
      --   outer (named sb): E.op -> resume 2
      --   inner (ambient) : E.op -> resume 1
      --   body            : let x = sb.E.op () in ret x
      let e = runFresh $ do
            sb <- freshName (T.pack "sb")
            x  <- freshName (T.pack "x")
            pIn <- freshName (T.pack "pIn"); rIn <- freshName (T.pack "rIn")
            pOut <- freshName (T.pack "pOut"); rOut <- freshName (T.pack "rOut")
            vIn <- freshName (T.pack "vIn"); vOut <- freshName (T.pack "vOut")
            armIn <- freshName (T.pack "armIn"); armOut <- freshName (T.pack "armOut")
            let unit = Ty.CTCon Ty.TcUnit []
                resumeBody resume rb val =
                  Anf.Let (Anf.Binder rb Anf.Unrestricted unit)
                    (Anf.RApp (Anf.AVar resume) [Anf.ALit (Anf.LInt val)])
                    (Anf.Ret (Anf.AVar rb))
                body =
                  Anf.Let (Anf.Binder x Anf.Unrestricted unit)
                    (Anf.ROp (Just (Anf.AVar sb)) (T.pack "E") (T.pack "op") [Anf.ALit Anf.LUnit])
                    (Anf.Ret (Anf.AVar x))
                innerArm =
                  Anf.OpArm (T.pack "E") (T.pack "op")
                    [Anf.Binder pIn Anf.Unrestricted unit]
                    (Anf.Binder rIn Anf.Unrestricted unit)
                    (resumeBody rIn armIn 1)
                innerHdlr =
                  Anf.Handler (Anf.Binder vIn Anf.Unrestricted unit, Anf.Ret (Anf.AVar vIn))
                    [innerArm] Nothing Nothing Nothing
                outerArm =
                  Anf.OpArm (T.pack "E") (T.pack "op")
                    [Anf.Binder pOut Anf.Unrestricted unit]
                    (Anf.Binder rOut Anf.Unrestricted unit)
                    (resumeBody rOut armOut 2)
                outerHdlr =
                  Anf.Handler (Anf.Binder vOut Anf.Unrestricted unit, Anf.Ret (Anf.AVar vOut))
                    [outerArm] Nothing Nothing (Just (Anf.Binder sb Anf.Unrestricted unit))
            pure (Anf.Handle (Anf.Handle body innerHdlr) outerHdlr)
      in assertEval Map.empty e (T.pack "2")

  , testCase "unhandled operation errors" $
      let e = runFresh $ do
            a <- freshName (T.pack "a")
            pure $ Anf.Let (Anf.Binder a Anf.Unrestricted (Ty.CTCon Ty.TcUnit []))
                     (Anf.ROp Nothing (T.pack "Ask") (T.pack "ask") [Anf.ALit Anf.LUnit])
                     (Anf.Ret (Anf.AVar a))
      in case IM.evalExprWith Map.empty e of
           Left (IV.NoMatchingHandler l o) -> (l, o) @?= (T.pack "Ask", T.pack "ask")
           other -> assertFailure ("expected NoMatchingHandler, got " <> show other)
  ]
  where
    assertEval env e expected =
      case IM.evalExprWith env e of
        Right v -> IV.renderValue v @?= expected
        Left err -> assertFailure ("eval failed: " <> show err)

-- ---------------------------------------------------------------------------
-- oneShotOracleTests

-- | Phase D (one-shot spec section 9): unit tests of the runtime one-shot
-- oracle at the 'IM.enter' apply site, with hand-made flags so they hold in
-- BOTH suite modes (default and the scripts/oneshot-oracle.sh run). Laziness
-- caveat: each application must be a syntactically distinct 'IM.enter' call
-- forced in order -- naming one 'Either' and casing on it twice would memoize
-- the first application's result and never re-run the flag check.
oneShotOracleTests :: TestTree
oneShotOracleTests = testGroup "one-shot runtime oracle"
  [ testCase "flagged VCont: first apply ok, second aborts OneShotViolation" $ do
      fl <- Just <$> newIORef False
      let v = IV.VCont fl id
      assertApplyOk (IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 1)] IV.KDone)
      case IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 2)] IV.KDone of
        Left IV.OneShotViolation -> pure ()
        other -> assertFailure ("second apply must abort: " <> showEither other)

  , testCase "flagged VContP: first apply ok, second aborts OneShotViolation" $ do
      fl <- Just <$> newIORef False
      let v = IV.VContP fl (\_ k -> k)
      assertApplyOk (IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 1), IV.VLit (Anf.LInt 2)] IV.KDone)
      case IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 3), IV.VLit (Anf.LInt 4)] IV.KDone of
        Left IV.OneShotViolation -> pure ()
        other -> assertFailure ("second apply must abort: " <> showEither other)

  , testCase "flag-less VCont: multi-shot capability preserved (oracle off is free)" $ do
      let v = IV.VCont Nothing id
      assertApplyOk (IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 1)] IV.KDone)
      assertApplyOk (IM.enter IP.primTable 0 v [IV.VLit (Anf.LInt 2)] IV.KDone)
  ]
  where
    assertApplyOk r = case r of
      Right _  -> pure ()
      Left err -> assertFailure ("apply must succeed: " <> show err)
    showEither (Left err) = "Left " <> show err
    showEither (Right _)  = "Right <config>"

-- ---------------------------------------------------------------------------
-- interpEntryTests

-- Load + elaborate (via the given elaborator) + run a single-file program.
-- Unique temp path per call (parallel-safe); guaranteed cleanup.
runSourceWith
  :: (Loader.ModuleName -> [Loader.LoadedModule] -> Either String Anf.CoreModule)
  -> Text -> IO (Either String Text)
runSourceWith elaborate src = do
  u <- newUnique
  let path = "test/.interp-tmp-" <> show (hashUnique u) <> ".wok"
  go path `Control.Exception.finally` removeFileIfExists path
  where
    go path = do
      TIO.writeFile path src
      result <- Loader.loadProgram path []
      case result of
        Left lerr -> pure (Left ("loader: " <> show lerr))
        Right (entryName, ms) ->
          case elaborate entryName ms of
            Left s  -> pure (Left ("elaborate: " <> s))
            Right cm -> case Interp.runModule cm of
              Left rerr -> pure (Left ("runtime: " <> show rerr))
              Right v   -> pure (Right (Interp.renderValue v))

-- Load + whole-program-elaborate a single-file program, returning the elaborated
-- CoreModule (for IR-shape assertions). Unique temp path per call; cleaned up.
elaborateSourceFull :: Text -> IO (Either String Anf.CoreModule)
elaborateSourceFull src = do
  u <- newUnique
  let path = "test/.interp-tmp-" <> show (hashUnique u) <> ".wok"
  go path `Control.Exception.finally` removeFileIfExists path
  where
    go path = do
      TIO.writeFile path src
      result <- Loader.loadProgram path []
      case result of
        Left lerr -> pure (Left ("loader: " <> show lerr))
        Right (entryName, ms) -> pure (Pipeline.elaborateProgramFull entryName ms)

-- Every APrim (module, name) key appearing anywhere in a CoreModule's bodies.
aprimKeysInModule :: Anf.CoreModule -> Set.Set (Text, Text)
aprimKeysInModule (Anf.CoreModule binds) =
  Set.unions (map (goE . Anf.tbBody) binds)
  where
    goA (Anf.APrim qkey) = Set.singleton qkey
    goA _                = Set.empty
    goR r = case r of
      RAtom a       -> goA a
      RApp h as     -> Set.unions (map goA (h : as))
      RCon _ as     -> Set.unions (map goA as)
      RLam _ b      -> goE b
      ROp m _ _ as  -> Set.unions (map goA (maybe as (: as) m))
      RRecord _ fls -> Set.unions (map (goA . snd) fls)
      RProj _ a     -> goA a
      RMakeHandler h -> goE (snd (Anf.hReturn h))
                          `Set.union` Set.unions (map (goE . Anf.oaBody) (Anf.hOps h))
      RReuseCon{}          -> error "RReuseCon: produced only by reusePairing post-pass (never in hand-built test IR)"
      RForeignCall _ _ _ _ _ as -> Set.unions (map goA as)
    goE e = case e of
      Ret a               -> goA a
      Jump _ as           -> Set.unions (map goA as)
      Let _ r body        -> goR r `Set.union` goE body
      LetRec ds body      -> Set.unions (goE body : [ goE d | (_, _, d) <- ds ])
      Case a alts         -> goA a `Set.union` Set.unions (map goAlt alts)
      LetJoin _ _ jb body -> goE jb `Set.union` goE body
      Handle e' h         ->
        goE e' `Set.union` goE (snd (Anf.hReturn h))
               `Set.union` Set.unions (map (goE . Anf.oaBody) (Anf.hOps h))
      InstallHandler a _ e' -> goA a `Set.union` goE e'
    goAlt (AltCon _ _ e) = goE e
    goAlt (AltLit _ e)   = goE e
    goAlt (AltDefault e) = goE e

runSourceToValue :: Text -> IO (Either String Text)
runSourceToValue = runSourceWith Pipeline.elaborateProgram

-- Like 'runSourceToValue' but additionally forces the result and converts any
-- pure 'error' thrown during elaboration (e.g. unsupported pattern) into a
-- 'Left'. Elaboration errors are raised lazily, so a plain run would otherwise
-- surface them only as an uncaught exception.
runSourceToValueForced :: Text -> IO (Either String Text)
runSourceToValueForced src = do
  caught <- Control.Exception.try (runSourceToValue src >>= \r -> Control.Exception.evaluate (forceEither r))
  pure $ case caught of
    Left (Control.Exception.ErrorCall msg) -> Left msg
    Right ok                               -> ok
  where
    forceEither e@(Left s)  = s `seq` e
    forceEither e@(Right t) = T.length t `seq` e

removeFileIfExists :: FilePath -> IO ()
removeFileIfExists p = Dir.doesFileExist p >>= \yes -> Control.Monad.when yes (Dir.removeFile p)

interpEntryTests :: TestTree
interpEntryTests = testGroup "InterpEntry"
  [ testCase "arithmetic main" $ do
      r <- runSourceToValue (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "main = 2 + 3 * 4" ])
      r @?= Right (T.pack "14")
  , testCase "recursive factorial" $ do
      r <- runSourceToValue (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "fact n = case n of"
             , T.pack "  0 -> 1"
             , T.pack "  _ -> n * fact (n - 1)"
             , T.pack "main = fact 5" ])
      r @?= Right (T.pack "120")
  , testCase "missing main errors" $ do
      r <- runSourceToValue (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "helper x = x" ])
      case r of
        Left msg -> assertBool ("expected missing-main (UnboundVar) error, got: " <> msg)
                      (Data.List.isInfixOf "UnboundVar" msg && Data.List.isInfixOf "main" msg)
        Right v  -> assertFailure ("expected failure, got " <> T.unpack v)
  , testCase "top-level constant (CAF) is forced and usable from main" $ do
      -- A 0-arity non-main bind is now evaluated once to a value and shared
      -- (previously rejected as UnsupportedCaf). This underpins ground
      -- instance dictionaries, which lower to 0-arity record values.
      r <- runSourceToValue (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "answer = 42"
             , T.pack "main = answer" ])
      r @?= Right (T.pack "42")
  , testCase "non-zero integer pattern matches its literal (C1 regression)" $ do
      -- Before the fix, integer-literal patterns were compiled to a literal 0,
      -- so `case 5 of 5 -> 100; _ -> 0` returned 0 instead of 100.
      r <- runSourceToValue (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "classify n = case n of"
             , T.pack "  5 -> 100"
             , T.pack "  _ -> 0"
             , T.pack "main = classify 5" ])
      r @?= Right (T.pack "100")
  , testCase "non-empty list literal pattern is rejected (I3 guard)" $ do
      -- Exact-length list matching needs a backtracking match compiler the flat
      -- one-Alt-per-clause model lacks; rather than silently match ANY non-empty
      -- list, a non-empty list literal pattern is rejected (as it was on main).
      r <- runSourceToValueForced (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "solo xs = case xs of"
             , T.pack "  [a] -> a"
             , T.pack "  _   -> 0"
             , T.pack "main = solo [1, 2]" ])
      case r of
        Left msg -> assertBool
                      ("expected non-empty list literal pattern rejection, got: " <> msg)
                      (Data.List.isInfixOf "non-empty list literal pattern" msg)
        Right v  -> assertFailure ("expected rejection, got " <> T.unpack v)
  ]

interpWholeProgramTests :: TestTree
interpWholeProgramTests = testGroup "InterpWholeProgram"
  [ testCase "main calls prelude id" $ do
      r <- runSourceWith Pipeline.elaborateProgramFull (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "main = id 99" ])
      r @?= Right (T.pack "99")
  , testCase "main calls prelude const" $ do
      r <- runSourceWith Pipeline.elaborateProgramFull (T.unlines
             [ T.pack "module Main"
             , T.pack "import Base"
             , T.pack "main = const 7 99" ])
      r @?= Right (T.pack "7")
  , testCase "builtin (+) elaborates to APrim (Base, +)" $ do
      -- The elaborator routes a value-level prelude extern reference to APrim by
      -- extern identity. `1 + 2` lowers `(+)` to its prelude extern, so the
      -- elaborated IR must contain APrim ("Base", "+") and NOT a bare AVar "+".
      cm <- elaborateSourceFull (T.unlines
              [ T.pack "module Main"
              , T.pack "import Base"
              , T.pack "main = 1 + 2" ])
      case cm of
        Left s   -> assertFailure s
        Right m  ->
          let keys = aprimKeysInModule m
          in assertBool ("expected APrim (Base, +) in elaborated IR, got APrims: "
                           <> show keys)
                        ((T.pack "Base", T.pack "+") `Set.member` keys)
  ]

-- ---------------------------------------------------------------------------
-- Elaborate basic tests

-- | Check whether an Expr matches the structural shape of:
--   Let _ (RApp _ [ALit (LInt 1)]) (Let _ (RApp _ [AVar _]) (Ret (AVar _)))
-- This corresponds to elaborating  f (g 1).
isAppNamingShape :: Anf.Expr -> Bool
isAppNamingShape
  (Anf.Let _ (Anf.RApp _ [Anf.ALit (Anf.LInt 1)])
    (Anf.Let _ (Anf.RApp _ [Anf.AVar _])
      (Anf.Ret (Anf.AVar _)))) = True
isAppNamingShape _ = False

elaborateBasicTests :: TestTree
elaborateBasicTests = testGroup "ElaborateBasic"
  [ testCase "literal int -> Ret (ALit (LInt 1))" $
      elaborateExprForTest TE.emptyEnv
        (Abs.ELitI (Abs.WokInt ((0,0), T.pack "1")))
        @?= Anf.Ret (Anf.ALit (Anf.LInt 1))

  , testCase "literal string -> Ret (ALit (LStr ...))" $
      elaborateExprForTest TE.emptyEnv
        (Abs.ELitS "hello")
        @?= Anf.Ret (Anf.ALit (Anf.LStr (T.pack "hello")))

  , testCase "unit -> Ret (ALit LUnit)" $
      elaborateExprForTest TE.emptyEnv Abs.EUnit
        @?= Anf.Ret (Anf.ALit Anf.LUnit)

  , testCase "application f (g 1) names its arguments" $
      let -- f (g 1) encoded as EApp (EVar f) (EParen (EApp (EVar g) (ELitI 1)))
          lit1  = Abs.ELitI (Abs.WokInt ((0,0), T.pack "1"))
          g_app = Abs.EApp (Abs.EVar (Abs.VarId ((0,0), T.pack "g"))) lit1
          expr  = Abs.EApp
                    (Abs.EVar (Abs.VarId ((0,0), T.pack "f")))
                    (Abs.EParen g_app)
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Let _ (RApp _ [ALit 1]) (Let _ (RApp _ [AVar _]) (Ret (AVar _))), got: "
            <> show result)
           (isAppNamingShape result)

  , testCase "tuple (1, 2) -> Let _ (RCon Tuple2 [ALit 1, ALit 2]) (Ret (AVar _))" $
      let expr = Abs.ETuple
                   (Abs.ELitI (Abs.WokInt ((0,0), T.pack "1")))
                   [Abs.ELitI (Abs.WokInt ((0,0), T.pack "2"))]
          result = elaborateExprForTest TE.emptyEnv expr
      in case result of
           Anf.Let _ (Anf.RCon tag [Anf.ALit (Anf.LInt 1), Anf.ALit (Anf.LInt 2)]) (Anf.Ret (Anf.AVar _)) ->
             tag @?= T.pack "Tuple2"
           _ -> assertFailure ("unexpected shape: " <> show result)

  , testCase "list [1] -> Let nil (RCon Nil []) (Let _ (RCon Cons [ALit 1, AVar nil]) (Ret ...))" $
      let expr   = Abs.EList [Abs.ELitI (Abs.WokInt ((0,0), T.pack "1"))]
          result = elaborateExprForTest TE.emptyEnv expr
      in case result of
           Anf.Let _ (Anf.RCon nilTag []) (Anf.Let _ (Anf.RCon consTag [Anf.ALit (Anf.LInt 1), Anf.AVar _]) (Anf.Ret (Anf.AVar _))) -> do
             nilTag  @?= T.pack "Nil"
             consTag @?= T.pack "Cons"
           _ -> assertFailure ("unexpected shape: " <> show result)

  , testCase "empty list [] -> Let _ (RCon Nil []) (Ret (AVar _))" $
      let expr   = Abs.EList []
          result = elaborateExprForTest TE.emptyEnv expr
      in case result of
           Anf.Let _ (Anf.RCon nilTag []) (Anf.Ret (Anf.AVar _)) ->
             nilTag @?= T.pack "Nil"
           -- nullary con passes through as RAtom-free path -> Let binding
           _ -> assertFailure ("unexpected shape: " <> show result)
  ]

-- ---------------------------------------------------------------------------
-- ElaborateControl tests

-- | Helpers for building dummy-position tokens.
dummyPos :: (Int, Int)
dummyPos = (0, 0)

varId :: T.Text -> Abs.VarId
varId t = Abs.VarId (dummyPos, t)

conId :: T.Text -> Abs.ConId
conId t = Abs.ConId (dummyPos, t)

-- | Check whether an Expr has a Case with two AltCon arms, the first being
-- conName1 with at least one field binder and the second being conName2 with
-- no field binders.
isTwoConCaseShape :: T.Text -> T.Text -> Anf.Expr -> Bool
isTwoConCaseShape con1 con2 e = case e of
  Anf.Case _ [Anf.AltCon c1 (_:_) _, Anf.AltCon c2 [] _] ->
    c1 == con1 && c2 == con2
  _ -> False

-- | Check that an Expr contains at least one LetJoin node anywhere.
hasLetJoin :: Anf.Expr -> Bool
hasLetJoin (Anf.LetJoin _ _ _ _)     = True
hasLetJoin (Anf.Let _ _ e)            = hasLetJoin e
hasLetJoin (Anf.LetRec defs e)        = any (\(_, _, b) -> hasLetJoin b) defs || hasLetJoin e
hasLetJoin (Anf.Case _ alts)          = any altHasLetJoin alts
hasLetJoin (Anf.Jump _ _)             = False
hasLetJoin (Anf.Ret _)                = False
hasLetJoin (Anf.Handle e _)           = hasLetJoin e
hasLetJoin (Anf.InstallHandler _ _ e)   = hasLetJoin e

altHasLetJoin :: Anf.Alt -> Bool
altHasLetJoin (Anf.AltCon _ _ e)  = hasLetJoin e
altHasLetJoin (Anf.AltLit _ e)    = hasLetJoin e
altHasLetJoin (Anf.AltDefault e)  = hasLetJoin e

-- | Check that a tail-position if elaborates to a bare Case (no LetJoin).
isBareIfCase :: Anf.Expr -> Bool
isBareIfCase (Anf.Case _ [Anf.AltCon t1 [] _, Anf.AltCon f1 [] _]) =
  t1 == T.pack "True" && f1 == T.pack "False"
isBareIfCase _ = False

-- | Check the shape of a bare let-value binding:
-- Let _ (RAtom (ALit (LInt 1))) (Ret (AVar _))
isLetValueRetShape :: Anf.Expr -> Bool
isLetValueRetShape (Anf.Let _ (Anf.RAtom (Anf.ALit (Anf.LInt 1))) (Anf.Ret (Anf.AVar _))) = True
isLetValueRetShape _ = False

-- | Check that an Expr contains a LetRec with at least one entry.
hasLetRec :: Anf.Expr -> Bool
hasLetRec (Anf.LetRec (_:_) _)       = True
hasLetRec (Anf.Let _ _ e)             = hasLetRec e
hasLetRec (Anf.LetRec _ e)            = hasLetRec e
hasLetRec (Anf.LetJoin _ _ jb e)     = hasLetRec jb || hasLetRec e
hasLetRec (Anf.Case _ alts)           = any altHasLetRec alts
hasLetRec _                           = False

altHasLetRec :: Anf.Alt -> Bool
altHasLetRec (Anf.AltCon _ _ e) = hasLetRec e
altHasLetRec (Anf.AltLit _ e)   = hasLetRec e
altHasLetRec (Anf.AltDefault e) = hasLetRec e

elaborateControlTests :: TestTree
elaborateControlTests = testGroup "ElaborateControl"

  [ -- case on a 2-constructor type: case m of { Just x -> x ; Nothing -> 0 }
    -- Expect: Case _ [AltCon "Just" [_] _, AltCon "Nothing" [] _]
    testCase "case: 2-constructor type Just/Nothing shape" $
      let mExpr   = Abs.EVar (varId (T.pack "m"))
          justPat = Abs.PApp (Abs.MPName (conId (T.pack "Just")))
                             (Abs.APVar (varId (T.pack "x")))
                             []
          nothPat = Abs.PAtom (Abs.APCon (Abs.MPName (conId (T.pack "Nothing"))))
          xExpr   = Abs.EVar (varId (T.pack "x"))
          zeroExpr = Abs.ELitI (Abs.WokInt (dummyPos, T.pack "0"))
          alt1    = Abs.AltC justPat xExpr Abs.NoWhere
          alt2    = Abs.AltC nothPat zeroExpr Abs.NoWhere
          expr    = Abs.ECase mExpr [alt1, alt2]
          result  = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Case [AltCon Just [_] _, AltCon Nothing [] _], got: " <> show result)
           (isTwoConCaseShape (T.pack "Just") (T.pack "Nothing") result)

  , -- value-position if introduces a LetJoin:
    -- normName (EIf c 1 2) k  =>  LetJoin j [r] (k (AVar r)) (Case c [True->Jump j [1]; False->Jump j [2]])
    testCase "value-position if: normName introduces LetJoin" $
      let cExpr = Abs.EVar (varId (T.pack "c"))
          ifExpr = Abs.EIf cExpr
                     (Abs.ELitI (Abs.WokInt (dummyPos, T.pack "1")))
                     (Abs.ELitI (Abs.WokInt (dummyPos, T.pack "2")))
          -- wrap in a let so 'if' is in value position: let y = (if c then 1 else 2) in y
          letBody = Abs.EVar (varId (T.pack "y"))
          letDecl = Abs.LDEqn (Abs.LHSPre (Abs.FNBare (varId (T.pack "y"))) [])
                               ifExpr Abs.NoWhere
          expr    = Abs.ELet [letDecl] letBody
          result  = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected LetJoin in result (value-position if), got: " <> show result)
           (hasLetJoin result)

  , -- tail-position if is a bare Case over True/False (no LetJoin)
    testCase "tail-position if: bare Case over True/False" $
      let cExpr = Abs.EVar (varId (T.pack "c"))
          expr  = Abs.EIf cExpr
                    (Abs.ELitI (Abs.WokInt (dummyPos, T.pack "1")))
                    (Abs.ELitI (Abs.WokInt (dummyPos, T.pack "2")))
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected bare Case over True/False, got: " <> show result)
           (isBareIfCase result)

  , -- let value binding: let x = 1 in x
    -- Expect: Let _ (RAtom (ALit (LInt 1))) (Ret (AVar _))
    testCase "let value binding: let x = 1 in x -> Let _ (RAtom (LInt 1)) (Ret (AVar _))" $
      let litExpr = Abs.ELitI (Abs.WokInt (dummyPos, T.pack "1"))
          letDecl = Abs.LDEqn (Abs.LHSPre (Abs.FNBare (varId (T.pack "x"))) [])
                               litExpr Abs.NoWhere
          body    = Abs.EVar (varId (T.pack "x"))
          expr    = Abs.ELet [letDecl] body
          result  = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Let _ (RAtom (LInt 1)) (Ret (AVar _)), got: " <> show result)
           (isLetValueRetShape result)

  , -- let function binding: let f y = y in f
    -- Expect: LetRec with one entry whose body is Ret (AVar _)
    testCase "let function binding: let f y = y in f -> contains LetRec" $
      let paramPat = Abs.APVar (varId (T.pack "y"))
          bodyY    = Abs.EVar (varId (T.pack "y"))
          letDecl  = Abs.LDEqn (Abs.LHSPre (Abs.FNBare (varId (T.pack "f"))) [paramPat])
                                bodyY Abs.NoWhere
          contF    = Abs.EVar (varId (T.pack "f"))
          expr     = Abs.ELet [letDecl] contF
          result   = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected LetRec in result, got: " <> show result)
           (hasLetRec result)

  , -- PCons with a non-trivial (literal) head: case xs of { 0 : rest -> rest ; _ -> [] }
    -- The head 0 is an APLitI, which is refutable; elabPat must emit a nested
    -- Case on the head binder with an AltLit 0 arm (not silently wildcard it).
    testCase "cons pattern with literal head: literal is compiled to a real test (not wildcarded)" $
      -- `case xs of (0 :: rest) -> rest; _ -> []`. The head literal `0` is a
      -- REFUTABLE sub-pattern under Cons, so this routes through the decision-tree
      -- compiler (bug #7: the old flat one-Alt path committed to Cons and could
      -- not backtrack from a failed `0` test to the `_` arm). The literal must
      -- still appear as an AltLit (LInt 0) somewhere in the tree -- proving it was
      -- compiled to an actual test rather than silently wildcarded.
      let expr = Abs.ECase (Abs.EVar (Abs.VarId ((0,0), T.pack "xs")))
                   [ Abs.AltC
                       (Abs.PCons (Abs.APLitI (Abs.WokInt ((0,0), T.pack "0")))
                                  (Abs.PAtom (Abs.APVar (Abs.VarId ((0,0), T.pack "rest")))))
                       (Abs.EVar (Abs.VarId ((0,0), T.pack "rest")))
                       Abs.NoWhere
                   , Abs.AltC (Abs.PAtom Abs.APWild) (Abs.EList []) Abs.NoWhere
                   ]
          result = elaborateExprForTest TE.emptyEnv expr
          altHasLit0 a = case a of
            Anf.AltLit (Anf.LInt 0) _ -> True
            Anf.AltLit _ b            -> exprHasLit0 b
            Anf.AltCon _ _ b          -> exprHasLit0 b
            Anf.AltDefault b          -> exprHasLit0 b
          exprHasLit0 e = case e of
            Anf.Case _ alts        -> any altHasLit0 alts
            Anf.Let _ _ b          -> exprHasLit0 b
            Anf.LetRec _ b         -> exprHasLit0 b
            Anf.LetJoin _ _ jb b   -> exprHasLit0 jb || exprHasLit0 b
            _                      -> False
      in assertBool
           ("expected an AltLit (LInt 0) somewhere in the tree, got: " <> show result)
           (exprHasLit0 result)

  , -- where clause: equation body using where-bound name
    -- let x = (let-with-where body) where w = 5
    -- Modeled as:  let x = w where { w = 5 } in x
    testCase "where clause: body uses where-bound name -> binding in scope" $
      let wExpr   = Abs.EVar (varId (T.pack "w"))
          wDecl   = Abs.LDEqn (Abs.LHSPre (Abs.FNBare (varId (T.pack "w"))) [])
                               (Abs.ELitI (Abs.WokInt (dummyPos, T.pack "5"))) Abs.NoWhere
          xDecl   = Abs.LDEqn (Abs.LHSPre (Abs.FNBare (varId (T.pack "x"))) [])
                               wExpr (Abs.WithWh [wDecl])
          xVar    = Abs.EVar (varId (T.pack "x"))
          expr    = Abs.ELet [xDecl] xVar
          result  = elaborateExprForTest TE.emptyEnv expr
      in -- The result should be some nested Let structure (not error) and
         -- eventually return via Ret.
         case result of
           Anf.Ret _               -> assertFailure ("unexpectedly bare Ret: " <> show result)
           Anf.Let _ _ _           -> pure ()  -- nested Let structure: where binding in scope
           Anf.LetJoin _ _ _ _     -> pure ()  -- join wiring: also fine
           other                   -> assertFailure ("unexpected shape: " <> show other)
  ]

-- ---------------------------------------------------------------------------
-- ElaborateRecords tests
-- ---------------------------------------------------------------------------

-- | Minimal env with a record constructor Point { x : U64, y : U64 } and a
-- non-nullary data constructor Just (arity 1).
recordTestEnv :: TE.Env
recordTestEnv =
  let dummyScheme = Ty.mkScheme [] (Ty.CTCon Ty.TcUnit [])
      justInfo    = TE.ConInfo dummyScheme 1 (T.pack "Maybe")
      nilInfo     = TE.ConInfo dummyScheme 0 (T.pack "List")
      pointRci    = TE.RecordConInfo
                      (T.pack "Point")
                      [ (T.pack "x", Ty.CTCon Ty.TcU64 [])
                      , (T.pack "y", Ty.CTCon Ty.TcU64 [])
                      ]
                      []
  in TE.extendRecordCon (T.pack "Point") pointRci
       (TE.extendCon (T.pack "Just") justInfo
         (TE.extendCon (T.pack "Nil") nilInfo TE.emptyEnv))

-- Shape predicates for the record tests --------------------------------

-- For ECon "Just" in tail position, elabTail calls elabRhs then deliverRhs,
-- so the result should be:
-- Let t (RLam [a] (Let c (RCon "Just" [AVar a]) (Ret (AVar c)))) (Ret (AVar t))
isEtaJustShape :: Anf.Expr -> Bool
isEtaJustShape (Anf.Let _ (Anf.RLam (_:_) lamBody) _) = lamBodyHasRCon (T.pack "Just") lamBody
isEtaJustShape _ = False

lamBodyHasRCon :: T.Text -> Anf.Expr -> Bool
lamBodyHasRCon conName (Anf.Let _ (Anf.RCon c _) _) = c == conName
lamBodyHasRCon _       _                            = False

-- | ECon "Nil" (arity 0, registered) should produce RCon "Nil" [].
-- In tail position: Ret (AVar _) where the var came from a Let _ (RCon "Nil" []).
-- Actually for nullary: deliverRhs TRet (RCon "Nil" []) ->
--   Let t (RCon "Nil" []) (Ret (AVar t))
isNullaryConShape :: T.Text -> Anf.Expr -> Bool
isNullaryConShape conName (Anf.Let _ (Anf.RCon c []) (Anf.Ret (Anf.AVar _))) = c == conName
isNullaryConShape _ _ = False

-- | ERecord "Point" [y=2, x=1] reordered to [x=1, y=2] then RRecord "Point" [("x",..), ("y",..)]
-- In tail position: Let t (RRecord "Point" [...]) (Ret (AVar t))
isRecordDeclaredOrder :: Anf.Expr -> Bool
isRecordDeclaredOrder (Anf.Let _ (Anf.RRecord t fields) _) =
  t == T.pack "Point" && length fields == 2 &&
  fst (fields !! 0) == T.pack "x" &&
  fst (fields !! 1) == T.pack "y"
isRecordDeclaredOrder _ = False

-- | EProj (EVar p) "x" -> Let t (RProj "x" (AVar _)) (Ret (AVar t))
isProjShape :: T.Text -> Anf.Expr -> Bool
isProjShape lbl (Anf.Let _ (Anf.RProj l (Anf.AVar _)) _) = l == lbl
isProjShape _   _                                         = False

-- | Record pattern: case pt of { Point { x = px } -> px }
-- Expect: Case _ [AltCon "Point" [] (Let _ (RProj "x" _) (Ret (AVar _)))]
isRecordPatShape :: Anf.Expr -> Bool
isRecordPatShape (Anf.Case _ [Anf.AltCon t [] body]) =
  t == T.pack "Point" && bodyHasProjLet body
isRecordPatShape _ = False

bodyHasProjLet :: Anf.Expr -> Bool
bodyHasProjLet (Anf.Let _ (Anf.RProj l (Anf.AVar _)) (Anf.Ret (Anf.AVar _))) =
  l == T.pack "x"
bodyHasProjLet _ = False

elaborateRecordsTests :: TestTree
elaborateRecordsTests = testGroup "ElaborateRecords"
  [ -- Constructor saturation: bare ECon "Just" (arity 1) -> eta-expanded RLam
    testCase "saturation: ECon Just (arity 1) produces an RLam wrapper" $
      let expr   = Abs.ECon (conId (T.pack "Just"))
          result = elaborateExprForTest recordTestEnv expr
      in assertBool
           ("expected Let _ (RLam [_] ...) _, got: " <> show result)
           (isEtaJustShape result)

  , -- Nullary constructor stays RCon
    testCase "nullary: ECon Nil (arity 0) produces RCon Nil []" $
      let expr   = Abs.ECon (conId (T.pack "Nil"))
          result = elaborateExprForTest recordTestEnv expr
      in assertBool
           ("expected Let _ (RCon \"Nil\" []) (Ret _), got: " <> show result)
           (isNullaryConShape (T.pack "Nil") result)

  , -- Unregistered constructor stays nullary
    testCase "nullary: unregistered ECon stays RCon []" $
      let expr   = Abs.ECon (conId (T.pack "Nothing"))
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected RCon \"Nothing\" [], got: " <> show result)
           (isNullaryConShape (T.pack "Nothing") result)

  , -- Record construction with fields given out of order -> reordered to declared order
    testCase "record construction: ERecord Point [y=2, x=1] reordered to [x,y]" $
      let litI n = Abs.ELitI (Abs.WokInt (dummyPos, T.pack (show (n :: Int))))
          fe l e = Abs.RFExpr (varId (T.pack l)) e
          -- fields in source order: y first, then x
          expr   = Abs.ERecord (conId (T.pack "Point"))
                     [ fe "y" (litI 2)
                     , fe "x" (litI 1)
                     ]
          result = elaborateExprForTest recordTestEnv expr
      in assertBool
           ("expected RRecord Point [(x,_),(y,_)] in declared order, got: " <> show result)
           (isRecordDeclaredOrder result)

  , -- Record projection
    testCase "projection: EProj (EVar p) x -> RProj \"x\" _" $
      let expr   = Abs.EProj (Abs.EVar (varId (T.pack "p"))) (varId (T.pack "x"))
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Let _ (RProj \"x\" (AVar _)) _, got: " <> show result)
           (isProjShape (T.pack "x") result)

  , -- Record pattern: case pt of { Point { x = px } -> px }
    testCase "record pattern PRecord: fields bound by RProj" $
      let ptExpr  = Abs.EVar (varId (T.pack "pt"))
          pxPat   = Abs.PAtom (Abs.APVar (varId (T.pack "px")))
          rfp     = Abs.RFPat (varId (T.pack "x")) pxPat
          pat     = Abs.PAtom (Abs.PRecord (conId (T.pack "Point")) [rfp])
          bodyExpr = Abs.EVar (varId (T.pack "px"))
          alt     = Abs.AltC pat bodyExpr Abs.NoWhere
          expr    = Abs.ECase ptExpr [alt]
          result  = elaborateExprForTest recordTestEnv expr
      in assertBool
           ("expected Case _ [AltCon Point [] (Let _ (RProj x _) (Ret _))], got: " <> show result)
           (isRecordPatShape result)
  ]

-- ---------------------------------------------------------------------------
-- ElaborateEffects tests
-- ---------------------------------------------------------------------------

-- | Minimal env with effect IO declaring operations write (1 arg) and read (1 arg).
effectTestEnv :: TE.Env
effectTestEnv =
  let dummyScheme = Ty.mkScheme [] (Ty.CTCon Ty.TcUnit [])
      ioInfo = TE.EffectInfo
                 []
                 (Map.fromList
                   [ (T.pack "write", dummyScheme)
                   , (T.pack "read",  dummyScheme)
                   ])
  in TE.extendEffect (T.pack "IO") ioInfo TE.emptyEnv

-- | Check whether the top-level Rhs of an expression is an ROp with the given label and op.
-- Searches through the outermost Let if present.
hasROp :: T.Text -> T.Text -> Anf.Expr -> Bool
hasROp lbl op e = case e of
  Anf.Let _ (Anf.ROp _ l o _) _ -> l == lbl && o == op
  Anf.Ret (Anf.AVar _)          -> False  -- bare atom, no ROp
  _                              -> False

-- | Check that an ROp (not an RApp/RProj) appears in the outermost binding.
topLevelIsROp :: T.Text -> T.Text -> Anf.Expr -> Bool
topLevelIsROp lbl op expr = case expr of
  Anf.Let _ (Anf.ROp _ l o _) _ -> l == lbl && o == op
  _                             -> False

-- | Check that the outermost expression is a Handle with at least one OpArm
-- whose label and op match.
isHandleWithOpArm :: T.Text -> T.Text -> Anf.Expr -> Bool
isHandleWithOpArm lbl op expr = case expr of
  Anf.Handle _ (Anf.Handler _ opArms _ _ _) ->
    any (\arm -> Anf.oaLabel arm == lbl && Anf.oaOp arm == op) opArms
  _ -> False

-- | Check that an OpArm body contains an RApp of the resume binder (auto-resume).
opArmBodyHasResume :: Anf.OpArm -> Bool
opArmBodyHasResume arm =
  let resumeName = Anf.bndName (Anf.oaResume arm)
  in exprHasRAppOf resumeName (Anf.oaBody arm)

exprHasRAppOf :: Name -> Anf.Expr -> Bool
exprHasRAppOf n (Anf.Let _ (Anf.RApp (Anf.AVar f) _) _) = f == n
exprHasRAppOf n (Anf.Let _ _ rest)                        = exprHasRAppOf n rest
exprHasRAppOf n (Anf.LetJoin _ _ jb e)                   = exprHasRAppOf n jb || exprHasRAppOf n e
exprHasRAppOf _ _                                         = False

elaborateEffectsTests :: TestTree
elaborateEffectsTests = testGroup "ElaborateEffects"

  [ -- Effect operation call: IO.write x -> ROp "IO" "write" [_]
    testCase "operation call: EApp (EProj (ECon IO) write) x -> ROp IO write [_]" $
      let xExpr = Abs.EVar (varId (T.pack "x"))
          hdExpr = Abs.EProj (Abs.ECon (conId (T.pack "IO"))) (varId (T.pack "write"))
          expr   = Abs.EApp hdExpr xExpr
          result = elaborateExprForTest effectTestEnv expr
      in assertBool
           ("expected Let _ (ROp \"IO\" \"write\" [_]) _, got: " <> show result)
           (topLevelIsROp (T.pack "IO") (T.pack "write") result)

  , -- Non-effect projection should still produce RProj, not ROp.
    testCase "non-effect EProj (EVar r) x -> RProj x _ (not ROp)" $
      let rExpr  = Abs.EVar (varId (T.pack "r"))
          expr   = Abs.EProj rExpr (varId (T.pack "x"))
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Let _ (RProj \"x\" _) _, got: " <> show result)
           (case result of
             Anf.Let _ (Anf.RProj l (Anf.AVar _)) _ -> l == T.pack "x"
             _                                        -> False)

  , -- Operator chain: a + b -> RApp <+> [a, b]
    testCase "EExpr: a + b -> RApp (AVar +) [AVar a, AVar b]" $
      let aE = Abs.EVar (varId (T.pack "a"))
          bE = Abs.EVar (varId (T.pack "b"))
          op = Abs.IOSym (Abs.VarSym (dummyPos, T.pack "+"))
          expr = Abs.EExpr aE [Abs.ITail op bE]
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Let _ (RApp (AVar +) [AVar a, AVar b]) (Ret (AVar _)), got: " <> show result)
           (case result of
             Anf.Let _ (Anf.RApp (Anf.AVar _) [Anf.AVar _, Anf.AVar _]) (Anf.Ret (Anf.AVar _)) -> True
             _                                                                                    -> False)

  , -- Operator section: (+) -> RAtom (AVar _)
    testCase "EParenOp (+) -> RAtom (AVar _)" $
      let expr   = Abs.EParenOp (Abs.VarSym (dummyPos, T.pack "+"))
          result = elaborateExprForTest TE.emptyEnv expr
      in assertBool
           ("expected Ret (AVar _), got: " <> show result)
           (case result of
             Anf.Ret (Anf.AVar _) -> True
             _                    -> False)

  , -- Handler in tail position:
    -- with { IO.write m -> () ; return v -> v } (comp ())
    testCase "EWith tail position: produces Handle + OpArm with auto-resume" $
      let unitE   = Abs.EUnit
          compApp = Abs.EApp (Abs.EVar (varId (T.pack "comp"))) unitE
          mPat    = Abs.APVar (varId (T.pack "m"))
          writeArm = Abs.HArm (conId (T.pack "IO")) (varId (T.pack "write")) [mPat] Abs.EUnit
          -- Since the retrofit the value arm is spelled `return v -> e`, so it
          -- is built as HRetArm; a bare HUArm is an operation arm.
          retArm  = Abs.HRetArm (Abs.APVar (varId (T.pack "v")))
                                (Abs.EVar (varId (T.pack "v")))
          expr    = Abs.EWith [writeArm, retArm] compApp
          result  = elaborateExprForTest effectTestEnv expr
      in do
        assertBool
          ("expected Handle with IO.write OpArm, got: " <> show result)
          (isHandleWithOpArm (T.pack "IO") (T.pack "write") result)
        -- check auto-resume: the op arm body contains RApp of the resume binder
        case result of
          Anf.Handle _ (Anf.Handler _ (arm:_) _ _ _) ->
            assertBool
              ("expected op arm body to contain RApp of resume binder, got body: "
               <> show (Anf.oaBody arm))
              (opArmBodyHasResume arm)
          _ -> assertFailure ("expected Handle node, got: " <> show result)
  ]

-- ---------------------------------------------------------------------------
-- ElaborateModule tests

-- Build a small module with two top-level equations:
--   idf x = x
--   k = idf
-- and an Env whose envVars contains "idf" and "k".
-- Tests:
--   1. Two TopBinds named "idf" and "k".
--   2. idf has one param; body is Ret (AVar p) where p == the param binder.
--   3. k's body references the SAME canonical Name as idf's tbName.

elaborateModuleTests :: TestTree
elaborateModuleTests = testGroup "ElaborateModule"
  [ testCase "produces two TopBinds named idf and k" $ do
      let (idfBind, kBind) = buildElabModule
      nameHint (Anf.tbName idfBind) @?= T.pack "idf"
      nameHint (Anf.tbName kBind)   @?= T.pack "k"

  , testCase "idf has one param binder" $ do
      let (idfBind, _) = buildElabModule
      length (Anf.tbParams idfBind) @?= 1

  , testCase "idf body is Ret (AVar param): identity preserved" $ do
      let (idfBind, _) = buildElabModule
      case Anf.tbParams idfBind of
        [b] -> case Anf.tbBody idfBind of
          Anf.Ret (Anf.AVar n) -> n @?= Anf.bndName b
          other -> assertFailure ("expected Ret (AVar param), got: " <> show other)
        _ -> assertFailure "expected exactly one param binder"

  , testCase "k's body references the same canonical Name as idf's tbName" $ do
      let (idfBind, kBind) = buildElabModule
          idfName = Anf.tbName idfBind
      -- k = idf; body should be Ret (AVar idfName)
      case Anf.tbBody kBind of
        Anf.Ret (Anf.AVar n) -> n @?= idfName
        other -> assertFailure ("expected Ret (AVar idfName), got: " <> show other)
  ]

-- | Build the test module and return (idfBind, kBind).
buildElabModule :: (Anf.TopBind, Anf.TopBind)
buildElabModule =
  let -- idf x = x
      idfParam = Abs.APVar (varId (T.pack "x"))
      idfLhs   = Abs.LHSPre (Abs.FNBare (varId (T.pack "idf"))) [idfParam]
      idfBody  = Abs.EVar (varId (T.pack "x"))
      idfDecl  = Abs.DEqn idfLhs idfBody Abs.NoWhere
      -- k = idf
      kLhs  = Abs.LHSPre (Abs.FNBare (varId (T.pack "k"))) []
      kBody = Abs.EVar (varId (T.pack "idf"))
      kDecl = Abs.DEqn kLhs kBody Abs.NoWhere
      (envOut, tds) = typedModuleForTest B.initialEnv (Abs.Module [idfDecl, kDecl])
      cm = elaborateModule (T.pack "Main") Set.empty envOut tds
      binds = Anf.cmBinds cm
      idfBind = case filter (\b -> nameHint (Anf.tbName b) == T.pack "idf") binds of
                  (b:_) -> b
                  []    -> error "buildElabModule: idf bind not found"
      kBind   = case filter (\b -> nameHint (Anf.tbName b) == T.pack "k") binds of
                  (b:_) -> b
                  []    -> error "buildElabModule: k bind not found"
  in (idfBind, kBind)

typedAstTests :: TestTree
typedAstTests = testGroup "TypedAst"
  [ testCase "fmap/Foldable reach every annotation" $
      let e = Typed.Texp (1 :: Int) (Typed.TApp (Typed.Texp 2 (Typed.TVar (T.pack "f")))
                                                 [Typed.Texp 3 (Typed.TLitI 0)])
          e' = fmap (* 10) e
      in sum e' @?= (60 :: Int)   -- 10 + 20 + 30 over the three annotations
  , testCase "TQVar folds over its class-arg annotations" $
      let e = Typed.Texp (10 :: Int)
                (Typed.TQVar (T.pack "==") [(T.pack "Eq", 5)])
      in sum e @?= 15   -- node ann 10 + class-arg ann 5
  ]

-- | Parse-only coverage for the Eq type-class slice (Task 0): `class`/`instance`
-- declarations and `(C a) => T` qualified types parse into the new Abs nodes.
-- These are semantically ignored for now (no typechecking yet).
classParseTests :: TestTree
classParseTests = testGroup "ClassParse"
  [ testCase "class decl parses to DClass" $
      case parse (T.pack "module M\nclass Eq a where\n  (==) : a -> a -> Bool\n") of
        Right (Abs.Module ds) -> assertBool "expected a DClass" (any isDClass ds)
        Left e -> assertFailure ("parse: " ++ e)
  , testCase "instance decl parses to DInstance" $
      case parse (T.pack "module M\ninstance Eq U64 where\n  (==) = eqU64\n") of
        Right (Abs.Module ds) -> assertBool "expected a DInstance" (any isDInstance ds)
        Left e -> assertFailure ("parse: " ++ e)
  , testCase "instance with context parses to IHCtx" $
      case parse (T.pack "module M\ninstance (Eq a) => Eq (Option a) where\n  (==) x y = True\n") of
        Right (Abs.Module ds) -> assertBool "expected an IHCtx instance head" (any isCtxInstance ds)
        Left e -> assertFailure ("parse: " ++ e)
  , testCase "qualified sig parses to TQual" $
      case parse (T.pack "module M\nisEq : (Eq a) => a -> a -> Bool\n") of
        Right (Abs.Module ds) -> assertBool "expected a TQual in a DSig" (any sigHasQual ds)
        Left e -> assertFailure ("parse: " ++ e)
  ]
  where
    isDClass Abs.DClass{}    = True
    isDClass _               = False
    isDInstance Abs.DInstance{} = True
    isDInstance _               = False
    isCtxInstance (Abs.DInstance (Abs.IHCtx{}) _) = True
    isCtxInstance _                               = False
    sigHasQual (Abs.DSig _ _ (Abs.TQual _ _)) = True
    sigHasQual _                              = False

-- | Parse-only coverage for FFI Slice 2 (Task 1): `foreign module` declarations
-- parse into the DForeign AST node with correct ForeignFree / ForeignMember shapes.
-- No typechecking yet; semantic pass is a later task.
foreignModuleParseTests :: TestTree
foreignModuleParseTests = testGroup "ForeignModuleParse"
  [ testCase "plain member parses to FMPlain with FSNone" $
      case parse (T.pack src1) of
        Right (Abs.Module ds) -> assertBool "expected FMPlain memchr" (any hasMembPlain ds)
        Left e -> assertFailure ("parse: " ++ e)

  , testCase "owned member parses to FMOwned" $
      case parse (T.pack src2) of
        Right (Abs.Module ds) -> assertBool "expected FMOwned strndup" (any hasMembOwned ds)
        Left e -> assertFailure ("parse: " ++ e)

  , testCase "symbol-override member parses to FSName" $
      case parse (T.pack src3) of
        Right (Abs.Module ds) -> assertBool "expected FSName open64" (any hasMembSym ds)
        Left e -> assertFailure ("parse: " ++ e)

  , testCase "no-free clause parses to FFNone" $
      case parse (T.pack src4) of
        Right (Abs.Module ds) -> assertBool "expected FFNone header" (any hasFFNone ds)
        Left e -> assertFailure ("parse: " ++ e)

  , testCase "free clause parses to FFSym" $
      case parse (T.pack src5) of
        Right (Abs.Module ds) -> assertBool "expected FFSym free" (any hasFFSym ds)
        Left e -> assertFailure ("parse: " ++ e)

  , testCase "full foreign module round-trip: ConId, lib string, free, members" $
      case parse (T.pack srcFull) of
        Right (Abs.Module ds) ->
          case [ d | d@(Abs.DForeign{}) <- ds ] of
            [Abs.DForeign (Abs.ConId (_, cidText)) lib ffree mems] -> do
              cidText @?= T.pack "Libc"
              lib     @?= "c"
              ffree   @?= Abs.FFSym "free"
              length mems @?= 2
            other -> assertFailure ("expected exactly one DForeign, got: " ++ show other)
        Left e -> assertFailure ("parse: " ++ e)
  ]
  where
  -- plain member: memchr with no owned and no symbol override
  src1 = unlines
    [ "module M"
    , "foreign module Libc \"c\" free \"free\" where"
    , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
    ]
  hasMembPlain (Abs.DForeign _ _ _ mems) =
    any (\m -> case m of Abs.FMPlain _ Abs.FSNone _ -> True; _ -> False) mems
  hasMembPlain _ = False

  -- owned member
  src2 = unlines
    [ "module M"
    , "foreign module Libc \"c\" free \"free\" where"
    , "  owned strndup : Bytes -> U64 -> Bytes with IO"
    ]
  hasMembOwned (Abs.DForeign _ _ _ mems) =
    any (\m -> case m of Abs.FMOwned{} -> True; _ -> False) mems
  hasMembOwned _ = False

  -- symbol-override member: `open64 "open64" : ...`
  src3 = unlines
    [ "module M"
    , "foreign module Libc \"c\" where"
    , "  open64 \"open64\" : U64 -> U64 with IO"
    ]
  hasMembSym (Abs.DForeign _ _ _ mems) =
    any (\m -> case m of Abs.FMPlain _ (Abs.FSName _) _ -> True; _ -> False) mems
  hasMembSym _ = False

  -- no free clause
  src4 = unlines
    [ "module M"
    , "foreign module Posix \"c\" where"
    , "  write : U64 -> Bytes -> U64 with IO"
    ]
  hasFFNone (Abs.DForeign _ _ Abs.FFNone _) = True
  hasFFNone _                               = False

  -- with free clause
  src5 = unlines
    [ "module M"
    , "foreign module Libc \"c\" free \"free\" where"
    , "  strndup : Bytes -> U64 -> Bytes with IO"
    ]
  hasFFSym (Abs.DForeign _ _ (Abs.FFSym _) _) = True
  hasFFSym _                                   = False

  -- full round-trip source
  srcFull = unlines
    [ "module M"
    , "foreign module Libc \"c\" free \"free\" where"
    , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
    , "  owned strndup : Bytes -> U64 -> Bytes with IO"
    ]

-- | Typecheck-level coverage for FFI Slice 2 Task 3: foreign-module
-- registration, member resolution via the dotted projection arm, the blessed
-- allow-list honesty gate, and clean error reporting for each rejection case.
-- All programs are self-contained (no loader); run under `B.initialEnv` with
-- `SO.Embedded` origin so `Bytes`, `U64`, and `IO` are available.
foreignResolutionTests :: TestTree
foreignResolutionTests = testGroup "foreign resolution"
  [ -- AC1: Libc.memchr resolves to the declared arrow type; applying it emits IO.
    testCase "Libc.memchr resolves; caller's sig carries with IO" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "use_memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "use_memchr b n m = Libc.memchr b n m"
             ]
             "use_memchr" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC1 (emit IO): inferred sig WITHOUT annotation must carry with IO.
    testCase "Libc.memchr call infers IO in ambient row" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "call_memchr b n m = Libc.memchr b n m"
             ]
             "call_memchr" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right sch ->
          assertBool ("expected 'with IO' in inferred scheme, got: " ++ T.unpack sch)
            (T.pack "with IO" `T.isInfixOf` sch)

  , -- AC2: strndup with owned is recorded; the module still resolves.
    testCase "Libc.strndup (owned) resolves" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "call_strndup b n = Libc.strndup b n"
             ]
             "call_strndup" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC3: (\"c\", \"frob\") not in blessedTable -> ForeignSymbolNotBlessed.
    testCase "unlisted symbol gives ForeignSymbolNotBlessed" $
      case schemeOf
             [ "foreign module Bad \"c\" where"
             , "  frob : U64 -> U64 with IO"
             ]
             "frob" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignSymbolNotBlessed, got: " ++ err)
            ("ForeignSymbolNotBlessed" `isInfixOf` err)

  , -- AC4: unknown member -> ForeignModuleMemberUnknown.
    testCase "unknown member gives ForeignModuleMemberUnknown" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "bad x = Libc.nope x"
             ]
             "bad" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignModuleMemberUnknown, got: " ++ err)
            ("ForeignModuleMemberUnknown" `isInfixOf` err)

  , -- AC5: ConId is both an effect and a foreign module -> AmbiguousProjectionHead.
    testCase "ConId both effect and foreign module gives AmbiguousProjectionHead" $
      case schemeOf
             [ "effect Libc = { read : U64 -> U64 }"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             ]
             "Libc" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected AmbiguousProjectionHead, got: " ++ err)
            ("AmbiguousProjectionHead" `isInfixOf` err)

  , -- AC6: owned member with no free clause -> ForeignOwnedNeedsFree.
    testCase "owned member without free clause gives ForeignOwnedNeedsFree" $
      case schemeOf
             [ "foreign module Libc \"c\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             ]
             "Libc" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignOwnedNeedsFree, got: " ++ err)
            ("ForeignOwnedNeedsFree" `isInfixOf` err)

  , -- AC8: owned on a DispScalar member -> ForeignDispositionMismatch.
    --      memchr is blessed DispScalar, so `owned` must be rejected.
    testCase "owned memchr (DispScalar) gives ForeignDispositionMismatch" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  owned memchr : Bytes -> U64 -> U64 -> U64 with IO"
             ]
             "Libc" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignDispositionMismatch, got: " ++ err)
            ("ForeignDispositionMismatch" `isInfixOf` err)

  , -- AC9: strndup without owned (DispAdopt) -> ForeignDispositionMismatch.
    --      This is the divergence case: previously type-checked but diverged
    --      across backends at runtime. Must now be a compile error.
    testCase "strndup without owned (DispAdopt) gives ForeignDispositionMismatch" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  strndup : Bytes -> U64 -> Bytes with IO"
             ]
             "Libc" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignDispositionMismatch, got: " ++ err)
            ("ForeignDispositionMismatch" `isInfixOf` err)

  , -- AC10: correct memchr (no owned, DispScalar) must still type-check.
    testCase "memchr without owned (DispScalar) still resolves" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "use_memchr b n m = Libc.memchr b n m"
             ]
             "use_memchr" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC11: correct strndup (owned + free, DispAdopt) must still type-check.
    testCase "owned strndup with free clause (DispAdopt) still resolves" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "call_strndup b n = Libc.strndup b n"
             ]
             "call_strndup" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC7: non-foreign dotted projection (effect op) still resolves via the
    --      existing arm (no regression).
    testCase "effect-op dot still resolves after foreign-module arm added" $
      case schemeOf
             [ "effect State s = { get : () -> s, set : s -> () }"
             , "getter : State U64 -> U64 with State U64"
             , "getter h = h.get ()"
             ]
             "getter" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC7 cont.: record-field projection still resolves (no regression).
    testCase "record-field projection still resolves after foreign-module arm added" $
      case schemeOf
             [ "data Point = Point { x : U64, y : U64 }"
             , "getX : Point -> U64"
             , "getX p = p.x"
             ]
             "getX" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC12: two `foreign module Libc` in one file -> DuplicateForeignModule.
    -- Previously the second declaration silently overwrote the first via
    -- Map.insert, losing the first's members with no error. The duplicate
    -- check now rejects this before any registration occurs.
    testCase "duplicate foreign module declaration gives DuplicateForeignModule" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             ]
             "Libc" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected DuplicateForeignModule, got: " ++ err)
            ("DuplicateForeignModule" `isInfixOf` err)

  , -- AC13: partial application of a foreign member -> ForeignMemberPartialApp.
    -- Previously this produced a clean typecheck signature but crashed the
    -- elaborator with a Haskell `error`. Now the typechecker rejects it
    -- directly with a clean diagnostic.
    testCase "partial application of foreign member gives ForeignMemberPartialApp" $
      case schemeOf
             [ "import Bytes"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "bad b = let f = Libc.strndup in f b 2"
             ]
             "bad" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignMemberPartialApp, got: " ++ err)
            ("ForeignMemberPartialApp" `isInfixOf` err)

  , -- AC13 regression: direct fully-applied call must still succeed (AC2/AC11
    -- cover this; this test targets the EApp special-case path specifically).
    testCase "direct application Libc.strndup b n still type-checks (no regression)" $
      case schemeOf
             [ "import Bytes"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "call b n = Libc.strndup b n"
             ]
             "call" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

    -- -----------------------------------------------------------------------
    -- Findings #1+#2 (saturation check + paren-head): TDD tests written
    -- BEFORE the fix so they start failing and pass after.
    -- -----------------------------------------------------------------------

  , -- Finding #1: under-saturated call (let f = Libc.memchr buf in f 65 3)
    -- must be a COMPILE ERROR, not a runtime crash. The spine now has 1 arg
    -- at the intercept point; arity = 3; 1 < 3 => ForeignMemberPartialApp.
    testCase "#1: under-saturated memchr (1 of 3 args) gives ForeignMemberPartialApp" $
      case schemeOf
             [ "import Bytes"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "bad b = let f = Libc.memchr b in f 65 3"
             ]
             "bad" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignMemberPartialApp, got: " ++ err)
            ("ForeignMemberPartialApp" `isInfixOf` err)

  , -- Finding #1b: same for strndup (arity 2, 1 arg supplied).
    testCase "#1b: under-saturated strndup (1 of 2 args) gives ForeignMemberPartialApp" $
      case schemeOf
             [ "import Bytes"
             , "foreign module Libc \"c\" free \"free\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "bad b = let f = Libc.strndup b in f 2"
             ]
             "bad" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignMemberPartialApp, got: " ++ err)
            ("ForeignMemberPartialApp" `isInfixOf` err)

  , -- Finding #2: paren-wrapped saturated call must TYPE-CHECK and run.
    -- (Libc.memchr) buf 65 3 -> the paren does not prevent resolution.
    testCase "#2: paren-wrapped saturated memchr type-checks and runs" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
        , "main = (Libc.memchr) (fromList [65, 66, 67]) 65 3"
        ]
      result @?= Right (T.pack "0")

    -- -----------------------------------------------------------------------
    -- Finding #3 (wrong destructor symbol is a COMPILE error).
    -- -----------------------------------------------------------------------

  , -- Finding #3: free "pfree" + owned strndup must be rejected at compile
    -- time with a clear diagnostic (not crash at runtime).
    testCase "#3: non-free destructor in adopt module gives compile error" $
      case schemeOf
             [ "import Bytes"
             , "foreign module Libc \"c\" free \"pfree\" where"
             , "  owned strndup : Bytes -> U64 -> Bytes with IO"
             , "call b n = Libc.strndup b n"
             ]
             "call" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignDispositionMismatch or ForeignAdoptFreeMustBeFree, got: " ++ err)
            (("ForeignDispositionMismatch" `isInfixOf` err)
             || ("ForeignAdoptFree" `isInfixOf` err)
             || ("free" `isInfixOf` err))

    -- -----------------------------------------------------------------------
    -- FFI Slice 3 Task 4: the borrow disposition (a member whose return TYPE
    -- is `Borrow` -- no new keyword, unlike `owned`).
    -- -----------------------------------------------------------------------

  , -- AC14: a foreign-module member whose return type is `Borrow` resolves
    -- as the borrow disposition with no `owned` keyword involved. Mirrors
    -- AC10/AC11's "still resolves" shape for the new disposition.
    testCase "lendBuffer (Borrow return, no owned) resolves as the borrow disposition" $
      case schemeOf
             [ "extern type Borrow"
             , "foreign module Demo \"wok\" where"
             , "  lendBuffer : U64 -> Borrow with IO"
             , "call_lend n = Demo.lendBuffer n"
             ]
             "call_lend" of
        Left err -> assertFailure ("expected success, got: " ++ err)
        Right _  -> pure ()

  , -- AC15: `owned` on a DispBorrow member -> ForeignDispositionMismatch
    -- ("returns a borrowed view; remove `owned`") -- the same coherence
    -- machinery as AC8/AC9, exercising the new disposition's message arm.
    testCase "owned lendBuffer (DispBorrow) gives ForeignDispositionMismatch" $
      case schemeOf
             [ "extern type Borrow"
             , "foreign module Demo \"wok\" free \"free\" where"
             , "  owned lendBuffer : U64 -> Borrow with IO"
             ]
             "Demo" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignDispositionMismatch, got: " ++ err)
            ("ForeignDispositionMismatch" `isInfixOf` err)

  , -- AC16: a member blessed DispBorrow but declared with a NON-Borrow return
    -- type -> ForeignDispositionMismatch. Without this check the elaborator
    -- would still wrap the call's result as a 0xFFFA borrow view (the
    -- blessed table is authoritative for the runtime disposition) while the
    -- checked type says something else -- a backend-divergence soundness
    -- hole this AC pins shut at compile time.
    testCase "lendBuffer declared with a non-Borrow return gives ForeignDispositionMismatch" $
      case schemeOf
             [ "foreign module Demo \"wok\" where"
             , "  lendBuffer : U64 -> U64 with IO"
             ]
             "Demo" of
        Right s -> assertFailure ("expected rejection, got: " ++ T.unpack s)
        Left err ->
          assertBool ("expected ForeignDispositionMismatch, got: " ++ err)
            ("ForeignDispositionMismatch" `isInfixOf` err)
  ]
  where
    isInfixOf needle hay = needle `Data.List.isInfixOf` hay

-- | Helper: type-check a module at UserFile origin, returning the full
-- result (error or success) so tests can check both directions (gate-flip).
inferUserFile :: Text -> Either TErr.TypeError (TE.Env, [I.TypedDecl], [TErr.Warning])
inferUserFile src =
  case parse src of
    Left err -> error ("inferUserFile: parse: " ++ err)
    Right ast -> case reorderModule ast of
      Left es -> error ("inferUserFile: reorder: " ++ show es)
      Right rm -> TC.inferProgramWith B.initialEnv (SO.UserFile "<test>") (reorderedAst rm)

externGateTests :: TestTree
externGateTests = testGroup "extern gate"
  [ testCase "user file with foreign module type-checks (no ExternNotAllowed)" $
      let src = T.unlines
              [ T.pack "module Main"
              , T.pack "foreign module Libc \"c\" free \"free\" where"
              , T.pack "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
              , T.pack "use_memchr b n m = Libc.memchr b n m"
              ]
      in case inferUserFile src of
           Right _ -> pure ()
           Left err -> assertFailure ("expected success, got: " ++ show err)

  , testCase "user file with bare extern throws ExternNotAllowed" $
      let src = T.unlines
              [ T.pack "module Main"
              , T.pack "extern foo : U64 -> U64"
              , T.pack "main = foo 0"
              ]
      in case inferUserFile src of
           Left (TErr.ExternNotAllowed _ n) ->
             n @?= T.pack "foo"
           Left err -> assertFailure ("expected ExternNotAllowed, got: " ++ show err)
           Right _ -> assertFailure "expected ExternNotAllowed error, but type-checking succeeded"
  ]

classEnvTests :: TestTree
classEnvTests = testGroup "ClassEnv"
  [ testCase "register + lookup a class and its method" $
      let ci = TE.ClassInfo (0, Ty.KStar)
                 (Map.singleton (T.pack "==") eqScheme)
                 Map.empty [T.pack "=="] (T.pack "Eq$Dict")
          e  = TE.extendClass (T.pack "Eq") ci TE.emptyEnv
      in do TE.lookupClass (T.pack "Eq") e @?= Just ci
            TE.classOfMethod (T.pack "==") e @?= Just (T.pack "Eq")
  , testCase "register + lookup an instance" $
      let ii = TE.InstanceInfo (T.pack "Eq") (Ty.CTCon Ty.TcU64 []) []
                 (T.pack "dict$Eq$U64") Map.empty
          e  = TE.extendInstance ii TE.emptyEnv
      in TE.lookupInstances (T.pack "Eq") e @?= [ii]
  ]
  where
    eqScheme = Ty.Scheme [(0, Ty.KStar)] [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
                 (Ty.CTArr (Ty.CTGen 0) Ty.CREmpty
                   (Ty.CTArr (Ty.CTGen 0) Ty.CREmpty (Ty.CTCon Ty.TcBool [])))

-- | Parse a module body (prefixed with @module M@), then fold the class
-- registrar over all class decls and the instance registrar over all
-- instance decls, starting from 'B.initialEnv'. Class decls are processed
-- before instance decls so that an instance can see its class.
registerDecls :: Text -> Either TErr.TypeError TE.Env
registerDecls body =
  case parse (T.pack "module M\n" <> body) of
    Left e -> error ("registerDecls: parse: " ++ e)
    Right (Abs.Module ds) -> do
      e1 <- Control.Monad.foldM Class.processClassDecl B.initialEnv ds
      Control.Monad.foldM Class.processInstanceDecl e1 ds

-- | Register a module body and hand the resulting 'Env' to a callback,
-- failing the test if registration returns 'Left'.
withDecls :: Text -> (TE.Env -> Assertion) -> Assertion
withDecls body k = case registerDecls body of
  Left err  -> assertFailure ("expected successful registration, got: " ++ show err)
  Right env -> k env

-- | Assert that registering a module body fails (returns 'Left').
assertRejected :: Text -> Assertion
assertRejected body = case registerDecls body of
  Left _    -> pure ()
  Right _   -> assertFailure "expected registration to be rejected, but it succeeded"

classRegisterTests :: TestTree
classRegisterTests = testGroup "ClassRegister"
  [ testCase "class Eq registers method scheme with Eq constraint" $
      withDecls (T.pack "class Eq a where\n  (==) : a -> a -> Bool\n") $ \env ->
        case TE.lookupVar (T.pack "==") env of
          Just s  -> Ty.schemeConstraints s
                       @?= [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
          Nothing -> assertFailure "no == in env"
  , testCase "ground instance registers, ground dict name" $
      withDecls (T.pack "class Eq a where\n  (==) : a -> a -> Bool\ninstance Eq U64 where\n  (==) = eqU64\n") $ \env ->
        case TE.lookupInstances (T.pack "Eq") env of
          [i] -> TE.iiDictName i @?= T.pack "dict$Eq$U64"
          _   -> assertFailure "expected exactly one Eq instance"
  , testCase "non-smaller instance context rejected" $
      assertRejected (T.pack "class Eq a where\n  (==) : a -> a -> Bool\ninstance (Eq [a]) => Eq a where\n  (==) x y = True\n")
  , testCase "overlapping instance rejected" $
      assertRejected (T.pack "class Eq a where\n  (==) : a -> a -> Bool\ninstance Eq U64 where\n  (==) = eqU64\ninstance Eq U64 where\n  (==) = eqU64\n")
  ]

constraintAccumTests :: TestTree
constraintAccumTests = testGroup "ConstraintAccum"
  [ testCase "add then take returns in order, then empties" $
      let r = TM.runTC_ B.initialEnv $ do
                a <- TM.freshTVar Ty.KStar
                TM.addConstraint (T.pack "Eq") a
                cs1 <- TM.takeConstraints
                cs2 <- TM.takeConstraints
                pure (map TM.csClass cs1, length cs1, length cs2)
      in case r of
           Right t -> t @?= ([T.pack "Eq"], 1, 0)
           Left e  -> assertFailure (show e)
  ]

solveTests :: TestTree
solveTests = testGroup "Solve"
  [ testCase "ground instance -> EvGlobal" $
      Solve.resolve env Set.empty (T.pack "Eq") (Ty.CTCon Ty.TcU64 [])
        @?= Right (Ty.EvGlobal (T.pack "dict$Eq$U64"))
  , testCase "constrained instance over concrete -> EvApp of EvGlobal" $
      Solve.resolve env Set.empty (T.pack "Eq")
        (Ty.CTCon (Ty.TcUser (T.pack "Option")) [Ty.CTCon Ty.TcU64 []])
        @?= Right (Ty.EvApp (T.pack "dict$Eq$Option")
                            [Ty.EvGlobal (T.pack "dict$Eq$U64")])
  , testCase "quantified var in scope -> EvParam" $
      Solve.resolve env (Set.singleton 0) (T.pack "Eq") (Ty.CTGen 0)
        @?= Right (Ty.EvParam (T.pack "d$Eq$0"))
  , testCase "quantified var out of scope -> Ambiguous" $
      Solve.resolve env Set.empty (T.pack "Eq") (Ty.CTGen 0)
        @?= Left (Solve.Ambiguous (T.pack "Eq"))
  , testCase "no instance -> NoInst" $
      Solve.resolve env Set.empty (T.pack "Eq") (Ty.CTCon Ty.TcString [])
        @?= Left (Solve.NoInst (T.pack "Eq") (Ty.CTCon Ty.TcString []))
  ]
  where
    env = TE.extendInstance optInst (TE.extendInstance u64Inst TE.emptyEnv)
    u64Inst = TE.InstanceInfo
                (T.pack "Eq")
                (Ty.CTCon Ty.TcU64 [])
                []
                (T.pack "dict$Eq$U64")
                Map.empty
    optInst = TE.InstanceInfo
                (T.pack "Eq")
                (Ty.CTCon (Ty.TcUser (T.pack "Option")) [Ty.CTGen 0])
                [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
                (T.pack "dict$Eq$Option")
                Map.empty

-- | End-to-end inference of the Eq type-class slice: qualified signatures,
-- constraint emission at use-sites, and top-level discharge. Each snippet is
-- prefixed with a minimal Eq class + an `Eq U64` instance (and an `eqU64`
-- bodyless sig so the instance impl typechecks), then run through the full
-- parse -> reorder -> inferProgramWith pipeline so registration, inference, and
-- discharge all execute together.
eqInferTests :: TestTree
eqInferTests = testGroup "EqInfer"
  [ testCase "1 == 2 : Bool" $
      case eqInferDecl (T.pack "main") (T.pack "main = 1 == 2") of
        Left e  -> assertFailure ("typecheck: " ++ show e)
        Right d -> do
          -- The constraint Eq U64 resolves to an instance, so main's scheme is
          -- monomorphic Bool with no residual constraints or evidence.
          Ty.schemeBody (I.tdScheme d) @?= Ty.CTCon Ty.TcBool []
          Ty.schemeConstraints (I.tdScheme d) @?= []
          I.tdEvidence d @?= []
  , testCase "isEq : forall a.(Eq a)=> a->a->Bool with evidence param" $
      case eqInferDecl (T.pack "isEq") (T.pack "isEq x y = x == y") of
        Left e  -> assertFailure ("typecheck: " ++ show e)
        Right d -> do
          Ty.schemeConstraints (I.tdScheme d)
            @?= [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
          map fst (I.tdEvidence d) @?= [T.pack "d$Eq$0"]
  , testCase "no instance for Eq String errors" $
      case eqInferModule (T.pack "bad = \"a\" == \"b\"") of
        Left _  -> pure ()
        Right _ -> assertFailure "expected NoInstance error for Eq String"
  , testCase "ambiguous constraint errors" $
      case eqInferModule (T.pack "amb : (Eq a) => Bool\namb = True") of
        Left _  -> pure ()
        Right _ -> assertFailure "expected AmbiguousConstraint error"
  , -- Regression guard (signed-path entailment must check the ARGUMENT, not
    -- merely the class name): the body needs Eq b but the declared context only
    -- promises Eq a, so this is under-entailed and must be REJECTED.
    testCase "under-entailed signed binding rejected (Eq a sig, body needs Eq b)" $
      case eqInferModule
             (T.pack "f : (Eq a) => a -> b -> Bool\nf x y = y == y") of
        Left _  -> pure ()
        Right _ -> assertFailure
          "expected rejection: body uses (==) on b but sig only provides Eq a"
  , -- A ground signed binding whose only Eq use is on U64 discharges to a
    -- concrete instance: no residual constraint, no evidence parameter.
    testCase "ground signed binding using == on U64 succeeds, no evidence" $
      case eqInferDecl (T.pack "g") (T.pack "g : U64 -> Bool\ng x = x == 0") of
        Left e  -> assertFailure ("typecheck: " ++ show e)
        Right d -> do
          Ty.schemeConstraints (I.tdScheme d) @?= []
          I.tdEvidence d @?= []
  ]
  where
    -- Minimal Eq prelude: fixity decls so the reorderer accepts (==)/(/=),
    -- a Bool datatype, a bodyless eqU64 (so the instance impl checks), and a
    -- single-parameter Eq class with an Eq U64 instance implementing both
    -- methods (the completeness check requires every method to be implemented).
    preludeEq =
      T.concat
        [ T.pack "fixity == left\n"
        , T.pack "fixity /= left\n"
        , T.pack "data Bool = True | False\n"
        , T.pack "eqU64 : U64 -> U64 -> Bool\n"
        , T.pack "class Eq a where\n"
        , T.pack "  (==) : a -> a -> Bool\n"
        , T.pack "  (/=) : a -> a -> Bool\n"
        , T.pack "instance Eq U64 where\n"
        , T.pack "  (==) = eqU64\n"
        , T.pack "  (/=) = eqU64\n"
        ]

    -- Parse + reorder + infer a module built from the Eq prelude plus the
    -- given body. Returns all TypedDecls or the type error.
    eqInferModule :: Text -> Either TErr.TypeError [I.TypedDecl]
    eqInferModule body =
      let src = T.concat [T.pack "module M\n", preludeEq, body, T.pack "\n"]
      in case parse src of
           Left e -> error ("EqInfer parse: " ++ e)
           Right ast -> case reorderModule ast of
             Left es -> error ("EqInfer reorder: " ++ show es)
             Right rm ->
               case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
                 Left e             -> Left e
                 Right (_, ds, _ws) -> Right ds

    -- Run 'eqInferModule' and pick out the named TypedDecl.
    eqInferDecl :: Text -> Text -> Either TErr.TypeError I.TypedDecl
    eqInferDecl name body = do
      ds <- eqInferModule body
      case [ d | d <- ds, I.tdName d == name ] of
        (d : _) -> Right d
        []      -> error ("EqInfer: no TypedDecl named " ++ T.unpack name)

-- | Synthetic instance desugaring (Task 9): each instance produces real
-- typed dict bindings via the existing inference pipeline. We infer a module
-- with an `Eq U64` (ground) and an `Eq (Option a)` (constrained) instance and
-- assert the resulting dict TypedDecls have the right schemes and evidence.
eqDesugarTests :: TestTree
eqDesugarTests = testGroup "EqDesugar"
  [ testCase "dict$Eq$U64 has scheme `Eq U64`, no constraints, no evidence" $
      case desugarModule of
        Left e   -> assertFailure ("typecheck: " ++ show e)
        Right ds -> case findDecl (T.pack "dict$Eq$U64") ds of
          Nothing -> assertFailure "no dict$Eq$U64 TypedDecl"
          Just d  -> do
            Ty.schemeBody (I.tdScheme d)
              @?= Ty.CTCon (Ty.TcUser (T.pack "Eq")) [Ty.CTCon Ty.TcU64 []]
            Ty.schemeConstraints (I.tdScheme d) @?= []
            I.tdEvidence d @?= []
  , testCase "dict$Eq$Option has (Eq a) constraint + an Eq evidence param" $
      case desugarModule of
        Left e   -> assertFailure ("typecheck: " ++ show e)
        Right ds -> case findDecl (T.pack "dict$Eq$Option") ds of
          Nothing -> assertFailure "no dict$Eq$Option TypedDecl"
          Just d  -> do
            Ty.schemeConstraints (I.tdScheme d)
              @?= [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
            map fst (I.tdEvidence d) @?= [T.pack "d$Eq$0"]
  , testCase "method-synth bindings dict$Eq$U64$m0 / $m1 exist" $
      case desugarModule of
        Left e   -> assertFailure ("typecheck: " ++ show e)
        Right ds -> do
          assertBool "missing dict$Eq$U64$m0"
            (any ((== T.pack "dict$Eq$U64$m0") . I.tdName) ds)
          assertBool "missing dict$Eq$U64$m1"
            (any ((== T.pack "dict$Eq$U64$m1") . I.tdName) ds)
  , -- C1 regression: a signed binding whose body yields a constraint with a
    -- declared skolem NESTED UNDER a type constructor (`Eq (Option a)` from
    -- `(Some x) == (Some x)`). This previously CRASHED in `freeze` on the
    -- embedded Rigid; the declared `(Eq a) =>` promises `Eq a`, and the
    -- `instance (Eq a) => Eq (Option a)` makes `Eq (Option a)` entailed, so it
    -- must TYPECHECK with `schemeConstraints = [Eq (CTGen 0)]` and a `d$Eq$0`.
    testCase "signed `Eq (Option a)` constraint entailed (skolem under tycon)" $
      case desugarModuleWith
             (T.pack "f : (Eq a) => a -> Bool\nf x = (Some x) == (Some x)\n") of
        Left e   -> assertFailure ("typecheck: " ++ show e)
        Right ds -> case findDecl (T.pack "f") ds of
          Nothing -> assertFailure "no f TypedDecl"
          Just d  -> do
            Ty.schemeConstraints (I.tdScheme d)
              @?= [Ty.Constraint (T.pack "Eq") (Ty.CTGen 0)]
            map fst (I.tdEvidence d) @?= [T.pack "d$Eq$0"]
  ]
  where
    findDecl n ds = case [ d | d <- ds, I.tdName d == n ] of
      (d : _) -> Just d
      []      -> Nothing

    -- Fixities, Bool, Option, a bodyless eqU64, not, the Eq class with a (/=)
    -- default, a ground Eq U64 instance, and a constrained Eq (Option a).
    desugarSrc =
      T.concat
        [ T.pack "module M\n"
        , T.pack "fixity == left\n"
        , T.pack "fixity /= left\n"
        , T.pack "data Bool = True | False\n"
        , T.pack "data Option a = None | Some a\n"
        , T.pack "eqU64 : U64 -> U64 -> Bool\n"
        , T.pack "not : Bool -> Bool\n"
        , T.pack "class Eq a where\n"
        , T.pack "  (==) : a -> a -> Bool\n"
        , T.pack "  (/=) : a -> a -> Bool\n"
        , T.pack "  (/=) x y = not (x == y)\n"
        , T.pack "instance Eq U64 where\n"
        , T.pack "  (==) = eqU64\n"
        , T.pack "instance (Eq a) => Eq (Option a) where\n"
        , T.pack "  (==) x y = case (x, y) of\n"
        , T.pack "    (None, None) -> True\n"
        , T.pack "    (Some a, Some b) -> a == b\n"
        , T.pack "    _ -> False\n"
        ]

    desugarModule :: Either TErr.TypeError [I.TypedDecl]
    desugarModule = desugarModuleWith (T.pack "")

    -- Like 'desugarModule', but appends an extra declaration body to the
    -- shared Eq+Option prelude before inferring.
    desugarModuleWith :: Text -> Either TErr.TypeError [I.TypedDecl]
    desugarModuleWith extra =
      case parse (T.append desugarSrc extra) of
        Left e -> error ("EqDesugar parse: " ++ e)
        Right ast -> case reorderModule ast of
          Left es -> error ("EqDesugar reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
              Left e             -> Left e
              Right (_, ds, _ws) -> Right ds

-- | End-to-end elaboration of a minimal Eq program (Task 10): parse -> reorder
-- -> infer -> elaborate, then assert the ANF shape of the desugared dictionary
-- bind and the case-projecting method dispatch in `main = 1 == 2`.
eqElaborateTests :: TestTree
eqElaborateTests = testGroup "ElaborateClass"
  [ testCase "dict$Eq$U64 is a 0-arity TopBind constructing Eq$Dict" $
      withElab $ \cm ->
        case findBind (T.pack "dict$Eq$U64") cm of
          Nothing -> assertFailure "no dict$Eq$U64 TopBind"
          Just tb -> do
            Anf.tbParams tb @?= []
            assertBool "dict$Eq$U64 body does not construct Eq$Dict"
              (buildsCon (T.pack "Eq$Dict") (Anf.tbBody tb))
  , testCase "main = 1 == 2 lowers `==` to a Case-project + apply" $
      withElab $ \cm ->
        case findBind (T.pack "main") cm of
          Nothing -> assertFailure "no main TopBind"
          Just tb ->
            case findMethodDispatch (Anf.tbBody tb) of
              Nothing -> assertFailure
                ("main body has no Eq$Dict Case-project+apply; body:\n"
                  ++ show (Anf.tbBody tb))
              Just () -> pure ()
  ]
  where
    src =
      T.concat
        [ T.pack "module M\n"
        , T.pack "fixity == left\n"
        , T.pack "data Bool = True | False\n"
        , T.pack "eqU64 : U64 -> U64 -> Bool\n"
        , T.pack "class Eq a where\n"
        , T.pack "  (==) : a -> a -> Bool\n"
        , T.pack "instance Eq U64 where\n"
        , T.pack "  (==) = eqU64\n"
        , T.pack "main = 1 == 2\n"
        ]

    withElab :: (Anf.CoreModule -> Assertion) -> Assertion
    withElab k =
      case parse src of
        Left e -> assertFailure ("ElaborateClass parse: " ++ e)
        Right ast -> case reorderModule ast of
          Left es -> assertFailure ("ElaborateClass reorder: " ++ show es)
          Right rm ->
            case TC.inferProgramWith B.initialEnv SO.Embedded (reorderedAst rm) of
              Left e            -> assertFailure ("ElaborateClass typecheck: " ++ show e)
              Right (env, ds, _) -> k (elaborateModule (T.pack "Main") Set.empty env ds)

    findBind :: Text -> Anf.CoreModule -> Maybe Anf.TopBind
    findBind n (Anf.CoreModule binds) =
      case [ tb | tb <- binds, Name.nameHint (Anf.tbName tb) == n ] of
        (tb : _) -> Just tb
        []       -> Nothing

    -- Does this Expr (anywhere down the let-chain / tail) emit an RCon for `c`?
    buildsCon :: Text -> Anf.Expr -> Bool
    buildsCon c expr = case expr of
      Anf.Let _ (Anf.RCon c' _) _ | c' == c -> True
      Anf.Let _ _ body                       -> buildsCon c body
      Anf.LetRec _ body                      -> buildsCon c body
      Anf.LetJoin _ _ j body                 -> buildsCon c j || buildsCon c body
      Anf.Case _ alts                        -> any (buildsCon c . altBody) alts
      _                                      -> False

    altBody :: Anf.Alt -> Anf.Expr
    altBody (Anf.AltCon _ _ e)  = e
    altBody (Anf.AltLit _ e)    = e
    altBody (Anf.AltDefault e)  = e

    -- Find a Case over a dict scrutinee that matches the Eq$Dict constructor,
    -- binds the method fields, and applies field 0 (the `==` method) to args.
    findMethodDispatch :: Anf.Expr -> Maybe ()
    findMethodDispatch expr = case expr of
      Anf.Case _ [Anf.AltCon con fbs body]
        | con == T.pack "Eq$Dict"
        , (f0 : _) <- map Anf.bndName fbs
        , appliesField f0 body -> Just ()
      Anf.Case _ alts   -> firstJust (map (findMethodDispatch . altBody) alts)
      Anf.Let _ _ body  -> findMethodDispatch body
      Anf.LetRec _ body -> findMethodDispatch body
      Anf.LetJoin _ _ j body ->
        firstJust [findMethodDispatch j, findMethodDispatch body]
      _ -> Nothing

    -- The field-0 method var is applied to two literal args somewhere in body.
    appliesField :: Name.Name -> Anf.Expr -> Bool
    appliesField f expr = case expr of
      Anf.Let _ (Anf.RApp (Anf.AVar g) _) _ | g == f -> True
      Anf.Ret _              -> False
      Anf.Let _ _ body       -> appliesField f body
      Anf.LetRec _ body      -> appliesField f body
      Anf.LetJoin _ _ j body -> appliesField f j || appliesField f body
      Anf.Case _ alts        -> any (appliesField f . altBody) alts
      _                      -> False

    firstJust :: [Maybe a] -> Maybe a
    firstJust = Data.Maybe.listToMaybe . Data.Maybe.catMaybes

matchCompilerTests :: TestTree
matchCompilerTests = testGroup "MatchCompiler"
  [ testCase "single constructor column: one Case, complete signature, no default" $ do
      let oracle = M.ConOracle
            { M.coArity = \t -> if t == T.pack "Some" then 1 else 0
            , M.coSiblings = \_ -> Just [T.pack "None", T.pack "Some"] }
          ty = Ty.CTCon Ty.TcUnit []
          j0 = Name.JoinId (Name.Unique 100)
          j1 = Name.JoinId (Name.Unique 101)
          rows =
            [ M.Row [M.MPat ty (M.MCon (T.pack "None") [])] [] j0 [] 0
            , M.Row [M.MPat ty (M.MCon (T.pack "Some")
                       [M.MPat ty (M.MVar (Just (T.pack "x")))])] [] j1 [T.pack "x"] 1 ]
          expr = runFresh
            (M.compileMatch oracle [Anf.AVar (Name.Name (T.pack "m") (Name.Unique 1))] rows)
      case expr of
        Anf.Case _ alts -> do
          length alts @?= 2
          [ () | Anf.AltDefault _ <- alts ] @?= []
          -- Assert None alt routes to j0 with no atoms.
          case [ body | Anf.AltCon c [] body <- alts, c == T.pack "None" ] of
            [body] -> body @?= Anf.Jump j0 []
            _      -> assertFailure "expected AltCon \"None\" [] ..."
          -- Assert Some alt binds the field and routes to j1 with that atom.
          case [ (fieldBinder, body)
               | Anf.AltCon c [fieldBinder] body <- alts, c == T.pack "Some" ] of
            [(fieldBinder, body)] ->
              body @?= Anf.Jump j1 [Anf.AVar (Anf.bndName fieldBinder)]
            _ -> assertFailure "expected AltCon \"Some\" [_] ..."
        other -> assertFailure ("expected Case, got: " ++ show other)

  , testCase "two columns: nested Case with cross-clause fallthrough" $ do
      let oracle = M.ConOracle
            { M.coArity = \t -> if t == T.pack "Cons" then 2 else 0
            , M.coSiblings = \_ -> Just [T.pack "Nil", T.pack "Cons"] }
          ty = Ty.CTCon Ty.TcUnit []
          v  s = M.MPat ty (M.MVar (Just (T.pack s)))
          cons h t = M.MPat ty (M.MCon (T.pack "Cons") [h, t])
          wild = M.MPat ty (M.MVar Nothing)
          jA = Name.JoinId (Name.Unique 200)
          jB = Name.JoinId (Name.Unique 201)
          rows =
            [ M.Row [cons (v "x") (v "xs"), cons (v "y") (v "ys")] []
                    jA [T.pack "x", T.pack "xs", T.pack "y", T.pack "ys"] 0
            , M.Row [wild, wild] [] jB [] 1 ]
          a1 = Anf.AVar (Name.Name (T.pack "a") (Name.Unique 1))
          a2 = Anf.AVar (Name.Name (T.pack "b") (Name.Unique 2))
          expr = runFresh (M.compileMatch oracle [a1, a2] rows)
          jumps = collectJumps expr
      case expr of
        Anf.Case _ alts -> assertBool "nested Case present" (any isNestedCase alts)
        other -> assertFailure ("expected Case, got: " ++ show other)
      assertBool "jA reachable via Cons/Cons clause" (jA `elem` jumps)
      assertBool "jB reachable via wildcard fallthrough" (jB `elem` jumps)

  , testCase "literal column tests constructor once then switches literal" $ do
      let oracle = M.ConOracle
            { M.coArity = \t -> if t == T.pack "Just" then 1 else 0
            , M.coSiblings = \_ -> Just [T.pack "Just", T.pack "Nothing"] }
          ty = Ty.CTCon Ty.TcUnit []
          just p = M.MPat ty (M.MCon (T.pack "Just") [p])
          lit0 = M.MPat ty (M.MLit (Anf.LInt 0))
          wild = M.MPat ty (M.MVar Nothing)
          none = M.MPat ty (M.MCon (T.pack "Nothing") [])
          j0 = Name.JoinId (Name.Unique 300)
          j1 = Name.JoinId (Name.Unique 301)
          j2 = Name.JoinId (Name.Unique 302)
          rows =
            [ M.Row [just lit0] [] j0 [] 0
            , M.Row [just wild] [] j1 [] 1
            , M.Row [none]      [] j2 [] 2 ]
          a1 = Anf.AVar (Name.Name (T.pack "m") (Name.Unique 1))
          expr = runFresh (M.compileMatch oracle [a1] rows)
      case expr of
        Anf.Case _ alts -> case [ e | Anf.AltCon c _ e <- alts, c == T.pack "Just" ] of
          (Anf.Case _ inner : _) ->
            assertBool "inner switch is on a literal"
              (any (\x -> case x of Anf.AltLit _ _ -> True; _ -> False) inner)
          _ -> assertFailure "expected a nested Case under AltCon Just"
        other -> assertFailure ("expected Case, got: " ++ show other)
  ]
  where
    isNestedCase (Anf.AltCon _ _ (Anf.Case _ _)) = True
    isNestedCase _                               = False

    -- Recursively collect all Jump targets in an Expr.
    collectJumps :: Anf.Expr -> [Name.JoinId]
    collectJumps (Anf.Jump j _)         = [j]
    collectJumps (Anf.Ret _)            = []
    collectJumps (Anf.Let _ rhs e)      = collectJumpsRhs rhs ++ collectJumps e
    collectJumps (Anf.LetRec defs e)    = concatMap (\(_,_,b) -> collectJumps b) defs ++ collectJumps e
    collectJumps (Anf.LetJoin _ _ jb e) = collectJumps jb ++ collectJumps e
    collectJumps (Anf.Case _ alts)      = concatMap collectJumpsAlt alts
    collectJumps (Anf.Handle e h)       =
      collectJumps e
        ++ collectJumps (snd (Anf.hReturn h))
        ++ concatMap (collectJumps . Anf.oaBody) (Anf.hOps h)
    collectJumps (Anf.InstallHandler _ _ e) = collectJumps e

    collectJumpsRhs :: Anf.Rhs -> [Name.JoinId]
    collectJumpsRhs (Anf.RLam _ e) = collectJumps e
    collectJumpsRhs _              = []

    collectJumpsAlt :: Anf.Alt -> [Name.JoinId]
    collectJumpsAlt (Anf.AltCon _ _ e)  = collectJumps e
    collectJumpsAlt (Anf.AltLit _ e)    = collectJumps e
    collectJumpsAlt (Anf.AltDefault e)  = collectJumps e

matchCoverageTests :: TestTree
matchCoverageTests = testGroup "MatchCoverage"
  [ testCase "single partial clause is non-exhaustive" $ do
      let oracle = M.ConOracle
            { M.coArity = \t -> if t == T.pack "Cons" then 2 else 0
            , M.coSiblings = \_ -> Just [T.pack "Nil", T.pack "Cons"] }
          ty = Ty.CTCon Ty.TcUnit []
          cons = M.MPat ty (M.MCon (T.pack "Cons")
                   [M.MPat ty (M.MVar (Just (T.pack "x")))
                   ,M.MPat ty (M.MVar (Just (T.pack "xs")))])
          rows = [ M.Row [cons] [] (Name.JoinId (Name.Unique 1)) [T.pack "x", T.pack "xs"] 0 ]
          cov  = M.matchCoverage oracle 1 rows
      M.covExhaustive cov @?= False
      M.covRedundant cov @?= []

  , testCase "full finite signature is exhaustive" $ do
      let oracle = M.ConOracle
            { M.coArity = \t -> if t == T.pack "Cons" then 2 else 0
            , M.coSiblings = \_ -> Just [T.pack "Nil", T.pack "Cons"] }
          ty = Ty.CTCon Ty.TcUnit []
          nil  = M.MPat ty (M.MCon (T.pack "Nil") [])
          cons = M.MPat ty (M.MCon (T.pack "Cons")
                   [M.MPat ty (M.MVar Nothing), M.MPat ty (M.MVar Nothing)])
          rows = [ M.Row [nil]  [] (Name.JoinId (Name.Unique 1)) [] 0
                 , M.Row [cons] [] (Name.JoinId (Name.Unique 2)) [] 1 ]
          cov  = M.matchCoverage oracle 1 rows
      M.covExhaustive cov @?= True
      M.covRedundant cov @?= []

  , testCase "redundant later clause under an all-var clause" $ do
      let oracle = M.ConOracle { M.coArity = const 0, M.coSiblings = \_ -> Just [T.pack "A"] }
          ty = Ty.CTCon Ty.TcUnit []
          wild = M.MPat ty (M.MVar Nothing)
          a    = M.MPat ty (M.MCon (T.pack "A") [])
          rows = [ M.Row [wild] [] (Name.JoinId (Name.Unique 1)) [] 0
                 , M.Row [a]    [] (Name.JoinId (Name.Unique 2)) [] 1 ]
          cov  = M.matchCoverage oracle 1 rows
      M.covExhaustive cov @?= True
      M.covRedundant cov @?= [1]

  , testCase "literal column is non-exhaustive" $ do
      let oracle = M.ConOracle { M.coArity = const 0, M.coSiblings = \_ -> Nothing }
          ty = Ty.CTCon Ty.TcUnit []
          l0 = M.MPat ty (M.MLit (Anf.LInt 0))
          rows = [ M.Row [l0] [] (Name.JoinId (Name.Unique 1)) [] 0 ]
          cov  = M.matchCoverage oracle 1 rows
      M.covExhaustive cov @?= False
  ]

multiplicityUnitTests :: TestTree
multiplicityUnitTests = testGroup "multiplicity (unit)"
  [ testGroup "lattice"
      [ testCase "addC One One = Many"    $ Mult.addC One One    @?= Many
      , testCase "addC Zero One = One"    $ Mult.addC Zero One   @?= One
      , testCase "addC One Many = Many"   $ Mult.addC One Many   @?= Many
      , testCase "joinC One One = One"    $ Mult.joinC One One   @?= One
      , testCase "joinC Zero Many = Many" $ Mult.joinC Zero Many @?= Many
      , testCase "joinC Zero Zero = Zero" $ Mult.joinC Zero Zero @?= Zero
      ]
  , testGroup "cardOf"
      [ testCase "drop (no resume) = Zero" $
          Mult.cardOf trustedSusp kName (Ret unit) @?= Zero
      , testCase "single direct resume = One" $
          Mult.cardOf trustedSusp kName resumeOnce @?= One
      , testCase "two sequenced resumes = Many" $
          Mult.cardOf trustedSusp kName resumeTwiceSeq @?= Many
      , testCase "resume in two case arms = One (branch join)" $
          Mult.cardOf trustedSusp kName resumeInBothArms @?= One
      , testCase "continuation returned = Many (escape)" $
          Mult.cardOf trustedSusp kName (Ret (AVar kName)) @?= Many
      , testCase "continuation passed to a call = Many (escape)" $
          Mult.cardOf trustedSusp kName escapeIntoCall @?= Many
      , testCase "continuation captured in a closure = Many" $
          Mult.cardOf trustedSusp kName escapeIntoLam @?= Many
      , testCase "continuation in LetRec body = Many" $
          Mult.cardOf trustedSusp kName escapeIntoLetRec @?= Many
      , testCase "resume inside a nested Handle arm = Many" $
          Mult.cardOf trustedSusp kName handleArmCapture @?= Many
      , testCase "jump to an unknown join = Many" $
          Mult.cardOf trustedSusp kName (Jump (JoinId (Unique 50)) []) @?= Many
      , testCase "resume in a join reached from two case arms = One" $
          Mult.cardOf trustedSusp kName joinFromTwoArms @?= One
      , testCase "genuine __coro_susp with resume binder = One (trusted-once)" $
          Mult.cardOf trustedSusp kName coroSuspResume @?= One
      , testCase "spoofed __coro_susp (distinct identity) = Many (C2)" $
          Mult.cardOf trustedSusp kName spoofCoroSuspResume @?= Many
      , testCase "genuine __coro_susp but empty trusted set = Many" $
          Mult.cardOf Set.empty kName coroSuspResume @?= Many
      , testCase "non-coro_susp call with resume binder = Many (control)" $
          Mult.cardOf trustedSusp kName fooCallResume @?= Many
      ]
  , testGroup "cardOfWithTrust (inter-procedural)"
      [ testCase "helper trusted One in slot 0 -> direct k pass = One" $
          Mult.cardOfWithTrust trustedSusp (Map.fromList [(helperUniq, [One])]) Map.empty
            kName callHelperWithK @?= One
      , testCase "helper trusted Many in slot 0 -> Many (relaxation no-op)" $
          Mult.cardOfWithTrust trustedSusp (Map.fromList [(helperUniq, [Many])]) Map.empty
            kName callHelperWithK @?= Many
      , testCase "helper absent from trust map -> Many (catch-all)" $
          Mult.cardOfWithTrust trustedSusp Map.empty Map.empty kName callHelperWithK @?= Many
      , testCase "k passed to two One-slots in one call = Many (addC)" $
          Mult.cardOfWithTrust trustedSusp (Map.fromList [(helperUniq, [One, One])]) Map.empty
            kName callHelperWithKK @?= Many
      , testCase "partial application of trusted helper to k = Many (escape, saturation guard)" $
          -- helper has arity 2 (trust [One, One]) but is applied to ONLY k: that
          -- partial app CAPTURES k into the closure f rather than consuming it.
          -- The two later f n calls re-invoke the captured continuation. Clause B
          -- must NOT fire (length as 1 != length cs 2) -> falls through to Many.
          Mult.cardOfWithTrust trustedSusp (Map.fromList [(helperUniq, [One, One])]) Map.empty
            kName partialHelperEscape @?= Many
      ]
  , testGroup "analyzeModule"
      [ testCase "clean module = no errors" $
          Mult.analyzeModule Set.empty (modWith resumeOnceArm) @?= []
      , testCase "multishot arm = one error" $
          Mult.analyzeModule Set.empty (modWith multishotArm)
            @?= [Mult.MultishotResume (T.pack "Choice") (T.pack "flip")]
      ]
  ]
  where
    kName  = Name (T.pack "k") (Unique 1)
    fName  = Name (T.pack "f") (Unique 2)
    ty     = Ty.CTCon Ty.TcUnit []
    bnd n  = Binder n Unrestricted ty
    unit   = ALit LUnit
    resumeOnce = Let (bnd (Name (T.pack "r") (Unique 10)))
                     (RApp (AVar kName) [unit]) (Ret unit)
    resumeTwiceSeq =
      Let (bnd (Name (T.pack "a") (Unique 11))) (RApp (AVar kName) [unit])
        (Let (bnd (Name (T.pack "b") (Unique 12))) (RApp (AVar kName) [unit])
          (Ret unit))
    resumeInBothArms =
      Case (ALit (LInt 0))
        [ AltCon (T.pack "A") [] resumeOnce
        , AltCon (T.pack "B") [] resumeOnce ]
    escapeIntoCall =
      Let (bnd (Name (T.pack "c") (Unique 13)))
          (RApp (AVar fName) [AVar kName]) (Ret unit)
    escapeIntoLam =
      Let (bnd (Name (T.pack "g") (Unique 14)))
          (RLam [bnd (Name (T.pack "x") (Unique 15))]
                (Let (bnd (Name (T.pack "r2") (Unique 16)))
                     (RApp (AVar kName) [AVar (Name (T.pack "x") (Unique 15))])
                     (Ret unit)))
          (Ret unit)
    escapeIntoLetRec =
      LetRec [ ( bnd (Name (T.pack "loop") (Unique 17))
               , [bnd (Name (T.pack "x") (Unique 18))]
               , Let (bnd (Name (T.pack "r3") (Unique 19)))
                     (RApp (AVar kName) [unit]) (Ret unit) ) ]
             (Ret unit)
    handleArmCapture =
      Handle (Ret unit)
        (Handler (bnd (Name (T.pack "v") (Unique 20)), Ret unit)
          [ OpArm (T.pack "E") (T.pack "op") []
              (bnd (Name (T.pack "rk") (Unique 21)))
              (Let (bnd (Name (T.pack "r4") (Unique 22)))
                   (RApp (AVar kName) [unit]) (Ret unit)) ]
          Nothing Nothing Nothing)
    joinFromTwoArms =
      LetJoin (JoinId (Unique 60)) []
        (Let (bnd (Name (T.pack "r5") (Unique 61)))
             (RApp (AVar kName) [unit]) (Ret unit))
        (Case (ALit (LInt 0))
          [ AltCon (T.pack "A") [] (Jump (JoinId (Unique 60)) [])
          , AltCon (T.pack "B") [] (Jump (JoinId (Unique 60)) []) ])
    handlerWith oa =
      Handler (bnd (Name (T.pack "v") (Unique 90)), Ret unit) [oa] Nothing Nothing Nothing
    modWith oa =
      CoreModule [ TopBind (Name (T.pack "main") (Unique 91)) []
                     (Handle (Ret unit) (handlerWith oa)) ]
    -- Trusted-once relaxation: handing the resume binder to a GENUINE once-sink
    -- extern (__coro_susp) counts as One. The relaxation keys on the call head
    -- being an APrim whose qualified (module, name) identity is in the trusted
    -- once-sink SET, not its hint text, so `trustedSusp` carries the genuine
    -- sink's identity. A user binding hinted the same resolves to an AVar (never
    -- APrim) and is NOT trusted (C2) — see `spoofCoroSuspResume`.
    coroSuspKey  = PN.coroSuspKey
    trustedSusp  = Set.singleton coroSuspKey
    -- A USER binding hinted `__coro_susp` but bound as an ordinary AVar.
    spoofSuspName = Name (T.pack "__coro_susp") (Unique 80)
    fooName      = Name (T.pack "foo")         (Unique 71)
    xName        = Name (T.pack "x")           (Unique 72)
    -- Let _ = __coro_susp x k; Ret ()  -- genuine sink routed to APrim
    coroSuspResume =
      Let (bnd (Name (T.pack "s") (Unique 73)))
          (RApp (APrim coroSuspKey) [AVar xName, AVar kName])
          (Ret unit)
    -- Let _ = <user __coro_susp> x k; Ret ()  -- spoof: an AVar head = Many
    spoofCoroSuspResume =
      Let (bnd (Name (T.pack "s3") (Unique 81)))
          (RApp (AVar spoofSuspName) [AVar xName, AVar kName])
          (Ret unit)
    -- Let _ = foo x k; Ret ()  -- non-trusted head should still be Many
    fooCallResume =
      Let (bnd (Name (T.pack "s2") (Unique 74)))
          (RApp (AVar fooName) [AVar xName, AVar kName])
          (Ret unit)
    -- Inter-procedural relaxation fixtures: a top-level helper to whose param the
    -- resume binder k is handed directly. Its trusted card is supplied via the
    -- trust map in each test.
    helperUniq = Unique 75
    helperName = Name (T.pack "helper") helperUniq
    tName      = Name (T.pack "t")      (Unique 76)
    -- let t = helper k in Ret t   (k handed directly to helper's slot 0)
    callHelperWithK =
      Let (bnd tName) (RApp (AVar helperName) [AVar kName]) (Ret (AVar tName))
    -- let t = helper k k in Ret t (k in two slots -> One + One = Many)
    callHelperWithKK =
      Let (bnd tName) (RApp (AVar helperName) [AVar kName, AVar kName]) (Ret (AVar tName))
    -- Partial application capture (arity 2, applied to 1 arg = k):
    --   let f = helper k        -- partial: captures k into the closure f
    --   let a = f n             -- re-invokes captured k
    --   let b = f n             -- re-invokes captured k again
    --   Ret b
    -- The saturation guard must keep clause B from firing on `helper k`.
    fName2 = Name (T.pack "f") (Unique 77)
    nName  = Name (T.pack "n") (Unique 78)
    partialHelperEscape =
      Let (bnd fName2) (RApp (AVar helperName) [AVar kName])
        (Let (bnd (Name (T.pack "a") (Unique 79))) (RApp (AVar fName2) [AVar nName])
          (Let (bnd (Name (T.pack "b") (Unique 82))) (RApp (AVar fName2) [AVar nName])
            (Ret (AVar (Name (T.pack "b") (Unique 82))))))
    resumeOnceArm =
      OpArm (T.pack "Tick") (T.pack "tick") [] (bnd kName) resumeOnce
    multishotArm =
      OpArm (T.pack "Choice") (T.pack "flip") [] (bnd kName) resumeTwiceSeq

-- ---------------------------------------------------------------------------
-- RC store tests (Task 0: owned heap foundation)

rcStoreTests :: TestTree
rcStoreTests = testGroup "rc store"
  [ testCase "alloc gives fresh addrs and counts" $ do
      let s0 = St.emptyStore
          (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (b, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
      a @?= St.HAddr 0
      b @?= St.HAddr 1
      St.stLive (St.stStats s2) @?= 2
      St.stAllocs (St.stStats s2) @?= 2
  , testCase "deref reads a live cell" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "True") []) St.emptyStore
      case St.derefPure a s1 of
        Right c -> St.cNode c @?= St.NCon (T.pack "True") []
        Left e  -> assertFailure ("unexpected: " <> show e)
  , testCase "deref of absent addr fails" $
      case St.derefPure (St.HAddr 99) St.emptyStore of
        Left _  -> pure ()
        Right _ -> assertFailure "expected failure on absent addr"
  ]

rcDropTests :: TestTree
rcDropTests = testGroup "rc drop"
  [ testCase "drop frees a unique leaf" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
      case St.dropAddrPure a s1 of
        Right s2 -> do
          St.stFrees (St.stStats s2) @?= 1
          St.stLive  (St.stStats s2) @?= 0
          case St.derefPure a s2 of
            Left _  -> pure ()
            Right _ -> assertFailure "UAF not trapped"
        Left e -> assertFailure (show e)
  , testCase "double free is trapped" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
      case St.dropAddrPure a s1 of
        Right s2 ->
          case St.dropAddrPure a s2 of
            Left _  -> pure ()
            Right _ -> assertFailure "double-free not trapped"
        Left e -> assertFailure (show e)
  , testCase "drop recursively frees children" $ do
      let (h, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
          (t, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (c, s3) = St.allocPure (St.NCon (T.pack "Cons") [St.RVBox h, St.RVBox t]) s2
      case St.dropAddrPure c s3 of
        Right s4 -> St.stLive (St.stStats s4) @?= 0
        Left e   -> assertFailure (show e)
  , testCase "deep list drops iteratively (no stack overflow)" $ do
      let n = 200000 :: Int
          -- NOTE: build is GHC-stack-recursive (GHC grows its stack); this test isolates dropAddr's EXPLICIT iterativeness, not the builder's.
          build 0 s = St.allocPure (St.NCon (T.pack "Nil") []) s
          build k s =
            let (rest, s') = build (k - 1) s
            in St.allocPure (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt (fromIntegral k)), St.RVBox rest]) s'
          (top, s1) = build n St.emptyStore
      case St.dropAddrPure top s1 of
        Right s2 -> St.stLive (St.stStats s2) @?= 0
        Left e   -> assertFailure (show e)
  ]

rcIncrefTests :: TestTree
rcIncrefTests = testGroup "rc incref"
  [ testCase "incref bumps rc from 1 to 2" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
      case St.increfPure a s1 of
        Right s2 ->
          case St.derefPure a s2 of
            Right c -> St.cRc c @?= 2
            Left e  -> assertFailure ("deref after incref: " <> show e)
        Left e -> assertFailure ("incref failed: " <> show e)
  , testCase "incref on dead addr returns Left" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
      case St.dropAddrPure a s1 of
        Right s2 ->
          case St.increfPure a s2 of
            Left _  -> pure ()
            Right _ -> assertFailure "incref of dead addr should return Left"
        Left e -> assertFailure ("drop failed: " <> show e)
  , testCase "incref then two drops frees exactly once" $ do
      let (a, s1) = St.allocPure (St.NCon (T.pack "Nil") []) St.emptyStore
      case St.increfPure a s1 of
        Left e -> assertFailure ("incref failed: " <> show e)
        Right s2 ->
          case St.dropAddrPure a s2 of
            Left e  -> assertFailure ("first drop failed: " <> show e)
            Right s3 -> do
              St.stFrees (St.stStats s3) @?= 0
              case St.derefPure a s3 of
                Left e  -> assertFailure ("cell freed too early: " <> show e)
                Right _ ->
                  case St.dropAddrPure a s3 of
                    Left e  -> assertFailure ("second drop failed: " <> show e)
                    Right s4 -> do
                      St.stFrees (St.stStats s4) @?= 1
                      St.stLive  (St.stStats s4) @?= 0
  ]

-- ---------------------------------------------------------------------------
-- RC M3 node tests (M3-b Task 2: the NContCell heap node)
--
-- 'NContCell (Maybe Addr)' is the affine one-shot continuation slot: empty
-- ('Nothing') or holding exactly one continuation addr ('Just a'). The held
-- continuation is an ORDINARY COUNTED CHILD of the cell, so dropping a full cell
-- at rc 0 cascades to the continuation (freed exactly once); an empty cell drops
-- with no children touched. These low-level Store tests exercise the accounting
-- in isolation, the same way 'rcDropTests' does for 'NCon'.

rcM3NodeTests :: TestTree
rcM3NodeTests = testGroup "rc m3 node"
  [ testCase "full cell drop frees the held continuation exactly once" $ do
      -- A minimal NCont with an EMPTY owned set (KDoneRC prefix): dropping the
      -- cell cascades to the NCont, which frees its (empty) owned set then its
      -- own shell. The whole heap returns to the baseline -- no leak, no
      -- double-free.
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          cont        = St.NCont St.KDoneRC (m2b2NoParamHandler, 0, St.emptyRCScope)
          (contAddr, s1) = St.allocPure cont s0
          (cellAddr, s2) = St.allocPure (St.NContCell (Just contAddr)) s1
      -- The cell counts the continuation as its single child.
      St.cascadeChildren (St.NContCell (Just contAddr)) @?= [contAddr]
      St.stLive (St.stStats s2) @?= baseline + 2
      case St.dropAddrPure cellAddr s2 of
        Left e  -> assertFailure ("cell drop failed: " <> show e)
        Right s3 -> do
          -- Both the cell and the held continuation are freed; heap balanced.
          St.stLive (St.stStats s3) @?= baseline
          St.stFrees (St.stStats s3) - St.stFrees (St.stStats s2) @?= 2
          -- The continuation cell is gone (a second free would be a double-free).
          case St.derefPure contAddr s3 of
            Left _  -> pure ()
            Right _ -> assertFailure "held continuation was not freed"
          case St.derefPure cellAddr s3 of
            Left _  -> pure ()
            Right _ -> assertFailure "cell was not freed"
  , testCase "empty cell drops cleanly with no children" $ do
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (cellAddr, s1) = St.allocPure (St.NContCell Nothing) s0
      -- An empty cell has no children.
      St.cascadeChildren (St.NContCell Nothing) @?= []
      St.nodeValues (St.NContCell Nothing) @?= []
      St.stLive (St.stStats s1) @?= baseline + 1
      case St.dropAddrPure cellAddr s1 of
        Left e  -> assertFailure ("empty cell drop failed: " <> show e)
        Right s2 -> do
          St.stLive (St.stStats s2) @?= baseline
          St.stFrees (St.stStats s2) - St.stFrees (St.stStats s1) @?= 1
  , testCase "cell-drop cascades through the continuation's owned set (freed once)" $ do
      -- A continuation whose owned set has a real value: build it the way the
      -- 'continuationOwned' unit tests do -- a nested parameterized handler frame
      -- whose hsc binds the param's Unique to a live allocated addr. Dropping the
      -- cell must reach that owned value through the cell -> NCont ->
      -- continuationOwned cascade, freeing it exactly once.
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          -- Allocate the owned value (e.g. the handler parameter's heap value).
          (ownedAddr, s1) = St.allocPure (St.NCon (T.pack "Owned") []) s0
          pb          = Binder (Name (T.pack "s") (Unique 8200)) Unrestricted m2bBoxTy
          h           = m2b2ParamHandler pb
          hsc         = St.RCScope (Map.fromList [(Unique 8200, St.RVBox ownedAddr)]) Map.empty
          prefix      = St.KHandleRC h 0 hsc St.KDoneRC
          cont        = St.NCont prefix (m2b2NoParamHandler, 0, St.emptyRCScope)
          (contAddr, s2) = St.allocPure cont s1
          (cellAddr, s3) = St.allocPure (St.NContCell (Just contAddr)) s2
      -- Sanity: the continuation's owned set is exactly the owned value.
      St.continuationOwned prefix @?= [ownedAddr]
      St.stLive (St.stStats s3) @?= baseline + 3
      case St.dropAddrPure cellAddr s3 of
        Left e  -> assertFailure ("cell drop failed: " <> show e)
        Right s4 -> do
          -- cell + NCont shell + owned value all freed: heap balanced.
          St.stLive (St.stStats s4) @?= baseline
          St.stFrees (St.stStats s4) - St.stFrees (St.stStats s3) @?= 3
          case St.derefPure ownedAddr s4 of
            Left _  -> pure ()
            Right _ -> assertFailure "owned value was not freed through the cell cascade"
  ]

-- ---------------------------------------------------------------------------
-- FBIP effect-safety (E+ lazy reclaim) Task 2: the abort-time reclaim
-- ('continuationReservations' + 'freeReservation' + the 'NCont'-drop wiring).
--
-- When an 'NCont' cell is dropped (a handler discards a captured continuation
-- -- an ABORT, a mid-run control-flow event, NOT program shutdown), the in-flight
-- FBIP reuse reservations trapped in its prefix would otherwise leak: their paired
-- 'allocAt' never runs. 'continuationReservations' collects those still-reserved
-- shells (filtered by 'stReserved', so a SPENT token lingering in an env is
-- excluded); 'freeReservation' frees one; 'dropAddr' folds the free over the
-- collected set when it frees an 'NCont' (spec §3.2-§3.4).
--
-- These low-level Store tests pin the collector and the reclaim wiring in
-- isolation, mirroring the off-books reservation 'dropReuse' performs (remove the
-- donor from 'stCells', add its address to 'stReserved') without running the full
-- pairing.
rcReclaimTests :: TestTree
rcReclaimTests = testGroup "rc-reclaim"
  [ testCase "collector returns the in-flight addr, excludes spent, dedups" $ do
      -- A KLetRC prefix whose scope env binds two binders to reuse tokens: one
      -- whose shell is still reserved (in-flight) and one whose shell is no longer
      -- reserved (spent). A THIRD binding aliases the in-flight token under a
      -- different Unique so the collector must dedup it to a single address.
      let inflight = St.HAddr 7   -- in stReserved
          spent    = St.HAddr 8   -- NOT in stReserved (consumed)
          slotIn   = St.ReuseSlot inflight 2 True 24
          slotSp   = St.ReuseSlot spent 2 True 24
          env      = Map.fromList
            [ (Unique 9001, St.RVReuse (Just slotIn))
            , (Unique 9002, St.RVReuse (Just slotSp))
            , (Unique 9003, St.RVReuse (Just slotIn))  -- alias of inflight (dedup)
            ]
          sc       = St.RCScope env Map.empty
          rBndr    = Binder (Name (T.pack "r") (Unique 9000)) Unrestricted m2bBoxTy
          prefix   = St.KLetRC rBndr (Ret (ALit LUnit)) sc St.KDoneRC
          reserved = Set.fromList [inflight]
      St.continuationReservations prefix reserved @?= [(inflight, 24)]
  , testCase "dropping an NCont reclaims its prefix's in-flight reservation" $ do
      -- Build an NCont whose prefix holds an in-flight reservation. The donor shell
      -- is reserved off-books through the REAL 'dropReuse' path (rc==1 unique donor
      -- -> removed from stCells, added to stReserved, NOT recordFree'd) so the
      -- in-flight state is exactly the production one. Dropping the NCont must
      -- reclaim that reserved shell: it ends freed (a use-after-free deref) and out
      -- of stReserved, and stLive returns to the post-reserve baseline minus the
      -- NCont shell.
      let s0          = St.emptyStore
          (donor, s1) = St.allocPure (St.NCon (T.pack "Shell") [St.RVLit (LInt 1)]) s0
      -- Reserve the donor via dropReuse (the real off-books reservation path).
      reserveRes <- runExceptT (St.dropReuse donor s1)
      (tok, sR) <- case reserveRes of
        Left e  -> assertFailure ("dropReuse failed: " <> show e) >> error "unreachable"
        Right r -> pure r
      slot <- case tok of
        St.RVReuse (Just sl) -> pure sl
        other -> assertFailure ("expected a reuse token, got " <> show other) >> error "unreachable"
      -- The reserved shell is in flight (in stReserved, off the live cell map).
      St.stReserved sR @?= Set.singleton donor
      let baseline    = St.stLive (St.stStats sR)   -- the reserved shell still counts as live
          env         = Map.fromList [(Unique 9101, St.RVReuse (Just slot))]
          sc          = St.RCScope env Map.empty
          rBndr       = Binder (Name (T.pack "r") (Unique 9100)) Unrestricted m2bBoxTy
          prefix      = St.KLetRC rBndr (Ret (ALit LUnit)) sc St.KDoneRC
          cont        = St.NCont prefix (m2b2NoParamHandler, 0, St.emptyRCScope)
          (contAddr, s2) = St.allocPure cont sR
      -- The collector sees the in-flight reservation.
      St.continuationReservations prefix (St.stReserved s2) @?= [(donor, 16)]
      res <- runExceptT (St.dropAddr contAddr s2)
      case res of
        Left e   -> assertFailure ("NCont drop failed: " <> show e)
        Right s3 -> do
          -- The reserved shell is reclaimed: gone from stReserved and freed (a
          -- deref now fails as use-after-free); stLive is back to the post-reserve
          -- baseline (the reserved shell + the NCont shell are both freed -> the
          -- baseline minus the NCont cell we added).
          Set.member donor (St.stReserved s3) @?= False
          case St.derefPure donor s3 of
            Left _  -> pure ()
            Right _ -> assertFailure "reserved shell was not reclaimed (still live)"
          -- Post-reserve baseline already counts the reserved shell. We added the
          -- NCont (baseline + 1); dropping it frees the NCont shell AND reclaims the
          -- reserved shell (two frees) -> baseline - 1.
          St.stLive (St.stStats s3) @?= baseline - 1
  , testCase "dropping an NCont with only a spent token reclaims nothing extra" $ do
      -- The same shape, but the donor is NOT in stReserved (its alloc_at already
      -- ran: spent). The collector must skip it, so the NCont drop frees only its
      -- own shell and never touches the spent token's (now revived/freed) cell.
      let s0          = St.emptyStore
          (donor, s1) = St.allocPure (St.NCon (T.pack "Shell") [St.RVLit (LInt 1)]) s0
          -- Spent: the token's value lingers in the env, but the address is NOT in
          -- stReserved. The cell is left LIVE (revived by the consume) to model the
          -- post-alloc_at state; freeing it would corrupt the heap.
          baseline    = St.stLive (St.stStats s1)
          slot        = St.ReuseSlot donor 1 True 16
          env         = Map.fromList [(Unique 9201, St.RVReuse (Just slot))]
          sc          = St.RCScope env Map.empty
          rBndr       = Binder (Name (T.pack "r") (Unique 9200)) Unrestricted m2bBoxTy
          prefix      = St.KLetRC rBndr (Ret (ALit LUnit)) sc St.KDoneRC
          cont        = St.NCont prefix (m2b2NoParamHandler, 0, St.emptyRCScope)
          (contAddr, s2) = St.allocPure cont s1   -- stReserved is empty here
      St.continuationReservations prefix (St.stReserved s2) @?= []
      res <- runExceptT (St.dropAddr contAddr s2)
      case res of
        Left e   -> assertFailure ("NCont drop failed: " <> show e)
        Right s3 -> do
          -- Only the NCont shell was freed; the spent token's cell is untouched.
          St.stLive (St.stStats s3) @?= baseline  -- the live donor cell remains
          case St.derefPure donor s3 of
            Left e  -> assertFailure ("spent token's cell was wrongly freed: " <> show e)
            Right _ -> pure ()
  ]

-- ---------------------------------------------------------------------------
-- Region Slice R1 (Task 4): the abstract-heap arena mirror.
--
-- An arena cohort is allocated UNCOUNTED ('arenaAllocPure'): dup/drop are no-ops
-- with no cascade (exactly like static/'Inline' values), the cohort's cells never
-- enter 'stLive'/'stPeak'/'stAllocs'/'stFrees', and they bump a SEPARATE
-- 'stArenaBytes'/'stArenaPeak' pair instead. 'arenaClose' SCANS OUT each arena
-- cell's COUNTED children (dropping them once, exactly the RC the program would
-- have done, relocated to scope close) and then BULK-REMOVES the cohort in O(1).
--
-- These Store-level tests pin the arena algebra in isolation (no interpreter
-- wiring yet, that is Task 5), mirroring 'rcStoreTests'/'rcDropTests' for the
-- counted heap. The crux soundness property (spec §5.1): a counted child of an
-- arena cell never points back into the arena, so the scan-out's 'dropAddr'
-- cascade only ever touches counted cells -- it never frees an arena cell.
rcArenaStoreTests :: TestTree
rcArenaStoreTests = testGroup "arena store"
  [ testCase "arena alloc is uncounted; dup/drop on it are no-ops" $ do
      -- Build a counted child B on the normal heap, then an arena cell A owning B.
      -- A is uncounted: it does not touch the counted books, and dup/drop of A are
      -- inert (no cascade) -- so B is NOT freed by a drop of A.
      let s0          = St.emptyStore
          sOpen       = St.arenaOpen s0
          (b, s1)     = St.allocPure (St.NCon (T.pack "B") []) sOpen
          allocsAfterB = St.stAllocs (St.stStats s1)
          liveAfterB   = St.stLive   (St.stStats s1)
          arenaBytesB  = St.stArenaBytes (St.stStats s1)
          nodeA        = St.NCon (T.pack "A") [St.RVBox b]
          (a, s2)      = St.arenaAllocPure nodeA s1
      -- A is recognised as an arena address (the store-aware uncounted check); the
      -- pure 'isUncounted' covers only static/'Inline', so A is NOT uncounted by it.
      St.isArenaAddr a s2 @?= True
      St.isUncounted a    @?= False
      -- The counted books did NOT count A: allocs/live unchanged from after B.
      St.stAllocs (St.stStats s2) @?= allocsAfterB
      St.stLive   (St.stStats s2) @?= liveAfterB
      -- But the arena footprint DID grow by exactly A's would-be C bytes.
      St.stArenaBytes (St.stStats s2) @?= arenaBytesB + St.wouldBeCBytes nodeA
      St.stArenaPeak  (St.stStats s2) @?= arenaBytesB + St.wouldBeCBytes nodeA
      -- dup A is a no-op: stats and cells unchanged.
      dupRes <- runExceptT (St.incref a s2)
      case dupRes of
        Left e   -> assertFailure ("dup of arena addr failed: " <> show e)
        Right s3 -> St.stStats s3 @?= St.stStats s2
      -- drop A is a no-op WITH NO CASCADE: stats unchanged, A still present,
      -- and crucially B is NOT freed (a naive cascade would have freed it).
      dropRes <- runExceptT (St.dropAddr a s2)
      case dropRes of
        Left e   -> assertFailure ("drop of arena addr failed: " <> show e)
        Right s3 -> do
          St.stStats s3 @?= St.stStats s2
          case St.derefPure a s3 of
            Left e  -> assertFailure ("arena cell A was wrongly removed by drop: " <> show e)
            Right _ -> pure ()
          case St.derefPure b s3 of
            Left e  -> assertFailure ("counted child B was wrongly freed by an inert arena drop: " <> show e)
            Right _ -> pure ()
  , testCase "close scans out counted children once; shared survives; cohort gone" $ do
      -- The cohort: two arena cells A and A2.
      --   * A owns a counted child B (rc 1) -> scan-out drops B to 0 (freed once).
      --   * A and A2 both own a counted child C; C also held once from OUTSIDE
      --     the cohort, so C starts at rc 3.  Scan-out drops C twice (once per
      --     arena owner) -> rc 1 (C survives, because the outside holder remains).
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          sOpen       = St.arenaOpen s0
          (b, s1)     = St.allocPure (St.NCon (T.pack "B") []) sOpen
          (c, s2)     = St.allocPure (St.NCon (T.pack "C") []) s1
          -- C must be referenced by A, A2, AND an outside holder = rc 3.
          s2'         = case St.increfPure c s2 >>= St.increfPure c of
                          Right s -> s
                          Left e  -> error ("incref C setup: " <> show e)
          (a,  s3)    = St.arenaAllocPure (St.NCon (T.pack "A")  [St.RVBox b, St.RVBox c]) s2'
          (a2, s4)    = St.arenaAllocPure (St.NCon (T.pack "A2") [St.RVBox c]) s3
      -- C is at rc 3 (A + A2 + outside) before close.
      case St.derefPure c s4 of
        Right cell -> St.cRc cell @?= 3
        Left e     -> assertFailure ("C deref before close: " <> show e)
      closeRes <- runExceptT (St.arenaClose s4)
      case closeRes of
        Left e   -> assertFailure ("arenaClose failed: " <> show e)
        Right s5 -> do
          -- B was freed exactly once (rc 1 -> 0).
          case St.derefPure b s5 of
            Left _  -> pure ()
            Right _ -> assertFailure "B was not freed by the scan-out"
          -- C survives at rc 1 (the outside holder remains).
          case St.derefPure c s5 of
            Right cell -> St.cRc cell @?= 1
            Left e     -> assertFailure ("C was wrongly freed by the scan-out: " <> show e)
          -- All arena addresses departed the arena (the frame popped) and the
          -- cells are gone from the heap (bulk reset).
          St.isArenaAddr a  s5 @?= False  -- no longer in any arena frame
          St.isArenaAddr a2 s5 @?= False
          case St.derefPure a s5 of
            Left _  -> pure ()
            Right _ -> assertFailure "arena cell A was not bulk-removed at close"
          case St.derefPure a2 s5 of
            Left _  -> pure ()
            Right _ -> assertFailure "arena cell A2 was not bulk-removed at close"
          -- Counted live = baseline + 1: only C survives (B freed; A/A2 uncounted,
          -- never on the counted books).
          St.stLive (St.stStats s5) @?= baseline + 1
          -- The arena frame stack popped.
          St.stArena s5 @?= []
  , testCase "close returns arena-bytes to baseline; stLive unperturbed" $ do
      -- Arena cells never enter 'stLive'/'stPeak'; after a full close
      -- 'stArenaBytes' returns to its pre-open value and 'stLive' equals the
      -- pre-open counted baseline (B is allocated and freed by the scan-out).
      let s0           = St.emptyStore
          arenaBytes0  = St.stArenaBytes (St.stStats s0)
          live0        = St.stLive (St.stStats s0)
          sOpen        = St.arenaOpen s0
          (b, s1)      = St.allocPure (St.NCon (T.pack "B") []) sOpen
          liveWithB    = St.stLive (St.stStats s1)
          (_, s2)      = St.arenaAllocPure (St.NCon (T.pack "A") [St.RVBox b]) s1
      -- The arena footprint grew (A charged its bytes); the counted live grew
      -- only by B (A is uncounted).
      St.stArenaBytes (St.stStats s2) @?= arenaBytes0 + St.wouldBeCBytes (St.NCon (T.pack "A") [St.RVBox b])
      St.stLive (St.stStats s2) @?= liveWithB
      closeRes <- runExceptT (St.arenaClose s2)
      case closeRes of
        Left e   -> assertFailure ("arenaClose failed: " <> show e)
        Right s3 -> do
          -- Arena bytes back to the pre-open value.
          St.stArenaBytes (St.stStats s3) @?= arenaBytes0
          -- Counted live back to the pre-open baseline: B was freed by the
          -- scan-out, A never perturbed stLive.
          St.stLive (St.stStats s3) @?= live0
  , testCase "stArenaPeak survives close (high-water mark, not reset)" $ do
      -- 'stArenaBytes' returns to baseline at close, but 'stArenaPeak' is a
      -- HIGH-WATER MARK: it retains the largest footprint the scope reached and is
      -- NEVER reduced by close. (The existing close test pins the bytes-reset; this
      -- pins the peak-retention, the complementary half.)
      let s0          = St.emptyStore
          arenaPeak0  = St.stArenaPeak (St.stStats s0)
          sOpen       = St.arenaOpen s0
          nodeA       = St.NCon (T.pack "A") [St.RVLit (LInt 1)]
          highWater   = arenaPeak0 + St.wouldBeCBytes nodeA
          (_, s1)     = St.arenaAllocPure nodeA sOpen
      -- The peak rose to the in-scope high-water mark.
      St.stArenaPeak (St.stStats s1) @?= highWater
      closeRes <- runExceptT (St.arenaClose s1)
      case closeRes of
        Left e   -> assertFailure ("arenaClose failed: " <> show e)
        Right s2 -> do
          -- After close: bytes back to baseline, but the peak is RETAINED (>= the
          -- in-scope high-water it reached, never reset to the pre-open value).
          St.stArenaBytes (St.stStats s2) @?= St.stArenaBytes (St.stStats s0)
          St.stArenaPeak  (St.stStats s2) @?= highWater
  , testCase "close of an empty arena (no open frame) fails loudly" $ do
      -- 'arenaClose' on a store with no open arena frame is an internal error.
      closeRes <- runExceptT (St.arenaClose St.emptyStore)
      case closeRes of
        Left _  -> pure ()
        Right _ -> assertFailure "arenaClose with no open frame should fail loudly"
  , testCase "arena cells are FBIP-excluded (never a reuse donor)" $ do
      -- An arena cell is uncounted, so 'dropReuse' must treat it like any other
      -- uncounted donor: it yields a NULL token and never reserves the shell.
      let s0      = St.emptyStore
          sOpen   = St.arenaOpen s0
          (a, s1) = St.arenaAllocPure (St.NCon (T.pack "A") [St.RVLit (LInt 1)]) sOpen
      reuseRes <- runExceptT (St.dropReuse a s1)
      case reuseRes of
        Left e         -> assertFailure ("dropReuse on arena addr failed: " <> show e)
        Right (tok, s2) -> do
          -- The token is NULL (the arena cell is not a reuse donor).
          tok @?= St.RVReuse Nothing
          -- The arena cell was NOT reserved off-books.
          St.stReserved s2 @?= St.stReserved s1
          St.stReserved s2 @?= Set.empty
          -- And the arena cell is still present (a no-op dropReuse).
          case St.derefPure a s2 of
            Left e  -> assertFailure ("arena cell was wrongly removed by dropReuse: " <> show e)
            Right _ -> pure ()
  ]

-- ---------------------------------------------------------------------------
-- FBIP effect-safety (E+ lazy reclaim) Task 3: the END-TO-END differential
-- oracle. The Task-2 reclaim ('rcReclaimTests' above) is pinned at the Store
-- level on hand-built 'NCont' prefixes; THIS group proves the same mechanism on
-- real '.wok' programs run through the production pipeline (elaborate -> prune ->
-- 'reusePairing . insertRC' -> run) on BOTH backends.
--
-- THE SHAPE (spec §7, the de-risk). An effectful map under a handler: a separate
-- effectful function 'f' performs an op, and 'mapF f xs' rebuilds a same-shape
-- 'Cons' over the unique scrutinee spine, so the 'Cons x xx' arm lowers to
--
--     let _tok = __rc_drop_reuse(xs)   -- a reuse token is minted on the donor
--     let t.2  = f(e, x)               -- an EFFECTFUL RApp ('e.op') in between
--     let t.4  = Cons@_tok(t.2, t.3)   -- the alloc_at consuming the token
--
-- The token spans the effectful call: 'ReusePairing.findTarget' rides PAST an
-- 'RApp' (only 'ROp'/'RLam'/'Handle' stop it), so the reuse pairing fires even
-- though 'f' performs an op internally. This is exactly the residual E+ closes:
-- the reservation is in flight WHILE the op's continuation is captured.
--
--   * 'fbip-effect-abort.wok': the op-arm ABORTS (returns 'None', never resumes),
--     so the captured continuation -- holding the pending 'Cons@_tok' rebuild,
--     i.e. the in-flight reservation -- is DROPPED. Before Task 2 the reserved
--     shell was orphaned (a leak: stLive > baseline; the C arena warned "live
--     cells"). The abort reclaim frees it, so the heap returns to baseline. This
--     run goes through the C backend, exercising 'freeReservation's 'CAddr' arm
--     (the reserved 'Cons' shell is an encodable NCon that landed on the C heap).
--   * 'fbip-effect-resume.wok': the op-arm RESUMES. The reservation rides along in
--     'stReserved' untouched; the spliced 'alloc_at' reuses the shell in place.
--     So reuse SURVIVES the resume: the fused run's allocs collapse by exactly the
--     output spine length vs the non-fused ('insertRC'-only) run.
rcEffectSafetyTests :: TestTree
rcEffectSafetyTests = testGroup "rc-effect-safety"
  [ -- DE-RISK (criterion 1, pinned in code): the effectful map under a handler
    -- reaches the pairing AND emits the effectful op alongside it. Asserted on the
    -- abort program's fused IR: all three primitives -- a '__rc_drop_reuse' donor,
    -- the '@_tok' reuse-con, and the effectful op (Exn.throw) -- are emitted in
    -- 'mapF's fused IR (presence, not order). If this ever stops firing, the
    -- abort/resume runs below would no longer exercise the reservation path and
    -- this guard fails loudly.
    testCase "de-risk: the effectful map under a handler PAIRS (op emitted alongside the reuse token)" $ do
      cm <- rcEffectSafetyPrepare "test/rc-c-backend/fbip-effect-abort.wok"
      let dumped = T.unpack (Anf.prettyModule (reusePairing (Perceus.insertRC cm)))
      assertBool "a reuse token is minted on the map spine donor (__rc_drop_reuse)"
        ("__rc_drop_reuse(" `Data.List.isInfixOf` dumped)
      assertBool "the rebuilt Cons consumes the token (@_tok), i.e. the pairing fired"
        ("@_tok" `Data.List.isInfixOf` dumped)
      -- The effectful op call ('e.Exn.throw') sits in the same module: the token
      -- genuinely spans an effectful RApp (not a pure map).
      assertBool "the map's element function performs an effect op (Exn.throw)"
        ("Exn.throw" `Data.List.isInfixOf` dumped)
      -- Resume program too: same pairing fires across its effectful op.
      cmR <- rcEffectSafetyPrepare "test/rc-c-backend/fbip-effect-resume.wok"
      let dumpedR = T.unpack (Anf.prettyModule (reusePairing (Perceus.insertRC cmR)))
      assertBool "resume program also pairs (token spans Reader.ask)"
        ("@_tok" `Data.List.isInfixOf` dumpedR && "Reader.ask" `Data.List.isInfixOf` dumpedR)

  , -- ABORT = NO LEAK (criterion 2). The effectful map under an ABORTING handler.
    -- Run on BOTH backends; assert no crash, the correct value, abstract == C, the
    -- C heap actually exercised (so 'freeReservation's CAddr arm runs on the
    -- reclaimed shell), and -- the regression -- the heap returns to baseline (no
    -- leaked reservation). This FAILS before Task 2 (frees one short of allocs,
    -- stLive == baseline + 1) and passes now.
    testCase "abort: effectful map under an aborting handler does not leak (abstract == C)" $ do
      (absR, cR, cAllocs) <- runBothBackendsUnchecked "test/rc-c-backend/fbip-effect-abort.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is None (the abort default)" (T.pack "None") (RCM.rcOutput c)
          assertEqual "abstract output == C output" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "abstract allocs == C allocs"
            (St.stAllocs (RCM.rcStats a)) (St.stAllocs (RCM.rcStats c))
          assertEqual "abstract frees == C frees"
            (St.stFrees (RCM.rcStats a)) (St.stFrees (RCM.rcStats c))
          assertEqual "abstract peak == C peak"
            (St.stPeak (RCM.rcStats a)) (St.stPeak (RCM.rcStats c))
          -- The headline: the reserved shell trapped in the dropped continuation is
          -- reclaimed, so frees == allocs and stLive returns to baseline. Before
          -- Task 2 this was a leak (frees == allocs - 1).
          assertEqual "no leak (C): stLive returns to baseline"
            (RCM.rcBaseline c) (St.stLive (RCM.rcStats c))
          assertEqual "no leak (C): allocs - frees == baseline"
            (RCM.rcBaseline c) (St.stAllocs (RCM.rcStats c) - St.stFrees (RCM.rcStats c))
          -- The reclaimed shell is a 'Cons' (an encodable NCon) that landed on the
          -- C heap, so the abort reclaim genuinely runs 'freeReservation's CAddr arm
          -- ('wok_free'). Read the C heap's OWN counter to prove the C path fired
          -- (not an all-abstract fallback that would never reach the CAddr arm).
          assertBool "C heap genuinely exercised (the reclaimed shell is a CAddr)"
            (cAllocs > 0)
        (Left e, _) -> assertFailure ("abstract backend FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C backend FAILED: " <> show e)

  , -- RESUME = REUSE SURVIVES (criterion 3). The same effectful map under a
    -- RESUMING handler. The reuse pairing must STILL fire across the resume: the
    -- fused ('reusePairing . insertRC') run allocates strictly fewer cells than the
    -- non-fused ('insertRC' only) run -- by exactly the output spine length -- and
    -- both produce the correct output. Plus abstract == C on the fused run.
    testCase "resume: reuse survives the resume (fused allocs drop by the spine length)" $ do
      cm <- rcEffectSafetyPrepare "test/rc-c-backend/fbip-effect-resume.wok"
      nf <- RCM.runModuleRCUnchecked (Perceus.insertRC cm) >>= \case
        Left e  -> assertFailure ("non-fused run FAILED: " <> show e) >> error "unreachable"
        Right r -> pure r
      fu <- RCM.runModuleRCUnchecked (reusePairing (Perceus.insertRC cm)) >>= \case
        Left e  -> assertFailure ("fused run FAILED: " <> show e) >> error "unreachable"
        Right r -> pure r
      -- reader 10 over [1,2,3] increments each element by the asked constant (10).
      assertEqual "output is [11, 12, 13]" (T.pack "[11, 12, 13]") (RCM.rcOutput fu)
      assertEqual "fused output == non-fused output"
        (RCM.rcOutput nf) (RCM.rcOutput fu)
      -- The FBIP win survives the resume: the fused run reuses the 3-cell output
      -- spine in place, so it allocates exactly 3 fewer cells than the non-fused
      -- run (which builds it fresh). If E+ broke reuse across a resume this would
      -- collapse to zero saving.
      assertBool "FBIP win: fused allocs strictly below non-fused"
        (St.stAllocs (RCM.rcStats fu) < St.stAllocs (RCM.rcStats nf))
      assertEqual "allocs reduced by exactly the output spine length (3)"
        3 (St.stAllocs (RCM.rcStats nf) - St.stAllocs (RCM.rcStats fu))
      -- The fused run is heap-balanced (no leak from the spliced-in reservation).
      assertEqual "fused run returns to baseline (no leak through the resume)"
        (RCM.rcBaseline fu) (St.stLive (RCM.rcStats fu))
      -- abstract == C on the fused run.
      (absR, cR, cAllocs) <- runBothBackendsUnchecked "test/rc-c-backend/fbip-effect-resume.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == C output" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "abstract allocs == C allocs"
            (St.stAllocs (RCM.rcStats a)) (St.stAllocs (RCM.rcStats c))
          assertEqual "abstract frees == C frees"
            (St.stFrees (RCM.rcStats a)) (St.stFrees (RCM.rcStats c))
          assertEqual "no leak (C): stLive returns to baseline"
            (RCM.rcBaseline c) (St.stLive (RCM.rcStats c))
          assertBool "C heap genuinely exercised" (cAllocs > 0)
        (Left e, _) -> assertFailure ("abstract backend FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C backend FAILED: " <> show e)
  ]

-- | Load + elaborate + prune an effect-safety '.wok' program to its pruned
-- 'CoreModule', WITHOUT the 'firstOrderNoHandlerViolations' guard (these programs
-- DELIBERATELY use a handler, so the guard would reject them). The caller applies
-- 'insertRC'/'reusePairing' and runs through the UNCHECKED runner. Mirrors
-- 'rcFbipPrepareRaw' but admits handlers.
rcEffectSafetyPrepare :: FilePath -> IO Anf.CoreModule
rcEffectSafetyPrepare path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr) >> error "unreachable"
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s   -> assertFailure ("elaborate: " <> s) >> error "unreachable"
        Right cm -> pure (pruneToReachable cm)

-- | Run an effect-safety program through BOTH backends via the UNCHECKED runner
-- (so the handler is admitted), applying the production fused pipeline
-- ('reusePairing . insertRC'). Mirrors 'withBothBackends' but bypasses the
-- handler guard and returns the two 'RCRun's plus the C heap's OWN alloc counter
-- (read before the heap is freed) so a caller can prove the C path fired.
runBothBackendsUnchecked
  :: FilePath
  -> IO ( Either IV.RuntimeError RCM.RCRun
        , Either IV.RuntimeError RCM.RCRun
        , Word64 )
runBothBackendsUnchecked path = do
  cm <- rcEffectSafetyPrepare path
  let fused = reusePairing (Perceus.insertRC cm)
  absR <- RCM.runModuleRCUncheckedWith St.AbstractHeap fused
  hp   <- Heap.wokHeapNew
  (cR, cAllocs) <- (do c <- RCM.runModuleRCUncheckedWith (St.CHeap hp) fused
                       a <- Heap.wokStatAllocs hp
                       pure (c, a))
                   `Control.Exception.finally` Heap.wokHeapFree hp
  pure (absR, cR, cAllocs)

-- ---------------------------------------------------------------------------
-- RC Array node tests (Array Slice A, Task 1: the NArray heap node)
--
-- 'NArray [RCValue]' is a fixed-size, homogeneous, boxed array on the abstract
-- 'IntMap' heap (no C cell in Slice A). Each element slot is an ordinary counted
-- child reached through 'nodeValues'/'countedRefs', so the generic cascade frees
-- one ref per counted element exactly once -- no new 'cascadeChildren' arm. These
-- store-layer tests exercise the accounting in isolation, mirroring 'rcM3NodeTests'
-- for 'NContCell' and 'rcDropTests' for 'NCon'. (No type or prim yet.)

rcArrayNodeTests :: TestTree
rcArrayNodeTests = testGroup "rc array node"
  [ testCase "nodeValues returns the element list verbatim" $ do
      let e1 = St.RVLit (Anf.LInt 1)
          e2 = St.RVLit (Anf.LInt 2)
      St.nodeValues (St.NArray [e1, e2]) @?= [e1, e2]
      St.nodeValues (St.NArray []) @?= []
  , testCase "renderRCValue prints an array like a list" $ do
      -- Render an array of three boxed nullary cells. The renderer derefs each
      -- handle, so we use real allocated Nil cells; expected text is [[], [], []].
      let s0          = St.emptyStore
          (a, s1)     = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (b, s2)     = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (c, s3)     = St.allocPure (St.NCon (T.pack "Nil") []) s2
          (arr, s4)   = St.allocPure (St.NArray [St.RVBox a, St.RVBox b, St.RVBox c]) s3
      case St.renderRCValue s4 (St.RVBox arr) of
        Right t -> t @?= T.pack "[[], [], []]"
        Left e  -> assertFailure ("render failed: " <> show e)
  , testCase "renderRCValue prints an empty array as []" $ do
      let (arr, s1) = St.allocPure (St.NArray []) St.emptyStore
      case St.renderRCValue s1 (St.RVBox arr) of
        Right t -> t @?= T.pack "[]"
        Left e  -> assertFailure ("render failed: " <> show e)
  , testCase "drop at rc 1 cascades one drop per boxed-counted element" $ do
      -- Two pre-allocated counted cells referenced as boxed elements. Dropping the
      -- array at rc 1 frees the array cell and each element exactly once; the heap
      -- returns to baseline.
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          (e1, s1)    = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e2, s2)    = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (arr, s3)   = St.allocPure (St.NArray [St.RVBox e1, St.RVBox e2]) s2
      -- The array counts both elements as children via the generic cascade.
      St.cascadeChildren (St.NArray [St.RVBox e1, St.RVBox e2]) @?= [e1, e2]
      St.stLive (St.stStats s3) @?= baseline + 3
      case St.dropAddrPure arr s3 of
        Left e  -> assertFailure ("array drop failed: " <> show e)
        Right s4 -> do
          St.stLive (St.stStats s4) @?= baseline
          St.stFrees (St.stStats s4) - St.stFrees (St.stStats s3) @?= 3
          case St.derefPure e1 s4 of
            Left _  -> pure ()
            Right _ -> assertFailure "element 1 was not freed through the cascade"
          case St.derefPure e2 s4 of
            Left _  -> pure ()
            Right _ -> assertFailure "element 2 was not freed through the cascade"
  , testCase "inline/uncounted elements add no children: drop frees only the array cell" $ do
      -- An array of literal (inline, uncounted) elements has NO counted children;
      -- dropping it frees one cell only -- no spurious child drops.
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          elems       = [St.RVLit (Anf.LInt 1), St.RVLit (Anf.LInt 2)]
          (arr, s1)   = St.allocPure (St.NArray elems) s0
      St.cascadeChildren (St.NArray elems) @?= []
      St.stLive (St.stStats s1) @?= baseline + 1
      case St.dropAddrPure arr s1 of
        Left e  -> assertFailure ("array drop failed: " <> show e)
        Right s2 -> do
          St.stLive (St.stStats s2) @?= baseline
          St.stFrees (St.stStats s2) - St.stFrees (St.stStats s1) @?= 1
  , testCase "incref then two drops: freed once, cascades once (no double-free)" $ do
      -- An array shared at rc 2: the first drop only decrements (the array and its
      -- element survive), the second frees the array and cascades to the element
      -- exactly once. The stDead double-free guard never trips.
      let s0          = St.emptyStore
          baseline    = St.stLive (St.stStats s0)
          (e1, s1)    = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (arr, s2)   = St.allocPure (St.NArray [St.RVBox e1]) s1
      case St.increfPure arr s2 of
        Left e  -> assertFailure ("incref failed: " <> show e)
        Right s3 ->
          case St.dropAddrPure arr s3 of
            Left e  -> assertFailure ("first drop failed: " <> show e)
            Right s4 -> do
              -- Nothing freed yet: array still live at rc 1, element untouched.
              St.stFrees (St.stStats s4) - St.stFrees (St.stStats s2) @?= 0
              St.stLive (St.stStats s4) @?= baseline + 2
              case St.derefPure arr s4 of
                Left e  -> assertFailure ("array freed too early: " <> show e)
                Right _ ->
                  case St.dropAddrPure arr s4 of
                    Left e  -> assertFailure ("second drop failed: " <> show e)
                    Right s5 -> do
                      -- Array + element freed exactly once each; heap balanced.
                      St.stLive (St.stStats s5) @?= baseline
                      St.stFrees (St.stStats s5) - St.stFrees (St.stStats s2) @?= 2
                      case St.derefPure e1 s5 of
                        Left _  -> pure ()
                        Right _ -> assertFailure "element was not freed on the final drop"
  ]

-- ---------------------------------------------------------------------------
-- RC String node tests (String Slice E1, Task 2: the NString heap node)
--
-- 'NString ByteString' is a flat UTF-8 byte buffer. Bytes are opaque (no child
-- refs), so the drop cascade is empty: freeing an 'NString' frees only the
-- cell itself. 'wouldBeCBytes' charges 16 + 8*ceil(byte_len/8) (8-rounded
-- body), exactly as 'wok_string_alloc' does in C, so both backends agree on
-- 'peak_bytes'. These store-layer tests exercise:
--   1. Abstract heap: 'allocPure' path, correct byte accounting, empty cascade.
--   2. C heap: real 'WokString' cell via 'wokStringAlloc', round-trip byte
--      read-back via 'wokStringLen', balanced allocs/frees, live == 0.
-- The test string "h\xc3\xa9llo" is UTF-8 for "héllo" (5 codepoints, 6 bytes),
-- so byte_len=6, ceil(6/8)=1, wouldBeCBytes=16+8=24.

rcStringNodeTests :: TestTree
rcStringNodeTests = testGroup "rc string node"
  [ testCase "nodeValues returns empty list (no child refs)" $ do
      let bs = TxEnc.encodeUtf8 (T.pack "hello")
      St.nodeValues (St.NString bs) @?= []

  , testCase "wouldBeCBytes: ASCII 5-byte string = 24 (ceil(5/8)=1)" $ do
      let bs = TxEnc.encodeUtf8 (T.pack "hello")  -- 5 bytes
      St.wouldBeCBytes (St.NString bs) @?= (24 :: Int)  -- 16 + 8*1

  , testCase "wouldBeCBytes: 8-byte string = 24 (ceil(8/8)=1)" $ do
      let bs = TxEnc.encodeUtf8 (T.pack "12345678")  -- 8 bytes
      St.wouldBeCBytes (St.NString bs) @?= (24 :: Int)  -- 16 + 8*1

  , testCase "wouldBeCBytes: 9-byte string = 32 (ceil(9/8)=2)" $ do
      let bs = TxEnc.encodeUtf8 (T.pack "123456789")  -- 9 bytes
      St.wouldBeCBytes (St.NString bs) @?= (32 :: Int)  -- 16 + 8*2

  , testCase "wouldBeCBytes: empty string = 16 (ceil(0/8)=0)" $ do
      let bs = BS.empty
      St.wouldBeCBytes (St.NString bs) @?= (16 :: Int)  -- 16 + 8*0

  , testCase "wouldBeCBytes: multi-byte UTF-8 'helo' = 24 (6 bytes, ceil(6/8)=1)" $ do
      -- "h\xc3\xa9llo" = UTF-8 for "h\233llo" = 6 bytes
      let bs = TxEnc.encodeUtf8 (T.pack "h\233llo")  -- 6 bytes
      St.wouldBeCBytes (St.NString bs) @?= (24 :: Int)  -- 16 + 8*1

  , testCase "nodeCEligible NString is False (own alloc path)" $ do
      let bs = TxEnc.encodeUtf8 (T.pack "hello")
      St.nodeCEligible (St.NString bs) @?= False

  , testCase "abstract alloc: allocPure, byte accounting, empty cascade, balanced drop" $ do
      -- Allocate an NString on the abstract heap; verify wouldBeCBytes is charged
      -- to stCurBytes/stPeakBytes; drop it; verify the heap returns to baseline.
      let bs       = TxEnc.encodeUtf8 (T.pack "h\233llo")  -- 6 bytes, 24 charged
          expected = St.wouldBeCBytes (St.NString bs)       -- 24
          s0       = St.emptyStore
          (a, s1)  = St.allocPure (St.NString bs) s0
      -- Byte accounting.
      St.stCurBytes  (St.stStats s1) @?= expected
      St.stPeakBytes (St.stStats s1) @?= expected
      -- Live count bumped.
      St.stLive (St.stStats s1) @?= St.stLive (St.stStats s0) + 1
      -- Empty cascade: cascadeChildren returns nothing.
      St.cascadeChildren (St.NString bs) @?= []
      -- Drop: heap returns to baseline.
      case St.dropAddrPure a s1 of
        Left e   -> assertFailure ("dropAddrPure NString failed: " <> show e)
        Right s2 -> do
          St.stLive     (St.stStats s2) @?= St.stLive (St.stStats s0)
          St.stCurBytes (St.stStats s2) @?= 0
          St.stFrees    (St.stStats s2) - St.stFrees (St.stStats s1) @?= 1

  , testCase "renderRCValue NString prints show-quoted text (reference-identical)" $ do
      -- "h\xc3\xa9llo" should render as "\"h\233llo\"" (Haskell show of Text).
      let bs  = TxEnc.encodeUtf8 (T.pack "h\233llo")
          s0  = St.emptyStore
          (a, s1) = St.allocPure (St.NString bs) s0
      case St.renderRCValue s1 (St.RVBox a) of
        Left e  -> assertFailure ("renderRCValue NString failed: " <> show e)
        Right t -> t @?= T.pack (show (T.pack "h\233llo"))
  ]

-- ---------------------------------------------------------------------------
-- RC StringView node tests (String Slice E4, Task 1)
--
-- Tests the NStringView constructor on the AbstractHeap backend:
--   * 'nodeValues' returns '[RVBox parent]' (the one counted child).
--   * 'nodeCEligible' is False (own alloc path).
--   * 'wouldBeCBytes' is 32 (fixed-size view cell).
--   * 'allocNStringView' increfs the parent then allocates the view cell; drop
--     of the view decrefs the parent, returning stLive to the pre-view baseline.
--   * 'stringBytes' on an NStringView returns the windowed ByteString (O(1) slice).
--   * 'renderRCValue' on a view renders the same text as the materialized substring.

rcStringViewNodeTests :: TestTree
rcStringViewNodeTests = testGroup "rcStringView"
  [ testCase "nodeValues NStringView returns [RVBox parent]" $ do
      let s0     = St.emptyStore
          (pa, _) = St.allocPure (St.NString (TxEnc.encodeUtf8 (T.pack "hello world"))) s0
      St.nodeValues (St.NStringView pa 6 5) @?= [St.RVBox pa]

  , testCase "nodeCEligible NStringView is False (own alloc path)" $ do
      let s0     = St.emptyStore
          (pa, _) = St.allocPure (St.NString (TxEnc.encodeUtf8 (T.pack "hello world"))) s0
      St.nodeCEligible (St.NStringView pa 6 5) @?= False

  , testCase "wouldBeCBytes NStringView is 32 (header 8 + ptr 8 + offset 8 + len 8)" $ do
      let s0     = St.emptyStore
          (pa, _) = St.allocPure (St.NString (TxEnc.encodeUtf8 (T.pack "hello world"))) s0
      St.wouldBeCBytes (St.NStringView pa 6 5) @?= (32 :: Int)

  , testCase "stringBytes on NStringView at offset 6 len 5 equals 'world'" $ do
      -- Build "hello world" on the abstract heap, then a view over bytes 6..10.
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes
          s0     = St.emptyStore
          (pa, s1) = St.allocPure (St.NString bs) s0
      r <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r of
        Left e  -> assertFailure ("allocNStringView failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- stringBytes on the view should return exactly the 5 bytes "world".
      rb <- runExceptT (RCP.stringBytes (St.RVBox va) s2)
      case rb of
        Left e   -> assertFailure ("stringBytes on NStringView failed: " <> show e)
        Right got -> got @?= TxEnc.encodeUtf8 (T.pack "world")

  , testCase "drop view: parent refcount returns to pre-view baseline" $ do
      -- Alloc the parent; record the live count; alloc the view (parent rc bumped
      -- to 2); drop the view; assert stLive returns to the pre-view baseline (1
      -- live cell: the parent) AND the parent cell's own refcount went 2 -> 1.
      let bs       = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes (> maxInlineStr)
          s0       = St.emptyStore
          (pa, s1) = St.allocPure (St.NString bs) s0
          baseline = St.stLive (St.stStats s1)  -- 1 (just the parent)
          -- The parent's own refcount: 1 immediately after its alloc.
          parentRc st = St.cRc <$> St.derefPure pa st
      r <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r of
        Left e  -> assertFailure ("allocNStringView failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- After alloc: 2 live cells (parent + view), and the parent's rc is 2
      -- (allocNStringView increfed it -- the view owns one counted ref).
      St.stLive (St.stStats s2) @?= baseline + 1
      parentRc s2 @?= Right 2
      -- Drop the view: parent is decreffed (rc 2->1), view cell freed.
      case St.dropAddrPure va s2 of
        Left e  -> assertFailure ("dropAddrPure view failed: " <> show e)
        Right s3 -> do
          St.stLive (St.stStats s3) @?= baseline
          -- The parent cell survives with its rc restored to 1 (its own binding).
          parentRc s3 @?= Right 1

  , testCase "renderRCValue NStringView renders same text as materialized substring" $ do
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")
          s0     = St.emptyStore
          (pa, s1) = St.allocPure (St.NString bs) s0
      r <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r of
        Left e  -> assertFailure ("allocNStringView failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      case St.renderRCValue s2 (St.RVBox va) of
        Left e  -> assertFailure ("renderRCValue NStringView failed: " <> show e)
        Right t -> t @?= T.pack (show (T.pack "world"))

  -- -------------------------------------------------------------------------
  -- CHeap backend: WokStringView C cell (E4 Task 2)
  -- -------------------------------------------------------------------------
  -- Run the same alloc/deref/drop sequence on the real C heap and assert:
  --   * allocNStringView on CHeap returns a CAddr (the WokStringView cell);
  --   * deref of the CAddr reconstructs the NStringView node with correct fields;
  --   * stringBytes on the CAddr view returns the windowed bytes;
  --   * dropAddr balances: C wok_stat_live == 0, allocs == frees;
  --   * peak_bytes on the CHeap run == 32 (the parent string) + 32 (the view).
  --
  -- 'onBothBackends' runs the body on AbstractHeap then CHeap (leak-checked),
  -- conjoining the results -- a failure on either backend surfaces.

  , testCase "CHeap: allocNStringView returns CAddr WokStringView cell" $ do
      hp <- Heap.wokHeapNew
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes > maxInlineStr
          s0     = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r2 <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      assertBool "allocNStringView CHeap: result is CAddr"
        (case va of St.CAddr _ -> True; _ -> False)
      -- peak_bytes must equal parent cell + view cell = (16+8*2) + 32 = 32 + 32 = 64.
      let expectedPeakBytes = St.wouldBeCBytes (St.NString bs) + 32
      St.stPeakBytes (St.stStats s2) @?= expectedPeakBytes
      -- Drop both cells; heap must balance.
      r3 <- runExceptT (St.dropAddr va s2)
      s3 <- case r3 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("dropAddr view CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r4 <- runExceptT (St.dropAddr pa s3)
      case r4 of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("dropAddr parent CHeap failed: " <> show e) }
        Right _ -> do
          cLive   <- Heap.wokStatLive   hp
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "CHeap view: wok_stat_live == 0 after drop" (0 :: Int64) cLive
          assertEqual "CHeap view: allocs == frees" cAllocs cFrees
          Heap.wokHeapFree hp

  , testCase "CHeap: deref CAddr view reconstructs NStringView with correct fields" $ do
      hp <- Heap.wokHeapNew
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes
          s0     = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r2 <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r3 <- runExceptT (St.deref va s2)
      case r3 of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("deref view CHeap failed: " <> show e) }
        Right c -> do
          St.cNode c @?= St.NStringView pa 6 5
          r4 <- runExceptT (St.dropAddr va s2)
          s3 <- case r4 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr view CHeap failed: " <> show e) >> error "unreachable" }
            Right x -> pure x
          r5 <- runExceptT (St.dropAddr pa s3)
          case r5 of
            Left e -> do { Heap.wokHeapFree hp
                         ; assertFailure ("dropAddr parent CHeap failed: " <> show e) }
            Right _ -> do
              cAllocs <- Heap.wokStatAllocs hp
              cFrees  <- Heap.wokStatFrees  hp
              assertEqual "CHeap deref: allocs == frees" cAllocs cFrees
              Heap.wokHeapFree hp

  , testCase "CHeap: stringBytes on CAddr view returns windowed bytes" $ do
      hp <- Heap.wokHeapNew
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes
          s0     = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r2 <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r3 <- runExceptT (RCP.stringBytes (St.RVBox va) s2)
      case r3 of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("stringBytes CAddr view failed: " <> show e) }
        Right got -> do
          got @?= TxEnc.encodeUtf8 (T.pack "world")
          r4 <- runExceptT (St.dropAddr va s2)
          s3 <- case r4 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr view CHeap failed: " <> show e) >> error "unreachable" }
            Right x -> pure x
          r5 <- runExceptT (St.dropAddr pa s3)
          case r5 of
            Left e -> do { Heap.wokHeapFree hp
                         ; assertFailure ("dropAddr parent CHeap failed: " <> show e) }
            Right _ -> do
              cAllocs <- Heap.wokStatAllocs hp
              cFrees  <- Heap.wokStatFrees  hp
              assertEqual "CHeap stringBytes: allocs == frees" cAllocs cFrees
              Heap.wokHeapFree hp

  , testCase "CHeap: drop view decrefs parent, then drop parent: C heap balanced" $ do
      hp <- Heap.wokHeapNew
      let bs     = TxEnc.encodeUtf8 (T.pack "hello world")  -- 11 bytes
          s0     = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      r2 <- runExceptT (St.allocNStringView pa 6 5 s1)
      (va, s2) <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      -- 2 C cells live (parent + view).
      cLive0 <- Heap.wokStatLive hp
      assertEqual "2 C cells live after alloc" (2 :: Int64) cLive0
      -- Drop the view: the view cell is freed, parent rc drops from 2 to 1.
      r3 <- runExceptT (St.dropAddr va s2)
      s3 <- case r3 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("dropAddr view CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      cLive1 <- Heap.wokStatLive hp
      assertEqual "1 C cell live after view drop (parent survives)" (1 :: Int64) cLive1
      -- Drop the parent: C heap fully balanced.
      r4 <- runExceptT (St.dropAddr pa s3)
      case r4 of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("dropAddr parent CHeap failed: " <> show e) }
        Right _ -> do
          cLive2  <- Heap.wokStatLive   hp
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "0 C cells live after parent drop" (0 :: Int64) cLive2
          assertEqual "CHeap: allocs == frees" cAllocs cFrees
          Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- RC String C-cell store-algebra tests (String Slice E1, Task 2)
--
-- Complement 'rcStringNodeTests' (abstract heap) by testing the REAL C cell
-- path.  Allocates a 'WokHeap', builds a CHeap-backend 'Store', calls
-- 'St.alloc (NString bs)', then asserts:
--   * 'wokStringLen' reads back the correct byte count;
--   * 'stLive' == baseline + 1 after alloc; C 'wok_stat_live' == 1;
--   * 'dropAddr' balances: stLive == baseline, wok_stat_live == 0,
--     allocs == frees (no C-heap leak);
--   * 'peak_bytes' charged = 'wouldBeCBytes (NString bs)' (the SAME rounded
--     formula on both backends, so the differential oracle would agree).

rcStringCCellTests :: TestTree
rcStringCCellTests = testGroup "rc string C-cell store algebra"
  [ -- Multi-byte UTF-8: "h\xc3\xa9llo" = 6 bytes.
    -- E3: 6 bytes <= maxInlineStr (7), so this becomes an InlineStr immediate --
    -- zero allocation on both backends.  The test was updated for E3; the
    -- corresponding heap-cell behavior is exercised by the 9-byte case below.
    testCase "multi-byte UTF-8 string (6B, <=maxInlineStr): InlineStr, 0 allocs (E3)" $ do
      hp <- Heap.wokHeapNew
      let bs       = TxEnc.encodeUtf8 (T.pack "h\233llo")  -- 6 bytes: <= maxInlineStr
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc InlineStr failed: " <> show e) }
        Right (a, s1) -> do
          -- E3: InlineStr -- no C cell, no alloc record.
          St.stAllocs (St.stStats s1) - allocsBefore @?= 0
          cAllocs <- Heap.wokStatAllocs hp
          cAllocs @?= 0
          assertBool "6-byte string is InlineStr (E3)"
            (case a of St.InlineStr _ -> True; _ -> False)
          -- dropAddr on InlineStr is a no-op.
          r2 <- runExceptT (St.dropAddr a s1)
          case r2 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr InlineStr failed: " <> show e) }
            Right _ -> Heap.wokHeapFree hp

  , -- Empty string: 0 bytes.
    -- E3: 0 bytes <= maxInlineStr, so this becomes InlineStr -- zero allocation.
    -- The test was updated for E3.
    testCase "empty string (0B, <=maxInlineStr): InlineStr, 0 allocs (E3)" $ do
      hp <- Heap.wokHeapNew
      let bs  = BS.empty
          s0  = St.emptyStore { St.stBackend = St.CHeap hp }
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc empty InlineStr failed: " <> show e) }
        Right (a, s1) -> do
          St.stAllocs (St.stStats s1) - allocsBefore @?= 0
          cAllocs <- Heap.wokStatAllocs hp
          cAllocs @?= 0
          assertBool "empty string is InlineStr (E3)"
            (case a of St.InlineStr _ -> True; _ -> False)
          -- derefPure reconstructs the NString node.
          case St.derefPure a s1 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("derefPure empty InlineStr failed: " <> show e) }
            Right c -> do
              St.cNode c @?= St.NString bs
              Heap.wokHeapFree hp

  , -- 9-byte string: ceil(9/8) = 2 -> cell_bytes = 16 + 8*2 = 32.
    testCase "9-byte string: cell_bytes = 32, alloc/drop balanced" $ do
      hp <- Heap.wokHeapNew
      let bs      = TxEnc.encodeUtf8 (T.pack "123456789")  -- 9 bytes
          charged = St.wouldBeCBytes (St.NString bs)         -- 32
          s0      = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      St.stPeakBytes (St.stStats s1) @?= charged
      blen <- case a of
        St.CAddr p -> Heap.wokStringLen p
        _          -> assertFailure "expected CAddr" >> error "unreachable"
      assertEqual "wokStringLen reads 9" (9 :: Word64) blen
      r2 <- runExceptT (St.dropAddr a s1)
      case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("dropAddr 9-byte NString failed: " <> show e) }
        Right s2 -> do
          St.stLive (St.stStats s2) @?= baseline
          cLive1 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after drop" (0 :: Int64) cLive1
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "C heap: allocs == frees" cAllocs cFrees
          Heap.wokHeapFree hp

  , -- Byte-content roundtrip: the highest-risk line in this task is the
    -- 'allocNString' 'copyBytes' into the cell body at offset 16. A wrong offset
    -- or wrong length would pass the len/peak/balance assertions above yet corrupt
    -- the content, undetected until Task 5. This test reads EVERY byte back via
    -- 'wokStringByteGet' (also the prim path Task 4 builds on) and asserts the
    -- read-back equals the original ByteString exactly. Multi-byte UTF-8 so the
    -- continuation-byte values (>= 0x80) are exercised, not just ASCII.
    testCase "byte-content roundtrip: every byte read back equals the original" $ do
      hp <- Heap.wokHeapNew
      let bs       = TxEnc.encodeUtf8 (T.pack "h\233llo w\246rld")  -- "héllo wörld", 13 bytes
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      p <- case a of
        St.CAddr p -> pure p
        _          -> assertFailure "expected CAddr" >> error "unreachable"
      -- byte_len matches the original length.
      blen <- Heap.wokStringLen p
      assertEqual "wokStringLen matches original byte count"
        (fromIntegral (BS.length bs) :: Word64) blen
      -- Read back every byte (index 0 .. byte_len-1) and rebuild the read list.
      readBack <- mapM (Heap.wokStringByteGet p)
                       (take (fromIntegral blen) [0 ..])
      -- Each cell byte (zero-extended to Word64) equals the original byte.
      let expected = map fromIntegral (BS.unpack bs) :: [Word64]
      assertEqual "every byte read back equals the original (correct offset + length copied)"
        expected readBack
      -- Drop: balanced, no leak.
      r2 <- runExceptT (St.dropAddr a s1)
      case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("dropAddr roundtrip NString failed: " <> show e) }
        Right s2 -> do
          St.stLive (St.stStats s2) @?= baseline
          cLive1 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after drop" (0 :: Int64) cLive1
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "C heap: allocs == frees" cAllocs cFrees
          Heap.wokHeapFree hp

  , -- Empty-string roundtrip: E3 makes "" an InlineStr (0 bytes <= maxInlineStr).
    -- The derefPure synthesis yields NString BS.empty; dropAddr is a no-op.
    -- The test was updated for E3; the CAddr path for empty strings no longer exists.
    testCase "byte-content roundtrip: empty string is InlineStr, deref yields NString empty (E3)" $ do
      hp <- Heap.wokHeapNew
      let bs       = BS.empty
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc empty NString failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      -- E3: empty string is InlineStr.
      assertBool "empty string is InlineStr (E3)"
        (case a of St.InlineStr _ -> True; _ -> False)
      -- derefPure synthesizes NString BS.empty (the round-trip hinge).
      case St.derefPure a s1 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("derefPure empty InlineStr failed: " <> show e) }
        Right c -> do
          St.cNode c @?= St.NString bs
          -- stLive unchanged (InlineStr has no counted cell).
          St.stLive (St.stStats s1) @?= baseline
          -- C runtime: no cell allocated.
          cAllocs <- Heap.wokStatAllocs hp
          cAllocs @?= 0
          Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- RC NForeignBytes store-level tests (FFI Slice 1, Task 2)
--
-- Tests the NForeignBytes constructor on BOTH the AbstractHeap and CHeap
-- backends:
--   * wouldBeCBytes always 24 regardless of buffer length.
--   * nodeCEligible is False (own alloc path).
--   * nodeValues returns [] (no child refs).
--   * On AbstractHeap: allocPure charges 24B to stCurBytes/stPeakBytes; drop
--     returns to baseline.
--   * On CHeap: alloc allocates a real WokForeignBytes cell; bytesBytes reads
--     back the correct bytes; dup-then-double-drop is balanced and crash-free
--     with stLive/stCurBytes returning to baseline.
-- ---------------------------------------------------------------------------

rcForeignBytesStoreTests :: TestTree
rcForeignBytesStoreTests = testGroup "foreign bytes store"
  [ testCase "wouldBeCBytes (NForeignBytes _) == 24 for any buffer size" $ do
      St.wouldBeCBytes (St.NForeignBytes BS.empty) @?= (24 :: Int)
      St.wouldBeCBytes (St.NForeignBytes (BS.pack [0..4])) @?= (24 :: Int)
      St.wouldBeCBytes (St.NForeignBytes (BS.pack (replicate 100 0))) @?= (24 :: Int)

  , testCase "nodeCEligible (NForeignBytes _) == False (own alloc path)" $ do
      St.nodeCEligible (St.NForeignBytes (BS.pack [0..4])) @?= False

  , testCase "nodeValues (NForeignBytes _) == [] (no child refs)" $ do
      St.nodeValues (St.NForeignBytes (BS.pack [0..4])) @?= []

  , testCase "AbstractHeap: alloc charges 24B, read-back correct, drop to baseline" $ do
      let bs       = BS.pack [0..4]  -- 5 bytes
          s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (a, s1)  = St.allocPure (St.NForeignBytes bs) s0
      -- Fixed 24B charge, not 16 + 8*ceil(5/8) = 24 (coincidence for this len,
      -- but the test below confirms the constant regardless of length).
      St.stCurBytes  (St.stStats s1) @?= 24
      St.stPeakBytes (St.stStats s1) @?= 24
      St.stLive (St.stStats s1) @?= baseline + 1
      -- Read-back via derefPure.
      case St.derefPure a s1 of
        Left e  -> assertFailure ("derefPure NForeignBytes failed: " <> show e)
        Right c -> St.cNode c @?= St.NForeignBytes bs
      -- Drop: stLive returns to baseline, stCurBytes returns to 0.
      case St.dropAddrPure a s1 of
        Left e  -> assertFailure ("dropAddrPure NForeignBytes failed: " <> show e)
        Right s2 -> do
          St.stLive     (St.stStats s2) @?= baseline
          St.stCurBytes (St.stStats s2) @?= 0
          St.stFrees (St.stStats s2) - St.stFrees (St.stStats s1) @?= 1

  , testCase "AbstractHeap: 100-byte buffer still charges 24B (fixed handle)" $ do
      let bs      = BS.pack (replicate 100 0xAB)
          s0      = St.emptyStore
          (_, s1) = St.allocPure (St.NForeignBytes bs) s0
      St.stCurBytes  (St.stStats s1) @?= 24
      St.stPeakBytes (St.stStats s1) @?= 24

  , testCase "AbstractHeap: dup then double-drop is balanced (no double-free)" $ do
      let bs       = BS.pack [0..4]
          s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (a, s1)  = St.allocPure (St.NForeignBytes bs) s0
      -- incref: rc goes to 2.
      s2 <- case runExceptT (St.incref a s1) of
        x -> x >>= \r -> case r of
          Left e  -> assertFailure ("incref failed: " <> show e) >> pure s1
          Right r' -> pure r'
      -- First drop: rc goes to 1, cell still live.
      case St.dropAddrPure a s2 of
        Left e  -> assertFailure ("first dropAddrPure failed: " <> show e)
        Right s3 -> do
          St.stLive (St.stStats s3) @?= baseline + 1
          -- Second drop: rc goes to 0, cell freed.
          case St.dropAddrPure a s3 of
            Left e  -> assertFailure ("second dropAddrPure failed: " <> show e)
            Right s4 -> do
              St.stLive     (St.stStats s4) @?= baseline
              St.stCurBytes (St.stStats s4) @?= 0

  , testCase "CHeap: alloc->read->drop balanced, live/cur_bytes return to baseline" $ do
      hp <- Heap.wokHeapNew
      let bs       = BS.pack [0..4]  -- 5 bytes
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NForeignBytes bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NForeignBytes CHeap failed: " <> show e)
                        >> error "unreachable" }
        Right x -> pure x
      -- Byte accounting: fixed 24B handle.
      St.stCurBytes  (St.stStats s1) @?= 24
      St.stPeakBytes (St.stStats s1) @?= 24
      -- Read-back via alloc/deref.
      r2 <- runExceptT (St.deref a s1)
      case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("deref NForeignBytes CHeap failed: " <> show e) }
        Right c -> do
          St.cNode c @?= St.NForeignBytes bs
          -- Drop: live and cur_bytes return to baseline.
          r3 <- runExceptT (St.dropAddr a s1)
          case r3 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr NForeignBytes CHeap failed: " <> show e) }
            Right s2 -> do
              St.stLive     (St.stStats s2) @?= baseline
              St.stCurBytes (St.stStats s2) @?= 0
              cLive   <- Heap.wokStatLive   hp
              cAllocs <- Heap.wokStatAllocs hp
              cFrees  <- Heap.wokStatFrees  hp
              assertEqual "C heap: live == 0 after drop" (0 :: Int64) cLive
              assertEqual "C heap: allocs == frees" cAllocs cFrees
              Heap.wokHeapFree hp

  , testCase "CHeap: dup then double-drop balanced and crash-free" $ do
      hp <- Heap.wokHeapNew
      let bs       = BS.pack [0..4]
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NForeignBytes bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NForeignBytes CHeap failed: " <> show e)
                        >> error "unreachable" }
        Right x -> pure x
      -- incref: rc goes to 2.
      r2 <- runExceptT (St.incref a s1)
      s2 <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("incref failed: " <> show e) >> error "unreachable" }
        Right r' -> pure r'
      -- First drop: rc goes to 1, no free yet.
      r3 <- runExceptT (St.dropAddr a s2)
      s3 <- case r3 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("first dropAddr CHeap failed: " <> show e)
                        >> error "unreachable" }
        Right r' -> pure r'
      St.stLive (St.stStats s3) @?= baseline + 1
      -- Second drop: rc goes to 0, foreign buffer freed, cell freed.
      r4 <- runExceptT (St.dropAddr a s3)
      case r4 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("second dropAddr CHeap failed: " <> show e) }
        Right s4 -> do
          St.stLive     (St.stStats s4) @?= baseline
          St.stCurBytes (St.stStats s4) @?= 0
          cLive   <- Heap.wokStatLive   hp
          assertEqual "C heap: live == 0 after double-drop" (0 :: Int64) cLive
          Heap.wokHeapFree hp

  , testCase "CHeap: empty buffer alloc->read->drop balanced (malloc(0) sentinel)" $ do
      -- The CHeap sentinel for the malloc(0)-may-return-NULL fix: an empty foreign
      -- buffer must alloc a non-NULL pointer, read back as empty, and free cleanly.
      hp <- Heap.wokHeapNew
      let bs       = BS.empty
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT (St.alloc (St.NForeignBytes bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc empty NForeignBytes CHeap failed: " <> show e)
                        >> error "unreachable" }
        Right x -> pure x
      St.stCurBytes (St.stStats s1) @?= 24  -- fixed handle, independent of buffer
      -- Read back as the empty ByteString (packCStringLen with len 0).
      r2 <- runExceptT (St.deref a s1)
      case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("deref empty NForeignBytes CHeap failed: " <> show e) }
        Right c -> do
          St.cNode c @?= St.NForeignBytes BS.empty
          r3 <- runExceptT (St.dropAddr a s1)
          case r3 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr empty NForeignBytes CHeap failed: " <> show e) }
            Right s2 -> do
              St.stLive     (St.stStats s2) @?= baseline
              St.stCurBytes (St.stStats s2) @?= 0
              cLive   <- Heap.wokStatLive   hp
              cAllocs <- Heap.wokStatAllocs hp
              cFrees  <- Heap.wokStatFrees  hp
              assertEqual "C heap: live == 0 after empty-buffer drop" (0 :: Int64) cLive
              assertEqual "C heap: allocs == frees (empty buffer)" cAllocs cFrees
              Heap.wokHeapFree hp

  , testCase "CHeap: bytesBytes reads foreign cell via wokForeignBytesTag fast path" $ do
      -- Directly exercise the bytesBytes fast path (the branch fromBytes/length/index
      -- actually use) on a foreign-bytes CAddr, not the deref fallback.
      hp <- Heap.wokHeapNew
      let bs = BS.pack [0..4]  -- 5 bytes
          s0 = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NForeignBytes bs) s0)
      (a, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NForeignBytes CHeap failed: " <> show e)
                        >> error "unreachable" }
        Right x -> pure x
      r2 <- runExceptT (RCP.bytesBytes (St.RVBox a) s1)
      case r2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("bytesBytes on foreign cell failed: " <> show e) }
        Right got -> do
          got @?= bs
          -- Clean up the cell so the heap teardown is leak-free.
          r3 <- runExceptT (St.dropAddr a s1)
          case r3 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr after bytesBytes failed: " <> show e) }
            Right _ -> Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- RC inline short-string tests (String Slice E3, Task 1)
--
-- Verifies that a short string (<=7 bytes) becomes an 'InlineStr' immediate
-- with ZERO allocation on both backends, while an 8-byte string still
-- allocates exactly one WokString cell.  Also confirms that 'derefPure' on
-- an 'InlineStr' reconstructs the original bytes (the round-trip hinge).
--
-- Pattern mirrors 'rcStringCCellTests': abstract-heap tests use 'allocPure' /
-- 'derefPure' directly; CHeap tests use 'runExceptT (St.alloc ...)' to drive
-- the real dispatch.

rcInlineStringTests :: TestTree
rcInlineStringTests = testGroup "rc inline string (E3)"
  [ -- -----------------------------------------------------------------------
    -- Zero-alloc on abstract heap (AbstractHeap backend)
    -- -----------------------------------------------------------------------
    testCase "<=7-byte string: InlineStr immediate, 0 allocs on AbstractHeap" $ do
      let bs       = BS.pack [97, 98, 99, 100, 101, 102, 103]  -- "abcdefg", 7 bytes
          s0       = St.emptyStore
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e       -> assertFailure ("alloc InlineStr failed: " <> show e)
        Right (a, s1) -> do
          -- No allocation recorded: InlineStr bypasses recordAlloc.
          St.stAllocs (St.stStats s1) - allocsBefore @?= 0
          -- The address is InlineStr, not HAddr.
          assertBool "7-byte string is InlineStr on AbstractHeap"
            (case a of St.InlineStr _ -> True; _ -> False)

  , testCase "8-byte string: WokString cell, 1 alloc on AbstractHeap" $ do
      let bs       = BS.pack [97, 98, 99, 100, 101, 102, 103, 104]  -- "abcdefgh", 8 bytes
          s0       = St.emptyStore
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e        -> assertFailure ("alloc NString failed: " <> show e)
        Right (a, s1) -> do
          -- Exactly one allocation recorded for the heap cell.
          St.stAllocs (St.stStats s1) - allocsBefore @?= 1
          -- The address is HAddr (abstract heap cell), not InlineStr.
          assertBool "8-byte string is NOT InlineStr on AbstractHeap"
            (case a of St.InlineStr _ -> False; _ -> True)

    -- -----------------------------------------------------------------------
    -- Zero-alloc on CHeap backend
    -- -----------------------------------------------------------------------
  , testCase "<=7-byte string: InlineStr immediate, 0 allocs on CHeap" $ do
      hp <- Heap.wokHeapNew
      let bs       = BS.pack [97, 98, 99, 100, 101, 102, 103]  -- "abcdefg", 7 bytes
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("alloc InlineStr CHeap failed: " <> show e) }
        Right (a, s1) -> do
          -- No allocation recorded on the Haskell side.
          St.stAllocs (St.stStats s1) - allocsBefore @?= 0
          -- No allocation on the C side either.
          cAllocs <- Heap.wokStatAllocs hp
          cAllocs @?= 0
          assertBool "7-byte string is InlineStr on CHeap"
            (case a of St.InlineStr _ -> True; _ -> False)
          Heap.wokHeapFree hp

  , testCase "8-byte string: WokString cell, 1 alloc on CHeap" $ do
      hp <- Heap.wokHeapNew
      let bs       = BS.pack [97, 98, 99, 100, 101, 102, 103, 104]  -- "abcdefgh", 8 bytes
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("alloc NString CHeap 8B failed: " <> show e) }
        Right (a, s1) -> do
          St.stAllocs (St.stStats s1) - allocsBefore @?= 1
          assertBool "8-byte string is NOT InlineStr on CHeap"
            (case a of St.InlineStr _ -> False; _ -> True)
          -- Drop and verify balanced.
          r2 <- runExceptT (St.dropAddr a s1)
          case r2 of
            Left e  -> do { Heap.wokHeapFree hp
                          ; assertFailure ("dropAddr 8B CHeap failed: " <> show e) }
            Right _ -> do
              cAllocs <- Heap.wokStatAllocs hp
              cFrees  <- Heap.wokStatFrees hp
              assertEqual "C heap: allocs == frees" cAllocs cFrees
              Heap.wokHeapFree hp

    -- -----------------------------------------------------------------------
    -- deref round-trip: InlineStr -> NString
    -- -----------------------------------------------------------------------
  , testCase "InlineStr round-trips: derefPure yields NString with same bytes" $ do
      let bs = BS.pack [104, 105]  -- "hi", 2 bytes
          s0 = St.emptyStore
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e        -> assertFailure ("alloc hi failed: " <> show e)
        Right (a, s1) -> do
          assertBool "\"hi\" is InlineStr"
            (case a of St.InlineStr _ -> True; _ -> False)
          case St.derefPure a s1 of
            Left e  -> assertFailure ("derefPure InlineStr failed: " <> show e)
            Right c -> St.cNode c @?= St.NString bs

    -- -----------------------------------------------------------------------
    -- isInline / isUncounted
    -- -----------------------------------------------------------------------
  , testCase "isInline (InlineStr _) is True" $ do
      let bs = BS.pack [104, 105]  -- "hi"
      St.isInline (St.InlineStr bs) @?= True

  , testCase "isUncounted (InlineStr _) is True" $ do
      let bs = BS.pack [104, 105]  -- "hi"
      St.isUncounted (St.InlineStr bs) @?= True

    -- -----------------------------------------------------------------------
    -- dropAddr on InlineStr is a no-op (no cascade, no free)
    -- -----------------------------------------------------------------------
  , testCase "dropAddr (InlineStr _) is a no-op: 0 frees, stLive unchanged" $ do
      let bs = BS.pack [65, 66, 67]  -- "ABC", 3 bytes
          s0 = St.emptyStore
          freesBefore = St.stFrees (St.stStats s0)
          liveBefore  = St.stLive (St.stStats s0)
      r <- runExceptT (St.dropAddr (St.InlineStr bs) s0)
      case r of
        Left e  -> assertFailure ("dropAddr InlineStr failed: " <> show e)
        Right s1 -> do
          St.stFrees (St.stStats s1) @?= freesBefore
          St.stLive  (St.stStats s1) @?= liveBefore

    -- -----------------------------------------------------------------------
    -- Empty string is inline (0 bytes <= 7)
    -- -----------------------------------------------------------------------
  , testCase "empty string is InlineStr (0 bytes <= maxInlineStr)" $ do
      let s0 = St.emptyStore
          allocsBefore = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString BS.empty) s0)
      case r of
        Left e        -> assertFailure ("alloc empty string failed: " <> show e)
        Right (a, s1) -> do
          St.stAllocs (St.stStats s1) - allocsBefore @?= 0
          assertBool "empty string is InlineStr"
            (case a of St.InlineStr _ -> True; _ -> False)

    -- -----------------------------------------------------------------------
    -- maxInlineStr boundary: exactly 7 bytes is inline, 8 is heap
    -- -----------------------------------------------------------------------
  , testCase "maxInlineStr boundary: 7-byte string is inline, 8-byte string is heap" $ do
      let bs7 = BS.replicate 7 65  -- 7 x 'A'
          bs8 = BS.replicate 8 65  -- 8 x 'A'
          s0  = St.emptyStore
      r7 <- runExceptT (St.alloc (St.NString bs7) s0)
      r8 <- runExceptT (St.alloc (St.NString bs8) s0)
      case (r7, r8) of
        (Right (a7, _), Right (a8, _)) -> do
          assertBool "7-byte: InlineStr"
            (case a7 of St.InlineStr _ -> True; _ -> False)
          assertBool "8-byte: not InlineStr"
            (case a8 of St.InlineStr _ -> False; _ -> True)
        _ -> assertFailure "alloc failed for boundary test"

    -- -----------------------------------------------------------------------
    -- String-literal CAF allocation (E3 Task 4)
    -- -----------------------------------------------------------------------
  , testCase "string-literal CAF (foo = \"/\") allocates 0 cells on both backends" $ do
      cm <- elaboratedModuleOf "test/rc-string/29-string-literal-caf.wok"
      let pruned = pruneToReachable cm
          instrumented = reusePairing (Perceus.insertRC pruned)
      -- AbstractHeap backend
      absRun <- RCM.runModuleRC instrumented >>= \case
        Left e  -> assertFailure ("AbstractHeap RC run failed: " <> show e)
        Right r -> pure r
      let absStats = RCM.rcStats absRun
          absBaseline = RCM.rcBaseline absRun
      assertEqual "AbstractHeap: string-literal CAF allocates 0 cells"
        absBaseline (St.stAllocs absStats - St.stFrees absStats)
      -- CHeap backend
      hp <- Heap.wokHeapNew
      cRun <- RCM.runModuleRCUncheckedWith (St.CHeap hp) instrumented >>= \case
        Left e  -> Heap.wokHeapFree hp >> assertFailure ("CHeap RC run failed: " <> show e)
        Right r -> pure r
      let cStats = RCM.rcStats cRun
          cBaseline = RCM.rcBaseline cRun
      cAllocs <- Heap.wokStatAllocs hp
      assertEqual "CHeap: string-literal CAF allocates 0 cells"
        0 cAllocs
      assertEqual "CHeap: live matches baseline"
        cBaseline (St.stLive cStats)
      -- Verify output is "\"/\"" (Haskell show renders with quotes and escaping)
      assertEqual "rendered output is \"/\" (with show escaping)"
        "\"/\"" (T.unpack (RCM.rcOutput absRun))
      Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- RC inline-string SLOT encoding (E3 Task 2)
--
-- These tests pin the bit-packing in 'encodeSlotC' / 'decodeSlotC' for the
-- 'InlineStr' case and verify that a constructor whose only non-nullary field is
-- a short string is C-eligible and round-trips on both backends.
--
-- Two sub-groups:
--   (A) Value-level round-trip -- call 'St.encodeSlotC' then 'St.decodeSlotC'
--       directly, so the bit layout is verified independently of the interpreter.
--   (B) Interpreter-level round-trip -- run a tiny wok program on both backends
--       and assert C-eligibility via 'cAllocs'.

rcInlineStringSlotTests :: TestTree
rcInlineStringSlotTests = testGroup "InlineStringSlot (E3 Task 2)"
  [ -- -----------------------------------------------------------------------
    -- (A) Value-level round-trip: encodeSlotC -> decodeSlotC
    -- -----------------------------------------------------------------------
    testGroup "value-level encode/decode round-trip"
      [ testCase "empty string (0 bytes) encodes and decodes" $ do
          let bs  = BS.empty
              val = St.RVBox (St.InlineStr bs)
          case St.encodeSlotC val of
            Nothing       -> assertFailure "encodeSlotC returned Nothing for empty InlineStr"
            Just (kind, w) -> do
              kind @?= St.KPointer
              -- low 3 bits must be 111
              (w .&. 0x7) @?= 0x7
              St.decodeSlotC kind w @?= val

      , testCase "1-byte string encodes and decodes" $ do
          let bs  = BS.pack [65]  -- "A"
              val = St.RVBox (St.InlineStr bs)
          case St.encodeSlotC val of
            Nothing        -> assertFailure "encodeSlotC returned Nothing for 1-byte InlineStr"
            Just (kind, w) -> do
              kind @?= St.KPointer
              (w .&. 0x7) @?= 0x7
              -- length field = 1
              fromIntegral ((w `shiftR` 3) .&. 0x7) @?= (1 :: Int)
              St.decodeSlotC kind w @?= val

      , testCase "7-byte string (maxInlineStr) encodes and decodes" $ do
          let bs  = BS.pack [104, 105, 106, 107, 108, 109, 110]  -- "hijklmn"
              val = St.RVBox (St.InlineStr bs)
          case St.encodeSlotC val of
            Nothing        -> assertFailure "encodeSlotC returned Nothing for 7-byte InlineStr"
            Just (kind, w) -> do
              kind @?= St.KPointer
              (w .&. 0x7) @?= 0x7
              fromIntegral ((w `shiftR` 3) .&. 0x7) @?= (7 :: Int)
              St.decodeSlotC kind w @?= val

      , testCase "\"hi\" (2 bytes) encodes and decodes" $ do
          let bs  = BS.pack [104, 105]  -- "hi"
              val = St.RVBox (St.InlineStr bs)
          case St.encodeSlotC val of
            Nothing        -> assertFailure "encodeSlotC returned Nothing for \"hi\" InlineStr"
            Just (kind, w) -> St.decodeSlotC kind w @?= val

      , testCase "nullary Inline re-encoding: low 3 bits = 011, decodes to same tag" $ do
          let tid = 42 :: Word32
              val = St.RVBox (St.Inline tid)
          case St.encodeSlotC val of
            Nothing        -> assertFailure "encodeSlotC returned Nothing for Inline tag"
            Just (kind, w) -> do
              kind @?= St.KPointer
              -- low 3 bits must be 011 (nullary discriminant)
              (w .&. 0x7) @?= 0x3
              -- bit 2 must be 0 (not the inline-string code 111)
              (w .&. 0x4) @?= 0
              St.decodeSlotC kind w @?= val

      , testCase "no cross-talk: Inline and InlineStr in same slot position differ by bit 2" $ do
          -- Both use the 11 low-2-bit class; Inline has bit2=0, InlineStr has bit2=1.
          let inlineVal   = St.RVBox (St.Inline 0)
              inlineStrVal = St.RVBox (St.InlineStr BS.empty)
          case (St.encodeSlotC inlineVal, St.encodeSlotC inlineStrVal) of
            (Just (_, wi), Just (_, ws)) -> do
              -- Discriminants must differ at bit 2
              assertBool "Inline bit2 = 0" ((wi .&. 4) == 0)
              assertBool "InlineStr bit2 = 1" ((ws .&. 4) /= 0)
            _ -> assertFailure "encodeSlotC returned Nothing for one of the values"
      ]

    -- -----------------------------------------------------------------------
    -- (B) Interpreter-level round-trip: constructor with short-string field
    --   Duplicate removed: see rcCBackendTargeted / "String field is a pointer
    --   cell (constructor with a String field is C-eligible)" for the canonical
    --   test (exact cAllocs == 1 assertion, same fallback-lstr.wok program).
    -- -----------------------------------------------------------------------

  , testCase "constructor with short-string field AND nullary sibling round-trips on both backends" $ do
      -- Pair "hi" True: "hi" = InlineStr (111 slot), True = Inline tid (011 slot).
      -- Both field kinds must coexist correctly; no cross-talk between 011 and 111.
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/inline-str-and-nullary.wok"
      -- The interpreter renders String values via show, so "hi" appears as "\"hi\"".
      assertEqual "result is the string field (rendered with quotes)" (T.pack "\"hi\"") txt
      assertEqual "no value-CAF baseline" 0 bl
      -- 1 cell: the Pair NCon only (both fields are slot-encoded; no extra cells).
      assertParityBalanced "InlineStr + Inline fields coexist (E3 Task 2)" 1 absSt cSt bl
      assertBool "Pair NCon routes to C heap" (cAllocs > 0)
  ]

-- ---------------------------------------------------------------------------
-- RC Array C-cell store-algebra tests (Array Slice B, Task 6)
--
-- These complement 'rcArrayNodeTests' (which operates on the abstract heap) by
-- repeating the same store-algebra invariants on the REAL C cell path.  Each
-- test allocates a 'WokHeap', builds a CHeap-backend 'Store', runs 'alloc' /
-- 'incref' / 'dropAddr' via 'runExceptT', then asserts both the Haskell-side
-- 'stLive' and the C runtime's 'wok_stat_live' counter return to baseline.
-- Passing both counters is what proves the C cell -- not just the abstract
-- mirror -- was genuinely exercised.
--
-- Two sub-cases pin the two important element-kind branches of the C cascade:
--
--   inline-element (Array U64 = KLitInt elemkind): teardown skips every slot
--   (raw-lit, uncounted).  Only the array cell itself is freed; cascade emits
--   zero child drops.
--
--   pointer-scheme (Array (NCon children) = KPointer elemkind): each counted
--   child (CAddr or HAddr) is dropped exactly once; uncounted Inline slots are
--   skipped.  The heap returns to baseline with no double-free.

rcArrayCCellTests :: TestTree
rcArrayCCellTests = testGroup "rc array C-cell store algebra"
  [ -- -----------------------------------------------------------------------
    -- Inline-element array (KLitInt elemkind): cascade emits zero child drops.
    --
    -- Build 'Array U64 = [1, 2, 3]' on a real WokHeap.  Before the drop:
    -- stLive == baseline + 1 (the array cell) and wok_stat_live == 1.
    -- After 'dropAddr' the array: stLive == baseline and wok_stat_live == 0,
    -- confirming no spurious child drops fired and no C-heap leak occurred.
    testCase "inline-element array (KLitInt): drop frees only the array cell, cascade empty" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
          elems = [ St.RVLit (Anf.LInt 1)
                  , St.RVLit (Anf.LInt 2)
                  , St.RVLit (Anf.LInt 3)
                  ]
      r <- runExceptT $ do
             (arr, s1) <- St.alloc (St.NArray elems) s0
             pure (arr, s1)
      (arr, s1) <- case r of
        Left e  -> assertFailure ("alloc NArray failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- The array cell is live; no child cells (raw-lit elements are inline).
      St.stLive (St.stStats s1) @?= baseline + 1
      cLive0 <- Heap.wokStatLive hp
      assertEqual "wok_stat_live == 1 after array alloc" (1 :: Int64) cLive0
      -- Drop the array.
      r2 <- runExceptT (St.dropAddr arr s1)
      case r2 of
        Left e  -> do
          Heap.wokHeapFree hp
          assertFailure ("dropAddr array failed: " <> show e)
        Right s2 -> do
          St.stLive (St.stStats s2) @?= baseline
          St.stFrees (St.stStats s2) - St.stFrees (St.stStats s1) @?= 1
          cLive1 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after drop (heap at baseline, no leak)" (0 :: Int64) cLive1
          Heap.wokHeapFree hp

  , -- -----------------------------------------------------------------------
    -- Pointer-scheme array (KPointer elemkind): each counted child dropped once.
    --
    -- Allocate two one-field NCon children on the C heap (they become CAddr),
    -- then build 'Array (NCon) = [RVBox child1, RVBox child2]'.  Before the
    -- drop: stLive == baseline + 3 (2 children + 1 array) and wok_stat_live == 3.
    -- After 'dropAddr' the array:
    --   * the cascade decodes the two KPointer slots and drops child1/child2;
    --   * stLive == baseline and wok_stat_live == 0;
    --   * no double-free (stFrees incremented by exactly 3: array + 2 children).
    testCase "pointer-scheme array (KPointer): each counted child dropped once, no double-free" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT $ do
             -- Allocate two one-field NCons (C-eligible: arity 1, field is LInt).
             (c1, s1) <- St.alloc (St.NCon (T.pack "Some") [St.RVLit (Anf.LInt 10)]) s0
             (c2, s2) <- St.alloc (St.NCon (T.pack "Some") [St.RVLit (Anf.LInt 20)]) s1
             -- Build the pointer-scheme array; elements are RVBox (CAddr ...).
             (arr, s3) <- St.alloc (St.NArray [St.RVBox c1, St.RVBox c2]) s2
             pure (c1, c2, arr, s3)
      (c1, c2, arr, s3) <- case r of
        Left e  -> assertFailure ("setup failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- Three cells live: child1, child2, the array.
      St.stLive (St.stStats s3) @?= baseline + 3
      cLive0 <- Heap.wokStatLive hp
      assertEqual "wok_stat_live == 3 after alloc (2 children + 1 array)" (3 :: Int64) cLive0
      -- Drop the array; the cascade must drop child1 and child2 exactly once.
      r2 <- runExceptT (St.dropAddr arr s3)
      case r2 of
        Left e  -> do
          Heap.wokHeapFree hp
          assertFailure ("dropAddr array failed: " <> show e)
        Right s4 -> do
          St.stLive (St.stStats s4) @?= baseline
          -- 3 frees: the array cell + both children.
          St.stFrees (St.stStats s4) - St.stFrees (St.stStats s3) @?= 3
          cLive1 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after cascade (heap at baseline)" (0 :: Int64) cLive1
          -- No double-free: children must be gone (deref on a CAddr has no
          -- pure reconstruction, so we verify via wok_stat_allocs == wok_stat_frees).
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "C heap: allocs == frees (fully balanced)" cAllocs cFrees
          -- Verify the children are absent from the abstract store too (no HAddr
          -- was produced for c1/c2 since they are CAddr; assert the cascade
          -- registered 3 total frees on the Haskell-side stats).
          assertBool "children were counted CAddr slots (non-vacuity: 3 frees recorded)"
            (St.stFrees (St.stStats s4) - St.stFrees (St.stStats s0) == 3)
          -- Deref pure does not apply to CAddr; confirm the array addr is a CAddr
          -- (i.e. actually routed to the C heap, not an HAddr fallback).
          assertBool "array was allocated on the C heap (arr is a CAddr)"
            (case arr of St.CAddr _ -> True; _ -> False)
          assertBool "c1 was allocated on the C heap (c1 is a CAddr)"
            (case c1 of St.CAddr _ -> True; _ -> False)
          assertBool "c2 was allocated on the C heap (c2 is a CAddr)"
            (case c2 of St.CAddr _ -> True; _ -> False)
          Heap.wokHeapFree hp

  , -- -----------------------------------------------------------------------
    -- Shared array (rc 2): first drop only decrements, second drop frees + cascades.
    --
    -- Build a pointer-scheme array at rc 1, incref to rc 2.  First 'dropAddr'
    -- must leave wok_stat_live unchanged (still 3).  Second 'dropAddr' must free
    -- the array AND its children, returning both counters to baseline.
    testCase "shared pointer-scheme array: dup+2xdrop frees exactly once, no double-free" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
      r <- runExceptT $ do
             (c1, s1) <- St.alloc (St.NCon (T.pack "Leaf") [St.RVLit (Anf.LInt 42)]) s0
             (arr, s2) <- St.alloc (St.NArray [St.RVBox c1]) s1
             s3 <- St.incref arr s2
             pure (c1, arr, s3)
      (c1, arr, s3) <- case r of
        Left e  -> assertFailure ("setup failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- Shared at rc 2: stLive == baseline + 2 (child + array).
      St.stLive (St.stStats s3) @?= baseline + 2
      cLive0 <- Heap.wokStatLive hp
      assertEqual "wok_stat_live == 2 after dup (array shared at rc 2)" (2 :: Int64) cLive0
      -- First drop: only decrements (rc 2 -> 1).
      r2 <- runExceptT (St.dropAddr arr s3)
      s4 <- case r2 of
        Left e  -> do { Heap.wokHeapFree hp; assertFailure ("first drop failed: " <> show e) }
        Right s -> pure s
      St.stLive (St.stStats s4) @?= baseline + 2
      cLive1 <- Heap.wokStatLive hp
      assertEqual "wok_stat_live == 2 after first drop (rc 2 -> 1, no free yet)" (2 :: Int64) cLive1
      -- Second drop: rc 1 -> 0, array freed, cascade drops child.
      r3 <- runExceptT (St.dropAddr arr s4)
      case r3 of
        Left e  -> do
          Heap.wokHeapFree hp
          assertFailure ("second drop failed: " <> show e)
        Right s5 -> do
          St.stLive (St.stStats s5) @?= baseline
          cLive2 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after final drop (heap at baseline)" (0 :: Int64) cLive2
          -- Exactly 2 frees: the array cell and the one child.
          St.stFrees (St.stStats s5) - St.stFrees (St.stStats s3) @?= 2
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "C heap: allocs == frees (fully balanced)" cAllocs cFrees
          assertBool "c1 is a CAddr (non-vacuity: C heap was exercised)"
            (case c1 of St.CAddr _ -> True; _ -> False)
          Heap.wokHeapFree hp

  , -- -----------------------------------------------------------------------
    -- Cross-heap child: a C 'WokArray' slot holding an HAddr (abstract-heap)
    -- child.  This is the one cascade sub-case the CAddr-child cases above do
    -- not cover: the array lives on the C heap, but one of its KPointer slots
    -- points at a cell on the ABSTRACT 'IntMap' heap.
    --
    -- 'allocPure' always allocates on the abstract heap (an HAddr) regardless of
    -- the backend, so it forces a genuine cross-heap edge even under a 'CHeap'
    -- store.  'encodeSlotC' packs an HAddr as a KPointer slot @(i << 2) | 1@,
    -- so the array's elemkind is KPointer and the teardown loop must decode the
    -- slot back to the HAddr and route the drop to the abstract-heap step.
    --
    -- Before the drop: stLive == baseline + 2 (the abstract child + the C array),
    -- wok_stat_live == 1 (only the array is on the C heap).  After 'dropAddr':
    --   * the C array cell is freed: wok_stat_live returns to 0;
    --   * the HAddr child's abstract cell is dropped exactly once (a UAF deref);
    --   * stLive returns to baseline; stFrees +2 (array + child); no double-free.
    testCase "cross-heap child (HAddr in a C array slot): cascade drops the abstract child once" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          baseline = St.stLive (St.stStats s0)
          -- 'allocPure' forces the child onto the ABSTRACT heap (an HAddr) even
          -- though the backend is 'CHeap'.
          (child, s1) = St.allocPure (St.NCon (T.pack "Abstract") [St.RVLit (Anf.LInt 7)]) s0
      -- Non-vacuity: the child must be an HAddr (abstract heap), not a CAddr.
      assertBool "child is an HAddr (abstract-heap node; the cross-heap edge)"
        (case child of St.HAddr _ -> True; _ -> False)
      r <- runExceptT $ do
             (arr, s2) <- St.alloc (St.NArray [St.RVBox child]) s1
             pure (arr, s2)
      (arr, s2) <- case r of
        Left e  -> do { Heap.wokHeapFree hp; assertFailure ("alloc NArray failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      -- The array lands on the C heap (it is a CAddr); the child stays abstract.
      assertBool "array is a CAddr (lands on the C heap)"
        (case arr of St.CAddr _ -> True; _ -> False)
      -- Two cells live: the abstract child + the C array.
      St.stLive (St.stStats s2) @?= baseline + 2
      cLive0 <- Heap.wokStatLive hp
      assertEqual "wok_stat_live == 1 (only the array is on the C heap)" (1 :: Int64) cLive0
      -- Drop the array; the cascade must decode the KPointer slot to the HAddr
      -- child and drop it on the abstract heap exactly once.
      r2 <- runExceptT (St.dropAddr arr s2)
      case r2 of
        Left e  -> do
          Heap.wokHeapFree hp
          assertFailure ("dropAddr array failed: " <> show e)
        Right s3 -> do
          St.stLive (St.stStats s3) @?= baseline
          -- 2 frees: the C array cell + the abstract child.
          St.stFrees (St.stStats s3) - St.stFrees (St.stStats s2) @?= 2
          cLive1 <- Heap.wokStatLive hp
          assertEqual "wok_stat_live == 0 after drop (C array cell freed)" (0 :: Int64) cLive1
          -- The abstract child must be gone: a pure deref now fails (use-after-free).
          -- This is the load-bearing check -- it fails if the cross-heap HAddr child
          -- leaked (deref would still succeed) or was double-dropped (the drop above
          -- would have raised before reaching here).
          case St.derefPure child s3 of
            Left _  -> pure ()
            Right _ -> assertFailure "cross-heap HAddr child was not freed through the array cascade"
          Heap.wokHeapFree hp
  , -- -----------------------------------------------------------------------
    -- Region Slice R1: a C-eligible NCon born in the C arena is UNCOUNTED, and
    -- 'incref' on it is INERT (no @wok_dup@). This pins the 'incref' CAddr arena
    -- guard symmetric with the 'dropAddr' one: arena-alloc a one-field NCon under
    -- CHeap (-> a real 'wok_arena_alloc' CAddr), read its raw rc, 'incref' it, and
    -- assert the rc is UNCHANGED and the counted stats are untouched. (The arena
    -- cell's rc field is unused; 'wok_arena_close' reclaims it, not refcounting.)
    testCase "C-arena cell: incref is inert (no wok_dup, rc unchanged, counted stats untouched)" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          allocs0 = St.stAllocs (St.stStats s0)
          live0   = St.stLive (St.stStats s0)
      r <- runExceptT $ do
             -- Open an arena and born a C-eligible NCon in it (arity 1, LInt field).
             s1        <- St.arenaOpenRC s0
             (a, s2)   <- St.arenaAlloc (St.NCon (T.pack "Some") [St.RVLit (Anf.LInt 7)]) s1
             rcBefore  <- liftIO $ case a of
                            St.CAddr p -> Heap.wokRc p
                            _          -> error "arena NCon under CHeap must be a CAddr"
             -- incref the arena cell: must be a no-op (no wok_dup).
             s3        <- St.incref a s2
             rcAfter   <- liftIO $ case a of
                            St.CAddr p -> Heap.wokRc p
                            _          -> error "unreachable"
             s4        <- St.arenaClose s3
             pure (a, rcBefore, rcAfter, s2, s4)
      case r of
        Left e -> Heap.wokHeapFree hp >> assertFailure ("C-arena incref test failed: " <> show e)
        Right (a, rcBefore, rcAfter, s2, s4) -> do
          -- The cell is a real C arena cell.
          assertBool "arena NCon under CHeap is a CAddr" (case a of St.CAddr _ -> True; _ -> False)
          -- incref did NOT bump the C runtime refcount.
          assertEqual "incref of a C-arena cell leaves wok_rc unchanged (inert dup)"
            rcBefore rcAfter
          -- The arena cell never touched the COUNTED books (allocs/live unchanged
          -- by the alloc), and incref/close left them at the pre-open baseline.
          assertEqual "arena alloc did not bump counted allocs"
            allocs0 (St.stAllocs (St.stStats s2))
          assertEqual "counted allocs still at baseline after incref+close"
            allocs0 (St.stAllocs (St.stStats s4))
          assertEqual "counted live still at baseline after incref+close"
            live0 (St.stLive (St.stStats s4))
          -- Arena bytes returned to the pre-open value (no arena leak).
          assertEqual "arena_bytes back to 0 after close"
            0 (St.stArenaBytes (St.stStats s4))
          Heap.wokHeapFree hp
  , -- -----------------------------------------------------------------------
    -- Region Slice R1 (code-review #2): the C-INELIGIBLE arena FALLBACK charges
    -- 0 arena bytes, matching the C runtime (which never ran 'wok_arena_alloc'
    -- for it). Forces the DESCRIPTOR first-kind-wins MISMATCH branch of
    -- 'arenaAlloc' under CHeap: a polymorphic constructor is allocated FIRST with
    -- a 'KLitInt' field (recording the tag's slot descriptor as [KLitInt]), then
    -- arena-allocated with a MISMATCHING 'KLitUnit' field. The second node is
    -- still 'nodeCEligible' (arity 1, both fields encode), so 'wouldBeCBytes' is
    -- NONZERO (16) -- but no 'wok_arena_alloc' runs (the mismatch falls back to
    -- the abstract arena), so the C @arena_bytes@ stays 0. The abstract side must
    -- therefore charge 0 too (via 'arenaAllocPureFallback'), or 'stArenaBytes'
    -- would diverge from the C @wok_stat_arena_bytes@ and fail the parity oracle.
    testCase "C-arena descriptor-mismatch fallback charges 0 arena bytes (parity)" $ do
      hp <- Heap.wokHeapNew
      let s0 = St.emptyStore { St.stBackend = St.CHeap hp }
          con = T.pack "Poly"
      r <- runExceptT $ do
             -- First alloc (counted C cell) records the tag descriptor as [KLitInt].
             (_, sA) <- St.alloc (St.NCon con [St.RVLit (Anf.LInt 1)]) s0
             -- The node WOULD be C-eligible (so 'wouldBeCBytes' is nonzero); confirm.
             let mismatch = St.NCon con [St.RVLit Anf.LUnit]
             liftIO $ assertBool "the mismatching arena node is genuinely C-eligible (nonzero would-be bytes)"
                        (St.wouldBeCBytes mismatch > 0)
             sOpen        <- St.arenaOpenRC sA
             let arenaB0   = St.stArenaBytes (St.stStats sOpen)
             -- Arena-alloc the SAME constructor with a MISMATCHING field kind
             -- ('KLitUnit' vs the recorded 'KLitInt') -> descriptor-mismatch
             -- fallback to the abstract arena, which must charge 0 bytes.
             (a, sMis)    <- St.arenaAlloc mismatch sOpen
             pure (a, arenaB0, sMis, sOpen)
      case r of
        Left e -> Heap.wokHeapFree hp >> assertFailure ("arena descriptor-mismatch test failed: " <> show e)
        Right (a, arenaB0, sMis, _) -> do
          -- The fallback landed on the ABSTRACT arena (an HAddr), not a C cell.
          assertBool "descriptor-mismatch arena alloc falls back to an abstract HAddr"
            (case a of St.HAddr _ -> True; _ -> False)
          -- THE PARITY POINT: the abstract side charged 0 arena bytes for the
          -- fallback (matching the C runtime's @arena_bytes@, which saw nothing),
          -- even though the node's 'wouldBeCBytes' is nonzero.
          assertEqual "C-ineligible arena fallback charges 0 arena bytes (matches C)"
            arenaB0 (St.stArenaBytes (St.stStats sMis))
          Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- M3-b (Task 3): the stored-continuation differential oracle.
--
-- Each 'test/rc-m3/*.wok' program routes a captured continuation THROUGH a
-- runtime cell: the op-arm '__cont_store's its resume into a fresh
-- 'ContCell' (move-in, no incref), '__cont_take's it back out (move-out, no
-- incref, cell emptied), and resumes it ONCE within the handler's dynamic extent
-- (resume-site semantics). 'store' returns the filled cell (Design A: the
-- reference oracle models the cell as an immutable 'VCon "ContCell" [k]' wrapper
-- with no in-place mutation, so the filled cell is threaded as a value; the RC
-- machine mutates in place and returns the same handle, so the two agree).
--
-- The boundary guard ('firstOrderNoHandlerViolations') still REJECTS the escaping
-- resume until Task 4, so these run via 'assertRcAgrees' (the
-- 'runModuleRCUnchecked' bypass) rather than the guard-gated corpus groups.
-- 'assertRcAgrees' is BOTH the differential (RC output == reference output) AND
-- the heap-stats oracle (live + allocs-minus-frees return to the value-CAF
-- baseline), with the 'rcMemSafetyFault' hardening that catches a
-- double-free/UAF even behind a reference failure. NO incref on store/take is
-- verified by the heap balance: an incref-on-store would leak the NCont
-- (live > baseline); the rc==1 floor at 'moveOutCont' fires loudly on any slipped
-- double-resume.
rcM3StoreTests :: [FilePath] -> TestTree
rcM3StoreTests files = testGroup "rc-m3 (stored-continuation differential)"
  [ testCase (takeBaseName f) (assertRcAgrees f) | f <- files ]

-- ---------------------------------------------------------------------------
-- M3 Task 4: boundary admission of the store route + carrier-wall rejection.
--
-- PART A (admission) is proven by 'rcM3AdmitTests': the store-route program
-- 'test/rc-m3/01-store-resume.wok' now produces EMPTY boundary violations under
-- the relaxed 'm2bHandlerViolations' AND runs HEAP-BALANCED through the CHECKED
-- production runner 'runModuleRC' (not just the 'Unchecked' bypass the
-- differential corpus uses). That is the proof the relaxation actually lets the
-- store route run in production.
--
-- PART A (narrowness) + the cycle exploit are proven by 'rcM3RejectTests':
--   * 'test/rc-m3-reject/02-resume-escapes-non-store.wok' --- a 'resume' that
--     escapes into a NON-'__cont_store' position (here, an ALIAS stored: 'let k2 =
--     k') --- STAYS rejected by the boundary, confirming the exemption admits
--     EXACTLY the literal '__cont_store cell resume' argument and nothing else.
--   * 'test/rc-m3-reject/01-cycle-cont-reaches-cell.wok' --- the closest surface
--     approximation of the cycle (store 'resume' into the handler's OWN baton, so
--     the parked continuation would counted-reach its own cell) --- is REJECTED at
--     ELABORATION by the type checker's OccursCheck (the type-level carrier wall,
--     spec §10.3): the cell's answer type would have to contain the continuation's
--     own result type. No surface program can build the cycle, so the static and
--     runtime carrier-wall checks are exercised on a hand-constructed owned set in
--     'rcM3CarrierWallTests' below (the bite at the achievable level).
--
-- RESEARCH FINDING (the headline). The cycle 'cell -> NCont -> cell' WAS built
-- operationally at the heap level (see 'rcM3CarrierWallTests': a captured prefix
-- whose nested-handler param value IS the cell, so 'continuationOwned prefix ==
-- [cellAddr]'; dropping the cell then double-frees it). It is therefore a real,
-- load-bearing hazard --- NOT a vacuous one. But every SURFACE route to it is
-- blocked one layer up: storing/returning a 'resume' whose result type ties back
-- to the cell/answer type is an OccursCheck. So the carrier-wall checks are a
-- TESTED DEFENSIVE BACKSTOP (spec §4.3 "checked, not assumed"): the static
-- 'm3CarrierWallViolations' rejects a store into a non-local (captured/enclosing)
-- cell, and the runtime '__cont_store' check rejects a store whose continuation's
-- owned set already contains the cell --- each red-checked here.

-- | PART A admission proof: the store route is admitted by the guard AND runs
-- heap-balanced through the CHECKED production runner 'runModuleRC'.
rcM3AdmitTests :: TestTree
rcM3AdmitTests = testGroup "rc-m3 admit (store route through CHECKED runModuleRC)"
  [ testCase "01-store-resume: empty boundary violations under the relaxed guard" $ do
      vs <- boundaryViolationsOf "test/rc-m3/01-store-resume.wok"
      assertEqual "store route must be admitted (no boundary violations)" [] vs
  , testCase "01-store-resume: heap-balanced through the CHECKED runModuleRC" $ do
      cm <- elaboratedModuleOf "test/rc-m3/01-store-resume.wok"
      let pruned = pruneToReachable cm
      rc <- RCM.runModuleRC (Perceus.insertRC pruned)
      case (Interp.runModule pruned, rc) of
        (Right v, Right run) -> do
          -- Production runner agrees with the reference AND returns to baseline.
          Interp.renderValue v @?= RCM.rcOutput run
          let st = RCM.rcStats run
              bl = RCM.rcBaseline run
          assertEqual "live cells return to baseline (no leak) through runModuleRC"
            bl (St.stLive st)
          assertEqual "allocs minus frees equal baseline (no leak) through runModuleRC"
            bl (St.stAllocs st - St.stFrees st)
        (refRes, rcRes) ->
          assertFailure
            ("store route must run through the CHECKED runModuleRC; got ref="
               <> either show (const "ok") refRes <> " rc="
               <> either show (const "ok") rcRes)
  ]

-- | PART A narrowness + the cycle reject. The store route admits ONLY the literal
-- '__cont_store cell resume' position; every other 'resume' escape stays rejected,
-- and the surface cycle shape is type-rejected.
rcM3RejectTests :: TestTree
rcM3RejectTests = testGroup "rc-m3-reject (carrier-wall + narrow store-route)"
  [ testCase "02-resume-escapes-non-store: aliased/non-store resume STAYS rejected" $ do
      vs <- boundaryViolationsOf "test/rc-m3-reject/02-resume-escapes-non-store.wok"
      assertBool
        "a resume escaping into a non-__cont_store position must be rejected"
        (not (null vs))
  , testCase "01-cycle-cont-reaches-cell: own-baton store is REJECTED (OccursCheck)" $ do
      -- The closest surface approximation of the cycle (store resume into the
      -- handler's own baton) never reaches the boundary guard: the type checker
      -- rejects it with an OccursCheck (the cell's answer type would contain the
      -- continuation's own result type --- the type-level carrier wall). Pin the
      -- rejection by asserting the file FAILS TO ELABORATE (mirroring the M2b
      -- 'rc-m2b-reject/13' carrier-wall-param rejection).
      result <- Loader.loadProgram "test/rc-m3-reject/01-cycle-cont-reaches-cell.wok" []
      case result of
        Left lerr -> assertFailure ("loader: " <> show lerr)
        Right (entryName, ms) ->
          case Pipeline.elaborateProgramFull entryName ms of
            Left _  -> pure ()   -- expected: OccursCheck (self-referential carrier)
            Right _ -> assertFailure
              "expected elaboration failure (OccursCheck on the self-stored carrier), got Right"
  ]

-- ---------------------------------------------------------------------------
-- M3 Task 4: the CARRIER-WALL cycle-prevention checks, exercised + red-checked
-- on a HAND-CONSTRUCTED owned set (the bite at the achievable level, since no
-- surface program can construct the cycle --- see the OccursCheck reject above).
--
-- The construction (verified by 'cellInOwnedSet' below) is the operational cycle:
-- an 'NCont' whose captured prefix is a nested PARAMETERIZED handler frame whose
-- param value IS the cell it is parked in. Then 'continuationOwned prefix ==
-- [cellAddr]' --- a counted edge from the NCont back to its own cell. This is the
-- shape §3.4's "nested-param route" would have to reach; it is REAL (constructible
-- at the heap level), so the checks are load-bearing, not vacuous.
rcM3CarrierWallTests :: TestTree
rcM3CarrierWallTests = testGroup "m3 cycle red-check (carrier-wall is load-bearing)"
  [ testCase "the cycle IS constructible: continuationOwned includes the cell addr" $ do
      let (_, _, _, prefix, cellAddr) = buildCycleStore
      -- The cell is in the captured continuation's owned set: a counted edge back.
      assertBool "cellAddr must appear in continuationOwned prefix (the cycle edge)"
        (cellAddr `elem` St.continuationOwned prefix)

  , testCase "RED-CHECK: WITHOUT the carrier-wall check, the store + drop double-frees" $ do
      -- Bypass the '__cont_store' carrier-wall check by writing the cell directly
      -- (the cycle the check would have rejected), then drop the cell ONCE. The
      -- cell-drop cascades through the NCont's owned set, which contains the cell
      -- itself, so the cascade re-enters and double-frees it --- caught LOUDLY by
      -- 'dropAddr's 'stDead' guard. This proves the surviving cycle is a real
      -- memory-safety fault, so the check is load-bearing.
      let (s2, contAddr, _h, _prefix, cellAddr) = buildCycleStore
      case St.writeNodePure cellAddr (St.NContCell (Just contAddr)) s2 of
        Left e   -> assertFailure ("setup writeNode failed: " <> show e)
        Right s3 ->
          case St.dropAddrPure cellAddr s3 of
            Left (IV.PrimError m)
              | T.pack "double-free" `T.isInfixOf` m -> pure ()   -- the cycle bites
            Left e  -> assertFailure
              ("expected a double-free from the surviving cycle, got: " <> show e)
            Right _ -> assertFailure
              "expected the surviving cycle to double-free on cell-drop, but it balanced"

  , testCase "GREEN: WITH the runtime carrier-wall check, __cont_store REJECTS the cycle" $ do
      -- Drive the real '__cont_store' prim with the cyclic (cell, NCont) pair. The
      -- runtime check ('cellAddr `notElem` continuationOwned prefix') must reject it
      -- loudly with the carrier-wall message --- BEFORE it can write the cyclic edge.
      let (s2, contAddr, _h, _prefix, cellAddr) = buildCycleStore
      case Map.lookup (T.pack "Control", T.pack "__cont_store") RCP.rcPrimTable of
        Nothing -> assertFailure "rcPrimTable is missing __cont_store"
        Just p  -> do
          res <- runExceptT (St.rpFn p [St.RVBox cellAddr, St.RVBox contAddr] s2)
          case res of
            Left (IV.PrimError m)
              | T.pack "carrier-wall" `T.isInfixOf` m -> pure ()   -- rejected as designed
            Left e  -> assertFailure
              ("__cont_store must reject the cycle with a carrier-wall error, got: " <> show e)
            Right _ -> assertFailure
              "__cont_store accepted a cyclic store (cell in the continuation's owned set)"

  , testCase "the static m3CarrierWallViolations flags a store into a NON-LOCAL cell" $ do
      -- A hand-built handler whose op-arm stores 'resume' into a cell that is a
      -- FREE VARIABLE of the arm (the handler baton / an enclosing local), not a
      -- fresh '__cont_cell_new'. The static carrier-wall check must flag it; a
      -- store into a fresh local cell (the admitted shape) must NOT be flagged.
      assertBool "non-local (captured) store cell must be flagged"
        (not (null (m3CarrierWallViolations carrierWallNonLocalHandler)))
      assertEqual "fresh-local store cell must NOT be flagged" []
        (m3CarrierWallViolations carrierWallLocalHandler)

  -- 04-store-into-op-arg-cell: the STATIC scope hole (review #3). The op-arg-cell
  -- shape is grammar-rejected at the surface, so it is exercised here as a UNIT
  -- test on a hand-built arm. A store into an OP-ARGUMENT cell ('tick(cellArg) ->
  -- __cont_store cellArg resume') is a non-fresh-local cell (the op arg is a value
  -- live at the op, potentially captured above it), so it MUST be rejected. The
  -- prior 'armFreeVars' subtracted op args, treating the op-arg cell as a local
  -- and false-ADMITTING it.
  , testCase "04-store-into-op-arg-cell: store into an OP-ARGUMENT cell is REJECTED" $
      assertBool "an op-argument store cell must be flagged (it is not a fresh local)"
        (not (null (m3CarrierWallViolations carrierWallOpArgHandler)))

  -- A store buried in a NESTED handler arm, whose cell is a (non-fresh-local)
  -- value relative to that nested arm, must also be rejected. 'storeRouteCells'
  -- recurses into nested handler arms; the carrier-wall must reject any such store
  -- whose cell is not freshly created by '__cont_cell_new' in the SAME scope as
  -- the store.
  , testCase "nested-handler-arm store into a captured cell is REJECTED" $
      assertBool "a store inside a nested handler arm into a captured cell must be flagged"
        (not (null (m3CarrierWallViolations carrierWallNestedHandlerHandler)))

  -- POSITIVE guard against over-rejection: 'storeRouteCells' on the admitted
  -- fresh-local shape returns exactly the freshly bound cell, and the carrier-wall
  -- admits it (the corpus shape 'rc-m3/01').
  , testCase "fresh-local store cell: storeRouteCells finds the fresh cell, carrier-wall admits" $
      case Anf.hOps carrierWallLocalHandler of
        (oa : _) -> do
          let cells = Esc.storeRouteCells (Anf.oaResume oa) (Anf.oaBody oa)
          assertEqual "exactly one store cell recognized" 1 (length cells)
          assertEqual "fresh-local store cell carrier-wall-admitted" []
            (m3CarrierWallViolations carrierWallLocalHandler)
        [] -> assertFailure "carrierWallLocalHandler must have an op-arm"

  -- __RC_DUP ALIAS-FOLLOW (code-review #4). The wall runs on POST-Perceus IR, where
  -- the store cell operand can be a '__rc_dup' of the fresh cell (@let c2 = __rc_dup
  -- cell; __cont_store c2 resume@). 'freshCellBinder' traces through that dup: a dup
  -- of an ALREADY-fresh cell is still fresh-local, so the carrier-wall must ADMIT it.
  , testCase "store into a __rc_dup of a FRESH cell is ADMITTED (#4 alias-follow)" $
      assertEqual "a __rc_dup of a fresh-local cell is still fresh; admit the store" []
        (m3CarrierWallViolations carrierWallDupFreshHandler)

  -- The dual: a '__rc_dup' of a NON-fresh (baton / free-variable) cell is NOT
  -- promoted to fresh (the operand is not in the fresh set), so the store must still
  -- be REJECTED. This pins that the alias-follow only promotes dups of fresh cells.
  , testCase "store into a __rc_dup of a NON-FRESH (baton) cell is REJECTED (#4 dual)" $
      assertBool "a __rc_dup of a captured baton is not fresh; reject the store"
        (not (null (m3CarrierWallViolations carrierWallDupBatonHandler)))
  ]

-- | A handler whose 'tick' op-arm binds a fresh cell ('__cont_cell_new'), then DUPs
-- it ('__rc_dup') into 'c2', and stores 'resume' into 'c2': @let cell =
-- __cont_cell_new (); let c2 = __rc_dup cell; __cont_store c2 resume@. The dup'd
-- cell is the same fresh cell rc-bumped, so the carrier-wall must ADMIT the store
-- (code-review #4 alias-follow through '__rc_dup').
carrierWallDupFreshHandler :: Anf.Handler
carrierWallDupFreshHandler = carrierWallDupHandlerWith True

-- | The dual of 'carrierWallDupFreshHandler': the DUP'd cell is a 'baton' FREE
-- variable of the arm (not bound by '__cont_cell_new' inside it), so the dup is not
-- of a fresh cell and the store must be REJECTED.
carrierWallDupBatonHandler :: Anf.Handler
carrierWallDupBatonHandler = carrierWallDupHandlerWith False

-- | Build a one-op handler whose arm is @let c2 = __rc_dup SRC; __cont_store c2
-- resume@. When 'srcFresh' is True, SRC is a fresh @let cell = __cont_cell_new ()@
-- bound in the arm (so the dup'd 'c2' is still fresh --- admit); when False, SRC is
-- the 'baton' free variable (so 'c2' is a dup of a captured cell --- reject).
carrierWallDupHandlerWith :: Bool -> Anf.Handler
carrierWallDupHandlerWith srcFresh =
  let resumeB = Binder (Name (T.pack "k")      (Unique 8431)) Unrestricted m2bBoxTy
      cellB   = Binder (Name (T.pack "cell")    (Unique 8432)) Unrestricted m2bBoxTy
      c2B     = Binder (Name (T.pack "c2")      (Unique 8433)) Unrestricted m2bBoxTy
      batonN  = Name (T.pack "baton")           (Unique 8434)
      rcDup   = Name (T.pack "__rc_dup")        (Unique 8436)
      filledB = Binder (Name (T.pack "filled")  (Unique 8438)) Unrestricted m2bBoxTy
      srcAtom = if srcFresh then AVar (Anf.bndName cellB) else AVar batonN
      dupAndStore =
        Let c2B (RApp (AVar rcDup) [srcAtom])
          (Let filledB
             (RApp m3Store [AVar (Anf.bndName c2B), AVar (Anf.bndName resumeB)])
             (Ret (ALit LUnit)))
      body = if srcFresh
               then Let cellB (RApp m3CellNew [ALit LUnit]) dupAndStore
               else dupAndStore
      op = Anf.OpArm
             { Anf.oaLabel  = T.pack "Tick"
             , Anf.oaOp     = T.pack "tick"
             , Anf.oaArgs   = []
             , Anf.oaResume = resumeB
             , Anf.oaBody   = body
             }
  in Anf.Handler
       { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 8439)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
       , Anf.hOps        = [op]
       , Anf.hAnswerJoin = Nothing
       , Anf.hParam      = Nothing
       , Anf.hSelf       = Nothing
       }

-- | The operational cycle construction shared by the carrier-wall tests: a cell
-- (allocated empty) and an 'NCont' whose captured prefix is a nested
-- parameterized-handler frame binding the param's Unique to 'RVBox cellAddr'. So
-- 'continuationOwned prefix == [cellAddr]' --- the continuation counted-reaches its
-- own cell. Returns the store (with the cell + NCont allocated, cell still EMPTY so
-- a real '__cont_store' can be invoked on it), the NCont addr, the handler, the
-- prefix, and the cell addr.
buildCycleStore :: (St.Store, St.Addr, Anf.Handler, St.RCKont, St.Addr)
buildCycleStore =
  let s0          = St.emptyStore
      (cellAddr, s1) = St.allocPure (St.NContCell Nothing) s0
      pb          = Binder (Name (T.pack "baton") (Unique 8300)) Unrestricted m2bBoxTy
      h           = m2b2ParamHandler pb
      hsc         = St.RCScope (Map.fromList [(Unique 8300, St.RVBox cellAddr)]) Map.empty
      prefix      = St.KHandleRC h 0 hsc St.KDoneRC
      cont        = St.NCont prefix (m2b2NoParamHandler, 0, St.emptyRCScope)
      (contAddr, s2) = St.allocPure cont s1
  in (s2, contAddr, h, prefix, cellAddr)

-- | A handler whose 'tick' op-arm stores 'resume' into a cell that is a FREE
-- VARIABLE of the arm body (the synthetic 'baton' binder, NOT bound inside the
-- arm) --- the UNSAFE (non-local) store the static carrier-wall check must reject.
carrierWallNonLocalHandler :: Anf.Handler
carrierWallNonLocalHandler = carrierWallHandlerWith False

-- | A handler whose 'tick' op-arm stores 'resume' into a cell bound LOCALLY inside
-- the arm (by a synthetic '__cont_cell_new' call) --- the SAFE (fresh-local) store
-- the static carrier-wall check must admit.
carrierWallLocalHandler :: Anf.Handler
carrierWallLocalHandler = carrierWallHandlerWith True

-- | Build a one-op handler whose arm is @__cont_store CELL resume@, where CELL is
-- either a fresh local ('localCell' = True: @let cell = __cont_cell_new () in ...@)
-- or a free variable of the arm ('localCell' = False: a 'baton' name not bound in
-- the arm). Used to exercise 'm3CarrierWallViolations' directly at the ANF level.
carrierWallHandlerWith :: Bool -> Anf.Handler
carrierWallHandlerWith localCell =
  let resumeB = Binder (Name (T.pack "k")     (Unique 8401)) Unrestricted m2bBoxTy
      cellB   = Binder (Name (T.pack "cell")   (Unique 8402)) Unrestricted m2bBoxTy
      batonN  = Name (T.pack "baton") (Unique 8403)
      filledB = Binder (Name (T.pack "filled") (Unique 8406)) Unrestricted m2bBoxTy
      cellAtom = if localCell then AVar (Anf.bndName cellB) else AVar batonN
      storeCall = Let filledB
                    (RApp m3Store [cellAtom, AVar (Anf.bndName resumeB)])
                    (Ret (ALit LUnit))
      body = if localCell
               then Let cellB (RApp m3CellNew [ALit LUnit]) storeCall
               else storeCall
      op = Anf.OpArm
             { Anf.oaLabel  = T.pack "Tick"
             , Anf.oaOp     = T.pack "tick"
             , Anf.oaArgs   = []
             , Anf.oaResume = resumeB
             , Anf.oaBody   = body
             }
  in Anf.Handler
       { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 8407)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
       , Anf.hOps        = [op]
       , Anf.hAnswerJoin = Nothing
       , Anf.hParam      = Nothing
       , Anf.hSelf       = Nothing
       }

-- | A handler whose op-arm receives a CELL as an OP ARGUMENT and stores 'resume'
-- into it: @tick(cellArg, resume) -> __cont_store cellArg resume@. The op-arg cell
-- is a value LIVE AT THE OP (it could be captured into the continuation prefix
-- above the op), so it is NOT a fresh local of the arm and MUST be rejected by the
-- carrier-wall check (review #3: the prior 'armFreeVars' subtracted op args,
-- false-admitting this shape).
carrierWallOpArgHandler :: Anf.Handler
carrierWallOpArgHandler =
  let resumeB = Binder (Name (T.pack "k")      (Unique 8411)) Unrestricted m2bBoxTy
      cellArgB = Binder (Name (T.pack "cellArg") (Unique 8412)) Unrestricted m2bBoxTy
      filledB = Binder (Name (T.pack "filled") (Unique 8414)) Unrestricted m2bBoxTy
      body = Let filledB
               (RApp m3Store
                     [AVar (Anf.bndName cellArgB), AVar (Anf.bndName resumeB)])
               (Ret (ALit LUnit))
      op = Anf.OpArm
             { Anf.oaLabel  = T.pack "Tick"
             , Anf.oaOp     = T.pack "tick"
             , Anf.oaArgs   = [cellArgB]
             , Anf.oaResume = resumeB
             , Anf.oaBody   = body
             }
  in Anf.Handler
       { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 8415)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
       , Anf.hOps        = [op]
       , Anf.hAnswerJoin = Nothing
       , Anf.hParam      = Nothing
       , Anf.hSelf       = Nothing
       }

-- | A handler whose op-arm body opens a NESTED handler, and the nested arm stores
-- the OUTER arm's 'resume' into a cell bound in the OUTER arm (so the cell is a
-- free variable of the NESTED arm). 'storeRouteCells' recurses into the nested
-- arm; the carrier-wall must REJECT this store because its cell is not freshly
-- created by '__cont_cell_new' within the SAME scope as the store (it is captured
-- from an enclosing scope).
carrierWallNestedHandlerHandler :: Anf.Handler
carrierWallNestedHandlerHandler =
  let resumeB = Binder (Name (T.pack "k")     (Unique 8421)) Unrestricted m2bBoxTy
      cellB   = Binder (Name (T.pack "cell")   (Unique 8422)) Unrestricted m2bBoxTy
      filledB = Binder (Name (T.pack "filled") (Unique 8425)) Unrestricted m2bBoxTy
      innerResumeB = Binder (Name (T.pack "bk") (Unique 8426)) Unrestricted m2bBoxTy
      -- The NESTED arm stores the OUTER 'resume' (k) into the OUTER 'cell'. From
      -- the nested arm's perspective both 'cell' and 'k' are free variables.
      nestedArm = Anf.OpArm
        { Anf.oaLabel  = T.pack "B"
        , Anf.oaOp     = T.pack "bop"
        , Anf.oaArgs   = []
        , Anf.oaResume = innerResumeB
        , Anf.oaBody   =
            Let filledB
              (RApp m3Store
                    [AVar (Anf.bndName cellB), AVar (Anf.bndName resumeB)])
              (Ret (ALit LUnit))
        }
      nestedHandler = Anf.Handler
        { Anf.hReturn     = (Binder (Name (T.pack "w") (Unique 8427)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
        , Anf.hOps        = [nestedArm]
        , Anf.hAnswerJoin = Nothing
        , Anf.hParam      = Nothing
        , Anf.hSelf       = Nothing
        }
      -- Outer arm: bind 'cell' via __cont_cell_new, then open the nested handler.
      body = Let cellB (RApp m3CellNew [ALit LUnit])
               (Handle (Ret (ALit LUnit)) nestedHandler)
      op = Anf.OpArm
             { Anf.oaLabel  = T.pack "Tick"
             , Anf.oaOp     = T.pack "tick"
             , Anf.oaArgs   = []
             , Anf.oaResume = resumeB
             , Anf.oaBody   = body
             }
  in Anf.Handler
       { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 8428)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
       , Anf.hOps        = [op]
       , Anf.hAnswerJoin = Nothing
       , Anf.hParam      = Nothing
       , Anf.hSelf       = Nothing
       }

-- ---------------------------------------------------------------------------
-- Finding #4 (code-review H2): the runtime carrier-wall check is SINGLE-LEVEL, so
-- by ITSELF it misses an N-cell cycle; but the static fresh-local rule (H1,
-- 'm3CarrierWallViolations') is the COMPLETE cycle wall, which SUBSUMES the gap.
--
-- EMPIRICAL VERDICT (verified, not assumed). A 2-cell cycle IS constructible at the
-- HEAP level (cellA holds contA owning cellB; cellB holds contB owning cellA) and
-- the single-level runtime check passes BOTH legs (cellA is not in contA's owned
-- set --- cellB is), so the cycle goes live and dropping any cell double-frees. BUT
-- it is NOT constructible through the ADMITTED path: for a continuation to OWN a
-- cell, that cell must be in its captured prefix's owned set --- a value live ABOVE
-- the op (a handler param / enclosing local / op arg), which is exactly the
-- NON-fresh-local cell H1 statically REJECTS. A fresh-local '__cont_cell_new' cell
-- (the only kind H1 admits) is bound INSIDE the storing arm, BELOW the op, and can
-- never be in any captured prefix's owned set. So every multi-cell cycle needs a
-- non-fresh cell H1 walls; no fresh-local-cell cycle exists. The transitive walk a
-- multi-cell cycle would otherwise demand is therefore DEAD CODE under H1 and
-- deliberately omitted (not added).
rcM3TwoCellCycleSubsumedTests :: TestTree
rcM3TwoCellCycleSubsumedTests =
  testGroup "m3 #4: 2-cell cycle is SUBSUMED by H1's static fresh-local rule"
  [ testCase "the single-level runtime check ALONE misses a 2-cell cycle (the gap is real)" $ do
      -- Build the 2-cell cycle directly on the heap (cellA->contA->cellB->contB->cellA).
      -- Each continuation owns the OTHER cell, so the single-level check passes both
      -- legs and the cycle goes live; dropping cellA then double-frees. This is the
      -- gap the single-level runtime check has by itself.
      let (s2, cellA, cellB, contA, contB) = buildTwoCellCycle
      case Map.lookup (T.pack "Control", T.pack "__cont_store") RCP.rcPrimTable of
        Nothing -> assertFailure "rcPrimTable is missing __cont_store"
        Just storeP -> do
          -- leg 1: store contA into cellA. single-level: cellA `elem` owned(contA)?
          leg1 <- runExceptT (St.rpFn storeP [St.RVBox cellA, St.RVBox contA] s2)
          case leg1 of
            Left e -> assertFailure
              ("leg1 should pass the single-level check (cellA is NOT in contA's owned set), got: "
                <> show e)
            Right (_, s3) -> do
              leg2 <- runExceptT (St.rpFn storeP [St.RVBox cellB, St.RVBox contB] s3)
              case leg2 of
                Left e -> assertFailure
                  ("leg2 should pass the single-level check (cellB is NOT in contB's owned set), got: "
                    <> show e)
                Right (_, s4) ->
                  -- The cycle is now LIVE; dropping cellA double-frees (caught loudly by stDead).
                  case St.dropAddrPure cellA s4 of
                    Left (IV.PrimError m)
                      | T.pack "double-free" `T.isInfixOf` m -> pure ()  -- the surviving cycle bites
                    Left e  -> assertFailure
                      ("expected a double-free from the surviving 2-cell cycle, got: " <> show e)
                    Right _ -> assertFailure
                      "the single-level runtime check let a 2-cell cycle go live without double-freeing \
                      \--- the gap this test documents did not appear"

  , testCase "H1 (static) REJECTS the 2-cell cycle: each store is into a NON-fresh-local cell" $ do
      -- The SOURCE shape of the 2-cell cycle: each arm stores its resume into a cell
      -- that the OTHER continuation must own --- i.e. an ENCLOSING / captured value,
      -- NOT a '__cont_cell_new' fresh local of the storing arm. H1's static
      -- 'm3CarrierWallViolations' rejects every such store, so the cycle's source
      -- shape never reaches the runtime. This is why the gap above is SUBSUMED.
      assertBool "store into an enclosing (cycle-capable) cell must be statically flagged"
        (not (null (m3CarrierWallViolations twoCellCycleArmHandler)))

  , testCase "H1 ADMITS only fresh-local cells, which can NEVER be in an owned set" $ do
      -- The complement: a fresh-local cell IS admitted by H1, and (by construction)
      -- it is bound below the op, so no captured continuation can own it. The
      -- carrier-wall does not flag it, and there is no cycle to form.
      assertEqual "a fresh-local store cell is carrier-wall-admitted (no cycle possible)" []
        (m3CarrierWallViolations carrierWallLocalHandler)
  ]

-- | The 2-cell cycle at the HEAP level: two cells, each holding a continuation
-- whose captured prefix OWNS the OTHER cell (via a nested parameterized-handler
-- frame binding the param to 'RVBox' of the other cell). So
-- @continuationOwned(contA) == [cellB]@ and @continuationOwned(contB) == [cellA]@:
-- the single-level @__cont_store@ check (cell in its OWN continuation's owned set)
-- passes both legs, yet the ring is closed. Both cells start EMPTY so the real
-- '__cont_store' prim can be driven on them. Returns the store and the four addrs.
buildTwoCellCycle :: (St.Store, St.Addr, St.Addr, St.Addr, St.Addr)
buildTwoCellCycle =
  let s0            = St.emptyStore
      (cellA, s1)   = St.allocPure (St.NContCell Nothing) s0
      (cellB, s2)   = St.allocPure (St.NContCell Nothing) s1
      -- contA owns cellB (its nested-handler param value is RVBox cellB).
      pbA           = Binder (Name (T.pack "pa") (Unique 8700)) Unrestricted m2bBoxTy
      hA            = m2b2ParamHandler pbA
      hscA          = St.RCScope (Map.fromList [(Unique 8700, St.RVBox cellB)]) Map.empty
      prefixA       = St.KHandleRC hA 0 hscA St.KDoneRC
      (contA, s3)   = St.allocPure (St.NCont prefixA (m2b2NoParamHandler, 0, St.emptyRCScope)) s2
      -- contB owns cellA.
      pbB           = Binder (Name (T.pack "pb") (Unique 8710)) Unrestricted m2bBoxTy
      hB            = m2b2ParamHandler pbB
      hscB          = St.RCScope (Map.fromList [(Unique 8710, St.RVBox cellA)]) Map.empty
      prefixB       = St.KHandleRC hB 0 hscB St.KDoneRC
      (contB, s4)   = St.allocPure (St.NCont prefixB (m2b2NoParamHandler, 0, St.emptyRCScope)) s3
  in (s4, cellA, cellB, contA, contB)

-- | A handler whose op-arm stores its 'resume' into a cell that is a FREE VARIABLE
-- of the arm (an enclosing value the OTHER continuation in a 2-cell cycle would
-- own) --- NOT a fresh '__cont_cell_new'. This is the SOURCE shape of one leg of a
-- 2-cell cycle; H1's static carrier-wall must reject it (a non-fresh-local cell).
twoCellCycleArmHandler :: Anf.Handler
twoCellCycleArmHandler =
  let resumeB = Binder (Name (T.pack "k")     (Unique 8721)) Unrestricted m2bBoxTy
      otherN  = Name (T.pack "otherCell")     (Unique 8722)   -- the OTHER cell, enclosing free var
      filledB = Binder (Name (T.pack "filled") (Unique 8724)) Unrestricted m2bBoxTy
      body = Let filledB
               (RApp m3Store [AVar otherN, AVar (Anf.bndName resumeB)])
               (Ret (ALit LUnit))
      op = Anf.OpArm
             { Anf.oaLabel  = T.pack "Tick"
             , Anf.oaOp     = T.pack "tick"
             , Anf.oaArgs   = []
             , Anf.oaResume = resumeB
             , Anf.oaBody   = body
             }
  in Anf.Handler
       { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 8725)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
       , Anf.hOps        = [op]
       , Anf.hAnswerJoin = Nothing
       , Anf.hParam      = Nothing
       , Anf.hSelf       = Nothing
       }

-- ---------------------------------------------------------------------------
-- Finding #5 (code-review H2): the raw-vs-named owned-set NON-dedup is CORRECT by
-- rc-accounting, and the per-entry free is LOAD-BEARING (deduping would leak).
--
-- The scenario: a captured continuation prefix where the SAME address @A@ is owned
-- BOTH as a KLetRC NAMED binder ((Just u, A)) AND as a KAppRC RAW over-arg
-- ((Nothing, A)). Both are CONSUMING (move) positions, so Perceus pays a
-- @__rc_dup@ on the second --- @A@ has rc == 2. The owned set must therefore list
-- @A@ TWICE so the cascade frees it twice (rc 2 -> 0). Deduping to a single @A@
-- would free it once (rc 2 -> 1) --- a LEAK. (The corpus does not yet REACH a
-- KAppRC/KDropCellRC inside a captured prefix, so this pins the accounting directly.)
rcM3RawVsNamedOwnedSetTests :: TestTree
rcM3RawVsNamedOwnedSetTests =
  testGroup "m3 #5: raw-vs-named owned-set per-entry free is load-bearing"
  [ testCase "continuationOwned lists A TWICE when owned as BOTH a named binder and a raw over-arg" $ do
      let (_, ownedAddr, prefix) = buildRawAndNamedOwned
      assertEqual "the owned set must list the address per-entry (named + raw), NOT deduped"
        [ownedAddr, ownedAddr] (St.continuationOwned prefix)

  , testCase "freeing per the (per-entry) owned set returns A's rc 2 -> 0 (balanced)" $ do
      -- A is at rc 2 (a Perceus dup on the second move position). The cascade frees
      -- it twice (the owned set lists it twice), returning the heap to baseline.
      let (s0, _ownedAddr, prefix) = buildRawAndNamedOwned
          baseline = St.stLive (St.stStats s0) - 1   -- after A is fully freed
      case freeEach (St.continuationOwned prefix) s0 of
        Left e  -> assertFailure ("per-entry free must balance rc 2 -> 0, got: " <> show e)
        Right s -> assertEqual "per-entry free returns A's cell to freed (no leak)"
          baseline (St.stLive (St.stStats s))

  , testCase "RED-CHECK: a DEDUPED (distinct-address) free LEAKS A (rc 2 -> 1)" $ do
      -- Simulate the naive dedup: free each DISTINCT owned address once. A is freed
      -- once (rc 2 -> 1), leaving its cell LIVE --- the leak the per-entry free
      -- prevents. This is the empirical proof that deduping is unsound.
      let (s0, ownedAddr, prefix) = buildRawAndNamedOwned
          distinct = Set.toList (Set.fromList (St.continuationOwned prefix))
      assertEqual "naive dedup collapses [A,A] to [A]" [ownedAddr] distinct
      case freeEach distinct s0 of
        Left e  -> assertFailure ("the deduped free should not error, it should LEAK: " <> show e)
        Right s ->
          assertBool "the deduped free must LEAK A's cell (rc 2 -> 1, still live)"
            (St.stLive (St.stStats s) > St.stLive (St.stStats s0) - 1)
  ]

-- | A captured continuation prefix where address @A@ is owned BOTH as a KLetRC
-- NAMED binder (a non-head MOVE occurrence in the frame body) AND as a KAppRC RAW
-- over-arg, with @A@ at rc == 2 (the Perceus dup on the second move position).
-- Returns the store (A allocated at rc 2), A's address, and the prefix.
buildRawAndNamedOwned :: (St.Store, St.Addr, St.RCKont)
buildRawAndNamedOwned =
  let s0          = St.emptyStore
      (aAddr, s1) = St.allocPure (St.NCon (T.pack "Owned") []) s0   -- rc 1
      s2          = either (error . show) id (St.increfPure aAddr s1)  -- rc 2 (the dup)
      -- KLetRC frame: body = Ret (AVar x) makes x a non-head MOVE occurrence, so x
      -- (bound to RVBox aAddr) is in the frame's owned set --- the NAMED (Just u, A).
      xName       = Name (T.pack "x") (Unique 8801)
      rBndr       = Binder (Name (T.pack "r") (Unique 8802)) Unrestricted m2bBoxTy
      body        = Ret (AVar xName)
      sc          = St.RCScope (Map.fromList [(Unique 8801, St.RVBox aAddr)]) Map.empty
      kLet        = St.KLetRC rBndr body sc St.KDoneRC
      -- KAppRC frame above it: its over-arg is RVBox aAddr --- the RAW (Nothing, A).
      prefix      = St.KAppRC [St.RVBox aAddr] kLet
  in (s2, aAddr, prefix)

-- | Free each address in a list in order (the owned-set cascade does exactly this:
-- one 'dropAddr' per owned-set entry). 'Left' on the first error.
freeEach :: [St.Addr] -> St.Store -> Either IV.RuntimeError St.Store
freeEach addrs s0 = foldl (\acc a -> acc >>= St.dropAddrPure a) (Right s0) addrs

-- | A captured continuation prefix (FIX 1b) whose single 'KLetRC' frame body
-- contains an 'RReuseCon' --- the shape that would arise if a reuse token were in
-- flight when an op captured the continuation. The frame body is
-- @let r = RReuseCon tok Cons [y] in Ret r@; @y@ (the field) resolves through the
-- frame scope to a live 'Owned' cell, so the frame's owned set is exactly that
-- cell. 'continuationOwned' over this prefix must NOT crash and must return @[y]@'s
-- address (the field is the owned move; the affine token is uncounted, ignored).
-- Returns the prefix and the field's owned address.
buildReuseConFrame :: (St.RCKont, St.Addr)
buildReuseConFrame =
  let s0          = St.emptyStore
      (yAddr, _)  = St.allocPure (St.NCon (T.pack "Owned") []) s0   -- the field cell
      yName       = Name (T.pack "y")   (Unique 9101)
      rBndr       = Binder (Name (T.pack "r") (Unique 9102)) Unrestricted m2bBoxTy
      tokName     = Name (T.pack "tok") (Unique 9103)
      -- body = let r = RReuseCon tok Cons [y] in Ret r
      body        = Let rBndr
                      (RReuseCon (AVar tokName) (T.pack "Cons") [AVar yName])
                      (Ret (AVar (Name (T.pack "r") (Unique 9102))))
      -- y is the only frame-scoped binder bound to a counted cell; tok is NOT in
      -- the env (an uncounted affine token, never resolved to an address).
      sc          = St.RCScope (Map.fromList [(Unique 9101, St.RVBox yAddr)]) Map.empty
      prefix      = St.KLetRC rBndr body sc St.KDoneRC
  in (prefix, yAddr)

-- ---------------------------------------------------------------------------
-- M3 Task 5: the DOUBLE-RESUME red-check (the 'moveOutCont' rc==1 floor is
-- load-bearing, spec §4.2 / §10 item 1). A stored continuation resumed TWICE is
-- the new silent-failure frontier: the second resume re-uses a captured frame
-- whose owned set the first resume already handed out, so the owned set is freed
-- twice (a double-free). The 'moveOutCont' rc==1 assert is the SOUNDNESS FLOOR
-- that turns this into a LOUD, LOCAL fault.
--
-- The static 'Multiplicity' layer does NOT prove single-resume for a
-- '__cont_take' result (it tracks the 'resume' binder handed to '__cont_store',
-- not the take-result), so the runtime move-discipline is the ONLY net for this
-- shape --- exactly the "never rest soundness on a single static analysis"
-- philosophy. Hence the floor is exercised + red-checked here at the heap level.
--
-- The surface double-resume corpus file 'test/rc-m3-reject/03-double-resume.wok'
-- documents the SHAPE; the splice re-entry after the first resume runs the live
-- continuation to the answer, so the second resume's heap effect is not a clean
-- value-level differential --- the hand-built scenario below pins the floor.
--
-- The construction is the M3 stored-continuation analogue of the M2b resume
-- move-out: an 'NCont' whose captured prefix is a nested parameterized-handler
-- frame binding the param's Unique to a live 'Owned' value (so
-- 'continuationOwned prefix == [ownedAddr]' --- a real owned set). Two resumes of
-- the same continuation each free that owned set.
rcM3DoubleResumeTests :: TestTree
rcM3DoubleResumeTests = testGroup "m3 double-resume red-check (rc==1 floor is load-bearing)"
  [ testCase "the surface double-resume shape is boundary-admitted (static layer does NOT catch it)" $ do
      -- '03-double-resume.wok' stores 'resume' (admitted) then resumes the
      -- '__cont_take' result twice. The boundary guard + 'Multiplicity' admit it
      -- (the static layer tracks the stored 'resume', not the take-result), so the
      -- RUNTIME 'moveOutCont' rc==1 floor is the only net --- the construction
      -- below exercises that floor directly.
      vs <- boundaryViolationsOf "test/rc-m3-reject/03-double-resume.wok"
      assertEqual "the double-resume shape is admitted; the runtime floor is its net" [] vs

  , testCase "the continuation has a real owned set (continuationOwned == [ownedAddr])" $ do
      let (_, _, ownedAddr, prefix) = buildDoubleResumeNCont
      St.continuationOwned prefix @?= [ownedAddr]

  , testCase "GREEN: a SINGLE resume (moveOutCont rc==1) frees the owned set exactly once" $ do
      -- The honest single-resume: 'moveOutCont' at rc==1 frees the NCont SHELL
      -- only and hands the owned set to the spliced frames; those frames free it
      -- once. Heap returns to baseline (the floor does NOT over-reject).
      let (s0, contAddr, ownedAddr, _prefix) = buildDoubleResumeNCont
          baseline = St.stLive (St.stStats s0)
      case St.moveOutContPure contAddr s0 of
        Left e -> assertFailure ("a legitimate single resume must succeed at rc==1: " <> show e)
        Right (_prefix', _hinfo, s1) ->
          -- The spliced frames run and free the owned set exactly once.
          case St.dropAddrPure ownedAddr s1 of
            Left e  -> assertFailure ("owned-set free after one resume must succeed: " <> show e)
            Right s2 -> St.stLive (St.stStats s2) @?= baseline - 2  -- shell + owned freed

  , testCase "GREEN (the floor): a double-resume (rc==2) is caught LOUDLY by moveOutCont" $ do
      -- A continuation with TWO owners (rc==2) is the double-resume hazard: two
      -- aliases would each resume it. The rc==1 floor fires on the FIRST resume
      -- attempt, BEFORE any frame is spliced or any owned value is freed --- a
      -- loud, local "one-shot violation" rather than a silent double-free.
      let (s0, contAddr, _ownedAddr, _prefix) = buildDoubleResumeNCont
      case St.increfPure contAddr s0 of
        Left e   -> assertFailure ("setup incref failed: " <> show e)
        Right s1 ->
          case St.moveOutContPure contAddr s1 of
            Left e
              | rcMemSafetyFault e -> pure ()   -- the floor caught it loudly
              | otherwise -> assertFailure
                  ("rc!=1 must be a memory-safety fault (one-shot violation), got: " <> show e)
            Right _ -> assertFailure
              "moveOutCont accepted a resume of an rc==2 (double-owned) continuation --- \
              \the one-shot floor did not fire"

  , testCase "RED-CHECK: WITHOUT the rc==1 floor, the second resume double-frees the owned set" $ do
      -- Demonstrate the corruption the floor prevents, using the public API. A
      -- double-resume reuses the SAME captured prefix twice, so its owned set is
      -- freed twice. Resume #1: 'moveOutCont' hands out the owned set; the spliced
      -- frames free it ('dropAddr ownedAddr'). Resume #2 (the double-resume the
      -- neutered floor would admit) re-runs the same prefix and frees the owned set
      -- AGAIN --- a double-free, caught LOUDLY by 'dropAddr's 'stDead' guard. This
      -- proves the second resume's corruption is REAL and is only SILENT at the
      -- resume site (it surfaces later as a double-free / heap imbalance), which is
      -- precisely what the rc==1 floor (caught above) prevents up front.
      let (s0, contAddr, ownedAddr, _prefix) = buildDoubleResumeNCont
      case St.moveOutContPure contAddr s0 of
        Left e -> assertFailure ("resume #1 must succeed at rc==1: " <> show e)
        Right (_prefix', _hinfo, s1) ->
          case St.dropAddrPure ownedAddr s1 of      -- resume #1's spliced frames free the owned set
            Left e  -> assertFailure ("owned-set free after resume #1 must succeed: " <> show e)
            Right s2 ->
              case St.dropAddrPure ownedAddr s2 of   -- resume #2 (double-resume) frees it AGAIN
                Left (IV.PrimError m)
                  | T.pack "double-free" `T.isInfixOf` m -> pure ()   -- the corruption bites
                Left e  -> assertFailure
                  ("expected a double-free from the second resume, got: " <> show e)
                Right _ -> assertFailure
                  "expected the double-resume to double-free the owned set, but it balanced"
  ]

-- | The double-resume construction shared by 'rcM3DoubleResumeTests': an 'NCont'
-- whose captured prefix is a nested parameterized-handler frame binding the
-- param's Unique to a live 'Owned' value, so 'continuationOwned prefix ==
-- [ownedAddr]' (a real, non-empty owned set). The NCont is allocated at rc==1.
-- Returns the store, the NCont addr, the owned value's addr, and the prefix.
buildDoubleResumeNCont :: (St.Store, St.Addr, St.Addr, St.RCKont)
buildDoubleResumeNCont =
  let s0             = St.emptyStore
      (ownedAddr, s1) = St.allocPure (St.NCon (T.pack "Owned") []) s0
      pb             = Binder (Name (T.pack "s") (Unique 8500)) Unrestricted m2bBoxTy
      h              = m2b2ParamHandler pb
      hsc            = St.RCScope (Map.fromList [(Unique 8500, St.RVBox ownedAddr)]) Map.empty
      prefix         = St.KHandleRC h 0 hsc St.KDoneRC
      cont           = St.NCont prefix (m2b2NoParamHandler, 0, St.emptyRCScope)
      (contAddr, s2) = St.allocPure cont s1
  in (s2, contAddr, ownedAddr, prefix)

-- ---------------------------------------------------------------------------
-- RC machine tests (Task 2: store-threaded CEK over the no-handler fragment)
--
-- Each program is a HAND-INSTRUMENTED ANF: dup/drop are inserted manually (the
-- automatic Perceus pass is Task 5). We run it from an empty store, render the
-- result EXACTLY as the reference renderer would, then drop the result handle,
-- and assert the heap is empty (stLive == 0) -- i.e. every allocation was
-- balanced by a free.

-- | A boxed binder with a placeholder type (the machine ignores binder types;
-- only the Unique identity matters for env lookup).
rcBnd :: Name.Name -> Anf.Binder
rcBnd n = Anf.Binder n Anf.Unrestricted (Ty.CTCon Ty.TcUnit [])

-- | Run a hand-instrumented Expr from the empty store, then RENDER the result
-- and DROP it (if boxed). Returns the rendered text and the final live-cell
-- count. A 'Left' anywhere is reported as a test failure.
runAndAccount :: Anf.Expr -> IO (Text, Int)
runAndAccount e =
  RCM.runExprRC RCP.rcPrimTable Map.empty (St.initSentinel St.emptyStore) e >>= \case
    Left err -> assertFailure ("rc run failed: " <> show err)
    Right (v, s) ->
      case St.renderRCValue s v of
        Left err -> assertFailure ("render failed: " <> show err)
        Right txt ->
          case v of
            St.RVBox a ->
              case St.dropAddrPure a s of
                Left err -> assertFailure ("result drop failed: " <> show err)
                Right s' -> pure (txt, St.stLive (St.stStats s'))
            St.RVLit _           -> pure (txt, St.stLive (St.stStats s))
            St.RVRecMember _ _ envA ->
              case St.dropAddrPure envA s of
                Left err -> assertFailure ("result drop failed: " <> show err)
                Right s' -> pure (txt, St.stLive (St.stStats s'))
            St.RVInst _ _        -> pure (txt, St.stLive (St.stStats s))
            St.RVReuse _         -> assertFailure "a reuse token is never a program result value"

wokRcHeapTests :: TestTree
wokRcHeapTests = testGroup "wok-rc-heap (raw C runtime FFI)"
  [ testCase "alloc/set/get/dup/dec/free round-trip + stats" $ do
      h <- Heap.wokHeapNew
      p <- Heap.wokAlloc h 7 2
      -- Compact slots: one Word64 each (no per-slot tag; kind lives in the Haskell descriptor)
      Heap.wokSlotSet p 0 42
      Heap.wokSlotSet p 1 0
      t  <- Heap.wokTag p
      ar <- Heap.wokArity p
      w0 <- Heap.wokSlotGet p 0
      w1 <- Heap.wokSlotGet p 1
      assertEqual "tag" (7 :: Word32) t
      assertEqual "arity" (2 :: Word32) ar
      assertEqual "slot0" (42 :: Word64) w0
      assertEqual "slot1" (0  :: Word64) w1
      Heap.wokDup p
      rc1 <- Heap.wokDec p
      assertEqual "rc after dup+dec" (1 :: Word64) rc1
      rc0 <- Heap.wokDec p
      assertEqual "rc at zero" (0 :: Word64) rc0
      Heap.wokFree h p
      allocs <- Heap.wokStatAllocs h
      frees  <- Heap.wokStatFrees h
      live   <- Heap.wokStatLive h
      peak   <- Heap.wokStatPeak h
      assertEqual "allocs" (1 :: Word64) allocs
      assertEqual "frees"  (1 :: Word64) frees
      assertEqual "live"   (0 :: Int64) live
      assertEqual "peak"   (1 :: Int64) peak
      Heap.wokHeapFree h
  ]

-- ---------------------------------------------------------------------------
-- RC reuse tests (FBIP Task 1: the reuse token + abstract-heap
-- 'drop_reuse'/'alloc_at' store algebra).
--
-- A reuse pair is 'dropReuse' (release the children, retain the shell as a
-- token) followed by 'allocAt' (consume the token, write the new node into the
-- reserved shell if its placement matches, else free + fresh). The headline win
-- is that a unique cons reusing a same-arity/same-eligibility shell nets to 0
-- allocs / 0 frees and revives the SAME index; a shared cell yields a NULL token
-- and falls back to a fresh alloc; a placement mismatch frees the shell for real
-- and allocates fresh. These run on the abstract heap exclusively, the same way
-- 'rcDropTests' does.
wokRcReuseTests :: TestTree
wokRcReuseTests = testGroup "rc-reuse"
  [ testCase "unique cons reuse nets 0 alloc / 0 free and revives the same index" $ do
      -- Build a unique 'Cons 1 Nil': the Nil tail is an inline immediate (no cell,
      -- routed by 'alloc' on a nullary 'NCon'), so the only counted cell is the
      -- Cons. Drop-reuse it (unique, rc 1), then alloc_at a new same-arity
      -- 'Cons 2 Nil'.
      r <- runExceptT $ do
             (nil, s1)  <- St.alloc (St.NCon (T.pack "Nil") []) St.emptyStore
             (cons, s2) <- St.alloc
                             (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVBox nil]) s1
             let newNode = St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 2), St.RVBox nil]
                 allocsBefore = St.stAllocs (St.stStats s2)
                 freesBefore  = St.stFrees (St.stStats s2)
             (tok, s3) <- St.dropReuse cons s2
             (a, s4)   <- St.allocAt tok newNode s3
             pure (cons, newNode, allocsBefore, freesBefore, tok, a, s4)
      case r of
        Left e -> assertFailure ("reuse pair failed: " <> show e)
        Right (cons, newNode, allocsBefore, freesBefore, tok, a, s4) -> do
          St.valueChildren tok @?= []
          a @?= cons                         -- same index revived
          St.stAllocs (St.stStats s4) - allocsBefore @?= 0
          St.stFrees  (St.stStats s4) - freesBefore  @?= 0
          case St.derefPure a s4 of
            Right c -> St.cNode c @?= newNode
            Left e  -> assertFailure ("deref of revived shell: " <> show e)
  , testCase "shared cell yields RVReuse Nothing and falls back to a fresh alloc (+1/0)" $ do
      -- A cons shared at rc 2: drop_reuse decrements (no free, NULL token), then
      -- alloc_at NULL fresh-allocates.
      r <- runExceptT $ do
             (nil, s1)  <- St.alloc (St.NCon (T.pack "Nil") []) St.emptyStore
             (cons, s2) <- St.alloc
                             (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVBox nil]) s1
             s3 <- St.incref cons s2          -- share it: rc 2
             let newNode = St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 2), St.RVBox nil]
                 allocsBefore = St.stAllocs (St.stStats s3)
                 freesBefore  = St.stFrees (St.stStats s3)
             (tok, s4) <- St.dropReuse cons s3
             (a, s5)   <- St.allocAt tok newNode s4
             pure (cons, allocsBefore, freesBefore, tok, a, s5)
      case r of
        Left e -> assertFailure ("shared fallback failed: " <> show e)
        Right (cons, allocsBefore, freesBefore, tok, a, s5) -> do
          tok @?= St.RVReuse Nothing
          a /= cons @? "fresh alloc must NOT revive the shared cons"
          St.stAllocs (St.stStats s5) - allocsBefore @?= 1
          St.stFrees  (St.stStats s5) - freesBefore  @?= 0
          -- the shared cons survives at rc 1
          case St.derefPure cons s5 of
            Right c -> St.cRc c @?= 1
            Left e  -> assertFailure ("shared cons must survive: " <> show e)
  , testCase "not-eligible token (arity mismatch) frees the shell for real then fresh-allocs (+1/+1)" $ do
      -- A unique arity-2 Cons donor, but alloc_at an arity-1 node: the placement
      -- (arity) does not match, so the shell is freed for real and a fresh cell
      -- allocated. Net +1 alloc / +1 free.
      let (cons, s1) = St.allocPure
                         (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVLit (Anf.LInt 2)])
                         St.emptyStore
          allocsBefore = St.stAllocs (St.stStats s1)
          freesBefore  = St.stFrees (St.stStats s1)
          newNode = St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 9)]   -- arity 1, != donor arity 2
      r <- runExceptT $ do
             (tok, s2) <- St.dropReuse cons s1
             (a, s3)   <- St.allocAt tok newNode s2
             pure (tok, a, s3)
      case r of
        Left e -> assertFailure ("not-eligible fallback failed: " <> show e)
        Right (_, a, s3) -> do
          St.stAllocs (St.stStats s3) - allocsBefore @?= 1
          St.stFrees  (St.stStats s3) - freesBefore  @?= 1
          -- the donor index is freed for real (UAF on re-deref); the fresh node is at a new index
          (a /= cons) @? "fresh alloc must not revive the freed donor"
          case St.derefPure cons s3 of
            Left _  -> pure ()
            Right _ -> assertFailure "donor shell must be freed for real"
          case St.derefPure a s3 of
            Right c -> St.cNode c @?= newNode
            Left e  -> assertFailure ("fresh node deref: " <> show e)
  , testCase "valueChildren of a reuse token is empty (inert to dup/drop)" $ do
      St.valueChildren (St.RVReuse Nothing) @?= []
      St.valueChildren (St.RVReuse (Just (St.ReuseSlot (St.HAddr 7) 2 True 24))) @?= []
  ]

-- | The in-flight reservation set ('stReserved', effect-safety Task 1). A
-- 'dropReuse' that reserves a shell inserts its 'rsAddr' into 'stReserved'; an
-- 'allocAt' that consumes a 'Just' token (on EITHER the reuse re-stamp or the
-- not-eligible free+fresh path) removes it. So a complete reuse pair nets back to
-- the prior set, while a reservation whose 'allocAt' has not run lingers in the
-- set --- exactly the addresses the later abort-reclaim collector consults.
wokRcReservedTests :: TestTree
wokRcReservedTests = testGroup "rc-reserved"
  [ testCase "dropReuse reserves a unique shell -> rsAddr in stReserved" $ do
      -- A unique 'Cons 1 Nil' (the Nil tail is an inline immediate, so the Cons
      -- is the only counted cell). dropReuse reserves its shell; its address is
      -- now tracked as in-flight.
      r <- runExceptT $ do
             (nil, s1)  <- St.alloc (St.NCon (T.pack "Nil") []) St.emptyStore
             (cons, s2) <- St.alloc
                             (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVBox nil]) s1
             (tok, s3)  <- St.dropReuse cons s2
             pure (cons, tok, s3)
      case r of
        Left e -> assertFailure ("dropReuse failed: " <> show e)
        Right (cons, tok, s3) -> do
          case tok of
            St.RVReuse (Just (St.ReuseSlot a _ _ _)) -> a @?= cons
            other -> assertFailure ("expected a Just reuse token, got " <> show other)
          Set.member cons (St.stReserved s3) @? "the reserved shell must be in stReserved"
  , testCase "allocAt reuse releases the reservation -> stReserved nets empty after the pair" $ do
      -- The reuse re-stamp path: dropReuse inserts, allocAt (same-arity) consumes
      -- and removes. The set returns to its prior (empty) value.
      r <- runExceptT $ do
             (nil, s1)  <- St.alloc (St.NCon (T.pack "Nil") []) St.emptyStore
             (cons, s2) <- St.alloc
                             (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVBox nil]) s1
             let newNode = St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 2), St.RVBox nil]
                 reservedBefore = St.stReserved s2
             (tok, s3)  <- St.dropReuse cons s2
             (a, s4)    <- St.allocAt tok newNode s3
             pure (cons, a, reservedBefore, s3, s4)
      case r of
        Left e -> assertFailure ("reuse pair failed: " <> show e)
        Right (cons, a, reservedBefore, s3, s4) -> do
          a @?= cons                                           -- same shell revived
          Set.member cons (St.stReserved s3) @? "reserved while in flight"
          Set.notMember cons (St.stReserved s4) @? "released after allocAt reuse"
          St.stReserved s4 @?= reservedBefore                  -- nets back to prior
  , testCase "allocAt not-eligible (arity mismatch) releases the reservation" $ do
      -- The not-eligible free+fresh path also consumes the token, so its address
      -- is removed from stReserved even though the shell is freed (not revived).
      r <- runExceptT $ do
             (cons, s1) <- St.alloc
                             (St.NCon (T.pack "Cons")
                                [St.RVLit (Anf.LInt 1), St.RVLit (Anf.LInt 2)]) St.emptyStore
             let newNode = St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 9)]  -- arity 1 != donor 2
                 reservedBefore = St.stReserved s1
             (tok, s2)  <- St.dropReuse cons s1
             (a, s3)    <- St.allocAt tok newNode s2
             pure (cons, a, reservedBefore, s2, s3)
      case r of
        Left e -> assertFailure ("not-eligible fallback failed: " <> show e)
        Right (cons, a, reservedBefore, s2, s3) -> do
          (a /= cons) @? "fresh alloc must not revive the freed donor"
          Set.member cons (St.stReserved s2) @? "reserved while in flight"
          Set.notMember cons (St.stReserved s3) @? "released after not-eligible allocAt"
          St.stReserved s3 @?= reservedBefore
  , testCase "shared cell (rc>1) dropReuse does NOT insert (RVReuse Nothing)" $ do
      -- A cons shared at rc 2: dropReuse decrements in place and returns a NULL
      -- token; nothing is reserved, so stReserved is untouched.
      r <- runExceptT $ do
             (nil, s1)  <- St.alloc (St.NCon (T.pack "Nil") []) St.emptyStore
             (cons, s2) <- St.alloc
                             (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt 1), St.RVBox nil]) s1
             s3 <- St.incref cons s2          -- share it: rc 2
             let reservedBefore = St.stReserved s3
             (tok, s4)  <- St.dropReuse cons s3
             pure (tok, reservedBefore, s4)
      case r of
        Left e -> assertFailure ("shared dropReuse failed: " <> show e)
        Right (tok, reservedBefore, s4) -> do
          tok @?= St.RVReuse Nothing
          St.stReserved s4 @?= reservedBefore                  -- untouched
  ]

-- | The IR-level half of FBIP reuse (Task 3): the two forms a later post-pass
-- emits and the machine sites that execute them. A reuse pair is a
-- @let tok = __rc_drop_reuse parent@ (the @drop_reuse@ intrinsic, returning a
-- reuse token instead of unit) followed by a @let r = RReuseCon tok Con fields@
-- (the @alloc_at@ allocation form, consuming the token). Both forms are produced
-- ONLY by the not-yet-existing pairing post-pass, so these tests build the
-- 'Anf.Expr' directly (no @.wok@ source, no 'Perceus.insertRC') and run it
-- through 'RCM.runExprRC' --- exactly the way 'wokRcReuseTests' exercises the
-- store-algebra layer, but here through the machine so the new 'evalRhsRC' arm
-- and the prim-table entry are on the path.
--
-- The headline assertion is the win: a unique cons reuse nets 0 alloc / 0 free
-- on the abstract backend (the only counted allocation over the whole run is the
-- original 'Cons'; the pair adds nothing) and the program output is correct.
-- The C ('CHeap') backend's reuse path is validated end-to-end in Task 5 via real
-- programs through the post-pass; T3 asserts the abstract round-trip only.
wokRcReuseIrTests :: TestTree
wokRcReuseIrTests = testGroup "rc-reuse-ir"
  [ testCase "RReuseCon over a __rc_drop_reuse'd unique cons nets 0 alloc / 0 free and outputs correctly" $ do
      -- let nil = Nil                              -- inline immediate (no cell)
      --     xs  = Cons 1 nil                       -- the ONLY counted alloc (1)
      --     tok = __rc_drop_reuse xs               -- unique rc1: release children, keep shell
      --     r   = RReuseCon tok Cons [2, nil]      -- reuse the shell (0 alloc / 0 free)
      -- in r                                       -- => [2]
      let dropReuseName = Name.Name PN.rcDropReuseName (Unique (-3))
          e = runFresh $ do
                nNil <- freshName (T.pack "nil")
                nXs  <- freshName (T.pack "xs")
                nTok <- freshName (T.pack "tok")
                nR   <- freshName (T.pack "r")
                pure $
                  Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBnd nXs)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nNil])
                  (Anf.Let (rcBnd nTok)
                    (Anf.RApp (Anf.AVar dropReuseName) [Anf.AVar nXs])
                  (Anf.Let (rcBnd nR)
                    (Anf.RReuseCon (Anf.AVar nTok) (T.pack "Cons")
                       [Anf.ALit (Anf.LInt 2), Anf.AVar nNil])
                  (Anf.Ret (Anf.AVar nR)))))
      RCM.runExprRC RCP.rcPrimTable Map.empty (St.initSentinel St.emptyStore) e >>= \case
        Left err -> assertFailure ("rc-reuse-ir run failed: " <> show err)
        Right (v, s) -> do
          -- Output is correct: the revived shell holds 'Cons 2 Nil' => "[2]".
          case St.renderRCValue s v of
            Left err  -> assertFailure ("render failed: " <> show err)
            Right txt -> txt @?= T.pack "[2]"
          -- The win: the reuse pair nets 0 alloc / 0 free. The original 'Cons' is
          -- the single counted allocation over the whole run (the inline 'Nil'
          -- costs no cell), and the pair revives that same shell, so:
          St.stAllocs (St.stStats s) @?= 1
          St.stFrees  (St.stStats s) @?= 0
          -- The result is the revived donor shell (reuse, not a fresh alloc): it
          -- is a boxed dynamic cell still live at rc 1.
          case v of
            St.RVBox a -> case St.derefPure a s of
              Right c -> St.cRc c @?= 1
              Left de -> assertFailure ("deref of result: " <> show de)
            other -> assertFailure ("expected a boxed cons result, got " <> show other)
  ]

-- ---------------------------------------------------------------------------
-- FBIP reuse-pairing post-pass (Task 4): 'reusePairing' over the
-- Perceus-instrumented module.
--
-- The golden dumps 'Perceus.prettyPerceus (reusePairing (insertRC cm))' for three
-- HAND-BUILT modules (no '.wok' source, so the post-Perceus shape is exact and the
-- slot-kind guard can be exercised directly):
--
--   * 'map+1'    ([U64] -> [U64], same slot kinds): the 'Cons' alt rewrites to
--     '__rc_drop_reuse' + 'Cons@tok'; the nullary 'Nil' alt is NOT rewritten (an
--     immediate is never a donor).
--   * 'reverse'  (accumulator, target 'Cons' BEFORE the recursive call): the
--     'Cons' alt rewrites; the token is born and consumed without crossing the
--     call.
--   * 'kindMap'  ([U64] -> [Char], kind-changing): the slot-kind signature guard
--     (§6.3) REFUSES to pair (matched '[KLitInt, KPointer]' /= target
--     '[KLitChar, KPointer]'), so it keeps a plain '__rc_drop' + 'RCon'. This is
--     the regression test for the C descriptor mis-decode the guard prevents.
--
-- Plus a slot-class unit test and a balance-preserving check (balanceLint runs on
-- 'insertRC cm' BEFORE the post-pass and is unaffected; the rewrite cannot
-- unbalance it because the token is structurally affine).
rcReusePairingTests :: TestTree
rcReusePairingTests = testGroup "rc-reuse-pairing"
  [ goldenVsString "map+1"
      "test/rc-reuse-pairing/map.expected"
      (reusePairingDump reuseMapModule)
  , goldenVsString "reverse"
      "test/rc-reuse-pairing/reverse.expected"
      (reusePairingDump reuseReverseModule)
  , goldenVsString "kindchange"
      "test/rc-reuse-pairing/kindchange.expected"
      (reusePairingDump reuseKindModule)
  , goldenVsString "crosscon"
      "test/rc-reuse-pairing/crosscon.expected"
      (reusePairingDump reuseCrossConModule)
  , testCase "cross-constructor reuse is REFUSED even with an identical slot-kind signature (F1)" $ do
      -- Review finding F1: a target 'RCon' whose slot-kind signature equals the
      -- matched cell's but whose CONSTRUCTOR DIFFERS must NOT be paired. The
      -- §6.3 backend-lockstep + descriptor-validity argument holds only for
      -- same-constructor reuse; a cross-constructor re-stamp could decode under a
      -- stale tag-keyed descriptor (silent mis-decode) and diverge from the
      -- abstract heap. So 'A x y -> ... B x y' (A, B same arity + same slot kinds)
      -- keeps a plain '__rc_drop' + 'RCon' --- never a '__rc_drop_reuse'/'@_tok'.
      let dumped = T.unpack (Anf.prettyModule (reusePairing (Perceus.insertRC reuseCrossConModule)))
      assertBool "cross-con: no __rc_drop_reuse emitted"
        (not ("__rc_drop_reuse" `Data.List.isInfixOf` dumped))
      assertBool "cross-con: no @_tok reuse-con emitted"
        (not ("@_tok" `Data.List.isInfixOf` dumped))
      -- The plain drop is still present (correctness is unaffected; we just do not reuse).
      assertBool "cross-con: plain __rc_drop is retained"
        ("__rc_drop(" `Data.List.isInfixOf` dumped)
  , testCase "an ROp between the parent-drop and the same-con RCon is NOT paired (FIX 1a)" $ do
      -- A reuse token must NOT span an effect op: an op captures the continuation
      -- (which would hold the still-unconsumed token), and the reserved shell has no
      -- continuation-RC finalizer, so a token spanning an op under an aborting handler
      -- would leak its shell. 'findTarget' STOPS at the 'ROp', so the alt keeps a plain
      -- '__rc_drop' + 'RCon' --- no '__rc_drop_reuse', no 'RReuseCon'.
      let dumped = T.unpack (Anf.prettyModule (reusePairing (Perceus.insertRC reuseOpModule)))
      assertBool "ROp-span: no __rc_drop_reuse emitted"
        (not ("__rc_drop_reuse" `Data.List.isInfixOf` dumped))
      assertBool "ROp-span: no @_tok reuse-con emitted"
        (not ("@_tok" `Data.List.isInfixOf` dumped))
      -- No token was minted at all (the refusal mints nothing, Uniques stable).
      assertEqual "ROp-span: zero reuse tokens minted"
        [] (tokenUniques (reusePairing (Perceus.insertRC reuseOpModule)))
  , testCase "continuationOwned is TOTAL over an RReuseCon frame body (FIX 1b, no crash)" $ do
      -- The continuation-drop analysis ('continuationOwned' -> 'nonHeadOccs'/
      -- 'dropTargets' in Wok.IR.Escape) must NOT crash if a captured continuation body
      -- contains an 'RReuseCon' (a token in flight when an op captured the
      -- continuation). 'escapingAtomsRhs' treats 'RReuseCon tok c fields' like
      -- 'RCon c fields': the FIELD atoms are the owned moves; the uncounted affine
      -- token contributes NOTHING. So 'continuationOwned' over a frame whose body is
      -- @Ret r@ after @let r = RReuseCon tok Cons [y]@ owns exactly the field's cell.
      let (prefix, ownedAddr) = buildReuseConFrame
      -- The analysis runs (does not 'error') and returns the field's owned addr.
      St.continuationOwned prefix @?= [ownedAddr]
      -- Belt-and-braces: the raw Escape predicates are total over RReuseCon directly.
      let body = Ret (AVar (Name (T.pack "r") (Unique 9102)))
          rcBody = Let (Binder (Name (T.pack "r") (Unique 9102)) Unrestricted m2bBoxTy)
                       (RReuseCon (AVar (Name (T.pack "tok") (Unique 9103)))
                                  (T.pack "Cons") [AVar (Name (T.pack "y") (Unique 9101))])
                       body
      -- nonHeadOccs over the RReuseCon body counts the field (y), never the token.
      assertEqual "nonHeadOccs over RReuseCon body == its field (tok ignored)"
        (Set.fromList [Unique 9101, Unique 9102])
        (Esc.nonHeadOccs Set.empty rcBody)
      -- dropTargets is already total (no __rc_drop in the body -> empty, no crash).
      Esc.dropTargets rcBody @?= Set.empty
  , testCase "seedSupply scans handler arm bodies; minted token avoids arm-binder collision (F2)" $ do
      -- Review finding F2: 'exprMaxU' must descend into a 'Handle's handler arm
      -- bodies (mirroring 'Perceus.handlerMaxU'), else 'seedSupply' can seed BELOW
      -- an arm binder's Unique and 'freshU' mints a colliding '_tok'.
      --
      -- 'reuseHandlerModule' has its largest Unique buried in an op-arm body, and a
      -- reusable Cons-map pattern inside the handled expression. After the fix,
      -- 'exprMaxU' accounts for the arm binder, and the minted token Unique must be
      -- strictly above EVERY Unique present before the pass.
      let instrumented = Perceus.insertRC reuseHandlerModule
          armMaxBefore = maximum (map (RP.exprMaxU . Anf.tbBody) (Anf.cmBinds instrumented))
          fused        = reusePairing instrumented
          tokUs        = tokenUniques fused
      -- exprMaxU sees the arm-buried Unique (1000), not just the surface binders.
      assertBool ("exprMaxU accounts for the arm-buried Unique (got " <> show armMaxBefore <> ")")
        (armMaxBefore >= 1000)
      -- The pass minted at least one fresh token (the handled expr is reusable).
      assertBool "reuse fired inside the handled expr (a _tok was minted)" (not (null tokUs))
      -- Every minted token Unique is strictly above the largest pre-existing Unique,
      -- so it cannot collide with the arm binder (the F2 collision the fix prevents).
      assertBool ("minted token Unique(s) " <> show tokUs <> " exceed the pre-pass max " <> show armMaxBefore)
        (all (> armMaxBefore) tokUs)
  , testCase "slotClassOf maps the storage classes per the §6.3 table" $ do
      RP.slotClassOf (Ty.CTCon Ty.TcU64 [])    @?= RP.KLitInt
      RP.slotClassOf (Ty.CTCon Ty.TcU32 [])    @?= RP.KLitInt
      RP.slotClassOf (Ty.CTCon Ty.TcChar [])   @?= RP.KLitChar
      RP.slotClassOf (Ty.CTCon Ty.TcUnit [])   @?= RP.KLitUnit
      -- Slice E1, Task 3: a String is a counted 'NString' cell stored as a pointer,
      -- so its slot class is 'KPointer' (was 'NonEncodable' when String was inline).
      RP.slotClassOf (Ty.CTCon Ty.TcString []) @?= RP.KPointer
      RP.slotClassOf (Ty.CTCon Ty.TcBool [])   @?= RP.KPointer
      RP.slotClassOf (Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]) @?= RP.KPointer
      RP.slotClassOf (Ty.CTCon (Ty.TcTuple 2) [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcU64 []])
        @?= RP.KPointer
  , testCase "reuse-compatible iff same arity AND equal class at every position" $ do
      let intList = [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]]
          chrList = [Ty.CTCon Ty.TcChar [], Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcChar []]]
      -- map (a -> a) / reverse: identical signatures.
      (RP.conSlotSig intList == RP.conSlotSig intList) @? "Int-list signatures match"
      -- kind-changing map: same arity, DIFFERENT class at position 0.
      (RP.conSlotSig intList /= RP.conSlotSig chrList) @? "Int vs Char signatures differ"
      -- arity mismatch: never compatible.
      (RP.conSlotSig intList /= RP.conSlotSig [Ty.CTCon Ty.TcU64 []]) @? "arity differs"
  , testCase "post-pass is balance-preserving: balanceLint on insertRC is unaffected" $ do
      -- The lint runs on the PRE-FBIP instrumented module (balanceLint re-runs
      -- insertRC itself); it must stay clean. The post-pass output is then verified
      -- to run on the machine without a balance regression by the runtime check
      -- below.
      Perceus.balanceLint reuseMapModule     @?= []
      Perceus.balanceLint reuseReverseModule @?= []
      Perceus.balanceLint reuseKindModule    @?= []
  , testCase "rewritten map+1 RUNS identically to the non-reused version (output + balance)" $ do
      -- The headline win: the reuse run nets ~0 net spine allocs, the non-reuse run
      -- allocates the spine fresh, and BOTH produce the same output and balance to
      -- the same baseline. (mapInc [1,2,3] == [2,3,4].)
      let plain = Perceus.insertRC reuseMapRunModule
          fused = reusePairing plain
      plainR <- RCM.runModuleRC plain
      fusedR <- RCM.runModuleRC fused
      case (plainR, fusedR) of
        (Right p, Right f) -> do
          -- Output is byte-identical.
          assertEqual "map+1 output identical (reuse vs non-reuse)"
            (RCM.rcOutput p) (RCM.rcOutput f)
          assertEqual "map+1 output is [2, 3, 4]"
            (T.pack "[2, 3, 4]") (RCM.rcOutput f)
          -- Both balance to baseline (no leak, no over-free).
          assertEqual "non-reuse balances to baseline"
            (RCM.rcBaseline p) (St.stLive (RCM.rcStats p))
          assertEqual "reuse balances to baseline"
            (RCM.rcBaseline f) (St.stLive (RCM.rcStats f))
          -- The win: the fused run records strictly fewer allocator events on the
          -- spine. A unique 3-element map reuses all three Cons shells, so the
          -- fused allocs are below the non-reuse allocs.
          assertBool
            ("FBIP win: fused allocs (" <> show (St.stAllocs (RCM.rcStats f))
               <> ") must be < non-reuse allocs (" <> show (St.stAllocs (RCM.rcStats p)) <> ")")
            (St.stAllocs (RCM.rcStats f) < St.stAllocs (RCM.rcStats p))
        (Left e, _) -> assertFailure ("non-reuse run failed: " <> show e)
        (_, Left e) -> assertFailure ("reuse run failed: " <> show e)
  ]

-- | Dump 'Perceus.prettyPerceus (reusePairing (insertRC cm))' as golden bytes.
reusePairingDump :: Anf.CoreModule -> IO BL.ByteString
reusePairingDump cm =
  pure (BL.pack (T.unpack (Anf.prettyModule (reusePairing (Perceus.insertRC cm))) <> "\n"))

-- Hand-built modules for the reuse-pairing golden. Each is the ANF a real
-- 'map'/'reverse' would elaborate to; binder types are FAITHFUL (so the slot-kind
-- guard is exercised). A trivial 'main' keeps every module a valid 'CoreModule'.

reuseU64, reuseListU64, reuseChar, reuseListChar :: Ty.CType
reuseU64      = Ty.CTCon Ty.TcU64 []
reuseListU64  = Ty.CTCon Ty.TcList [reuseU64]
reuseChar     = Ty.CTCon Ty.TcChar []
reuseListChar = Ty.CTCon Ty.TcList [reuseChar]

reuseBnd :: T.Text -> Int -> Ty.CType -> Anf.Binder
reuseBnd h u t = Anf.Binder (Name h (Unique u)) Anf.Unrestricted t

reuseNm :: T.Text -> Int -> Name
reuseNm h u = Name h (Unique u)

-- mapInc xs = case xs of
--   Cons x xx -> let y = x + 1 ; let ys = mapInc xx ; Cons y ys
--   Nil       -> Nil
reuseMapModule :: Anf.CoreModule
reuseMapModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "mapInc" 10) [reuseBnd "xs" 11 reuseListU64]
      (Anf.Case (Anf.AVar (reuseNm "xs" 11))
        [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 12 reuseU64, reuseBnd "xx" 13 reuseListU64]
            (Anf.Let (reuseBnd "y" 14 reuseU64)
               (Anf.RApp (Anf.APrim (T.pack "Base", T.pack "+"))
                  [Anf.AVar (reuseNm "x" 12), Anf.ALit (Anf.LInt 1)])
            (Anf.Let (reuseBnd "ys" 15 reuseListU64)
               (Anf.RApp (Anf.AVar (reuseNm "mapInc" 10)) [Anf.AVar (reuseNm "xx" 13)])
            (Anf.Let (reuseBnd "r" 16 reuseListU64)
               (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "y" 14), Anf.AVar (reuseNm "ys" 15)])
            (Anf.Ret (Anf.AVar (reuseNm "r" 16))))))
        , Anf.AltCon (T.pack "Nil") []
            (Anf.Let (reuseBnd "n" 17 reuseListU64) (Anf.RCon (T.pack "Nil") [])
              (Anf.Ret (Anf.AVar (reuseNm "n" 17))))
        ])
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- revAcc acc xs = case xs of
--   Cons x xx -> let acc2 = Cons x acc ; revAcc acc2 xx
--   Nil       -> acc
reuseReverseModule :: Anf.CoreModule
reuseReverseModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "revAcc" 20) [reuseBnd "acc" 21 reuseListU64, reuseBnd "xs" 22 reuseListU64]
      (Anf.Case (Anf.AVar (reuseNm "xs" 22))
        [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 23 reuseU64, reuseBnd "xx" 24 reuseListU64]
            (Anf.Let (reuseBnd "acc2" 25 reuseListU64)
               (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "x" 23), Anf.AVar (reuseNm "acc" 21)])
            (Anf.Let (reuseBnd "rr" 27 reuseListU64)
               (Anf.RApp (Anf.AVar (reuseNm "revAcc" 20))
                  [Anf.AVar (reuseNm "acc2" 25), Anf.AVar (reuseNm "xx" 24)])
            (Anf.Ret (Anf.AVar (reuseNm "rr" 27)))))
        , Anf.AltCon (T.pack "Nil") [] (Anf.Ret (Anf.AVar (reuseNm "acc" 21)))
        ])
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- kindMap xs = case xs of            (Int -> Char: the slot-kind guard refuses)
--   Cons x xx -> let c = toChar x ; let ys = kindMap xx ; Cons c ys
--   Nil       -> Nil
reuseKindModule :: Anf.CoreModule
reuseKindModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "kindMap" 30) [reuseBnd "xs" 31 reuseListU64]
      (Anf.Case (Anf.AVar (reuseNm "xs" 31))
        [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 32 reuseU64, reuseBnd "xx" 33 reuseListU64]
            (Anf.Let (reuseBnd "c" 34 reuseChar)
               (Anf.RApp (Anf.APrim (T.pack "Base", T.pack "toChar")) [Anf.AVar (reuseNm "x" 32)])
            (Anf.Let (reuseBnd "ys" 35 reuseListChar)
               (Anf.RApp (Anf.AVar (reuseNm "kindMap" 30)) [Anf.AVar (reuseNm "xx" 33)])
            (Anf.Let (reuseBnd "r" 36 reuseListChar)
               (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "c" 34), Anf.AVar (reuseNm "ys" 35)])
            (Anf.Ret (Anf.AVar (reuseNm "r" 36))))))
        , Anf.AltCon (T.pack "Nil") []
            (Anf.Let (reuseBnd "n" 37 reuseListChar) (Anf.RCon (T.pack "Nil") [])
              (Anf.Ret (Anf.AVar (reuseNm "n" 37))))
        ])
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- | A runnable version of 'reuseMapModule': @main = mapInc [1, 2, 3]@. Built with
-- inline 'Nil' (the immediate) and three 'Cons' cells, so the reuse run revives
-- all three shells while the non-reuse run allocates them fresh.
reuseMapRunModule :: Anf.CoreModule
reuseMapRunModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "mapInc" 10) [reuseBnd "xs" 11 reuseListU64]
      (Anf.Case (Anf.AVar (reuseNm "xs" 11))
        [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 12 reuseU64, reuseBnd "xx" 13 reuseListU64]
            (Anf.Let (reuseBnd "y" 14 reuseU64)
               (Anf.RApp (Anf.APrim (T.pack "Base", T.pack "+"))
                  [Anf.AVar (reuseNm "x" 12), Anf.ALit (Anf.LInt 1)])
            (Anf.Let (reuseBnd "ys" 15 reuseListU64)
               (Anf.RApp (Anf.AVar (reuseNm "mapInc" 10)) [Anf.AVar (reuseNm "xx" 13)])
            (Anf.Let (reuseBnd "r" 16 reuseListU64)
               (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "y" 14), Anf.AVar (reuseNm "ys" 15)])
            (Anf.Ret (Anf.AVar (reuseNm "r" 16))))))
        , Anf.AltCon (T.pack "Nil") []
            (Anf.Let (reuseBnd "n" 17 reuseListU64) (Anf.RCon (T.pack "Nil") [])
              (Anf.Ret (Anf.AVar (reuseNm "n" 17))))
        ])
  , Anf.TopBind (reuseNm "main" 0) []
      (Anf.Let (reuseBnd "nil" 40 reuseListU64) (Anf.RCon (T.pack "Nil") [])
      (Anf.Let (reuseBnd "l3" 41 reuseListU64)
         (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 3), Anf.AVar (reuseNm "nil" 40)])
      (Anf.Let (reuseBnd "l2" 42 reuseListU64)
         (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar (reuseNm "l3" 41)])
      (Anf.Let (reuseBnd "l1" 43 reuseListU64)
         (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar (reuseNm "l2" 42)])
      (Anf.Let (reuseBnd "res" 44 reuseListU64)
         (Anf.RApp (Anf.AVar (reuseNm "mapInc" 10)) [Anf.AVar (reuseNm "l1" 43)])
      (Anf.Ret (Anf.AVar (reuseNm "res" 44))))))))
  ]

-- crossCon xs = case xs of      (review finding F1: A and B are same-type, same
--   A x y -> let r = B x y ; r    arity, same slot-kind (both KPointer) constructors;
--   B x y -> let r = A x y ; r    the cross-constructor rebuild must NOT be paired)
--
-- Both constructors carry two boxed (list) fields, so the matched and target
-- slot-kind signatures are IDENTICAL ([KPointer, KPointer]). Only the
-- same-constructor guard (F1) keeps this from being (unsoundly) reused.
reuseCrossConModule :: Anf.CoreModule
reuseCrossConModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "crossCon" 50) [reuseBnd "t" 51 reuseListU64]
      (Anf.Case (Anf.AVar (reuseNm "t" 51))
        [ Anf.AltCon (T.pack "A") [reuseBnd "x" 52 reuseListU64, reuseBnd "y" 53 reuseListU64]
            (Anf.Let (reuseBnd "r" 54 reuseListU64)
               (Anf.RCon (T.pack "B") [Anf.AVar (reuseNm "x" 52), Anf.AVar (reuseNm "y" 53)])
            (Anf.Ret (Anf.AVar (reuseNm "r" 54))))
        , Anf.AltCon (T.pack "B") [reuseBnd "x" 55 reuseListU64, reuseBnd "y" 56 reuseListU64]
            (Anf.Let (reuseBnd "r" 57 reuseListU64)
               (Anf.RCon (T.pack "A") [Anf.AVar (reuseNm "x" 55), Anf.AVar (reuseNm "y" 56)])
            (Anf.Ret (Anf.AVar (reuseNm "r" 57))))
        ])
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- A module whose largest 'Unique' (1000) is buried in a handler op-arm body, with
-- a reusable Cons-map pattern inside the HANDLED expression (review finding F2).
-- 'exprMaxU' must descend into the arm body so 'seedSupply' seeds above 1000; the
-- minted '_tok' must then exceed it (no collision with the arm binder).
--
--   hMap xs = handle (case xs of
--                       Cons x xx -> let ys = hMap xx ; let r = Cons x ys ; r
--                       Nil       -> Nil)
--             { return v -> v
--             ; op resume -> let big = 1 ; resume big }   (big : Unique 1000)
reuseHandlerModule :: Anf.CoreModule
reuseHandlerModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "hMap" 60) [reuseBnd "xs" 61 reuseListU64]
      (Anf.Handle
        (Anf.Case (Anf.AVar (reuseNm "xs" 61))
          [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 62 reuseU64, reuseBnd "xx" 63 reuseListU64]
              (Anf.Let (reuseBnd "ys" 64 reuseListU64)
                 (Anf.RApp (Anf.AVar (reuseNm "hMap" 60)) [Anf.AVar (reuseNm "xx" 63)])
              (Anf.Let (reuseBnd "r" 65 reuseListU64)
                 (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "x" 62), Anf.AVar (reuseNm "ys" 64)])
              (Anf.Ret (Anf.AVar (reuseNm "r" 65)))))
          , Anf.AltCon (T.pack "Nil") []
              (Anf.Let (reuseBnd "n" 66 reuseListU64) (Anf.RCon (T.pack "Nil") [])
                (Anf.Ret (Anf.AVar (reuseNm "n" 66))))
          ])
        (Anf.Handler
          ( reuseBnd "v" 67 reuseListU64, Anf.Ret (Anf.AVar (reuseNm "v" 67)) )
          [ Anf.OpArm (T.pack "E") (T.pack "op") [] (reuseBnd "resume" 68 reuseU64)
              -- The arm body binds 'big' at Unique 1000 -- LARGER than any binder
              -- outside the handler. exprMaxU must see it.
              (Anf.Let (reuseBnd "big" 1000 reuseU64) (Anf.RAtom (Anf.ALit (Anf.LInt 1)))
                (Anf.Ret (Anf.AVar (reuseNm "big" 1000)))) ]
          Nothing Nothing Nothing))
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- A module where an EFFECT OP ('ROp') sits between the parent-drop point and the
-- target 'RCon' on the Cons alt's straight-line tail (FIX 1a). 'findTarget' must
-- STOP at the 'ROp' (an op captures the continuation, which would hold the still-
-- unconsumed reuse token; the reserved shell has no continuation-RC finalizer, so a
-- token spanning an op under an aborting handler would leak). So this alt is NOT
-- rewritten: no '__rc_drop_reuse', no 'RReuseCon'. The 'Case' is inside a 'Handle'
-- so 'insertRC' instruments the op normally and the parent drop is present.
--
--   opMap xs = handle (case xs of
--                        Cons x xx -> let ys = opMap xx
--                                     let _t = op E.tell [x]   -- the ROp on the tail
--                                     let r  = Cons x ys ; r
--                        Nil       -> Nil)
--              { return v -> v ; op resume -> resume () }
reuseOpModule :: Anf.CoreModule
reuseOpModule = Anf.CoreModule
  [ Anf.TopBind (reuseNm "opMap" 70) [reuseBnd "xs" 71 reuseListU64]
      (Anf.Handle
        (Anf.Case (Anf.AVar (reuseNm "xs" 71))
          [ Anf.AltCon (T.pack "Cons") [reuseBnd "x" 72 reuseU64, reuseBnd "xx" 73 reuseListU64]
              (Anf.Let (reuseBnd "ys" 74 reuseListU64)
                 (Anf.RApp (Anf.AVar (reuseNm "opMap" 70)) [Anf.AVar (reuseNm "xx" 73)])
              -- The effect op: token (born at the Cons match drop) would have to span
              -- THIS op to reach the rebuild below. 'findTarget' refuses (FIX 1a).
              (Anf.Let (reuseBnd "t" 75 reuseU64)
                 (Anf.ROp Nothing (T.pack "E") (T.pack "tell") [Anf.AVar (reuseNm "x" 72)])
              (Anf.Let (reuseBnd "r" 76 reuseListU64)
                 (Anf.RCon (T.pack "Cons") [Anf.AVar (reuseNm "x" 72), Anf.AVar (reuseNm "ys" 74)])
              (Anf.Ret (Anf.AVar (reuseNm "r" 76))))))
          , Anf.AltCon (T.pack "Nil") []
              (Anf.Let (reuseBnd "n" 77 reuseListU64) (Anf.RCon (T.pack "Nil") [])
                (Anf.Ret (Anf.AVar (reuseNm "n" 77))))
          ])
        (Anf.Handler
          ( reuseBnd "v" 78 reuseListU64, Anf.Ret (Anf.AVar (reuseNm "v" 78)) )
          [ Anf.OpArm (T.pack "E") (T.pack "tell") [reuseBnd "w" 79 reuseU64]
              (reuseBnd "resume" 80 reuseU64)
              (Anf.Let (reuseBnd "u" 81 (Ty.CTCon Ty.TcUnit [])) (Anf.RAtom (Anf.ALit Anf.LUnit))
                (Anf.Let (reuseBnd "rr" 82 reuseListU64)
                   (Anf.RApp (Anf.AVar (reuseNm "resume" 80)) [Anf.AVar (reuseNm "u" 81)])
                  (Anf.Ret (Anf.AVar (reuseNm "rr" 82))))) ]
          Nothing Nothing Nothing))
  , Anf.TopBind (reuseNm "main" 0) [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
  ]

-- | Every '_tok'-hinted binder 'Unique' in a module (the reuse tokens minted by
-- 'reusePairing'). Used by the F2 test to assert minted tokens exceed the
-- pre-pass max Unique.
tokenUniques :: Anf.CoreModule -> [Int]
tokenUniques (Anf.CoreModule bs) = concatMap (tokE . Anf.tbBody) bs
  where
    tokB b = [ u | nameHintEq b, let Unique u = Name.nameUniq (Anf.bndName b) ]
    nameHintEq b = Name.nameHint (Anf.bndName b) == T.pack "_tok"
    tokE (Anf.Ret _)            = []
    tokE (Anf.Let b _ e)        = tokB b ++ tokE e
    tokE (Anf.LetRec defs e)    = concatMap (\(_, _, body) -> tokE body) defs ++ tokE e
    tokE (Anf.Case _ alts)      = concatMap tokAlt alts
    tokE (Anf.LetJoin _ _ jb e) = tokE jb ++ tokE e
    tokE (Anf.Jump _ _)         = []
    tokE (Anf.Handle e h)       =
      tokE e ++ tokE (snd (Anf.hReturn h)) ++ concatMap (tokE . Anf.oaBody) (Anf.hOps h)
    tokE (Anf.InstallHandler _ _ e) = tokE e
    tokAlt (Anf.AltCon _ _ e) = tokE e
    tokAlt (Anf.AltLit _ e)   = tokE e
    tokAlt (Anf.AltDefault e) = tokE e

rcMachineTests :: TestTree
rcMachineTests = testGroup "rc machine"
  [ testCase "boundary admits a standalone closure capturing a LetRec sibling, escaping or not (M2a-2 Stage A)" $ do
      -- M2a-2 Stage A: a standalone closure that captures a 'LetRec' sibling is now
      -- ADMITTED whether it stays LOCAL or ESCAPES. The closure capture is
      -- dup-balanced by the pass (a build-site @__rc_dup@ of the shared env per
      -- capture), and the interpreter keeps an over-applied unnamed intermediate
      -- alive through its own call (deferred-consume, 'KDropCellRC'), so the escaped
      -- closure's cascade-drop balances exactly. A BARE move (con / record / list /
      -- call-arg / alias) of a sibling stays rejected (Stage B). See
      -- 'rlamSiblingCaptureEscapes' / the 'isRLam' narrowing in 'Wok.IR.Reachable'.
      --   NON-escaping:  let f n = 0 (LetRec) ; let h = \m -> f m ; in 0   (h dropped)
      --   ESCAPING:      let f n = 0 (LetRec) ; let h = \m -> f m ; in h   (h returned)
      let u64    = Ty.CTCon Ty.TcU64 []
          funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
          fName' = Name (T.pack "f") (Unique 990001)
          mName' = Name (T.pack "m") (Unique 990004)
          rName' = Name (T.pack "r") (Unique 990005)
          hName' = Name (T.pack "h") (Unique 990003)
          fBnd'  = Anf.Binder fName' Anf.Unrestricted funTy
          nBnd'  = Anf.Binder (Name (T.pack "n") (Unique 990002)) Anf.Unrestricted u64
          hBnd'  = Anf.Binder hName' Anf.Unrestricted funTy
          mBnd'  = Anf.Binder mName' Anf.Unrestricted u64
          rBnd'  = Anf.Binder rName' Anf.Unrestricted u64
          -- @cap@ = the closure body captures the sibling 'f'; @esc@ = the closure
          -- escapes (the enclosing body returns 'h' instead of the scalar 0).
          mkBody cap esc =
            Anf.LetRec [(fBnd', [nBnd'], Anf.Ret (Anf.ALit (Anf.LInt 0)))]
              (Anf.Let hBnd'
                 (Anf.RLam [mBnd']
                    (if cap
                       then Anf.Let rBnd' (Anf.RApp (Anf.AVar fName') [Anf.AVar mName'])
                                          (Anf.Ret (Anf.AVar rName'))
                       else Anf.Ret (Anf.AVar mName')))
                 (if esc then Anf.Ret (Anf.AVar hName')
                         else Anf.Ret (Anf.ALit (Anf.LInt 0))))
          cmWith cap esc = Anf.CoreModule
            [ Anf.TopBind (Name (T.pack "main") (Unique 990000)) [] (mkBody cap esc) ]
      -- NON-escaping sibling-capturing closure is ADMITTED.
      firstOrderNoHandlerViolations (cmWith True False) @?= []
      -- ESCAPING sibling-capturing closure is now ADMITTED (M2a-2 Stage A) and must
      -- RUN SOUND: the result is the escaped closure (a value CAF), so the run
      -- succeeds, is heap-balanced, and matches the reference interpreter.
      firstOrderNoHandlerViolations (cmWith True True) @?= []
      let escCm = pruneToReachable (cmWith True True)
      rc <- RCM.runModuleRCUnchecked (Perceus.insertRC escCm)
      case (Interp.runModule escCm, rc) of
        (Right v, Right run) -> do
          Interp.renderValue v @?= RCM.rcOutput run
          let st = RCM.rcStats run; bl = RCM.rcBaseline run
          assertEqual "escaping closure-capture: heap balanced (live)" bl (St.stLive st)
          assertEqual "escaping closure-capture: heap balanced (allocs-frees)"
            bl (St.stAllocs st - St.stFrees st)
        (refRes, rcRes) ->
          assertFailure ("both interpreters must succeed; got "
                           <> show (either show (const "ok") refRes) <> " / "
                           <> show (either show (const "ok") rcRes))
      -- A closure that does NOT capture a sibling is admitted regardless.
      firstOrderNoHandlerViolations (cmWith False False) @?= []
  , testCase "list literal renders and heap empties after result drop" $ do
      -- let n   = Nil
      --     c2  = Cons 2 n
      --     xs  = Cons 1 c2
      -- in xs                      -- => [1, 2]
      (txt, live) <- runAndAccount $ runFresh $ do
        nNil <- freshName (T.pack "n")
        nC2  <- freshName (T.pack "c2")
        nXs  <- freshName (T.pack "xs")
        pure $
          Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
            (Anf.Let (rcBnd nC2)
              (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar nNil])
              (Anf.Let (rcBnd nXs)
                (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nC2])
                (Anf.Ret (Anf.AVar nXs))))
      txt @?= T.pack "[1, 2]"
      live @?= 0

  , testCase "record projection: dup kept field, drop parent, heap empties" $ do
      -- let l0 = Nil
      --     l1 = Cons 1 l0          -- the field we keep
      --     m0 = Nil
      --     m1 = Cons 2 m0          -- the field we discard (freed via parent drop)
      --     p  = Pair { fst = l1, snd = m1 }
      --     k  = p.fst              -- alias into the record (NOT yet owned)
      --     k' = __rc_dup k         -- take ownership of the kept field
      --     _  = __rc_drop p        -- frees the record shell AND the discarded snd
      -- in k'                       -- => [1]
      (txt, live) <- runAndAccount $ runFresh $ do
        nL0 <- freshName (T.pack "l0"); nL1 <- freshName (T.pack "l1")
        nM0 <- freshName (T.pack "m0"); nM1 <- freshName (T.pack "m1")
        nP  <- freshName (T.pack "p");  nK  <- freshName (T.pack "k")
        nK' <- freshName (T.pack "kp"); nU  <- freshName (T.pack "u")
        let dropName = Name.Name (T.pack "__rc_drop") (Unique (-1))
            dupName  = Name.Name (T.pack "__rc_dup")  (Unique (-2))
        pure $
          Anf.Let (rcBnd nL0) (Anf.RCon (T.pack "Nil") [])
          (Anf.Let (rcBnd nL1) (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nL0])
          (Anf.Let (rcBnd nM0) (Anf.RCon (T.pack "Nil") [])
          (Anf.Let (rcBnd nM1) (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar nM0])
          (Anf.Let (rcBnd nP)
            (Anf.RRecord (T.pack "Pair")
              [ (T.pack "fst", Anf.AVar nL1), (T.pack "snd", Anf.AVar nM1) ])
          (Anf.Let (rcBnd nK)  (Anf.RProj (T.pack "fst") (Anf.AVar nP))
          (Anf.Let (rcBnd nK') (Anf.RApp (Anf.AVar dupName) [Anf.AVar nK])
          (Anf.Let (rcBnd nU)  (Anf.RApp (Anf.AVar dropName) [Anf.AVar nP])
          (Anf.Ret (Anf.AVar nK')))))))))
      txt @?= T.pack "[1]"
      live @?= 0

  , testCase "__rc_drop frees a tuple and returns unit; result is a literal" $ do
      -- let p = Tuple2 1 2
      --     _ = __rc_drop p
      -- in 99                       -- => 99, heap empty (the tuple was freed)
      (txt, live) <- runAndAccount $ runFresh $ do
        nP <- freshName (T.pack "p"); nU <- freshName (T.pack "u")
        let dropName = Name.Name (T.pack "__rc_drop") (Unique (-1))
        pure $
          Anf.Let (rcBnd nP)
            (Anf.RCon (T.pack "Tuple2") [Anf.ALit (Anf.LInt 1), Anf.ALit (Anf.LInt 2)])
          (Anf.Let (rcBnd nU) (Anf.RApp (Anf.AVar dropName) [Anf.AVar nP])
          (Anf.Ret (Anf.ALit (Anf.LInt 99))))
      txt @?= T.pack "99"
      live @?= 0

  , testCase "__rc_dup is a no-op on a literal" $ do
      -- let x = __rc_dup 5 in x     -- => 5, no allocation at all
      (txt, live) <- runAndAccount $ runFresh $ do
        nX <- freshName (T.pack "x")
        let dupName = Name.Name (T.pack "__rc_dup") (Unique (-2))
        pure $
          Anf.Let (rcBnd nX) (Anf.RApp (Anf.AVar dupName) [Anf.ALit (Anf.LInt 5)])
          (Anf.Ret (Anf.AVar nX))
      txt @?= T.pack "5"
      live @?= 0

  , testCase "shared value: one dup balances two drops, heap empties" $ do
      -- let s  = Cons 7 Nil          -- a value shared by two consumers
      --     s' = __rc_dup s          -- second owner
      --     a  = Tuple2 s 1          -- consumes the original ownership
      --     b  = Tuple2 s' 2         -- consumes the duped ownership
      --     _  = __rc_drop a         -- frees a AND its share of s
      --     _  = __rc_drop b         -- frees b AND the LAST share of s
      -- in 0                         -- => 0, heap empty
      (txt, live) <- runAndAccount $ runFresh $ do
        nNil <- freshName (T.pack "nil"); nS <- freshName (T.pack "s")
        nS'  <- freshName (T.pack "sp");  nA <- freshName (T.pack "a")
        nB   <- freshName (T.pack "b");   nU1 <- freshName (T.pack "u1")
        nU2  <- freshName (T.pack "u2")
        let dropName = Name.Name (T.pack "__rc_drop") (Unique (-1))
            dupName  = Name.Name (T.pack "__rc_dup")  (Unique (-2))
        pure $
          Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
          (Anf.Let (rcBnd nS)  (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 7), Anf.AVar nNil])
          (Anf.Let (rcBnd nS') (Anf.RApp (Anf.AVar dupName) [Anf.AVar nS])
          (Anf.Let (rcBnd nA)  (Anf.RCon (T.pack "Tuple2") [Anf.AVar nS, Anf.ALit (Anf.LInt 1)])
          (Anf.Let (rcBnd nB)  (Anf.RCon (T.pack "Tuple2") [Anf.AVar nS', Anf.ALit (Anf.LInt 2)])
          (Anf.Let (rcBnd nU1) (Anf.RApp (Anf.AVar dropName) [Anf.AVar nA])
          (Anf.Let (rcBnd nU2) (Anf.RApp (Anf.AVar dropName) [Anf.AVar nB])
          (Anf.Ret (Anf.ALit (Anf.LInt 0)))))))))
      txt @?= T.pack "0"
      live @?= 0

  , testCase "Case derefs the scrutinee, binds children, then drop-parent empties the heap" $ do
      -- let n  = Nil
      --     xs = Cons 42 n
      -- in case xs of
      --      Cons h t -> let _ = __rc_drop xs   -- own-children / drop-parent:
      --                  in h                    --   h is a literal (no dup),
      --                                           --   so drop the whole shell xs
      --                                           --   (recursively freeing n)
      --      Nil      -> 0                        -- => 42, heap empty
      -- This is the canonical Perceus shape for a Case whose kept children are
      -- unboxed: the shell is freed at the match, recursively releasing the tail.
      (txt, live) <- runAndAccount $ runFresh $ do
        nNil <- freshName (T.pack "n");  nXs <- freshName (T.pack "xs")
        nH   <- freshName (T.pack "h");  nT  <- freshName (T.pack "t")
        nU   <- freshName (T.pack "u")
        let dropName = Name.Name (T.pack "__rc_drop") (Unique (-1))
        pure $
          Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
          (Anf.Let (rcBnd nXs) (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 42), Anf.AVar nNil])
          (Anf.Case (Anf.AVar nXs)
            [ Anf.AltCon (T.pack "Cons") [rcBnd nH, rcBnd nT]
                (Anf.Let (rcBnd nU) (Anf.RApp (Anf.AVar dropName) [Anf.AVar nXs])
                  (Anf.Ret (Anf.AVar nH)))
            , Anf.AltCon (T.pack "Nil") []
                (Anf.Ret (Anf.ALit (Anf.LInt 0)))
            ]))
      txt @?= T.pack "42"
      live @?= 0

  , testCase "RLam free-var capture: uncaptured local survives closure drop" $ do
      -- Build an env holding an owned boxed local y (rc=1) that the lambda does
      -- NOT reference. Allocate the closure, then DROP it via __rc_drop (the
      -- Perceus-inserted scope-exit drop), then return y.
      --
      -- Under the old whole-env capture: dropping f cascades into y (y is in
      -- f's cenv), decrementing y from rc=1 to rc=0 and freeing y. The final
      -- Ret (AVar yName) then tries to look up yAddr which is now dead ->
      -- use-after-free (Right with a dead address, or Left if deref fails).
      -- Specifically, the final Ret returns RVBox yAddr, and since yAddr is in
      -- stDead, any subsequent deref (e.g. renderRCValue) would error. But since
      -- our test just checks the returned address equals yAddr, we need to verify
      -- yAddr is still LIVE (not in stDead). We check stLive increased back.
      --
      -- Under the NEW free-var-only capture: y is NOT in f's cenv, so dropping
      -- f does not touch y. y survives with rc=1.
      --
      --   let f  = \x -> 0    -- does NOT reference y
      --       _u = __rc_drop f -- Perceus scope-exit drop: drop the closure
      --   in y                 -- y must still be alive (not freed by drop f)
      let yU        = Unique 1000
          yName     = Name.Name (T.pack "y") yU
          fU        = Unique 1002
          fName     = Name.Name (T.pack "f") fU
          xU        = Unique 1001
          xName     = Name.Name (T.pack "x") xU
          uU        = Unique 1003
          uName     = Name.Name (T.pack "_u") uU
          dropName  = Name.Name (T.pack "__rc_drop") (Unique (-1))
          u64Ty     = Ty.CTCon Ty.TcU64 []
          px        = Anf.Binder xName Anf.Unrestricted u64Ty
          -- f = \x -> 0   (body does NOT mention y)
          e = Anf.Let (Anf.Binder fName Anf.Unrestricted u64Ty)
                      (Anf.RLam [px] (Anf.Ret (Anf.ALit (Anf.LInt 0))))
                      (Anf.Let (Anf.Binder uName Anf.Unrestricted u64Ty)
                               (Anf.RApp (Anf.AVar dropName) [Anf.AVar fName])
                               (Anf.Ret (Anf.AVar yName)))
          s0          = St.emptyStore
          (yAddr, s1) = St.allocPure (St.NCon (T.pack "Y") []) s0
          env         = Map.fromList [(yU, St.RVBox yAddr)]
      RCM.runExprRC RCP.rcPrimTable env s1 e >>= \case
        Left err     -> assertFailure ("expected success, got: " <> show err)
        Right (v, sf) -> do
          -- y must still be live (not freed by the closure drop)
          assertBool "y must not be in stDead after closure drop"
            (St.stLive (St.stStats sf) >= 1)
          case v of
            St.RVBox a -> a @?= yAddr
            other      -> assertFailure ("expected RVBox y, got " <> show other)

  , test_closureInstrumentationHeapEmpty
  , test_closureLintClean
  , test_closureLintTeeth
  ]

-- | A hand-built closure module (Task 3): a boxed local 'b' is captured by a
-- closure 'f' (which ignores its unboxed param and returns the unpacked field),
-- then 'f' is applied. Running the INSTRUMENTED body must end heap-empty: the
-- capture 'b' is consumed by the Case drop-parent inside the closure body and
-- the closure cell is consumed on application.
--
--   main =
--     let b = Box 7
--     in let f = \x -> case b of Box v -> v
--        in let r = f 5
--           in r
closureModule :: Anf.CoreModule
closureModule =
  Anf.CoreModule [Anf.TopBind mainName [] body]
  where
    mainName = Name.Name (T.pack "main") (Unique 2000)
    bN  = Name.Name (T.pack "b") (Unique 2001)
    fN  = Name.Name (T.pack "f") (Unique 2002)
    rN  = Name.Name (T.pack "r") (Unique 2003)
    xN  = Name.Name (T.pack "x") (Unique 2004)
    vN  = Name.Name (T.pack "v") (Unique 2005)
    boxTy = Ty.CTCon (Ty.TcUser (T.pack "Box")) []   -- isBoxedType => True
    u64Ty = Ty.CTCon Ty.TcU64 []                     -- unboxed
    funTy = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []   -- boxed via catch-all
    bB = Anf.Binder bN Anf.Unrestricted boxTy
    fB = Anf.Binder fN Anf.Unrestricted funTy
    rB = Anf.Binder rN Anf.Unrestricted u64Ty
    xB = Anf.Binder xN Anf.Unrestricted u64Ty
    vB = Anf.Binder vN Anf.Unrestricted u64Ty
    body =
      Anf.Let bB (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 7)])
        (Anf.Let fB
          (Anf.RLam [xB]
            (Anf.Case (Anf.AVar bN)
              [Anf.AltCon (T.pack "Box") [vB] (Anf.Ret (Anf.AVar vN))]))
          (Anf.Let rB (Anf.RApp (Anf.AVar fN) [Anf.ALit (Anf.LInt 5)])
            (Anf.Ret (Anf.AVar rN))))

test_closureInstrumentationHeapEmpty :: TestTree
test_closureInstrumentationHeapEmpty =
  testCase "closure instrumentation: build+call is heap-empty" $
    case Perceus.insertRC closureModule of
      Anf.CoreModule (Anf.TopBind _ _ body0 : _) ->
        RCM.runExprRC RCP.rcPrimTable Map.empty St.emptyStore body0 >>= \case
          Left err      -> assertFailure ("run failed: " <> show err)
          Right (_, st) -> St.stLive (St.stStats st) @?= 0
      Anf.CoreModule [] -> assertFailure "insertRC dropped the module's binds"

-- | Task 4: the balanced closure module lints clean (capture-as-consume and the
-- lambda-body scope are both accounted by 'balanceLint').
test_closureLintClean :: TestTree
test_closureLintClean = testCase "closure lint: balanced closure lints clean" $
  Perceus.balanceLint closureModule @?= []

-- | Task 4 teeth: omit one inserted drop and the lint must report the imbalance,
-- proving it is genuinely counting the closure's consumes (not just un-refusing).
test_closureLintTeeth :: TestTree
test_closureLintTeeth = testCase "closure lint: missing capture drop is reported" $
  assertBool "expected a non-empty lint report"
    (not (null (Perceus.lintInstrumented (Perceus.insertRCMutated Perceus.OmitOneDrop closureModule))))

-- ---------------------------------------------------------------------------
-- RC whole-module tests (Task 3: runModuleRC, static globals, result drop)
--
-- These run a HAND-INSTRUMENTED 'CoreModule' end to end through 'runModuleRC':
-- top-level binds are installed into the static immortal region (never counted,
-- never dup/drop'd), 'main' is run, and its result is rendered then dropped. We
-- assert the rendered output AND that the DYNAMIC heap empties (stLive == 0).

-- | A top-level bind. The name's hint matters only for 'main' (located by hint);
-- every other bind is reached by its 'Unique' through the static env.
rcTop :: Name.Name -> [Anf.Binder] -> Anf.Expr -> Anf.TopBind
rcTop = Anf.TopBind

rcModuleTests :: TestTree
rcModuleTests = testGroup "rc module"
  [ testCase "static global function: called by main, never counted, heap empties" $ do
      -- id2 x = x                          -- a top-level FUNCTION (static closure)
      -- main  = let xs = Cons 1 (Cons 2 Nil)   -- dynamic allocation
      --             ys = id2 xs                -- call the static global
      --             _  = __rc_drop ys          -- frees the list (ys aliases xs)
      --         in 0                           -- => 0, dynamic heap empty
      let cm = runFresh $ do
            -- global function 'id2'
            nId  <- freshName (T.pack "id2")
            nIdX <- freshName (T.pack "x")
            -- main locals
            nMain <- freshName (T.pack "main")
            nNil  <- freshName (T.pack "n");  nC2  <- freshName (T.pack "c2")
            nXs   <- freshName (T.pack "xs"); nYs  <- freshName (T.pack "ys")
            nU    <- freshName (T.pack "u")
            let dropName = Name.Name (T.pack "__rc_drop") (Unique (-1))
                idBind = rcTop nId [rcBnd nIdX] (Anf.Ret (Anf.AVar nIdX))
                mainBody =
                  Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBnd nC2)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar nNil])
                  (Anf.Let (rcBnd nXs)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nC2])
                  (Anf.Let (rcBnd nYs) (Anf.RApp (Anf.AVar nId) [Anf.AVar nXs])
                  (Anf.Let (rcBnd nU)  (Anf.RApp (Anf.AVar dropName) [Anf.AVar nYs])
                  (Anf.Ret (Anf.ALit (Anf.LInt 0)))))))
                mainBind = rcTop nMain [] mainBody
            pure (Anf.CoreModule [idBind, mainBind])
      (txt, st, bl) <- RCM.runModuleRC cm >>= \case
                         Left err  -> error ("runModuleRC failed: " <> show err)
                         Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "0"
      -- The dynamic heap is empty: every dynamic alloc was freed, and the static
      -- global closure was NEVER counted (so it does not show up in stLive).
      -- No value-CAFs in this module, so baseline == 0.
      bl @?= (0 :: Int)
      St.stLive st @?= bl
      St.stAllocs st @?= St.stFrees st

  , testCase "boxed result is dropped by runModuleRC; heap empties" $ do
      -- main = Cons 1 (Cons 2 Nil)         -- returns a boxed list directly;
      --                                     -- runModuleRC renders THEN drops it.
      let cm = runFresh $ do
            nMain <- freshName (T.pack "main")
            nNil  <- freshName (T.pack "n"); nC2 <- freshName (T.pack "c2")
            nXs   <- freshName (T.pack "xs")
            let mainBody =
                  Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBnd nC2)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar nNil])
                  (Anf.Let (rcBnd nXs)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nC2])
                  (Anf.Ret (Anf.AVar nXs))))
            pure (Anf.CoreModule [rcTop nMain [] mainBody])
      (txt, st, bl) <- RCM.runModuleRC cm >>= \case
                         Left err  -> error ("runModuleRC failed: " <> show err)
                         Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "[1, 2]"
      -- No value-CAFs, baseline == 0.
      bl @?= (0 :: Int)
      St.stLive st @?= bl
      St.stAllocs st @?= St.stFrees st

  , testCase "literal result, no allocation: empty heap, zero allocs" $ do
      -- main = 99                           -- => 99, no allocation, no drop
      let cm = runFresh $ do
            nMain <- freshName (T.pack "main")
            pure (Anf.CoreModule [rcTop nMain [] (Anf.Ret (Anf.ALit (Anf.LInt 99)))])
      (txt, st, bl) <- RCM.runModuleRC cm >>= \case
                         Left err  -> error ("runModuleRC failed: " <> show err)
                         Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "99"
      -- No value-CAFs, baseline == 0.
      bl @?= (0 :: Int)
      St.stLive st @?= bl
      St.stAllocs st @?= (0 :: Int)

  , testCase "missing main is a loud error" $
      RCM.runModuleRC (Anf.CoreModule []) >>= \case
        Left _  -> pure ()
        Right _ -> assertFailure "expected runModuleRC to reject a module with no main"

  , testCase "HOF with standalone RLam is admitted and runs (M1.5 boundary)" $ do
      -- As of M1.5 'firstOrderNoHandlerViolations' no longer flags 'RLam', so
      -- 'runModuleRC' admits a higher-order program. This test verifies the
      -- boundary guard does NOT reject such a program (it produces the expected
      -- output rather than raising a PrimError).
      --
      --   apply f x = f x
      --   main = let b  = Cons 1 Nil
      --              lam = \y -> 7
      --              r  = apply lam b
      --          in r
      --
      -- NB: this hand-built AST uses rcBnd which annotates every binder with
      -- TcUnit, so Perceus treats every variable as unboxed and inserts no drops.
      -- The 'b' allocation leaks in this synthetic test; that is expected and
      -- acceptable here because the heap-balance invariant is fully covered by
      -- the corpus programs 26-30 which use correctly typed source programs.
      let cm = runFresh $ do
            nApply <- freshName (T.pack "apply")
            nF     <- freshName (T.pack "f")
            nX     <- freshName (T.pack "x")
            nR0    <- freshName (T.pack "r0")
            nMain  <- freshName (T.pack "main")
            nNil   <- freshName (T.pack "nil")
            nB     <- freshName (T.pack "b")
            nLam   <- freshName (T.pack "lam")
            nY     <- freshName (T.pack "y")
            nR     <- freshName (T.pack "r")
            let applyBody =
                  Anf.Let (rcBnd nR0) (Anf.RApp (Anf.AVar nF) [Anf.AVar nX])
                  (Anf.Ret (Anf.AVar nR0))
                applyBind = rcTop nApply [rcBnd nF, rcBnd nX] applyBody
                mainBody =
                  Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBnd nB)
                    (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nNil])
                  (Anf.Let (rcBnd nLam)
                    (Anf.RLam [rcBnd nY] (Anf.Ret (Anf.ALit (Anf.LInt 7))))
                  (Anf.Let (rcBnd nR)
                    (Anf.RApp (Anf.AVar nApply) [Anf.AVar nLam, Anf.AVar nB])
                  (Anf.Ret (Anf.AVar nR)))))
                mainBind = rcTop nMain [] mainBody
            pure (Anf.CoreModule [applyBind, mainBind])
      txt <- RCM.runModuleRC (Perceus.insertRC cm) >>= \case
              Left err  -> error ("runModuleRC failed: " <> show err)
              Right run -> pure (RCM.rcOutput run)
      txt @?= T.pack "7"

  -- -------------------------------------------------------------------------
  -- Immortal baseline tests (Task 3 follow-up).
  --
  -- A value-CAF (0-arity constant bind other than 'main') is forced at load
  -- time; its result lives on the DYNAMIC heap for the lifetime of the module.
  -- These cells are immortal globals: they must not be counted as a leak.
  --
  -- The oracle:  rcBaseline > 0  (the CAF allocated dynamic cells)
  --              stLive == rcBaseline  (main's work balanced; no extra leak)
  --
  -- Without the baseline fix, stLive would be > 0 after main completes even
  -- though there is no leak, falsely reporting a heap imbalance.

  , testCase "value-CAF (pair) allocates immortal cells; baseline>0 and stLive==baseline" $ do
      -- pair = Tuple2 1 2              -- a value-CAF: allocates 1 cell at load time
      -- main = 0                       -- does not allocate; => "0"
      --
      -- After installation, baseline = 1 (the Tuple2 cell is live).
      -- main allocates nothing and returns a literal, so stLive stays at 1.
      -- Oracle: baseline == 1, stLive == 1 (== baseline), no leak on top.
      let cm = runFresh $ do
            nPair  <- freshName (T.pack "pair")
            nPairV <- freshName (T.pack "pairV")  -- local binder inside the CAF body
            nMain  <- freshName (T.pack "main")
            let pairBind = rcTop nPair []
                             (Anf.Let (rcBnd nPairV)
                               (Anf.RCon (T.pack "Tuple2")
                                 [ Anf.ALit (Anf.LInt 1)
                                 , Anf.ALit (Anf.LInt 2) ])
                               (Anf.Ret (Anf.AVar nPairV)))
                mainBind = rcTop nMain [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
            pure (Anf.CoreModule [pairBind, mainBind])
      (txt, st, bl) <- RCM.runModuleRC cm >>= \case
                         Left err  -> error ("runModuleRC failed: " <> show err)
                         Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "0"
      -- The value-CAF genuinely allocated a dynamic cell: baseline must be > 0.
      -- (If this were 0 the test would not exercise the immortal-baseline fix.)
      assertBool "baseline > 0: value-CAF allocated at least one immortal cell" (bl > 0)
      -- main did no allocation and held no references to the pair, so the
      -- dynamic heap must be exactly at the baseline (no leak on top of it).
      St.stLive st @?= bl

  , testCase "value-CAF list allocates multiple immortal cells; baseline>0 and stLive==baseline" $ do
      -- xs   = Cons 10 (Cons 20 Nil)   -- value-CAF: 3 cells at load (Nil, Cons 20, Cons 10)
      -- main = 0                        -- does not allocate; => "0"
      --
      -- After installation, baseline = 3.
      -- main allocates nothing; stLive stays at 3.
      -- Oracle: baseline == 3, stLive == 3 (== baseline), no leak on top.
      let cm = runFresh $ do
            nXs   <- freshName (T.pack "xs")
            nMain <- freshName (T.pack "main")
            nNil  <- freshName (T.pack "nil")
            nC2   <- freshName (T.pack "c2")
            nC1   <- freshName (T.pack "c1")  -- local binder for the head Cons
            let xsBind = rcTop nXs []
                           (Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                           (Anf.Let (rcBnd nC2)
                             (Anf.RCon (T.pack "Cons") [ Anf.ALit (Anf.LInt 20)
                                                       , Anf.AVar nNil ])
                           (Anf.Let (rcBnd nC1)
                             (Anf.RCon (T.pack "Cons") [ Anf.ALit (Anf.LInt 10)
                                                       , Anf.AVar nC2 ])
                           (Anf.Ret (Anf.AVar nC1)))))
                mainBind = rcTop nMain [] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
            pure (Anf.CoreModule [xsBind, mainBind])
      (txt, st, bl) <- RCM.runModuleRC cm >>= \case
                         Left err  -> error ("runModuleRC failed: " <> show err)
                         Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "0"
      -- The list CAF allocated 3 cells (Nil, Cons 20, Cons 10); baseline >= 3.
      assertBool "baseline > 0: list CAF allocated immortal cells" (bl > 0)
      -- main did nothing dynamic; stLive must equal the baseline exactly.
      St.stLive st @?= bl
  ]

-- ---------------------------------------------------------------------------
-- RC local mutual recursion (Task 4: LetRec uncounted region)
--
-- A local 'LetRec' group of mutually-recursive closures is an UNCOUNTED REGION:
-- intra-group edges (even's env references odd, and vice versa) do NOT
-- contribute to reference counts, so the closure-env knot never forms a counted
-- cycle. The group is dropped as a UNIT at scope exit -- dropping one member
-- frees that member's cell but does NOT traverse a sibling edge (same region),
-- so siblings are neither double-freed nor leaked; each is freed by its own
-- scope-exit drop.
--
-- We run a HAND-INSTRUMENTED program with the canonical mutual-recursion shape:
--
--   letrec even = \n -> case eqU64 n 0 of
--                         True  -> let _ = drop bool in 1
--                         False -> let _ = drop bool; m = n - 1 in odd m
--          odd  = \n -> case eqU64 n 0 of
--                         True  -> let _ = drop bool in 0
--                         False -> let _ = drop bool; m = n - 1 in even m
--   in let r  = even 4          -- => 1 (4 is even)
--          _  = drop even       -- scope exit: drop the group as a unit
--          _  = drop odd
--      in r
--
-- Each call allocates one boxed Bool (from eqU64) which its branch drops, so the
-- only residue at scope exit is the two-closure region, dropped explicitly. The
-- result (1) is an unboxed literal, so runAndAccount has nothing further to free.

-- | The Perceus-synthesized @__rc_drop@ intrinsic handle. It is resolved by HINT
-- through the RC prim table (see 'callFn' in "Wok.Interp.RC.Machine" -- the one
-- by-hint case retained for the two RC intrinsics), so any negative 'Unique' that
-- cannot collide with a 'runFresh'-minted binder works as the identity. The
-- arithmetic/comparison prims are instead routed via 'primAtom' (an 'APrim' by
-- identity), mirroring the elaborator.
rcDropName :: Name.Name
rcDropName = Name.Name (T.pack "__rc_drop") (Unique (-1))

-- | A parity-clause body: @\\param -> case eqU64 param 0 of { True -> baseLit;
-- False -> sibling (param - 1) }@, fully ANF-instrumented with a drop of the
-- freshly-allocated boxed Bool in each branch. All fresh names are minted in the
-- SAME 'Fresh' computation as the surrounding group, so no Unique collides (a
-- nested 'runFresh' would restart the counter at 0 and alias the group binders).
rcParityClause :: Name.Name -> Integer -> Name.Name -> Fresh Anf.Expr
rcParityClause param baseLit sibling = do
  nZ <- freshName (T.pack "z");  nB <- freshName (T.pack "b")
  nU <- freshName (T.pack "u");  nM <- freshName (T.pack "m")
  nRec <- freshName (T.pack "rec")
  pure $
    Anf.Let (rcBnd nZ) (Anf.RAtom (Anf.ALit (Anf.LInt 0)))
    (Anf.Let (rcBnd nB)
      (Anf.RApp (primAtom (T.pack "eqU64")) [Anf.AVar param, Anf.AVar nZ])
    (Anf.Case (Anf.AVar nB)
      [ Anf.AltCon (T.pack "True") []
          (Anf.Let (rcBnd nU) (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar nB])
            (Anf.Ret (Anf.ALit (Anf.LInt baseLit))))
      , Anf.AltCon (T.pack "False") []
          (Anf.Let (rcBnd nU) (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar nB])
           (Anf.Let (rcBnd nM)
             (Anf.RApp (primAtom (T.pack "-")) [Anf.AVar param, Anf.ALit (Anf.LInt 1)])
           (Anf.Let (rcBnd nRec)
             (Anf.RApp (Anf.AVar sibling) [Anf.AVar nM])
             (Anf.Ret (Anf.AVar nRec)))))
      ]))

-- | Build the canonical mutual-recursion program:
--
--   letrec even = \n -> case eqU64 n 0 of True -> 1; False -> odd (n-1)
--          odd  = \n -> case eqU64 n 0 of True -> 0; False -> even (n-1)
--   in let r = <entry> <arg>
--          _ = drop <dropFirst>
--          _ = drop <dropSecond>      -- group dropped as a unit, in this order
--      in r
--
-- 'entryIsEven' selects which member 'main' calls; 'dropEvenFirst' selects the
-- scope-exit drop order, so a test can exercise dropping a sibling BEFORE the
-- one it points at (the uncounted-edge case).
rcMutualProgram :: Bool -> Integer -> Bool -> Fresh Anf.Expr
rcMutualProgram entryIsEven arg dropEvenFirst = do
  nEven <- freshName (T.pack "even"); nOdd <- freshName (T.pack "odd")
  nEN   <- freshName (T.pack "en");   nON  <- freshName (T.pack "on")
  nR    <- freshName (T.pack "r")
  nU1   <- freshName (T.pack "u1");   nU2  <- freshName (T.pack "u2")
  evenBody <- rcParityClause nEN 1 nOdd
  oddBody  <- rcParityClause nON 0 nEven
  let entry      = if entryIsEven then nEven else nOdd
      (d1, d2)   = if dropEvenFirst then (nEven, nOdd) else (nOdd, nEven)
  pure $
    Anf.LetRec
      [ (rcBnd nEven, [rcBnd nEN], evenBody)
      , (rcBnd nOdd,  [rcBnd nON], oddBody)
      ]
      (Anf.Let (rcBnd nR) (Anf.RApp (Anf.AVar entry) [Anf.ALit (Anf.LInt arg)])
       (Anf.Let (rcBnd nU1) (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar d1])
        (Anf.Let (rcBnd nU2) (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar d2])
         (Anf.Ret (Anf.AVar nR)))))

rcLetRecTests :: TestTree
rcLetRecTests = testGroup "rc letrec"
  [ testCase "local mutual recursion: even 4 = 1, group drops as a unit, heap empties" $ do
      (txt, live) <- runAndAccount $ runFresh (rcMutualProgram True 4 True)
      txt @?= T.pack "1"
      live @?= 0

  , testCase "odd 4 = 0 via the same group" $ do
      (txt, live) <- runAndAccount $ runFresh (rcMutualProgram False 4 True)
      txt @?= T.pack "0"
      live @?= 0

  , testCase "dropping one sibling before the one it points at does not double-free or leak" $ do
      -- Drop odd FIRST, then even. Because intra-group edges are uncounted,
      -- freeing odd does NOT traverse its edge to even (same region), so even is
      -- still live and is freed by its own drop. Neither double-free nor leak.
      (txt, live) <- runAndAccount $ runFresh (rcMutualProgram True 3 False)
      txt @?= T.pack "0"   -- even 3 = False = 0
      live @?= 0

  -- F6 regression. A covered local 'LetRec' group whose closure bodies reference
  -- a value-CAF must NOT decref the CAF when the group is dropped at scope exit.
  --
  -- The interpreter captures the WHOLE enclosing scope (incl. the CAF's handle)
  -- into each group closure cell. Before F2 made the CAF a static (negative)
  -- handle in the captured env, the group closure captured the CAF's DYNAMIC
  -- counted cell uncounted; at scope exit each member's drop cascaded through
  -- 'countedChildren' into that CAF edge (region-less, so NOT filtered as a
  -- same-region sibling), decref-ing the CAF once PER MEMBER -> premature free /
  -- double-free / stLive below baseline. The invariant: dropping a letrec group
  -- must not decref a cell the group does not own (globals/CAFs/outer borrows).
  --
  -- Shape (run through the REAL pass + runModuleRC, exactly as the corpus does):
  --   caf  = Cons 99 Nil                    -- value-CAF: 2 immortal cells
  --   main = letrec f = \x -> caf           -- two closures, both capture caf
  --                 g = \x -> caf
  --          in 0                           -- => 0, group dropped at scope exit
  -- The group is covered (main has no boxed enclosing locals, the CAF is a global
  -- reference, not a local), so Perceus instruments it with one scope-exit
  -- __rc_drop per member. main allocates nothing dynamic, so the ONLY live cells
  -- after main are the two immortal CAF cells: stLive must equal the baseline.
  , testCase "covered letrec group capturing a value-CAF: no double-free, stLive==baseline" $ do
      let cm = runFresh $ do
            nCaf  <- freshName (T.pack "caf")
            nCafV <- freshName (T.pack "cafV")
            nNil  <- freshName (T.pack "nil")
            nMain <- freshName (T.pack "main")
            nF    <- freshName (T.pack "f");  nG <- freshName (T.pack "g")
            nFX   <- freshName (T.pack "fx"); nGX <- freshName (T.pack "gx")
            let listTy   = Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]
                rcBndL n = Anf.Binder n Anf.Unrestricted listTy
                -- value-CAF: caf = Cons 99 Nil  (2 boxed cells)
                cafBind = rcTop nCaf []
                  (Anf.Let (rcBndL nNil) (Anf.RCon (T.pack "Nil") [])
                   (Anf.Let (rcBndL nCafV)
                     (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 99), Anf.AVar nNil])
                     (Anf.Ret (Anf.AVar nCafV))))
                -- each member closure simply returns the captured CAF.
                memberBody = Anf.Ret (Anf.AVar nCaf)
                mainBody =
                  Anf.LetRec
                    [ (rcBndL nF, [rcBndL nFX], memberBody)
                    , (rcBndL nG, [rcBndL nGX], memberBody)
                    ]
                    (Anf.Ret (Anf.ALit (Anf.LInt 0)))
                mainBind = rcTop nMain [] mainBody
            pure (Anf.CoreModule [cafBind, mainBind])
      (txt, st, bl) <- RCM.runModuleRC (Perceus.insertRC cm) >>= \case
              Left err  -> error ("runModuleRC failed: " <> show err)
              Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run)
      txt @?= T.pack "0"
      -- The CAF allocated immortal cells; the test only has teeth if baseline > 0.
      assertBool "baseline > 0: value-CAF allocated immortal cells" (bl > 0)
      -- The group drop must NOT have touched the CAF: stLive stays at the baseline.
      St.stLive st @?= bl

  -- F1 FOLLOW-UP (review #4) regression. The Jump rule reserves the TRANSITIVE
  -- captured set (union over closeJoins{j}) so an outer Jump does not drop a var
  -- a DOWNSTREAM chained join will consume. The join-body seeding ('jDelta') must
  -- be SYMMETRIC with that reservation: it must seed with the transitive cap too,
  -- not just the join's own cap. Otherwise a join j1 whose body is a Case --- one
  -- arm chaining to a downstream j2 that captures the outer var 'w', the other arm
  -- NOT mentioning w --- never OWNS w (w is in cap(j2), not cap(j1), and not free
  -- in j1's body), so its non-forwarding arm never drops w => w LEAKS on that path
  -- even though the outer Jump reserved it.
  --
  -- This exact ANF shape (an intermediate Case-bodied join that reaches the
  -- w-capturing join only TRANSITIVELY) is not currently emitted by the surface
  -- elaborator (it inlines/specializes the w-using continuation into each arm, so
  -- w lands in that join's OWN cap), so the regression is pinned at the IR level:
  --
  --   g w =                                  -- w : [U64], owned boxed param
  --     join j2(y) = let c = Cons y w in c   -- builds with w  => w in cap(j2)
  --     join j1(z) =                         -- body is a CASE; w NOT free here
  --       case z of
  --         0 -> 0                           -- non-forwarding: w must be DROPPED
  --         _ -> jump j2(7)                  -- chains to j2 (reserves w)
  --     jump j1(sel)                         -- outer jump: reserves transitive cap
  --   main = g [1,2,3] 0                      -- take the sel=0 (leaking) path
  --
  -- On the sel=0 path g returns a literal, so w is never moved out and MUST be
  -- dropped inside g. Before the symmetric-jDelta fix w is un-owned in j1's body
  -- and leaks (stLive > baseline = 0); after, j1's body owns w and its Case drops
  -- it on the non-forwarding arm. We assert BOTH a runnable heap-empty oracle
  -- (stLive == baseline) AND a clean 'balanceLint' (no over-consume / leak report).
  , testCase "F1 follow-up: transitive-cap join body drops a reserved outer var on its non-forwarding arm" $ do
      let buildCM sel = runFresh $ do
            nG    <- freshName (T.pack "g")
            nW    <- freshName (T.pack "w")
            nMain <- freshName (T.pack "main")
            nNil  <- freshName (T.pack "nil")
            nC2   <- freshName (T.pack "c2")
            nC1   <- freshName (T.pack "c1")
            j2    <- freshJoin; j1 <- freshJoin
            nY    <- freshName (T.pack "y")   -- j2 param (unboxed U64)
            nZ    <- freshName (T.pack "z")   -- j1 param (unboxed U64)
            nCell <- freshName (T.pack "cell")
            nGv   <- freshName (T.pack "gv")
            let listTy    = Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]
                u64Ty     = Ty.CTCon Ty.TcU64 []
                rcBndL n  = Anf.Binder n Anf.Unrestricted listTy   -- BOXED
                rcBndU n  = Anf.Binder n Anf.Unrestricted u64Ty    -- unboxed
                -- g w = join j2(y)=Cons y w ; join j1(z)=case z {0->0; _->jump j2 7}
                --       ; jump j1 sel
                gBody =
                  Anf.LetJoin j2 [rcBndU nY]
                    (Anf.Let (rcBndL nCell)
                       (Anf.RCon (T.pack "Cons") [Anf.AVar nY, Anf.AVar nW])
                       (Anf.Ret (Anf.AVar nCell)))
                  (Anf.LetJoin j1 [rcBndU nZ]
                    (Anf.Case (Anf.AVar nZ)
                       [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 0)))
                       , Anf.AltDefault (Anf.Jump j2 [Anf.ALit (Anf.LInt 7)]) ])
                  (Anf.Jump j1 [Anf.ALit (Anf.LInt sel)]))
                gBind = rcTop nG [rcBndL nW] gBody
                -- main = let nil=Nil; c2=Cons 2 nil; c1=Cons 1 c2; gv = g c1 in gv
                mainBody =
                  Anf.Let (rcBndL nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBndL nC2)
                     (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 2), Anf.AVar nNil])
                  (Anf.Let (rcBndL nC1)
                     (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nC2])
                  (Anf.Let (rcBndL nGv) (Anf.RApp (Anf.AVar nG) [Anf.AVar nC1])
                  (Anf.Ret (Anf.AVar nGv)))))
                mainBind = rcTop nMain [] mainBody
            pure (Anf.CoreModule [gBind, mainBind])
      -- (a) production pass must balance: no over-consume / leak lint findings.
      let cm0 = buildCM 0
      assertEqual "balanceLint must be clean on the transitive-cap join shape"
        [] (Perceus.balanceLint cm0)
      -- (b) runnable heap-empty oracle on the LEAKING (sel=0) path: w must be
      -- dropped inside g on the non-forwarding arm. baseline == 0 (no value-CAFs);
      -- before the fix this leaks the [1,2,3] spine (stLive == 3 > 0).
      RCM.runModuleRC (Perceus.insertRC cm0) >>= \case
        Left err  -> assertFailure ("runModuleRC failed: " <> show err)
        Right run -> do
          let st = RCM.rcStats run
              bl = RCM.rcBaseline run
          assertEqual "no value-CAFs: baseline must be 0" 0 bl
          assertEqual "sel=0 (non-forwarding) path: w must be dropped, heap empty"
            bl (St.stLive st)

  -- DIRECT-USE + FORWARD regression (review focus #1, and the move-variant of #2).
  -- A join body that BOTH moves an owned outer var directly into a binding AND
  -- forwards (tail-jumps) to a DOWNSTREAM join that also consumes that var has TWO
  -- consumers of one owned unit, so the pass MUST dup it. The 'Let' dup-planner
  -- keyed only on 'freeVarsExpr body' (syntactic free vars), which does NOT see a
  -- var delivered IMPLICITLY through a downstream join's 'cap'; without the fix it
  -- planned no dup and 'consumedHere' relinquished the var at the direct move, so
  -- the downstream join then consumed a var already moved -> use-after-free /
  -- double-free (balanceLint: over-consume of w). The fix makes the dup-planner and
  -- 'consumedHere' treat 'bodyReservedCap' as "needed later", exactly as the
  -- prompt-drop 'keepInBody' already does. This shape is not emitted by the surface
  -- elaborator (the corpus '--dump-perceus' goldens are unchanged by the fix), so
  -- the regression is pinned at the IR level:
  --
  --   f w =                                    -- w : [U64], owned boxed param
  --     join j2(yb) = let c2 = Pair yb w in c2 -- uses w  => w in cap(j2)
  --     join j1(z)  = let u  = Cons 0 w        -- DIRECT move of w
  --                   in jump j2(u)            -- forwards u; w arrives via cap(j2)
  --     jump j1(9)                             -- outer jump: reserves transitive cap
  --   main = let nil=Nil; c1=Cons 1 nil; r = f c1 in r
  --
  -- The returned Pair(u, w) shares w (referenced through both u's tail and the
  -- Pair's own field), so the single owned unit MUST be dup'd or the result-drop
  -- double-frees w. We assert a clean 'balanceLint' AND a runnable heap-empty
  -- oracle (stLive == baseline == 0).
  , testCase "review #1: join body moving an outer var AND forwarding it dups (no double-consume)" $ do
      let cm = runFresh $ do
            nF    <- freshName (T.pack "f")
            nW    <- freshName (T.pack "w")
            nMain <- freshName (T.pack "main")
            nNil  <- freshName (T.pack "nil")
            nC1   <- freshName (T.pack "c1")
            nR    <- freshName (T.pack "r")
            j2    <- freshJoin; j1 <- freshJoin
            nYb   <- freshName (T.pack "yb")   -- j2 param (boxed list)
            nZ    <- freshName (T.pack "z")    -- j1 param (unboxed U64)
            nU    <- freshName (T.pack "u")    -- j1 direct-use binder (boxed list)
            nC2   <- freshName (T.pack "c2")   -- j2 result (boxed Pair)
            let listTy   = Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]
                u64Ty    = Ty.CTCon Ty.TcU64 []
                rcBndL n = Anf.Binder n Anf.Unrestricted listTy   -- BOXED
                rcBndU n = Anf.Binder n Anf.Unrestricted u64Ty    -- unboxed
                fBody =
                  Anf.LetJoin j2 [rcBndL nYb]
                    (Anf.Let (rcBndL nC2)
                       (Anf.RCon (T.pack "Pair") [Anf.AVar nYb, Anf.AVar nW])
                       (Anf.Ret (Anf.AVar nC2)))
                  (Anf.LetJoin j1 [rcBndU nZ]
                    (Anf.Let (rcBndL nU)
                       (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 0), Anf.AVar nW])
                       (Anf.Jump j2 [Anf.AVar nU]))
                  (Anf.Jump j1 [Anf.ALit (Anf.LInt 9)]))
                fBind = rcTop nF [rcBndL nW] fBody
                mainBody =
                  Anf.Let (rcBndL nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBndL nC1)
                     (Anf.RCon (T.pack "Cons") [Anf.ALit (Anf.LInt 1), Anf.AVar nNil])
                  (Anf.Let (rcBndL nR) (Anf.RApp (Anf.AVar nF) [Anf.AVar nC1])
                  (Anf.Ret (Anf.AVar nR))))
                mainBind = rcTop nMain [] mainBody
            pure (Anf.CoreModule [fBind, mainBind])
      -- (a) production pass must balance: no over-consume / leak lint findings.
      assertEqual "balanceLint must be clean on the direct-use+forward join shape"
        [] (Perceus.balanceLint cm)
      -- (b) runnable heap-empty oracle: the result Pair shares w, so without the
      -- dup the result-drop double-frees w. baseline == 0 (no value-CAFs).
      RCM.runModuleRC (Perceus.insertRC cm) >>= \case
        Left err  -> assertFailure ("runModuleRC failed: " <> show err)
        Right run -> do
          let st = RCM.rcStats run
              bl = RCM.rcBaseline run
          assertEqual "no value-CAFs: baseline must be 0" 0 bl
          assertEqual "direct-use+forward: w dup'd, heap empties" bl (St.stLive st)

  -- Task 7: LetRec member free-var capture tightening.
  --
  -- A boxed local 'y' lives in the enclosing scope. The LetRec group (ev/od)
  -- is a standard mutual-recursion pair that does NOT reference 'y'. Under the
  -- OLD whole-env capture, each member's NClosure captures 'y' via 'groupEnv';
  -- when the group is dropped at scope exit (explicit __rc_drop of each member),
  -- the cascade for each member walks its cenv, finds 'y' (a non-sibling dynamic
  -- cell), decrefs it, and frees it prematurely (use-after-free). Under the NEW
  -- free-var-only capture, 'y' is NOT in any member's cenv, so the cascade never
  -- touches it and 'y' is still live after the group drop.
  --
  -- Shape (using runExprRC with y pre-loaded in the env):
  --   letrec ev k = case eqU64 k 0 of True -> 1; False -> od (k-1)
  --          od k = case eqU64 k 0 of True -> 0; False -> ev (k-1)
  --   in let r  = ev 2
  --          u1 = __rc_drop ev
  --          u2 = __rc_drop od
  --      in y                -- y must still be live after the group drop
  --
  -- We verify: (a) the expression evaluates to RVBox yAddr (y is the result),
  -- (b) stLive >= 1 because y's cell is still allocated and not freed (the
  --     literal result of 'ev 2' frees nothing on drop), and (c) deref yAddr
  --     succeeds (y not in stDead). Under the OLD whole-env capture both members
  --     captured y, so the two group drops double-freed it.
  , testCase "LetRec free-var capture: uncaptured enclosing local survives group drop" $ do
      -- Pre-allocate y as a standalone dynamic cell NOT referenced by ev/od.
      let yU          = Unique 9001
          yName       = Name.Name (T.pack "y") yU
          s0          = St.emptyStore
          (yAddr, s1) = St.allocPure (St.NCon (T.pack "Y") []) s0
          env         = Map.fromList [(yU, St.RVBox yAddr)]
          -- Build the LetRec expression using freshly minted names.
          -- y is in 'env' but NOT free in either member's body.
          e = runFresh $ do
                nEv <- freshName (T.pack "ev"); nOd <- freshName (T.pack "od")
                nEN <- freshName (T.pack "en"); nON <- freshName (T.pack "on")
                nR  <- freshName (T.pack "r")
                nU1 <- freshName (T.pack "u1")
                nU2 <- freshName (T.pack "u2")
                nU3 <- freshName (T.pack "u3")
                evenBody <- rcParityClause nEN 1 nOd
                oddBody  <- rcParityClause nON 0 nEv
                pure $
                  Anf.LetRec
                    [ (rcBnd nEv, [rcBnd nEN], evenBody)
                    , (rcBnd nOd, [rcBnd nON], oddBody)
                    ]
                    (Anf.Let (rcBnd nR)
                       (Anf.RApp (Anf.AVar nEv) [Anf.ALit (Anf.LInt 2)])
                    (Anf.Let (rcBnd nU1)
                       (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar nEv])
                    (Anf.Let (rcBnd nU2)
                       (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar nOd])
                    -- Drop the result of ev 2 (a literal, so drop is a no-op)
                    -- and return y so we can inspect whether y's address is live.
                    (Anf.Let (rcBnd nU3)
                       (Anf.RApp (Anf.AVar rcDropName) [Anf.AVar nR])
                    (Anf.Ret (Anf.AVar yName))))))
      RCM.runExprRC RCP.rcPrimTable env s1 e >>= \case
        Left err      -> assertFailure ("expected success, got: " <> show err)
        Right (v, sf) -> do
          -- y must still be live after the group drop; stLive >= 1 means y's
          -- cell was NOT freed by the cascade through the members' cenv.
          assertBool "y must not be freed by the LetRec group drop"
            (St.stLive (St.stStats sf) >= 1)
          case v of
            St.RVBox a -> do
              a @?= yAddr
              case St.derefPure yAddr sf of
                Left err2 -> assertFailure ("deref y after group drop failed: " <> show err2)
                Right _   -> pure ()
            other -> assertFailure ("expected RVBox y, got " <> show other)

  -- M1.5 PHASE 2 (Task 8) --- NON-ESCAPING enclosing capture is instrumented.
  --
  --   caf  = Box 7                            -- value-CAF (1 immortal cell)
  --   main =
  --     let b = caf                           -- enclosing boxed local (alias of CAF)
  --     in letrec f x = case b of Box v -> v  -- captures b (BORROWED), only called
  --        in let r = f 5
  --           in r                            -- => 7, group dropped at scope exit
  --
  -- Single-member capture: the borrow model moves b into the region (capOcc[b]=1,
  -- need(b)=1, dups(b)=0); at the group drop f's cascade decrefs b exactly once.
  -- The CAF cell is immortal, so stLive must equal the baseline (b aliases it via
  -- a static handle, never counted). The point is that the group is now COVERED
  -- and instrumented (pre-Phase-2 it was passed through unchanged).
  , testCase "non-escaping LetRec capturing one enclosing local: covered, heap==baseline, lint clean" $ do
      let cm = runFresh $ do
            nCaf <- freshName (T.pack "caf")
            nMain <- freshName (T.pack "main")
            nB   <- freshName (T.pack "b")
            nF   <- freshName (T.pack "f");  nX <- freshName (T.pack "x")
            nV   <- freshName (T.pack "v");  nR <- freshName (T.pack "r")
            let boxTy    = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
                u64Ty    = Ty.CTCon Ty.TcU64 []
                bndB n   = Anf.Binder n Anf.Unrestricted boxTy
                bndU n   = Anf.Binder n Anf.Unrestricted u64Ty
                cafBind  = rcTop nCaf []
                  (Anf.Let (bndB nB) (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 7)])
                    (Anf.Ret (Anf.AVar nB)))
                memberBody =
                  Anf.Case (Anf.AVar nB)
                    [Anf.AltCon (T.pack "Box") [bndU nV] (Anf.Ret (Anf.AVar nV))]
                mainBody =
                  Anf.Let (bndB nB) (Anf.RAtom (Anf.AVar nCaf))
                    (Anf.LetRec
                      [ (bndU nF, [bndU nX], memberBody) ]
                      (Anf.Let (bndU nR) (Anf.RApp (Anf.AVar nF) [Anf.ALit (Anf.LInt 5)])
                        (Anf.Ret (Anf.AVar nR))))
            pure (Anf.CoreModule [cafBind, rcTop nMain [] mainBody])
      (txt, st, bl, lintOut) <- RCM.runModuleRC (Perceus.insertRC cm) >>= \case
              Left err  -> error ("runModuleRC failed: " <> show err)
              Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run,
                                 Perceus.balanceLint cm)
      txt @?= T.pack "7"
      assertBool "baseline > 0: the Box CAF allocated an immortal cell" (bl > 0)
      St.stLive st @?= bl
      lintOut @?= ([] :: [Text])

  -- M1.5 PHASE 2 (Task 8) --- SHARED enclosing capture (multiset dup). TWO members
  -- both capture the same enclosing local b, so capOcc[b]=2, need(b)=2, dups(b)=1.
  -- The build emits ONE __rc_dup b; at the group drop BOTH members cascade-decref
  -- b once each (2 total), balanced by the original unit + the dup. Reverting the
  -- multiset dup (dups(b)=0) would leave b with one unit and two decrefs => a
  -- double-free; this test pins the multiset accounting.
  --
  --   caf  = Box 7
  --   main =
  --     let b = caf
  --     in letrec f x = case b of Box v -> v   -- captures b
  --               g x = case b of Box v -> v   -- ALSO captures b
  --        in let r = f 5
  --           in r                             -- => 7, both members drop at exit
  , testCase "shared LetRec capture (two members, one b): multiset dup, heap==baseline, lint clean" $ do
      let cm = runFresh $ do
            nCaf <- freshName (T.pack "caf")
            nMain <- freshName (T.pack "main")
            nB   <- freshName (T.pack "b")
            nF   <- freshName (T.pack "f");  nX <- freshName (T.pack "x")
            nG   <- freshName (T.pack "g");  nY <- freshName (T.pack "y")
            nV   <- freshName (T.pack "v");  nW <- freshName (T.pack "w")
            nR   <- freshName (T.pack "r")
            let boxTy    = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
                u64Ty    = Ty.CTCon Ty.TcU64 []
                bndB n   = Anf.Binder n Anf.Unrestricted boxTy
                bndU n   = Anf.Binder n Anf.Unrestricted u64Ty
                cafBind  = rcTop nCaf []
                  (Anf.Let (bndB nB) (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 7)])
                    (Anf.Ret (Anf.AVar nB)))
                clause vn = Anf.Case (Anf.AVar nB)
                  [Anf.AltCon (T.pack "Box") [bndU vn] (Anf.Ret (Anf.AVar vn))]
                mainBody =
                  Anf.Let (bndB nB) (Anf.RAtom (Anf.AVar nCaf))
                    (Anf.LetRec
                      [ (bndU nF, [bndU nX], clause nV)
                      , (bndU nG, [bndU nY], clause nW)
                      ]
                      (Anf.Let (bndU nR) (Anf.RApp (Anf.AVar nF) [Anf.ALit (Anf.LInt 5)])
                        (Anf.Ret (Anf.AVar nR))))
            pure (Anf.CoreModule [cafBind, rcTop nMain [] mainBody])
      (txt, st, bl, lintOut) <- RCM.runModuleRC (Perceus.insertRC cm) >>= \case
              Left err  -> error ("runModuleRC failed: " <> show err)
              Right run -> pure (RCM.rcOutput run, RCM.rcStats run, RCM.rcBaseline run,
                                 Perceus.balanceLint cm)
      txt @?= T.pack "7"
      assertBool "baseline > 0: the Box CAF allocated an immortal cell" (bl > 0)
      St.stLive st @?= bl
      lintOut @?= ([] :: [Text])

  -- M2a-2 (Task 4) --- the shared env of a CAPTURING NON-ESCAPING group is dropped
  -- EXACTLY ONCE. A two-member group f/g both BORROW-READ one enclosing boxed local
  -- @b = Box 7@ (each base case @case b of Box v -> v@); the body calls @f 2@ and
  -- returns the scalar result (no member escapes). The pass must instrument this as
  -- ordinary acyclic RC: exactly ONE @__rc_drop@ of a member (the shared-env handle,
  -- member 0) at the group's combined last use --- NOT one drop per member, and NO
  -- per-member multiset capture dups. Asserted three ways: (1) a 'prettyPerceus'
  -- count of exactly one member-drop in @main@'s instrumented body, (2) heap-balance
  -- (the single env-drop frees the env, whose cascade frees the captured Box once),
  -- (3) a clean 'balanceLint'.
  , testCase "M2a-2 capturing non-escaping group: shared env dropped EXACTLY once" $ do
      let cm = runFresh $ do
            nB   <- freshName (T.pack "b")
            nMain <- freshName (T.pack "main")
            nF   <- freshName (T.pack "f");  nG <- freshName (T.pack "g")
            nFK  <- freshName (T.pack "fk"); nGK <- freshName (T.pack "gk")
            nV1  <- freshName (T.pack "v1"); nV2 <- freshName (T.pack "v2")
            nFKs <- freshName (T.pack "fks"); nGKs <- freshName (T.pack "gks")
            nFr  <- freshName (T.pack "fr");  nGr <- freshName (T.pack "gr")
            nR   <- freshName (T.pack "r")
            let boxTy  = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
                u64Ty  = Ty.CTCon Ty.TcU64 []
                bndB n = Anf.Binder n Anf.Unrestricted boxTy
                bndU n = Anf.Binder n Anf.Unrestricted u64Ty
                baseRead vn = Anf.Case (Anf.AVar nB)
                  [Anf.AltCon (T.pack "Box") [bndU vn] (Anf.Ret (Anf.AVar vn))]
                recArm selfK sib ksN rN =
                  Anf.Let (bndU ksN) (Anf.RApp (primAtom (T.pack "-")) [Anf.AVar selfK, Anf.ALit (Anf.LInt 1)])
                    (Anf.Let (bndU rN) (Anf.RApp (Anf.AVar sib) [Anf.AVar ksN])
                      (Anf.Ret (Anf.AVar rN)))
                fBody = Anf.Case (Anf.AVar nFK)
                  [Anf.AltLit (Anf.LInt 0) (baseRead nV1), Anf.AltDefault (recArm nFK nG nFKs nFr)]
                gBody = Anf.Case (Anf.AVar nGK)
                  [Anf.AltLit (Anf.LInt 0) (baseRead nV2), Anf.AltDefault (recArm nGK nF nGKs nGr)]
                mainBody =
                  Anf.Let (bndB nB) (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 7)])
                    (Anf.LetRec
                      [ (bndU nF, [bndU nFK], fBody)
                      , (bndU nG, [bndU nGK], gBody) ]
                      (Anf.Let (bndU nR) (Anf.RApp (Anf.AVar nF) [Anf.ALit (Anf.LInt 2)])
                        (Anf.Ret (Anf.AVar nR))))
            pure (Anf.CoreModule [rcTop nMain [] mainBody])
      (pretty, st, bl, lintOut) <- RCM.runModuleRC (Perceus.insertRC cm) >>= \case
              Left err  -> error ("runModuleRC failed: " <> show err)
              Right run -> pure ( Perceus.prettyPerceus cm
                                , RCM.rcStats run, RCM.rcBaseline run, Perceus.balanceLint cm )
      -- (1) Exactly ONE member-drop in main's body (the single shared-env drop).
      let memberDrops = length (T.breakOnAll (T.pack "__rc_drop(f)") pretty)
                          + length (T.breakOnAll (T.pack "__rc_drop(g)") pretty)
      assertEqual "exactly one member-drop (the single shared-env drop, not per-member)"
        1 memberDrops
      -- (2) Heap-balanced: Box + ONE NEnv allocated, both freed by the single drop.
      assertEqual "allocs - frees == baseline (heap balanced)" bl (St.stAllocs st - St.stFrees st)
      St.stLive st @?= bl
      assertEqual "exactly two dynamic allocations (Box + ONE shared NEnv)" 2 (St.stAllocs st)
      -- (3) The pass is balanceLint-clean.
      lintOut @?= ([] :: [Text])

  -- M2a-2 STAGE B --- ESCAPING enclosing capture is now ADMITTED and runs SOUND.
  -- A group that captures an enclosing boxed local AND RETURNS a member (the member
  -- binder flows out of the LetRec body as a value) is dup-balanced by the pass: the
  -- returned member transfers the single shared-env handle out (the env-alive handle
  -- is not also dropped), so the captured 'b' is freed exactly once via the env
  -- cascade when the result CAF drops. CONTROL: the SAME group shape WITHOUT the
  -- enclosing capture (the existing 23-letrec-return-member shape) is also admitted.
  --
  --   main =
  --     let b = Box 7                          -- enclosing boxed local
  --     in letrec f x = case b of Box v -> v   -- captures b (borrowed read)
  --        in f                                -- RETURNS the member f => ESCAPES
  , testCase "escaping LetRec capturing an enclosing local: ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      let boxTy   = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
          u64Ty   = Ty.CTCon Ty.TcU64 []
          funTy   = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
          bName   = Name (T.pack "b") (Unique 970001)
          fName   = Name (T.pack "f") (Unique 970002)
          xName   = Name (T.pack "x") (Unique 970003)
          vName   = Name (T.pack "v") (Unique 970004)
          bBnd    = Anf.Binder bName Anf.Unrestricted boxTy
          fBnd    = Anf.Binder fName Anf.Unrestricted funTy
          xBnd    = Anf.Binder xName Anf.Unrestricted u64Ty
          vBnd    = Anf.Binder vName Anf.Unrestricted u64Ty
          -- capture: member reads the enclosing b; nocap: member ignores b.
          memberBody captures =
            if captures
              then Anf.Case (Anf.AVar bName)
                     [Anf.AltCon (T.pack "Box") [vBnd] (Anf.Ret (Anf.AVar vName))]
              else Anf.Ret (Anf.AVar xName)
          mkBody captures =
            Anf.Let bBnd (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 7)])
              (Anf.LetRec [(fBnd, [xBnd], memberBody captures)]
                 (Anf.Ret (Anf.AVar fName)))         -- RETURN f => member escapes
          cmWith captures = Anf.CoreModule
            [ Anf.TopBind (Name (T.pack "main") (Unique 970000)) [] (mkBody captures) ]
      -- M2a-2 Stage B: the capturing-and-escaping group is now ADMITTED and runs
      -- SOUND (the returned member transfers the single env handle out).
      firstOrderNoHandlerViolations (cmWith True) @?= []
      let escCm = pruneToReachable (cmWith True)
      rc <- RCM.runModuleRCUnchecked (Perceus.insertRC escCm)
      case (Interp.runModule escCm, rc) of
        (Right v, Right run) -> do
          Interp.renderValue v @?= RCM.rcOutput run
          let st = RCM.rcStats run; bl = RCM.rcBaseline run
          assertEqual "escaping enclosing-capture return: heap balanced (live)" bl (St.stLive st)
          assertEqual "escaping enclosing-capture return: heap balanced (allocs-frees)"
            bl (St.stAllocs st - St.stFrees st)
        (Left _, Left _) -> pure ()
        (refRes, rcRes) ->
          assertFailure ("RC run must agree with reference; got ref="
                           <> either show (const "ok") refRes <> " rc="
                           <> either show (const "ok") rcRes)
      -- Control: the same escaping group WITHOUT the enclosing capture (the existing
      -- 23-letrec-return-member shape) is also admitted.
      firstOrderNoHandlerViolations (cmWith False) @?= []

  -- M1.5 PHASE 2 REVIEW FINDING 1 (verified DOUBLE-FREE; M2a-1 Task 5 narrowing) ---
  -- a member that CONSUMES (moves) an enclosing capture is now ADMITTED when the
  -- group is NON-escaping (the pass emits a dup-per-consuming-use; the runtime
  -- accounting balances), and is REJECTED only when a member ALSO ESCAPES the
  -- scope (region-lifetime extension = M2a-2; 'letRecMemberEscapes'). CONTROL: a
  -- BORROWED READ (a Case scrutinee keeping only the unboxed field, like 31/32) is
  -- admitted regardless.
  --
  --   peek p = 0
  --   main = let b = Box 6
  --          in letrec go k = case k of 0 -> peek b ; _ -> go (k-1)   -- peek b MOVES b
  --          in let r = go 1 in r                                     -- go non-escaping
  , testCase "consuming LetRec capture: REJECTED (escaping or not), borrow admitted" $ do
      let boxTy   = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
          u64Ty   = Ty.CTCon Ty.TcU64 []
          funTy   = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
          peekName = Name (T.pack "peek") (Unique 960001)
          pName    = Name (T.pack "p")    (Unique 960002)
          bName    = Name (T.pack "b")    (Unique 960003)
          goName   = Name (T.pack "go")   (Unique 960004)
          kName    = Name (T.pack "k")    (Unique 960005)
          vName    = Name (T.pack "v")    (Unique 960006)
          rName    = Name (T.pack "r")    (Unique 960007)
          pBnd     = Anf.Binder pName  Anf.Unrestricted boxTy
          bBnd     = Anf.Binder bName  Anf.Unrestricted boxTy
          goBnd    = Anf.Binder goName Anf.Unrestricted funTy
          kBnd     = Anf.Binder kName  Anf.Unrestricted u64Ty
          vBnd     = Anf.Binder vName  Anf.Unrestricted u64Ty
          rBnd     = Anf.Binder rName  Anf.Unrestricted u64Ty
          peekBind = Anf.TopBind peekName [pBnd] (Anf.Ret (Anf.ALit (Anf.LInt 0)))
          -- consuming=True : 0 -> peek b      (b is a CALL ARGUMENT => moved)
          -- consuming=False: 0 -> case b of Box v -> v   (BORROWED READ, like 31/32)
          memberBody consuming =
            Anf.Case (Anf.AVar kName)
              [ Anf.AltLit (Anf.LInt 0)
                  (if consuming
                     then Anf.Let rBnd (Anf.RApp (Anf.AVar peekName) [Anf.AVar bName])
                                       (Anf.Ret (Anf.AVar rName))
                     else Anf.Case (Anf.AVar bName)
                            [Anf.AltCon (T.pack "Box") [vBnd] (Anf.Ret (Anf.AVar vName))])
              , Anf.AltDefault
                  (Anf.Let kBnd (Anf.RApp (Anf.AVar goName) [Anf.ALit (Anf.LInt 0)])
                     (Anf.Ret (Anf.AVar kName)))
              ]
          -- escaping=False: body is 'let r = go 1 in r' (go used only as call head)
          -- escaping=True : body is 'Ret go'            (the member escapes)
          mkBody consuming escaping =
            Anf.Let bBnd (Anf.RCon (T.pack "Box") [Anf.ALit (Anf.LInt 6)])
              (Anf.LetRec [(goBnd, [kBnd], memberBody consuming)]
                 (if escaping
                    then Anf.Ret (Anf.AVar goName)
                    else Anf.Let rBnd (Anf.RApp (Anf.AVar goName) [Anf.ALit (Anf.LInt 1)])
                           (Anf.Ret (Anf.AVar rName))))
          cmWith consuming escaping = Anf.CoreModule
            [ peekBind
            , Anf.TopBind (Name (T.pack "main") (Unique 960000)) [] (mkBody consuming escaping) ]
      -- Consuming-capture support is DEFERRED: ANY consuming use is REJECTED,
      -- whether the member escapes or not.
      assertBool "non-escaping consuming-capture group must be rejected"
        (not (null (firstOrderNoHandlerViolations (cmWith True False))))
      assertBool "consuming-AND-escaping group must be rejected"
        (not (null (firstOrderNoHandlerViolations (cmWith True True))))
      -- Control: the borrowed-read shape (Case scrutinee keeping only the unboxed
      -- field, like 31/32) is NOT rejected, escaping or not.
      firstOrderNoHandlerViolations (cmWith False False) @?= []

  -- M1.5 PHASE 2 REVIEW FINDING 2 (verified LEAK) --- a NESTED inner LetRec whose
  -- member captures an OUTER group member (cross-region counted edge) is EXCLUDED
  -- from coverage by the pass ('capturesRegion', spec 5.5) but was passed through
  -- UN-instrumented => leak. The boundary must refuse it. CONTROL: the same nested
  -- shape where the inner member does NOT reference the outer member is NOT rejected.
  --
  --   main = letrec outer k = ... outer (k-1)
  --          in letrec inner j = case j of 0 -> outer 1 ; _ -> inner (j-1)  -- inner CALLS outer
  --          in inner 2
  , testCase "cross-region LetRec capture (inner member calls outer member): boundary rejects it" $ do
      let u64Ty   = Ty.CTCon Ty.TcU64 []
          funTy   = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
          outerN  = Name (T.pack "outer") (Unique 950001)
          kName   = Name (T.pack "k")     (Unique 950002)
          innerN  = Name (T.pack "inner") (Unique 950003)
          jName   = Name (T.pack "j")     (Unique 950004)
          tName   = Name (T.pack "t")     (Unique 950005)
          rName   = Name (T.pack "r")     (Unique 950006)
          outerB  = Anf.Binder outerN Anf.Unrestricted funTy
          kBnd    = Anf.Binder kName  Anf.Unrestricted u64Ty
          innerB  = Anf.Binder innerN Anf.Unrestricted funTy
          jBnd    = Anf.Binder jName  Anf.Unrestricted u64Ty
          tBnd    = Anf.Binder tName  Anf.Unrestricted u64Ty
          rBnd    = Anf.Binder rName  Anf.Unrestricted u64Ty
          outerBody =
            Anf.Case (Anf.AVar kName)
              [ Anf.AltLit (Anf.LInt 0) (Anf.Ret (Anf.ALit (Anf.LInt 0)))
              , Anf.AltDefault
                  (Anf.Let kBnd (Anf.RApp (Anf.AVar outerN) [Anf.ALit (Anf.LInt 0)])
                     (Anf.Ret (Anf.AVar kName)))
              ]
          -- crosses=True : inner's base case CALLS the outer member (cross-region).
          -- crosses=False: inner's base case returns a literal (no outer reference).
          innerBody crosses =
            Anf.Case (Anf.AVar jName)
              [ Anf.AltLit (Anf.LInt 0)
                  (if crosses
                     then Anf.Let tBnd (Anf.RApp (Anf.AVar outerN) [Anf.ALit (Anf.LInt 1)])
                                       (Anf.Ret (Anf.AVar tName))
                     else Anf.Ret (Anf.ALit (Anf.LInt 0)))
              , Anf.AltDefault
                  (Anf.Let jBnd (Anf.RApp (Anf.AVar innerN) [Anf.ALit (Anf.LInt 0)])
                     (Anf.Ret (Anf.AVar jName)))
              ]
          mkBody crosses =
            Anf.LetRec [(outerB, [kBnd], outerBody)]
              (Anf.LetRec [(innerB, [jBnd], innerBody crosses)]
                 (Anf.Let rBnd (Anf.RApp (Anf.AVar innerN) [Anf.ALit (Anf.LInt 2)])
                    (Anf.Ret (Anf.AVar rName))))
          cmWith crosses = Anf.CoreModule
            [ Anf.TopBind (Name (T.pack "main") (Unique 950000)) [] (mkBody crosses) ]
      -- Teeth: the cross-region group fires the violation.
      assertBool "cross-region capture group must be rejected"
        (not (null (firstOrderNoHandlerViolations (cmWith True))))
      -- Control: the same nested shape with NO cross-region reference is NOT rejected.
      firstOrderNoHandlerViolations (cmWith False) @?= []
  ]

-- ---------------------------------------------------------------------------
-- M2a-1 boundary: the escape-narrowed guard ACCEPTS non-escaping reproducers
-- and still REJECTS their escaping variants
--
-- 'test/rc-m2a1/33-consuming-capture-nonescape.wok' (case #1): a 'LetRec'
-- member that CONSUMES an enclosing boxed capture via a function-call argument
-- ('RApp'). The group is NON-ESCAPING, but consuming-capture support is DEFERRED
-- (a dup-per-consuming-use scheme was proved unsound at scale by Suite G), so the
-- '#1' guard REJECTS ANY consuming use of an enclosing capture --- escaping or
-- not. The file lives in 'test/rc-m2a1/' (NOT auto-discovered) since it is no
-- longer admitted.
--
-- 'test/rc-examples/34-rlam-sibling-nonescape.wok' (case #4): a standalone
-- closure ('RLam') that captures a 'LetRec' group sibling; the closure is never
-- used and is dropped (NON-ESCAPING), so the boundary guard ACCEPTS it (the
-- '#4' guard only fires when 'rlamSiblingCaptureEscapes'). This shape is the
-- owned/borrowed-capture (Invariant-2) case and stays supported.
--
-- The ESCAPING variants STAY rejected (region-lifetime extension = M2a-2):
--   * 'test/rc-m2a1/36-rlam-sibling-escape.wok' RETURNS the closure 'h'.
--   * 'test/rc-m2a1/37-consuming-capture-escape.wok' RETURNS the member 'go'.
--
-- The escaping/rejected variants live in 'test/rc-m2a1/' (NOT 'test/rc-examples/')
-- so they are NOT auto-discovered by the perceus-golden / perceus-lint /
-- rc-differential / rc-stats suites, all of which assert-fail on rejected
-- programs. The admitted reproducer (34) lives in 'test/rc-examples/' and runs
-- under those suites.

-- | Load and elaborate a '.wok' file, then return the boundary-guard
-- violations.  Returns an empty list when the file is in the RC fragment and
-- returns the violation messages when it is not.  Propagates loader and
-- elaboration errors as 'assertFailure' (the file must at least elaborate).
boundaryViolationsOf :: FilePath -> IO [Text]
boundaryViolationsOf path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s  -> assertFailure ("elaborate: " <> s)
        Right cm -> pure (firstOrderNoHandlerViolations cm)

-- M2b-1 boundary regression (full-branch review, verified UAF): a handler whose
-- return/op arm captures an enclosing BOXED local double-frees that local (on both
-- the abort and tail-resume paths) because the arm is instrumented as a fresh owned
-- scope while the enclosing handler-body still drops the capture, and
-- 'continuationOwned' does not process the handler scope (spec 4.2). It is DEFERRED
-- and must be REJECTED at the boundary. These programs live in 'test/rc-m2b-reject/'
-- (NOT the auto-discovered 'test/rc-m2b/' run-corpus, since the differential harness
-- uses 'runModuleRCUnchecked' which bypasses the guard and would UAF on them).
rcM2bRejectTests :: TestTree
rcM2bRejectTests = testGroup "m2b-1 boundary (enclosing-capture arms REJECTED)"
  [ testCase "abort arm sealing an enclosing boxed local into a con is REJECTED" $ do
      vs <- boundaryViolationsOf "test/rc-m2b-reject/08-arm-capture-con-reject.wok"
      assertBool "handler arm capturing an enclosing boxed local must be rejected"
        (not (null vs))
  , testCase "tail-resume arm handing an enclosing boxed local to resume is REJECTED" $ do
      vs <- boundaryViolationsOf "test/rc-m2b-reject/09-arm-capture-resume-reject.wok"
      assertBool "handler arm capturing an enclosing boxed local must be rejected"
        (not (null vs))
  , testCase "op arm that ALIASES resume (let k2 = k) is REJECTED (code-review #4)" $ do
      vs <- boundaryViolationsOf "test/rc-m2b-reject/12-resume-alias-reject.wok"
      assertBool "an aliased resume escapes the move-out tracking and must be rejected"
        (not (null vs))
  , testCase "carrier-wall param (k k ()) is REJECTED at ELABORATION (M2b-2 Task 4C OccursCheck)" $ do
      -- test/rc-m2b-reject/13-carrier-wall-param-reject.wok does  set x k -> k k ()
      -- which unifies the resume continuation type with itself applied, causing an
      -- OccursCheck type error.  It never reaches the boundary guard; pin the rejection
      -- by asserting the file FAILS TO ELABORATE.
      result <- Loader.loadProgram "test/rc-m2b-reject/13-carrier-wall-param-reject.wok" []
      case result of
        Left lerr -> assertFailure ("loader: " <> show lerr)
        Right (entryName, ms) ->
          case Pipeline.elaborateProgramFull entryName ms of
            Left _  -> pure ()   -- expected: type error (OccursCheck on k k ())
            Right _ -> assertFailure
              "expected elaboration failure (OccursCheck on carrier-wall), got Right"
  ]

-- | Direct unit coverage for the M2b-1 resume-escape predicate (code-review #2/#4).
-- m2bResumeEscapes must (a) NOT follow alias-renames (an aliased resume escapes the
-- ctxResume move-out tracking -> leak) and (b) DESCEND into nested handler arms (a
-- resume stored inside a nested handler's arm escapes). It must still ADMIT a direct
-- tail-resume and an abort (resume unused). Built at the ANF level to avoid the
-- surface parser's friction with nested with-in handlers inside an arm.
rcM2bResumeEscapeTests :: TestTree
rcM2bResumeEscapeTests = testGroup "m2b-1 resume-escape predicate (code-review #2/#4)"
  [ testCase "direct tail-resume does NOT escape (admitted)" $
      Esc.m2bResumeEscapes resumeB tailResumeBody @?= False
  , testCase "abort (resume unused) does NOT escape (admitted)" $
      Esc.m2bResumeEscapes resumeB abortBody @?= False
  , testCase "aliased resume (let k2 = k) DOES escape (rejected)" $
      Esc.m2bResumeEscapes resumeB aliasBody @?= True
  , testCase "resume stored inside a NESTED handler arm DOES escape (rejected)" $
      Esc.m2bResumeEscapes resumeB nestedArmBody @?= True
  , testCase "carrier-wall: resume as a non-head arg (k x k) DOES escape (M2b-2 Task 4C)" $
      Esc.m2bResumeEscapes resumeB carrierWallBody @?= True
  ]
  where
    u64       = Ty.CTCon Ty.TcU64 []
    nm s i    = Name (T.pack s) (Unique i)
    resumeB   = Binder (nm "resume" 7001) Unrestricted u64
    resumeV   = AVar (nm "resume" 7001)
    -- let res = resume(0) in res
    tailResumeBody =
      Let (Binder (nm "res" 7002) Unrestricted u64) (RApp resumeV [ALit (LInt 0)])
          (Ret (AVar (nm "res" 7002)))
    -- Ret 0  (resume never applied)
    abortBody = Ret (ALit (LInt 0))
    -- let k2 = resume in let r = k2(0) in r
    aliasBody =
      Let (Binder (nm "k2" 7003) Unrestricted u64) (RAtom resumeV)
        (Let (Binder (nm "r" 7004) Unrestricted u64) (RApp (AVar (nm "k2" 7003)) [ALit (LInt 0)])
             (Ret (AVar (nm "r" 7004))))
    -- handle (Ret 0) with { return v -> v;  B.bop(bk) -> let c = Cons resume Nil in Ret 0 }
    -- resume is stored into a Cons INSIDE the nested handler's op arm.
    nestedArmBody =
      Handle (Ret (ALit (LInt 0)))
        (Handler (Binder (nm "v" 7005) Unrestricted u64, Ret (AVar (nm "v" 7005)))
                 [ OpArm (T.pack "B") (T.pack "bop") [] (Binder (nm "bk" 7006) Unrestricted u64)
                     (Let (Binder (nm "c" 7007) Unrestricted u64)
                          (RCon (T.pack "Cons") [resumeV, ALit LUnit])
                          (Ret (ALit (LInt 0)))) ]
                 Nothing Nothing Nothing)
    -- Carrier-wall: resume appears as a NON-HEAD argument (M2b-2 Task 4C).
    -- Models  set x k -> let r = k x k in r  where the SECOND k is a non-head
    -- argument.  m2bResumeEscapes must detect this and return True (rejected).
    carrierWallBody =
      Let (Binder (nm "r" 7008) Unrestricted u64)
          (RApp resumeV [ALit (LInt 0), resumeV])
          (Ret (AVar (nm "r" 7008)))

rcM2a1BaselineTests :: TestTree
rcM2a1BaselineTests = testGroup "m2a-1 boundary (escape-narrowed guards)"
  [ testCase "consuming-capture non-escape #1 is REJECTED (deferred)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/33-consuming-capture-nonescape.wok"
      assertBool "any consuming-capture group must be rejected (deferred)" (not (null vs))
  , testCase "rlam-sibling non-escape #4 is ACCEPTED" $ do
      vs <- boundaryViolationsOf "test/rc-examples/34-rlam-sibling-nonescape.wok"
      assertEqual "non-escaping sibling-capturing closure must pass the boundary" [] vs
  -- M2a-2 STAGE A: a sibling captured into an ESCAPING standalone CLOSURE (#6) or a
  -- NESTED escaping closure (#8) is now ADMITTED and runs SOUND. The closure capture
  -- is dup-balanced by the pass, and the interpreter keeps an over-applied unnamed
  -- intermediate alive through its own call (deferred-consume), so the escaped
  -- closure's cascade-drop balances exactly. Both corpora over-apply the escaped
  -- closure ('main = (mk 7) 2'), exercising that path; the run must agree with the
  -- reference value and be heap-balanced.
  , testCase "rlam-sibling ESCAPE #6 is ACCEPTED and runs sound (M2a-2 Stage A)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/36-rlam-sibling-escape.wok"
      assertEqual "an escaping closure capturing a sibling must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/36-rlam-sibling-escape.wok"
  , testCase "consuming-capture ESCAPE #7 is still REJECTED" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/37-consuming-capture-escape.wok"
      assertBool "an escaping consuming-capture group must be rejected" (not (null vs))
  , testCase "rlam-sibling NESTED-ESCAPE #8 is ACCEPTED and runs sound (M2a-2 Stage A)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/38-rlam-nested-escape.wok"
      assertEqual "a sibling captured into a nested escaping closure must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/38-rlam-nested-escape.wok"
  , testCase "consuming-capture NESTED-ESCAPE #9 is REJECTED" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/39-consuming-nested-escape.wok"
      assertBool "a group member captured into a nested escaping closure must be rejected" (not (null vs))
  -- DIRECT-escape (M2a-2 Stage B, now SOUND): a sibling moved DIRECTLY into an
  -- escaping value --- an 'RCon'/'RRecord' field, a list cell, or a non-head call
  -- argument --- is now ADMITTED and runs SOUND. The pass dups the shared env at the
  -- move (dup-on-consume), so the escaped cell owns an independent env unit and the
  -- group's enclosing local is freed exactly once via the env cascade. Each over-
  -- applies the escaped sibling ('main = ... g 2'), exercising the unnamed-
  -- intermediate deferred env-drop; the run must agree with the reference value and
  -- be heap-balanced.
  , testCase "sibling-into-constructor escape #12 is ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/42-sibling-con-escape.wok"
      assertEqual "a sibling moved into an escaping constructor must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/42-sibling-con-escape.wok"
  , testCase "sibling-into-call-argument escape #13 is ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/43-sibling-arg-escape.wok"
      assertEqual "a sibling passed as a non-head arg of an escaping call must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/43-sibling-arg-escape.wok"
  , testCase "sibling-into-list-constructor escape #14 is ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/44-sibling-listcon-escape.wok"
      assertEqual "a sibling stored in an escaping list cell must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/44-sibling-listcon-escape.wok"
  , testCase "sibling-into-record-field escape #15 is ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/45-sibling-record-escape.wok"
      assertEqual "a sibling stored in an escaping record field must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/45-sibling-record-escape.wok"
  -- POSITIVE guards against over-rejection: a member returned DIRECTLY ('Ret f',
  -- mirror of rc-examples/23) and a sibling used only as a CALL HEAD ('f 3') are
  -- NOT escapes via the generalized guard and must STAY ACCEPTED.
  , testCase "direct return-of-member #16 STAYS ACCEPTED (not over-rejected)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/46-return-member-accept.wok"
      assertEqual "a direct return-of-member must pass the boundary" [] vs
  , testCase "sibling-as-call-head #17 STAYS ACCEPTED (not over-rejected)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/47-sibling-callhead-accept.wok"
      assertEqual "a sibling used only as a call head must pass the boundary" [] vs
  -- M2a-2 Stage B: over-applying a DIRECT member return as an UNNAMED INTERMEDIATE
  -- ('(mk 7) 2') leaked the shared env before the interpreter's deferred env-drop on
  -- the 'RVRecMember' unnamed-intermediate path. Must be ACCEPTED and run sound
  -- (heap-balanced + value-match) --- the permanent guard for that fix.
  , testCase "member over-apply #21 is ACCEPTED and runs sound (M2a-2 Stage B)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/51-member-overapply-accept.wok"
      assertEqual "an over-applied direct member return must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/51-member-overapply-accept.wok"
  -- POSITIVE guards against the call-head over-rejection: a recursive group member
  -- whose body CALLS an enclosing boxed CAPTURE 'g' as a call HEAD ('g u') is a
  -- BORROW under uniform borrow-on-call, NOT a move/consume. 'consumingOccs' used to
  -- count the head and (the group being non-escaping) wrongly REJECTED it; now the
  -- head is exempt and the group is ADMITTED and runs SOUND (value-match + heap-
  -- balanced). Both a SATURATED head (#52) and a PARTIAL head (#53) must pass.
  , testCase "capture-as-saturated-call-head #22 is ACCEPTED and runs sound (M2a-2)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/52-capture-callhead-accept.wok"
      assertEqual "a capture used only as a saturated call head must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/52-capture-callhead-accept.wok"
  , testCase "capture-as-partial-call-head #23 is ACCEPTED and runs sound (M2a-2)" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/53-capture-partial-callhead-accept.wok"
      assertEqual "a capture used only as a partial call head must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/53-capture-partial-callhead-accept.wok"
  ]

-- ---------------------------------------------------------------------------
-- M2a-1 lint: 'balanceLint' as the compile-time oracle for case #1/#4
--
-- M2a-1 Tasks 3+4 bring the consuming-capture (#1) and borrowed-sibling (#4)
-- 'LetRec' shapes INTO the Perceus pass's coverage and make 'balanceLint'
-- audit them. The pass emits a build-site '__rc_dup' per consuming use of an
-- enclosing capture so each runtime move owns its unit and the region keeps its
-- per-member cascade unit; 'balanceLint' relinquishes the same multiset, so it is
-- BALANCED on these shapes only when the dup-per-consuming-use is exactly right.
--
-- The RC BOUNDARY guard ('firstOrderNoHandlerViolations') STILL rejects both
-- programs until the escape-narrowing slice (Task 5) --- 'rcM2a1BaselineTests'
-- asserts that. These tests audit the PASS + LINT directly, on the elaborated
-- module ('balanceLint' runs 'insertRC' itself), so they bypass the boundary.

-- | Load and elaborate a '.wok' file to its 'CoreModule'. Propagates loader and
-- elaboration errors as 'assertFailure'.
elaboratedModuleOf :: FilePath -> IO Anf.CoreModule
elaboratedModuleOf path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s  -> assertFailure ("elaborate: " <> s)
        Right cm -> pure cm

rcM2a1LintTests :: TestTree
rcM2a1LintTests = testGroup "m2a-1 lint (balanceLint is the oracle for #4)"
  [ testCase "rlam-sibling #4 is covered and balances clean" $ do
      cm <- elaboratedModuleOf "test/rc-examples/34-rlam-sibling-nonescape.wok"
      assertEqual "balanceLint must be clean on the borrowed-sibling shape"
        [] (Perceus.balanceLint cm)
  , testCase "teeth: OmitOneDrop is caught on #4" $ do
      cm <- elaboratedModuleOf "test/rc-examples/34-rlam-sibling-nonescape.wok"
      assertBool "a dropped __rc_drop must produce a balanceLint violation"
        (not (null (Perceus.lintInstrumented (Perceus.insertRCMutated Perceus.OmitOneDrop cm))))
  ]

-- ---------------------------------------------------------------------------
-- M2a-1 alias-of-sibling hardening: a bare 'let x = f' that aliases a LetRec
-- group sibling 'f' (a borrowed/uncounted-region member) must propagate the
-- sibling's exempt-ness THROUGH the alias --- 'x' is a borrow of the same member,
-- so the pass emits NO '__rc_dup' and NO '__rc_drop' for it and does NOT count it
-- as owned. Before the fix the pass dropped 'x' at its dead point, double-freeing
-- the region member (cell-drop + group-drop); 'runModuleRCUnchecked' errored
-- 'double-free: addr 0' while the boundary guard ACCEPTED the program and
-- 'balanceLint' reported it CLEAN --- it escaped both oracles. The genuine oracle
-- is runtime accounting.
--
--   * '40-alias-sibling-drop' (alias DROPPED, non-escaping): now ACCEPTED by the
--     boundary guard, runs heap-BALANCED, and agrees with the reference value.
--   * '41-alias-sibling-escape' (alias RETURNED, escaping): the borrow leaves the
--     region; the boundary guard's escape detection follows the alias rename and
--     REJECTS it (region-lifetime extension = M2a-2).
rcM2a1AliasTests :: TestTree
rcM2a1AliasTests = testGroup "m2a-1 alias-of-sibling (exempt-ness through aliases)"
  [ testCase "alias-sibling DROP #10: boundary ACCEPTS the non-escaping alias" $ do
      vs <- boundaryViolationsOf "test/rc-m2a1/40-alias-sibling-drop.wok"
      assertEqual "a dropped (non-escaping) alias of a sibling must pass the boundary"
        [] vs
  , testCase "alias-sibling DROP #10: heap empties after RC run (no double-free)" $
      assertHeapEmpty "test/rc-m2a1/40-alias-sibling-drop.wok"
  , testCase "alias-sibling DROP #10: balanceLint is clean (mirrors the pass)" $ do
      cm <- elaboratedModuleOf "test/rc-m2a1/40-alias-sibling-drop.wok"
      assertEqual "balanceLint must be clean on the alias-of-sibling shape"
        [] (Perceus.balanceLint cm)
  , testCase "alias-sibling DROP #10: teeth: OmitOneDrop is caught" $ do
      cm <- elaboratedModuleOf "test/rc-m2a1/40-alias-sibling-drop.wok"
      assertBool "a dropped __rc_drop must produce a balanceLint violation"
        (not (null (Perceus.lintInstrumented (Perceus.insertRCMutated Perceus.OmitOneDrop cm))))
  , testCase "alias-sibling DROP #10: RC run agrees with the reference value" $ do
      cm <- elaboratedModuleOf "test/rc-m2a1/40-alias-sibling-drop.wok"
      let pruned = pruneToReachable cm
      rc <- RCM.runModuleRCUnchecked (Perceus.insertRC pruned)
      case (Interp.runModule pruned, rc) of
        (Right v, Right run) ->
          Interp.renderValue v @?= RCM.rcOutput run
        (refRes, rcRes) ->
          assertFailure ("both interpreters must succeed; got "
                           <> show (either show (const "ok") refRes) <> " / "
                           <> show (either show (const "ok") rcRes))
  , testCase "alias-sibling ESCAPE #11: boundary ACCEPTS and runs sound (M2a-2 Stage B)" $ do
      -- M2a-2 Stage B: a bare ALIAS of a sibling that ESCAPES (returned) is now
      -- ADMITTED and runs SOUND. The env-alias propagation makes the escaping alias
      -- transfer the single shared-env handle out; the scope's env-alive handle is
      -- NOT also dropped, so the env the escaped alias still holds is not double-freed.
      vs <- boundaryViolationsOf "test/rc-m2a1/41-alias-sibling-escape.wok"
      assertEqual "an escaping alias of a sibling must pass the boundary" [] vs
      assertRcAgrees "test/rc-m2a1/41-alias-sibling-escape.wok"
  ]

-- ---------------------------------------------------------------------------
-- M2a-1 sibling-in-cell LOCAL DROP: a LetRec group sibling moved into an
-- ordinary container cell ('NCon'/'NRecord'/list 'Cons') that is then DROPPED
-- LOCALLY (the cell does NOT escape; the result is a scalar). Before the cascade
-- fix, 'countedChildren' returned ALL boxed children of a non-region, non-closure
-- container, so dropping the local cell cascaded into the region member 'f' --- and
-- the LetRec group's own unit-drop freed 'f' again --- a verified DOUBLE-FREE
-- ('double-free: addr 0') under 'runModuleRCUnchecked', while the boundary guard
-- correctly ACCEPTED the program (no escape) and 'balanceLint' reported it clean.
-- The genuine oracle is runtime accounting.
--
-- The fix makes the region/static-child skip in 'countedChildren' uniform across
-- ALL node kinds, so an 'NCon'/'NRecord' cell never cascade-frees a sibling it
-- merely contains; the sibling is freed exactly once by its group's unit-drop.
--
--   * '48-sibling-con-drop'     ('Box f'        dropped locally)
