-- ---------------------------------------------------------------------------
-- M2a-2 Task 1: uniform BORROW-ON-CALL.
--
-- Applying ANY function value BORROWS it (the call is a pure read), never
-- consumes it. Perceus drops a function value at its LAST USE, exactly like any
-- other value. A closure called N times is therefore dup'd 0 times and dropped
-- exactly once. These tests lock that convention together with the heap-balance,
-- value-match, and 'balanceLint' oracles.

-- | Count the inserted @__rc_dup u@ / @__rc_drop u@ calls naming a specific
-- 'Unique' anywhere in an instrumented expression. An RC intrinsic is an
-- @RApp (AVar h) [AVar n]@ whose head hint is the dup/drop hint and whose single
-- operand names @u@.
countRcIntrinsicFor :: Text -> Unique -> Expr -> Int
countRcIntrinsicFor hint u = goE
  where
    isFor (RApp (AVar h) [AVar n]) =
      nameHint h == hint && nameUniq n == u
    isFor _ = False
    one r = if isFor r then 1 else 0
    goE (Ret _)            = 0
    goE (Let _ r e)        = one r + goRhs r + goE e
    goE (Case _ alts)      = sum (map goAlt alts)
    goE (LetJoin _ _ jb e) = goE jb + goE e
    goE (Jump _ _)         = 0
    goE (LetRec defs e)    = sum [ goE d | (_, _, d) <- defs ] + goE e
    goE (Handle e _)       = goE e
    goE (InstallHandler _ _ e) = goE e
    goRhs (RLam _ e) = goE e
    goRhs _          = 0
    goAlt (AltCon _ _ e) = goE e
    goAlt (AltLit _ e)   = goE e
    goAlt (AltDefault e) = goE e

borrowOnCallTests :: TestTree
borrowOnCallTests = testGroup "borrow-on-call"
  [ testCase "closure called twice: borrow => no dup, drop at last use, heap balanced" $
      borrowOnCallTwiceBalanced
  ]

-- main = let f = \x -> x + 1
--        let a = f 10
--        let b = f 20      -- f used twice; borrow => no dup, drop at last use
--        in a + b
borrowOnCallTwiceBalanced :: Assertion
borrowOnCallTwiceBalanced = do
  let intTy = Ty.CTCon Ty.TcU64 []
      funTy = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
      nm h u = Name (T.pack h) (Unique u)
      fLam = RLam [Binder (nm "x" 1) Unrestricted intTy]
               (Let (Binder (nm "x1" 2) Unrestricted intTy)
                    (RApp (primAtom (T.pack "+")) [AVar (nm "x" 1), ALit (LInt 1)])
                 (Ret (AVar (nm "x1" 2))))
      body =
        Let (Binder (nm "f" 3) Unrestricted funTy) fLam
          (Let (Binder (nm "a" 4) Unrestricted intTy) (RApp (AVar (nm "f" 3)) [ALit (LInt 10)])
            (Let (Binder (nm "b" 5) Unrestricted intTy) (RApp (AVar (nm "f" 3)) [ALit (LInt 20)])
              (Let (Binder (nm "s" 6) Unrestricted intTy)
                   (RApp (primAtom (T.pack "+")) [AVar (nm "a" 4), AVar (nm "b" 5)])
                (Ret (AVar (nm "s" 6))))))
      cm     = CoreModule [TopBind (nm "main" 1000000) [] body]
      pruned = pruneToReachable cm
  assertBool "must be accepted" (null (firstOrderNoHandlerViolations pruned))
  -- Borrow-on-call: 'f' (the closure binder, Unique 3) is dup'd 0 times and
  -- dropped exactly once (at its last use, the second call site).
  let instrumented = Perceus.insertRC pruned
      CoreModule iBinds = instrumented
  case [ b | TopBind n _ b <- iBinds, nameHint n == T.pack "main" ] of
    (ib : _) -> do
      assertEqual "f is never dup'd (borrow, not move)"
        0 (countRcIntrinsicFor (T.pack "__rc_dup") (Unique 3) ib)
      assertEqual "f is dropped exactly once (at last use)"
        1 (countRcIntrinsicFor (T.pack "__rc_drop") (Unique 3) ib)
    [] -> assertFailure "instrumented module dropped main"
  rc <- RCM.runModuleRC instrumented
  case (Interp.runModule pruned, rc) of
    (Right v, Right run) -> do
      assertEqual "value" (Interp.renderValue v) (RCM.rcOutput run)
      assertEqual "heap empty" (St.stLive (RCM.rcStats run)) (RCM.rcBaseline run)
      assertEqual "balanced"
        (St.stAllocs (RCM.rcStats run) - St.stFrees (RCM.rcStats run))
        (RCM.rcBaseline run)
    (refRes, rcRes) ->
      assertFailure ("both interpreters must succeed; got "
                       <> either show (const "ok") refRes <> " / "
                       <> either show (const "ok") rcRes)
  assertEqual "balanceLint clean" [] (Perceus.balanceLint pruned)

-- ---------------------------------------------------------------------------
-- M2a-2 Task 3: evaluate 'letrec' via the shared-env + code-pointer
-- representation ('RVRecMember' over a static 'NGroupCode' label plus at most
-- ONE shared 'NEnv' cell). The boundary guard still rejects escaping shapes, so
-- only NON-escaping 'letrec' exercises this path.
--
--   * a CAPTURE-FREE group uses the static empty-env sentinel and allocates NO
--     dynamic group cell (acceptance: zero group allocation);
--   * a CAPTURING group allocates exactly ONE 'NEnv' cell, freed once;
--   * sibling (recursive) calls allocate nothing (the sibling scope is
--     reconstructed inline at entry);
--   * partial application of a member builds an ordinary closure that re-enters
--     the member on full application.

sharedEnvEvalTests :: TestTree
sharedEnvEvalTests = testGroup "sharedenv-eval"
  [ testCase "capture-free mutual even/odd: value-match, heap-balanced, ZERO group allocation" $
      sharedEnvCaptureFreeMutual
  , testCase "capture-free group derefs the static sentinel as the empty env (no collision)" $
      sharedEnvSentinelIsEmptyEnv
  , testCase "capturing group (borrow-read one boxed local): exactly ONE NEnv, freed once" $
      sharedEnvCapturingOneEnv
  , testCase "partial application of a recursive member re-enters it on full application" $
      sharedEnvPartialApplication
  , testCase "bare-member top-level result: runModuleRCUnchecked drops its env (heap-balanced)" $
      sharedEnvBareMemberResult
  ]

-- | Prereq A regression: a 'main' that RETURNS a bare group member
-- ('Ret (AVar even)') produces an 'RVRecMember' as the top-level result. The
-- final result-drop in 'runModuleRCUnchecked' must release that result via its
-- 'valueChildren' (the shared 'NEnv'), exactly like 'RVBox'; otherwise the env
-- cell is never freed and the run is spuriously imbalanced ('stLive' above
-- baseline). The capturing group below allocates exactly one 'NEnv' (it
-- borrow-reads the boxed local @b@), so a missing final drop leaves @live=2@.
--
--   main = let b = Box 7
--          letrec even k = case k of 0 -> (case b of Box v -> v) ; _ -> odd (k-1)
--                 odd  k = case k of 0 -> (case b of Box v -> v) ; _ -> even (k-1)
--          in even                         -- bare member returned => RVRecMember
sharedEnvBareMemberResult :: Assertion
sharedEnvBareMemberResult = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      boxTy  = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
      funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
      nm h u = Name (T.pack h) (Unique u)
      bnd h u ty = Binder (nm h u) Unrestricted ty
      nB = nm "b" 1; nEven = nm "even" 2; nOdd = nm "odd" 3
      baseRead vU = Case (AVar nB)
                      [ AltCon (T.pack "Box") [bnd "v" vU intTy] (Ret (AVar (nm "v" vU))) ]
      recArm selfK sib ks ksU r rU =
        Let (bnd ks ksU intTy) (RApp (primAtom (T.pack "-")) [AVar selfK, ALit (LInt 1)])
          (Let (bnd r rU intTy) (RApp (AVar sib) [AVar (nm ks ksU)])
            (Ret (AVar (nm r rU))))
      evenBody = Case (AVar (nm "ek" 4))
                   [ AltLit (LInt 0) (baseRead 10), AltDefault (recArm (nm "ek" 4) nOdd "eks" 20 "er" 21) ]
      oddBody  = Case (AVar (nm "ok" 5))
                   [ AltLit (LInt 0) (baseRead 11), AltDefault (recArm (nm "ok" 5) nEven "oks" 22 "or" 23) ]
      body =
        Let (bnd "b" 1 boxTy) (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec [ (Binder nEven Unrestricted funTy, [bnd "ek" 4 intTy], evenBody)
                  , (Binder nOdd  Unrestricted funTy, [bnd "ok" 5 intTy], oddBody) ]
            (Ret (AVar nEven)))
      cm     = CoreModule [TopBind (nm "main" 100) [] body]
      pruned = pruneToReachable cm
  RCM.runModuleRCUnchecked (Perceus.insertRC pruned) >>= \case
    Left err  -> assertFailure ("runModuleRCUnchecked failed: " <> show err)
    Right run -> do
      let st = RCM.rcStats run
          bl = RCM.rcBaseline run
      assertEqual "live cells must return to baseline after dropping the bare-member result"
        bl (St.stLive st)
      assertEqual "allocs minus frees must equal the baseline (no leaked env)"
        bl (St.stAllocs st - St.stFrees st)

-- | A capture-free, TRULY mutually-recursive even/odd group with LITERAL base
-- cases, as a whole 'main' module. The 'Case' scrutinises the integer parameter
-- DIRECTLY (an 'AltLit 0' base + an 'AltDefault' recursive arm), so no boxed
-- Bool is ever allocated: a correct capture-free run allocates ZERO dynamic
-- cells (no 'NEnv', members inline over the static sentinel).
--
--   main = letrec even k = case k of 0 -> 1 ; _ -> odd (k-1)
--                 odd  k = case k of 0 -> 0 ; _ -> even (k-1)
--          in even <arg>
mutualLitModule :: Integer -> CoreModule
mutualLitModule arg =
  let intTy = Ty.CTCon Ty.TcU64 []
      nm h u = Name (T.pack h) (Unique u)
      bnd h u = Binder (nm h u) Unrestricted intTy
      -- distinct Uniques per binder (the machine keys env on Unique).
      nEven = nm "even" 1; nOdd = nm "odd" 2
      evenBody =
        Case (AVar (nm "ek" 3))
          [ AltLit (LInt 0) (Ret (ALit (LInt 1)))
          , AltDefault (Let (bnd "eks" 5) (RApp (primAtom (T.pack "-")) [AVar (nm "ek" 3), ALit (LInt 1)])
                          (Let (bnd "er" 6) (RApp (AVar nOdd) [AVar (nm "eks" 5)])
                            (Ret (AVar (nm "er" 6))))) ]
      oddBody =
        Case (AVar (nm "ok" 4))
          [ AltLit (LInt 0) (Ret (ALit (LInt 0)))
          , AltDefault (Let (bnd "oks" 7) (RApp (primAtom (T.pack "-")) [AVar (nm "ok" 4), ALit (LInt 1)])
                          (Let (bnd "or" 8) (RApp (AVar nEven) [AVar (nm "oks" 7)])
                            (Ret (AVar (nm "or" 8))))) ]
      body =
        LetRec [ (Binder nEven Unrestricted intTy, [bnd "ek" 3], evenBody)
               , (Binder nOdd  Unrestricted intTy, [bnd "ok" 4], oddBody) ]
          (Let (bnd "r" 9) (RApp (AVar nEven) [ALit (LInt arg)])
            (Ret (AVar (nm "r" 9))))
  in CoreModule [TopBind (nm "main" 100) [] body]

sharedEnvCaptureFreeMutual :: Assertion
sharedEnvCaptureFreeMutual = do
  let cm     = mutualLitModule 4
      pruned = pruneToReachable cm
  assertBool "non-escaping capture-free group must pass the boundary"
    (null (firstOrderNoHandlerViolations pruned))
  let instrumented = Perceus.insertRC pruned
  rc <- RCM.runModuleRC instrumented
  case (Interp.runModule pruned, rc) of
    (Right v, Right run) -> do
      let st = RCM.rcStats run
          bl = RCM.rcBaseline run
      assertEqual "value matches the reference interpreter"
        (Interp.renderValue v) (RCM.rcOutput run)   -- even 4 = 1
      assertEqual "heap empties to the immortal baseline" bl (St.stLive st)
      assertEqual "allocs - frees == baseline"
        bl (St.stAllocs st - St.stFrees st)
      -- ZERO group allocation: a capture-free group allocates no dynamic cell
      -- (no NEnv; the code label is static; literal base cases allocate no Bool).
      assertEqual "capture-free group allocates ZERO dynamic cells" 0 (St.stAllocs st)
      assertEqual "and never peaks above zero live dynamic cells" 0 (St.stPeak st)
    (refRes, rcRes) ->
      assertFailure ("both interpreters must succeed; got "
                       <> either show (const "ok") refRes <> " / "
                       <> either show (const "ok") rcRes)

-- | The sentinel collision fix: a capture-free group's @envAddr@ is the static
-- empty-env sentinel, and dereferencing it returns @NEnv Map.empty@ --- NOT the
-- first top-level bind's static cell (which 'reserveStatic' now starts at -2
-- after 'initSentinel' reserves -1).
sharedEnvSentinelIsEmptyEnv :: Assertion
sharedEnvSentinelIsEmptyEnv = do
  let s = St.initSentinel St.emptyStore
  case St.derefPure St.emptyEnvSentinelAddr s of
    Right c -> case St.cNode c of
      St.NEnv m -> assertEqual "sentinel holds the empty env" Map.empty m
      other     -> assertFailure ("sentinel must be NEnv empty, got " <> show other)
    Left err -> assertFailure ("sentinel deref failed: " <> show err)
  -- After the sentinel, the next static address is -2, so the first top-level
  -- bind (or group code label) cannot alias the sentinel slot.
  let (a, _) = St.allocStatic (St.NCon (T.pack "X") []) s
  assertBool "first post-sentinel static addr is below the sentinel" (a < St.emptyEnvSentinelAddr)

-- | A capturing, non-escaping group: two members that BOTH borrow-read one boxed
-- enclosing local @b = Box 7@ (each base case is @case b of Box v -> v@, a
-- borrow-read that keeps no boxed child). Built and HAND-INSTRUMENTED directly
-- (Perceus's letrec instrumentation is simplified in Task 4), so the group is
-- dropped by exactly ONE member-drop --- which frees the single shared 'NEnv'
-- and cascades into @b@. Asserts: exactly ONE 'NEnv' allocated (Box + env = 2
-- dynamic allocs, peak 2) and freed once (heap empties).
sharedEnvCapturingOneEnv :: Assertion
sharedEnvCapturingOneEnv = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      boxTy  = Ty.CTCon (Ty.TcUser (T.pack "Box")) []
      nm h u = Name (T.pack h) (Unique u)
      bnd h u ty = Binder (nm h u) Unrestricted ty
      nB = nm "b" 1; nF = nm "f" 2; nG = nm "g" 3
      -- base case: case b of Box v -> v   (a borrow-read of the captured b)
      baseRead vU = Case (AVar nB)
                      [ AltCon (T.pack "Box") [bnd "v" vU intTy] (Ret (AVar (nm "v" vU))) ]
      recArm selfK sib ks ksU r rU =
        Let (bnd ks ksU intTy) (RApp (primAtom (T.pack "-")) [AVar selfK, ALit (LInt 1)])
          (Let (bnd r rU intTy) (RApp (AVar sib) [AVar (nm ks ksU)])
            (Ret (AVar (nm r rU))))
      fBody = Case (AVar (nm "fk" 4))
                [ AltLit (LInt 0) (baseRead 10), AltDefault (recArm (nm "fk" 4) nG "fks" 20 "fr" 21) ]
      gBody = Case (AVar (nm "gk" 5))
                [ AltLit (LInt 0) (baseRead 11), AltDefault (recArm (nm "gk" 5) nF "gks" 22 "gr" 23) ]
      -- main = let b = Box 7
      --        letrec f k = case k of 0 -> (case b of Box v -> v) ; _ -> g (k-1)
      --               g k = case k of 0 -> (case b of Box v -> v) ; _ -> f (k-1)
      --        let r = f 2                       -- => 7 (the captured value)
      --            _ = __rc_drop f               -- ONE member-drop: frees the env, cascades b
      --        in r
      e =
        Let (bnd "b" 1 boxTy) (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec [ (Binder nF Unrestricted intTy, [bnd "fk" 4 intTy], fBody)
                  , (Binder nG Unrestricted intTy, [bnd "gk" 5 intTy], gBody) ]
            (Let (bnd "r" 6 intTy) (RApp (AVar nF) [ALit (LInt 2)])
              (Let (bnd "_d" 7 intTy) (RApp (AVar rcDropName) [AVar nF])
                (Ret (AVar (nm "r" 6))))))
      s0 = St.initSentinel St.emptyStore
  RCM.runExprRC RCP.rcPrimTable Map.empty s0 e >>= \case
    Left err -> assertFailure ("rc run failed: " <> show err)
    Right (v, s) -> do
      txt <- either (assertFailure . show) pure (St.renderRCValue s v)
      txt @?= T.pack "7"
      let st = St.stStats s
      -- Box (1) + the ONE shared NEnv (1) = exactly two dynamic allocs; nothing
      -- more (sibling calls allocate nothing, base case is a borrow-read).
      assertEqual "exactly two dynamic allocations (Box + ONE NEnv)" 2 (St.stAllocs st)
      assertEqual "peak two live dynamic cells (Box + env held together)" 2 (St.stPeak st)
      -- The single member-drop freed the env, whose cascade freed Box: heap empties
      -- (the result is the unboxed literal 7, so there is nothing further to drop).
      assertEqual "both cells freed (env + cascaded Box)" 2 (St.stFrees st)
      assertEqual "heap empty after the single group drop" 0 (St.stLive st)

-- | Partial application of a recursive member. The single-member group
--
--   f a b = case b of 0 -> a ; _ -> let b' = b - 1 ; r = f a b' in r
--
-- accumulates @a@ while counting @b@ down to 0 (so @f 10 3 = 10@). We apply it
-- PARTIALLY (@p = f 10@, one arg of two), which must build an ordinary closure
-- capturing the supplied arg + the member, then FULLY apply it (@p 3@) so the
-- closure re-enters the member's code. Non-escaping (capture-free, result is a
-- scalar), hand-instrumented: the partial closure is the only dynamic cell and
-- is dropped at the end.
sharedEnvPartialApplication :: Assertion
sharedEnvPartialApplication = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
      nm h u = Name (T.pack h) (Unique u)
      bnd h u ty = Binder (nm h u) Unrestricted ty
      nF = nm "f" 1
      fBody =
        Case (AVar (nm "fb" 3))
          [ AltLit (LInt 0) (Ret (AVar (nm "fa" 2)))
          , AltDefault
              (Let (bnd "fb1" 4 intTy) (RApp (primAtom (T.pack "-")) [AVar (nm "fb" 3), ALit (LInt 1)])
                (Let (bnd "fr" 5 intTy) (RApp (AVar nF) [AVar (nm "fa" 2), AVar (nm "fb1" 4)])
                  (Ret (AVar (nm "fr" 5))))) ]
      -- main = letrec f a b = case b of 0 -> a ; _ -> f a (b-1)
      --        let p = f 10            -- PARTIAL: na=1 < np=2 => build a closure
      --            r = p 3             -- FULL: re-enters f => 10
      --            _ = __rc_drop p     -- drop the partial closure (its only owner)
      --        in r
      e =
        LetRec [ (Binder nF Unrestricted funTy, [bnd "fa" 2 intTy, bnd "fb" 3 intTy], fBody) ]
          (Let (bnd "p" 6 funTy) (RApp (AVar nF) [ALit (LInt 10)])
            (Let (bnd "r" 7 intTy) (RApp (AVar (nm "p" 6)) [ALit (LInt 3)])
              (Let (bnd "_d" 8 intTy) (RApp (AVar rcDropName) [AVar (nm "p" 6)])
                (Ret (AVar (nm "r" 7))))))
      s0 = St.initSentinel St.emptyStore
  RCM.runExprRC RCP.rcPrimTable Map.empty s0 e >>= \case
    Left err -> assertFailure ("rc run failed: " <> show err)
    Right (v, s) -> do
      txt <- either (assertFailure . show) pure (St.renderRCValue s v)
      txt @?= T.pack "10"      -- f 10 3 accumulates a=10 down b=3..0
      let st = St.stStats s
      -- The ONLY dynamic cell is the partial-application closure; freed by its
      -- single drop. (The group code label is static; capture-free, so no NEnv.)
      assertEqual "exactly one dynamic allocation (the partial closure)" 1 (St.stAllocs st)
      assertEqual "the partial closure is freed" 1 (St.stFrees st)
      assertEqual "heap empty after dropping the partial closure" 0 (St.stLive st)

-- | Elaborate -> prune -> Perceus.insertRC -> runModuleRC a consuming-capture
-- corpus file directly (no boundary guard), and assert the heap is balanced:
-- everything born is freed and 'stLive' returns to the value-CAF baseline.
assertHeapEmpty :: FilePath -> Assertion
assertHeapEmpty path = do
  cm <- elaboratedModuleOf path
  RCM.runModuleRCUnchecked (Perceus.insertRC (pruneToReachable cm)) >>= \case
    Left err  -> assertFailure ("runModuleRCUnchecked failed: " <> show err)
    Right run -> do
      let st = RCM.rcStats run
          bl = RCM.rcBaseline run
      assertEqual "live cells must return to the value-CAF baseline (no leak)"
        bl (St.stLive st)
      assertEqual "allocs minus frees must equal the baseline (no leak)"
        bl (St.stAllocs st - St.stFrees st)

-- | Elaborate -> prune a '.wok' file, then run BOTH interpreters and assert the RC
-- run AGREES with the reference value AND is heap-balanced (allocs - frees and live
-- both return to the value-CAF baseline). Unlike 'assertHeapEmpty', the result MAY
-- be a live value CAF (an escaped closure), so it asserts balance against the
-- baseline rather than zero. The run-the-exploit check for an ACCEPTED escaping
-- shape: a wrongly-admitted escape surfaces as a 'Left' (UAF / double-free), a leak
-- (live /= baseline), or a value mismatch.
assertRcAgrees :: FilePath -> Assertion
assertRcAgrees path = do
  cm <- elaboratedModuleOf path
  let pruned = pruneToReachable cm
  rc <- RCM.runModuleRCUnchecked (Perceus.insertRC pruned)
  case (Interp.runModule pruned, rc) of
    (Right v, Right run) -> do
      Interp.renderValue v @?= RCM.rcOutput run
      let st = RCM.rcStats run
          bl = RCM.rcBaseline run
      assertEqual "live cells must return to the value-CAF baseline (no leak)"
        bl (St.stLive st)
      assertEqual "allocs minus frees must equal the baseline (no leak)"
        bl (St.stAllocs st - St.stFrees st)
    -- BOTH interpreters failing is AGREEMENT (the RC pass did not DIVERGE from the
    -- reference): e.g. a shape that hits a shared evaluator limitation such as a
    -- record-pattern match on a call result ('NonExhaustiveCase' in both). The RC
    -- soundness claim is "RC agrees with the reference", not "the program runs". A
    -- one-sided failure (a UAF / double-free / leak in the RC run only) is the real
    -- soundness fault and still fails loudly.
    -- BOTH interpreters failing is AGREEMENT ONLY when they fail the SAME WAY: a
    -- shared evaluator limitation (e.g. a record-pattern match on a call result =>
    -- 'NonExhaustiveCase' in both). It is NOT a free pass. An RC memory-safety
    -- fault (double-free / use-after-free / dangling --- a 'PrimError' the
    -- reference interpreter, having no store, can NEVER produce) is a real
    -- one-sided soundness fault and MUST fail loudly even when the reference also
    -- errored; otherwise a future RC double-free could hide behind an unrelated
    -- reference failure (and recall a freed-env UAF surfaces as 'UnboundVar', which
    -- looks innocuous). So: reject any RC memory-safety fault outright, then require
    -- the two failures to share a constructor (payload text differs by design).
    (Left refE, Left rcE)
      | rcMemSafetyFault rcE ->
          assertFailure ("RC memory-safety fault hidden behind a reference failure (" <> path
                           <> "): rc=" <> show rcE <> " ref=" <> show refE)
      | errCtorTag refE == errCtorTag rcE -> pure ()
      | otherwise ->
          assertFailure ("RC failure DIVERGES from the reference failure --- a possible one-sided RC \
                         \fault (" <> path <> "): ref=" <> show refE <> " rc=" <> show rcE)
    (refRes, rcRes) ->
      assertFailure ("RC run must AGREE with the reference (both succeed or both fail); got ref="
                       <> either show (const "ok") refRes <> " rc="
                       <> either show (const "ok") rcRes)

-- | True iff @e@ is an RC STORE memory-safety / store-internal fault --- a
-- double-free, a use-after-free, a drop of a dangling/never-allocated address, OR
-- an RC-store-only structural invariant break (an env-handle whose backing cell is
-- not an 'NEnv', or any "internal:" machine message). These are all 'PrimError's
-- the reference interpreter (which has NO reference-counted store) can never raise,
-- so their presence on the RC side is ALWAYS a real one-sided soundness fault, even
-- when the reference also failed for an unrelated reason --- they must never launder
-- past 'errCtorTag' agreement in a both-fail branch.
--
-- The matched fragments are EXACTLY the store-only 'PrimError' messages emitted in
-- "src/Wok/Interp/RC/Value.hs" (drop/incref store guards) and
-- "src/Wok/Interp/RC/Machine.hs" ("RVRecMember env addr is not NEnv", "internal:"
-- machine invariants). We deliberately do NOT match the SHARED type-confusion
-- PrimErrors ("expected U64" / "expected Bool" / "division by zero" / "rc M1:
-- effects not supported"): those describe a value-level limitation the store-less
-- reference can also hit, so treating them as RC-only would risk a false failure.
--
-- RESIDUAL (cannot be closed without false failures): a freed-env use-after-free
-- can also surface as a plain 'IV.UnboundVar' (the env slot is gone, so the member
-- lookup misses) rather than a store 'PrimError'. 'UnboundVar' is a legitimate
-- reference-interpreter error too, so classifying it here would reject genuine
-- both-fail agreement (a real false failure). It is therefore left UNCAUGHT by this
-- predicate; the heap-balance assertions in 'assertRcAgrees' / 'prop_m2a1Escape' are
-- the backstop for that UAF shape on the accepting path (a freed-env leak shows as
-- live /= baseline), and the boundary fences keep the unsound shapes out entirely.
rcMemSafetyFault :: IV.RuntimeError -> Bool
rcMemSafetyFault (IV.PrimError m) =
  any (`T.isInfixOf` m)
    [ T.pack "double-free", T.pack "use-after-free", T.pack "dangling"
    , T.pack "is not NEnv", T.pack "internal:"
    -- M2b: the resume move-out faults (a continuation handle applied to a freed/
    -- non-continuation address). The rc/=1 one-shot-violation message already
    -- starts with "internal:"; this covers the non-NCont case.
    , T.pack "resume of non-continuation" ]
rcMemSafetyFault _ = False

-- | The constructor tag of a 'RuntimeError', ignoring its payload text (which
-- differs by design between the reference and RC interpreters). Two failures
-- that share a tag are the SAME class of error (genuine agreement).
errCtorTag :: IV.RuntimeError -> Text
errCtorTag e = case e of
  IV.UnboundVar{}        -> T.pack "UnboundVar"
  IV.UnboundPrim{}       -> T.pack "UnboundPrim"
  IV.NotAFunction{}      -> T.pack "NotAFunction"
  IV.NonExhaustiveCase{} -> T.pack "NonExhaustiveCase"
  IV.NoMatchingHandler{} -> T.pack "NoMatchingHandler"
  IV.BadProjection{}     -> T.pack "BadProjection"
  IV.PrimError{}         -> T.pack "PrimError"
  IV.ArityError{}        -> T.pack "ArityError"
  IV.UnsupportedCaf{}    -> T.pack "UnsupportedCaf"
  IV.OneShotViolation{}  -> T.pack "OneShotViolation"

-- ---------------------------------------------------------------------------
-- Suite A: differential run over the no-handler / first-order corpus (Task 8)
--
-- For each program in test/rc-examples/, run BOTH interpreters in the same test:
--
--   * the REFERENCE interpreter on the ORIGINAL (pre-Perceus) ANF
--       (Interp.runModule -> Interp.renderValue), and
--   * the RC interpreter on the Perceus-INSTRUMENTED ANF
--       (Machine.runModuleRC . Perceus.insertRC -> rcOutput).
--
-- dup/drop never change values, so the two rendered outputs must be
-- byte-identical. Because the RC interpreter is an INDEPENDENT implementation,
-- this is a genuine differential signal (a bug in either side surfaces as a
-- divergence rather than hiding identically in both).
--
-- Error path: we compare SUCCESS outputs. If BOTH sides return 'Left' we treat
-- it as a match WITHOUT comparing the error text -- the RC and reference error
-- renderings differ by design (different RuntimeError constructors / messages).
-- A one-sided failure is a real divergence and fails the test.
--
-- RC scope guard: the RC interpreter supports the handler-free fragment
-- (closures included, as of M1.5). We reject any corpus program whose CODE
-- REACHABLE FROM 'main' contains a handler/operation ('Handle'/'ROp' -- effects
-- are M2). We scope the check to the reachable call graph rather than the whole
-- elaborated module on purpose: 'elaborateProgramFull' inlines the entire
-- prelude (which DOES contain handlers), but none of it is reached by a
-- handler-free corpus 'main', so it never executes on the RC store.

rcDifferentialHarness :: FilePath -> Assertion
rcDifferentialHarness path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s   -> assertFailure ("elaborate: " <> s)
        Right cm -> do
          -- RC scope guard: reject handlers / operations ('Handle'/'ROp')
          -- anywhere in the code reachable from 'main' (closures are admitted).
          case firstOrderNoHandlerViolations cm of
            [] -> pure ()
            vs -> assertFailure
              (path <> ": not a handler-free program (Handle/ROp out of scope):\n"
                 <> unlines (map T.unpack vs))
          -- Prune to the binds reachable from 'main' before running. This is a
          -- semantics-preserving dead-bind elimination: a top-level bind never
          -- reached from 'main' cannot affect main's result. We prune for BOTH
          -- interpreters so they execute byte-identical programs. It is REQUIRED
          -- for the RC interpreter: 'runModuleRC' force-evaluates every value-CAF
          -- eagerly at load time, whereas 'elaborateProgramFull' inlines the whole
          -- prelude (incl. dictionary CAFs that bottom out in prims the RC store
          -- does not bind); pruning drops those unreached CAFs so only the
          -- first-order corpus actually runs.
          let pruned = pruneToReachable cm
              refRes = Interp.runModule pruned
          -- FBIP reuse-pairing AFTER insertRC; the differential below asserts the
          -- RC output equals the reference output bit-for-bit (reuse never changes
          -- the value, only the allocation count).
          rcRes <- RCM.runModuleRC (reusePairing (Perceus.insertRC pruned))
          case (refRes, rcRes) of
            (Right v, Right run) ->
              Interp.renderValue v @?= RCM.rcOutput run
            (Left _, Left _) ->
              -- Both failed: a match by design (error text differs between the
              -- reference and RC interpreters; we do not compare it).
              pure ()
            (Right v, Left rerr) ->
              assertFailure
                ( "divergence: reference SUCCEEDED ("
                    <> T.unpack (Interp.renderValue v)
                    <> ") but RC interpreter FAILED: " <> show rerr )
            (Left rerr, Right run) ->
              assertFailure
                ( "divergence: reference FAILED (" <> show rerr
                    <> ") but RC interpreter SUCCEEDED ("
                    <> T.unpack (RCM.rcOutput run) <> ")" )

-- ---------------------------------------------------------------------------
-- Suite E: deep-list recursive-drop at scale (Task 11)
--
-- The corpus carries a small (N == 8) deep-list program at
-- 'test/rc-examples/16-deep-list.wok', which is golden-pinned and runs through
-- Suites A/B/D like every other corpus file. This dedicated harness additionally
-- runs a LARGE (N == 50000) variant --- kept out of the auto-discovered corpus
-- so it is not golden-pinned --- end-to-end through the WHOLE pipeline
-- (elaborate -> Perceus insertRC -> runModuleRC) and asserts the exact heap
-- accounting for a freshly built, fully consumed spine of length N:
--
--   NOTE: since Slice 2, 'Nil' (nullary) is an 'Inline' immediate with ZERO heap
--   cells, so the counts are N (not N + 1):
--
--   * frees    == N  (N 'Cons' shells reclaimed; 'Nil' is now inline, no cell),
--   * allocs   == N  (only the Cons spine is allocated; baseline == 0),
--   * peakLive == N  (the whole Cons spine is live before it is consumed),
--   * stLive   == 0  (heap-empty at exit).
--
-- Reaching 'frees == N' at this scale proves the RC store's drop is ITERATIVE
-- (a worklist, not host recursion): a recursive drop of a 50000-cell spine would
-- otherwise overflow the Haskell stack. This is the same property as the
-- Store-level unit test in 'rc drop', but exercised end-to-end through the
-- '__rc_drop' calls the Perceus pass actually inserts.

rcDeepListTests :: TestTree
rcDeepListTests = testGroup "rc deep-list"
  [ testCase ("frees == N + 1 at scale (N = " <> show deepListN <> ")") $ do
      instrumented <- rcStatsPrepare "test/rc-deep-list/scale.wok"
      RCM.runModuleRC instrumented >>= \case
        Left rerr -> assertFailure ("RC interpreter failed: " <> show rerr)
        Right run -> do
          let st       = RCM.rcStats run
              baseline = RCM.rcBaseline run
              -- Nil is now Inline (zero heap cells), so only N Cons cells are
              -- allocated and freed (not N + 1).
              expected = deepListN
          assertEqual "this program retains no global baseline"
            0 baseline
          assertEqual "frees must equal N (every Cons cell reclaimed; Nil is inline)"
            expected (St.stFrees st)
          assertEqual "allocs must equal N (only the Cons spine is allocated)"
            expected (St.stAllocs st)
          assertEqual "peakLive must equal N (whole Cons spine live before consume)"
            expected (St.stPeak st)
          assertEqual "stLive must be 0 at exit (heap-empty)"
            0 (St.stLive st)
  ]
  where
    deepListN :: Int
    deepListN = 50000

-- ---------------------------------------------------------------------------
-- C-backend differential oracle (Task 3): the abstract heap is the trusted
-- reference; the C heap is the new implementation under test. For the WHOLE
-- in-scope corpus we run the SAME prepared module through both backends and
-- assert byte-identical observable behaviour:
--
--   * 'rcOutput'  (the rendered result) is byte-identical, and
--   * the four heap-accounting numbers ('stAllocs'/'stFrees'/'stPeak', plus the
--     'stLive == rcBaseline' baseline invariant) agree.
--
-- Allocation-stat parity is the load-bearing signal: the abstract and C heaps
-- share ONE 'recordAlloc'/'recordFree' so equal counts mean the C path took the
-- same alloc/free decisions on the same cells (no silent leak, no over-free).
-- Both backends see the same Perceus-instrumented program, so a divergence is a
-- backend bug, not a dup/drop placement difference.
--
-- The harness reuses the differential/stats front end EXACTLY (load -> elaborate
-- -> 'firstOrderNoHandlerViolations' scope guard -> 'pruneToReachable' ->
-- 'Perceus.insertRC'), so the parity group compares like with like over the same
-- in-scope programs the abstract corpus groups already run.

-- | Shared front end for the C-backend parity group: load -> elaborate -> M1
-- scope guard -> prune-to-reachable -> insertRC, identical to 'rcStatsPrepare'
-- and the differential harness so the parity comparison runs the same program.
rcParityPrepare :: FilePath -> IO Anf.CoreModule
rcParityPrepare = rcStatsPrepare

-- | The C-backend differential oracle over the whole in-scope corpus. For each
-- program, run the prepared module through BOTH the abstract heap and a fresh C
-- heap and assert output + allocation-stat parity, plus the C run's heap-empty
-- baseline invariant. The C heap is created and freed per program so each runs
-- on a clean allocator (the post-run 'stLive == rcBaseline' check still holds
-- for CAF-baseline programs; 'wokHeapFree' may emit a cosmetic stderr "live
-- cells" note for those immortal cells, which is expected and not a failure).
rcCBackendParity :: [FilePath] -> TestTree
rcCBackendParity files = testGroup "rc-c-backend-parity"
  [ testCase (takeBaseName f) (rcParityHarness f)
  | f <- files
  ]

-- | The single shared core for BOTH C-backend groups: prepare the module, run it
-- through the abstract heap, then through a FRESH C heap, read the C heap's OWN
-- allocation counter ('Heap.wokStatAllocs') and peak-bytes counter
-- ('Heap.wokStatPeakBytes') BEFORE freeing it, and return the raw
-- @(abstractResult, cResult, cHeapAllocs, cPeakBytes)@. The C heap is freed via
-- 'finally' so a thrown exception during the C run cannot leak the 'Ptr WokHeap';
-- the counters are read before the free on the success path.
withBothBackends
  :: FilePath
  -> IO ( Either IV.RuntimeError RCM.RCRun
        , Either IV.RuntimeError RCM.RCRun
        , Word64
        , Word64 )
withBothBackends path = do
  cm   <- rcParityPrepare path
  absR <- RCM.runModuleRCWith St.AbstractHeap cm
  hp   <- Heap.wokHeapNew
  (cR, cAllocs, cPeakBytes) <-
    (do c  <- RCM.runModuleRCWith (St.CHeap hp) cm
        a  <- Heap.wokStatAllocs hp
        pb <- Heap.wokStatPeakBytes hp
        pure (c, a, pb))
    `Control.Exception.finally` Heap.wokHeapFree hp
  pure (absR, cR, cAllocs, cPeakBytes)

-- | FFI Slice 3 Task 5: run a borrow program through BOTH backends and assert the
-- foreign-borrow close count equals @expected@ on each. CHeap performs the real
-- @free@ (ASan-checked separately via scripts/asan-runtime.sh); AbstractHeap counts
-- the same N. Pinning the absolute count (not just abstract == C parity) catches a
-- regression where the close silently stops firing on both backends.
rcBorrowCloseCount :: FilePath -> Int -> Assertion
rcBorrowCloseCount path expected = do
  (absR, cR, _cAllocs, _cPeakBytes) <- withBothBackends path
  case (absR, cR) of
    (Right a, Right c) -> do
      assertEqual (path <> ": closes (AbstractHeap)")
        expected (St.stCloses (RCM.rcStats a))
      assertEqual (path <> ": closes (CHeap)")
        expected (St.stCloses (RCM.rcStats c))
    (Left e, _) -> assertFailure (path <> ": abstract backend FAILED: " <> show e)
    (_, Left e) -> assertFailure (path <> ": C backend FAILED: " <> show e)

-- | FFI Slice 3 Task 6 (death-test matrix, compile-reject half). Type-check a
-- `death-*.wok` Borrow-escape program in the NORMAL build and assert it is
-- rejected with a CarrierEscape. This is vacuity-guard step 1: the EXACT program
-- scripts/asan-runtime.sh later runs under the `ffi-borrow-noescape-negctrl`
-- mutation to produce a genuine ASan use-after-free is, without the mutation,
-- a compile-time rejection. If a death file ever type-checked here it would mean
-- the carrier rule had a hole on that route -- a soundness regression.
borrowDeathCompileRejects :: FilePath -> Assertion
borrowDeathCompileRejects path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure (path <> ": loader error: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.typecheckProgram entryName ms of
        Left msg
          | T.pack "CarrierEscape" `T.isInfixOf` T.pack msg -> pure ()
          | otherwise -> assertFailure
              (path <> ": expected CarrierEscape, got: " <> msg)
        Right _ -> assertFailure
          (path <> ": expected a compile-time CarrierEscape rejection, but it type-checked")

-- | FFI Slice 4 Task 1 (owned-arg coherence, compile-reject half). Type-check a
-- `foreign module` fixture and assert it is rejected with the given TypeError
-- CONSTRUCTOR (matched by name in the pipeline's rendered error string, exactly
-- as 'borrowDeathCompileRejects' matches "CarrierEscape"). These pin the
-- soundness-critical surface-`owned` <=> blessed-`MoveOut` invariant the Slice 4
-- Task 4 router relies on; without a committed test a refactor could silently
-- drop a rejection (Tasks 5/6 only exercise runtime behavior, never these
-- compile-time gates).
ffiOwnedCoherenceRejects :: FilePath -> String -> Assertion
ffiOwnedCoherenceRejects path expectedCon = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure (path <> ": loader error: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.typecheckProgram entryName ms of
        Left msg
          | T.pack expectedCon `T.isInfixOf` T.pack msg -> pure ()
          | otherwise -> assertFailure
              (path <> ": expected " <> expectedCon <> ", got: " <> msg)
        Right _ -> assertFailure
          (path <> ": expected a compile-time " <> expectedCon
                <> " rejection, but it type-checked")

-- | FFI Slice 4 Task 1 (owned-arg coherence, POSITIVE case). The dual of
-- 'ffiOwnedCoherenceRejects': a fixture whose surface `owned` markers agree with
-- the blessed `MoveOut` list must type-check cleanly. Pins that the coherence
-- checks are not over-eager (a well-formed `owned Bytes` sink still passes).
ffiOwnedCoherenceAccepts :: FilePath -> Assertion
ffiOwnedCoherenceAccepts path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure (path <> ": loader error: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.typecheckProgram entryName ms of
        Right _  -> pure ()
        Left msg -> assertFailure
          (path <> ": expected a clean type-check, but was rejected: " <> msg)

-- ---------------------------------------------------------------------------
-- FFI Slice 4 Task 5: owned-INTO-C move-out router, QuickCheck properties
-- (P1-P7) over RANDOM 'Bytes' contents.
--
-- The Task 4 corpus ('test/rc-ffi-owned/00-consume-unique.wok' and
-- '01-consume-shared.wok') pins the MOVE and COPY router branches on ONE fixed
-- byte string ([65, 66, 67]). This suite reuses those exact two program
-- SHAPES -- templatized over the byte contents -- and drives them through the
-- SAME three-backend oracle ('rcDifferentialHarness' + 'withBothBackends')
-- per QuickCheck iteration, over randomly generated 'Bytes'.
--
-- MECHANISM: 'Wok.Loader.loadProgram' only reads source from disk, so each
-- iteration spools the templatized source to a scratch temp file, runs it
-- through load -> elaborate -> M1 scope guard -> prune -> (reference
-- interpreter on the pre-Perceus ANF) and (Perceus insertRC + reusePairing on
-- RC-abstract and RC-CHeap), and removes the temp file. This is the SAME
-- front end 'rcDifferentialHarness'/'withBothBackends' use on the fixed
-- corpus, just parameterized by a source string instead of a corpus path.
-- ---------------------------------------------------------------------------

-- | A sized length distribution spanning empty, small, and multi-KB 'Bytes'
-- contents, so the corpus exercises the router's MOVE/COPY branches (which
-- don't care about size) alongside the CHeap allocator's small-vs-large paths.
genFfiOwnedBytesLen :: Gen Int
genFfiOwnedBytesLen = QC.frequency
  [ (2, pure 0)
  , (5, QC.choose (1, 32))
  , (3, QC.choose (33, 512))
  , (2, QC.choose (513, 4096))
  ]

-- | The property generator: a random byte string spanning empty/small/multi-KB.
-- Each byte is drawn via 'QC.choose' (uniform over the FULL 0..255 range,
-- independent of QuickCheck's internal "size" parameter) rather than
-- 'QC.arbitrary' (whose 'Word8' instance scales its range with size, so
-- early/small-size iterations would otherwise skew heavily toward 0/1 and
-- never exercise the full byte-value domain).
genFfiOwnedBytes :: Gen [Word8]
genFfiOwnedBytes = do
  n <- genFfiOwnedBytesLen
  QC.vectorOf n (QC.choose (0, 255 :: Word8))

-- | Render a byte list as a wok @[U64]@ literal body (no brackets), matching
-- the corpus files' @fromList [65, 66, 67]@ shape.
ffiOwnedRenderBytes :: [Word8] -> String
ffiOwnedRenderBytes = intercalate ", " . map show

-- | The @module Main@ / @import Bytes@ / @foreign module Sink@ preamble
-- shared by every generated template, verbatim from the Task 4 corpus files.
ffiOwnedPreamble :: [String]
ffiOwnedPreamble =
  [ "module Main"
  , "import Bytes"
  , ""
  , "foreign module Sink \"wok\" where"
  , "  consume \"consume\" : owned Bytes -> U64 with IO"
  , ""
  ]

-- | The UNIQUE (move) template, parameterized by byte contents. Mirrors
-- 'test/rc-ffi-owned/00-consume-unique.wok': the freshly built 'Bytes' is
-- consumed as its ONLY use, so Perceus emits no dup -> rc==1 at the call ->
-- the router MOVES (frees the buffer once, 0 copy bytes). The rendered result
-- IS the checksum.
ffiOwnedUniqueSource :: [Word8] -> String
ffiOwnedUniqueSource bs = unlines $ ffiOwnedPreamble ++
  [ "main : U64"
  , "main = Sink.consume (fromList [" <> ffiOwnedRenderBytes bs <> "])"
  ]

-- | The SHARED (copy) template, parameterized by byte contents. Mirrors
-- 'test/rc-ffi-owned/01-consume-shared.wok': 'b' is consumed AND read again
-- (@length b@), so Perceus dups it before the consume -> rc>1 at the call ->
-- the router COPIES. When 'bs' is non-empty we also read byte 0 of 'b' AFTER
-- the consume (the P4 non-interference check); which arm to emit is decided
-- in HASKELL (not a wok @if@) to keep the surface syntax to what the corpus
-- already uses. The rendered result is @checksum + length b (+ byte 0)@.
ffiOwnedSharedSource :: [Word8] -> String
ffiOwnedSharedSource bs = unlines $ ffiOwnedPreamble ++
  [ "main : U64"
  , "main ="
  , "  let b = fromList [" <> ffiOwnedRenderBytes bs <> "] in"
  , "  let h = Sink.consume b in"
  , "  let n = length b in"
  ] ++
  ( if null bs
      then [ "  h + n" ]
      else [ "  let x = index b 0 in"
           , "  h + n + x"
           ]
  )

-- | The N-ARY independent-unique-consumes template for P7: 'n' separate
-- 'Bytes' literals (never aliased), each consumed exactly once (each its own
-- MOVE), summed. Every summand is expected to equal @referenceFNV1a bs@.
ffiOwnedMultiUniqueSource :: Int -> [Word8] -> String
ffiOwnedMultiUniqueSource n bs = unlines $ ffiOwnedPreamble ++
  [ "main : U64"
  , "main ="
  ] ++
  [ "  let c" <> show i <> " = Sink.consume (fromList [" <> ffiOwnedRenderBytes bs <> "]) in"
  | i <- [0 .. n - 1]
  ] ++
  [ "  " <> intercalate " + " [ "c" <> show i | i <- [0 .. n - 1] ] ]

-- | The pure Haskell oracle for the UNIQUE template's rendered checksum.
ffiOwnedExpectedChecksum :: [Word8] -> Word64
ffiOwnedExpectedChecksum bs = FM.referenceFNV1a (BS.pack bs)

-- | @0@ for an empty buffer, else the first byte (widened to 'Integer') --
-- the P4/P3 templates' @index b 0@ term.
ffiOwnedFirstByte :: [Word8] -> Integer
ffiOwnedFirstByte []       = 0
ffiOwnedFirstByte (b0 : _) = toInteger b0

-- | Parse a rendered U64 (a plain decimal 'Text') back into an 'Integer'.
-- MUST be 'Integer', not 'Word64': the interpreter's arithmetic prims
-- ('Wok.Interp.Prim.arith' / 'Wok.Interp.RC.Prim.arith') operate on
-- unbounded @Integer -> Integer -> Integer@, i.e. wok's \"U64\" @+@ does NOT
-- wrap modulo 2^64 the way Haskell's 'Word64' does. Summing several 64-bit
-- FNV-1a checksums (P7) or adding a checksum to a small length/byte (P3/P4)
-- can genuinely exceed 'maxBound :: Word64'; reading such a value back into a
-- 'Word64' would silently wrap (GHC's 'Read' instance reduces mod 2^64) and
-- desync from wok's true unbounded result. 'Integer' has no such ceiling.
-- 'read' is partial (a bare 'Prelude.read: no parse' on any unparseable
-- 'Text' gives no indication of the offending string or which property
-- caller hit it). Parse via 'readMaybe' and fail LOUD with a labeled message
-- naming the unparseable text on the 'Nothing' branch, mirroring the
-- 'ffiOwnedExpectRight' idiom used throughout this group: both run inside
-- 'QC.ioProperty' 'IO' actions, so an 'assertFailure' here fails the
-- property with a clear counterexample instead of throwing an opaque
-- 'Prelude.read' parse-error exception.
ffiOwnedReadInteger :: String -> Text -> IO Integer
ffiOwnedReadInteger label t = case readMaybe (T.unpack t) of
  Just n  -> pure n
  Nothing -> assertFailure
    (label <> ": unparseable Integer: " <> show t)

-- | Unwrap a backend result inside the property's 'IO', or fail the property
-- with a labeled message (mirrors the @Left lerr -> assertFailure@ idiom used
-- throughout the corpus harnesses above, generalized to any labeled 'Either').
ffiOwnedExpectRight :: Show e => String -> Either e a -> IO a
ffiOwnedExpectRight label = either (\e -> assertFailure (label <> ": FAILED: " <> show e)) pure

-- | The three-backend result of running ONE generated program: the pure
-- reference interpreter's rendered output (pre-Perceus ANF), the RC-abstract
-- run, the RC-CHeap run, and the CHeap's own allocation counter (read before
-- the CHeap is freed, exactly as 'withBothBackends' does). We capture the
-- alloc COUNT (not peak bytes) because P6 pins the router's move-vs-copy signal
-- as an alloc-count delta -- see 'prop_ffiOwnedZeroCopySaving' for why peak
-- bytes is unusable here.
data FfiOwnedRun = FfiOwnedRun
  { forRef        :: Either IV.RuntimeError Text
  , forAbs        :: Either IV.RuntimeError RCM.RCRun
  , forC          :: Either IV.RuntimeError RCM.RCRun
  , forCAllocs    :: Word64
  }

-- | Run one property-generated wok SOURCE STRING through the full three-backend
-- oracle. Spools 'src' to a scratch temp file for the duration of the run (only
-- 'Loader.loadProgram' needs disk; everything downstream is in-memory), removing
-- it afterward via 'Control.Exception.finally' so a thrown exception mid-run
-- cannot leak the scratch file. Mirrors 'rcDifferentialHarness' +
-- 'withBothBackends' EXACTLY: load -> elaborate -> M1 scope guard -> prune ->
-- (reference interpreter on the pruned pre-Perceus ANF) and (Perceus insertRC +
-- reusePairing, run on AbstractHeap then a fresh CHeap).
runFfiOwnedSource :: String -> IO FfiOwnedRun
runFfiOwnedSource src = do
  u <- newUnique
  let path = "test/.interp-tmp-" <> show (hashUnique u) <> ".wok"
  writeFile path src
  Control.Exception.finally (runFfiOwnedPath path) (removeFileIfExists path)

-- 'runFfiOwnedPath' deliberately does NOT go through 'withBothBackends' /
-- 'rcStatsPrepare': this suite needs the pre-Perceus (reference-interpreter)
-- module AND the Perceus-instrumented module TOGETHER in one 'FfiOwnedRun'
-- (P1/P3 compare the reference output against both RC backends), and no
-- existing helper exposes that pair -- 'withBothBackends' only returns the
-- two RC-backend results, and 'rcStatsPrepare' only prepares the
-- instrumented module. So this mirrors 'rcDifferentialHarness' +
-- 'withBothBackends' inline rather than sharing either. A real shared
-- helper (returning reference + instrumented together) would be a larger
-- refactor touching both call sites; left as a documented follow-up, not
-- done here.
runFfiOwnedPath :: FilePath -> IO FfiOwnedRun
runFfiOwnedPath path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure (path <> ": loader: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s   -> assertFailure (path <> ": elaborate: " <> s)
        Right cm -> do
          case firstOrderNoHandlerViolations cm of
            [] -> pure ()
            vs -> assertFailure
              (path <> ": not a handler-free program (Handle/ROp out of scope):\n"
                 <> unlines (map T.unpack vs))
          let pruned = pruneToReachable cm
              refRes = case Interp.runModule pruned of
                         Left e  -> Left e
                         Right v -> Right (Interp.renderValue v)
              instrumented = reusePairing (Perceus.insertRC pruned)
          absR <- RCM.runModuleRCWith St.AbstractHeap instrumented
          hp   <- Heap.wokHeapNew
          (cR, cAllocs) <-
            (do c  <- RCM.runModuleRCWith (St.CHeap hp) instrumented
                a  <- Heap.wokStatAllocs hp
                pure (c, a))
            `Control.Exception.finally` Heap.wokHeapFree hp
          pure (FfiOwnedRun refRes absR cR cAllocs)

-- | The paired result of running BOTH router-branch templates on the same
-- random 'bs' -- shared by every property below so each random sample only
-- pays the compile+run cost once per template.
data FfiOwnedTrial = FfiOwnedTrial
  { fotUnique :: FfiOwnedRun
  , fotShared :: FfiOwnedRun
  }

runFfiOwnedTrial :: [Word8] -> IO FfiOwnedTrial
runFfiOwnedTrial bs = do
  u <- runFfiOwnedSource (ffiOwnedUniqueSource bs)
  s <- runFfiOwnedSource (ffiOwnedSharedSource bs)
  pure (FfiOwnedTrial u s)

-- | P1: 'consume'\'s checksum is identical across the pure reference
-- interpreter, RC-abstract, and RC-CHeap -- on BOTH router branches (the
-- unique/MOVE template's output IS the checksum; the shared/COPY template's
-- output is @checksum + length + byte0@, so backend agreement there still
-- pins backend-parity of the router's COPY-branch checksum contribution).
prop_ffiOwnedBackendParity :: Property
prop_ffiOwnedBackendParity =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      trial <- runFfiOwnedTrial bs
      pu <- parityOf "unique(MOVE)" (fotUnique trial)
      ps <- parityOf "shared(COPY)" (fotShared trial)
      pure (QC.conjoin [pu, ps])
  where
    parityOf label run = do
      refText <- ffiOwnedExpectRight (label <> ": reference interpreter") (forRef run)
      absRun  <- ffiOwnedExpectRight (label <> ": RC-abstract") (forAbs run)
      cRun    <- ffiOwnedExpectRight (label <> ": RC-CHeap") (forC run)
      let absText = RCM.rcOutput absRun
          cText   = RCM.rcOutput cRun
          ok      = refText == absText && absText == cText
      pure $ QC.counterexample
        (label <> ": backend divergence -- ref=" <> T.unpack refText
          <> " abstract=" <> T.unpack absText <> " cheap=" <> T.unpack cText)
        ok

-- | P2: the unique(MOVE) template's checksum equals the pure Haskell
-- 'referenceFNV1a' oracle -- the RIGHT value, not merely agreement across
-- backends (which P1 already covers).
prop_ffiOwnedSemanticChecksum :: Property
prop_ffiOwnedSemanticChecksum =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      run    <- runFfiOwnedSource (ffiOwnedUniqueSource bs)
      absRun <- ffiOwnedExpectRight "unique(MOVE) RC-abstract" (forAbs run)
      let expected = T.pack (show (ffiOwnedExpectedChecksum bs))
          got      = RCM.rcOutput absRun
      pure $ QC.counterexample
        ("unique(MOVE) checksum: got=" <> T.unpack got
          <> " expected(referenceFNV1a bs)=" <> T.unpack expected)
        (got == expected)

-- | P3: the router's MOVE branch and COPY branch yield the IDENTICAL checksum
-- for the same input -- the branch taken is an implementation detail, never
-- observable in the result. We isolate the COPY branch's checksum
-- contribution ALGEBRAICALLY (subtracting the deterministic @length + byte0@
-- terms, known independent of the checksum) and compare it against the
-- OBSERVED unique(MOVE) checksum -- not the Haskell oracle -- so this pins
-- router self-consistency independent of 'referenceFNV1a' correctness (P2's
-- job).
--
-- NOTE (redundancy, intentionally kept): this property is algebraically
-- IMPLIED by P2 (@prop_ffiOwnedSemanticChecksum@: unique(MOVE) checksum ==
-- the 'referenceFNV1a' oracle) conjoined with P4
-- (@prop_ffiOwnedCopyFidelity@: shared(COPY) total - oracle ==
-- @length + byte0@) -- substituting P2's equality into P4's gives exactly
-- this property's assertion. It is not a bug; it is deliberate redundant
-- coverage kept as an INDEPENDENT cross-check that does not route through
-- the Haskell oracle at all (see the paragraph above). Do not delete it as
-- "redundant" without first checking this note -- P2 and P4 are each
-- independently load-bearing and neither alone subsumes what P3 checks.
prop_ffiOwnedBranchInvariance :: Property
prop_ffiOwnedBranchInvariance =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      trial <- runFfiOwnedTrial bs
      uAbs <- ffiOwnedExpectRight "unique(MOVE) RC-abstract" (forAbs (fotUnique trial))
      sAbs <- ffiOwnedExpectRight "shared(COPY) RC-abstract" (forAbs (fotShared trial))
      let uChecksumText = RCM.rcOutput uAbs
          sTotalText     = RCM.rcOutput sAbs
          extra          = toInteger (length bs) + ffiOwnedFirstByte bs
      uChecksum <- ffiOwnedReadInteger "P3 unique(MOVE) checksum" uChecksumText
      let expectedShared = T.pack (show (uChecksum + extra))
      pure $ QC.counterexample
        ("branch invariance: unique(MOVE) checksum=" <> T.unpack uChecksumText
          <> " shared(COPY) total=" <> T.unpack sTotalText
          <> " expected(from unique checksum + length + byte0)=" <> T.unpack expectedShared)
        (sTotalText == expectedShared)

-- | P4: copy-fidelity / non-interference. In the shared(COPY) template, the
-- ORIGINAL 'b' must still read correctly (both its length and its first byte)
-- AFTER the consume that copied it out. We derive the observed
-- @length + byte0@ contribution by subtracting the KNOWN-CORRECT oracle
-- checksum (not the observed one, unlike P3 -- this property targets the
-- length/byte-read fidelity specifically, assuming P2 already pins the
-- checksum) from the shared template's total, and compare it against the
-- Haskell-computed @length bs (+ bs !! 0)@.
prop_ffiOwnedCopyFidelity :: Property
prop_ffiOwnedCopyFidelity =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      run    <- runFfiOwnedSource (ffiOwnedSharedSource bs)
      absRun <- ffiOwnedExpectRight "shared(COPY) RC-abstract" (forAbs run)
      sTotal <- ffiOwnedReadInteger "P4 shared(COPY) total" (RCM.rcOutput absRun)
      let oracle              = toInteger (ffiOwnedExpectedChecksum bs)
          observedLenPlusByte = sTotal - oracle
          expectedLenPlusByte = toInteger (length bs) + ffiOwnedFirstByte bs
      pure $ QC.counterexample
        ("copy-fidelity (original still readable after COPY): observed(length+byte0)="
          <> show observedLenPlusByte <> " expected=" <> show expectedLenPlusByte
          <> " (total=" <> show sTotal <> " oracleChecksum=" <> show oracle <> ")")
        (observedLenPlusByte == expectedLenPlusByte)

-- | P5: heap-accounting balance on BOTH RC backends, for BOTH router
-- branches: 'stLive' returns to the immortal baseline and
-- @stAllocs - stFrees == baseline@ -- no leak, no double-free, on either the
-- MOVE or the COPY path, for any random 'bs'.
prop_ffiOwnedAccountingBalance :: Property
prop_ffiOwnedAccountingBalance =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      trial <- runFfiOwnedTrial bs
      pu <- balanceOf "unique(MOVE)" (fotUnique trial)
      ps <- balanceOf "shared(COPY)" (fotShared trial)
      pure (QC.conjoin [pu, ps])
  where
    balanceOf label run = do
      absRun <- ffiOwnedExpectRight (label <> " RC-abstract") (forAbs run)
      cRun   <- ffiOwnedExpectRight (label <> " RC-CHeap") (forC run)
      pure $ QC.conjoin
        [ balanced (label <> " RC-abstract") absRun
        , balanced (label <> " RC-CHeap") cRun
        ]
    balanced label run =
      let st       = RCM.rcStats run
          baseline = RCM.rcBaseline run
          liveOk   = St.stLive st == baseline
          allocOk  = St.stAllocs st - St.stFrees st == baseline
      in QC.counterexample
           (label <> ": stLive=" <> show (St.stLive st) <> " baseline=" <> show baseline
             <> " allocs=" <> show (St.stAllocs st) <> " frees=" <> show (St.stFrees st))
           (liveOk && allocOk)

-- | P6: the zero-copy saving, differentially, over random 'bs'. We use the
-- CHeap's ALLOC-COUNT ('forCAllocs', i.e. 'Heap.wokStatAllocs' -- a fresh
-- counter per run, exactly as 'withBothBackends' reads it), NOT peak bytes:
-- both templates first evaluate an IDENTICAL @fromList [b0, b1, ...]@ literal,
-- which itself builds a transient Cons/Nil SPINE of @length bs@ cells before
-- 'Bytes.fromList' folds it into one flat 'NBytes' cell (dropping the spine
-- first, per 'bytesFromListRC'). That spine's PEAK BYTE contribution (~24B per
-- Cons cell) dwarfs a packed byte buffer's charge (~1B/byte) for any
-- non-trivial length, so 'wokStatPeakBytes' is swamped by spine noise and
-- cannot isolate the router's move-vs-copy signal (verified empirically: an
-- earlier version of this property pinned peak bytes directly and failed
-- immediately once 'bs' was non-trivially sized). Alloc COUNT is immune to
-- this: the spine contributes IDENTICALLY @length bs@ allocs to both
-- templates (cancels out), so the router's OWN contribution is exact and
-- absolute -- unique(MOVE) allocates exactly @length bs + 1@ cells (the
-- spine, folded into ONE buffer, never a second); shared(COPY) allocates
-- exactly @length bs + 2@ (the spine's buffer, PLUS the router's fresh
-- boundary copy) -- a genuine differential measurement of the real CHeap
-- run, matching \"unique allocates 0 extra cells; shared allocates 1 extra
-- ... cell\" precisely as an alloc-count delta.
prop_ffiOwnedZeroCopySaving :: Property
prop_ffiOwnedZeroCopySaving =
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      trial <- runFfiOwnedTrial bs
      -- Force both runs' Either results so a hard failure surfaces as a clear
      -- assertFailure message rather than silently comparing stale alloc-count
      -- fields from a failed run.
      _ <- ffiOwnedExpectRight "unique(MOVE) RC-CHeap" (forC (fotUnique trial))
      _ <- ffiOwnedExpectRight "shared(COPY) RC-CHeap" (forC (fotShared trial))
      let uAllocs  = forCAllocs (fotUnique trial)
          sAllocs  = forCAllocs (fotShared trial)
          spineLen = fromIntegral (length bs) :: Word64
      pure $ QC.conjoin
        [ QC.counterexample
            ("unique(MOVE) CHeap allocs: got " <> show uAllocs
              <> " expected (spine + 1 buffer) = " <> show (spineLen + 1))
            (uAllocs == spineLen + 1)
        , QC.counterexample
            ("shared(COPY) CHeap allocs: got " <> show sAllocs
              <> " expected (spine + buffer + 1 boundary copy) = " <> show (spineLen + 2))
            (sAllocs == spineLen + 2)
        , QC.counterexample
            ("zero-copy saving: the COPY branch must allocate EXACTLY ONE extra cell vs "
              <> "MOVE -- got delta " <> show (sAllocs - uAllocs))
            (sAllocs - uAllocs == 1)
        ]

-- | P7: multi-consume. For a random small arity @n@ (1..4), @n@ INDEPENDENT
-- unique(MOVE) consumes of freshly built (never-aliased) copies of the same
-- 'bs' all return 'referenceFNV1a bs', and the whole program's accounting
-- still balances on both RC backends.
prop_ffiOwnedMultiConsume :: Property
prop_ffiOwnedMultiConsume =
  QC.forAllShrink (QC.choose (1, 4) :: Gen Int) (filter (>= 1) . QC.shrink) $ \n ->
  QC.forAllShrink genFfiOwnedBytes QC.shrink $ \bs ->
    QC.ioProperty $ do
      run    <- runFfiOwnedSource (ffiOwnedMultiUniqueSource n bs)
      absRun <- ffiOwnedExpectRight "multi-consume RC-abstract" (forAbs run)
      cRun   <- ffiOwnedExpectRight "multi-consume RC-CHeap" (forC run)
      let expectedText = T.pack
            (show (sum (replicate n (toInteger (ffiOwnedExpectedChecksum bs)))))
          absText      = RCM.rcOutput absRun
          cText        = RCM.rcOutput cRun
          absSt        = RCM.rcStats absRun
          absBaseline  = RCM.rcBaseline absRun
          cSt          = RCM.rcStats cRun
          cBaseline    = RCM.rcBaseline cRun
          balancedAbs  = St.stLive absSt == absBaseline
                           && St.stAllocs absSt - St.stFrees absSt == absBaseline
          balancedC    = St.stLive cSt == cBaseline
                           && St.stAllocs cSt - St.stFrees cSt == cBaseline
      pure $ QC.conjoin
        [ QC.counterexample
            ("multi-consume (n=" <> show n <> "): abstract=" <> T.unpack absText
              <> " cheap=" <> T.unpack cText <> " expected=" <> T.unpack expectedText)
            (absText == expectedText && cText == expectedText)
        , QC.counterexample "multi-consume: RC-abstract accounting must balance" balancedAbs
        , QC.counterexample "multi-consume: RC-CHeap accounting must balance" balancedC
        ]

-- | Registration: modest 'QuickCheckTests' (each iteration is a full
-- compile+elaborate+run across THREE backends, so this is deliberately far
-- below the 500-800 counts the pure-IR Suite F/rc-string/rc-cont-store
-- property groups use) -- still enough samples to cover empty/small/multi-KB
-- 'Bytes' and to shrink a deliberate regression down to a small counterexample.
ffiOwnedIntoCPropertyTests :: TestTree
ffiOwnedIntoCPropertyTests =
  localOption (QuickCheckTests 60) $
    testGroup "FFI Slice 4: owned-INTO-C properties"
      [ testProperty "P1: backend parity (reference == RC-abstract == RC-CHeap), both branches"
          prop_ffiOwnedBackendParity
      , testProperty "P2: semantic -- unique(MOVE) checksum == referenceFNV1a bs"
          prop_ffiOwnedSemanticChecksum
      , testProperty "P3: branch-invariance -- MOVE and COPY yield the identical checksum"
          prop_ffiOwnedBranchInvariance
      , testProperty "P4: copy-fidelity -- original Bytes still reads correctly after a COPY consume"
          prop_ffiOwnedCopyFidelity
      , testProperty "P5: accounting balance -- allocs==frees, stLive==baseline on both RC backends"
          prop_ffiOwnedAccountingBalance
      , testProperty "P6: zero-copy saving (differential) -- MOVE charges 1x the buffer, COPY charges 2x"
          prop_ffiOwnedZeroCopySaving
      , testProperty "P7: multi-consume -- n independent unique consumes all == referenceFNV1a bs"
          prop_ffiOwnedMultiConsume
      ]

-- | FFI Slice 3 Task 6 (stored-continuation route, Q4). A borrow-capturing
-- continuation that ESCAPES its op-arm body (aliased then `__cont_store`'d) must be
-- rejected at the M3 continuation-escape boundary (`firstOrderNoHandlerViolations`),
-- BEFORE the program ever runs on the RC store. The program type-checks (the carrier
-- rule does not see the continuation capture), so the rejection is the M3 boundary,
-- not a CarrierEscape -- confirming the route's independent second line keeps a borrow
-- from riding a continuation out of its lending activation.
borrowContStoreBoundaryRejects :: FilePath -> Assertion
borrowContStoreBoundaryRejects path = do
  vs <- boundaryViolationsOf path
  assertBool
    (path <> ": expected an M3 continuation-escape boundary violation, got none "
          <> "(the borrow-capturing continuation would escape its lending activation)")
    (not (null vs))

-- | Run one corpus program through both backends and assert parity.
rcParityHarness :: FilePath -> Assertion
rcParityHarness path = do
  (absR, cR, _cAllocs, cPeakBytes) <- withBothBackends path
  case (absR, cR) of
    (Right a, Right c) -> do
      assertEqual (path <> ": output parity")
        (RCM.rcOutput a) (RCM.rcOutput c)
      assertEqual (path <> ": allocs parity")
        (St.stAllocs (RCM.rcStats a)) (St.stAllocs (RCM.rcStats c))
      assertEqual (path <> ": frees parity")
        (St.stFrees (RCM.rcStats a)) (St.stFrees (RCM.rcStats c))
      assertEqual (path <> ": peak parity")
        (St.stPeak (RCM.rcStats a)) (St.stPeak (RCM.rcStats c))
      -- closes parity (FFI Slice 3 Task 5): the foreign-borrow close count must be
      -- IDENTICAL on both backends. CHeap performs the real free; AbstractHeap only
      -- counts (no buffer), but the logical count is bumped in lockstep, so the
      -- abstract/C oracle pins "exactly one close per lent buffer". 0 == 0 for every
      -- non-borrow program (trivially true), N == N for a borrow-lending one.
      assertEqual (path <> ": closes parity")
        (St.stCloses (RCM.rcStats a)) (St.stCloses (RCM.rcStats c))
      -- peak_bytes parity: the abstract stPeakBytes must match the C runtime's
      -- wok_stat_peak_bytes (read before wok_heap_free). Both charge the same
      -- bytes per node via wouldBeCBytes, so the high-water marks must agree.
      assertEqual (path <> ": peak_bytes parity")
        (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
      -- Both backends must agree on the immortal baseline, and the C run must
      -- return its live count to exactly that baseline (no leak, no over-free).
      assertEqual (path <> ": baseline parity")
        (RCM.rcBaseline a) (RCM.rcBaseline c)
      assertEqual (path <> ": no leak (C) -- stLive returns to baseline")
        (RCM.rcBaseline c) (St.stLive (RCM.rcStats c))
    (Left e, _) ->
      assertFailure (path <> ": abstract backend FAILED: " <> show e)
    (_, Left e) ->
      assertFailure (path <> ": C backend FAILED: " <> show e)

-- ---------------------------------------------------------------------------
-- C-backend targeted tests (Task 3): source programs that ISOLATE the cross-heap
-- edges the auto-discovered corpus does not --- a C cell pointing at an abstract
-- cell and vice versa, the LStr fallback, and a deep spine through the C heap.
-- Each program lives in 'test/rc-c-backend' (its own directory, NOT
-- auto-discovered into the golden corpus) and is prepared by the SAME front end
-- as the parity group (load -> elaborate -> guard -> prune -> 'Perceus.insertRC'),
-- so the dup/drop instrumentation is the production pass, not a hand placement.
--
-- Each test runs the program through BOTH backends and asserts (a) the correct
-- output, (b) abstract/C stat parity, and (c) the C run returns to its baseline.
-- Parity against the abstract reference is what proves the C path is genuinely
-- exercised and correct (a vacuous all-abstract fallback would still differ from
-- the abstract run only in WHERE cells live, never in the counts --- but the
-- non-trivial alloc count asserted per test pins that real cells were built).

-- | Run a source file through both backends (fresh C heap, freed after) and
-- return @(output, abstractStats, cStats, baseline, cHeapAllocs)@.
--
-- @cHeapAllocs@ is the C heap's OWN allocation counter ('Heap.wokStatAllocs'),
-- read off @hp@ BEFORE it is freed. It is NOT the mirrored Haskell @stStats@
-- counter (which is bumped identically on the C and the abstract-fallback path);
-- it counts only 'NCon's that genuinely landed on the C runtime heap. Asserting
-- on it is what proves the C path was actually exercised rather than silently
-- all-falling-back to the abstract store.
runBothBackends :: FilePath -> IO (Text, St.Stats, St.Stats, Int, Word64)
runBothBackends path = do
  (absR, cR, cAllocs, _cPeakBytes) <- withBothBackends path
  case (absR, cR) of
    (Right a, Right c) ->
      pure (RCM.rcOutput c, RCM.rcStats a, RCM.rcStats c, RCM.rcBaseline c, cAllocs)
    (Left e, _) ->
      assertFailure ("abstract backend FAILED (" <> path <> "): " <> show e)
        >> error "unreachable: assertFailure throws"
    (_, Left e) ->
      assertFailure ("C backend FAILED (" <> path <> "): " <> show e)
        >> error "unreachable: assertFailure throws"

-- | Assert abstract/C stat parity plus the C run's baseline invariant. The
-- @minAllocs@ floor pins that the program actually built cells (so the test is
-- not vacuously balanced on an empty heap).
assertParityBalanced :: String -> Int -> St.Stats -> St.Stats -> Int -> Assertion
assertParityBalanced label minAllocs absSt cSt bl = do
  assertEqual (label <> ": allocs parity") (St.stAllocs absSt) (St.stAllocs cSt)
  assertEqual (label <> ": frees parity")  (St.stFrees absSt)  (St.stFrees cSt)
  assertEqual (label <> ": peak parity")   (St.stPeak absSt)   (St.stPeak cSt)
  assertBool  (label <> ": built a non-trivial number of cells")
    (St.stAllocs cSt >= minAllocs)
  assertEqual (label <> ": stLive returns to baseline (C)") bl (St.stLive cSt)
  assertEqual (label <> ": allocs - frees == baseline (C)")
    bl (St.stAllocs cSt - St.stFrees cSt)

-- ---------------------------------------------------------------------------
-- FBIP S2 differential-oracle corpus + fault injection (Task 5).
--
-- Six real '.wok' programs under 'test/rc-c-backend' that exercise the in-place
-- reuse mechanism end-to-end on BOTH backends. They are listed explicitly (see
-- 'rcFbipFiles', fed to 'rcCBackendParity') so each gets the standard output +
-- abstract==C + balance-lint parity check, plus the per-file targeted assertions
-- below (the FBIP WIN: fused allocs strictly below the non-FBIP 'insertRC'-only
-- run; reuse fires vs falls back per the spec table §4.4).
--
-- The "win" is the SAME program run with vs without 'reusePairing': identical
-- output, but the fused run records strictly fewer allocator events on a unique
-- spine. 'rcFbipFused'/'rcFbipNonFused' run that pair and return the stats.

-- | The FBIP S2 corpus, by path. Fed to 'rcCBackendParity' (parity check) and
-- referenced by 'rcFbipTargeted' (the win + fire/fallback assertions).
rcFbipFiles :: [FilePath]
rcFbipFiles =
  [ "test/rc-c-backend/fbip-map.wok"
  , "test/rc-c-backend/fbip-reverse.wok"
  , "test/rc-c-backend/fbip-shared.wok"
  , "test/rc-c-backend/fbip-cons-nil.wok"
  , "test/rc-c-backend/fbip-intwidth-flip.wok"
  , "test/rc-c-backend/fbip-kindchange.wok"
  , "test/rc-c-backend/fbip-string-field.wok"
  ]

-- | Load + elaborate + M1-guard + prune a corpus file to the pruned, elaborated
-- module --- WITHOUT 'insertRC' or 'reusePairing' --- so a caller can apply each
-- pipeline (fused vs non-FBIP) to the SAME source for the win comparison.
rcFbipPrepareRaw :: FilePath -> IO Anf.CoreModule
rcFbipPrepareRaw path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr) >> error "unreachable"
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s   -> assertFailure ("elaborate: " <> s) >> error "unreachable"
        Right cm ->
          case firstOrderNoHandlerViolations cm of
            [] -> pure (pruneToReachable cm)
            vs -> assertFailure (path <> ": handlers out of scope:\n"
                                   <> unlines (map T.unpack vs)) >> error "unreachable"

-- | Run a corpus file through the NON-FBIP pipeline ('insertRC' only) on the
-- abstract heap. Returns @(output, stats)@.
rcFbipNonFused :: FilePath -> IO (Text, St.Stats)
rcFbipNonFused path = do
  cm <- rcFbipPrepareRaw path
  RCM.runModuleRC (Perceus.insertRC cm) >>= \case
    Left e    -> assertFailure (path <> " (non-fused) FAILED: " <> show e) >> error "unreachable"
    Right run -> pure (RCM.rcOutput run, RCM.rcStats run)

-- | Run a corpus file through the FUSED pipeline ('reusePairing . insertRC') on
-- the abstract heap. Returns @(output, stats)@.
rcFbipFused :: FilePath -> IO (Text, St.Stats)
rcFbipFused path = do
  cm <- rcFbipPrepareRaw path
  RCM.runModuleRC (reusePairing (Perceus.insertRC cm)) >>= \case
    Left e    -> assertFailure (path <> " (fused) FAILED: " <> show e) >> error "unreachable"
    Right run -> pure (RCM.rcOutput run, RCM.rcStats run)

rcFbipTargeted :: TestTree
rcFbipTargeted = testGroup "rc-fbip"
  [ -- AC1a: map (+1) over a unique 3-element list. Reuse fires on every spine
    -- cell; the fused run's allocs/frees drop by EXACTLY the spine length (3) vs
    -- the non-FBIP run, collapsing the output spine to 0 net allocs. Output is
    -- bit-identical fused-vs-non-fused; abstract == C (via rcCBackendParity).
    testCase "fbip-map: reuse fires, allocs drop by the spine length (3), output [2, 3, 4]" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-map.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-map.wok"
      assertEqual "output is [2, 3, 4]" (T.pack "[2, 3, 4]") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      -- The 3-cell input spine is built either way; the win is the 3-cell OUTPUT
      -- spine collapsing to 0 net allocs.
      assertEqual "non-fused allocs = input spine + output spine (3 + 3)" 6 (St.stAllocs nfSt)
      assertEqual "fused allocs = input spine only (output spine reused in place)" 3 (St.stAllocs fSt)
      assertEqual "fused frees collapse to the input spine too" 3 (St.stFrees fSt)
      assertBool "FBIP win: fused allocs strictly below non-fused"
        (St.stAllocs fSt < St.stAllocs nfSt)
      assertEqual "allocs reduced by exactly the spine length (3)"
        3 (St.stAllocs nfSt - St.stAllocs fSt)

  , -- AC1b: accumulator reverse, target Cons built BEFORE the recursive call, so
    -- the token is born and consumed without crossing the call. Each input spine
    -- cell is reused to build the reversed spine; allocs drop by the spine length.
    testCase "fbip-reverse: reuse fires, allocs drop by the spine length (3), output [3, 2, 1]" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-reverse.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-reverse.wok"
      assertEqual "output is [3, 2, 1]" (T.pack "[3, 2, 1]") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      assertEqual "non-fused allocs = input spine + reversed spine (3 + 3)" 6 (St.stAllocs nfSt)
      assertEqual "fused allocs = input spine only (reversed spine reused in place)" 3 (St.stAllocs fSt)
      assertBool "FBIP win: fused allocs strictly below non-fused"
        (St.stAllocs fSt < St.stAllocs nfSt)
      assertEqual "allocs reduced by exactly the spine length (3)"
        3 (St.stAllocs nfSt - St.stAllocs fSt)
      -- Peak stays at the spine length (one cell churns at a time; no doubling).
      assertEqual "peak does not rise above the spine length (3)" 3 (St.stPeak fSt)

  , -- AC2: a list whose tail is SHARED (rc > 1). The runtime rc==1 gate yields a
    -- NULL token for the shared cells, so reuse does NOT fire on them (fresh
    -- alloc); only the UNIQUE head 'Cons 1' reuses. So the fused run saves exactly
    -- ONE alloc (the head), not three. Output is correct on both backends.
    testCase "fbip-shared: reuse does NOT fire on shared (rc>1) cells; only the unique head reuses" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-shared.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-shared.wok"
      -- sumList [2,3,4] = 9 ; sumList [2,3] = 5 ; total 14.
      assertEqual "output is 14" (T.pack "14") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      -- Only the unique head reuses; the 2 shared-tail cells allocate fresh. So
      -- the fused run saves exactly ONE alloc vs the non-FBIP run.
      assertEqual "fused saves exactly the one unique head cell (shared tail does not reuse)"
        1 (St.stAllocs nfSt - St.stAllocs fSt)
      assertBool "shared cells allocate fresh: fused allocs NOT collapsed to the input build"
        (St.stAllocs fSt > 3)

  , -- AC5: a single 'Cons x Nil' whose tail is the inline 'Nil' immediate. Reuse
    -- fires on the one Cons shell; the immediate slot is handled (never a donor,
    -- never double-freed). Fused saves the single output Cons.
    testCase "fbip-cons-nil: Cons-with-inline-Nil reuses; immediate slot handled, output [42]" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-cons-nil.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-cons-nil.wok"
      assertEqual "output is [42]" (T.pack "[42]") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      assertEqual "non-fused allocs = input Cons + output Cons (Nil is inline, no cell)" 2 (St.stAllocs nfSt)
      assertEqual "fused allocs = input Cons only (output Cons reused in place)" 1 (St.stAllocs fSt)
      assertEqual "the inline Nil is never a donor and never a fresh cell"
        1 (St.stAllocs nfSt - St.stAllocs fSt)

  , -- AC4: a map whose result crosses >= 2^63 (U64 head becomes non-encodable).
    -- The §6.3 static guard still PAIRS (both fields are statically U64 ->
    -- KLitInt), so a token is produced; but at runtime 'alloc_at' sees the new
    -- node is NOT C-eligible while the reserved shell was, so it takes the §4.3
    -- not-eligible branch: free the shell for real + alloc fresh (+1 / +1). Net:
    -- the fused run allocates the SAME as the non-FBIP run. Output + counts match
    -- abstract == C (verified by rcCBackendParity).
    testCase "fbip-intwidth-flip: §4.3 not-eligible free+fresh (no net win), output correct" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-intwidth-flip.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-intwidth-flip.wok"
      -- (2^63-8 + 8) + (2^63-8 + 9) + (2^63-8 + 10) = 3*2^63 + 3 = 27670116110564327427.
      assertEqual "output is the sum of three >= 2^63 values" (T.pack "27670116110564327427") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      -- The token IS produced (the pairing fired) but every alloc_at frees the
      -- reserved shell and allocates fresh, so there is NO net alloc win.
      assertEqual "not-eligible branch nets the same alloc count as non-FBIP"
        (St.stAllocs nfSt) (St.stAllocs fSt)
      assertEqual "not-eligible branch nets the same free count as non-FBIP"
        (St.stFrees nfSt) (St.stFrees fSt)

  , -- AC3: a slot-kind-changing map (KLitInt head -> KPointer String head).
    -- The §6.3 guard REFUSES to pair ([KLitInt,KPointer] /= [KPointer,
    -- KPointer]), so the output spine allocates FRESH (no token, no reuse). This
    -- is the regression guard against the C descriptor mis-decode (re-stamping an
    -- Int cell as a pointer cell would decode the Int payload as a heap handle).
    -- Output correct; abstract == C. (Int->Char is not expressible in current wok
    -- -- no Char literal/conversion -- so this uses the closest expressible
    -- kind-change, KLitInt -> KPointer via String, which since Slice E1 is a
    -- counted pointer; the unit-level Int->Char kindchange golden in
    -- 'rc-reuse-pairing' covers that case directly.)
    testCase "fbip-kindchange: §6.3 guard refuses the pair (fresh alloc, no reuse), output 3" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-kindchange.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-kindchange.wok"
      assertEqual "output is the list length 3" (T.pack "3") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      -- The guard refuses to pair, so fused == non-fused exactly (no token emitted).
      assertEqual "kind-change refused: fused allocs identical to non-FBIP"
        (St.stAllocs nfSt) (St.stAllocs fSt)
      assertEqual "kind-change refused: fused frees identical to non-FBIP"
        (St.stFrees nfSt) (St.stFrees fSt)

  , -- AC6 (String Slice E1): String-field reuse. 'slotClassOf TcString = KPointer'
    -- (Slice E1 Task 3), so a constructor with a String field gets slot-kind
    -- signature [KPointer, KLitInt] for Box String U64. When 'relabel' rebuilds
    -- 'Box "x" n' from a matched 'Box _ n', the slot-kind signatures agree and
    -- the reuse pairing fires for the Box cells (3 reuses). 'mapRelabel' also
    -- rebuilds 'BCons' with identical slot-kind signature [KPointer, KPointer],
    -- so the BCons spine cells also reuse (3 more). Total: 6 reuses; the fused
    -- run saves exactly 6 allocs vs the non-FBIP run. Output 6 (sum 1+2+3).
    testCase "fbip-string-field: String-field KPointer reuse fires, allocs drop by 6, output 6" $ do
      (nfOut, nfSt) <- rcFbipNonFused "test/rc-c-backend/fbip-string-field.wok"
      (fOut,  fSt)  <- rcFbipFused    "test/rc-c-backend/fbip-string-field.wok"
      assertEqual "output is 6" (T.pack "6") fOut
      assertEqual "fused output == non-fused output" nfOut fOut
      assertBool "FBIP win: fused allocs strictly below non-fused"
        (St.stAllocs fSt < St.stAllocs nfSt)
      -- 3 Box shells + 3 BCons spine shells reuse in place = 6 saved allocs.
      assertEqual "allocs reduced by exactly 6 (3 Box + 3 BCons shells reuse in place)"
        6 (St.stAllocs nfSt - St.stAllocs fSt)
  ]

-- ---------------------------------------------------------------------------
-- FBIP fault injection (Task 5, §10.3): the reuse oracle has TEETH.
--
-- A deliberately WRONG reuse pairing must be CAUGHT --- never a silent wrong
-- answer. We exercise the cleanly-injectable wrong-ARITY fault: 'badArityReuse'
-- is a surgical post-pass (analogous to 'Perceus.insertRCMutated') that rewrites
-- the FIRST 'RReuseCon tok c fields' to drop its LAST field, so the token's
-- reserved shell (recorded arity N) is asked to reuse an (N-1)-field node. The
-- 'allocAt' arity guard ('nodeArity newNode == rsArity') then takes the §4.3
-- not-eligible branch and the cell is rebuilt with a MISSING field --- a
-- malformed 'Cons' (no tail) whose render/consume diverges from the correct fused
-- run. The test asserts the mutated run is caught: it FAILS ('Left') or its output
-- DIVERGES from the correct fused output (the differential tripwire), never a
-- silent match.
--
-- This is the production 'reusePairing' output mutated by exactly one rewrite; the
-- real pass is untouched (its §5.3 size-exactness invariant guarantees the arity
-- always matches, so this fault cannot arise except by injection).
rcFbipFaultInjection :: TestTree
rcFbipFaultInjection = testGroup "rc-fbip-fault"
  [ testCase "wrong-arity RReuseCon is caught (run fails or output diverges; never silent)" $ do
      cm <- rcFbipPrepareRaw "test/rc-c-backend/fbip-map.wok"
      let fused   = reusePairing (Perceus.insertRC cm)
          mutated = badArityReuse fused
      -- The mutation must actually change the module (an RReuseCon was present and
      -- rewritten) --- otherwise the test would be vacuous.
      assertBool "the bad-arity mutation actually fired (an RReuseCon was rewritten)"
        (Anf.prettyModule mutated /= Anf.prettyModule fused)
      goodR <- RCM.runModuleRC fused
      badR  <- RCM.runModuleRC mutated
      case (goodR, badR) of
        (Right good, Right bad) ->
          -- Both ran: the only acceptable outcome is a DIVERGENCE (the malformed
          -- cell renders differently). A silent match would mean the oracle missed
          -- the corruption.
          assertBool
            ("wrong-arity reuse produced a SILENT matching answer ("
               <> T.unpack (RCM.rcOutput bad) <> ") --- the oracle has no teeth")
            (RCM.rcOutput good /= RCM.rcOutput bad)
        (Right _, Left _) ->
          -- The mutated run failed loudly (a structural/UAF/double-free error).
          -- Caught: this is the desired outcome.
          pure ()
        (Left e, _) ->
          assertFailure ("the CORRECT fused run failed unexpectedly: " <> show e)
  ]

-- | Surgical bad-reuse mutation (TESTS ONLY): rewrite the FIRST 'RReuseCon tok c
-- fields' encountered to drop its LAST field, so the reused node's arity is one
-- below the token's reserved-shell arity. The production 'reusePairing' never
-- emits this (its §5.3 size-exactness guarantees arity exactness); this is the
-- fault injector that proves 'allocAt's arity guard + the differential oracle
-- catch a wrong pairing rather than silently corrupting the heap.
badArityReuse :: Anf.CoreModule -> Anf.CoreModule
badArityReuse (Anf.CoreModule bs) =
  Anf.CoreModule (snd (foldr stepB (False, []) bs))
  where
    stepB (Anf.TopBind n ps body) (done, acc) =
      let (done', body') = goB done body
      in (done', Anf.TopBind n ps body' : acc)

    goB done e | done = (True, e)
    goB _ (Anf.Let b (Anf.RReuseCon tok c fields) rest)
      | not (null fields) =
          -- Drop the LAST field via a total expression (CLAUDE.md: avoid partial
          -- 'init'); 'reverse (drop 1 (reverse fields))' is total and behaves
          -- identically on the non-empty list this guard admits.
          (True, Anf.Let b (Anf.RReuseCon tok c (reverse (drop 1 (reverse fields)))) rest)
    goB done (Anf.Let b r rest) =
      let (done1, r')    = goRhsB done r
          (done2, rest') = goB done1 rest
      in (done2, Anf.Let b r' rest')
    goB done (Anf.Case s alts) =
      let (done', alts') = goAltsB done alts
      in (done', Anf.Case s alts')
    goB done (Anf.LetJoin j ps jb e) =
      let (done1, jb') = goB done jb
          (done2, e')  = goB done1 e
      in (done2, Anf.LetJoin j ps jb' e')
    goB done (Anf.LetRec defs e) =
      let (done1, defs') = goDefsB done defs
          (done2, e')    = goB done1 e
      in (done2, Anf.LetRec defs' e')
    goB done (Anf.Handle e h) =
      let (done', e') = goB done e in (done', Anf.Handle e' h)
    goB done e = (done, e)

    goRhsB done (Anf.RLam ps e) =
      let (done', e') = goB done e in (done', Anf.RLam ps e')
    goRhsB done r = (done, r)

    goAltsB done [] = (done, [])
    goAltsB done (Anf.AltCon c bs' body : rest) =
      let (done1, body') = goB done body
          (done2, rest') = goAltsB done1 rest
      in (done2, Anf.AltCon c bs' body' : rest')
    goAltsB done (Anf.AltLit l body : rest) =
      let (done1, body') = goB done body
          (done2, rest') = goAltsB done1 rest
      in (done2, Anf.AltLit l body' : rest')
    goAltsB done (Anf.AltDefault body : rest) =
      let (done1, body') = goB done body
          (done2, rest') = goAltsB done1 rest
      in (done2, Anf.AltDefault body' : rest')

    goDefsB done [] = (done, [])
    goDefsB done ((b, ps, body) : rest) =
      let (done1, body') = goB done body
          (done2, rest') = goDefsB done1 rest
      in (done2, (b, ps, body') : rest')

rcCBackendTargeted :: TestTree
rcCBackendTargeted = testGroup "rc-c-backend-targeted"
  [ -- Cross-heap cascade: a 'Wrap' NCon HOLDS a closure (HBOX child into the
    -- abstract heap) and that closure CAPTURES a 'Box' NCon (a C-heap child).
    -- The drop cascade must cross the heap boundary in both directions and
    -- return the heap to baseline with balanced stats and no sanitizer error.
    -- (>= 3 cells: the Box NCon, the closure, and the Wrap NCon.)
    testCase "cross-heap cascade (NCon holds closure; closure captures NCon)" $ do
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/cross-heap-cascade.wok"
      assertEqual "result is n + captured (5 + 7)" (T.pack "12") txt
      assertEqual "no value-CAF baseline for this program" 0 bl
      assertParityBalanced "cross-heap cascade" 3 absSt cSt bl
      -- Non-vacuity: 'Box' and 'Wrap' are encodable NCons that MUST route to the
      -- C heap. Read off the C heap's OWN counter (not the mirrored stStats) to
      -- prove the C path actually fired -- this fails if 'allocNCon's CHeap branch
      -- silently all-falls-back to the abstract store.
      assertBool "C heap genuinely exercised (NCon routed to CAddr)" (cAllocs > 0)

  , -- String field slot-encoded (Slice E3, Task 2): a 'Tagged' NCon with a
    -- short 'String' field.  "hi" (2 bytes) is 'InlineStr'; with Task 2
    -- 'encodeSlotC (RVBox (InlineStr bs))' packs it into a @111@ slot word,
    -- so the 'Tagged' NCon is C-eligible again.  Only 1 cell is allocated
    -- (the NCon itself; the InlineStr packs into a slot with no extra cell).
    -- Both backends agree and the C heap records >= 1 alloc.
    testCase "String field is a pointer cell (constructor with a String field is C-eligible)" $ do
      -- E3 Task 2: "hi" is InlineStr packed into a 111 slot; Tagged is C-eligible.
      -- 1 cell: the Tagged NCon only (no separate string cell for a short string).
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/fallback-lstr.wok"
      assertEqual "result is the U64 field (1)" (T.pack "1") txt
      assertEqual "no value-CAF baseline for this program" 0 bl
      assertParityBalanced "InlineStr field slot-encoded; Tagged is C-eligible (E3 Task 2)" 1 absSt cSt bl
      -- Non-vacuity: exactly 1 C cell (the Tagged NCon); the InlineStr field packs
      -- into a slot with no separate WokString cell.  A regression where the inline
      -- field gets its own cell (cAllocs == 2) will fail this assertion.
      assertEqual "E3 Task 2: exactly 1 C cell (NCon only; inline string field packed in-slot, no separate WokString cell)"
        (1 :: Word64) cAllocs

  , -- Fallback: a 'Tagged' NCon whose first field is a U64 literal >= 2^63.
    -- 'encodeSlotC' calls 'toIntegralSized n :: Maybe Int64', which returns
    -- 'Nothing' for n >= 2^63, so the whole NCon falls back to the ABSTRACT
    -- heap under the C backend even though the second field (42) is encodable.
    -- The result and heap accounting must still match the abstract reference.
    testCase "high-bit U64 fallback (U64 >= 2^63 stays abstract)" $ do
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/fallback-highbit-u64.wok"
      assertEqual "result is the second U64 field (42)" (T.pack "42") txt
      assertEqual "no value-CAF baseline for this program" 0 bl
      assertParityBalanced "high-bit U64 fallback" 1 absSt cSt bl
      -- Non-vacuity (fallback proof): the ONLY constructor this program builds is
      -- 'Tagged 9223372036854775815 42'. The first field (2^63 + 7) exceeds
      -- Int64.maxBound, so 'encodeSlotC' returns 'Nothing' for the whole NCon,
      -- routing it to the abstract heap. The C heap's OWN counter must be zero
      -- -- direct proof the high-bit check fired at alloc-site selection time.
      assertEqual "high-bit-U64-bearing NCon fell back to abstract heap; nothing on C"
        (0 :: Word64) cAllocs

  , -- Deep list (100000 C-heap Cons cells): build and consume a long spine
    -- through the C backend. The drop cascade is an iterative Haskell worklist,
    -- so 'stLive' must return to baseline without a host-stack overflow.
    -- NOTE (Slice 2, Task 3): 'Nil' is an 'Inline' immediate (zero cells). With
    -- the 2-bit slot tag, 'Inline' slots ARE now encodable (low 2 bits = 11), so
    -- ALL 100000 Cons cells route to the C heap --- including 'Cons 1 Nil' which
    -- previously fell back. Total allocated: 100000 cells (all C-heap Cons).
    testCase "deep list (100000 C-heap cons cells) frees to baseline" $ do
      (_, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/deep-list.wok"
      assertEqual "no value-CAF baseline for this program" 0 bl
      assertParityBalanced "deep list" 100000 absSt cSt bl
      -- Non-vacuity: all 100000 Cons cells route to the C heap (Inline Nil is
      -- encodable via the 2-bit low-tag '11' class introduced in Task 3).
      assertBool "all Cons cells routed to C heap" (cAllocs >= 100000)
      assertEqual "deep list: all 100000 Cons on C heap (Inline Nil encodable)"
        (100000 :: Word64) cAllocs

  , -- Nullary immediate: a bare nullary constructor ('[]' = Nil, zero fields)
    -- must produce ZERO heap cells on BOTH backends (abstract and C). An
    -- 'Inline' immediate lives in the 'Addr' tag itself; it never touches
    -- 'recordAlloc', so allocs == frees == peak == 0. Output must still render
    -- identically to the abstract run.
    testCase "nullary-zero-alloc (main = []) allocates zero cells on both backends" $ do
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/nullary-zero-alloc.wok"
      assertEqual "result renders as []" (T.pack "[]") txt
      assertEqual "abstract backend: zero allocs" 0 (St.stAllocs absSt)
      assertEqual "abstract backend: zero frees"  0 (St.stFrees absSt)
      assertEqual "abstract backend: zero peak"   0 (St.stPeak absSt)
      assertEqual "C backend: zero allocs"        0 (St.stAllocs cSt)
      assertEqual "C backend: zero frees"         0 (St.stFrees cSt)
      assertEqual "C backend: zero peak"          0 (St.stPeak cSt)
      assertEqual "no value-CAF baseline"         0 bl
      assertEqual "C heap itself: zero allocs"    (0 :: Word64) cAllocs

  , -- Mixed pointer/immediate cascade (Task 3): a list mixing Some (one-field)
    -- and None (nullary -> Inline) options. Under the 2-bit low-tag encoding,
    -- a 'Cons (Some n) tail' has an HBox slot (the Some NCon, carrying a U64) and
    -- an Inline/HBox tail; a 'Cons None tail' has an Inline slot (None) and a
    -- tail. All Cons and Some cells must route to the C heap; None is Inline (zero
    -- cells). The drop cascade must skip the Inline slots without double-freeing
    -- or leaking any counted child.
    testCase "mixed pointer/immediate cascade (Some/None list stays C-resident)" $ do
      (txt, absSt, cSt, bl, cAllocs) <- runBothBackends "test/rc-c-backend/mixed-maybe-list.wok"
      -- The program builds [Some 1, None, Some 3, None] and renders it.
      assertEqual "result renders as the option list" (T.pack "[Some(1), None, Some(3), None]") txt
      assertEqual "no value-CAF baseline for this program" 0 bl
      assertParityBalanced "mixed pointer/immediate" 6 absSt cSt bl
      -- Non-vacuity (EXACT): all 6 cells -- 4 Cons + 2 Some -- route to the C heap;
      -- the 2 None and the trailing Nil are Inline immediates (zero cells). Pinning
      -- the exact count (not just > 0) catches a regression where an Inline slot
      -- wrongly forces its carrying Cons to fall back to the abstract heap (which
      -- would drop cAllocs to 2, the Some cells only -- a `> 0` floor would miss it).
      assertEqual "mixed pointer/immediate: all 6 cells (4 Cons + 2 Some) on C heap"
        (6 :: Word64) cAllocs
  ]

-- ---------------------------------------------------------------------------
-- C-backend slot encode/decode round-trip property (Task 3 step 5).
--
-- 'encodeSlotC' packs an 'RCValue' into a @('SlotKind', 'Word64')@ pair when it is
-- C-encodable; 'decodeSlotC' is its exact inverse on those shapes. The property
-- pins that inverse for the generable encodable values: an 'Int64'-range integer
-- literal, a char literal, unit, an abstract-heap box ('HAddr'), a nullary inline
-- immediate ('Inline' tag), and a short inline string ('InlineStr', 0..7 bytes).
-- A 'CAddr' is a raw runtime pointer (not purely generable) and is excluded.
--
-- The @KPointer@ class uses the low 2 bits to discriminate pointer-classes, then
-- sub-discriminates inside the @11@ class with bit 2 (four classes in all):
--
--   * @..0@ (bit0 = 0): 'CAddr' bare 8-aligned pointer.
--   * @01@ (bits 1:0 = 01): 'HAddr' index, stored as @(i << 2) .|. 1@.  Uses 62
--     bits for the index; the round-trip holds for indices with |i| < 2^61.
--   * @011@ (bits 2:0 = 011): 'Inline' nullary tag, stored as @(tag << 3) .|. 3@.
--   * @111@ (bits 2:0 = 111): 'InlineStr' short string ('packInlineStr').
--
-- The property also asserts mutual exclusivity: a 'CAddr' round-trips to 'CAddr',
-- an 'HAddr' to 'HAddr', an 'Inline' to 'Inline', an 'InlineStr' to 'InlineStr'
-- --- never crossing class.

-- | An 'RCValue' restricted to the C-encodable shapes the property round-trips.
newtype EncodableRCValue = EncodableRCValue St.RCValue
  deriving (Eq, Show)

-- | The maximum Int value that round-trips through the HAddr (i << 2 | 1) encoding.
-- Values with |i| >= 2^61 would lose the top bit on the left shift.
maxHAddrIdx :: Int64
maxHAddrIdx = 2^(61 :: Int) - 1

instance QC.Arbitrary EncodableRCValue where
  arbitrary = EncodableRCValue <$> QC.oneof
    [ -- 'LInt' must fit in Int64 (the encoder rejects wider bignums), so draw the
      -- payload from the full Int64 range.
      St.RVLit . Anf.LInt . toInteger
        <$> QC.choose (minBound :: Int64, maxBound :: Int64)
    , St.RVLit . Anf.LChar <$> QC.arbitrary
    , pure (St.RVLit Anf.LUnit)
      -- 'HAddr' is encoded as @(i << 2) .|. 1@, using 62 bits for the index.
      -- Restrict to Int62 range; also generate negative (static-index) values to
      -- exercise the sign-extension on the arithmetic >> 2 decode path.
    , St.RVBox . St.HAddr . fromIntegral
        <$> QC.choose (negate maxHAddrIdx, maxHAddrIdx)
      -- 'Inline' is encoded as @(tag << 3) .|. 3@; the tag is an arbitrary Word32.
    , St.RVBox . St.Inline <$> QC.arbitrary
      -- 'InlineStr' is encoded by 'packInlineStr' (bits 2:0 = 111, length in 5:3,
      -- bytes little-endian above). Draw 0..7 arbitrary bytes to fuzz the packing.
    , do n     <- QC.choose (0, 7 :: Int)
         bytes <- QC.vectorOf n (QC.arbitrary :: Gen Word8)
         pure (St.RVBox (St.InlineStr (BS.pack bytes)))
    ]

-- | Classify a decoded 'RCValue' by its pointer-class for mutual-exclusivity check.
data PointerClass = PCCAddr | PCHAddr | PCInline | PCInlineStr | PCOther
  deriving (Eq, Show)

pointerClass :: St.RCValue -> PointerClass
pointerClass (St.RVBox (St.CAddr _))     = PCCAddr
pointerClass (St.RVBox (St.HAddr _))     = PCHAddr
pointerClass (St.RVBox (St.Inline _))    = PCInline
pointerClass (St.RVBox (St.InlineStr _)) = PCInlineStr
pointerClass _                            = PCOther

rcCBackendSlotProperty :: TestTree
rcCBackendSlotProperty = testGroup "rc-c-backend-slot"
  [ testProperty "encodeSlotC/decodeSlotC round-trips encodable RCValues" $
      \(EncodableRCValue v) -> Just v == fmap (uncurry St.decodeSlotC) (St.encodeSlotC v)
  , testProperty "pointer-class low-tag mutually exclusive on round-trip" $
      \(EncodableRCValue v) ->
        case fmap (uncurry St.decodeSlotC) (St.encodeSlotC v) of
          Just decoded -> pointerClass decoded == pointerClass v
          Nothing      -> True  -- non-pointer kinds are not classified
  ]

-- ---------------------------------------------------------------------------
-- Suite B: heap accounting + --dump-rc-stats golden (Task 9)
--
-- For each program in test/rc-examples/, after running it on the RC interpreter,
-- assert the BASELINE heap invariant: every dynamic allocation made by 'main' is
-- reclaimed, leaving exactly the immortal global/dictionary-CAF baseline live:
--
--     stLive          == rcBaseline   AND
--     stAllocs - stFrees == rcBaseline
--
-- We assert against the baseline, NOT against zero, because 'runModuleRC' forces
-- every value-CAF (e.g. an instance-dictionary record) at load time; those cells
-- are immortal globals, not leaks (see 'RCRun's documentation). For a module
-- whose 'main' allocates nothing persistent, rcBaseline == 0 and the invariant
-- reduces to the textbook heap-empty (stLive == 0, allocs == frees). The corpus
-- includes a typeclass program (15-typeclass-dict) whose dictionary CAF makes
-- rcBaseline == 1, exercising the non-zero-baseline path.
--
-- A second golden test pins the four accounting numbers (allocs/frees/peakLive/
-- baseline) per program via 'Machine.renderRcStats' --- the same bytes the
-- '--dump-rc-stats' CLI mode emits --- so a regression (a move silently turning
-- into a dup, or a dropped/duplicated drop) surfaces as a golden diff.
--
-- Both harnesses share the differential harness's M1 scope guard and reachable
-- pruning, so they run the same byte-identical handler-free programs.

rcStatsGoldenFor :: FilePath -> FilePath
rcStatsGoldenFor f =
  replaceDirectory (replaceExtension f ".expected") "test/rc-stats-golden"

-- | Load -> elaborate -> M1 scope guard -> prune-to-reachable -> insertRC. The
-- shared front end for both Suite B harnesses; returns the pruned, instrumented
-- module ready for 'runModuleRC', or an 'assertFailure' on any front-end error.
rcStatsPrepare :: FilePath -> IO Anf.CoreModule
rcStatsPrepare path = do
  result <- Loader.loadProgram path []
  case result of
    Left lerr -> assertFailure ("loader: " <> show lerr)
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left s   -> assertFailure ("elaborate: " <> s)
        Right cm -> do
          case firstOrderNoHandlerViolations cm of
            [] -> pure ()
            vs -> assertFailure
              (path <> ": not a handler-free program (Handle/ROp out of scope):\n"
                 <> unlines (map T.unpack vs))
          -- FBIP reuse-pairing runs AFTER insertRC everywhere the instrumented
          -- module is EXECUTED (this prepare funnels Suite B stats + the C-backend
          -- parity oracle). The differential oracle re-checks output + balance, so
          -- a reuse win surfaces as an alloc/free count drop, never a wrong answer.
          pure (reusePairing (Perceus.insertRC (pruneToReachable cm)))

-- | Suite B heap-accounting assertion: run the instrumented module and check the
-- baseline invariant.
rcStatsHarness :: FilePath -> Assertion
rcStatsHarness path = do
  instrumented <- rcStatsPrepare path
  RCM.runModuleRC instrumented >>= \case
    Left rerr -> assertFailure ("RC interpreter failed: " <> show rerr)
    Right run -> do
      let st       = RCM.rcStats run
          baseline = RCM.rcBaseline run
      assertEqual (path <> ": stLive must return to the immortal baseline")
        baseline (St.stLive st)
      assertEqual (path <> ": allocs - frees must equal the immortal baseline")
        baseline (St.stAllocs st - St.stFrees st)

-- | Suite B golden: the '--dump-rc-stats' bytes for a corpus program.
rcStatsDumpHarness :: FilePath -> IO BL.ByteString
rcStatsDumpHarness path = do
  instrumented <- rcStatsPrepare path
  RCM.runModuleRC instrumented >>= \case
    Left rerr -> pure (BL.pack ("RC interpreter failed: " <> show rerr <> "\n"))
    Right run -> pure (BL.pack (T.unpack (RCM.renderRcStats run)))

-- ---------------------------------------------------------------------------
-- Suite C(b): fault injection --- the oracle has TEETH (Task 10)
--
-- The differential + heap-accounting oracle is only worth anything if it CATCHES
-- a wrong dup/drop placement. To prove it does, we deliberately break the pass
-- with 'Perceus.insertRCMutated' (a tests-only post-pass that perturbs exactly
-- one RC call; the production 'insertRC' is untouched) and assert each mutation
-- makes the oracle fail LOUDLY somewhere on the corpus:
--
--   * 'OmitOneDrop'      --- a leak: the Suite B baseline invariant breaks
--     (@stLive > rcBaseline@) on at least one program.
--   * 'OmitOneDup'       --- under-counting a shared value: the RC run trips a
--     'Left' use-after-free / double-free, OR 'balanceLint' reports an
--     over-consume on the mutated module.
--   * 'DuplicateOneDrop' --- over-relinquishing: the RC run trips a 'Left'
--     double-free on at least one program.
--
-- Each test asserts the FAILURE is DETECTED --- i.e. the mutated run does NOT
-- satisfy the oracle on at least one corpus program. A mutation that the oracle
-- failed to catch on EVERY program would be a vacuous oracle, and the test fails.
--
-- We share the front end with Suite B (same load -> elaborate -> M1 scope guard
-- -> prune), then apply the MUTATED instrumentation instead of the correct one.

rcTeethTests :: [FilePath] -> TestTree
rcTeethTests perceusFiles = testGroup "rc teeth"
  [ testCase "OmitOneDrop leaks (Suite B baseline breaks somewhere)" $ do
      detected <- Control.Monad.filterM
                    (teethLeakDetected Perceus.OmitOneDrop) perceusFiles
      assertBool
        ("OmitOneDrop produced NO leak on any corpus program --- the heap-accounting "
           <> "oracle is vacuous")
        (not (null detected))
  , testCase "OmitOneDup trips UAF/double-free or balance over-consume somewhere" $ do
      detected <- Control.Monad.filterM
                    (teethUnsoundDetected Perceus.OmitOneDup) perceusFiles
      assertBool
        ("OmitOneDup was caught by NEITHER the RC run nor balanceLint on any corpus "
           <> "program --- the oracle is vacuous")
        (not (null detected))
  , testCase "DuplicateOneDrop trips a double-free somewhere" $ do
      detected <- Control.Monad.filterM
                    (teethRunFailDetected Perceus.DuplicateOneDrop) perceusFiles
      assertBool
        ("DuplicateOneDrop produced NO RC-run failure on any corpus program --- the "
           <> "double-free trap is vacuous")
        (not (null detected))
  ]

-- | Load + elaborate + M1-guard + prune a corpus file, then instrument it with a
-- MUTATED Perceus pass. Returns 'Nothing' for a file outside the M1 fragment (so
-- the teeth tests silently skip it, exactly as Suite B would refuse it) and
-- 'Just' the mutated module otherwise.
teethPrepareMutated :: Perceus.Mutation -> FilePath -> IO (Maybe Anf.CoreModule)
teethPrepareMutated mut path = do
  result <- Loader.loadProgram path []
  case result of
    Left _ -> pure Nothing
    Right (entryName, ms) ->
      case Pipeline.elaborateProgramFull entryName ms of
        Left _   -> pure Nothing
        Right cm
          | not (null (firstOrderNoHandlerViolations cm)) -> pure Nothing
          | otherwise ->
              pure (Just (Perceus.insertRCMutated mut (pruneToReachable cm)))

-- | Does 'OmitOneDrop' make Suite B's baseline invariant FAIL on this file via a
-- genuine LEAK? A leak shows up as @stLive > rcBaseline@ (more live cells than the
-- immortal baseline) OR as @stAllocs - stFrees > rcBaseline@. We deliberately do
-- NOT count a 'Left' as a leak: the plan says OmitOneDrop must make Suite B report
-- @stLive > baseline@, so this asserts the SPECIFIC leak path, not just "something
-- went wrong". 'Nothing' (out of fragment) or a clean (balanced) run -> NOT
-- detected.
teethLeakDetected :: Perceus.Mutation -> FilePath -> IO Bool
teethLeakDetected mut path = do
  mcm <- teethPrepareMutated mut path
  case mcm of
    Nothing -> pure False
    Just cm -> RCM.runModuleRC cm >>= \case
      Left _    -> pure False  -- a run failure is not the leak signal we assert
      Right run ->
        let st       = RCM.rcStats run
            baseline = RCM.rcBaseline run
        in pure (St.stLive st > baseline
                   || (St.stAllocs st - St.stFrees st) > baseline)

-- | Does the mutation make the RC RUN fail with a 'Left' on this file
-- (use-after-free / double-free / dangling)? 'Nothing' or a clean run -> 'False'.
teethRunFailDetected :: Perceus.Mutation -> FilePath -> IO Bool
teethRunFailDetected mut path = do
  mcm <- teethPrepareMutated mut path
  case mcm of
    Nothing -> pure False
    Just cm -> RCM.runModuleRC cm >>= \case
                 Left _  -> pure True
                 Right _ -> pure False

-- | Does the mutation make the oracle catch UNSOUNDNESS on this file --- EITHER
-- the RC run trips a 'Left' (UAF/double-free), OR 'Perceus.lintInstrumented'
-- flags an over-consume on the mutated, instrumented module? We lint the
-- ALREADY-mutated bytes via 'lintInstrumented' (the plain 'balanceLint' re-runs
-- the CORRECT 'insertRC', which would hide the mutation). Either signal counts.
teethUnsoundDetected :: Perceus.Mutation -> FilePath -> IO Bool
teethUnsoundDetected mut path = do
  runFail <- teethRunFailDetected mut path
  if runFail
    then pure True
    else do
      mcm <- teethPrepareMutated mut path
      pure (case mcm of
              Nothing -> False
              Just cm -> not (null (Perceus.lintInstrumented cm)))

-- ---------------------------------------------------------------------------
-- Suite F: property-based differential + heap-empty (Task 12)
--
-- The curated corpus (Suites A/B/D/E) pins specific programs; this suite throws
-- RANDOM first-order ANF at the same oracle so it catches placement bugs the
-- corpus misses. For every generated program we assert ALL THREE oracle signals
-- at once:
--
--   1. DIFFERENTIAL: the reference interpreter (on the PRE-Perceus ANF) and the
--      RC interpreter (on the Perceus-INSTRUMENTED ANF) render byte-identical
--      output. 'dup'/'drop' do not change values, so any divergence is a bug.
--   2. HEAP-EMPTY: after the RC run, @stLive == rcBaseline@ AND
--      @stAllocs - stFrees == rcBaseline@ (the baseline invariant; generated
--      programs have no global CAFs so the baseline is 0 in practice, but we
--      assert against the reported baseline for robustness).
--   3. NO UAF / DOUBLE-FREE: the RC run returns 'Right' (the store tombstone
--      traps surface any use-after-free / double-free as a 'Left').
--
-- The generator emits WELL-SCOPED, FIRST-ORDER ANF directly (no surface syntax,
-- no loader/elaborator): Lit / Con / Record / Proj / Case / Let over a small
-- fixed set of nullary+binary constructors and saturated binary integer prims.
-- There are NO lambdas / HOF / partial application / effects, so every program
-- is squarely in the M1 fragment. Because both interpreters resolve constructors
-- structurally and prims by name (and 'renderValue'/'renderRCValue' agree byte
-- for byte), a directly-built @main = e@ module runs identically on both without
-- the type checker --- exactly the differential we want. Binder types are
-- generated FAITHFULLY (Int = unboxed U64; Pair/List/Record = boxed) so the
-- Perceus pass inserts dup/drop on precisely the reference-counted values.

rcPropertyTests :: TestTree
rcPropertyTests =
  localOption (QuickCheckTests 500) $
    testGroup "rc property"
      [ testProperty "differential output + heap-empty + no UAF/double-free"
          prop_rcDifferential
      ]

-- | The single Suite F property. Generate a first-order program, then assert the
-- three oracle signals. On failure, attach the pretty-printed instrumented ANF
-- and both interpreters' results as a counterexample (so a shrink/seed is
-- diagnosable without re-running by hand).
prop_rcDifferential :: Property
prop_rcDifferential =
  forAllShrink genProgram shrinkProgram $ \cm -> QC.ioProperty $ do
    -- FBIP reuse-pairing AFTER insertRC: random first-order programs exercise the
    -- post-pass adversarially. The three oracle signals below (output / heap-empty
    -- / balance) hold regardless of whether a pair fires.
    rcRes <- RCM.runModuleRC (reusePairing (Perceus.insertRC cm))
    let refRes = Interp.runModule cm
        report =
          "instrumented ANF:\n"
            <> T.unpack (Perceus.prettyPerceus cm)
            <> "\n\nreference: " <> showRes (fmap Interp.renderValue refRes)
            <> "\nrc:        " <> showRcRes rcRes
    pure $ counterexample report $
         case (refRes, rcRes) of
           (Right v, Right run) ->
             let outOk      = Interp.renderValue v == RCM.rcOutput run
                 st         = RCM.rcStats run
                 baseline   = RCM.rcBaseline run
                 liveOk     = St.stLive st == baseline
                 balancedOk = St.stAllocs st - St.stFrees st == baseline
             in counterexample "output / heap-empty / balanced mismatch"
                  (outOk && liveOk && balancedOk)
           (Left _, Left _) ->
             -- Both failed the same way by construction (a generated divide is
             -- the only partial prim and we never emit it; this branch is a
             -- defensive match, treated as agreement).
             counterexample "both interpreters failed (treated as agreement)" True
           _ ->
             counterexample "divergence: exactly one interpreter failed" False
  where
    showRes (Right t)  = T.unpack t
    showRes (Left e)   = "FAILED (" <> show e <> ")"
    showRcRes (Right run) = T.unpack (RCM.rcOutput run)
    showRcRes (Left e)    = "FAILED (" <> show e <> ")"

-- ---------------------------------------------------------------------------
-- The first-order ANF generator
--
-- A program is @main = e@ where @e@ produces a value of a randomly chosen type.
-- Generation runs in @StateT Int Gen@: the 'Int' is a monotonic fresh-Unique
-- supply (so every binder is globally unique => well-scoped by construction),
-- and 'Gen' drives the random choices. A typed environment @[(Name, GTy)]@ of
-- in-scope binders lets leaves reference earlier bindings of a compatible type.

-- | The closed first-order type universe the generator ranges over. Every one is
-- rendered identically by the reference and RC interpreters.
data GTy
  = GInt            -- unboxed U64 scalar
  | GPair           -- boxed   Pair(Int, Int)
  | GList           -- boxed   cons-list of Int (Cons(Int, GList) | Nil)
  | GRec            -- boxed   record R { fst : Int, snd : Int }
  deriving (Eq, Show)

-- | Map a generator type to the 'CType' carried by binders of that type. The
-- Perceus pass keys boxedness off this type ('isBoxedType'): 'GInt' is unboxed
-- (no dup/drop), the other three are boxed (reference-counted).
gtyCType :: GTy -> Ty.CType
gtyCType GInt  = Ty.CTCon Ty.TcU64 []
gtyCType GPair = Ty.CTCon (Ty.TcTuple 2) [Ty.CTCon Ty.TcU64 [], Ty.CTCon Ty.TcU64 []]
gtyCType GList = Ty.CTCon Ty.TcList [Ty.CTCon Ty.TcU64 []]
gtyCType GRec  = Ty.CTRecord recTyName Ty.CREmpty

recTyName :: Text
recTyName = T.pack "R"

-- | Generation monad: a fresh-Unique counter threaded over 'Gen'.
type GenM = StateT Int Gen

-- | Pull a fresh, globally-unique 'Name' with a readable hint.
freshN :: Text -> GenM Name
freshN hint = state (\u -> (Name hint (Unique u), u + 1))

-- | A typed binder over a generated type.
gBinder :: Text -> GTy -> GenM Binder
gBinder hint ty = do
  n <- freshN hint
  pure (Binder n Unrestricted (gtyCType ty))

-- | Lift a 'Gen' action into 'GenM'.
liftG :: Gen a -> GenM a
liftG = lift

-- | Weighted choice among 'GenM' alternatives (a 'GenM' analogue of QuickCheck's
-- 'frequency'). Zero-weight entries are ignored; at least one positive-weight
-- entry must be supplied.
freqM :: [(Int, GenM a)] -> GenM a
freqM xs = do
  let live = [ (w, a) | (w, a) <- xs, w > 0 ]
      total = sum (map fst live)
  pick <- liftG (choose (1, total))
  go pick live
  where
    go _ [] = error "freqM: empty / all-zero weights"
    go k ((w, a) : rest)
      | k <= w    = a
      | otherwise = go (k - w) rest

-- | The whole-program generator: @main = e@, scaled by the QuickCheck size.
genProgram :: Gen CoreModule
genProgram = sized $ \sz -> do
  ty <- elements [GInt, GPair, GList, GRec]
  (body, _) <- runStateT (genExpr [] (max 1 (min sz 8)) ty) 0
  mainN <- pure (Name (T.pack "main") (Unique 1000000))
  pure (CoreModule [TopBind mainN [] body])

-- | Generate an ANF 'Expr' of result type @ty@ under typed environment @env@,
-- with a fuel budget @n@ bounding nesting depth. The environment lists in-scope
-- boxed/unboxed binders the leaves may reference.
genExpr :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genExpr env n ty
  | n <= 0    = Ret <$> genAtom env ty
  | otherwise =
      freqM
        [ (2, Ret <$> genAtom env ty)
        , (4, genLet env n ty)
        , (if scrutinizable env then 3 else 0, genCase env n ty)
        , (if n >= 3 then 3 else 0, genJoinCluster env n ty)
        , (if n >= 3 then 3 else 0, genClosureCluster env n ty)
        , (if n >= 3 then 3 else 0, genLetRecCaptureCluster env n ty)
        ]

-- | A 'let x = rhs in body' producing @ty@. The rhs produces some intermediate
-- type; the body (under x in scope) produces @ty@.
genLet :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genLet env n ty = do
  rhsTy <- liftG (elements [GInt, GPair, GList, GRec])
  (b, rhs) <- genRhs env (n - 1) rhsTy
  body <- genExpr ((bndName b, rhsTy) : env) (n - 1) ty
  pure (Let b rhs body)

-- | Generate a 'Let' binder of type @ty@ together with its (already-ANF) rhs.
genRhs :: [(Name, GTy)] -> Int -> GTy -> GenM (Binder, Rhs)
genRhs env _n ty = do
  b <- gBinder (hintFor ty) ty
  rhs <- case ty of
    GInt  -> genIntRhs env
    GPair -> do x <- genAtom env GInt
                y <- genAtom env GInt
                pure (RCon (T.pack "Tuple2") [x, y])
    GList -> freqM
               [ (1, pure (RCon (T.pack "Nil") []))
               , (3, do hd <- genAtom env GInt
                        tl <- genAtom env GList
                        pure (RCon (T.pack "Cons") [hd, tl])) ]
    GRec  -> do a <- genAtom env GInt
                c <- genAtom env GInt
                pure (RRecord recTyName [(T.pack "fst", a), (T.pack "snd", c)])
  pure (b, rhs)

-- | An integer-producing rhs: either a saturated binary prim over two int atoms,
-- a projection of a boxed value's int field, or a plain int atom.
genIntRhs :: [(Name, GTy)] -> GenM Rhs
genIntRhs env = do
  let projSources =
        [ (nm, lbl)
        | (nm, GRec) <- env, lbl <- [T.pack "fst", T.pack "snd"] ]
  freqM
    [ (4, do op <- liftG (elements [T.pack "+", T.pack "-", T.pack "*"])
             x  <- genAtom env GInt
             y  <- genAtom env GInt
             pure (RApp (primAtom op) [x, y]))
    , (if null projSources then 0 else 2,
         do (nm, lbl) <- liftG (elements projSources)
            pure (RProj lbl (AVar nm)))
    , (2, RAtom <$> genAtom env GInt)
    ]

-- | A 'case' scrutinizing an in-scope boxed value (Pair / List / Record) and
-- producing @ty@ in every alt. Every alt consumes the same owned set, exercising
-- the Perceus branch-reconciliation / own-children-drop-parent rules.
genCase :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genCase env n ty = do
  (scrut, scrutTy) <- liftG (elements (scrutCandidates env))
  case scrutTy of
    GPair -> do
      xb <- gBinder (T.pack "px") GInt
      yb <- gBinder (T.pack "py") GInt
      body <- genExpr ((bndName xb, GInt) : (bndName yb, GInt) : env) (n - 1) ty
      pure (Case (AVar scrut) [AltCon (T.pack "Tuple2") [xb, yb] body])
    GRec -> do
      -- A record has no constructor to match; scrutinize via a default alt that
      -- keeps the record live for projection in the body.
      body <- genExpr env (n - 1) ty
      pure (Case (AVar scrut) [AltDefault body])
    GList -> do
      hb   <- gBinder (T.pack "h") GInt
      tb   <- gBinder (T.pack "t") GList
      consBody <- genExpr ((bndName hb, GInt) : (bndName tb, GList) : env) (n - 1) ty
      nilBody  <- genExpr env (n - 1) ty
      pure (Case (AVar scrut)
              [ AltCon (T.pack "Cons") [hb, tb] consBody
              , AltCon (T.pack "Nil") [] nilBody ])
    GInt -> Ret <$> genAtom env ty   -- unreachable (filtered by scrutCandidates)

-- | Boxed in-scope binders usable as 'case' scrutinees.
scrutCandidates :: [(Name, GTy)] -> [(Name, GTy)]
scrutCandidates env = [ (nm, t) | (nm, t) <- env, t /= GInt ]

scrutinizable :: [(Name, GTy)] -> Bool
scrutinizable = not . null . scrutCandidates

-- | A trivial atom of the requested type: prefer an in-scope binder of that type,
-- otherwise a literal/constant. For 'GInt' a random small literal; for the boxed
-- types, a canonical empty/zero constant so a leaf always type-checks structurally.
genAtom :: [(Name, GTy)] -> GTy -> GenM Atom
genAtom env ty =
  let candidates = [ AVar nm | (nm, t) <- env, t == ty ]
  in case ty of
       GInt -> freqM
                 [ (3, ALit . LInt . toInteger <$> liftG (choose (0, 20 :: Int)))
                 , (if null candidates then 0 else 4, liftG (elements candidates))
                 ]
       _    -> if null candidates
                 then pure (constAtomFor ty)
                 else liftG (elements candidates)

-- | A canonical closed constant atom for a boxed type, used when no in-scope
-- binder of that type exists. These are LITERAL/nullary forms only (an atom must
-- be trivial); compound constants are introduced via 'genRhs' lets, so the only
-- nullary boxed constant we can express as a bare atom is the empty list 'Nil'...
-- which is itself a constructor, NOT an atom. Therefore boxed leaves fall back to
-- a unit literal sentinel only when truly unavoidable; in practice 'genExpr'
-- seeds boxed bindings via 'genLet' before requesting a boxed atom, so this path
-- is not hit for well-fuelled programs. To stay TOTAL we emit a zero int literal,
-- which is only ever reached at fuel 0 with an empty env and is harmless because
-- the differential compares whatever both interpreters produce identically.
constAtomFor :: GTy -> Atom
constAtomFor _ = ALit (LInt 0)

hintFor :: GTy -> Text
hintFor GInt  = T.pack "i"
hintFor GPair = T.pack "p"
hintFor GList = T.pack "xs"
hintFor GRec  = T.pack "r"

-- ---------------------------------------------------------------------------
-- Adversarial join clusters (Suite F, review #1 follow-up)
--
-- The base generator emits no joins, so the recurring "a var consumed somewhere
-- the dup/drop placement didn't see" bug class was unreachable by random programs:
--   * F1     -- a Case whose scrutinee is captured only by a join reached
--               TRANSITIVELY through a chain (reuse detection must close over it);
--   * #4     -- a join that owns a var only via the TRANSITIVE cap and so must
--               DROP it on a non-forwarding arm of its own body;
--   * §1     -- a join body that MOVES a captured var AND forwards onward to a
--               downstream join that also uses it (two consumers => a dup).
--
-- 'genJoinCluster' synthesizes a value-position case on a freshly-seeded boxed
-- capture whose continuation is a chain of joins capturing that var, directly in
-- ANF. It only owes STRUCTURAL validity (well-scoped, arity-correct jumps, covered
-- fragment); the existing triple oracle (differential output + heap-empty +
-- balanced, with a UAF/double-free trapped as a 'Left') checks that the PASS got
-- the reference counting right. Reverting any of the three fixes makes the
-- corresponding kind below fail at runtime (a leak or a trapped use-after-free).

-- | How an INTERMEDIATE join (one that is not the deepest in the chain) treats the
-- captured scrutinee. The deepest join always uses the capture (so it is in that
-- join's cap); the intermediates differ:
data IntermediateKind
  = PureForward     -- ^ body is a bare 'Jump' onward: the capture is reached only
                    --   TRANSITIVELY through the deepest join (exercises F1).
  | MoveForward     -- ^ body MOVES the capture into a dead binding then jumps on:
                    --   the capture lives in two places => a dup is required (§1).
  | BranchForward   -- ^ body is a 'Case' on its int param, one arm forwarding and
                    --   one not, so the capture (owned only via the transitive cap)
                    --   must be DROPPED on the non-forwarding arm (#4).
  deriving (Eq, Show)

-- | A fresh 'JoinId' from the same monotonic supply as binder names.
freshJoinId :: GenM JoinId
freshJoinId = state (\u -> (JoinId (Unique u), u + 1))

-- | Generate an adversarial join cluster producing @ty@. Seeds its own boxed
-- capture, so it needs nothing from @env@ and is available whenever there is fuel.
genJoinCluster :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genJoinCluster env n ty = do
  -- Pure-forward weighted twice so the F1 path is well represented.
  kind  <- liftG (elements [PureForward, PureForward, MoveForward, BranchForward])
  depth <- case kind of
             PureForward   -> liftG (choose (1, 3 :: Int))
             MoveForward   -> liftG (choose (2, 3 :: Int))
             BranchForward -> pure (2 :: Int)
  -- Seed a fresh non-empty capture list  s = Cons h Nil  (so the Cons arm runs).
  nilN <- freshN (T.pack "n0")
  sN   <- freshN (T.pack "s")
  hN   <- freshN (T.pack "h")
  tN   <- freshN (T.pack "t")
  h0   <- liftG (choose (0, 9 :: Int))
  jHead    <- freshJoinId
  restJids <- mapM (const freshJoinId) [2 .. depth]
  let jids = jHead : restJids
  params <- mapM (const (freshN (T.pack "r"))) jids
  let listTy  = gtyCType GList
      intTy   = gtyCType GInt
      -- BranchForward needs head arg 0 so j1's non-forwarding arm runs at runtime
      -- (review #4 shows up there as a leak); otherwise any nonzero forward arg.
      headArg = if kind == BranchForward then 0 else 1 :: Int
      armTo j = Jump j [ALit (LInt (toInteger headArg))]
      -- The capture is NOT referenced in the arms (it reaches the joins only
      -- through the cap) -- exactly the F1 trap.
      caseE   = Case (AVar sN)
                  [ AltCon (T.pack "Cons")
                      [Binder hN Unrestricted intTy, Binder tN Unrestricted listTy]
                      (armTo jHead)
                  , AltCon (T.pack "Nil") [] (armTo jHead) ]
      succs   = map Just restJids ++ [Nothing]   -- successor of each join; deepest -> Nothing
      triples = zip3 jids params succs
  -- Build each join body, then nest deepest-OUTERMOST (foldM: head ends innermost,
  -- delivering the Case; each later join wraps the accumulator).
  nest <- Control.Monad.foldM
            (\acc (jid, pN, mSucc) -> do
               body <- genJoinBody env n ty sN kind pN mSucc
               pure (LetJoin jid [Binder pN Unrestricted intTy] body acc))
            caseE
            triples
  pure $ Let (Binder nilN Unrestricted listTy) (RCon (T.pack "Nil") [])
       $ Let (Binder sN Unrestricted listTy)
             (RCon (T.pack "Cons") [ALit (LInt (toInteger h0)), AVar nilN])
       $ nest

-- | One join body. @mSucc = Nothing@ marks the deepest join (it captures @sN@ and
-- produces @ty@); otherwise it is an intermediate whose shape follows @kind@.
genJoinBody :: [(Name, GTy)] -> Int -> GTy -> Name -> IntermediateKind -> Name -> Maybe JoinId -> GenM Expr
genJoinBody env n ty sN kind pN mSucc =
  let listTy = gtyCType GList
  in case mSucc of
       Nothing -> do
         -- Deepest join: USE the capture (a dead Cons that moves it -> sN is in the
         -- cap), then produce @ty@ by the ordinary rules.
         capN  <- freshN (T.pack "cap")
         inner <- genExpr env (n - 1) ty
         pure (Let (Binder capN Unrestricted listTy)
                   (RCon (T.pack "Cons") [ALit (LInt 0), AVar sN]) inner)
       Just jn -> case kind of
         PureForward -> pure (Jump jn [ALit (LInt 1)])
         MoveForward -> do
           uN <- freshN (T.pack "u")
           pure (Let (Binder uN Unrestricted listTy)
                     (RCon (T.pack "Cons") [ALit (LInt 0), AVar sN])
                     (Jump jn [ALit (LInt 1)]))
         BranchForward -> do
           nf <- genExpr env (n - 1) ty     -- non-forwarding arm (does not use sN)
           pure (Case (AVar pN)
                   [ AltLit (LInt 0) nf
                   , AltDefault (Jump jn [ALit (LInt 1)]) ])

-- ---------------------------------------------------------------------------
-- Adversarial closure clusters (Suite F, M1.5 Task 6)
--
-- 'genClosureCluster' seeds a fresh boxed capture (a Pair of two ints), builds
-- an 'RLam' that captures and CONSUMES it via a 'Case', then exercises one of
-- four shapes that stress different RC obligations the Perceus pass must satisfy:
--
--   ClosureCallOnce   -- f built and called once; f and capture consumed by call
--   ClosureCallTwice  -- f called twice; pass must DUP f before the first call
--                       so the second call still has a live copy
--   ClosureDrop       -- f built and NEVER called; pass must DROP f (which
--                       cascades to the capture)
--   ClosureBranch     -- f built; one Case arm calls it, the other drops it;
--                       pass must balance dup/drop across the two arms
--
-- The closure body is always: @\x -> case cap of Tuple2 px py -> px@ (returns
-- the first int field, ignoring the unboxed param @x@).  The program result is
-- always GInt so the heap returns to baseline after a correct Perceus pass.

-- | The four structural shapes for 'genClosureCluster'.
data ClosureShape
  = ClosureCallOnce    -- ^ call f exactly once
  | ClosureCallTwice   -- ^ call f twice (forces a dup of the closure)
  | ClosureDrop        -- ^ build f and drop without calling (tests drop cascade)
  | ClosureBranch      -- ^ call f in one branch, drop in the other
  deriving (Eq, Show)

-- | Generate an adversarial closure cluster producing @ty@. Seeds its own
-- boxed capture, so it is self-contained and available whenever there is fuel.
-- The closure binder carries @'Ty.CTCon' ('Ty.TcUser' "Fun") []@ so 'isBoxedType'
-- tracks it as a heap-allocated cell (the same convention as 'closureModule').
genClosureCluster :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genClosureCluster env n ty = do
  shape <- liftG (elements [ClosureCallOnce, ClosureCallTwice, ClosureDrop, ClosureBranch])
  -- Seed the capture: a Pair of two random int literals.
  v0 <- liftG (choose (0, 9 :: Int))
  v1 <- liftG (choose (0, 9 :: Int))
  capN <- freshN (T.pack "cap")
  fN   <- freshN (T.pack "f")
  xN   <- freshN (T.pack "x")
  pxN  <- freshN (T.pack "fpx")
  pyN  <- freshN (T.pack "fpy")
  let pairTy = gtyCType GPair   -- CTCon (TcTuple 2) [U64, U64]  -- boxed
      funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []  -- boxed (catch-all)
      intTy  = gtyCType GInt    -- CTCon TcU64 []               -- unboxed
      capB   = Binder capN Unrestricted pairTy
      fB     = Binder fN  Unrestricted funTy
      xB     = Binder xN  Unrestricted intTy
      pxB    = Binder pxN Unrestricted intTy
      pyB    = Binder pyN Unrestricted intTy
      -- The closure body: consume cap via case, return first field.
      lamBody = Case (AVar capN)
                  [ AltCon (T.pack "Tuple2") [pxB, pyB]
                      (Ret (AVar pxN)) ]
      lam    = RLam [xB] lamBody
      -- One call of f with an unboxed arg; produces GInt.
      callF result body =
        Let (Binder result Unrestricted intTy)
            (RApp (AVar fN) [ALit (LInt 0)])
            body
  -- Build the closure-seeding prefix, then add the shape-specific continuation.
  let seedPrefix inner =
        Let capB (RCon (T.pack "Tuple2") [ALit (LInt (toInteger v0)), ALit (LInt (toInteger v1))])
          (Let fB lam inner)
  case shape of
    ClosureCallOnce -> do
      rN    <- freshN (T.pack "r")
      inner <- genExpr ((rN, GInt) : env) (n - 1) ty
      pure $ seedPrefix (callF rN inner)

    ClosureCallTwice -> do
      r1N   <- freshN (T.pack "r1")
      r2N   <- freshN (T.pack "r2")
      inner <- genExpr ((r2N, GInt) : (r1N, GInt) : env) (n - 1) ty
      pure $ seedPrefix
        (callF r1N (callF r2N inner))

    ClosureDrop -> do
      -- Never call f; Perceus must drop f (cascade to cap) at scope exit.
      -- Result comes from genExpr so ty is satisfied.
      inner <- genExpr env (n - 1) ty
      pure $ seedPrefix inner

    ClosureBranch -> do
      -- A Case where one arm CALLS f and the other DROPS it: the pass must
      -- instrument BOTH arms (dup-then-consume on the call arm, a drop on the
      -- non-calling arm) and balance them. The scrutinee is pinned to 0 so the
      -- CALL arm always runs at runtime (the double-free-on-f risk is the
      -- adversarial half worth executing every case; the drop arm is still
      -- statically instrumented and balanceLint-checked). Mirrors the
      -- 'BranchForward' precedent in 'genJoinCluster'.
      rN    <- freshN (T.pack "r")
      -- call arm: call f, bind result, continue
      callBody <- genExpr ((rN, GInt) : env) (n - 1) ty
      -- drop arm: f is NOT called; Perceus must drop it here
      dropBody <- genExpr env (n - 1) ty
      pure $ seedPrefix
        (Case (ALit (LInt 0))
          [ AltLit (LInt 0)      (callF rN callBody)
          , AltDefault            dropBody ])

-- ---------------------------------------------------------------------------
-- Adversarial LetRec capture clusters (Suite F, M1.5 Task 10)
--
-- 'genLetRecCaptureCluster' seeds a fresh boxed capture (a Pair of two ints),
-- builds a TWO-member MUTUALLY-RECURSIVE 'LetRec' group where BOTH members
-- capture it (it is free in both bodies, so capOcc=2), and exercises it
-- non-escapingly (the group is called once; the result is unboxed). The pass
-- instruments the capture-consuming base-case arm of BOTH members statically;
-- which arm actually fires at runtime depends on the call parity, but the RC
-- accounting (and 'balanceLint') must balance for both regardless.
--
-- STRUCTURAL INVARIANTS that make this adversarial:
--
--   SharedCapture  -- both members capture the SAME boxed local; the pass must
--                     emit one 'dup' of the capture (multiset accounting: need=2,
--                     dups=1). Reverting the dup plan empties it and causes a
--                     double-free / use-after-free detectable by the heap-empty
--                     oracle and 'balanceLint'.
--
-- The two members are TRULY MUTUALLY RECURSIVE (f calls g, g calls f) so the
-- elaborator/generator puts them in a SINGLE 'LetRec' node (not two nested
-- single-member groups, which would trigger the cross-region-capture deferral).
-- The group is NON-ESCAPING: the result is an unboxed GInt extracted by calling
-- 'f'; no member is returned, stored, or passed as a non-head argument.
--
-- Member bodies:
--   f kN1 = case kN1 of
--     0 -> case capN of Tuple2 pxN1 pyN1 -> pxN1   (consume cap, return int)
--     _ -> gN(kN1 - 1)                              (call sibling, mutual-rec)
--   g kN2 = case kN2 of
--     0 -> case capN of Tuple2 pxN2 pyN2 -> pyN2   (consume cap, return int)
--     _ -> fN(kN2 - 1)                              (call sibling, mutual-rec)
--
-- 'cap' is BORROWED inside each body (the pass adds it to ctxExempt for the
-- member scope): the case-on-cap destructs it structurally but no drop is
-- emitted inside. The drops come from the group's scope-exit drop cascade: one
-- member drop per capture occurrence => the multiset dup must supply two units.

-- | Generate an adversarial LetRec capture cluster producing @ty@. Seeds its
-- own boxed capture, so it is self-contained and available whenever there is
-- fuel. The result is always 'GInt' (unboxed), so the heap returns to baseline
-- after a correct Perceus pass.
genLetRecCaptureCluster :: [(Name, GTy)] -> Int -> GTy -> GenM Expr
genLetRecCaptureCluster env n ty = do
  -- Seed the capture: a Pair of two random int literals (the shared boxed local).
  v0   <- liftG (choose (0, 9 :: Int))
  v1   <- liftG (choose (0, 9 :: Int))
  capN <- freshN (T.pack "cap")
  fN   <- freshN (T.pack "lrf")
  gN   <- freshN (T.pack "lrg")
  kN1  <- freshN (T.pack "k1")
  kN2  <- freshN (T.pack "k2")
  ks1N <- freshN (T.pack "ks1")
  ks2N <- freshN (T.pack "ks2")
  pxN1 <- freshN (T.pack "px1")
  pyN1 <- freshN (T.pack "py1")
  pxN2 <- freshN (T.pack "px2")
  pyN2 <- freshN (T.pack "py2")
  r1N  <- freshN (T.pack "r1")
  r2N  <- freshN (T.pack "r2")
  rN   <- freshN (T.pack "lrr")
  let pairTy = gtyCType GPair   -- boxed Pair
      intTy  = gtyCType GInt    -- unboxed U64
      capB   = Binder capN Unrestricted pairTy
      fB     = Binder fN   Unrestricted intTy   -- result type (not arrow)
      gB     = Binder gN   Unrestricted intTy
      kB1    = Binder kN1  Unrestricted intTy
      kB2    = Binder kN2  Unrestricted intTy
      ks1B   = Binder ks1N Unrestricted intTy
      ks2B   = Binder ks2N Unrestricted intTy
      pxB1   = Binder pxN1 Unrestricted intTy
      pyB1   = Binder pyN1 Unrestricted intTy
      pxB2   = Binder pxN2 Unrestricted intTy
      pyB2   = Binder pyN2 Unrestricted intTy
      r1B    = Binder r1N  Unrestricted intTy
      r2B    = Binder r2N  Unrestricted intTy
      rB     = Binder rN   Unrestricted intTy
      -- Body of f: case k of 0 -> case cap of Tuple2 px py -> px
      --                       _ -> let ks = k - 1; r = g(ks); r
      -- capN and gN are free in this body: capN is the shared boxed capture,
      -- gN is a sibling (exempt, never dup'd/drop'd inside).
      fBody  = Case (AVar kN1)
                 [ AltLit (LInt 0)
                     (Case (AVar capN)
                       [ AltCon (T.pack "Tuple2") [pxB1, pyB1]
                           (Ret (AVar pxN1)) ])
                 , AltDefault
                     (Let ks1B (RApp (primAtom (T.pack "-"))
                                     [AVar kN1, ALit (LInt 1)])
                       (Let r1B (RApp (AVar gN) [AVar ks1N])
                         (Ret (AVar r1N)))) ]
      -- Body of g: case k of 0 -> case cap of Tuple2 px py -> py
      --                       _ -> let ks = k - 1; r = f(ks); r
      -- capN and fN are free in this body.
      gBody  = Case (AVar kN2)
                 [ AltLit (LInt 0)
                     (Case (AVar capN)
                       [ AltCon (T.pack "Tuple2") [pxB2, pyB2]
                           (Ret (AVar pyN2)) ])
                 , AltDefault
                     (Let ks2B (RApp (primAtom (T.pack "-"))
                                     [AVar kN2, ALit (LInt 1)])
                       (Let r2B (RApp (AVar fN) [AVar ks2N])
                         (Ret (AVar r2N)))) ]
  -- The continuation uses rN (a GInt) and proceeds to produce @ty@.
  inner <- genExpr ((rN, GInt) : env) (n - 1) ty
  pure $
    -- seed the shared boxed capture
    Let capB (RCon (T.pack "Tuple2")
                   [ALit (LInt (toInteger v0)), ALit (LInt (toInteger v1))]) $
    -- the two-member mutually-recursive group (f calls g, g calls f => truly mutual)
    LetRec
      [ (fB, [kB1], fBody)
      , (gB, [kB2], gBody) ]
    -- non-escaping call: result is unboxed; no member is returned or stored
    (Let rB (RApp (AVar fN) [ALit (LInt 2)]) inner)

-- ---------------------------------------------------------------------------
-- Suite G: M2a-1 owned/borrowed + escape property generator (this slice)
--
-- The four M2a-1 holes (alias double-free, escaping-alias, direct sibling-escape
-- via con/call, local-drop of sibling-in-con) all survived because Suite F's
-- generators NEVER produce the M2a-1 shapes: a LetRec member CONSUMING an
-- enclosing capture, a standalone closure capturing a LetRec sibling that
-- ESCAPES, a sibling moved DIRECTLY into a con/record/call-arg, or an ALIAS of a
-- sibling. This generator emits exactly those shapes, in BOTH the non-escaping
-- (must be ACCEPTED by the boundary guard AND run sound) and escaping (must be
-- REJECTED) variants, directly in ANF (mirroring the test/rc-m2a1/33-50 corpus).
--
-- The PROOF (prop_m2a1Escape): for every generated program p, if the boundary
-- guard 'firstOrderNoHandlerViolations' ACCEPTS p, then the RC run via
-- 'runModuleRCUnchecked (insertRC (pruneToReachable cm))' MUST succeed, be
-- heap-balanced (stLive == baseline AND stAllocs - stFrees == baseline), AND
-- match the reference interpreter. A wrongly-ACCEPTED escaping shape would
-- surface here as a leak, a use-after-free / double-free 'Left', or a value
-- mismatch. If the guard REJECTS p the run assertion is skipped (rejection is
-- the conservative, always-sound verdict). Two supporting properties pin the
-- static oracle: 'balanceLint' must be clean on every IN-FRAGMENT program, and
-- every single-site RC mutation (OmitOneDrop / OmitOneDup / DuplicateOneDrop)
-- must be CAUGHT (a non-empty 'lintInstrumented' or a trapped runtime 'Left').
--
-- IMPORTANT DESIGN NOTE on what "escapes" means here. The boundary guard's
-- escape walkers ('rlamSiblingCaptureEscapes', 'letRecMemberEscapes') run over a
-- single bind body. A value RETURNED from 'main' (Ret (AVar h)) IS an escape
-- (goE (Ret a) = hit a), and a value sealed into a returned con/record likewise.
-- So we build everything inside 'main''s body and drive the verdict by whether
-- the captured value flows OUT (return / con / record / call-arg / nested
-- closure) or stays LOCAL (dropped unused, or only called in place). The
-- non-escaping variants always produce a GInt result so a sound pass empties the
-- heap; the escaping variants are only checked for the REJECT verdict, so their
-- result type is unconstrained.

-- | The five M2a-1 shape families this generator ranges over. Each is realized
-- in a non-escaping (ACCEPT) and an escaping (REJECT) variant where applicable.
data M2a1Shape
  = M2ConsumeCapture       -- ^ LetRec member CONSUMES (moves) an enclosing capture
  | M2ClosureSibling       -- ^ standalone closure ('RLam') captures a LetRec sibling
  | M2DirectSibling        -- ^ sibling moved DIRECTLY into con / record / call-arg / proj
  | M2AliasSibling         -- ^ alias ('let x = f') of a sibling, incl. transitive
  | M2Mixed                -- ^ capture-an-enclosing-local + an escaping member; nested
  | M2MemberBodyEscape     -- ^ a member's BASE or REC arm RETURNS / MOVES a sibling
                           --   (the BLOCKER-1 member-body escape: the shared env is
                           --   carried OUT from INSIDE a member body, where the body
                           --   borrows --- not owns --- the env). The escaped member
                           --   is then called externally, so the run must be sound.
  | M2PartialMember        -- ^ a MULTI-ARITY recursive member that captures an
                           --   enclosing local, applied at PARTIAL / SATURATED / OVER
                           --   saturation. PARTIAL is the M2a-2 double-free shape (the
                           --   LT path of 'enterRC's 'RVRecMember' arm): @mk u = let
                           --   f a b = ... u ... in f@; @main = let g = mk 7 in let h =
                           --   g 0 in h 2@. The result is a scalar (heap must empty),
                           --   so it is ACCEPT-and-run-sound.
  | M2CaptureBodyEscape    -- ^ a member body ESCAPES a borrowed enclosing CAPTURE: it
                           --   RETURNS the captured boxed value directly, or SEALS it
                           --   into a returned con. The capture is moved into the shared
                           --   env once; the escaping handle must dup the captured cell
                           --   (the 'Ret'/con-move escape-dup) so the env cascade frees
                           --   it exactly once. The escaped capture is then destructured
                           --   externally to a scalar, so the heap must empty =>
                           --   ACCEPT-and-run-sound. The CAPTURE analogue of
                           --   'M2MemberBodyEscape' (which escapes a SIBLING).
  | M2CaptureCallHead      -- ^ a member body CALLS an enclosing boxed FUNCTION capture
                           --   @g@ as a (saturated or partial) call HEAD (@g k@). A call
                           --   head is a BORROW under uniform borrow-on-call, NOT a
                           --   move/consume, so the group is ACCEPT-and-run-sound. This
                           --   is the regression family for the call-head over-rejection
                           --   ('consumingOccs' used to count the head); the capture is
                           --   never escaped (result is a scalar) so the heap must empty.
  | M2CrossRegion          -- ^ an INNER 'LetRec' group nested inside an OUTER group's
                           --   member body, whose inner member captures an OUTER group
                           --   MEMBER BINDER (a cross-region counted edge: @rawEnclosingFv
                           --   ∩ lr@, where @lr@ is the outer region's binders). The pass
                           --   excludes this from coverage (spec 5.5) so it is DEFERRED
                           --   and REJECTED at the boundary by the cross-region fence
                           --   ('crossRegionViol'). This is the GENERATIVE coverage for
                           --   that fence (previously 0 fires across Suite G); a 'cover'
                           --   below pins that the class is generated AND rejected, so a
                           --   regression that stops rejecting cross-region goes red.
  deriving (Eq, Show)

-- | How the captured / aliased value flows, deciding the boundary verdict.
data M2Flow
  = FlowDropLocal          -- ^ value stays local (dropped unused / called in place): ACCEPT
  | FlowReturn             -- ^ value RETURNED from main: ESCAPE => REJECT
  | FlowCon                -- ^ value sealed into a returned constructor field: ESCAPE
  | FlowRecord             -- ^ value sealed into a returned record field: ESCAPE
  | FlowList               -- ^ value sealed into a returned list cell: ESCAPE
  | FlowCallArg            -- ^ value passed as a non-head call argument that escapes: ESCAPE
  | FlowNestedClosure      -- ^ value captured by a nested closure that escapes: ESCAPE
  | FlowReturnThenCall     -- ^ closure routed through an unnamed intermediate then
                           --   OVER-APPLIED (the corpus-36 @(mk u) 2@ path): exercises
                           --   the deferred-consume ('KDropCellRC') so the escaped
                           --   closure's env survives its own call. Yields a scalar
                           --   (the call result), so it is LOCAL/ACCEPT and runs sound.
  deriving (Eq, Show)

-- | The boxed catch-all type carried by a closure / sibling-function binder, so
-- 'isBoxedType' tracks it as a heap cell (same convention as 'closureModule' and
-- 'genClosureCluster').
funTyC :: Ty.CType
funTyC = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []

-- | A boxed single-field constructor type used as an escape vehicle.
boxTyC :: Ty.CType
boxTyC = Ty.CTCon (Ty.TcUser (T.pack "Box")) []

-- | The whole-program generator for the M2a-1 suite: @main = e@ where @e@ is one
-- of the five shape families. Sized by the QuickCheck size for the inner
-- continuation depth.
genM2a1Program :: Gen CoreModule
genM2a1Program = sized $ \sz -> do
  shape <- elements [M2ConsumeCapture, M2ClosureSibling, M2DirectSibling, M2AliasSibling, M2Mixed
                    , M2MemberBodyEscape, M2PartialMember, M2CaptureBodyEscape, M2CaptureCallHead
                    , M2CrossRegion]
  (body, _) <- runStateT (genM2a1Cluster shape (max 1 (min sz 6))) 0
  let mainN = Name (T.pack "main") (Unique 1000000)
  pure (CoreModule [TopBind mainN [] body])

-- | Dispatch on the shape family. @n@ is the inner-continuation fuel.
genM2a1Cluster :: M2a1Shape -> Int -> GenM Expr
genM2a1Cluster shape n = case shape of
  M2ConsumeCapture -> genConsumeCaptureCluster n
  M2ClosureSibling -> genClosureSiblingCluster n
  M2DirectSibling  -> genDirectSiblingCluster n
  M2AliasSibling   -> genAliasSiblingCluster n
  M2Mixed          -> genMixedCluster n
  M2MemberBodyEscape -> genMemberBodyEscapeCluster n
  M2PartialMember  -> genPartialMemberCluster n
  M2CaptureBodyEscape -> genCaptureBodyEscapeCluster n
  M2CaptureCallHead -> genCaptureCallHeadCluster n
  M2CrossRegion    -> genCrossRegionCluster n

-- | Build a two-member, TRULY mutually-recursive 'LetRec' group (f calls g, g
-- calls f, so the elaborator would put them in ONE group node). The caller
-- supplies the per-member base-case body (fired when the int param is 0); the
-- recursive arm always calls the sibling. The boxed locals @capN@ (an enclosing
-- capture) and the sibling names are free in the bodies exactly as the corpus
-- shapes require. Returns the group binders and the assembled 'LetRec' wrapper
-- that takes the continuation (the expression following the group).
--
-- @mkFBase@ / @mkGBase@ receive the capture binder name and the sibling name so
-- they can either BORROW (case cap) or CONSUME (move cap) it. The recursive arm
-- is fixed: @_ -> let ks = k - 1; r = <sibling>(ks); r@.
genMutualGroup
  :: Name                                  -- ^ enclosing boxed capture in scope
  -> (Name -> Name -> GenM Expr)           -- ^ f base body, given (capN, siblingG)
  -> (Name -> Name -> GenM Expr)           -- ^ g base body, given (capN, siblingF)
  -> GenM (Name, Name, Expr -> Expr)
genMutualGroup capN mkFBase mkGBase = do
  fN  <- freshN (T.pack "lrf")
  gN  <- freshN (T.pack "lrg")
  kN1 <- freshN (T.pack "k1")
  kN2 <- freshN (T.pack "k2")
  ks1 <- freshN (T.pack "ks1")
  ks2 <- freshN (T.pack "ks2")
  r1  <- freshN (T.pack "r1")
  r2  <- freshN (T.pack "r2")
  let intTy = gtyCType GInt
      kB1   = Binder kN1 Unrestricted intTy
      kB2   = Binder kN2 Unrestricted intTy
  fBase <- mkFBase capN gN
  gBase <- mkGBase capN fN
  let recArmF =
        Let (Binder ks1 Unrestricted intTy)
            (RApp (primAtom (T.pack "-")) [AVar kN1, ALit (LInt 1)])
          (Let (Binder r1 Unrestricted intTy) (RApp (AVar gN) [AVar ks1])
            (Ret (AVar r1)))
      recArmG =
        Let (Binder ks2 Unrestricted intTy)
            (RApp (primAtom (T.pack "-")) [AVar kN2, ALit (LInt 1)])
          (Let (Binder r2 Unrestricted intTy) (RApp (AVar fN) [AVar ks2])
            (Ret (AVar r2)))
      fBody = Case (AVar kN1) [AltLit (LInt 0) fBase, AltDefault recArmF]
      gBody = Case (AVar kN2) [AltLit (LInt 0) gBase, AltDefault recArmG]
      wrap cont = LetRec [(Binder fN Unrestricted intTy, [kB1], fBody)
                         ,(Binder gN Unrestricted intTy, [kB2], gBody)] cont
  pure (fN, gN, wrap)

-- | A surface prim atom (e.g. a binary integer op). The elaborator routes every
-- prelude @extern@ to an 'APrim' carrying its @(module, name)@ identity; these
-- hand-built RC/interpreter fixtures mirror that so the interpreters resolve them
-- by the name part (Caveat B). The module label is cosmetic at runtime (lookup is
-- name-keyed) -- 'Base' is where these arithmetic/comparison prims live.
primAtom :: Text -> Atom
primAtom op = APrim (T.pack "Base", op)

-- | Seed a boxed Pair capture from two random int literals, returning its binder
-- name and a wrapper that prefixes the seeding 'Let'.
seedPairCapture :: GenM (Name, Expr -> Expr)
seedPairCapture = do
  v0 <- liftG (choose (0, 9 :: Int))
  v1 <- liftG (choose (0, 9 :: Int))
  capN <- freshN (T.pack "cap")
  let capB = Binder capN Unrestricted (gtyCType GPair)
      wrap cont = Let capB (RCon (T.pack "Tuple2")
                                 [ALit (LInt (toInteger v0)), ALit (LInt (toInteger v1))]) cont
  pure (capN, wrap)

-- ---------------------------------------------------------------------------
-- Family 1: LetRec member CONSUMES an enclosing boxed capture.
--
-- The base case MOVES the capture (passes it to a call / stores it in a con or
-- record / returns it), which is a CONSUMING use; the pass must emit a build-site
-- dup per consuming use so the move owns its unit and the group cascade keeps its
-- own. NON-escaping: the group is called in place and the result is the scalar
-- extracted; the group never escapes => ACCEPT, heap must empty. We also exercise
-- multi-branch ('Case') consumption and value-position 'if'/'case' (which the
-- elaborator lowers to joins; we emit the join form directly).
genConsumeCaptureCluster :: Int -> GenM Expr
genConsumeCaptureCluster n = do
  (capN, seedCap) <- seedPairCapture
  -- How each base body consumes the capture.
  consumeStyle <- liftG (elements [ConsumeMoveToCon, ConsumeMoveToRecord, ConsumeMultiBranch, ConsumeValueCase])
  let intTy = gtyCType GInt
  -- A consuming base body that yields a GInt: it MOVES the Pair capture into a
  -- cell (con / record), then destructures the cell back to an int. Storing the
  -- Pair into the cell is the CONSUMING move the pass must dup-cover; the cell is
  -- then fully consumed locally (the result is the scalar), so the group + the
  -- dup accounting must balance.
  let consumeBody pickField capArg = case consumeStyle of
        ConsumeMoveToCon -> consumeViaBox pickField capArg
        ConsumeMoveToRecord -> do
          -- seal cap into a record field (move), then read the field back (RProj on
          -- a RECORD is valid) and case-destructure the Pair.
          recN <- freshN (T.pack "rc")
          capBackN <- freshN (T.pack "cb")
          pxN <- freshN (T.pack "px")
          pyN <- freshN (T.pack "py")
          pure (Let (Binder recN Unrestricted capCellRecTy)
                    (RRecord capCellRecName [(T.pack "p", AVar capArg)])
                  (Let (Binder capBackN Unrestricted (gtyCType GPair))
                       (RProj (T.pack "p") (AVar recN))
                    (Case (AVar capBackN)
                       [ AltCon (T.pack "Tuple2")
                           [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                           (Ret (AVar (if pickField then pxN else pyN))) ])))
        ConsumeMultiBranch -> do
          -- a Case on a fresh int, BOTH arms consuming cap (move into a box, then
          -- destructure picking different fields). cap is consumed on every arm.
          sN <- freshN (T.pack "sel")
          armA <- consumeViaBox True capArg
          armB <- consumeViaBox False capArg
          pure (Let (Binder sN Unrestricted intTy) (RAtom (ALit (LInt 0)))
                  (Case (AVar sN) [ AltLit (LInt 0) armA, AltDefault armB ]))
        ConsumeValueCase -> do
          -- value-position case lowered to a join: a join j(x) delivers the
          -- result; a Case feeds it, and cap is consumed (moved into a box and
          -- destructured) in the arm feeding the join.
          jId <- freshJoinId
          pN  <- freshN (T.pack "jp")
          sN  <- freshN (T.pack "vsel")
          feedDirect <- consumeViaBoxJumping pickField capArg jId
          pure (LetJoin jId [Binder pN Unrestricted intTy] (Ret (AVar pN))
                  (Let (Binder sN Unrestricted intTy) (RAtom (ALit (LInt 0)))
                    (Case (AVar sN) [AltDefault feedDirect])))
  (fN, _gN, wrapGroup) <-
    genMutualGroup capN
      (\c _g -> consumeBody True c)
      (\c _g -> consumeBody False c)
  rN <- freshN (T.pack "lrr")
  let rB = Binder rN Unrestricted intTy
  -- non-escaping call: the result is unboxed; no member is returned or stored.
  cont <- genExpr [(rN, GInt)] (n - 1) GInt
  pure $ seedCap $ wrapGroup
    (Let rB (RApp (AVar fN) [ALit (LInt 2)]) cont)

-- | The consuming styles for family 1. Each performs a valid CONSUMING MOVE of
-- the Pair capture (storing it into a con / record cell), then destructures the
-- cell back to a scalar locally.
data ConsumeStyle
  = ConsumeMoveToCon
  | ConsumeMoveToRecord
  | ConsumeMultiBranch
  | ConsumeValueCase
  deriving (Eq, Show)

-- | Consume the Pair @capArg@ by moving it into a single-field 'Box' con, then
-- destructuring the box and the Pair to yield an int (the chosen field). The
-- @RCon "Box" [cap]@ is the consuming move; the box is fully consumed locally.
consumeViaBox :: Bool -> Name -> GenM Expr
consumeViaBox pickField capArg = do
  let intTy = gtyCType GInt
  boxN <- freshN (T.pack "bx")
  capBackN <- freshN (T.pack "cback")
  pxN <- freshN (T.pack "px")
  pyN <- freshN (T.pack "py")
  pure (Let (Binder boxN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar capArg])
          (Case (AVar boxN)
            [ AltCon (T.pack "Box") [Binder capBackN Unrestricted (gtyCType GPair)]
                (Case (AVar capBackN)
                  [ AltCon (T.pack "Tuple2")
                      [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                      (Ret (AVar (if pickField then pxN else pyN))) ]) ]))

-- | As 'consumeViaBox', but instead of returning the extracted int it JUMPS to
-- @jId@ with it (used to feed a value-position join). Same consuming move.
consumeViaBoxJumping :: Bool -> Name -> JoinId -> GenM Expr
consumeViaBoxJumping pickField capArg jId = do
  let intTy = gtyCType GInt
  boxN <- freshN (T.pack "bx")
  capBackN <- freshN (T.pack "cback")
  pxN <- freshN (T.pack "px")
  pyN <- freshN (T.pack "py")
  pure (Let (Binder boxN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar capArg])
          (Case (AVar boxN)
            [ AltCon (T.pack "Box") [Binder capBackN Unrestricted (gtyCType GPair)]
                (Case (AVar capBackN)
                  [ AltCon (T.pack "Tuple2")
                      [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                      (Jump jId [AVar (if pickField then pxN else pyN)]) ]) ]))

-- ---------------------------------------------------------------------------
-- Family 9: a member body CALLS an enclosing boxed FUNCTION capture as a HEAD.
--
-- Seed a boxed function capture @g@ (a lambda of 'funTyC', so 'isBoxedType' tracks
-- it as a heap cell and it lands in the boundary's @bsc@), then build a recursive
-- group whose base bodies CALL @g@ as the call HEAD --- saturated (@g k@) or
-- partial (@(g k) 1@, @g@ a two-arg lambda). A call head is a BORROW under uniform
-- borrow-on-call, NOT a move/consume, so the group is ADMITTED and runs SOUND. The
-- capture never escapes (the result is a scalar), so the heap must empty. This is
-- the GENERATIVE regression guard for the call-head over-rejection: before the fix
-- 'consumingOccs' counted the head, and the non-escaping group was wrongly
-- REJECTED.
genCaptureCallHeadCluster :: Int -> GenM Expr
genCaptureCallHeadCluster n = do
  partial <- liftG (elements [False, True])
  let intTy = gtyCType GInt
  gN <- freshN (T.pack "gcap")
  -- The captured function. Saturated variant: @\x -> x + 1@ (arity 1). Partial
  -- variant: @\a b -> a + b@ (arity 2), called partially as a head below.
  gBody <-
    if partial
      then do
        aN <- freshN (T.pack "ga")
        bN <- freshN (T.pack "gb")
        sN <- freshN (T.pack "gs")
        pure (RLam [Binder aN Unrestricted intTy, Binder bN Unrestricted intTy]
                (Let (Binder sN Unrestricted intTy)
                     (RApp (primAtom (T.pack "+")) [AVar aN, AVar bN])
                  (Ret (AVar sN))))
      else do
        xN <- freshN (T.pack "gx")
        sN <- freshN (T.pack "gs")
        pure (RLam [Binder xN Unrestricted intTy]
                (Let (Binder sN Unrestricted intTy)
                     (RApp (primAtom (T.pack "+")) [AVar xN, ALit (LInt 1)])
                  (Ret (AVar sN))))
  let gB = Binder gN Unrestricted funTyC
      -- The base body CALLS @g@ as a HEAD on an int literal (a borrow, never a
      -- move). Saturated: @r = g 0; r@. Partial: @t = g 0; r = t 1; r@. The base
      -- body does not receive the member's int param, so we feed a literal --- the
      -- point under test is purely that the call HEAD @g@ is a borrow.
      callHeadBase capN =
        if partial
          then do
            tN <- freshN (T.pack "ct")
            rN <- freshN (T.pack "cr")
            pure (Let (Binder tN Unrestricted funTyC) (RApp (AVar capN) [ALit (LInt 0)])
                    (Let (Binder rN Unrestricted intTy) (RApp (AVar tN) [ALit (LInt 1)])
                      (Ret (AVar rN))))
          else do
            rN <- freshN (T.pack "cr")
            pure (Let (Binder rN Unrestricted intTy) (RApp (AVar capN) [ALit (LInt 0)])
                    (Ret (AVar rN)))
  (fN, _gN2, wrapGroup) <-
    genMutualGroup gN
      (\c _g -> callHeadBase c)
      (\c _g -> callHeadBase c)
  rN <- freshN (T.pack "lrr")
  let rB = Binder rN Unrestricted intTy
  -- non-escaping call: the result is the scalar; no member escapes.
  cont <- genExpr [(rN, GInt)] (n - 1) GInt
  pure $ Let gB gBody $ wrapGroup
    (Let rB (RApp (AVar fN) [ALit (LInt 2)]) cont)

-- ---------------------------------------------------------------------------
-- Family 10: CROSS-REGION capture (the cross-region #3 fence, DEFERRED/REJECTED).
--
-- An OUTER two-member group @(oF, oG)@; INSIDE @oF@'s member body sits an INNER
-- self-recursive group @inr@ whose member body REFERENCES @oG@ --- an OUTER group
-- MEMBER BINDER. That is a cross-region COUNTED EDGE: at the inner 'LetRec' node the
-- in-scope region set @lr@ is exactly @{oF, oG}@, and @rawEnclosingFv inr@ contains
-- @oG@, so @rawEnclosingFv inr ∩ lr@ is non-empty and 'crossRegionViol' fires. The
-- pass excludes a member that captures an outer region member from coverage (spec
-- 5.5 'capturesRegion') and an un-instrumented pass-through would LEAK, so the class
-- is DEFERRED and REJECTED at the boundary.
--
-- This is the ONLY Suite G family that produces cross-region shapes (0 fires across
-- the other families). It is always a REJECT, so 'prop_m2a1Escape' merely skips the
-- run; the teeth are the dedicated 'cover' in the property that the class is
-- GENERATED AND REJECTED (so a regression that stops rejecting cross-region goes
-- red). We vary HOW the inner member references the outer member @oG@: as a SATURATED
-- call head, or as a non-head call ARGUMENT (both put @oG@ in 'rawEnclosingFv').
genCrossRegionCluster :: Int -> GenM Expr
genCrossRegionCluster _n = do
  refAsArg <- liftG (elements [False, True])
  let intTy = gtyCType GInt
  oFN <- freshN (T.pack "ocrf")
  oGN <- freshN (T.pack "ocrg")
  okN1 <- freshN (T.pack "ock1")
  okN2 <- freshN (T.pack "ock2")
  -- The inner self-recursive group, nested in @oF@'s body. Its base body references
  -- the OUTER member @oG@ (the cross-region edge): either as a saturated call head
  -- @oG 0@, or as a non-head argument to a different call.
  inN <- freshN (T.pack "incr")
  inkN <- freshN (T.pack "ink")
  inrN <- freshN (T.pack "inr")
  inrsN <- freshN (T.pack "inrs")
  let innerBase =
        if refAsArg
          then
            -- seal @oG@ (the outer member) into a 'Box' con as a non-head field ---
            -- still a free var of the body => in rawEnclosingFv => cross-region.
            Let (Binder inrN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar oGN])
              (Ret (ALit (LInt 0)))
          else
            -- call the OUTER member @oG@ as a saturated head.
            Let (Binder inrN Unrestricted intTy) (RApp (AVar oGN) [ALit (LInt 0)])
              (Ret (AVar inrN))
      innerRec =
        Let (Binder inrsN Unrestricted intTy)
            (RApp (primAtom (T.pack "-")) [AVar inkN, ALit (LInt 1)])
          (Let (Binder inrN Unrestricted intTy) (RApp (AVar inN) [AVar inrsN])
            (Ret (AVar inrN)))
      innerBody = Case (AVar inkN) [AltLit (LInt 0) innerBase, AltDefault innerRec]
      innerGroupBody =
        LetRec [(Binder inN Unrestricted intTy, [Binder inkN Unrestricted intTy], innerBody)]
          (Let (Binder inrN Unrestricted intTy) (RApp (AVar inN) [ALit (LInt 0)])
            (Ret (AVar inrN)))
      -- @oF@'s body holds the inner group; @oG@ is a trivial base.
      oFBody = innerGroupBody
      oGBody = Ret (ALit (LInt 0))
      outer cont =
        LetRec [ (Binder oFN Unrestricted intTy, [Binder okN1 Unrestricted intTy], oFBody)
               , (Binder oGN Unrestricted intTy, [Binder okN2 Unrestricted intTy], oGBody) ]
               cont
  rN <- freshN (T.pack "ocrr")
  pure $ outer
    (Let (Binder rN Unrestricted intTy) (RApp (AVar oFN) [ALit (LInt 0)])
      (Ret (AVar rN)))

-- | The record type / name used as a Pair-capture cell vehicle.
capCellRecName :: Text
capCellRecName = T.pack "PCell"

capCellRecTy :: Ty.CType
capCellRecTy = Ty.CTRecord capCellRecName Ty.CREmpty

-- | Build the CORPUS-style single self-recursive 'LetRec' member that captures an
-- UNBOXED enclosing local (a fresh @U64@ seed @u@, exactly like corpus 36/42/etc:
-- @f n = case n of 0 -> u ; _ -> f (n - 1)@). Because the captured local is
-- UNBOXED, the group does NOT trip 'letRecCapturesEnclosing' (which only watches
-- BOXED enclosing locals), so the group itself is admitted and the boundary
-- verdict is driven SOLELY by how the sibling @f@ flows downstream (closure /
-- cell / alias). Returns the sibling binder name and a wrapper that seeds @u@ and
-- the group, taking the continuation (the expression following the group).
--
-- M2a-2 BLOCKER 2 NOTE: this group is NOT capture-free. The counted-env predicate
-- is "captures ANY bound enclosing local, boxed or unboxed", so the runtime
-- allocates ONE counted 'NEnv' holding @u@ (the member body resolves @u@ from it),
-- dropped exactly once via the pass's member-0 env unit. "Capture-free => sentinel"
-- applies only when the capture union is EMPTY (no enclosing local at all).
genSiblingGroup :: GenM (Name, Expr -> Expr)
genSiblingGroup = do
  seed <- liftG (choose (0, 9 :: Int))
  uN  <- freshN (T.pack "u")
  fN  <- freshN (T.pack "lrf")
  nN  <- freshN (T.pack "fn")
  ksN <- freshN (T.pack "fks")
  rN  <- freshN (T.pack "frr")
  let intTy = gtyCType GInt
      fBody = Case (AVar nN)
                [ AltLit (LInt 0) (Ret (AVar uN))
                , AltDefault
                    (Let (Binder ksN Unrestricted intTy)
                         (RApp (primAtom (T.pack "-")) [AVar nN, ALit (LInt 1)])
                       (Let (Binder rN Unrestricted intTy) (RApp (AVar fN) [AVar ksN])
                         (Ret (AVar rN)))) ]
      wrap cont =
        Let (Binder uN Unrestricted intTy) (RAtom (ALit (LInt (toInteger seed))))
          (LetRec [(Binder fN Unrestricted intTy, [Binder nN Unrestricted intTy], fBody)] cont)
  pure (fN, wrap)

-- | As 'genSiblingGroup', but the self-recursive member captures a BOXED enclosing
-- local (a fresh @Tuple2@ @cap@) instead of an unboxed @u@. The base case
-- destructures @cap@ to a scalar. Because the capture is BOXED, the group's shared
-- env is a real COUNTED 'NEnv' cell (not the capture-free sentinel), so a closure
-- that captures the sibling @f@ and escapes must DUP that env --- exercising the
-- dup-on-closure-capture + the escaped closure's cascade-drop balance. (The unboxed
-- 'genSiblingGroup' ALSO allocates a counted 'NEnv' holding @u@ --- BLOCKER 2: the
-- env exists for any enclosing capture, boxed or unboxed; only a group with NO
-- enclosing capture at all uses the sentinel. The boxed variant differs in that its
-- captured field is itself reference-counted, so the cascade decrefs a heap child.) The base
-- case only READS @cap@ (a borrowed scrutinee keeping no boxed child), so the group
-- is NOT a consuming-capture (#1) reject; the verdict is driven purely by how the
-- sibling @f@ flows downstream. NOTE: the group itself captures a boxed enclosing
-- local, so a BARE escape of @f@ would trip Part B (escapeViol) --- but a CLOSURE
-- escape is exempt (escapeViol uses the bare-only predicate), exactly the Stage A
-- frontier under test.
genSiblingGroupBoxed :: GenM (Name, Expr -> Expr)
genSiblingGroupBoxed = do
  (capN, seedCap) <- seedPairCapture
  fN  <- freshN (T.pack "lrf")
  nN  <- freshN (T.pack "fn")
  ksN <- freshN (T.pack "fks")
  rN  <- freshN (T.pack "frr")
  pxN <- freshN (T.pack "px")
  pyN <- freshN (T.pack "py")
  let intTy = gtyCType GInt
      -- base case: case cap of Tuple2 px py -> px  (a borrowed read of cap; the
      -- boxed children px/py are unboxed ints, so cap is NOT consumed)
      baseBody = Case (AVar capN)
                   [ AltCon (T.pack "Tuple2")
                       [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                       (Ret (AVar pxN)) ]
      fBody = Case (AVar nN)
                [ AltLit (LInt 0) baseBody
                , AltDefault
                    (Let (Binder ksN Unrestricted intTy)
                         (RApp (primAtom (T.pack "-")) [AVar nN, ALit (LInt 1)])
                       (Let (Binder rN Unrestricted intTy) (RApp (AVar fN) [AVar ksN])
                         (Ret (AVar rN)))) ]
      wrap cont =
        seedCap (LetRec [(Binder fN Unrestricted intTy, [Binder nN Unrestricted intTy], fBody)] cont)
  pure (fN, wrap)

-- ---------------------------------------------------------------------------
-- Family 2: a standalone closure that captures a LetRec GROUP SIBLING.
--
-- A two-member group is built; then a standalone 'RLam' h captures a sibling f
-- (f is FREE in h's body, used as a call head inside the closure). The closure
-- then either stays LOCAL (dropped unused / called in place => ACCEPT) or
-- ESCAPES (returned, sealed into a con/record, or captured by a nested closure
-- that escapes => REJECT). Mirrors corpus 36 (escape) and the admitted local
-- case.
genClosureSiblingCluster :: Int -> GenM Expr
genClosureSiblingCluster n = do
  -- Range over BOTH the unboxed-capture group (a counted 'NEnv' whose single field
  -- is the unboxed @u@; BLOCKER 2 --- NOT the sentinel, which is reserved for groups
  -- with NO enclosing capture) and the BOXED-capture group (a counted 'NEnv' whose
  -- field is itself a heap child). The boxed variant is what exercises
  -- the dup-on-closure-capture and the escaped closure's env cascade-drop balance;
  -- the unboxed variant is the corpus 36/38 shape.
  boxedCap <- liftG (elements [True, False])
  (fN, wrapGroup) <- if boxedCap then genSiblingGroupBoxed else genSiblingGroup
  flow <- liftG (frequency
                   [ (1, pure FlowDropLocal)
                   , (1, pure FlowReturn)
                   , (1, pure FlowCon)
                   , (1, pure FlowRecord)
                   , (1, pure FlowNestedClosure)
                   , (1, pure FlowReturnThenCall) ])
  -- The closure h: \m -> let r = f (m + 1); r   (f is the captured sibling,
  -- used as a call head inside the body; the closure cell captures f).
  hN <- freshN (T.pack "h")
  mN <- freshN (T.pack "hm")
  msN <- freshN (T.pack "hms")
  hrN <- freshN (T.pack "hr")
  let intTy = gtyCType GInt
      hBody = Let (Binder msN Unrestricted intTy)
                  (RApp (primAtom (T.pack "+")) [AVar mN, ALit (LInt 1)])
                (Let (Binder hrN Unrestricted intTy) (RApp (AVar fN) [AVar msN])
                  (Ret (AVar hrN)))
      hLam  = RLam [Binder mN Unrestricted intTy] hBody
      hB    = Binder hN Unrestricted funTyC
  body <- closureFlowBody flow hN n
  pure $ wrapGroup (Let hB hLam body)

-- | Realize a closure / sibling flow as the continuation following the binder
-- @vN@ (the closure or sibling value). 'FlowDropLocal' yields a GInt and never
-- mentions @vN@ (so it is dropped unused => ACCEPT). The escaping flows return /
-- seal @vN@ so the guard REJECTS.
closureFlowBody :: M2Flow -> Name -> Int -> GenM Expr
closureFlowBody flow vN n = case flow of
  FlowDropLocal -> genExpr [] (n - 1) GInt          -- vN unused => dropped => local
  FlowReturn    -> pure (Ret (AVar vN))             -- escape via return
  FlowCon       -> do
    cN <- freshN (T.pack "esc")
    pure (Let (Binder cN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar vN]) (Ret (AVar cN)))
  FlowRecord    -> do
    cN <- freshN (T.pack "escr")
    pure (Let (Binder cN Unrestricted (Ty.CTRecord (T.pack "Cell") Ty.CREmpty))
              (RRecord (T.pack "Cell") [(T.pack "fn", AVar vN)]) (Ret (AVar cN)))
  FlowList      -> do
    nilN <- freshN (T.pack "nl")
    cN   <- freshN (T.pack "escl")
    pure (Let (Binder nilN Unrestricted funTyC) (RCon (T.pack "Nil") [])
            (Let (Binder cN Unrestricted funTyC) (RCon (T.pack "Cons") [AVar vN, AVar nilN])
              (Ret (AVar cN))))
  FlowCallArg   -> do
    -- pass vN as a non-head argument to an in-scope identity-ish closure that we
    -- build on the spot, whose RESULT escapes (returned).
    idN <- freshN (T.pack "idf")
    pN  <- freshN (T.pack "idp")
    rN  <- freshN (T.pack "idr")
    let idLam = RLam [Binder pN Unrestricted funTyC] (Ret (AVar pN))
    pure (Let (Binder idN Unrestricted funTyC) idLam
            (Let (Binder rN Unrestricted funTyC) (RApp (AVar idN) [AVar vN]) (Ret (AVar rN))))
  FlowNestedClosure -> do
    -- a nested closure that captures vN free, and we RETURN the nested closure
    -- (so vN rides out in its cell => escape).
    gN <- freshN (T.pack "nest")
    qN <- freshN (T.pack "nq")
    rN <- freshN (T.pack "nr")
    let nestLam = RLam [Binder qN Unrestricted (gtyCType GInt)]
                    (Let (Binder rN Unrestricted (gtyCType GInt)) (RApp (AVar vN) [AVar qN])
                      (Ret (AVar rN)))
    pure (Let (Binder gN Unrestricted funTyC) nestLam (Ret (AVar gN)))
  FlowReturnThenCall -> do
    -- Route vN through an identity closure (which RETURNS vN, an unnamed
    -- intermediate at the application site) then OVER-APPLY the result to a scalar:
    -- @let r = (id vN) 7 in r@. The intermediate closure value is consumed by the
    -- application with NO IR binder, exercising the deferred-consume path
    -- ('KDropCellRC') that keeps the escaped closure's shared env alive through its
    -- own call. The result is the scalar call value (a GInt), so a sound pass empties
    -- the heap. This is the in-main analogue of the corpus-36 @(mk u) 2@ shape.
    idN <- freshN (T.pack "idf")
    pN  <- freshN (T.pack "idp")
    rN  <- freshN (T.pack "callr")
    -- @id@ has arity 1; applying it to TWO args (vN and 7) saturates @id@ (it
    -- returns vN, an unnamed intermediate) then OVER-APPLIES that result to 7.
    let idLam = RLam [Binder pN Unrestricted funTyC] (Ret (AVar pN))
    pure (Let (Binder idN Unrestricted funTyC) idLam
            (Let (Binder rN Unrestricted (gtyCType GInt))
                 (RApp (AVar idN) [AVar vN, ALit (LInt 7)])
              (Ret (AVar rN))))

-- ---------------------------------------------------------------------------
-- Family 3: a LetRec sibling moved DIRECTLY (no closure) into a con / record /
-- list / call-arg / projection. Non-escaping (dropped locally => ACCEPT) vs
-- escaping (the cell is returned => REJECT). Mirrors corpus 42-45 (escape) and
-- 48-50 (local drop).
genDirectSiblingCluster :: Int -> GenM Expr
genDirectSiblingCluster n = do
  -- Range over unboxed (sentinel env) and BOXED (counted NEnv) capture groups, so
  -- the bare-move dup-on-escape is exercised against a real env (Stage B).
  boxedCap <- liftG (elements [True, False])
  (fN, wrapGroup) <- if boxedCap then genSiblingGroupBoxed else genSiblingGroup
  -- vehicle for moving the sibling: con / record / list cell.
  vehicle <- liftG (elements [FlowCon, FlowRecord, FlowList])
  -- M2a-2 STAGE B: a BARE move of a sibling into a con / record / list is now sound
  -- whether it stays LOCAL (dropped) or ESCAPES (returned) --- the pass dups the
  -- shared env at the move. Range over both so the property exercises the now-
  -- admitted bare-escape class.
  escapes <- liftG (elements [True, False])
  -- Build the cell holding the sibling f directly, bound to cN.
  cN <- freshN (T.pack "cell")
  (cellTy, cellRhs, extraPrefix) <- case vehicle of
    FlowRecord -> pure (Ty.CTRecord (T.pack "Cell") Ty.CREmpty
                       , RRecord (T.pack "Cell") [(T.pack "fn", AVar fN)]
                       , id)
    FlowList   -> do
      nilN <- freshN (T.pack "nl")
      pure ( funTyC
           , RCon (T.pack "Cons") [AVar fN, AVar nilN]
           , Let (Binder nilN Unrestricted funTyC) (RCon (T.pack "Nil") []) )
    _          -> pure (boxTyC, RCon (T.pack "Box") [AVar fN], id)
  let cB = Binder cN Unrestricted cellTy
  body <-
    if escapes
      then pure (Ret (AVar cN))                -- cell escapes => REJECT
      else genExpr [] (n - 1) GInt             -- cell dropped locally => ACCEPT
  pure $ wrapGroup (extraPrefix (Let cB cellRhs body))

-- ---------------------------------------------------------------------------
-- Family 4: an ALIAS of a sibling ('let x = f'), including a transitive chain
-- ('let y = x'). Dropped locally (=> ACCEPT) vs returned (=> REJECT). Mirrors
-- corpus 40 (drop) and 41 (escape).
genAliasSiblingCluster :: Int -> GenM Expr
genAliasSiblingCluster n = do
  -- Range over unboxed (sentinel env) and BOXED (counted NEnv) capture groups, so
  -- the escaping-alias env-handle transfer is exercised against a real env (Stage B).
  boxedCap <- liftG (elements [True, False])
  (fN, wrapGroup) <- if boxedCap then genSiblingGroupBoxed else genSiblingGroup
  transitive <- liftG (elements [True, False])
  -- M2a-2 STAGE B: a bare ALIAS of a sibling (incl. a transitive chain) is now sound
  -- whether it is dropped LOCALLY or ESCAPES (returned) --- the env-alias propagation
  -- transfers the single shared-env handle out on escape. Range over both.
  escapes <- liftG (elements [True, False])
  xN <- freshN (T.pack "ax")
  yN <- freshN (T.pack "ay")
  let xB = Binder xN Unrestricted funTyC
      yB = Binder yN Unrestricted funTyC
      -- the final alias name that flows out (or is dropped)
      finalAlias = if transitive then yN else xN
      aliasPrefix cont =
        if transitive
          then Let xB (RAtom (AVar fN)) (Let yB (RAtom (AVar xN)) cont)
          else Let xB (RAtom (AVar fN)) cont
  body <-
    if escapes
      then pure (Ret (AVar finalAlias))        -- alias escapes => REJECT
      else genExpr [] (n - 1) GInt             -- alias dropped locally => ACCEPT
  pure $ wrapGroup (aliasPrefix body)

-- ---------------------------------------------------------------------------
-- Family 5: MIXES. A group that BOTH captures an enclosing local AND has an
-- escaping member (the Part-B reject), plus a nested-LetRec variant. We bias
-- toward the consuming-AND-escaping shape (corpus 37) and the borrow-AND-escape
-- shape so both the 'consumeViol' and the 'escapeViol' boundary clauses fire.
genMixedCluster :: Int -> GenM Expr
genMixedCluster _n = do
  (capN, seedCap) <- seedPairCapture
  consuming <- liftG (elements [True, False])
  -- base body either CONSUMES (project cap) or BORROWS (case cap); a member is
  -- ALSO made to escape by returning it from the group body.
  let consumeBase pick c _g = consumeViaBox pick c
      borrowBase pick = \c _g -> do
        pxN <- freshN (T.pack "px")
        pyN <- freshN (T.pack "py")
        pure (Case (AVar c)
                [ AltCon (T.pack "Tuple2")
                    [Binder pxN Unrestricted (gtyCType GInt), Binder pyN Unrestricted (gtyCType GInt)]
                    (Ret (AVar (if pick then pxN else pyN))) ])
      base = if consuming then consumeBase else borrowBase
  (fN, _gN, wrapGroup) <- genMutualGroup capN (base True) (base False)
  -- The group body RETURNS a member (escape) => letRecMemberEscapes is True, and
  -- with an enclosing capture present this is the Part-B / FINDING-1 reject.
  nested <- liftG (elements [True, False])
  let groupBodyEscape = Ret (AVar fN)
  if not nested
    then pure $ seedCap $ wrapGroup groupBodyEscape
    else do
      -- nest the escaping group inside an OUTER group that just calls a sibling;
      -- exercises nested-LetRec handling on the way to the reject.
      oFN <- freshN (T.pack "olrf")
      oGN <- freshN (T.pack "olrg")
      okN1 <- freshN (T.pack "ok1")
      okN2 <- freshN (T.pack "ok2")
      let intTy = gtyCType GInt
          oFBody = wrapGroup groupBodyEscape   -- inner group + its escaping body
          oGBody = Ret (ALit (LInt 0))
          outer cont =
            LetRec [ (Binder oFN Unrestricted funTyC, [Binder okN1 Unrestricted intTy], oFBody)
                   , (Binder oGN Unrestricted intTy,  [Binder okN2 Unrestricted intTy], oGBody) ]
                   cont
      pure $ seedCap $ outer (Ret (AVar oFN))

-- ---------------------------------------------------------------------------
-- Family 6: MEMBER-BODY sibling escape (the M2a-2 BLOCKER-1 class).
--
-- A two-member group where one member's BASE or RECURSIVE arm RETURNS or MOVES a
-- sibling --- so the shared env is carried OUT from INSIDE a member body, where the
-- body BORROWS (does not own) the env. The escaped sibling is then called
-- externally. This is the shape Suite G's other families never produced (their
-- escapes all leave from MAIN's body, never from inside a member body), so the
-- member-body double-free shipped green. After the fix the pass must DUP the env
-- at the member-body escape (an incref) so the externally-held handle owns its own
-- unit and the single 'NEnv' is dropped exactly once. ACCEPTED + must-run-sound.
--
-- We range over: BOXED vs UNBOXED capture (so the escaped env is a real counted
-- 'NEnv' in both --- the unboxed variant is BLOCKER 2); BASE-arm vs REC-arm escape;
-- escape via bare RETURN vs MOVE-into-a-con (dup-on-consume at two distinct sites);
-- and the OVER-APPLY-THEN-CALL variant (@(f 0) depth@ as a single saturating apply,
-- exercising the unnamed-intermediate deferred env-drop alongside the member-body
-- escape).
data MemberEscStyle
  = MescReturn          -- ^ member arm is @Ret sibling@ (bare member-body escape)
  | MescMoveCon         -- ^ member arm seals sibling into a returned 'Box' con
  deriving (Eq, Show)

genMemberBodyEscapeCluster :: Int -> GenM Expr
genMemberBodyEscapeCluster n = do
  boxedCap <- liftG (elements [True, False])
  escStyle <- liftG (elements [MescReturn, MescMoveCon])
  escInRec <- liftG (elements [True, False])   -- escape from the REC arm vs the BASE arm
  overApply <- liftG (elements [True, False])  -- (f 0) depth saturating apply vs named h
  let intTy = gtyCType GInt
  -- Seed the capture (boxed Pair or unboxed U64) and a reader that turns it into a
  -- GInt the non-escaping member arm yields (a borrowed READ of the capture, never a
  -- consume --- consuming captures stay boundary-rejected and out of this family).
  (_capN, seedCap, capReader) <-
    if boxedCap
      then do
        (cN, sc) <- seedPairCapture
        let reader = do
              pxN <- freshN (T.pack "px"); pyN <- freshN (T.pack "py")
              pure (\k -> Case (AVar cN)
                            [ AltCon (T.pack "Tuple2")
                                [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                                (k (AVar pxN)) ])
        pure (cN, sc, reader)
      else do
        seed <- liftG (choose (0, 9 :: Int))
        uN <- freshN (T.pack "u")
        let sc cont = Let (Binder uN Unrestricted intTy)
                          (RAtom (ALit (LInt (toInteger seed)))) cont
            reader = pure (\k -> k (AVar uN))
        pure (uN, sc, reader)
  -- The escaping member f and the worker member g (truly mutually recursive: f's
  -- non-escaping arm calls g, g's rec arm calls f, so the elaborator co-groups them).
  fN  <- freshN (T.pack "lrf")
  gN  <- freshN (T.pack "lrg")
  k1N <- freshN (T.pack "k1"); k2N <- freshN (T.pack "k2")
  -- The member-body escape expression: carry sibling g OUT (Ret g) or seal it into a
  -- returned con (a MOVE of g into a Box). Both are member-body escapes of the env.
  escExpr <- case escStyle of
    MescReturn  -> pure (Ret (AVar gN))
    MescMoveCon -> do
      cN <- freshN (T.pack "mesc")
      pure (Let (Binder cN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar gN]) (Ret (AVar cN)))
  readCap <- capReader
  -- f's body ALWAYS yields the escaping value (so f is type-consistent: every path
  -- returns the function value / Box). escInRec=False escapes immediately
  -- (single-arm); escInRec=True SELF-recurses first (@f (k1-1)@), then escapes at
  -- the base arm --- the escape then happens from a member body reached BY a sibling
  -- recursion, the same env-borrowing position. Either way the env leaves from
  -- INSIDE f's body. f references its sibling g (the escaped value), so f and g are
  -- ONE group node sharing the env.
  ks1N <- freshN (T.pack "fks"); r1N <- freshN (T.pack "fr")
  let fSelfRec = Let (Binder ks1N Unrestricted intTy)
                     (RApp (primAtom (T.pack "-")) [AVar k1N, ALit (LInt 1)])
                   (Let (Binder r1N Unrestricted funTyC) (RApp (AVar fN) [AVar ks1N])
                     (Ret (AVar r1N)))
      fBody = if escInRec
                then Case (AVar k1N) [ AltLit (LInt 0) escExpr, AltDefault fSelfRec ]
                else escExpr
  -- g's body: a self-recursive worker that READS the capture at its base case (so the
  -- capture --- boxed or unboxed --- is genuinely live in the shared env), yielding a
  -- GInt. The escaped g is what main calls.
  ks2N <- freshN (T.pack "gks"); r2N <- freshN (T.pack "gr")
  let gRecCall = Let (Binder ks2N Unrestricted intTy)
                     (RApp (primAtom (T.pack "-")) [AVar k2N, ALit (LInt 1)])
                   (Let (Binder r2N Unrestricted intTy) (RApp (AVar gN) [AVar ks2N])
                     (Ret (AVar r2N)))
      gBody = Case (AVar k2N) [ AltLit (LInt 0) (readCap (\a -> Ret a)), AltDefault gRecCall ]
      wrapGroup cont =
        LetRec [ (Binder fN Unrestricted funTyC, [Binder k1N Unrestricted intTy], fBody)
               , (Binder gN Unrestricted funTyC, [Binder k2N Unrestricted intTy], gBody) ]
               cont
  -- The escaped member (g, possibly inside a Box) flows out of f, then is CALLED
  -- externally so the run exercises the escaped env: either through a named handle
  -- @h@ that is then applied, or via an over-apply @(f initArg) depth@. When the
  -- escape sealed g in a Box we must first unbox it before calling.
  -- Pick @initArg@ so f's FIRST call lands on the ESCAPING arm (which returns the
  -- callable sibling g): base-arm escape (escInRec=False) fires at k1==0; rec-arm
  -- escape (escInRec=True) fires at any k1 /= 0. This guarantees the call-out target
  -- is a function value (g), not the GInt the cap-reading arm would yield.
  let initArg = if escInRec then 1 else 0 :: Int
  depth   <- liftG (choose (1, max 1 (min n 4)))
  hN <- freshN (T.pack "h"); rN <- freshN (T.pack "rr")
  callOut <- case escStyle of
    MescReturn ->
      if overApply
        then pure (Let (Binder rN Unrestricted intTy)
                       (RApp (AVar fN) [ALit (LInt (toInteger initArg)), ALit (LInt (toInteger depth))])
                     (Ret (AVar rN)))
        else pure (Let (Binder hN Unrestricted funTyC) (RApp (AVar fN) [ALit (LInt (toInteger initArg))])
                     (Let (Binder rN Unrestricted intTy) (RApp (AVar hN) [ALit (LInt (toInteger depth))])
                       (Ret (AVar rN))))
    MescMoveCon -> do
      -- f returns a Box holding g; unbox then call.
      boxN <- freshN (T.pack "bx"); gOutN <- freshN (T.pack "gout")
      pure (Let (Binder boxN Unrestricted boxTyC) (RApp (AVar fN) [ALit (LInt (toInteger initArg))])
              (Case (AVar boxN)
                [ AltCon (T.pack "Box") [Binder gOutN Unrestricted funTyC]
                    (Let (Binder rN Unrestricted intTy) (RApp (AVar gOutN) [ALit (LInt (toInteger depth))])
                      (Ret (AVar rN))) ]))
  pure $ seedCap $ wrapGroup callOut

-- ---------------------------------------------------------------------------
-- Family 6b: a member body ESCAPES a borrowed enclosing CAPTURE (the capture
-- analogue of Family 6, which escapes a SIBLING).
--
-- A self-recursive member @f@ closes over a BOXED enclosing capture @cap@ (a
-- 'Tuple2'). Its base arm ESCAPES the capture: either RETURNS @cap@ bare
-- (@Ret cap@) or SEALS it into a returned 'Box' con (@let bx = Box cap in bx@) ---
-- both carry the captured boxed cell OUT from INSIDE a member body, where the body
-- BORROWS (does not own) the shared env that holds @cap@. The pass must dup the
-- captured cell at the escape site (the generalised 'Ret'/'Jump' escape-dup, or the
-- con-move dup-on-consume) so the env's capture-field cascade frees @cap@ exactly
-- once. Without that dup the env cascade frees @cap@ out from under the returned
-- handle --- the verified member-body CAPTURE-escape use-after-free.
--
-- The escaped capture is then DESTRUCTURED externally to a scalar 'GInt' (one field
-- of the Tuple2), so the whole program yields a scalar and the heap MUST empty =>
-- ACCEPT-and-run-sound. We range over: BASE-arm vs REC-arm escape (rec-arm
-- self-recurses first, then escapes at the base, so the escape happens from a body
-- reached BY a recursion --- the same env-borrowing position); and escape via bare
-- RETURN vs MOVE-into-a-returned-con (two distinct dup sites). The saturating apply
-- @(f init) ...@ form is not needed (the capture, not a function, is what escapes).
genCaptureBodyEscapeCluster :: Int -> GenM Expr
genCaptureBodyEscapeCluster _n = do
  escStyle <- liftG (elements [MescReturn, MescMoveCon])
  escInRec <- liftG (elements [True, False])
  let intTy  = gtyCType GInt
      pairTy = gtyCType GPair
  (capN, seedCap) <- seedPairCapture
  fN  <- freshN (T.pack "lcf")
  k1N <- freshN (T.pack "ck1")
  -- The member-body escape expression: carry the CAPTURE out bare (@Ret cap@) or
  -- sealed into a returned 'Box' con (a MOVE of @cap@ into the con). Both escape the
  -- borrowed capture from inside the member body.
  escExpr <- case escStyle of
    MescReturn  -> pure (Ret (AVar capN))
    MescMoveCon -> do
      cN <- freshN (T.pack "csc")
      pure (Let (Binder cN Unrestricted boxTyC) (RCon (T.pack "Box") [AVar capN]) (Ret (AVar cN)))
  ks1N <- freshN (T.pack "cks"); r1N <- freshN (T.pack "cfr")
  -- f's result type is the escaped value (a Pair, or a Box of a Pair). The rec arm
  -- self-recurses (borrowing the env), so escInRec=True escapes from a body reached
  -- by a recursion; escInRec=False escapes immediately.
  let escTy = case escStyle of { MescReturn -> pairTy; MescMoveCon -> boxTyC }
      fSelfRec = Let (Binder ks1N Unrestricted intTy)
                     (RApp (primAtom (T.pack "-")) [AVar k1N, ALit (LInt 1)])
                   (Let (Binder r1N Unrestricted escTy) (RApp (AVar fN) [AVar ks1N])
                     (Ret (AVar r1N)))
      fBody = if escInRec
                then Case (AVar k1N) [ AltLit (LInt 0) escExpr, AltDefault fSelfRec ]
                else escExpr
      wrapGroup cont =
        LetRec [ (Binder fN Unrestricted funTyC, [Binder k1N Unrestricted intTy], fBody) ] cont
  -- Call f so its FIRST call lands on the escaping (base) arm: base-arm escape fires
  -- at k1==0; rec-arm escape fires at any k1 /= 0 (here 1, recursing once to k1==0).
  let initArg = if escInRec then 1 else 0 :: Int
  -- Externally destructure the escaped capture to one Tuple2 field (a scalar).
  pxN <- freshN (T.pack "cpx"); pyN <- freshN (T.pack "cpy")
  pick <- liftG (elements [True, False])
  let readPair scrut = Case scrut
        [ AltCon (T.pack "Tuple2")
            [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
            (Ret (AVar (if pick then pxN else pyN))) ]
  rN <- freshN (T.pack "crr")
  callOut <- case escStyle of
    MescReturn ->
      pure (Let (Binder rN Unrestricted pairTy) (RApp (AVar fN) [ALit (LInt (toInteger initArg))])
              (readPair (AVar rN)))
    MescMoveCon -> do
      -- f returns a Box holding the Pair capture; unbox then destructure.
      boxN <- freshN (T.pack "cbx"); pOutN <- freshN (T.pack "cpout")
      pure (Let (Binder boxN Unrestricted boxTyC) (RApp (AVar fN) [ALit (LInt (toInteger initArg))])
              (Case (AVar boxN)
                [ AltCon (T.pack "Box") [Binder pOutN Unrestricted pairTy]
                    (readPair (AVar pOutN)) ]))
  pure $ seedCap $ wrapGroup callOut

-- ---------------------------------------------------------------------------
-- Family 7: PARTIAL APPLICATION of a MULTI-ARITY capturing member (the M2a-2
-- double-free shape).
--
-- A single self-recursive member of arity >= 2 captures an enclosing local
-- (boxed Pair or unboxed U64). The member is bound to a NAMED head @g@, then
-- applied at one of three SATURATIONS:
--
--   * PARTIAL   --- @let h = g a0 in h <rest>@. @g a0@ is an UNDER-application of
--     the 'RVRecMember' (the LT path of 'enterRC's member arm) --- the exact
--     branch where the shared env was double-freed (build incref'd nothing while
--     the cell's drop cascaded the env). @h@ is the resulting 'NClosure'
--     ('BorrowCaptures'), then saturated.
--   * SATURATED --- @let r = g a0 a1 [a2] in r@ in ONE call (the clean control;
--     EQ path, no partial cell).
--   * OVER      --- the member is arity-1-extended via an identity wrapper so an
--     over-application chains through 'KAppRC'. (We realize "over" as a saturated
--     call whose result --- a scalar --- is then NOT further applied; genuine
--     over-application of a first-order member needs a higher-arity result, which
--     this corpus does not produce, so OVER here saturates a 3-arity member by a
--     1-then-2 split, exercising partial-then-saturate.)
--
-- Every variant yields a GInt (the base case reads the capture to a scalar), so a
-- sound pass empties the heap: ACCEPT-and-run-sound. The base case only READS the
-- capture (borrowed scrutinee / unboxed read), never CONSUMES it (#1 is deferred).
data PartialSaturation = PartPartial | PartSaturated | PartOver
  deriving (Eq, Show)

-- | HOW the named member head @g@ is consumed downstream. The PLAIN kinds apply
-- @g@ DIRECTLY (the original M2a-2 corpus); the two RLAM-MEDIATED crosses route
-- the member through an 'RLam' so 'CaptureMode' propagation across the partial-
-- application of a closure (the 'NClosure' LT branch of 'enterRC') is under test:
--
--   * 'PartRLamPartial' (CROSS 5) --- a 2-arg 'RLam' @e = \x y -> g (x+y) <rest>@
--     that CAPTURES the recursive member head @g@. @e@ is PARTIALLY applied to ONE
--     arg (@let p = e a0@), stored, then SATURATED and called (@p a1@). The partial
--     of the RLam takes the LT branch; its 'CaptureMode' must be carried to the new
--     partial cell verbatim.
--   * 'PartRLamBodyPartial' (CROSS 6) --- a 1-arg ESCAPING 'RLam' @h = \x -> <member
--     @g@ partially applied, then saturated>@. The member partial lives INSIDE the
--     closure body; for an arity-3 member the body does a 1-then-1-then-rest split so
--     the partial-of-a-partial fires the LT branch (the 'BorrowCaptures' propagation
--     case). @h@ is bound, then CALLED locally (@h a@), so the result is a scalar and
--     the run is ACCEPT-and-sound.
--
-- Both yield a GInt, so a sound pass empties the heap (ACCEPT-and-run-sound).
data PartialKind
  = PartPlain PartialSaturation   -- ^ apply the member head @g@ directly
  | PartRLamPartial               -- ^ CROSS 5: capture @g@ in an RLam, partial-apply the RLam
  | PartRLamBodyPartial           -- ^ CROSS 6: member partial inside an escaping RLam body
  deriving (Eq, Show)

genPartialMemberCluster :: Int -> GenM Expr
genPartialMemberCluster n = do
  boxedCap <- liftG (elements [True, False])
  kind     <- liftG (elements [ PartPlain PartPartial, PartPlain PartSaturated, PartPlain PartOver
                              , PartRLamPartial, PartRLamBodyPartial ])
  -- CROSS 6's partial-of-a-partial needs arity 3 to fire the LT branch INSIDE the
  -- RLam body; otherwise range over 2/3 as before.
  arity    <- case kind of
                PartRLamBodyPartial -> pure (3 :: Int)
                _                   -> liftG (elements [2, 3 :: Int])
  let intTy = gtyCType GInt
  -- Seed the capture and a reader turning it into the GInt the base arm yields.
  (seedCap, capReader) <-
    if boxedCap
      then do
        (cN, sc) <- seedPairCapture
        let reader = do
              pxN <- freshN (T.pack "px"); pyN <- freshN (T.pack "py")
              pure (\k -> Case (AVar cN)
                            [ AltCon (T.pack "Tuple2")
                                [Binder pxN Unrestricted intTy, Binder pyN Unrestricted intTy]
                                (k (AVar pxN)) ])
        pure (sc, reader)
      else do
        seed <- liftG (choose (0, 9 :: Int))
        uN <- freshN (T.pack "u")
        let sc cont = Let (Binder uN Unrestricted intTy)
                          (RAtom (ALit (LInt (toInteger seed)))) cont
            reader = pure (\k -> k (AVar uN))
        pure (sc, reader)
  -- The member f of the chosen arity: its FIRST param @a@ is the recursion fuel;
  -- the rest are inert (threaded through the recursive call so they stay live).
  -- f a p1 .. = case a of 0 -> <read cap> ; _ -> f (a-1) p1 .. .
  fN  <- freshN (T.pack "lrf")
  aN  <- freshN (T.pack "fa")
  restNs <- mapM (\_ -> freshN (T.pack "fp")) [2 .. arity]   -- arity-1 inert params
  ksN <- freshN (T.pack "fks")
  rN  <- freshN (T.pack "frr")
  readCap <- capReader
  let paramBs = Binder aN Unrestricted intTy
                  : [ Binder p Unrestricted intTy | p <- restNs ]
      recCallArgs = AVar ksN : map AVar restNs
      fBody = Case (AVar aN)
                [ AltLit (LInt 0) (readCap Ret)
                , AltDefault
                    (Let (Binder ksN Unrestricted intTy)
                         (RApp (primAtom (T.pack "-")) [AVar aN, ALit (LInt 1)])
                       (Let (Binder rN Unrestricted intTy) (RApp (AVar fN) recCallArgs)
                         (Ret (AVar rN)))) ]
      wrapGroup cont =
        LetRec [(Binder fN Unrestricted intTy, paramBs, fBody)] cont
  -- Bind the member to a NAMED head @g@, then apply at the chosen saturation.
  gN  <- freshN (T.pack "g")
  -- Choose a small recursion depth (the first arg) and inert arg values.
  depth <- liftG (choose (0, max 0 (min n 3)))
  -- Concrete argument literals: the FUEL (@depth@, the first arg) and the inert REST.
  let fuelArg  = ALit (LInt (toInteger depth))
      restArgs = [ ALit (LInt (toInteger (10 + i))) | i <- [1 .. arity - 1] ]
  body <- case kind of
    PartPlain PartSaturated -> do
      rrN <- freshN (T.pack "rr")
      pure (Let (Binder rrN Unrestricted intTy) (RApp (AVar gN) (fuelArg : restArgs))
              (Ret (AVar rrN)))
    PartPlain PartPartial -> do
      -- g applied to the FUEL arg only (partial); the result @h@ is then applied
      -- to the remaining args (saturating it). The double-free shape.
      hN  <- freshN (T.pack "h")
      rrN <- freshN (T.pack "rr")
      pure (Let (Binder hN Unrestricted funTyC) (RApp (AVar gN) [fuelArg])
              (Let (Binder rrN Unrestricted intTy) (RApp (AVar hN) restArgs)
                (Ret (AVar rrN))))
    PartPlain PartOver -> do
      -- Partial in TWO steps for arity-3 (1 then the rest); for arity-2 this
      -- coincides with PartPartial. Exercises a chain of partial closures.
      hN  <- freshN (T.pack "h"); h2N <- freshN (T.pack "h2")
      rrN <- freshN (T.pack "rr")
      case restArgs of
        (r1 : r2rest) | arity >= 3 ->
          pure (Let (Binder hN Unrestricted funTyC) (RApp (AVar gN) [fuelArg])
                 (Let (Binder h2N Unrestricted funTyC) (RApp (AVar hN) [r1])
                   (Let (Binder rrN Unrestricted intTy) (RApp (AVar h2N) r2rest)
                     (Ret (AVar rrN)))))
        _ ->
          pure (Let (Binder hN Unrestricted funTyC) (RApp (AVar gN) [fuelArg])
                 (Let (Binder rrN Unrestricted intTy) (RApp (AVar hN) restArgs)
                   (Ret (AVar rrN))))
    PartRLamPartial -> do
      -- CROSS 5: a 2-arg RLam @e = \x y -> let s = x + y in let r = g s <rest> in r@
      -- that CAPTURES the recursive member head @g@ (free in the body as a call
      -- head). @e@ is PARTIALLY applied to ONE arg (@let p = e a0@), then SATURATED
      -- and called (@p a1@). The partial of the RLam takes the 'NClosure' LT branch
      -- of 'enterRC', so its 'CaptureMode' must reach the new partial cell intact.
      xN  <- freshN (T.pack "rlx"); yN <- freshN (T.pack "rly")
      sN  <- freshN (T.pack "rls"); erN <- freshN (T.pack "rler")
      eN  <- freshN (T.pack "rle"); pN  <- freshN (T.pack "rlp")
      rrN <- freshN (T.pack "rr")
      -- g saturated INSIDE the RLam body: g s <rest> where s = x + y stands in for
      -- the fuel arg and the inert rest are the member's remaining params.
      let eBody = Let (Binder sN Unrestricted intTy)
                      (RApp (primAtom (T.pack "+")) [AVar xN, AVar yN])
                    (Let (Binder erN Unrestricted intTy)
                         (RApp (AVar gN) (AVar sN : restArgs))
                      (Ret (AVar erN)))
          eLam  = RLam [Binder xN Unrestricted intTy, Binder yN Unrestricted intTy] eBody
      pure (Let (Binder eN Unrestricted funTyC) eLam
              (Let (Binder pN Unrestricted funTyC) (RApp (AVar eN) [fuelArg])
                (Let (Binder rrN Unrestricted intTy) (RApp (AVar pN) [ALit (LInt 1)])
                  (Ret (AVar rrN)))))
    PartRLamBodyPartial -> do
      -- CROSS 6: a 1-arg RLam @h@ whose BODY partially applies the member @g@, then
      -- saturates it. For arity-3 the body does a 1-then-1-then-rest split so the
      -- partial-of-a-partial fires the 'NClosure' LT branch (the 'BorrowCaptures'
      -- propagation case) INSIDE the closure body. @h@ is bound then CALLED locally,
      -- so the member partial's lifetime is bounded by @h@'s call and the result is
      -- a scalar (ACCEPT-and-run-sound).
      hN  <- freshN (T.pack "h"); hxN <- freshN (T.pack "hx")
      p1N <- freshN (T.pack "hp1"); p2N <- freshN (T.pack "hp2")
      hrN <- freshN (T.pack "hr"); rrN <- freshN (T.pack "rr")
      let hBody = case restArgs of
            (r1 : _) | arity >= 3 ->
              -- arity-3: g fuel (partial, 1 of 3) -> p1 r1 (partial-of-partial, 2 of
              -- 3, the LT branch) -> p2 hx (saturate, 3 of 3). The closure param @hx@
              -- is the LAST inert arg, so the partial-of-partial saturates exactly.
              Let (Binder p1N Unrestricted funTyC) (RApp (AVar gN) [fuelArg])
                (Let (Binder p2N Unrestricted funTyC) (RApp (AVar p1N) [r1])
                  (Let (Binder hrN Unrestricted intTy) (RApp (AVar p2N) [AVar hxN])
                    (Ret (AVar hrN))))
            _ ->
              -- arity-2 fallback: g fuel (partial, 1 of 2) then saturate inside the
              -- body with the closure param @hx@ as the single remaining arg.
              Let (Binder p1N Unrestricted funTyC) (RApp (AVar gN) [fuelArg])
                (Let (Binder hrN Unrestricted intTy) (RApp (AVar p1N) [AVar hxN])
                  (Ret (AVar hrN)))
          hLam = RLam [Binder hxN Unrestricted intTy] hBody
      pure (Let (Binder hN Unrestricted funTyC) hLam
              (Let (Binder rrN Unrestricted intTy) (RApp (AVar hN) [ALit (LInt 0)])
                (Ret (AVar rrN))))
  pure $ seedCap $ wrapGroup (Let (Binder gN Unrestricted funTyC) (RAtom (AVar fN)) body)

-- | Structural detector for the PARTIAL-APPLICATION-of-a-multi-arity-member class
-- (M2a-2 double-free shape): a 'LetRec' member of arity >= 2 whose handle is then
-- applied to FEWER arguments than its arity at a named head (the 'enterRC'
-- 'RVRecMember' LT path). Used only for the 'cover'/'checkCoverage' non-vacuity
-- floor; it is a conservative recognizer (member arity >= 2 + a single-arg apply
-- of a binder bound to that member).
hasPartialMemberApply :: CoreModule -> Bool
hasPartialMemberApply (CoreModule bs) = any (\(TopBind _ _ b) -> go Map.empty b) bs
  where
    -- @arits@ maps a binder Unique to the arity of the member it (transitively)
    -- names, for any name aliased to a >= 2-arity LetRec member.
    go arits e = case e of
      LetRec defs body ->
        let arits' = foldr (\(bd, ps, _) m ->
                              if length ps >= 2
                                then Map.insert (binderUnique bd) (length ps) m
                                else m) arits defs
        in any (\(_, _, d) -> go arits' d) defs || go arits' body
      Let bd r body ->
        let arits' = case r of
              RAtom (AVar nm') | Just k <- Map.lookup (nameUniq nm') arits ->
                Map.insert (binderUnique bd) k arits
              _ -> arits
            here = case r of
              RApp (AVar nm') as
                | Just k <- Map.lookup (nameUniq nm') arits, length as < k -> True
              _ -> False
        in here || go arits' body
      Case _ alts -> any (go arits . altBody) alts
      LetJoin _ _ jb body -> go arits jb || go arits body
      _ -> False
    altBody (AltCon _ _ b) = b
    altBody (AltLit _ b)   = b
    altBody (AltDefault b) = b

-- | Structural detector for the RLAM-MEDIATED member-partial class (CROSS 5/6):
-- a 'LetRec' member of arity >= 2 whose handle (or an alias of it) is referenced
-- as a CALL HEAD from INSIDE an 'RLam' body --- either the RLam itself captures
-- the member and is then partially applied (CROSS 5), or the member is partially
-- applied within an escaping RLam body (CROSS 6). Either way the member flows
-- through a closure, so the 'NClosure' LT branch's 'CaptureMode' propagation is on
-- the path. Used only for the 'cover'/'checkCoverage' non-vacuity floor; it is a
-- conservative recognizer (member arity >= 2 + a member-alias call head occurring
-- lexically under at least one 'RLam').
hasRLamMemberPartial :: CoreModule -> Bool
hasRLamMemberPartial (CoreModule bs) = any (\(TopBind _ _ b) -> go Map.empty False b) bs
  where
    -- @arits@ maps a binder Unique to the arity of the >= 2-arity LetRec member it
    -- (transitively) names. @inLam@ records whether we are lexically inside an RLam.
    go arits inLam e = case e of
      LetRec defs body ->
        let arits' = foldr (\(bd, ps, _) m ->
                              if length ps >= 2
                                then Map.insert (binderUnique bd) (length ps) m
                                else m) arits defs
        in any (\(_, _, d) -> go arits' inLam d) defs || go arits' inLam body
      Let bd r body ->
        let arits' = case r of
              RAtom (AVar nm') | Just k <- Map.lookup (nameUniq nm') arits ->
                Map.insert (binderUnique bd) k arits
              _ -> arits
            -- A member-alias call HEAD seen INSIDE an RLam body is the marker.
            here = case r of
              RApp (AVar nm') _ | inLam, Map.member (nameUniq nm') arits -> True
              RLam _ lamB -> go arits' True lamB
              _ -> False
        in here || go arits' inLam body
      Case _ alts -> any (go arits inLam . altBody) alts
      LetJoin _ _ jb body -> go arits inLam jb || go arits inLam body
      _ -> False
    altBody (AltCon _ _ b) = b
    altBody (AltLit _ b)   = b
    altBody (AltDefault b) = b

-- ---------------------------------------------------------------------------
-- Suite G properties.

-- | The Suite G test group. Three properties as recommended: the soundness proof
-- (accepted ⟹ heap-balanced + value-match), the static-lint cleanliness oracle,
-- and the generalized fault-injection teeth.
rcM2a1PropertyTests :: TestTree
rcM2a1PropertyTests =
  localOption (QuickCheckTests 800) $
    testGroup "rc m2a-1 property (Suite G: owned/borrowed + escape)"
      [ testCase "consuming-capture groups (single + two-member) are REJECTED (deferred)"
          rcM2a1ConsumeCaptureRejected
      , testCase "nested capturing groups are REJECTED (escape + borrow-read); flat stays admitted"
          rcM2a2NestedCaptureRejected
      , testCase "fence partition: indirect-alias captures rejected by consumeViol (not mob)"
          rcM2a2FencePartitionPinned
      , testProperty "accepted => sound (heap-balanced + value-match); rejected => skipped"
          prop_m2a1Escape
      , testProperty "balanceLint is clean on every in-fragment generated program"
          prop_m2a1LintClean
      , testProperty "every single-site RC mutation is caught (generalized teeth)"
          prop_m2a1Teeth
      , testCase "captureEscapesBody single-source: verdict + oracle on hand-built RHS matrix"
          captureEscapesBodyDriftGuard
      , testProperty "captureEscapesBody DERIVES from escapeWalk (equals frozen oracle on every program)"
          prop_captureEscapesBodyMatchesOracle
      , testCase "hasCaptureBodyEscape: fires on capture escape, NOT on sibling escape"
          hasCaptureBodyEscapeSpecific
      , testCase "rcMemSafetyFault catches RC-store-only faults, NOT shared/value errors"
          rcMemSafetyFaultClassification
      ]

-- | 'rcMemSafetyFault' must classify EXACTLY the RC-store-only 'PrimError'
-- messages as memory-safety faults (so a both-fail branch rejects them outright,
-- never laundering a one-sided RC fault past 'errCtorTag' agreement), and must
-- NOT classify the SHARED value-level errors the store-less reference can also
-- produce (else a both-fail branch would false-fail on genuine agreement).
rcMemSafetyFaultClassification :: Assertion
rcMemSafetyFaultClassification = do
  let pe = IV.PrimError . T.pack
  -- MUST catch: the store guards (Value.hs) and the machine invariants (Machine.hs)
  -- the reference, having no reference-counted store, can NEVER emit.
  assertBool "double-free is an RC mem-safety fault"
    (rcMemSafetyFault (pe "double-free: addr 7"))
  assertBool "use-after-free is an RC mem-safety fault"
    (rcMemSafetyFault (pe "use-after-free: addr 7"))
  assertBool "dangling addr is an RC mem-safety fault"
    (rcMemSafetyFault (pe "dangling addr 7"))
  assertBool "drop of dangling addr is an RC mem-safety fault"
    (rcMemSafetyFault (pe "drop of dangling addr 7"))
  assertBool "RVRecMember env addr is not NEnv is an RC store-internal fault"
    (rcMemSafetyFault (pe "RVRecMember env addr is not NEnv: 3"))
  assertBool "an internal: machine message is an RC store-internal fault"
    (rcMemSafetyFault (pe "internal: runModuleRC bind/addr length mismatch"))
  -- MUST NOT catch: shared value-level errors (a store-less reference hits these
  -- too), and non-PrimError constructors.
  assertBool "expected U64 is a SHARED value error, not an RC mem-safety fault"
    (not (rcMemSafetyFault (pe "expected U64")))
  assertBool "expected Bool is a SHARED value error, not an RC mem-safety fault"
    (not (rcMemSafetyFault (pe "expected Bool, got a closure handle")))
  assertBool "division by zero is a SHARED value error, not an RC mem-safety fault"
    (not (rcMemSafetyFault (pe "-: division by zero")))
  assertBool "UnboundVar is NOT an RC mem-safety fault (residual UAF-as-UnboundVar)"
    (not (rcMemSafetyFault (IV.UnboundVar (T.pack "x"))))

-- | Specificity test for 'hasCaptureBodyEscape' (the FIX-1 capture-escape detector):
-- it must fire ONLY when a member body escapes an ENCLOSING BOXED CAPTURE, and must
-- NOT fire when a member body escapes a SIBLING group binder (a distinct code path).
-- This guards against a future over-broadening of the detector (which previously
-- fired on ~55% of programs across every family, gutting the non-vacuity floor).
hasCaptureBodyEscapeSpecific :: Assertion
hasCaptureBodyEscapeSpecific = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      pairTy = Ty.CTCon (Ty.TcTuple 2) [intTy, intTy]
      nm h u = Name (T.pack h) (Unique u)
      -- POSITIVE: a single-member group whose body RETURNS an enclosing boxed
      -- capture @cap@ (bound OUTSIDE the group, not a sibling, not a param).
      --   main = let cap = Tuple2(9,5)
      --          letrec f k = Ret cap
      --          in let r = f 0 in case r of Tuple2 px py -> Ret px
      capEscapeBody =
        Let (Binder (nm "cap" 0) Unrestricted pairTy)
            (RCon (T.pack "Tuple2") [ALit (LInt 9), ALit (LInt 5)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTyC
              , [Binder (nm "k" 2) Unrestricted intTy]
              , Ret (AVar (nm "cap" 0)) ) ]               -- member body escapes the CAPTURE
            (Let (Binder (nm "r" 3) Unrestricted pairTy)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Case (AVar (nm "r" 3))
                [ AltCon (T.pack "Tuple2")
                    [Binder (nm "px" 4) Unrestricted intTy, Binder (nm "py" 5) Unrestricted intTy]
                    (Ret (AVar (nm "px" 4))) ])))
      capEscapeCm = CoreModule [TopBind (nm "main" 1000000) [] capEscapeBody]
      -- NEGATIVE: a two-member group whose body RETURNS a SIBLING binder @g@ (a group
      -- member, NOT an enclosing capture). This is the M2MemberBodyEscape code path.
      --   main = letrec f k = Ret g
      --                 g k = Ret k
      --          in let h = f 0 in let r = h 0 in Ret r
      sibEscapeBody =
        LetRec
          [ ( Binder (nm "f" 1) Unrestricted funTyC
            , [Binder (nm "k1" 2) Unrestricted intTy]
            , Ret (AVar (nm "g" 6)) )                     -- member body escapes a SIBLING
          , ( Binder (nm "g" 6) Unrestricted funTyC
            , [Binder (nm "k2" 7) Unrestricted intTy]
            , Ret (AVar (nm "k2" 7)) ) ]
          (Let (Binder (nm "h" 3) Unrestricted funTyC)
               (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
            (Let (Binder (nm "r" 4) Unrestricted intTy)
                 (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
              (Ret (AVar (nm "r" 4)))))
      sibEscapeCm = CoreModule [TopBind (nm "main" 1000000) [] sibEscapeBody]
  assertBool "must fire on a member body escaping an enclosing boxed CAPTURE"
    (hasCaptureBodyEscape capEscapeCm)
  assertBool "must NOT fire on a member body escaping a SIBLING group binder"
    (not (hasCaptureBodyEscape sibEscapeCm))

-- | The two-member consuming-capture group that a dup-per-consuming-use plan got
-- WRONG (Suite G surfaced the leak): both base cases CONSUME (move) the shared
-- enclosing boxed capture @cap@:
--
--   main = let cap = Tuple2(9,5)
--          letrec lrf k1 = case k1 of 0 -> <move cap into a Box, read it back>
--                                     _ -> lrg (k1 - 1)
--                 lrg k2 = case k2 of 0 -> <move cap into a Box, read it back>
--                                     _ -> lrf (k2 - 1)
--          let lrr = lrf 2 in lrr
--
-- The dup-per-consuming-use scheme pre-emitted one @__rc_dup cap@ per consuming
-- SIBLING at the build site, but at runtime the mutual recursion terminates in
-- EXACTLY ONE base case, so only one consuming move fires --- the surplus dups
-- leaked. Consuming-capture support is therefore DEFERRED (it needs proper
-- borrow-passing). This asserts the M1.5 boundary line is RESTORED: ANY consuming
-- use of an enclosing capture is REJECTED at the boundary --- single-member
-- (rc-m2a1/33) and two-member alike --- so the unsound shape never reaches the
-- pass. A REJECTED program is sound (it is never compiled).
rcM2a1ConsumeCaptureRejected :: Assertion
rcM2a1ConsumeCaptureRejected = do
  -- Single-member consuming-capture corpus: rejected at the boundary BY THE
  -- CONSUMING-CAPTURE FENCE (pinned to catch a fence-swap regression).
  vs33 <- boundaryViolationsOf "test/rc-m2a1/33-consuming-capture-nonescape.wok"
  assertBool "single-member consuming-capture group must be REJECTED by the consuming-capture fence"
    (any (T.isInfixOf (T.pack "consumes an enclosing capture")) vs33)
  -- Two-member consuming-capture group (built directly): rejected at the boundary.
  let intTy  = Ty.CTCon Ty.TcU64 []
      pairTy = Ty.CTCon (Ty.TcTuple 2) [intTy, intTy]
      nm h u = Name (T.pack h) (Unique u)
      -- base case: move cap into a Box con, destructure the box and the Pair,
      -- return one int field (a valid CONSUMING move of cap).
      consumeBase backU pxU pyU pick =
        Let (Binder (nm "bx" backU) Unrestricted boxTyC)
            (RCon (T.pack "Box") [AVar (nm "cap" 0)])
          (Case (AVar (nm "bx" backU))
            [ AltCon (T.pack "Box") [Binder (nm "cback" (backU + 100)) Unrestricted pairTy]
                (Case (AVar (nm "cback" (backU + 100)))
                  [ AltCon (T.pack "Tuple2")
                      [Binder (nm "px" pxU) Unrestricted intTy, Binder (nm "py" pyU) Unrestricted intTy]
                      (Ret (AVar (if pick then nm "px" pxU else nm "py" pyU))) ]) ])
      fBody = Case (AVar (nm "k1" 3))
                [ AltLit (LInt 0) (consumeBase 9 11 12 True)
                , AltDefault
                    (Let (Binder (nm "ks1" 5) Unrestricted intTy)
                         (RApp (AVar (nm "-" 2000000)) [AVar (nm "k1" 3), ALit (LInt 1)])
                       (Let (Binder (nm "r1" 7) Unrestricted intTy)
                            (RApp (AVar (nm "lrg" 2)) [AVar (nm "ks1" 5)])
                         (Ret (AVar (nm "r1" 7))))) ]
      gBody = Case (AVar (nm "k2" 4))
                [ AltLit (LInt 0) (consumeBase 13 15 16 False)
                , AltDefault
                    (Let (Binder (nm "ks2" 6) Unrestricted intTy)
                         (RApp (AVar (nm "-" 2000000)) [AVar (nm "k2" 4), ALit (LInt 1)])
                       (Let (Binder (nm "r2" 8) Unrestricted intTy)
                            (RApp (AVar (nm "lrf" 1)) [AVar (nm "ks2" 6)])
                         (Ret (AVar (nm "r2" 8))))) ]
      body =
        Let (Binder (nm "cap" 0) Unrestricted pairTy)
            (RCon (T.pack "Tuple2") [ALit (LInt 9), ALit (LInt 5)])
          (LetRec [ (Binder (nm "lrf" 1) Unrestricted intTy, [Binder (nm "k1" 3) Unrestricted intTy], fBody)
                  , (Binder (nm "lrg" 2) Unrestricted intTy, [Binder (nm "k2" 4) Unrestricted intTy], gBody) ]
            (Let (Binder (nm "lrr" 17) Unrestricted intTy)
                 (RApp (AVar (nm "lrf" 1)) [ALit (LInt 2)])
              (Ret (AVar (nm "lrr" 17)))))
      cm     = CoreModule [TopBind (nm "main" 1000000) [] body]
      pruned = pruneToReachable cm
  assertBool "two-member consuming-capture group must be REJECTED by the consuming-capture fence"
    (any (T.isInfixOf (T.pack "consumes an enclosing capture"))
         (firstOrderNoHandlerViolations pruned))
  -- WHY the rejection stands (verification-gate finding, 2026-06-16). The shared-env
  -- borrow model alone does NOT make #1 sound. If the boundary were bypassed and the
  -- pass run on this very reproducer, the dynamic dup-on-consume balances the path
  -- TAKEN at runtime (so a runModuleRCUnchecked at a fixed depth happens to empty the
  -- heap), but the pass does NOT emit statically-balanced instrumentation: the capture
  -- is moved into the shared env ONCE while each base-case arm independently dups it,
  -- and the path-insensitive multiset accounting that underwrites soundness for ALL
  -- call patterns (including the nested/escaped group whose env-drop never fires)
  -- cannot reconcile. 'balanceLint' --- the compile-time oracle (Suite G's
  -- 'prop_m2a1LintClean') --- MUST therefore flag the leak. This is the teeth: were
  -- the dup-on-consume emission ever made to "pass" by weakening the lint, this
  -- assertion would catch the regression.
  assertBool "balanceLint must flag the consuming-capture imbalance (deferral rationale)"
    (not (null (Perceus.balanceLint (Perceus.insertRC pruned))))

-- | NESTED CAPTURING GROUP (M2a-2, verified DOUBLE-FREE). A 'LetRec' group NESTED
-- inside an enclosing 'LetRec' member body that captures a boxed local bound
-- OUTSIDE that enclosing member double-frees the local: the local lives in BOTH the
-- enclosing member's 'NEnv' and the inner group's 'NEnv' --- two cascades on drop,
-- but only one incref backs the re-capture (the local is treated as
-- borrowed/moved-once). The boundary guard REJECTS this class on the MEMBER-OUTER
-- BOXED SET (@rawEnclosingFv ∩ mob@) --- whether the inner group ESCAPES the
-- outside-bound local (CLAIM 1, returns it), only BORROW-READS it (CLAIM 2),
-- reaches it through a same-cell ALIAS rename (CLAIM 3), or is TRIPLE-nested
-- (CLAIM 4). A REJECTED program is sound (it is never compiled). Each must-reject
-- shape is RUN unchecked to confirm it would genuinely double-free if admitted.
--
-- The PRECISION boundary (M2a-2 precision-cleanup): three shapes that were
-- conservatively over-rejected are now ADMITTED-and-RUN-SOUND because the captured
-- local is NOT in the member-outer set:
--   * FLAT (non-nested) group capturing an enclosing local --- one env, one cascade;
--   * GROUP-IN-LAMBDA-IN-MEMBER --- a lambda body is a fresh frame, resetting @mob@
--     (ADMIT 1, the same group is sound at top level);
--   * PER-ENTRY LET-LOCAL --- a local ALLOCATED inside the enclosing member body
--     (rebuilt per entry alongside the inner env --- one cascade) (ADMIT 2).
-- A nested group that captures NO enclosing boxed local also stays ADMITTED.
rcM2a2NestedCaptureRejected :: Assertion
rcM2a2NestedCaptureRejected = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
      nm h u = Name (T.pack h) (Unique u)
      -- main = let b = Box 7 in
      --        letrec f k = (letrec h j = Ret b in let r = h 0 in Ret r)
      --        in let res = f 0 in case res of Box v -> Ret v
      claim1 =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , LetRec
                  [ ( Binder (nm "h" 3) Unrestricted funTy
                    , [Binder (nm "j" 4) Unrestricted intTy]
                    , Ret (AVar (nm "b" 0)) ) ]      -- inner group ESCAPES the local b
                  (Let (Binder (nm "r" 5) Unrestricted boxTyC)
                       (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                    (Ret (AVar (nm "r" 5)))) ) ]
            (Let (Binder (nm "res" 6) Unrestricted boxTyC)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Case (AVar (nm "res" 6))
                [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                    (Ret (AVar (nm "v" 7))) ])))
      claim1Cm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] claim1])
      -- main = let b = Box 7 in
      --        letrec f k = (letrec h j = (case b of Box v -> Ret v) in let r = h 0 in Ret r)
      --        in let res = f 0 in Ret res
      claim2 =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , LetRec
                  [ ( Binder (nm "h" 3) Unrestricted funTy
                    , [Binder (nm "j" 4) Unrestricted intTy]
                    , Case (AVar (nm "b" 0))          -- inner group BORROW-READS the local b
                        [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                            (Ret (AVar (nm "v" 7))) ] ) ]
                  (Let (Binder (nm "r" 5) Unrestricted intTy)
                       (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                    (Ret (AVar (nm "r" 5)))) ) ]
            (Let (Binder (nm "res" 6) Unrestricted intTy)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Ret (AVar (nm "res" 6)))))
      claim2Cm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] claim2])
  -- CLAIM 1 (escape) and CLAIM 2 (borrow-read): BOTH rejected at the boundary BY
  -- THE NESTED-CAPTURING-GROUP FENCE (pinned to catch a fence-swap regression).
  assertBool "CLAIM 1 (nested group escapes enclosing local) must be REJECTED by the nested-capture fence"
    (any (T.isInfixOf (T.pack "nested LetRec group captures a local bound outside"))
         (firstOrderNoHandlerViolations claim1Cm))
  assertBool "CLAIM 2 (nested group borrow-reads enclosing local) must be REJECTED by the nested-capture fence"
    (any (T.isInfixOf (T.pack "nested LetRec group captures a local bound outside"))
         (firstOrderNoHandlerViolations claim2Cm))

  -- CLAIM 3 (ALIAS): the inner group captures the outside-bound local through a
  -- same-cell rename @let ba = b@ bound inside the enclosing member body. @ba@ is
  -- NOT allocated per entry --- it names the SAME cell as @b@ --- so capturing it
  -- double-frees exactly as capturing @b@. The member-outer set propagates through
  -- the pure 'RAtom' rename, so the fence still fires.
  --   main = let b = Box 7 in
  --          letrec f k = (let ba = b in letrec h j = Ret ba in let r = h 0 in Ret r)
  --          in let res = f 0 in case res of Box v -> Ret v
  let claim3 =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , Let (Binder (nm "ba" 30) Unrestricted boxTyC)
                    (RAtom (AVar (nm "b" 0)))           -- same-cell alias of the outside-bound b
                  (LetRec
                    [ ( Binder (nm "h" 3) Unrestricted funTy
                      , [Binder (nm "j" 4) Unrestricted intTy]
                      , Ret (AVar (nm "ba" 30)) ) ]      -- inner group captures the alias
                    (Let (Binder (nm "r" 5) Unrestricted boxTyC)
                         (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                      (Ret (AVar (nm "r" 5))))) ) ]
            (Let (Binder (nm "res" 6) Unrestricted boxTyC)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Case (AVar (nm "res" 6))
                [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                    (Ret (AVar (nm "v" 7))) ])))
      claim3Cm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] claim3])
  assertBool "CLAIM 3 (nested group captures outside-bound local via alias) must be REJECTED by the nested-capture fence"
    (any (T.isInfixOf (T.pack "nested LetRec group captures a local bound outside"))
         (firstOrderNoHandlerViolations claim3Cm))

  -- CLAIM 4 (TRIPLE NESTING): group @g@ nested in member @f@, group @h@ nested in
  -- member @g@; @h@ captures @b@ bound OUTSIDE @f@. @b@ is in the member-outer set
  -- of the @g@-member body (snapshotted from @f@'s body), so the innermost fence
  -- fires.
  --   main = let b = Box 7 in
  --          letrec f k = (letrec g m = (letrec h j = Ret b in let r = h 0 in Ret r)
  --                        in let s = g 0 in Ret s)
  --          in let res = f 0 in case res of Box v -> Ret v
  let claim4 =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , LetRec
                  [ ( Binder (nm "g" 40) Unrestricted funTy
                    , [Binder (nm "m" 41) Unrestricted intTy]
                    , LetRec
                        [ ( Binder (nm "h" 3) Unrestricted funTy
                          , [Binder (nm "j" 4) Unrestricted intTy]
                          , Ret (AVar (nm "b" 0)) ) ]    -- innermost group captures outside-f local b
                        (Let (Binder (nm "r" 5) Unrestricted boxTyC)
                             (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                          (Ret (AVar (nm "r" 5)))) ) ]
                  (Let (Binder (nm "s" 42) Unrestricted boxTyC)
                       (RApp (AVar (nm "g" 40)) [ALit (LInt 0)])
                    (Ret (AVar (nm "s" 42)))) ) ]
            (Let (Binder (nm "res" 6) Unrestricted boxTyC)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Case (AVar (nm "res" 6))
                [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                    (Ret (AVar (nm "v" 7))) ])))
      claim4Cm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] claim4])
  assertBool "CLAIM 4 (triple-nested group captures outside-bound local) must be REJECTED by the nested-capture fence"
    (any (T.isInfixOf (T.pack "nested LetRec group captures a local bound outside"))
         (firstOrderNoHandlerViolations claim4Cm))

  -- ENTANGLEMENT GATE: every must-reject shape would genuinely DOUBLE-FREE / UAF if
  -- it were admitted. Run each unchecked and assert the RC interpreter FAILS (or
  -- leaves the heap imbalanced) --- so the rejection is load-bearing, not vacuous.
  let wouldFaultUnchecked cm =
        RCM.runModuleRCUnchecked (Perceus.insertRC cm) >>= \case
          Left _    -> pure True
          Right run -> pure (St.stLive (RCM.rcStats run) /= RCM.rcBaseline run)
  wouldFaultUnchecked claim1Cm >>= assertBool
    "CLAIM 1 would double-free if admitted (rejection is load-bearing)"
  wouldFaultUnchecked claim2Cm >>= assertBool
    "CLAIM 2 would double-free if admitted (rejection is load-bearing)"
  wouldFaultUnchecked claim3Cm >>= assertBool
    "CLAIM 3 would double-free if admitted (rejection is load-bearing)"
  wouldFaultUnchecked claim4Cm >>= assertBool
    "CLAIM 4 would double-free/UAF if admitted (rejection is load-bearing)"

  -- ADMIT 1 (newly admitted + SOUND): a group nested inside a LAMBDA that sits in a
  -- member body. The lambda body is a fresh frame (resets the member-outer set), so
  -- the nested group is sound exactly as the same group at top level.
  --   main = let b = Box 7 in
  --          letrec f k = (let cl = (\z -> letrec h j = case b of Box v -> Ret v
  --                                        in let r = h 0 in Ret r)
  --                        in let out = cl 0 in Ret out)
  --          in let res = f 0 in Ret res
  let admitLam =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , Let (Binder (nm "cl" 8) Unrestricted funTy)
                    (RLam [Binder (nm "z" 9) Unrestricted intTy]
                      (LetRec
                        [ ( Binder (nm "h" 3) Unrestricted funTy
                          , [Binder (nm "j" 4) Unrestricted intTy]
                          , Case (AVar (nm "b" 0))
                              [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                                  (Ret (AVar (nm "v" 7))) ] ) ]
                        (Let (Binder (nm "r" 5) Unrestricted intTy)
                             (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                          (Ret (AVar (nm "r" 5))))))
                  (Let (Binder (nm "out" 10) Unrestricted intTy)
                       (RApp (AVar (nm "cl" 8)) [ALit (LInt 0)])
                    (Ret (AVar (nm "out" 10)))) ) ]
            (Let (Binder (nm "res" 6) Unrestricted intTy)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (Ret (AVar (nm "res" 6)))))
      admitLamCm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] admitLam])
  assertBool "ADMIT 1: a group nested inside a lambda in a member body must be ADMITTED"
    (null (firstOrderNoHandlerViolations admitLamCm))
  admitLamRc <- RCM.runModuleRCUnchecked (Perceus.insertRC admitLamCm)
  case (Interp.runModule admitLamCm, admitLamRc) of
    (Right v, Right run) -> do
      Interp.renderValue v @?= RCM.rcOutput run
      assertEqual "group-in-lambda: live cells return to baseline"
        (RCM.rcBaseline run) (St.stLive (RCM.rcStats run))
      assertEqual "group-in-lambda: allocs minus frees equal baseline"
        (RCM.rcBaseline run) (St.stAllocs (RCM.rcStats run) - St.stFrees (RCM.rcStats run))
    (refRes, rcRes) ->
      assertFailure ("group-in-lambda: both interpreters must succeed; got "
                       <> either show (const "ok") refRes <> " / "
                       <> either show (const "ok") rcRes)

  -- ADMIT 2 (newly admitted + SOUND): a group nested in a member body capturing a
  -- PER-ENTRY local ALLOCATED inside that member body (@let bloc = Box 9@). It is
  -- NOT in the member-outer set (it is rebuilt per entry alongside the inner env),
  -- so one cascade --- sound.
  --   main = letrec f k = (let bloc = Box 9 in
  --                         letrec h j = case bloc of Box v -> Ret v in let r = h 0 in Ret r)
  --          in let res = f 0 in Ret res
  let admitPerEntry =
        LetRec
          [ ( Binder (nm "f" 1) Unrestricted funTy
            , [Binder (nm "k" 2) Unrestricted intTy]
            , Let (Binder (nm "bloc" 20) Unrestricted boxTyC)
                  (RCon (T.pack "Box") [ALit (LInt 9)])
                (LetRec
                  [ ( Binder (nm "h" 3) Unrestricted funTy
                    , [Binder (nm "j" 4) Unrestricted intTy]
                    , Case (AVar (nm "bloc" 20))
                        [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                            (Ret (AVar (nm "v" 7))) ] ) ]
                  (Let (Binder (nm "r" 5) Unrestricted intTy)
                       (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                    (Ret (AVar (nm "r" 5))))) ) ]
          (Let (Binder (nm "res" 6) Unrestricted intTy)
               (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
            (Ret (AVar (nm "res" 6))))
      admitPerEntryCm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] admitPerEntry])
  assertBool "ADMIT 2: a nested group capturing a per-entry let-local must be ADMITTED"
    (null (firstOrderNoHandlerViolations admitPerEntryCm))
  admitPerEntryRc <- RCM.runModuleRCUnchecked (Perceus.insertRC admitPerEntryCm)
  case (Interp.runModule admitPerEntryCm, admitPerEntryRc) of
    (Right v, Right run) -> do
      Interp.renderValue v @?= RCM.rcOutput run
      assertEqual "per-entry-let-local: live cells return to baseline"
        (RCM.rcBaseline run) (St.stLive (RCM.rcStats run))
      assertEqual "per-entry-let-local: allocs minus frees equal baseline"
        (RCM.rcBaseline run) (St.stAllocs (RCM.rcStats run) - St.stFrees (RCM.rcStats run))
    (refRes, rcRes) ->
      assertFailure ("per-entry-let-local: both interpreters must succeed; got "
                       <> either show (const "ok") refRes <> " / "
                       <> either show (const "ok") rcRes)

  -- PRECISION 1 (admit + SOUND): a FLAT group (top-level scope, lr empty) capturing
  -- an enclosing boxed local. One env cell, one cascade --- verified sound.
  --   main = let b = Box 7 in
  --          letrec h j = (case b of Box v -> Ret v)
  --          in let r = h 0 in Ret r
  let flatBody =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "h" 3) Unrestricted funTy
              , [Binder (nm "j" 4) Unrestricted intTy]
              , Case (AVar (nm "b" 0))
                  [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                      (Ret (AVar (nm "v" 7))) ] ) ]
            (Let (Binder (nm "r" 5) Unrestricted intTy)
                 (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
              (Ret (AVar (nm "r" 5)))))
      flatCm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] flatBody])
  assertBool "PRECISION: a FLAT group capturing an enclosing local must stay ADMITTED"
    (null (firstOrderNoHandlerViolations flatCm))
  flatRc <- RCM.runModuleRCUnchecked (Perceus.insertRC flatCm)
  case (Interp.runModule flatCm, flatRc) of
    (Right v, Right run) -> do
      Interp.renderValue v @?= RCM.rcOutput run
      let st = RCM.rcStats run
          bl = RCM.rcBaseline run
      assertEqual "flat-capture: live cells return to baseline (no leak/double-free)"
        bl (St.stLive st)
      assertEqual "flat-capture: allocs minus frees equal baseline"
        bl (St.stAllocs st - St.stFrees st)
    (refRes, rcRes) ->
      assertFailure ("flat-capture: both interpreters must succeed; got "
                       <> either show (const "ok") refRes <> " / "
                       <> either show (const "ok") rcRes)

  -- PRECISION 2 (admit): a NESTED group that captures NO enclosing boxed local ---
  -- the inner group references only its own param. lr is non-empty but the
  -- rawEnclosingFv ∩ bsc intersection is empty, so it stays ADMITTED.
  --   main = let b = Box 7 in
  --          letrec f k = (letrec h j = Ret j in let r = h 0 in Ret r)
  --          in case b of Box v -> Ret v
  let nestedNoCap =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec
            [ ( Binder (nm "f" 1) Unrestricted funTy
              , [Binder (nm "k" 2) Unrestricted intTy]
              , LetRec
                  [ ( Binder (nm "h" 3) Unrestricted funTy
                    , [Binder (nm "j" 4) Unrestricted intTy]
                    , Ret (AVar (nm "j" 4)) ) ]       -- captures only its own param
                  (Let (Binder (nm "r" 5) Unrestricted intTy)
                       (RApp (AVar (nm "h" 3)) [ALit (LInt 0)])
                    (Ret (AVar (nm "r" 5)))) ) ]
            (Case (AVar (nm "b" 0))
              [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                  (Ret (AVar (nm "v" 7))) ]))
      nestedNoCapCm = pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] nestedNoCap])
  assertBool "PRECISION: a NESTED group capturing NO enclosing local must stay ADMITTED"
    (null (firstOrderNoHandlerViolations nestedNoCapCm))

-- | FENCE-PARTITION REGRESSION (pins the split between two nested-capture fences,
-- and the soundness boundary it protects).
--
-- A nested group capturing an outside-bound local @b@ through an INSIDE-bound alias
-- is policed by TWO disjoint fences, and which one fires depends on HOW the alias was
-- formed --- a partition that is load-bearing for soundness:
--
--   * SAME-CELL 'RAtom' rename (@let ba = b@): @ba@ names the SAME heap cell as the
--     outside-bound @b@, so capturing it into a nested group genuinely DOUBLE-FREES
--     (@b@ lives in both the member's env and the inner group's env --- two cascades,
--     one incref). 'nestedCaptureViol' catches this BECAUSE @mob@ (the member-outer
--     boxed set) is PROPAGATED through the pure 'RAtom' rename. This rejection is
--     LOAD-BEARING (verified below: it double-frees if force-run).
--
--   * INDIRECT alias --- a 'RApp' call RESULT (@let al = idf b@), an 'RCon'-then-
--     destructure, or an 'RProj' of a record field holding @b@: @mob@ is deliberately
--     NOT propagated through these RHS forms (they allocate / yield a fresh cell in
--     the GENERAL case), so 'nestedCaptureViol' does NOT fire. They are caught instead
--     by the CONSUMING-CAPTURE fence ('consumeViol'): the alias is bound inside the
--     member body so it lands in @bsc@, and a nested group consuming it locally is a
--     consuming capture of a @bsc@ member. CRUCIALLY (verified below) these shapes are
--     actually SOUND if force-run --- the pass's move/projection dup machinery
--     ('projDupFor', 'moveOperandUniques') breaks the aliasing --- so @consumeViol@'s
--     rejection of them is CONSERVATIVE OVER-REJECTION, NOT a load-bearing fence.
--
-- WHY THIS IS PINNED (the cross-fence dependency a future slice must respect): if a
-- later slice RELAXES @consumeViol@ to admit local consumes (via proper borrow-
-- passing), the indirect-alias shapes stay sound, BUT it must NOT also drop the
-- 'RAtom'-rename case from @consumeViol@ on the assumption that @consumeViol@ alone
-- covered it --- the 'RAtom' double-free is held by @nestedCaptureViol@ via @mob@,
-- and that coverage must remain. This test asserts the partition exactly: the
-- 'RAtom' shape is caught by @nestedCaptureViol@ AND double-frees if admitted; the
-- three indirect shapes are caught by @consumeViol@, NOT @nestedCaptureViol@, AND run
-- sound if admitted (the over-rejection is documented, not asserted away).
rcM2a2FencePartitionPinned :: Assertion
rcM2a2FencePartitionPinned = do
  let intTy  = Ty.CTCon Ty.TcU64 []
      funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
      recTy  = Ty.CTRecord (T.pack "PCell") Ty.CREmpty
      nm h u = Name (T.pack h) (Unique u)
      -- The inner self-recursive group @h@ CONSUMES its captured alias @aliasN@ by
      -- sealing it into a 'Box' that is destructured-and-dropped locally (the deferred
      -- #1 local-consume shape). @h@ is called by the enclosing member, so the alias is
      -- captured into @h@'s env.
      innerConsumeGroup aliasN contBuild =
        LetRec
          [ ( Binder (nm "h" 3) Unrestricted funTy
            , [Binder (nm "j" 4) Unrestricted intTy]
            , Let (Binder (nm "bx" 8) Unrestricted boxTyC)
                  (RCon (T.pack "Box") [AVar aliasN])      -- MOVE the alias into a Box (consume)
                (Case (AVar (nm "bx" 8))
                  [ AltCon (T.pack "Box") [Binder (nm "cb" 9) Unrestricted boxTyC]
                      (Case (AVar (nm "cb" 9))
                        [ AltCon (T.pack "Box") [Binder (nm "vv" 10) Unrestricted intTy]
                            (Ret (AVar (nm "vv" 10))) ]) ]) ) ]
          (contBuild (nm "h" 3))
      -- The inner group @h@ ESCAPES its captured alias (returns it). This is the shape
      -- whose double-free is genuinely load-bearing for the SAME-CELL 'RAtom' alias.
      innerEscapeGroup aliasN contBuild =
        LetRec
          [ ( Binder (nm "h" 3) Unrestricted funTy
            , [Binder (nm "j" 4) Unrestricted intTy]
            , Ret (AVar aliasN) ) ]                       -- ESCAPE the alias
          (contBuild (nm "h" 3))
      -- The enclosing member @f@ runs @aliasBody@ --- the alias-binding prologue
      -- followed by the nested group + call. @resTy@ is the call result type (int for
      -- the consume shapes; Box for the escape shape).
      mkMember aliasBody =
        ( Binder (nm "f" 1) Unrestricted funTy
        , [Binder (nm "k" 2) Unrestricted intTy]
        , aliasBody )
      consumeCont hN =
        Let (Binder (nm "r" 5) Unrestricted intTy)
            (RApp (AVar hN) [ALit (LInt 0)])
          (Ret (AVar (nm "r" 5)))
      escapeCont hN =
        Let (Binder (nm "r" 5) Unrestricted boxTyC)
            (RApp (AVar hN) [ALit (LInt 0)])
          (Ret (AVar (nm "r" 5)))
      -- An inner group that ESCAPES / CONSUMES its captured alias, with its call
      -- continuation already applied --- a plain @Name -> Expr@ the alias builders feed.
      innerEscape aliasN  = innerEscapeGroup aliasN escapeCont
      innerConsume aliasN = innerConsumeGroup aliasN consumeCont
      -- Drive @main@: build @b@ outside, the group with @f@, call @f@, then either drop
      -- the int result or destructure the escaped Box to a scalar (so the heap empties
      -- on a SOUND run).
      program member resTy escaped =
        Let (Binder (nm "b" 0) Unrestricted boxTyC)
            (RCon (T.pack "Box") [ALit (LInt 7)])
          (LetRec [member]
            (Let (Binder (nm "res" 6) Unrestricted resTy)
                 (RApp (AVar (nm "f" 1)) [ALit (LInt 0)])
              (if escaped
                 then Case (AVar (nm "res" 6))
                        [ AltCon (T.pack "Box") [Binder (nm "v" 7) Unrestricted intTy]
                            (Ret (AVar (nm "v" 7))) ]
                 else Ret (AVar (nm "res" 6)))))
      mkCm member resTy escaped =
        pruneToReachable (CoreModule [TopBind (nm "main" 1000000) [] (program member resTy escaped)])

  -- SAME-CELL alias (RAtom rename), inner group ESCAPES it: the genuine DOUBLE-FREE.
  --   let ba = b   (pure rename --- same cell, mob propagates)
  let ratomAlias k =
        Let (Binder (nm "ba" 30) Unrestricted boxTyC) (RAtom (AVar (nm "b" 0)))
          (k (nm "ba" 30))
      ratomCm = mkCm (mkMember (ratomAlias innerEscape)) boxTyC True

  -- INDIRECT alias 1: call-result  @let al = idf b@  (idf = \x -> x).
  let callResultAlias k =
        Let (Binder (nm "idf" 20) Unrestricted funTy)
            (RLam [Binder (nm "x" 21) Unrestricted boxTyC] (Ret (AVar (nm "x" 21))))
          (Let (Binder (nm "al" 22) Unrestricted boxTyC)
               (RApp (AVar (nm "idf" 20)) [AVar (nm "b" 0)])   -- RApp RESULT (a fresh move)
            (k (nm "al" 22)))
      callResultCm = mkCm (mkMember (callResultAlias innerConsume)) intTy False

  -- INDIRECT alias 2: con-then-destructure  @let c = Box b ; case c of Box al -> ...@
  -- (the destructured child @al@ is dup'd by the pass, breaking the aliasing).
  let conAlias k =
        Let (Binder (nm "c" 23) Unrestricted boxTyC)
            (RCon (T.pack "Box") [AVar (nm "b" 0)])             -- RCon captures b
          (Case (AVar (nm "c" 23))
            [ AltCon (T.pack "Box") [Binder (nm "al" 24) Unrestricted boxTyC]
                (k (nm "al" 24)) ])
      conCm = mkCm (mkMember (conAlias innerConsume)) intTy False

  -- INDIRECT alias 3: record projection  @let c = {p=b} ; let al = c.p@  (RProj of a
  -- record field --- valid projection; 'projDupFor' dups @al@).
  let recProjAlias k =
        Let (Binder (nm "c" 25) Unrestricted recTy)
            (RRecord (T.pack "PCell") [(T.pack "p", AVar (nm "b" 0))])
          (Let (Binder (nm "al" 26) Unrestricted boxTyC)
               (RProj (T.pack "p") (AVar (nm "c" 25)))          -- RProj alias
            (k (nm "al" 26)))
      recProjCm = mkCm (mkMember (recProjAlias innerConsume)) intTy False

  let nestedMsg  = T.pack "nested LetRec group captures a local bound outside"
      consumeMsg = T.pack "consumes an enclosing capture"
      rejectedBy needle cm = any (T.isInfixOf needle) (firstOrderNoHandlerViolations cm)
      wouldFaultUnchecked cm =
        RCM.runModuleRCUnchecked (Perceus.insertRC cm) >>= \case
          Left _    -> pure True
          Right run -> pure (St.stLive (RCM.rcStats run) /= RCM.rcBaseline run)
      runsSoundUnchecked cm =
        RCM.runModuleRCUnchecked (Perceus.insertRC cm) >>= \case
          Left _    -> pure False
          Right run -> pure (St.stLive (RCM.rcStats run) == RCM.rcBaseline run)

  -- SAME-CELL 'RAtom' alias: caught by the NESTED-CAPTURE fence (mob propagates the
  -- rename), and the rejection is LOAD-BEARING --- it genuinely double-frees.
  assertBool "RAtom-rename alias must be REJECTED by the nested-capture fence (mob)"
    (rejectedBy nestedMsg ratomCm)
  wouldFaultUnchecked ratomCm >>= assertBool
    "RAtom-rename alias would DOUBLE-FREE if admitted (nested-capture fence is load-bearing)"

  -- INDIRECT aliases: caught by the CONSUMING-CAPTURE fence, NOT the nested-capture
  -- fence (mob does not propagate through RApp/RCon-destructure/RProj). The partition.
  assertBool "call-result alias must be REJECTED by the consuming-capture fence"
    (rejectedBy consumeMsg callResultCm)
  assertBool "call-result alias must NOT be caught by the nested-capture fence (partition)"
    (not (rejectedBy nestedMsg callResultCm))
  assertBool "con-destructure alias must be REJECTED by the consuming-capture fence"
    (rejectedBy consumeMsg conCm)
  assertBool "con-destructure alias must NOT be caught by the nested-capture fence (partition)"
    (not (rejectedBy nestedMsg conCm))
  assertBool "record-proj alias must be REJECTED by the consuming-capture fence"
    (rejectedBy consumeMsg recProjCm)
  assertBool "record-proj alias must NOT be caught by the nested-capture fence (partition)"
    (not (rejectedBy nestedMsg recProjCm))

  -- The indirect-alias rejections are CONSERVATIVE OVER-REJECTION: each actually runs
  -- SOUND if force-run (the pass's move/projection dup machinery breaks the aliasing).
  -- This is documented, not a soundness fault. Pinning it makes the over-rejection a
  -- KNOWN, INTENTIONAL fact: if a future slice relaxes consumeViol to ADMIT these, the
  -- run is already sound (so the admission is safe) --- but the RAtom case above stays
  -- held by the nested-capture fence and must not be dropped.
  runsSoundUnchecked callResultCm >>= assertBool
    "call-result alias actually RUNS SOUND if admitted (over-rejection, not a double-free)"
  runsSoundUnchecked conCm >>= assertBool
    "con-destructure alias actually RUNS SOUND if admitted (over-rejection)"
  runsSoundUnchecked recProjCm >>= assertBool
    "record-proj alias actually RUNS SOUND if admitted (over-rejection)"

-- | The soundness proof. Generate an M2a-1 program; if the boundary guard accepts
-- it, the unchecked RC run MUST succeed, be heap-balanced, AND match the
-- reference value. If the guard rejects, the run assertion is skipped.
prop_m2a1Escape :: Property
prop_m2a1Escape =
  forAllShrink genM2a1Program shrinkProgram $ \cm0 -> QC.ioProperty $ do
    let cm      = pruneToReachable cm0
        accepted = null (firstOrderNoHandlerViolations cm)
        refRes  = Interp.runModule cm
    rcRes <- RCM.runModuleRCUnchecked (Perceus.insertRC cm)
    let report  =
          "boundary accepted: " <> show accepted
            <> "\ninstrumented ANF:\n" <> T.unpack (Perceus.prettyPerceus cm)
            <> "\nreference: " <> showRes (fmap Interp.renderValue refRes)
            <> "\nrc:        " <> showRcRes rcRes
        memberEsc = hasMemberBodyEscape cm
        partialMember = hasPartialMemberApply cm
        rlamMemberPartial = hasRLamMemberPartial cm
        captureEsc = hasCaptureBodyEscape cm
        captureCallHead = hasCaptureCallHead cm
        crossRegion = hasCrossRegion cm
        -- NON-VACUITY (made explicit, and now LOUD via 'checkCoverage'). Three classes
        -- whose absence would silently gut the proof must be GENERATED, ACCEPTED, and
        -- actually RUN --- not merely skipped as rejects:
        --   * the member-body sibling-escape class (BLOCKER 1);
        --   * the PARTIAL APPLICATION of a multi-arity capturing member (the M2a-2
        --     double-free shape --- the LT path of 'enterRC's 'RVRecMember' arm); and
        --   * the RLAM-MEDIATED member-partial class (CROSS 5/6) --- a recursive
        --     member flowed THROUGH an 'RLam' that is itself partially applied, so the
        --     'NClosure' LT branch's 'CaptureMode' propagation (the shared-env
        --     retain/release fix) is exercised through a closure, not only through a
        --     bare named head. Without this floor a regression that stops generating
        --     the RLam-mediated crosses would leave the propagation unguarded.
        -- 'checkCoverage' (wrapping the whole property below) turns each 'cover'
        -- floor from an inert warning into a HARD FAILURE: if a generator regression
        -- stops producing any class above its floor, the property goes red.
        ranSound = accepted && either (const False) (const True) rcRes
    pure $ checkCoverage $
       cover 4.0 (memberEsc && ranSound) "member-body sibling escape: accepted+run" $
       cover 3.0 (partialMember && ranSound) "partial multi-arity member apply: accepted+run" $
       cover 3.0 (rlamMemberPartial && ranSound) "RLam-mediated member partial (CROSS 5/6): accepted+run" $
       cover 5.0 (captureEsc && ranSound) "member-body CAPTURE escape: accepted+run" $
       cover 3.0 (captureCallHead && ranSound) "member-body CAPTURE call-head: accepted+run" $
       -- CROSS-REGION (#3): the class MUST be generated AND REJECTED (the fence is the
       -- only thing keeping a cross-region counted edge out; its absence from coverage
       -- previously left the fence with ZERO generative teeth). The 'cover' pins the
       -- generation rate; the conjoined property below pins that a generated
       -- cross-region program is ALWAYS rejected, so a regression that stops rejecting
       -- cross-region goes red.
       cover 3.0 (crossRegion && not accepted) "cross-region capture: generated+rejected" $
       counterexample ("cross-region program was NOT rejected (fence regression): "
                         <> T.unpack (Perceus.prettyPerceus cm))
         (not crossRegion || not accepted)
         .&&.
       QC.label (if memberEsc
                   then if accepted then "member-body-escape: accepted+run"
                                    else "member-body-escape: rejected"
                   else if partialMember
                          then if accepted then "partial-member-apply: accepted+run"
                                           else "partial-member-apply: rejected"
                          else "other shape")
       (counterexample report $
         if not accepted
           then property True   -- rejection is the conservative, always-sound verdict
           else case (refRes, rcRes) of
                  (Right v, Right run) ->
                    let outOk      = Interp.renderValue v == RCM.rcOutput run
                        st         = RCM.rcStats run
                        baseline   = RCM.rcBaseline run
                        liveOk     = St.stLive st == baseline
                        balancedOk = St.stAllocs st - St.stFrees st == baseline
                    in counterexample "ACCEPTED but unsound: output / heap-empty / balanced mismatch"
                         (outOk && liveOk && balancedOk)
                  -- BOTH failing is AGREEMENT ONLY when they fail the SAME WAY (a
                  -- shared evaluator limitation). It is NOT a free pass: an RC
                  -- memory-safety fault (double-free / UAF / dangling --- a 'PrimError'
                  -- the store-less reference can NEVER produce) is a real one-sided
                  -- soundness fault that MUST fail loudly even when the reference also
                  -- errored, and a freed-env UAF can surface as a quiet 'UnboundVar'.
                  -- Mirrors 'assertRcAgrees': reject any RC mem-safety fault, then
                  -- require the two failures to share an error constructor.
                  (Left refE, Left rcE)
                    | rcMemSafetyFault rcE ->
                        counterexample ("ACCEPTED but unsound: RC memory-safety fault hidden behind a \
                                        \reference failure: rc=" <> show rcE <> " ref=" <> show refE)
                          False
                    | errCtorTag refE == errCtorTag rcE ->
                        counterexample "both interpreters failed the same way (agreement)" True
                    | otherwise ->
                        counterexample ("ACCEPTED but unsound: RC failure DIVERGES from the reference \
                                        \failure: ref=" <> show refE <> " rc=" <> show rcE)
                          False
                  _ ->
                    counterexample "ACCEPTED but unsound: exactly one interpreter failed" False)
  where
    showRes (Right t)  = T.unpack t
    showRes (Left e)   = "FAILED (" <> show e <> ")"
    showRcRes (Right run) = T.unpack (RCM.rcOutput run)
    showRcRes (Left e)    = "FAILED (" <> show e <> ")"

-- | Structural detector for the MEMBER-BODY sibling-escape class (BLOCKER 1): a
-- 'LetRec' MEMBER body (NOT the group body) in which a SIBLING group-binder occurs
-- in an ESCAPING position --- a 'Ret' atom, or a 'RCon'/'RRecord' field, or a
-- non-head call argument. A call-HEAD occurrence (a recursive call) is excluded (it
-- is a borrow, not an escape). Used only for the 'cover'/'label' non-vacuity floor.
hasMemberBodyEscape :: CoreModule -> Bool
hasMemberBodyEscape (CoreModule bs) = any (topB) bs
  where
    topB (TopBind _ _ body) = go Set.empty body
    -- @sibs@ = the group-binder Uniques whose MEMBER BODIES we are currently inside.
    go sibs e = case e of
      Ret a              -> escapesSib sibs [a]
      Let _ r body       -> rhsEsc sibs r || go sibs body
      Case _ alts        -> any (altG sibs) alts
      LetJoin _ _ jb body -> go sibs jb || go sibs body
      Jump _ as          -> escapesSib sibs as
      LetRec defs body   ->
        let gU = Set.fromList [ binderUnique b | (b, _, _) <- defs ]
            -- INSIDE each member body the siblings are escape candidates.
            inMember = any (\(_, _, d) -> go gU d) defs
        in inMember || go sibs body   -- group body uses the OUTER sibs only
      Handle _ _         -> False
      InstallHandler{} -> False
    altG sibs (AltCon _ _ b) = go sibs b
    altG sibs (AltLit _ b)   = go sibs b
    altG sibs (AltDefault b) = go sibs b
    -- An escaping RHS: a sibling moved into a con/record field or a non-head call
    -- argument. The call HEAD of an 'RApp' is a borrow (excluded). 'RLam' captures
    -- are handled by descending (a captured sibling escapes via the closure cell).
    rhsEsc sibs r = case r of
      RCon _ as       -> escapesSib sibs as
      RRecord _ flds  -> escapesSib sibs (map snd flds)
      RApp _ as       -> escapesSib sibs as            -- args escape; head borrows
      RLam _ b        -> go sibs b
      _               -> False
    escapesSib sibs as = any (\a -> case a of AVar n -> Set.member (nameUniq n) sibs; _ -> False) as

-- | Structural detector for the CAPTURE-BODY-escape class (the capture analogue of
-- 'hasMemberBodyEscape', the M2CaptureBodyEscape family): a 'LetRec' MEMBER body
-- that ESCAPES an ENCLOSING BOXED CAPTURE --- a boxed free variable bound OUTSIDE
-- the group that is NEITHER a sibling group binder NOR one of that member's own
-- params --- by carrying it OUT as (part of) the body's RETURN VALUE.
--
-- The detector is SPECIFIC to that class. It must NOT fire on a SIBLING-member
-- escape (a member returning a fellow group binder --- the M2MemberBodyEscape
-- family) nor on a recursion-SEED escape (an enclosing value returned from the
-- GROUP BODY, not from inside a member body) --- those are distinct code paths.
-- The earlier detector was over-broad (it fired on ~55% of programs across every
-- family) because it tracked ANY enclosing 'Unique' as a capture, regardless of
-- boxedness, and counted escapes that were not genuine member-body capture flows.
--
-- The specificity comes from mirroring the real pass predicate
-- 'letRecMemberConsumesCaptureNonEscaping' / 'captureEscapesBody' in
-- "src/Wok/IR/Escape.hs": for each group member we compute its enclosing boxed
-- capture set (free vars of the body, minus the member's params, minus the group
-- binders, intersected with the boxed binders in scope) and fire iff SOME such
-- capture flows OUT of that member body as its return value. The escape walk
-- ('captureFlowsOut') is a focused AST matcher --- it does NOT re-run the pass.
-- Used only for the 'cover' / 'label' non-vacuity floor.
hasCaptureBodyEscape :: CoreModule -> Bool
hasCaptureBodyEscape (CoreModule bs) = any topB bs
  where
    -- @boxed@ = Uniques of BOXED binders bound in ENCLOSING scopes (capture
    -- candidates for any nested group member).
    topB (TopBind _ ps body) = go (boxedOf ps) body
    go boxed e = case e of
      Ret _                -> False
      Jump _ _             -> False
      Let b r body         ->
        goR boxed r
          || go (extend boxed [b]) body
      Case _ alts          -> any (altG boxed) alts
      LetJoin _ ps jb body -> go (extend boxed ps) jb || go boxed body
      LetRec defs body     ->
        let groupU = Set.fromList [ binderUnique b | (b, _, _) <- defs ]
            -- A member body's enclosing boxed captures: its free vars, minus its own
            -- params, minus the sibling group binders, intersected with the boxed
            -- binders in enclosing scope. Fire iff one of them flows OUT as the body's
            -- return value (the genuine member-body capture escape).
            memberEscapes (_, dps, d) =
              let params = Set.fromList (map binderUnique dps)
                  caps   = ((freeVarsExpr d `Set.difference` params)
                             `Set.difference` groupU)
                            `Set.intersection` boxed
              in any (`captureFlowsOut` d) (Set.toList caps)
            -- Inside the GROUP BODY the siblings are now in scope (boxed function
            -- binders), but the group body is NOT a member body, so a return there is
            -- a seed/sibling escape (a different code path), not this class.
            boxedBody = extend boxed [ b | (b, _, _) <- defs ]
        in any memberEscapes defs || go boxedBody body
      Handle _ _           -> False
      InstallHandler{}   -> False
    altG boxed (AltCon _ bs' b) = go (extend boxed bs') b
    altG boxed (AltLit _ b)     = go boxed b
    altG boxed (AltDefault b)   = go boxed b
    goR boxed r = case r of
      RLam _ b -> go boxed b
      _        -> False
    extend boxed bs' = Set.union boxed (boxedOf bs')
    boxedOf = Set.fromList . map binderUnique . filter (Esc.isBoxedType . bndType)

-- | True iff the captured value @u0@ flows OUT of the member body @body@ AS (part
-- of) its RETURN VALUE: it (or a con/record container holding it, or an alias)
-- reaches a 'Ret' or a 'Jump' argument. Mirrors 'captureEscapesBody' in
-- "src/Wok/IR/Escape.hs" --- the exact admissible-escape rule the pass dup-balances
-- --- but as a TEST-side AST matcher (no pass internals imported). A capture sealed
-- into a con/record that is destructured-and-dropped INSIDE the body, passed as a
-- call argument, re-captured into a nested closure, or projected does NOT count.
captureFlowsOut :: Unique -> Expr -> Bool
captureFlowsOut u0 = goE (Set.singleton u0)
  where
    hit tracked a = case a of
      AVar n -> nameUniq n `Set.member` tracked
      ALit _ -> False
      APrim _ -> False
    anyHit tracked = any (hit tracked)
    goE tracked e = case e of
      Ret a              -> hit tracked a
      Jump _ as          -> anyHit tracked as
      Let bd r body      -> case r of
        RAtom (AVar n)
          | nameUniq n `Set.member` tracked ->
              goE (Set.insert (binderUnique bd) tracked) body
        RCon _ as
          | anyHit tracked as ->
              goE (Set.insert (binderUnique bd) tracked) body
        RRecord _ flds
          | anyHit tracked (map snd flds) ->
              goE (Set.insert (binderUnique bd) tracked) body
        _ -> goE tracked body
      LetRec ds body     -> any (\(_, _, d) -> goE tracked d) ds || goE tracked body
      Case _ alts        -> any (goAlt tracked) alts
      LetJoin _ _ jb body -> goE tracked jb || goE tracked body
      Handle e' _        -> goE tracked e'
      InstallHandler _ _ e' -> goE tracked e'
    goAlt tracked (AltCon _ _ e) = goE tracked e
    goAlt tracked (AltLit _ e)   = goE tracked e
    goAlt tracked (AltDefault e) = goE tracked e

-- ---------------------------------------------------------------------------
-- DRIFT GUARD for the single-source escape walker (feat/rc-escape-single-source)
--
-- 'Esc.captureEscapesBody' was refactored to DERIVE from the shared 'escapeWalk'
-- skeleton instead of re-listing its own per-'Rhs' case table. The refactor is a
-- pure dedup --- it MUST be result-identical on every input. 'oldCaptureEscapesBody'
-- below is a FROZEN, byte-faithful copy of the pre-refactor hand-rolled definition;
-- it is the ORACLE. 'prop_captureEscapesBodyMatchesOracle' pins the two equal over
-- generated programs, and 'captureEscapesBodyDriftGuard' pins them over a battery of
-- hand-built RHS shapes (Ret/Jump/RCon/RRecord/RProj/RApp-arg/RApp-head/alias-chain/
-- Case). If a future edit to the shared skeleton drifts the verdict on ANY shape, one
-- of these fails. DO NOT "fix" the oracle to track the new behaviour --- a divergence
-- is a real regression in the dedup.

-- | FROZEN ORACLE: the pre-refactor hand-rolled 'captureEscapesBody'. Kept verbatim
-- so a drift in the shared 'escapeWalk' fold is caught. (Mirror only --- never edit
-- to follow a behaviour change.)
oldCaptureEscapesBody :: Unique -> Expr -> Bool
oldCaptureEscapesBody u0 = goE (Set.singleton u0)
  where
    hit tracked a = case a of
      AVar n -> Name.nameUniq n `Set.member` tracked
      ALit _ -> False
      APrim _ -> False
    anyHit tracked = any (hit tracked)
    goE tracked e = case e of
      Ret a                 -> hit tracked a
      Jump _ as             -> anyHit tracked as
      Let bd r body         -> case r of
        RAtom (AVar n)
          | Name.nameUniq n `Set.member` tracked ->
              goE (Set.insert (binderUnique bd) tracked) body
        RCon _ as
          | anyHit tracked as ->
              goE (Set.insert (binderUnique bd) tracked) body
        RRecord _ flds
          | anyHit tracked (map snd flds) ->
              goE (Set.insert (binderUnique bd) tracked) body
        _ -> goE tracked body
      LetRec ds body        -> any (\(_, _, d) -> goE tracked d) ds || goE tracked body
      Case _ alts           -> any (goAlt tracked) alts
      LetJoin _ _ jb body   -> goE tracked jb || goE tracked body
      Handle e' _           -> goE tracked e'
      InstallHandler _ _ e'   -> goE tracked e'
    goAlt tracked (AltCon _ _ e) = goE tracked e
    goAlt tracked (AltLit _ e)   = goE tracked e
    goAlt tracked (AltDefault e) = goE tracked e

-- | Every 'Unique' that NAMES a binder or occurs as an atom anywhere in @e@. Used
-- as the drift-guard's probe set: 'captureEscapesBody' must agree with the oracle on
-- ALL of them (not just genuine captures), so the equality is total over the corpus.
allMentionedUniques :: Expr -> Set.Set Unique
allMentionedUniques = go
  where
    go e = case e of
      Ret a               -> atomVars a
      Jump _ as           -> Set.unions (map atomVars as)
      Let bd r body       -> Set.insert (binderUnique bd) (goR r) `Set.union` go body
      LetRec ds body      ->
        Set.unions (go body : [ Set.insert (binderUnique b) (go d) | (b, _, d) <- ds ])
      Case a alts         -> atomVars a `Set.union` Set.unions (map goAlt alts)
      LetJoin _ ps jb body ->
        Set.fromList (map binderUnique ps) `Set.union` go jb `Set.union` go body
      Handle e' _         -> go e'
      InstallHandler a _ e' -> atomVars a `Set.union` go e'
    goAlt (AltCon _ bs e) = Set.fromList (map binderUnique bs) `Set.union` go e
    goAlt (AltLit _ e)    = go e
    goAlt (AltDefault e)  = go e
    goR r = case r of
      RAtom a      -> atomVars a
      RApp h as    -> Set.unions (map atomVars (h : as))
      RCon _ as    -> Set.unions (map atomVars as)
      RLam ps e    -> Set.fromList (map binderUnique ps) `Set.union` go e
      ROp m _ _ as -> Set.unions (map atomVars (maybe as (: as) m))
      RRecord _ fl -> Set.unions (map (atomVars . snd) fl)
      RProj _ a    -> atomVars a
      RMakeHandler _ -> Set.empty   -- proto/handler-values: never in this hand-built/generated corpus; internals ignored like Handle's
      RReuseCon{}             -> error "RReuseCon: produced only by reusePairing post-pass (never in hand-built test IR)"
      RForeignCall _ _ _ _ _ as -> Set.unions (map atomVars as)

-- | All sub-expressions of @e@ (including @e@ itself), so the drift guard probes
-- 'captureEscapesBody' at every body position, not just the top.
allSubExprs :: Expr -> [Expr]
allSubExprs e = e : case e of
  Ret _                -> []
  Jump _ _             -> []
  Let _ r body         -> rhsSub r ++ allSubExprs body
  LetRec ds body       -> concat [ allSubExprs d | (_, _, d) <- ds ] ++ allSubExprs body
  Case _ alts          -> concatMap altSub alts
  LetJoin _ _ jb body  -> allSubExprs jb ++ allSubExprs body
  Handle e' _          -> allSubExprs e'
  InstallHandler _ _ e'  -> allSubExprs e'
  where
    altSub (AltCon _ _ b) = allSubExprs b
    altSub (AltLit _ b)   = allSubExprs b
    altSub (AltDefault b) = allSubExprs b
    rhsSub (RLam _ b)     = allSubExprs b
    rhsSub _              = []

-- | DRIFT GUARD (generative): 'Esc.captureEscapesBody' must equal the frozen oracle
-- on EVERY (capture 'Unique', sub-expression) pair of every generated program. A
-- single disagreement is a regression in the single-source fold.
prop_captureEscapesBodyMatchesOracle :: Property
prop_captureEscapesBodyMatchesOracle =
  forAllShrink genM2a1Program shrinkProgram $ \(CoreModule binds) ->
    conjoin
      [ counterexample
          ("captureEscapesBody DRIFTED from oracle for u=" <> show u
             <> "\nsub-expr:\n" <> show sub)
          (Esc.captureEscapesBody u sub QC.=== oldCaptureEscapesBody u sub)
      | TopBind _ _ body <- binds
      , sub <- allSubExprs body
      , u   <- Set.toList (allMentionedUniques sub)
      ]

-- | DRIFT GUARD (hand-built shapes): pin 'captureEscapesBody' against the oracle on
-- the matrix the M2a-2 admit/reject verdicts turn on --- Ret/Jump (escape), a
-- returned RCon/RRecord container (escape via the tracked-closure), an RProj parent
-- / a non-head RApp arg / an RApp head / a re-capturing RLam / an ROp arg (all
-- NON-escape), and an alias chain that ends in a Ret (escape). The oracle equality
-- is the single-source property; we additionally assert the GROUND TRUTH verdict on
-- each shape so the matrix itself is pinned, not just self-consistency.
captureEscapesBodyDriftGuard :: Assertion
captureEscapesBodyDriftGuard = do
  let u  = Unique 9001
      nU = Name (T.pack "u") u
      boxed = Ty.CTCon Ty.TcBool []
      bnd t uq = Binder (Name (T.pack "b") (Unique uq)) Unrestricted t
      var uq = AVar (Name (T.pack "b") (Unique uq))
      -- shape, expected verdict
      shapes :: [(String, Expr, Bool)]
      shapes =
        [ ("Ret of capture",            Ret (AVar nU),                       True)
        , ("Jump of capture",           Jump (JoinId (Unique 1)) [AVar nU],  True)
        , ("returned RCon container",
            Let (bnd boxed 10) (RCon (T.pack "Box") [AVar nU])
              (Ret (var 10)),                                                True)
        , ("returned RRecord container",
            Let (bnd boxed 11) (RRecord (T.pack "R") [(T.pack "f", AVar nU)])
              (Ret (var 11)),                                                True)
        , ("alias chain then Ret",
            Let (bnd boxed 12) (RAtom (AVar nU))
              (Let (bnd boxed 13) (RAtom (var 12)) (Ret (var 13))),          True)
        , ("RCon container destructured-and-dropped locally",
            Let (bnd boxed 14) (RCon (T.pack "Box") [AVar nU])
              (Ret (ALit LUnit)),                                            False)
        , ("non-head RApp arg (consumed by callee)",
            Let (bnd boxed 15) (RApp (var 99) [AVar nU]) (Ret (ALit LUnit)), False)
        , ("RApp head (borrow)",
            Let (bnd boxed 16) (RApp (AVar nU) [ALit LUnit]) (Ret (ALit LUnit)), False)
        , ("re-capture into nested RLam",
            Let (bnd boxed 17) (RLam [bnd boxed 18] (Ret (AVar nU)))
              (Ret (ALit LUnit)),                                            False)
        , ("RProj parent",
            Let (bnd boxed 19) (RProj (T.pack "f") (AVar nU)) (Ret (ALit LUnit)), False)
        , ("ROp arg",
            Let (bnd boxed 20) (ROp Nothing (T.pack "E") (T.pack "op") [AVar nU])
              (Ret (ALit LUnit)),                                            False)
        , ("Case scrutinee (matched, not flowed out)",
            Case (AVar nU) [AltDefault (Ret (ALit LUnit))],                  False)
        , ("capture re-named inside Case alt then Ret",
            Case (ALit LUnit) [AltDefault (Ret (AVar nU))],                  True)
        ]
  mapM_ (\(label, expr, expected) -> do
            assertEqual (label <> ": verdict") expected (Esc.captureEscapesBody u expr)
            assertEqual (label <> ": matches oracle")
              (oldCaptureEscapesBody u expr) (Esc.captureEscapesBody u expr))
        shapes

-- | Non-vacuity detector for the M2CaptureCallHead family (the call-head admit
-- guard): a 'LetRec' MEMBER body in which an enclosing CAPTURE (a 'Unique' bound
-- OUTSIDE the group --- not a sibling, not a member param) occurs as an 'RApp' call
-- HEAD. A call head is a BORROW, so this shape must be ADMITTED and run sound; the
-- floor keeps the generator from silently dropping it. Mirrors the @outer@/
-- @inMember@ threading of 'hasCaptureBodyEscape'.
hasCaptureCallHead :: CoreModule -> Bool
hasCaptureCallHead (CoreModule bs) = any topB bs
  where
    topB (TopBind _ ps body) = go (Set.fromList (map binderUnique ps)) False body
    go outer inMember e = case e of
      Ret _                -> False
      Jump _ _             -> False
      Let b r body         ->
        rhsHead outer inMember r
          || go (Set.insert (binderUnique b) outer) inMember body
      Case _ alts          -> any (altG outer inMember) alts
      LetJoin _ ps jb body ->
        let outer' = Set.union outer (Set.fromList (map binderUnique ps))
        in go outer' inMember jb || go outer inMember body
      LetRec defs body     ->
        let gU = Set.fromList [ binderUnique b | (b, _, _) <- defs ]
            inDef (_, dps, d) =
              go (Set.union outer (Set.fromList (map binderUnique dps))) True d
            outerBody = Set.union outer gU
        in any inDef defs || go outerBody inMember body
      Handle _ _           -> False
      InstallHandler{}   -> False
    altG outer inMember (AltCon _ bs' b) =
      go (Set.union outer (Set.fromList (map binderUnique bs'))) inMember b
    altG outer inMember (AltLit _ b)   = go outer inMember b
    altG outer inMember (AltDefault b) = go outer inMember b
    rhsHead outer inMember r = case r of
      RApp (AVar n) _ -> inMember && Set.member (nameUniq n) outer
      _               -> False

-- | Non-vacuity detector for the M2CrossRegion family (the cross-region #3 fence):
-- some 'LetRec' group, somewhere, captures an OUTER 'LetRec' GROUP-MEMBER binder ---
-- a free var of an inner group member that is bound by an ENCLOSING group still in
-- scope (NOT by this group, NOT by the member's own params). Mirrors the boundary
-- 'crossRegionViol' predicate (@rawEnclosingFv defs ∩ lr@) as a TEST-side AST matcher:
-- @lr@ is threaded as the set of enclosing group binders in scope. Used only for the
-- 'cover' floor that the cross-region class is GENERATED (and, paired with the
-- always-reject verdict, REJECTED), giving the otherwise-untested fence generative
-- teeth. The fence is the SOURCE OF TRUTH; this is a structural witness, not a re-run.
hasCrossRegion :: CoreModule -> Bool
hasCrossRegion (CoreModule bs) = any topB bs
  where
    topB (TopBind _ _ body) = go Set.empty body
    -- @lr@ = the Uniques of group binders bound by ENCLOSING (in-scope) LetRec groups.
    go lr e = case e of
      Ret _              -> False
      Jump _ _           -> False
      Let _ r body       -> goR lr r || go lr body
      Case _ alts        -> any (altG lr) alts
      LetJoin _ _ jb body -> go lr jb || go lr body
      Handle e' _        -> go lr e'
      InstallHandler _ _ e' -> go lr e'
      LetRec defs body   ->
        let groupU = Set.fromList [ binderUnique b | (b, _, _) <- defs ]
            params ps = Set.fromList (map binderUnique ps)
            rawEncl =
              Set.unions
                [ (freeVarsExpr d `Set.difference` params ps) `Set.difference` groupU
                | (_, ps, d) <- defs ]
            -- cross-region: an inner member captures an OUTER region member (in @lr@).
            here = not (Set.null (Set.intersection rawEncl lr))
            lr'  = Set.union lr groupU
            -- member bodies see the EXTENDED region set (so a doubly-nested group's
            -- capture of the outermost member is detected too).
            inMembers = any (\(_, _, d) -> go lr' d) defs
        in here || inMembers || go lr' body
    altG lr (AltCon _ _ b) = go lr b
    altG lr (AltLit _ b)   = go lr b
    altG lr (AltDefault b) = go lr b
    goR lr r = case r of
      RLam _ b -> go lr b
      _        -> False

-- | The static oracle must be clean on every IN-FRAGMENT generated program (one
-- the boundary guard ACCEPTS). 'balanceLint' runs 'insertRC' itself and does not
-- consult the boundary guard, so on an ESCAPING (out-of-fragment) program ---
-- e.g. a sibling alias that is RETURNED --- it CORRECTLY reports the over-consume
-- of the escaped value ("not owned here"); that is the conservative reject the
-- boundary makes, not a pass bug. We therefore gate on acceptance (in-fragment)
-- and document the skip: a boundary-rejected program may legitimately lint dirty.
prop_m2a1LintClean :: Property
prop_m2a1LintClean =
  forAllShrink genM2a1Program shrinkProgram $ \cm0 ->
    let cm   = pruneToReachable cm0
        viol = Perceus.balanceLint cm
    in if not (null (firstOrderNoHandlerViolations cm))
         then property True   -- out-of-fragment: a dirty lint is the conservative reject
         else counterexample ("balanceLint reported on an IN-FRAGMENT program: " <> show viol
                                <> "\nANF:\n" <> T.unpack (Perceus.prettyPerceus cm))
                (null viol)

-- | Generalized fault-injection: for every generated program, each single-site
-- mutation must be CAUGHT --- either 'lintInstrumented' flags the mutated,
-- already-instrumented module, OR the unchecked RC run trips a 'Left'. This turns
-- the three hand teeth into a generative oracle. A mutation that is a structural
-- no-op on a particular program (e.g. 'OmitOneDrop' when the program inserts no
-- drop) leaves the bytes IDENTICAL to the correct instrumentation; we detect that
-- and treat it as vacuously fine for that program (no mutation actually happened),
-- so it is not a false counterexample.
prop_m2a1Teeth :: Property
prop_m2a1Teeth =
  forAllShrink genM2a1Program shrinkProgram $ \cm0 -> QC.ioProperty $ do
    let cm = pruneToReachable cm0
    props <- mapM
      (\mut -> do
         caught <- mutationCaught mut cm
         pure (counterexample ("mutation " <> show mut <> " was NOT caught\nANF:\n"
                                 <> T.unpack (Perceus.prettyPerceus cm))
                 caught))
      [Perceus.OmitOneDrop, Perceus.OmitOneDup, Perceus.DuplicateOneDrop]
    pure (conjoin props)

-- | Is the given single-site mutation caught on this module, or a structural
-- no-op? Caught = a non-empty 'lintInstrumented' OR a 'Left' from the unchecked
-- RC run OR the mutation is semantically inert on uncounted values. No-op
-- cases (all count as "fine"):
--   1. The mutated instrumentation is byte-identical to the correct one (the
--      mutation site did not exist).
--   2. The mutation omitted/duplicated a __rc_drop/__rc_dup that targets an
--      INLINE (uncounted) immediate: with 'Inline' addresses, a drop/dup of a
--      nullary constructor is always a no-op on the heap. Both the correct and
--      mutated modules produce the same heap accounting, so the mutation is
--      genuinely harmless (not a soundness violation -- the drop was already
--      inert).
mutationCaught :: Perceus.Mutation -> CoreModule -> IO Bool
mutationCaught mut cm = do
  let correct = Perceus.insertRC cm
      mutated = Perceus.insertRCMutated mut cm
  if mutated == correct                                  -- mutation was a no-op
       || not (null (Perceus.lintInstrumented mutated))  -- caught statically
    then pure True
    else RCM.runModuleRCUnchecked mutated >>= \case      -- caught at runtime
           Left _     -> pure True
           Right mrun ->
             -- If the mutated run succeeds AND its heap stats match the correct
             -- run's stats (same allocs/frees/peak/live/baseline), the mutation
             -- only targeted an uncounted value (e.g. a drop of an Inline
             -- immediate). That is harmless: the drop was already a no-op.
             RCM.runModuleRCUnchecked correct >>= \case
               Left _     -> pure False  -- correct run itself is broken; skip
               Right crun ->
                 let ms = RCM.rcStats mrun
                     cs = RCM.rcStats crun
                 in pure (St.stAllocs ms == St.stAllocs cs
                       && St.stFrees  ms == St.stFrees  cs
                       && St.stPeak   ms == St.stPeak   cs
                       && St.stLive   ms == St.stLive   cs
                       && RCM.rcBaseline mrun == RCM.rcBaseline crun)

-- | Shrinking: drop the program toward a constant. We shrink the single 'main'
-- bind's body to its trivial sub-results (a 'Ret' of a contained atom, an alt
-- body, or a let body), preserving well-scopedness by only ever REPLACING an
-- expression with one of its own sub-expressions whose free variables are a
-- subset of the original's. The simplest safe shrink: replace the body with a
-- 'Ret' of a literal of the same shape is unsound (type may differ), so we only
-- climb into structurally-contained sub-expressions.
shrinkProgram :: CoreModule -> [CoreModule]
shrinkProgram (CoreModule [TopBind n ps body]) =
  [ CoreModule [TopBind n ps body'] | body' <- shrinkExpr body ]
shrinkProgram _ = []

-- | Sub-expressions reachable by peeling one constructor layer, restricted to
-- those that remain WELL-SCOPED on their own (no free variable bound only by the
-- peeled layer). Returns same-typed continuations only (a let body, an alt body),
-- never a differently-typed fragment.
shrinkExpr :: Expr -> [Expr]
shrinkExpr e = case e of
  Let b _ body
    | not (Name.nameUniq (bndName b) `Set.member` exprUniques body) -> [body]
    | otherwise -> []
  Case _ alts ->
    [ altBody | alt <- alts
              , Just altBody <- [altClosedBody alt] ]
  -- A join cluster: recursively shrink the delivering body, keeping the join
  -- DEFINED so no 'Jump' is stranded; additionally offer dropping the whole join
  -- iff the delivering body never jumps to it. We never extract a join body alone
  -- (it may reference the join params or the captured var).
  LetJoin j ps jb body ->
    [ LetJoin j ps jb body' | body' <- shrinkExpr body ]
      ++ [ body | not (exprJumpsTo j body) ]
  _ -> []
  where
    -- Only extract an alt body that is well-scoped on its own: no free child
    -- binder, and no 'Jump' (which would dangle once its enclosing join is gone).
    altClosedBody (AltCon _ bs b)
      | not (any (\bd -> Name.nameUniq (bndName bd) `Set.member` exprUniques b) bs)
      , not (exprHasJump b) = Just b
      | otherwise = Nothing
    altClosedBody (AltLit _ b)   | not (exprHasJump b) = Just b
                                 | otherwise           = Nothing
    altClosedBody (AltDefault b) | not (exprHasJump b) = Just b
                                 | otherwise           = Nothing

-- | Does @e@ contain any 'Jump' (which would dangle if extracted from its
-- enclosing join)? Used to keep 'shrinkExpr' from producing ill-scoped fragments.
exprHasJump :: Expr -> Bool
exprHasJump (Jump _ _)         = True
exprHasJump (Ret _)            = False
exprHasJump (Let _ _ e)        = exprHasJump e
exprHasJump (Case _ alts)      = any (exprHasJump . clusterAltBody) alts
exprHasJump (LetJoin _ _ jb e) = exprHasJump jb || exprHasJump e
exprHasJump (LetRec ds e)      = any (\(_, _, b) -> exprHasJump b) ds || exprHasJump e
exprHasJump (Handle e _)       = exprHasJump e
exprHasJump (InstallHandler _ _ e) = exprHasJump e

-- | Does @e@ jump to the specific join @j@ (so dropping @j@'s binder would strand it)?
exprJumpsTo :: JoinId -> Expr -> Bool
exprJumpsTo j (Jump j' _)        = j == j'
exprJumpsTo _ (Ret _)            = False
exprJumpsTo j (Let _ _ e)        = exprJumpsTo j e
exprJumpsTo j (Case _ alts)      = any (exprJumpsTo j . clusterAltBody) alts
exprJumpsTo j (LetJoin _ _ jb e) = exprJumpsTo j jb || exprJumpsTo j e
exprJumpsTo j (LetRec ds e)      = any (\(_, _, b) -> exprJumpsTo j b) ds || exprJumpsTo j e
exprJumpsTo j (Handle e _)       = exprJumpsTo j e
exprJumpsTo j (InstallHandler _ _ e) = exprJumpsTo j e

clusterAltBody :: Anf.Alt -> Expr
clusterAltBody (AltCon _ _ b) = b
clusterAltBody (AltLit _ b)   = b
clusterAltBody (AltDefault b) = b

-- ===========================================================================
-- Suite G (M2b-1): generative property over the supported HANDLER fragment.
--
-- The hand-written corpus 'test/rc-m2b/01..07' covers only the shapes we thought
-- to write. This generator is the DURABLE adversarial oracle: for every generated,
-- in-fragment, one-shot handler program, the RC interpreter must HEAP-BALANCE and
-- AGREE with the reference interpreter. A shape that isn't generated is a shape that
-- ships green-broken --- so the generator MUST stress the owned-set failure modes
-- (spec §4.2): a value MOVED into a cell before the op (the stale binder must not
-- double-free), a boxed value LIVE ACROSS the op, two distinct ALIASES of one cell
-- (both freed, matching the dup), a global/CAF reference across the op (must NOT be
-- freed --- 'isStaticAddr'), an op under a non-trivial 'above' (Let / Case / two ops).
--
-- TRACTABLE STRATEGY (do NOT free-generate arbitrary ANF). A program is
-- @main = Handle <progBody> <handler>@ where the handler is one of two AMBIENT
-- (no 'hSelf'), M2b-1-fragment skeletons (hParam = Nothing, hAnswerJoin = Nothing,
-- one-arg resume, resume non-escaping):
--
--   * ABORT:  @op(n, k) -> Some? / None@   --- k is bound, NEVER applied. Perceus
--             drops @k@ at the end of the arm; the runtime frees the captured
--             continuation's OWNED SET (spec §4.2). This is the path where the
--             owned-set computation is exercised (the moved/aliased/captured cases).
--   * RESUME: @op(n, k) -> let r = k <x> in r@  --- tail-applies @k@; the captured
--             frames splice back and run. This exercises the move-out path (spliced
--             frames' own drops fire; the shell frees without cascade).
--
-- The op-performing 'progBody' is varied across the owned-set dimensions. Building
-- correct ANF directly (boxed types for cons/box/pair, unboxed U64 for scalars) the
-- same way 'genM2a1Program' does. Ambient dispatch ('ROp Nothing') routes to the
-- nearest covering handler, so no self-instance binder is needed --- the simplest
-- in-fragment shape. Out-of-fragment shapes are not generated (we keep the handlers
-- no-param / tail / one-arg / resume-non-escaping); the boundary guard would reject
-- any that slipped, making the property vacuously true for them.

-- | Which handler skeleton wraps the generated computation.
data M2bHandlerKind
  = M2bAbort        -- ^ op arm returns a value WITHOUT applying resume (abort / no-resume)
  | M2bTailResume   -- ^ op arm tail-applies resume (tail-resume move-out)
  | M2bTwoArgResume -- ^ PARAMETERIZED handler (hParam = Just sB): op arm does two-arg
                    --   resume (baton model, M2b-2 Task 4D).  The old boxed param is
                    --   dropped by the arm's Perceus-inserted __rc_drop; the new param
                    --   (a fresh Box cell) is owned by the reinstalled KHandleRC frame.
  | M2bValueResume  -- ^ VALUE-POSITION handler (hAnswerJoin = Just j): the Handle sits
                    --   inside a LetJoin; arms deliver via Jump j; answerRebindRC re-points
                    --   j on each resume so the sub-run's answer routes to the resume site.
  | M2bValueAbort   -- ^ VALUE-POSITION abort: same LetJoin wrapping, op arm aborts
                    --   (never applies resume), so answerRebindRC is a no-op on the abort
                    --   path; the outer case on the join result still runs.
  deriving (Eq, Show)

-- | The owned-set dimension the generated computation stresses (spec §4.2 / §7).
data M2bShape
  = M2bMovedBeforeOp     -- ^ a boxed value MOVED into a cell before the op (abort):
                         --   the stale binder must NOT double-free (the §4.2 counterexample).
  | M2bCapturedBoxed     -- ^ a boxed value LIVE in the captured frame (created before,
                         --   used after the op): freed once on abort, moved-back on resume.
  | M2bAliasedBoxed      -- ^ two distinct ALIASES (@let a = x@ the pass dup'd) of one cell,
                         --   both live across the op: freed twice, matching the refcount.
  | M2bGlobalAcrossOp    -- ^ a top-level boxed CAF referenced across the op: must NOT be
                         --   freed (static addr); pins the 'isStaticAddr' no-op.
  deriving (Eq, Show, Enum, Bounded)

-- | A boxed catch-all return/escape vehicle type. 'isBoxedType' tracks it as a heap
-- cell, the same convention as 'boxTyC' in the m2a-1 generator.
m2bBoxTy :: Ty.CType
m2bBoxTy = Ty.CTCon (Ty.TcUser (T.pack "Box")) []

m2bPairTy :: Ty.CType
m2bPairTy = gtyCType GPair

m2bListTy :: Ty.CType
m2bListTy = gtyCType GList

m2bOptTy :: Ty.CType
m2bOptTy = Ty.CTCon (Ty.TcUser (T.pack "Option")) []

m2bU64 :: Ty.CType
m2bU64 = gtyCType GInt

-- | The single effect label/op the generator uses (ambient). Distinct names so the
-- generated handler is the unique covering handler.
m2bLbl, m2bOp :: Text
m2bLbl = T.pack "Eff"
m2bOp  = T.pack "op"

-- | A SECOND effect label/op used by the nested-param-abort shape: the OUTER
-- aborting handler handles 'OuterEff'.'outerOp' while the INNER parameterized
-- handler handles the original 'm2bLbl'/'m2bOp'. Two distinct labels are needed
-- so ambient dispatch routes each op to the right (nearest covering) handler.
m2bOuterLbl, m2bOuterOp :: Text
m2bOuterLbl = T.pack "OuterEff"
m2bOuterOp  = T.pack "outerOp"

-- | A binary integer prim atom (an 'APrim' by identity, like 'primAtom').
m2bPlus :: Atom
m2bPlus = primAtom (T.pack "+")

-- | Whether the generated computation references a top-level boxed CAF. Carried out
-- of the 'GenM' so 'genM2bProgram' can splice the CAF bind alongside @main@.
data M2bGlobals = M2bGlobals
  { m2bgCafName :: Maybe Name   -- ^ the CAF binder name, when a global is used
  }

-- | The whole-program generator for Suite G's M2b-1 handler fragment. Builds
-- @main = Handle progBody handler@ (plus an optional boxed CAF bind when the global
-- dimension fires), directly as ANF, mirroring 'genM2a1Program'. The handler kind
-- (abort / tail-resume) and the owned-set shape are chosen so the §4.2 dimensions are
-- all reachable; coverage floors in 'prop_m2bEscape' pin that they actually appear.
--
-- With weight 1-in-5 the generator instead emits the NESTED-PARAM-ABORT shape
-- (Task 5 gap): an outer aborting handler wrapping an inner parameterized handler
-- whose body performs a set then triggers the outer abort. This is the shape that
-- requires the (Unique, Addr) dedup in 'continuationOwned' (spec §7).
genM2bProgram :: Gen CoreModule
genM2bProgram = sized $ \sz -> do
  let fuel = max 1 (min sz 4)
  let mainN = Name (T.pack "main") (Unique 1000000)
  useNested <- frequency [(1, pure True), (4, pure False)]
  if useNested
    then do
      -- Nested-param-abort shape: vary the number of inner sets (1 or 2).
      nSets <- elements [1, 2 :: Int]
      (body, globals, _) <- runStateT3 (genM2bNestedParamAbort nSets) 1
      let mainB = TopBind mainN [] body
      case m2bgCafName globals of
        Nothing -> pure (CoreModule [mainB])
        Just cN -> pure (CoreModule [m2bCafBind cN, mainB])
    else do
      -- The aliased shape is only sound on the ABORT path (the pass dup's @let a = x@
      -- and both copies are freed); pairing it with a tail-resume would still be
      -- in-fragment but the move-out semantics make the dimension less pointed, so we
      -- keep aliased on abort. Every other shape is exercised under BOTH handler kinds.
      -- M2bValueResume and M2bValueAbort are value-position variants: the Handle is
      -- wrapped in a LetJoin and arms deliver via Jump (hAnswerJoin = Just j). These
      -- are chosen with weight 1 each (same weight as the tail-position kinds) so the
      -- new cover floors are reachable within 800 tests.
      kind  <- elements [M2bAbort, M2bTailResume, M2bTwoArgResume, M2bValueResume, M2bValueAbort]
      shape0 <- elements [minBound .. maxBound :: M2bShape]
      -- Aliased-boxed only makes sense on the abort path (the pass dup's the alias;
      -- tail-resume or two-arg-resume would re-enter the same binder scope which is
      -- not what we want to stress). Value-position kinds are not abort-only, but
      -- the same reasoning applies: aliased-boxed under value-resume is a fine shape,
      -- but aliased-boxed under value-abort would be the same dedup stress as plain
      -- M2bAbort; normalise to M2bMovedBeforeOp to keep aliased pinned to abort.
      let shape = if shape0 == M2bAliasedBoxed && kind `notElem` [M2bAbort, M2bValueAbort]
                    then M2bMovedBeforeOp
                    else shape0
      -- How many ops the computation performs (1 or 2): a second op makes the captured
      -- 'above' prefix multi-frame and, on tail-resume, drives move-out twice.
      nOps  <- elements [1, 1, 2 :: Int]
      -- Whether the op fires INSIDE a Case arm (so 'above' is a non-trivial multi-frame
      -- prefix that includes a Case continuation), versus only under a Let chain.
      underCase <- elements [False, True]
      (body, globals, _) <-
        runStateT3 (genM2bBody kind shape nOps underCase fuel) 1
      let mainB = TopBind mainN [] body
      case m2bgCafName globals of
        Nothing  -> pure (CoreModule [mainB])
        Just cN  -> pure (CoreModule [m2bCafBind cN, mainB])

-- | Run a 'GenM' that also accumulates an 'M2bGlobals', returning the value, the
-- globals, and the final unique counter. (A thin wrapper over the same 'StateT Int
-- Gen' the m2a-1 generator uses, threading 'M2bGlobals' alongside.)
runStateT3 :: StateT (Int, M2bGlobals) Gen a -> Int -> Gen (a, M2bGlobals, Int)
runStateT3 m u0 = do
  (a, (u, gl)) <- runStateT m (u0, M2bGlobals Nothing)
  pure (a, gl, u)

-- | The Suite-G generation monad: a fresh-Unique counter plus the accumulated
-- top-level CAF usage.
type GenM2b = StateT (Int, M2bGlobals) Gen

freshN2b :: Text -> GenM2b Name
freshN2b hint = state (\(u, gl) -> (Name hint (Unique u), (u + 1, gl)))

liftG2b :: Gen a -> GenM2b a
liftG2b = lift

-- | A fresh 'JoinId' using the same counter as 'freshN2b'. Join IDs occupy a
-- separate namespace from binder 'Name's, so sharing the counter is safe.
freshJoinId2b :: GenM2b JoinId
freshJoinId2b = state (\(u, gl) -> (JoinId (Unique u), (u + 1, gl)))

useCaf :: GenM2b Name
useCaf = state (\(u, gl) ->
  let cN = Name (T.pack "g_caf") (Unique 800000)
  in (cN, (u, gl { m2bgCafName = Just cN })))

-- | The boxed-CAF top-level bind: @g_caf = Cons(9, Nil)@ (a value-CAF; contributes
-- to 'rcBaseline', is never freed, and 'isStaticAddr' must make the abort owned-set
-- skip it). Uniques are reserved well above the 'GenM2b' range.
m2bCafBind :: Name -> TopBind
m2bCafBind cN =
  TopBind cN []
    (Let (Binder (Name (T.pack "g_nil") (Unique 800001)) Unrestricted m2bListTy)
         (RCon (T.pack "Nil") [])
      (Let (Binder cN Unrestricted m2bListTy)
           (RCon (T.pack "Cons") [ALit (LInt 9), AVar (Name (T.pack "g_nil") (Unique 800001))])
        (Ret (AVar cN))))

-- | The handler skeleton. The arm's op-args are one U64 (the op argument). For
-- ABORT and TAIL-RESUME the resume binder is one-arg (no hParam). For
-- TWO-ARG-RESUME a parameterized handler is built (hParam = Just sB supplied by
-- the caller); the op arm installs a fresh Box as the new param and resumes with a
-- unit result, mirroring a State.set arm.  The return arm wraps the result in
-- 'Some' (a boxed cell), so the answer type is 'Option progTy'. hAnswerJoin is
-- 'Nothing' for tail-position kinds; for value-position kinds (@mJoinId = Just j@)
-- every terminal is 'Jump j [x]' and 'hAnswerJoin = Just j'.
genM2bHandler :: M2bHandlerKind -> Ty.CType -> Maybe Binder -> Maybe JoinId -> GenM2b Handler
genM2bHandler kind progTy mParamB mJoinId = do
  vN     <- freshN2b (T.pack "v")
  nN     <- freshN2b (T.pack "opn")
  kN     <- freshN2b (T.pack "k")
  svN    <- freshN2b (T.pack "sv")
  -- Terminal delivery: Jump to the answer join in value position; Ret in tail position.
  let terminal x = case mJoinId of
        Just j  -> Jump j [x]
        Nothing -> Ret x
  let retArm =
        ( Binder vN Unrestricted progTy
        , Let (Binder svN Unrestricted m2bOptTy) (RCon (T.pack "Some") [AVar vN])
            (terminal (AVar svN)) )
  case kind of
    M2bAbort -> do
      noneN <- freshN2b (T.pack "none")
      let armBody = Let (Binder noneN Unrestricted m2bOptTy) (RCon (T.pack "None") [])
                      (terminal (AVar noneN))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] mJoinId Nothing Nothing)
    M2bTailResume -> do
      rN <- freshN2b (T.pack "rr")
      let armBody = Let (Binder rN Unrestricted progTy) (RApp (AVar kN) [ALit (LInt 1)])
                      (terminal (AVar rN))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] mJoinId Nothing Nothing)
    M2bTwoArgResume -> do
      -- Parameterized handler (baton model, M2b-2 Task 4D).
      -- hParam = Just sB, where sB is the param binder allocated OUTSIDE the Handle.
      -- Op arm: op n k -> let np = Box(0) in let r = k(np, ()) in r
      -- The resume binder k takes TWO args (new-param, result); Perceus will insert
      -- __rc_drop(s) after the call (drop old param) to balance ownership.
      npN <- freshN2b (T.pack "np")
      rN  <- freshN2b (T.pack "rr")
      let armBody = Let (Binder npN Unrestricted m2bBoxTy)
                        (RCon (T.pack "Box") [ALit (LInt 0)])
                      (Let (Binder rN Unrestricted progTy)
                           (RApp (AVar kN) [AVar npN, ALit LUnit])
                           (terminal (AVar rN)))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] mJoinId mParamB Nothing)
    -- Value-position variants: the JoinId is always supplied (mJoinId = Just j),
    -- so we delegate to the abort / tail-resume cases above (just with mJoinId set).
    -- These constructors exist to make the generator's intent explicit; they are
    -- handled in 'genM2bBody' / 'genM2bValueBody', which always pass 'Just j' here.
    M2bValueResume -> do
      -- VALUE-POSITION RESUME: calls k (so the sub-run executes), then DISCARDS the
      -- resume result and always delivers 'None' to the answer join j.
      --
      -- Without 'answerRebindRC':
      --   The sub-run's return arm fires 'Jump j [Some v]' into the ORIGINAL j (not
      --   the rebind), which runs the 'Some _ -> 1' arm, giving output "1".
      -- With 'answerRebindRC' working (correct behaviour):
      --   'Jump j [Some v]' routes to the arm's KLetRC via the rebound j. The arm
      --   gets r = Some v, drops it, then fires 'Jump j [None]' → j's 'None -> 0'
      --   arm → output "0".
      -- This produces a genuine reference-vs-RC MISMATCH ("0" vs "1") when
      -- 'answerRebindRC' is neutered, making the RED-CHECK go red.
      --
      -- Dropping 'r' (the resume result, a boxed Option cell) is inserted by
      -- Perceus since 'r' is not used for anything other than being consumed.
      -- 'k' itself is used (called), so Perceus does NOT insert a drop for it.
      rN    <- freshN2b (T.pack "rr")
      noneN <- freshN2b (T.pack "none")
      let armBody = Let (Binder rN Unrestricted m2bOptTy)
                        (RApp (AVar kN) [ALit (LInt 1)])
                      (Let (Binder noneN Unrestricted m2bOptTy)
                           (RCon (T.pack "None") [])
                        (terminal (AVar noneN)))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] mJoinId Nothing Nothing)
    M2bValueAbort -> do
      -- VALUE-POSITION ABORT: never calls k; delivers 'None' to j directly.
      -- 'answerRebindRC' is a no-op for abort (no resume fires).
      noneN <- freshN2b (T.pack "none")
      let armBody = Let (Binder noneN Unrestricted m2bOptTy) (RCon (T.pack "None") [])
                      (terminal (AVar noneN))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] mJoinId Nothing Nothing)

-- | Build @Handle progBody handler@ for the chosen kind/shape. The handler is the
-- AMBIENT (no hSelf), tail-position skeleton; @progBody@ is the op-performing
-- computation varied across the owned-set dimensions. For M2bTwoArgResume the
-- initial param cell is allocated in a Let OUTSIDE the Handle; the hParam binder IS
-- that outer Let binder (same Unique) so the runtime finds the value in scope.
-- For M2bValueResume / M2bValueAbort see 'genM2bValueBody'.
genM2bBody :: M2bHandlerKind -> M2bShape -> Int -> Bool -> Int -> GenM2b Expr
genM2bBody kind shape nOps underCase fuel = do
  (prog, progTy) <- genM2bProg shape nOps underCase fuel
  case kind of
    M2bTwoArgResume -> do
      -- Allocate the initial param cell BEFORE the Handle.
      -- initB is BOTH the outer Let binder AND the handler's hParam binder (same Unique).
      initN <- freshN2b (T.pack "sp")
      let initB = Binder initN Unrestricted m2bBoxTy
      hdlr <- genM2bHandler kind progTy (Just initB) Nothing
      pure (Let initB (RCon (T.pack "Box") [ALit (LInt 1)])
             (Handle prog hdlr))
    M2bValueResume -> genM2bValueBody M2bValueResume prog progTy
    M2bValueAbort  -> genM2bValueBody M2bValueAbort  prog progTy
    _ -> do
      hdlr <- genM2bHandler kind progTy Nothing Nothing
      pure (Handle prog hdlr)

-- | Build the VALUE-POSITION handler expression:
--
-- > LetJoin j [rb : Option progTy]
-- >   (case rb of
-- >     None    -> Ret 0
-- >     Some _  -> Ret 1)        -- distinct output per constructor
-- >   (Handle prog (handler with hAnswerJoin = Just j))
--
-- The outer 'Case' is the NON-CONSTANT consumer of the join result (the M2b-1
-- lesson: the join body must not be 'Ret rb' because that is a tail-position
-- identity and the rebind would be unobservable).  The two arms return DIFFERENT
-- constants (0 vs 1), so where the resumed sub-run's answer routes is observable.
--
-- 'answerRebindRC' is exercised on the RESUME path: when the op arm calls @k 1@,
-- the handler's answer-join @j@ is re-pointed to deliver the sub-run's final answer
-- BACK to the op arm's 'Let' bind site (not to the outer 'Case').  The abort path
-- delivers 'None' via 'Jump j [none]' directly; answerRebindRC is a no-op there.
genM2bValueBody :: M2bHandlerKind -> Expr -> Ty.CType -> GenM2b Expr
genM2bValueBody kind prog progTy = do
  j     <- freshJoinId2b
  rbN   <- freshN2b (T.pack "rb")
  someN <- freshN2b (T.pack "sv_ign")
  hdlr  <- genM2bHandler kind progTy Nothing (Just j)
  -- Join body: case rb of { None -> 0 ; Some _ -> 1 }
  --
  -- 'None' arm FIRST: Perceus inserts __rc_drop(rb) in each arm. 'OmitOneDrop'
  -- traverses the join body left-to-right, so the None arm's drop is targeted
  -- first. Both the M2bValueResume arm (which always jumps j[None]) and the
  -- M2bValueAbort arm (which also jumps j[None]) deliver 'None' to j, so the
  -- None arm always executes. The first drop is therefore always on the executed
  -- path, making the mutation detectable via heap imbalance ('mutationCaughtM2b').
  --
  -- Non-constant ('None -> 0' vs 'Some _ -> 1'): this is the RED-CHECK key.
  -- Without 'answerRebindRC', the M2bValueResume arm's sub-run fires
  -- 'Jump j [Some v]' into the ORIGINAL j, taking the 'Some _ -> 1' arm (output
  -- "1"). With correct rebind the arm intercepts the result, drops it, and fires
  -- 'Jump j [None]' into the original j, taking 'None -> 0' (output "0").
  -- The two outputs differ, making the RED-CHECK go red on a value-position
  -- resume program.
  let joinBody =
        Case (AVar rbN)
          [ AltCon (T.pack "None") [] (Ret (ALit (LInt 0)))
          , AltCon (T.pack "Some") [Binder someN Unrestricted progTy]
              (Ret (ALit (LInt 1))) ]
  pure (LetJoin j [Binder rbN Unrestricted m2bOptTy] joinBody
         (Handle prog hdlr))

-- | Generate the NESTED-PARAM-ABORT shape (spec §7 dedup gap):
--
-- > let sp = Box(v_init) in
-- >   Handle (                               -- outer: M2bAbort for OuterEff.outerOp
-- >     Handle (                             -- inner: param handler (hParam=sp), "Eff"."op"
-- >       let np1 = Box(v_new) in            -- allocate new param value to pass to op
-- >       let xr  = op(np1)   in             -- inner op: arm resumes with np1 as new hParam
-- >       let ur  = outerOp(n) in            -- outer op: aborts, discards captured prefix
-- >       0
-- >     ) innerHdlr                          -- hParam = initB, op-arg = Box -> arm resumes
-- >   ) outerHdlr
--
-- The dedup shape arises because the inner-op arm does:
--   op(newParam, k) -> let rr = k(newParam, ()) in let __rc_drop(sp) in rr
-- (sp, the OLD hParam, is dead AFTER the resume call, not before). When the two-arg
-- resume fires and then the outer abort fires, the captured prefix holds BOTH:
--   * KHandleRC(innerHdlr, env holds newParam at addr A = sp.Unique -> addr A)
--   * KLetRC(xr, env2 holds sp=old param at addr B = sp.Unique -> addr B)
-- Both have the SAME Unique (sp) but DIFFERENT addresses; 'continuationOwned' must
-- free both. Keying on Unique alone collapses them -> one address leaks.
--
-- The inner op-arg type is 'm2bBoxTy' (the computation passes a freshly-allocated Box
-- as the new param). @nSets@ inner ops fire before the outer abort; each set leaves an
-- old-param entry in the set-arm's KLetRC env2.
genM2bNestedParamAbort :: Int -> GenM2b Expr
genM2bNestedParamAbort nSets = do
  -- Initial inner param: sp = Box(v_init)
  vInit <- liftG2b (choose (1, 9 :: Integer))
  spN   <- freshN2b (T.pack "sp")
  let initB = Binder spN Unrestricted m2bBoxTy
  -- Inner handler: handles "Eff"."op" with a BOXED op-arg as the new param value.
  -- Op arm: op(newP : Box, k) -> let rr = k(newP, ()) in rr
  -- sp (hParam) is dead AFTER the resume call -> Perceus inserts __rc_drop(sp) there.
  innerHdlr <- genM2bSetStyleHandler initB
  -- Inner computation body: allocate new param(s) and fire op(s), then outer abort.
  innerBody <- buildInnerBody nSets
  -- Outer handler: abort on "OuterEff"."outerOp"
  outerHdlr <- genM2bOuterAbortHandler m2bOptTy
  -- Assemble:
  -- let sp = Box(v_init) in
  --   Handle (Handle innerBody innerHdlr) outerHdlr
  pure (Let initB (RCon (T.pack "Box") [ALit (LInt vInit)])
         (Handle
           (Handle innerBody innerHdlr)
           outerHdlr))
  where
    -- Build the inner computation: nSets x (let np = Box(v); let xr = op(np)) then outerOp.
    -- The result type of the op at the call site is Unit (the arm passes ALit LUnit back).
    -- We bind xr : m2bU64 to keep the type annotation compatible (unit is unboxed, close
    -- enough for the runtime; the interpreter is untyped).
    buildInnerBody 0 = do
      outerArgN <- liftG2b (choose (0, 9 :: Integer))
      urN <- freshN2b (T.pack "ur")
      pure (Let (Binder urN Unrestricted m2bU64)
                (ROp Nothing m2bOuterLbl m2bOuterOp [ALit (LInt outerArgN)])
              (Ret (ALit (LInt 0))))
    buildInnerBody k = do
      vNew  <- liftG2b (choose (1, 9 :: Integer))
      npN   <- freshN2b (T.pack "np")
      xrN   <- freshN2b (T.pack "xr")
      rest  <- buildInnerBody (k - 1)
      -- let np = Box(v_new) in let xr = op(np) in <rest>
      -- np is passed as the boxed new-param arg to the inner op
      pure (Let (Binder npN Unrestricted m2bBoxTy)
                (RCon (T.pack "Box") [ALit (LInt vNew)])
              (Let (Binder xrN Unrestricted m2bU64)
                   (ROp Nothing m2bLbl m2bOp [AVar npN])
                rest))

-- | Build the inner parameterized handler for the nested-param-abort shape.
-- Op-arg type is 'm2bBoxTy' (the new param value); the arm does:
--   op(newP : Box, k) -> let rr = k(newP, ()) in rr
-- With sp (hParam) dead ONLY AFTER the @k(newP, ())@ resume call, Perceus places
-- __rc_drop(sp) AFTER the resume. This leaves the old sp in KLetRC env2 when the
-- two-arg resume fires, creating the (Unique, Addr) dedup scenario on outer abort.
genM2bSetStyleHandler :: Binder -> GenM2b Handler
genM2bSetStyleHandler initB = do
  -- Return arm: wraps computation result in Some
  vN  <- freshN2b (T.pack "v")
  svN <- freshN2b (T.pack "sv")
  let retArm =
        ( Binder vN Unrestricted m2bU64
        , Let (Binder svN Unrestricted m2bOptTy) (RCon (T.pack "Some") [AVar vN])
            (Ret (AVar svN)) )
  -- Op arm: op(newP : m2bBoxTy, k) -> let rr = k(newP, ()) in rr
  newPN <- freshN2b (T.pack "newP")
  kN    <- freshN2b (T.pack "k")
  rN    <- freshN2b (T.pack "rr")
  let armBody = Let (Binder rN Unrestricted m2bU64)
                    (RApp (AVar kN) [AVar newPN, ALit LUnit])
                  (Ret (AVar rN))
      arm = OpArm m2bLbl m2bOp [Binder newPN Unrestricted m2bBoxTy]
              (Binder kN Unrestricted m2bOptTy) armBody
  pure (Handler retArm [arm] Nothing (Just initB) Nothing)

-- | An aborting handler for 'OuterEff'.'outerOp': op arm returns 'None' without
-- applying the resume binder. The return arm wraps the computation result in 'Some'.
-- Used by 'genM2bNestedParamAbort' for the outer aborting handler.
genM2bOuterAbortHandler :: Ty.CType -> GenM2b Handler
genM2bOuterAbortHandler progTy = do
  vN    <- freshN2b (T.pack "ov")
  nN    <- freshN2b (T.pack "opn2")
  kN    <- freshN2b (T.pack "k2")
  svN   <- freshN2b (T.pack "osv")
  noneN <- freshN2b (T.pack "none2")
  let retArm =
        ( Binder vN Unrestricted progTy
        , Let (Binder svN Unrestricted m2bOptTy) (RCon (T.pack "Some") [AVar vN])
            (Ret (AVar svN)) )
      armBody = Let (Binder noneN Unrestricted m2bOptTy) (RCon (T.pack "None") [])
                  (Ret (AVar noneN))
      arm = OpArm m2bOuterLbl m2bOuterOp [Binder nN Unrestricted m2bU64]
              (Binder kN Unrestricted m2bOptTy) armBody
  pure (Handler retArm [arm] Nothing Nothing Nothing)

-- | The op-performing computation and its result type. Varied across the owned-set
-- dimensions. @nOps@ ops are performed; @underCase@ fires the (first) op inside a
-- Case arm so the captured prefix is a non-trivial multi-frame above.
genM2bProg :: M2bShape -> Int -> Bool -> Int -> GenM2b (Expr, Ty.CType)
genM2bProg shape nOps underCase _fuel = case shape of
  M2bMovedBeforeOp -> do
    -- x = Box 1 ; ys = Box2(x)   [x MOVED into ys, x now stale]
    -- <ops, possibly under a Case on ys> ; return ys
    xN  <- freshN2b (T.pack "x")
    ysN <- freshN2b (T.pack "ys")
    let seed cont =
          Let (Binder xN Unrestricted m2bBoxTy) (RCon (T.pack "Box") [ALit (LInt 1)])
            (Let (Binder ysN Unrestricted m2bBoxTy) (RCon (T.pack "Box2") [AVar xN]) cont)
    inner <- m2bReturnBoxed ysN m2bBoxTy
    e <- m2bWithOps nOps underCase (AVar ysN) [(ysN, m2bBoxTy)] inner
    pure (seed e, m2bBoxTy)
  M2bCapturedBoxed -> do
    -- xs = Cons(5, Nil)   [boxed, live ACROSS the op] ; <ops> ; return head-ish via case
    nilN <- freshN2b (T.pack "nil")
    xsN  <- freshN2b (T.pack "xs")
    let seed cont =
          Let (Binder nilN Unrestricted m2bListTy) (RCon (T.pack "Nil") [])
            (Let (Binder xsN Unrestricted m2bListTy)
                 (RCon (T.pack "Cons") [ALit (LInt 5), AVar nilN]) cont)
    -- consume xs by a Case after the op: Cons h t -> h ; Nil -> 0  (boxed live across)
    hN <- freshN2b (T.pack "h")
    tN <- freshN2b (T.pack "t")
    let consume =
          Case (AVar xsN)
            [ AltCon (T.pack "Cons") [Binder hN Unrestricted m2bU64, Binder tN Unrestricted m2bListTy]
                (Ret (AVar hN))
            , AltCon (T.pack "Nil") [] (Ret (ALit (LInt 0))) ]
    e <- m2bWithOps nOps underCase (AVar xsN) [(xsN, m2bListTy)] consume
    pure (seed e, m2bU64)
  M2bAliasedBoxed -> do
    -- x = Box 1 ; a = x   [alias; the pass dup's it] ; <ops> ; return Pair(a, x)
    xN  <- freshN2b (T.pack "x")
    aN  <- freshN2b (T.pack "a")
    prN <- freshN2b (T.pack "pr")
    let seed cont =
          Let (Binder xN Unrestricted m2bBoxTy) (RCon (T.pack "Box") [ALit (LInt 1)])
            (Let (Binder aN Unrestricted m2bBoxTy) (RAtom (AVar xN)) cont)
        consume =
          Let (Binder prN Unrestricted m2bPairTy) (RCon (T.pack "Pair") [AVar aN, AVar xN])
            (Ret (AVar prN))
    e <- m2bWithOps nOps underCase (AVar xN) [(xN, m2bBoxTy)] consume
    pure (seed e, m2bPairTy)
  M2bGlobalAcrossOp -> do
    -- reference a top-level boxed CAF g_caf ACROSS the op, then return its head.
    cN <- useCaf
    hN <- freshN2b (T.pack "gh")
    tN <- freshN2b (T.pack "gt")
    let consume =
          Case (AVar cN)
            [ AltCon (T.pack "Cons") [Binder hN Unrestricted m2bU64, Binder tN Unrestricted m2bListTy]
                (Ret (AVar hN))
            , AltCon (T.pack "Nil") [] (Ret (ALit (LInt 0))) ]
    e <- m2bWithOps nOps underCase (AVar cN) [(cN, m2bListTy)] consume
    pure (e, m2bU64)

-- | A trivial boxed-result body: just return the named boxed binder.
m2bReturnBoxed :: Name -> Ty.CType -> GenM2b Expr
m2bReturnBoxed n _ = pure (Ret (AVar n))

-- | Wrap @inner@ with @nOps@ effect operations. The op result is bound to a fresh
-- (dead) U64 binder. When @underCase@, the FIRST op fires inside a Case arm on
-- @scrut@ (a non-trivial multi-frame 'above'); otherwise the ops sit in a plain Let
-- chain. @scrutEnv@ lists the live binders the Case arm may keep (used only to keep
-- the scrutinee live across the inner op so the captured prefix is realistic).
m2bWithOps :: Int -> Bool -> Atom -> [(Name, Ty.CType)] -> Expr -> GenM2b Expr
m2bWithOps nOps underCase scrut _scrutEnv inner = do
  -- Build the op-Let chain that ends in @inner@.
  let opLet cont = do
        uN <- freshN2b (T.pack "u")
        litN <- liftG2b (choose (0, 9 :: Integer))
        pure (Let (Binder uN Unrestricted m2bU64) (ROp Nothing m2bLbl m2bOp [ALit (LInt litN)]) cont)
  chain <- foldOps (max 1 nOps) opLet inner
  if underCase
    then do
      -- Fire the chain inside a Case default arm on @scrut@ so the captured 'above'
      -- prefix spans a Case continuation (a non-trivial multi-frame above). The
      -- scrutinee atom is matched by a default arm (keeps it live; no child binders).
      pure (Case scrut [AltDefault chain])
    else pure chain
  where
    foldOps 0 _ acc = pure acc
    foldOps k mk acc = do acc' <- mk acc; foldOps (k - 1) mk acc'

-- | The accepted=>sound property for the M2b-1 handler fragment. Mirrors
-- 'prop_m2a1Escape': prune, check the boundary guard; if not accepted, the property
-- is vacuously true (rejection is the conservative, always-sound verdict); else run
-- BOTH interpreters and require output equality AND heap balance (stLive == baseline
-- AND allocs - frees == baseline), with the both-fail branch hardened EXACTLY as
-- m2a-1 (reject an RC mem-safety fault hidden behind a reference failure; require the
-- same 'errCtorTag'). The 'checkCoverage' floors below make NON-VACUITY a HARD
-- FAILURE: if a generator regression stops producing any owned-set dimension above
-- its floor, the property goes red.
prop_m2bEscape :: Property
prop_m2bEscape =
  forAllShrink genM2bProgram shrinkProgramM2b $ \cm0 -> QC.ioProperty $ do
    let cm       = pruneToReachable cm0
        accepted = null (firstOrderNoHandlerViolations cm)
        refRes   = Interp.runModule cm
    rcRes <- RCM.runModuleRCUnchecked (Perceus.insertRC cm)
    let report   =
          "boundary accepted: " <> show accepted
            <> "\ninstrumented ANF:\n" <> T.unpack (Perceus.prettyPerceus cm)
            <> "\nreference: " <> showR (fmap Interp.renderValue refRes)
            <> "\nrc:        " <> showRC rcRes
        -- Structural detectors for the owned-set dimensions (used for the coverage
        -- floors). They classify the GENERATED, accepted-and-run program.
        ranSound        = accepted && either (const False) (const True) rcRes
        isAbort         = m2bHasAbortArm cm
        isResume        = m2bHasResumeArm cm
        movedB          = m2bHasMovedBeforeOp cm
        boxedAcr        = m2bHasBoxedAcrossOp cm
        opAbove         = m2bHasOpUnderCase cm
        isParam         = m2bHasParamHandler cm
        nestedParamAbrt = m2bHasNestedParamAbort cm
        valuePos        = m2bHasValuePosHandler cm
        valuePosAbrt    = m2bHasValuePosAbort cm
        -- Split floors: distinguish TAIL-POSITION (M2b-1) from VALUE-POSITION (M2b-2)
        -- paths so a regression in the M2b-1 tail path cannot hide behind the combined
        -- floor being satisfied by value-position cases alone.
        tailResume      = isResume && not valuePos
        tailAbort       = isAbort && not valuePosAbrt
        valuePosResume  = isResume && valuePos
    pure $ checkCoverage $
       cover 25.0 (isAbort && ranSound)  "abort path (any kind): accepted+run" $
       cover 25.0 (isResume && ranSound) "resume path (any kind): accepted+run" $
       -- Split floors: tail-position (M2b-1) independently pinned from value-position (M2b-2).
       cover 20.0 (tailAbort && ranSound)       "tail-position abort: accepted+run" $
       cover 20.0 (tailResume && ranSound)      "tail-position resume: accepted+run" $
       cover 10.0 (valuePosResume && ranSound)  "value-position resume: accepted+run" $
       cover 10.0 (valuePosAbrt && ranSound)    "value-position abort: accepted+run" $
       cover 12.0 (boxedAcr && ranSound) "boxed-value live across op: accepted+run" $
       cover 12.0 (movedB && ranSound)   "moved-before-op (stale binder): accepted+run" $
       cover 12.0 (opAbove && ranSound)  "op under non-trivial above (Case): accepted+run" $
       cover 12.0 (isParam && ranSound)  "parameterized handler (two-arg resume baton): accepted+run" $
       cover  4.0 (nestedParamAbrt && ranSound) "nested param handler abort (dedup shape): accepted+run" $
       QC.label (show (m2bClassify cm) <> (if accepted then " accepted" else " rejected")) $
       counterexample report $
         if not accepted
           then property True
           else case (refRes, rcRes) of
                  (Right v, Right run) ->
                    let outOk      = Interp.renderValue v == RCM.rcOutput run
                        st         = RCM.rcStats run
                        baseline   = RCM.rcBaseline run
                        liveOk     = St.stLive st == baseline
                        balancedOk = St.stAllocs st - St.stFrees st == baseline
                    in counterexample "ACCEPTED but unsound: output / heap-empty / balanced mismatch"
                         (outOk && liveOk && balancedOk)
                  (Left refE, Left rcE)
                    | rcMemSafetyFault rcE ->
                        counterexample ("ACCEPTED but unsound: RC memory-safety fault hidden behind a \
                                        \reference failure: rc=" <> show rcE <> " ref=" <> show refE)
                          False
                    | errCtorTag refE == errCtorTag rcE ->
                        counterexample "both interpreters failed the same way (agreement)" True
                    | otherwise ->
                        counterexample ("ACCEPTED but unsound: RC failure DIVERGES from the reference \
                                        \failure: ref=" <> show refE <> " rc=" <> show rcE)
                          False
                  _ ->
                    counterexample "ACCEPTED but unsound: exactly one interpreter failed" False
  where
    showR (Right t)  = T.unpack t
    showR (Left e)   = "FAILED (" <> show e <> ")"
    showRC (Right run) = T.unpack (RCM.rcOutput run)
    showRC (Left e)    = "FAILED (" <> show e <> ")"

-- | balanceLint must be clean on every IN-FRAGMENT generated M2b-1 program (one the
-- boundary guard ACCEPTS). Mirrors 'prop_m2a1LintClean'. A boundary-rejected program
-- may legitimately lint dirty (the conservative reject), so we gate on acceptance.
prop_m2bLintClean :: Property
prop_m2bLintClean =
  forAllShrink genM2bProgram shrinkProgramM2b $ \cm0 ->
    let cm   = pruneToReachable cm0
        viol = Perceus.balanceLint cm
    in if not (null (firstOrderNoHandlerViolations cm))
         then property True
         else counterexample ("balanceLint reported on an IN-FRAGMENT program: " <> show viol
                                <> "\nANF:\n" <> T.unpack (Perceus.prettyPerceus cm))
                (null viol)

-- | Every single-site RC mutation must be CAUGHT on every generated M2b-1 program ---
-- statically ('lintInstrumented'), at runtime (a 'Left'), OR via heap imbalance
-- ('stLive /= baseline' or 'stAllocs - stFrees /= baseline'). The heap-imbalance
-- check is necessary for value-position abort arms: omitting @__rc_drop(k)@ there
-- causes a LEAK (the NCont of the resume is never freed) rather than a crash,
-- because the 'Jump j [result]' in the arm body crosses the handler boundary to an
-- outer join that the arm's 'lintInstrumented' does not audit inline.
--
-- A mutation that is a structural no-op (the site did not exist) counts as fine.
prop_m2bTeeth :: Property
prop_m2bTeeth =
  forAllShrink genM2bProgram shrinkProgramM2b $ \cm0 -> QC.ioProperty $ do
    let cm = pruneToReachable cm0
    props <- mapM
      (\mut -> do
         caught <- mutationCaughtM2b mut cm
         pure (counterexample ("mutation " <> show mut <> " was NOT caught\nANF:\n"
                                 <> T.unpack (Perceus.prettyPerceus cm))
                 caught))
      [Perceus.OmitOneDrop, Perceus.OmitOneDup, Perceus.DuplicateOneDrop]
    pure (conjoin props)

-- | Extended mutation-caught check for the M2b generator: extends the shared
-- 'mutationCaught' with a heap-imbalance detector. Value-position handler arms
-- cross a handler boundary when they 'Jump' to the outer answer join, so
-- 'lintInstrumented' does not audit them inline (it treats the outer join as
-- unknown). A omitted drop in such an arm causes a leak ('stLive > baseline'),
-- which is detected here by running the mutated program and checking the stats.
--
-- NOTE (Slice 2): a mutation that targets an INLINE (uncounted) address is
-- semantically harmless -- drops of Inline immediates are always no-ops. If the
-- mutated run's heap stats match the correct run's stats exactly, the mutation
-- only hit uncounted values and is not a soundness violation.
mutationCaughtM2b :: Perceus.Mutation -> CoreModule -> IO Bool
mutationCaughtM2b mut cm = do
  let correct = Perceus.insertRC cm
      mutated = Perceus.insertRCMutated mut cm
  if mutated == correct                                    -- mutation was a no-op
       || not (null (Perceus.lintInstrumented mutated))    -- caught statically
    then pure True
    else RCM.runModuleRCUnchecked mutated >>= \case
           Left _    -> pure True                          -- caught as runtime crash
           Right mrun ->
             let mst       = RCM.rcStats mrun
                 mbaseline = RCM.rcBaseline mrun
             in if St.stLive mst /= mbaseline             -- detected as a heap leak
                     || St.stAllocs mst - St.stFrees mst /= mbaseline
                  then pure True
                  else -- Heap balanced: check if the correct run has identical
                       -- stats (then the drop was on an uncounted Inline value).
                       RCM.runModuleRCUnchecked correct >>= \case
                         Left _     -> pure False
                         Right crun ->
                           let cs = RCM.rcStats crun
                           in pure (St.stAllocs mst == St.stAllocs cs
                                 && St.stFrees  mst == St.stFrees  cs
                                 && St.stPeak   mst == St.stPeak   cs
                                 && St.stLive   mst == St.stLive   cs
                                 && mbaseline == RCM.rcBaseline crun)

-- | Shrinker for a generated M2b program. The program is a handler bind (plus an
-- optional CAF bind), so the generic single-main 'shrinkProgram' does not apply; we
-- shrink only the @main@ bind's body to a structurally-contained, well-scoped
-- sub-expression (reusing 'shrinkExpr'), keeping any CAF bind intact. A program whose
-- main body shrinks below the 'Handle' simply drops out of the fragment (no handler),
-- which the boundary guard still accepts, so a shrunk counterexample stays valid.
shrinkProgramM2b :: CoreModule -> [CoreModule]
shrinkProgramM2b (CoreModule binds) =
  case reverse binds of
    (TopBind n ps body : revRest) ->
      let rest = reverse revRest
      in [ CoreModule (rest ++ [TopBind n ps body']) | body' <- shrinkExpr body ]
    [] -> []

-- ---------------------------------------------------------------------------
-- Structural detectors for the Suite-G (M2b-1) coverage floors. They classify the
-- GENERATED program by inspecting its single 'Handle' node and its op-performing
-- body --- NOT by re-running the pass. Used only for 'cover' / 'label' non-vacuity.

-- | The unique 'Handler' of a generated program (its single 'Handle' node), if any.
m2bTheHandler :: CoreModule -> Maybe Handler
m2bTheHandler (CoreModule binds) =
  case [ h | TopBind _ _ body <- binds, h <- handlersIn body ] of
    (h : _) -> Just h
    []      -> Nothing
  where
    handlersIn e = case e of
      Handle inner h    -> h : handlersIn inner
      Let _ _ b         -> handlersIn b
      Case _ alts       -> concatMap (handlersIn . clusterAltBody) alts
      LetJoin _ _ jb b  -> handlersIn jb ++ handlersIn b
      LetRec ds b       -> concatMap (\(_, _, d) -> handlersIn d) ds ++ handlersIn b
      _                 -> []

-- | The op-performing computation (the inner expression of the single 'Handle').
m2bTheProg :: CoreModule -> Maybe Expr
m2bTheProg (CoreModule binds) =
  case [ inner | TopBind _ _ body <- binds, inner <- innersIn body ] of
    (e : _) -> Just e
    []      -> Nothing
  where
    innersIn e = case e of
      Handle inner _    -> inner : innersIn inner
      Let _ _ b         -> innersIn b
      Case _ alts       -> concatMap (innersIn . clusterAltBody) alts
      LetJoin _ _ jb b  -> innersIn jb ++ innersIn b
      LetRec ds b       -> concatMap (\(_, _, d) -> innersIn d) ds ++ innersIn b
      _                 -> []

-- | The single op arm's body applies its resume binder as a call head (tail-resume).
m2bHasResumeArm :: CoreModule -> Bool
m2bHasResumeArm cm = case m2bTheHandler cm of
  Just h  -> any (\oa -> resumeApplied (oaResume oa) (oaBody oa)) (hOps h)
  Nothing -> False
  where
    resumeApplied k = go
      where
        ku = binderUnique k
        go e = case e of
          Let _ (RApp (AVar f) _) b -> Name.nameUniq f == ku || go b
          Let _ _ b                 -> go b
          Case _ alts               -> any (go . clusterAltBody) alts
          LetJoin _ _ jb b          -> go jb || go b
          _                         -> False

-- | The single op arm never applies its resume binder (abort / no-resume).
m2bHasAbortArm :: CoreModule -> Bool
m2bHasAbortArm cm = case m2bTheHandler cm of
  Just h  -> not (null (hOps h)) && not (m2bHasResumeArm cm)
  Nothing -> False

-- | The computation MOVES a boxed binder into a constructor field, then performs the
-- op while that move-source binder is dead (the §4.2 stale-binder shape). Detected
-- structurally: a @let ys = Con(.. x ..)@ whose field @x@ was a prior boxed @let@,
-- followed (later in the body) by an op.
m2bHasMovedBeforeOp :: CoreModule -> Bool
m2bHasMovedBeforeOp cm = case m2bTheProg cm of
  Just e  -> go Set.empty e
  Nothing -> False
  where
    -- @boxed@ = boxed binders bound so far whose RHS allocated a fresh cell.
    go boxed e = case e of
      Let b (RCon _ as) body ->
        (movesBoxed boxed as && hasOpAfter body)
          || go (Set.insert (binderUnique b) boxed) body
      Let b _ body -> go (insertIfBoxed b boxed) body
      Case _ alts  -> any (go boxed . clusterAltBody) alts
      LetJoin _ _ jb body -> go boxed jb || go boxed body
      _ -> False
    insertIfBoxed b s = if Esc.isBoxedType (bndType b) then Set.insert (binderUnique b) s else s
    movesBoxed boxed = any (\a -> case a of AVar n -> Set.member (nameUniq n) boxed; _ -> False)
    hasOpAfter e = case e of
      Let _ (ROp{}) _ -> True
      Let _ _ b       -> hasOpAfter b
      Case _ alts     -> any (hasOpAfter . clusterAltBody) alts
      LetJoin _ _ jb b -> hasOpAfter jb || hasOpAfter b
      _               -> False

-- | A boxed binder is bound BEFORE the op and USED AFTER it (live across the op).
m2bHasBoxedAcrossOp :: CoreModule -> Bool
m2bHasBoxedAcrossOp cm = case m2bTheProg cm of
  Just e  -> go Set.empty e
  Nothing -> False
  where
    go boxed e = case e of
      Let _ (ROp{}) body ->
        -- at the op site, any boxed binder in scope that is FREE in the continuation
        -- body is live across the op.
        not (Set.null (Set.intersection boxed (freeVarsExpr body)))
          || go boxed body
      Let b _ body -> go (insertIfBoxed b boxed) body
      Case _ alts  -> any (go boxed . clusterAltBody) alts
      LetJoin _ _ jb body -> go boxed jb || go boxed body
      _ -> False
    insertIfBoxed b s = if Esc.isBoxedType (bndType b) then Set.insert (binderUnique b) s else s

-- | The op fires inside a 'Case' arm (a non-trivial multi-frame 'above').
m2bHasOpUnderCase :: CoreModule -> Bool
m2bHasOpUnderCase cm = case m2bTheProg cm of
  Just e  -> go False e
  Nothing -> False
  where
    go inCase e = case e of
      Let _ (ROp{}) body -> inCase || go inCase body
      Let _ _ body       -> go inCase body
      Case _ alts        -> any (go True . clusterAltBody) alts
      LetJoin _ _ jb body -> go inCase jb || go inCase body
      _ -> False

-- | The handler has a boxed parameter (hParam = Just _): a parameterized handler
-- exercising the two-arg resume baton model (M2b-2 Task 4D).
m2bHasParamHandler :: CoreModule -> Bool
m2bHasParamHandler cm = case m2bTheHandler cm of
  Just h  -> Data.Maybe.isJust (hParam h)
  Nothing -> False

-- | The program has the NESTED-PARAM-ABORT shape: a top-level 'Handle' node
-- (outer aborting handler) whose inner expression is ALSO a 'Handle' node (inner
-- parameterized handler with hParam).  This is the (Unique, Addr) dedup shape
-- generated by 'genM2bNestedParamAbort'.
m2bHasNestedParamAbort :: CoreModule -> Bool
m2bHasNestedParamAbort (CoreModule binds) =
  any (hasNested . tbBody) binds
  where
    hasNested e = case e of
      -- Outer Handle (no hParam): inner expr is also a Handle with hParam
      Handle (Handle _ innerH) outerH ->
        Data.Maybe.isJust (hParam innerH)
          && Data.Maybe.isNothing (hParam outerH)
          && not (null (hOps outerH))
          && not (m2bHasResumeArmH outerH)
      Let _ _ b -> hasNested b
      _         -> False
    -- True if the handler has an op arm that tail-applies the resume binder.
    m2bHasResumeArmH h = any (\oa -> resumeApplied (oaResume oa) (oaBody oa)) (hOps h)
    resumeApplied k = go
      where
        ku = binderUnique k
        go e = case e of
          Let _ (RApp (AVar f) _) b -> Name.nameUniq f == ku || go b
          Let _ _ b                 -> go b
          Case _ alts               -> any (go . clusterAltBody) alts
          LetJoin _ _ jb b          -> go jb || go b
          _                         -> False

-- | The handler is in VALUE POSITION: 'hAnswerJoin = Just _'. The whole 'Handle'
-- sits inside a 'LetJoin'; arms deliver via 'Jump'; 'answerRebindRC' fires on
-- every resume to re-point the join to the resume call site.
m2bHasValuePosHandler :: CoreModule -> Bool
m2bHasValuePosHandler cm = case m2bTheHandler cm of
  Just h  -> Data.Maybe.isJust (hAnswerJoin h)
  Nothing -> False

-- | The handler is in value position AND is an abort handler (op arm never applies
-- resume). In this case 'answerRebindRC' is a no-op (no resume fires), and the op
-- arm delivers 'None' via 'Jump j [none]' directly to the outer case.
m2bHasValuePosAbort :: CoreModule -> Bool
m2bHasValuePosAbort cm = m2bHasValuePosHandler cm && m2bHasAbortArm cm

-- | A coarse label of the generated program's shape, for the distribution readout.
m2bClassify :: CoreModule -> String
m2bClassify cm =
  (if m2bHasAbortArm cm then "abort" else if m2bHasResumeArm cm then "resume" else "no-op")
    <> (if m2bHasMovedBeforeOp cm then "/moved" else "")
    <> (if m2bHasBoxedAcrossOp cm then "/across" else "")
    <> (if m2bHasOpUnderCase cm then "/under-case" else "")
    <> (if m2bHasParamHandler cm then "/param" else "")
    <> (if m2bHasNestedParamAbort cm then "/nested-param-abort" else "")
    <> (if m2bHasValuePosHandler cm then "/value-pos" else "")
    <> (if m2bHasValuePosAbort cm then "/value-pos-abort" else "")

-- | Suite G (M2b-1): the generative oracle for the handler fragment. The accepted=>
-- sound property, the lint-clean property, and the generalized teeth, with coverage
-- floors that fail the property if any owned-set dimension stops being generated.
rcM2bPropertyTests :: TestTree
rcM2bPropertyTests =
  localOption (QuickCheckTests 800) $
    testGroup "rc m2b-1 property (Suite G: handler fragment owned-set)"
      [ testProperty "accepted => sound (heap-balanced + value-match); rejected => skipped"
          prop_m2bEscape
      , testProperty "balanceLint is clean on every in-fragment generated program"
          prop_m2bLintClean
      , testProperty "every single-site RC mutation is caught (generalized teeth)"
          prop_m2bTeeth
      ]

-- ---------------------------------------------------------------------------
-- Suite G (extended): the M3 STORED-CONTINUATION generative oracle (Task 7).
--
-- The BROAD soundness oracle for M3: an adversarial generative property over the
-- EXPRESSIBLE + ADMITTED store-route fragment, catching the silent double-free /
-- leak class hand-picked cases miss (the lesson this project learned twice).
--
-- The two routes (spec §3.1 / §3.2), exactly the fragment Tasks 1-5 support:
--   * STORE -> TAKE -> RESUME within one op-arm (the corpus '01-store-resume'
--     shape): the arm parks 'resume' in a FRESH-LOCAL cell ('__cont_cell_new'
--     INSIDE the arm), immediately takes it back out, and resumes the taken
--     continuation ONCE --- within the handler's dynamic extent (resume-site
--     semantics). Heap-balanced; output matches the direct tail-resume.
--   * STORE -> DROP (park-and-abandon; the corpus '03-store-drop-finally' shape):
--     the arm parks 'resume' in a fresh-local cell and NEVER takes it; it returns
--     the answer directly. The filled cell goes out of scope, Perceus drops it,
--     and the cell-drop CASCADES to the held NCont, freeing its owned set exactly
--     once (the §4.4 drop/finally seam = "free the owned set once"). This is the
--     M3 CELL-drop path, NOT the pre-existing M2b raw-abort leak (§10 item 6): the
--     'resume' is MOVED into the cell (a counted edge the drop cascade follows),
--     so the owned set is reachable and freed --- the store route is the CORRECT
--     drop path.
--
-- SCOPING (or the property ships green-broken or spuriously red --- spec §3.1 note,
-- §10 items 6+7):
--   * ONLY fresh-local cells. The cross-arm baton shape (the cell in 'hParam') hits
--     an OccursCheck at elaboration (§3.1), so it would never elaborate; it is NOT
--     generated.
--   * NEVER the raw resumable-op abort that discards 'resume' directly (the
--     pre-existing M2b leak, §10 item 6): that leaks independently of M3 and would
--     make the property RED on a bug that is NOT M3's. M3's drop path is the
--     CELL-drop (store then drop the filled cell), which frees correctly.
-- The accept predicate is the REAL guard
-- ('null (firstOrderNoHandlerViolations cm)'), which already wires in the M3
-- carrier-wall check + the store-route-relaxed boundary; the property quantifies
-- ONLY over accepted programs (the accepted/skipped split, mirroring
-- 'prop_m2bEscape').

-- | The store route the generated arm takes: resume after the round-trip, or
-- abandon the parked continuation.
data M3Route
  = M3StoreResume   -- ^ store -> take -> resume (within one op-arm)
  | M3StoreDrop     -- ^ store -> drop the filled cell (park-and-abandon)
  deriving (Eq, Show)

-- | Continuation-cell extern atoms. As the elaborator emits for a genuine
-- @Control@ continuation extern, these are 'APrim' heads carrying the
-- qualified @(module, name)@ identity --- the SAME identity the boundary guard
-- ('Wok.IR.Escape.contStoreCell'), the Perceus pass ('contTakeKey'), and both
-- machines' prim tables (by the name part) recognize. (A user binding hinted the
-- same resolves to an 'AVar' and is correctly NOT recognized.)
m3CellNew, m3Store, m3Take :: Atom
m3CellNew = APrim PN.contCellNewKey
m3Store   = APrim PN.contStoreKey
m3Take    = APrim PN.contTakeKey

-- | The whole-program generator for the M3 store route. Builds
-- @main = Handle progBody storeRouteHandler@ (plus an optional boxed CAF bind when
-- the global dimension fires), directly as ANF, mirroring 'genM2bProgram'. The op
-- 'prog' computation is shared verbatim with M2b ('genM2bProg'), so the SAME
-- owned-set dimensions (moved-into-con, two live aliases, op under a non-trivial
-- 'above', a global/CAF live across the store) drive the captured continuation's
-- owned set. The handler arm is the only difference: instead of tail-resuming (M2b)
-- or aborting raw (the pre-existing leak), it routes 'resume' THROUGH a fresh-local
-- continuation cell (store -> take -> resume, or store -> drop).
--
-- Dimensions varied (each pinned by a 'cover' floor in 'prop_m3Escape'):
--   * route: M3StoreResume vs M3StoreDrop (both must appear);
--   * owned-set shape on the store path: moved-into-con / two-alias / op-under-Case
--     / global-CAF / captured-boxed (the M2b shapes, reused);
--   * store-in-one-branch-of-a-Case: the cell-new/store fires inside a Case arm
--     ('underCase'), so the captured 'above' is a non-trivial multi-frame prefix.
genM3Program :: Gen CoreModule
genM3Program = sized $ \sz -> do
  let fuel  = max 1 (min sz 4)
  let mainN = Name (T.pack "main") (Unique 1000000)
  -- Both routes weighted equally so each clears its 'cover' floor within 800 tests.
  route <- elements [M3StoreResume, M3StoreDrop]
  -- The owned-set shape on the store path. The aliased-boxed shape (two live
  -- aliases of one boxed cell) is sound on the DROP path (the pass dup's the alias
  -- and both copies are freed via the cascade); on the RESUME path the round-trip
  -- moves the continuation back and the alias is still freed once. Both are fine,
  -- so every shape is exercised under both routes.
  shape <- elements [minBound .. maxBound :: M2bShape]
  -- How many ops the computation performs (1 or 2): a second op makes the captured
  -- 'above' prefix multi-frame.
  nOps  <- elements [1, 1, 2 :: Int]
  -- Whether the op fires INSIDE a Case arm (a non-trivial multi-frame 'above',
  -- i.e. store-in-one-branch-of-a-Case).
  underCase <- elements [False, True]
  (body, globals, _) <-
    runStateT3 (genM3Body route shape nOps underCase fuel) 1
  let mainB = TopBind mainN [] body
  case m2bgCafName globals of
    Nothing -> pure (CoreModule [mainB])
    Just cN -> pure (CoreModule [m2bCafBind cN, mainB])

-- | Build @Handle progBody storeRouteHandler@ for the chosen route/shape. The
-- handler is AMBIENT (no hSelf), tail-position (no hAnswerJoin), non-parameterized
-- (no hParam --- the fresh-local-cell fragment, §3.1). @progBody@ is the
-- op-performing computation from 'genM2bProg' (shared with M2b).
genM3Body :: M3Route -> M2bShape -> Int -> Bool -> Int -> GenM2b Expr
genM3Body route shape nOps underCase fuel = do
  (prog, progTy) <- genM2bProg shape nOps underCase fuel
  hdlr <- genM3Handler route progTy
  pure (Handle prog hdlr)

-- | The store-route handler skeleton. The op arm routes its 'resume' binder @k@
-- THROUGH a fresh-local continuation cell:
--
--   M3StoreResume:  op n k ->
--     let cell   = __cont_cell_new () in
--     let filled = __cont_store cell k in
--     let k2     = __cont_take filled in
--     let r      = k2 1 in
--     r                                       -- resume once, answer = r : progTy
--
--   M3StoreDrop:    op n k ->
--     let cell   = __cont_cell_new () in
--     let filled = __cont_store cell k in
--     None                                    -- abandon; filled drops -> cascade
--                                             -- frees the owned set once
--
-- The return arm wraps the computation result in 'Some' (answer type 'Option
-- progTy') for the DROP route (so the abandon arm's 'None' is type-compatible) and
-- delivers the resumed result directly for the RESUME route (answer type 'progTy',
-- mirroring 'genM2bHandler M2bTailResume'). Both arms route 'resume' ONLY into the
-- '__cont_store' continuation argument --- the EXACT position the boundary guard's
-- store-route exemption admits (every other escape stays rejected), and the cell is
-- a FRESH '__cont_cell_new' bound inside the arm (the carrier-wall check admits it).
genM3Handler :: M3Route -> Ty.CType -> GenM2b Handler
genM3Handler route progTy = do
  vN      <- freshN2b (T.pack "v")
  nN      <- freshN2b (T.pack "opn")
  kN      <- freshN2b (T.pack "k")
  cellN   <- freshN2b (T.pack "cell")
  filledN <- freshN2b (T.pack "filled")
  case route of
    M3StoreResume -> do
      svN <- freshN2b (T.pack "sv")
      k2N <- freshN2b (T.pack "k2")
      rrN <- freshN2b (T.pack "rr")
      -- Return arm: wrap in Some so it stays a boxed cell (parallels the M2b
      -- skeleton). It is reached only if the program returns WITHOUT performing the
      -- op; the generated 'prog' always performs the op, so the resume arm runs.
      let retArm =
            ( Binder vN Unrestricted progTy
            , Let (Binder svN Unrestricted m2bOptTy) (RCon (T.pack "Some") [AVar vN])
                (Ret (AVar svN)) )
          -- The taken continuation is resumed in TAIL position (@k2 1@), exactly as
          -- the admitted corpus '01-store-resume.wok'. ANF has no tail application,
          -- so the tail @k2 1@ elaborates to @let rr = k2 1 in rr@ (the corpus's own
          -- shape after ANF): the resume result is the arm's answer.
          armBody =
            Let (Binder cellN Unrestricted m2bBoxTy) (RApp m3CellNew [ALit LUnit])
              (Let (Binder filledN Unrestricted m2bBoxTy)
                   (RApp m3Store [AVar cellN, AVar kN])
                (Let (Binder k2N Unrestricted m2bOptTy) (RApp m3Take [AVar filledN])
                  (Let (Binder rrN Unrestricted progTy) (RApp (AVar k2N) [ALit (LInt 1)])
                    (Ret (AVar rrN)))))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] Nothing Nothing Nothing)
    M3StoreDrop -> do
      svN   <- freshN2b (T.pack "sv")
      noneN <- freshN2b (T.pack "none")
      let retArm =
            ( Binder vN Unrestricted progTy
            , Let (Binder svN Unrestricted m2bOptTy) (RCon (T.pack "Some") [AVar vN])
                (Ret (AVar svN)) )
          armBody =
            Let (Binder cellN Unrestricted m2bBoxTy) (RApp m3CellNew [ALit LUnit])
              (Let (Binder filledN Unrestricted m2bBoxTy)
                   (RApp m3Store [AVar cellN, AVar kN])
                (Let (Binder noneN Unrestricted m2bOptTy) (RCon (T.pack "None") [])
                  (Ret (AVar noneN))))
          arm = OpArm m2bLbl m2bOp [Binder nN Unrestricted m2bU64]
                  (Binder kN Unrestricted m2bOptTy) armBody
      pure (Handler retArm [arm] Nothing Nothing Nothing)

-- | Shrinker for a generated M3 program: identical to 'shrinkProgramM2b' (shrink
-- the main bind's body to a structurally-contained sub-expression, keeping any CAF
-- bind). A program whose main body shrinks below the 'Handle' drops out of the
-- store-route fragment (no handler), which the boundary guard still accepts, so a
-- shrunk counterexample stays valid.
shrinkProgramM3 :: CoreModule -> [CoreModule]
shrinkProgramM3 = shrinkProgramM2b

-- ---------------------------------------------------------------------------
-- Structural detectors for the M3 store-route coverage floors. They classify the
-- GENERATED program by inspecting its single 'Handle' node's op arm --- NOT by
-- re-running the pass. Used only for 'cover' / 'label' non-vacuity.

-- | The op arm performs a '__cont_store' (the store route): its body contains a
-- saturated @__cont_store cell resume@ call.
m3HasStore :: CoreModule -> Bool
m3HasStore cm = case m2bTheHandler cm of
  Just h  -> any (storesIn . oaBody) (hOps h)
  Nothing -> False
  where
    storesIn e = case e of
      Let _ (RApp hd _) b -> isStoreAtom hd || storesIn b
      Let _ _ b           -> storesIn b
      Case _ alts         -> any (storesIn . clusterAltBody) alts
      LetJoin _ _ jb b     -> storesIn jb || storesIn b
      _                    -> False

-- | The op arm '__cont_take's the cell back out and resumes it (the
-- store -> take -> resume route).
m3HasTakeResume :: CoreModule -> Bool
m3HasTakeResume cm = case m2bTheHandler cm of
  Just h  -> any (takesIn . oaBody) (hOps h)
  Nothing -> False
  where
    takesIn e = case e of
      Let _ (RApp hd _) b -> isTakeAtom hd || takesIn b
      Let _ _ b           -> takesIn b
      Case _ alts         -> any (takesIn . clusterAltBody) alts
      LetJoin _ _ jb b     -> takesIn jb || takesIn b
      _                    -> False

-- | The op arm stores and ABANDONS (never takes): a store with no take (the
-- store -> drop park-and-abandon route).
m3HasStoreDrop :: CoreModule -> Bool
m3HasStoreDrop cm = m3HasStore cm && not (m3HasTakeResume cm)

isStoreAtom, isTakeAtom :: Atom -> Bool
isStoreAtom (APrim k) = k == PN.contStoreKey
isStoreAtom _         = False
isTakeAtom (APrim k) = k == PN.contTakeKey
isTakeAtom _         = False

-- | A coarse label of the generated M3 program's shape, for the distribution
-- readout.
m3Classify :: CoreModule -> String
m3Classify cm =
  (if m3HasTakeResume cm then "store-resume"
   else if m3HasStoreDrop cm then "store-drop" else "no-store")
    <> (if m2bHasMovedBeforeOp cm then "/moved" else "")
    <> (if m2bHasBoxedAcrossOp cm then "/across" else "")
    <> (if m2bHasAliasedBoxed cm  then "/aliased" else "")
    <> (if m2bHasGlobalAcrossOp cm then "/global" else "")
    <> (if m2bHasOpUnderCase cm then "/under-case" else "")

-- | The computation has TWO live aliases of one boxed cell (the 'M2bAliasedBoxed'
-- shape): a @let a = x@ (a pure alias-rename) of a boxed binder @x@, both live
-- across the op. Detected structurally: a @let a = RAtom (AVar x)@ where @x@ is a
-- prior boxed @let@.
m2bHasAliasedBoxed :: CoreModule -> Bool
m2bHasAliasedBoxed cm = case m2bTheProg cm of
  Just e  -> go Set.empty e
  Nothing -> False
  where
    go boxed e = case e of
      Let _ (RAtom (AVar x)) body
        | Set.member (nameUniq x) boxed -> True
        | otherwise -> go boxed body
      Let b _ body -> go (insertIfBoxed b boxed) body
      Case _ alts  -> any (go boxed . clusterAltBody) alts
      LetJoin _ _ jb body -> go boxed jb || go boxed body
      _ -> False
    insertIfBoxed b s =
      if Esc.isBoxedType (bndType b) then Set.insert (binderUnique b) s else s

-- | The computation references a top-level boxed CAF (the 'M2bGlobalAcrossOp'
-- shape): the program has the splice 'g_caf' bind alongside main.
m2bHasGlobalAcrossOp :: CoreModule -> Bool
m2bHasGlobalAcrossOp (CoreModule binds) =
  any (\(TopBind n _ _) -> nameHint n == T.pack "g_caf") binds

-- | The accepted=>sound property for the M3 store route. Mirrors 'prop_m2bEscape'
-- EXACTLY (the accepted/skipped split, the dual heap-balance + value-match oracle,
-- the 'rcMemSafetyFault' both-fail hardening). The accept predicate is the REAL
-- guard, which already includes the M3 carrier-wall check and the store-route
-- boundary relaxation. The 'checkCoverage' floors make NON-VACUITY a HARD FAILURE:
-- if the generator stops producing a store-route dimension above its floor, the
-- property goes red.
prop_m3Escape :: Property
prop_m3Escape =
  forAllShrink genM3Program shrinkProgramM3 $ \cm0 -> QC.ioProperty $ do
    let cm       = pruneToReachable cm0
        accepted = null (firstOrderNoHandlerViolations cm)
        refRes   = Interp.runModule cm
    rcRes <- RCM.runModuleRCUnchecked (Perceus.insertRC cm)
    let report   =
          "boundary accepted: " <> show accepted
            <> "\ninstrumented ANF:\n" <> T.unpack (Perceus.prettyPerceus cm)
            <> "\nreference: " <> showR (fmap Interp.renderValue refRes)
            <> "\nrc:        " <> showRC rcRes
        ranSound    = accepted && either (const False) (const True) rcRes
        storeResume = m3HasTakeResume cm
        storeDrop   = m3HasStoreDrop cm
        movedB      = m2bHasMovedBeforeOp cm
        aliased     = m2bHasAliasedBoxed cm
        boxedAcr    = m2bHasBoxedAcrossOp cm
        opAbove     = m2bHasOpUnderCase cm
        globalAcr   = m2bHasGlobalAcrossOp cm
    pure $ checkCoverage $
       cover 30.0 (storeResume && ranSound) "store-resume run (store->take->resume)" $
       cover 30.0 (storeDrop && ranSound)   "store-drop run (store->drop, cascade free)" $
       cover 10.0 (movedB && ranSound)      "moved-into-con present (store path)" $
       cover  8.0 (aliased && ranSound)     "two-alias present (store path)" $
       cover 10.0 (boxedAcr && ranSound)    "boxed-value live across store" $
       cover 12.0 (opAbove && ranSound)     "store under non-trivial above (Case branch)" $
       cover  6.0 (globalAcr && ranSound)   "global/CAF live across store" $
       QC.label (m3Classify cm <> (if accepted then " accepted" else " rejected")) $
       counterexample report $
         if not accepted
           then property True
           else case (refRes, rcRes) of
                  (Right v, Right run) ->
                    let outOk      = Interp.renderValue v == RCM.rcOutput run
                        st         = RCM.rcStats run
                        baseline   = RCM.rcBaseline run
                        liveOk     = St.stLive st == baseline
                        balancedOk = St.stAllocs st - St.stFrees st == baseline
                    in counterexample "ACCEPTED but unsound: output / heap-empty / balanced mismatch"
                         (outOk && liveOk && balancedOk)
                  (Left refE, Left rcE)
                    | rcMemSafetyFault rcE ->
                        counterexample ("ACCEPTED but unsound: RC memory-safety fault hidden behind a \
                                        \reference failure: rc=" <> show rcE <> " ref=" <> show refE)
                          False
                    | errCtorTag refE == errCtorTag rcE ->
                        counterexample "both interpreters failed the same way (agreement)" True
                    | otherwise ->
                        counterexample ("ACCEPTED but unsound: RC failure DIVERGES from the reference \
                                        \failure: ref=" <> show refE <> " rc=" <> show rcE)
                          False
                  _ ->
                    counterexample "ACCEPTED but unsound: exactly one interpreter failed" False
  where
    showR (Right t)  = T.unpack t
    showR (Left e)   = "FAILED (" <> show e <> ")"
    showRC (Right run) = T.unpack (RCM.rcOutput run)
    showRC (Left e)    = "FAILED (" <> show e <> ")"

-- | balanceLint must be clean on every ADMITTED M3 store-route program. Mirrors
-- 'prop_m2bLintClean': a boundary-rejected program may legitimately lint dirty (the
-- conservative reject), so we gate on acceptance.
prop_m3LintClean :: Property
prop_m3LintClean =
  forAllShrink genM3Program shrinkProgramM3 $ \cm0 ->
    let cm   = pruneToReachable cm0
        viol = Perceus.balanceLint cm
    in if not (null (firstOrderNoHandlerViolations cm))
         then property True
         else counterexample ("balanceLint reported on an ADMITTED store-route program: " <> show viol
                                <> "\nANF:\n" <> T.unpack (Perceus.prettyPerceus cm))
                (null viol)

-- | Every single-site RC mutation must be CAUGHT on every generated M3 store-route
-- program --- statically ('lintInstrumented'), at runtime (a 'Left'), OR via heap
-- imbalance ('stLive /= baseline' or 'stAllocs - stFrees /= baseline'). The
-- heap-imbalance check is necessary for the cell-drop path: omitting the
-- '__rc_drop(filled)' on the abandon arm leaks the parked NCont + its owned set
-- (a LEAK, 'stLive > baseline') rather than a crash. Reuses 'mutationCaughtM2b'
-- (the M2b teeth oracle with the heap-imbalance detector).
prop_m3Teeth :: Property
prop_m3Teeth =
  forAllShrink genM3Program shrinkProgramM3 $ \cm0 -> QC.ioProperty $ do
    let cm = pruneToReachable cm0
    props <- mapM
      (\mut -> do
         caught <- mutationCaughtM2b mut cm
         pure (counterexample ("mutation " <> show mut <> " was NOT caught\nANF:\n"
                                 <> T.unpack (Perceus.prettyPerceus cm))
                 caught))
      [Perceus.OmitOneDrop, Perceus.OmitOneDup, Perceus.DuplicateOneDrop]
    pure (conjoin props)

-- | Suite G (extended, M3): the generative oracle for the stored-continuation
-- store route. The accepted=>sound property, the lint-clean property, and the
-- generalized teeth, with coverage floors that fail the property if any store-route
-- dimension stops being generated.
rcM3PropertyTests :: TestTree
rcM3PropertyTests =
  localOption (QuickCheckTests 800) $
    testGroup "rc m3 property (Suite G extended: stored-continuation store route)"
      [ testProperty "accepted => sound (heap-balanced + value-match); rejected => skipped"
          prop_m3Escape
      , testProperty "balanceLint is clean on every admitted store-route program"
          prop_m3LintClean
      , testProperty "every single-site RC mutation is caught on the store/drop path"
          prop_m3Teeth
      ]

-- ---------------------------------------------------------------------------
-- Task 2: RVRecMember representation tests

-- | 'St.valueChildren' must correctly enumerate the COUNTED child addresses for
-- each 'St.RCValue' variant. 'RVLit' has none, 'RVBox' has one (the node
-- pointer), and 'RVRecMember' has one (the shared env addr @envAddr@); the
-- static @groupAddr@ is UNCOUNTED and must NOT appear.
rvRecMemberChildren :: Assertion
rvRecMemberChildren = do
  assertEqual "lit has no children"    []  (St.valueChildren (St.RVLit LUnit))
  assertEqual "box child"              [St.HAddr 7] (St.valueChildren (St.RVBox (St.HAddr 7)))
  assertEqual "recmember counts env"   [St.HAddr 9] (St.valueChildren (St.RVRecMember (St.HAddr (-5)) 0 (St.HAddr 9)))

-- | Dropping the env address referenced by an 'St.RVRecMember' must free the
-- 'NEnv' cell.  An 'NEnv Map.empty' has no children, so after the single drop
-- the live count must be zero.
rvRecMemberDropCountsEnv :: Assertion
rvRecMemberDropCountsEnv = do
  let (envA, s0) = St.allocPure (St.NEnv Map.empty) St.emptyStore
  case St.dropAddrPure envA s0 of
    Right s1 -> assertEqual "env freed" 0 (St.stLive (St.stStats s1))
    Left err -> assertFailure (show err)

-- | The static sentinel installed by 'St.initSentinel' must live at
-- 'St.emptyEnvSentinelAddr' and be a static (negative) address, so
-- 'St.increfPure' and 'St.dropAddrPure' are no-ops on it.
rvRecMemberSentinelNoOp :: Assertion
rvRecMemberSentinelNoOp = do
  let s0 = St.initSentinel St.emptyStore
  -- The sentinel must be at the fixed static address.
  assertEqual "sentinel addr is static" True (St.isStaticAddr St.emptyEnvSentinelAddr)
  -- incref on the sentinel is a no-op: store is unchanged.
  case St.increfPure St.emptyEnvSentinelAddr s0 of
    Left err -> assertFailure ("incref sentinel failed: " <> show err)
    Right s1 -> assertEqual "incref on sentinel is no-op (live unchanged)" 0
                  (St.stLive (St.stStats s1))
  -- dropAddr on the sentinel is a no-op: store is unchanged.
  case St.dropAddrPure St.emptyEnvSentinelAddr s0 of
    Left err -> assertFailure ("drop sentinel failed: " <> show err)
    Right s1 -> assertEqual "drop on sentinel is no-op (live unchanged)" 0
                  (St.stLive (St.stStats s1))

-- | 'St.renderRCValue' must render an 'St.RVRecMember' as @"<closure>"@,
-- matching the reference interpreter's closure rendering for the differential
-- oracle.
rvRecMemberRender :: Assertion
rvRecMemberRender = do
  let s  = St.emptyStore
      v  = St.RVRecMember (St.HAddr (-5)) 0 (St.HAddr 9)
  case St.renderRCValue s v of
    Left err  -> assertFailure ("renderRCValue failed: " <> show err)
    Right txt -> assertEqual "renders as <closure>" (T.pack "<closure>") txt

-- | The test group for the 'RVRecMember' / 'NGroupCode' / 'NEnv'
-- representation additions (Task 2, M2a-2).
rvRecMemberRepTests :: TestTree
rvRecMemberRepTests = testGroup "rvrecmember-rep"
  [ testCase "valueChildren: lit=[], box=[a], recmember=[envAddr]" rvRecMemberChildren
  , testCase "drop of envAddr frees the NEnv cell"                 rvRecMemberDropCountsEnv
  , testCase "sentinel addr is static; incref/drop are no-ops"     rvRecMemberSentinelNoOp
  , testCase "renderRCValue of RVRecMember is <closure>"           rvRecMemberRender
  ]

-- ---------------------------------------------------------------------------
-- M2b-1 fragment predicate tests (Task 1)

-- | Build a minimal 'CoreModule' whose @main@ body is 'Handle comp hdlr'.
-- The @comp@ simply performs the single op then returns its result, so the
-- computation is meaningful without an interpreter.
m2b1Cm :: Anf.Handler -> Anf.Expr -> CoreModule
m2b1Cm hdlr comp =
  CoreModule
    [ TopBind (Name (T.pack "main") (Unique 9900)) [] (Handle comp hdlr) ]

-- | Helper: the unit 'CoreModule' for the M2b-1 tests. @comp@ is the inner
-- expression. We use pruneToReachable so the guard only sees the main bind.
m2b1Pruned :: Anf.Handler -> Anf.Expr -> CoreModule
m2b1Pruned h c = pruneToReachable (m2b1Cm h c)

-- Shared types / names used by the M2b-1 fixture builders.
m2b1Unit :: Ty.CType
m2b1Unit = Ty.CTCon Ty.TcUnit []

m2b1U64 :: Ty.CType
m2b1U64 = Ty.CTCon Ty.TcU64 []

m2b1Nm :: String -> Int -> Name
m2b1Nm h u = Name (T.pack h) (Unique u)

m2b1Bnd :: String -> Int -> Ty.CType -> Binder
m2b1Bnd h u t = Binder (m2b1Nm h u) Unrestricted t

-- | A simple inner computation: @let a = E.op () in Ret (AVar a)@.
m2b1Comp :: String -> String -> Name -> Expr
m2b1Comp lbl op aName =
  Let (Binder aName Unrestricted m2b1Unit)
      (ROp Nothing (T.pack lbl) (T.pack op) [ALit LUnit])
      (Ret (AVar aName))

-- | Build a M2b-1 Reader-shaped handler:
--   Ask.ask(p:U64, resume:?) -> let r = resume(41) in Ret r
--   return v -> Ret v
-- No hParam, no hAnswerJoin, resume used only as a call head.
mkReaderHandler :: Expr -> (Anf.Handler, Expr)
mkReaderHandler comp =
  let v      = m2b1Nm "v"      9910
      resume = m2b1Nm "resume" 9912
      r      = m2b1Nm "r"      9913
      armBody = Let (Binder (m2b1Nm "r" 9913) Unrestricted m2b1Unit)
                    (RApp (AVar resume) [ALit (LInt 41)])
                    (Ret (AVar r))
      arm = Anf.OpArm (T.pack "Ask") (T.pack "ask")
              [Binder (Name (T.pack "p") (Unique 9911)) Unrestricted m2b1Unit]
              (Binder (Name (T.pack "resume") (Unique 9912)) Unrestricted m2b1Unit)
              armBody
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9910)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] Nothing Nothing Nothing
  in (hdlr, comp)

-- | Build a Tick-shaped handler:
--   Tick.tick(p, resume) -> let r = resume () in Ret r
--   return v -> Ret v
mkTickHandler :: Expr -> (Anf.Handler, Expr)
mkTickHandler comp =
  let v      = m2b1Nm "v"      9920
      resume = m2b1Nm "resume" 9922
      r      = m2b1Nm "r"      9923
      armBody = Let (Binder (Name (T.pack "r") (Unique 9923)) Unrestricted m2b1Unit)
                    (RApp (AVar resume) [ALit LUnit])
                    (Ret (AVar r))
      arm = Anf.OpArm (T.pack "Tick") (T.pack "tick")
              [Binder (Name (T.pack "p") (Unique 9921)) Unrestricted m2b1Unit]
              (Binder (Name (T.pack "resume") (Unique 9922)) Unrestricted m2b1Unit)
              armBody
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9920)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] Nothing Nothing Nothing
  in (hdlr, comp)

-- | Build an Except-abort handler:
--   Abort.abort(p, resume) -> Ret (ALit 7)   [resume unused]
--   return v -> Ret v
mkAbortHandler :: Expr -> (Anf.Handler, Expr)
mkAbortHandler comp =
  let v      = m2b1Nm "v"      9930
      arm = Anf.OpArm (T.pack "Abort") (T.pack "abort")
              [Binder (Name (T.pack "p") (Unique 9931)) Unrestricted m2b1Unit]
              (Binder (Name (T.pack "resume") (Unique 9932)) Unrestricted m2b1Unit)
              (Ret (ALit (LInt 7)))
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9930)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] Nothing Nothing Nothing
  in (hdlr, comp)

-- | Build a handler with a handler-parameter (must be REJECTED, M2b-2):
--   hParam = Just someParam
mkParamHandler :: Expr -> (Anf.Handler, Expr)
mkParamHandler comp =
  let v      = m2b1Nm "v"      9940
      param  = m2b1Bnd "st" 9941 m2b1U64
      resume = m2b1Nm "resume" 9942
      r      = m2b1Nm "r"      9943
      armBody = Let (Binder (Name (T.pack "r") (Unique 9943)) Unrestricted m2b1Unit)
                    (RApp (AVar resume) [ALit LUnit])
                    (Ret (AVar r))
      arm = Anf.OpArm (T.pack "State") (T.pack "get")
              []
              (Binder (Name (T.pack "resume") (Unique 9942)) Unrestricted m2b1Unit)
              armBody
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9940)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] Nothing (Just param) Nothing
  in (hdlr, comp)

-- | Build a handler in value (non-tail) position (must be REJECTED, M2b-2):
--   hAnswerJoin = Just someJoin
mkValuePosHandler :: Expr -> (Anf.Handler, Expr)
mkValuePosHandler comp =
  let v      = m2b1Nm "v"      9950
      ajoin  = JoinId (Unique 9959)
      resume = m2b1Nm "resume" 9952
      r      = m2b1Nm "r"      9953
      armBody = Let (Binder (Name (T.pack "r") (Unique 9953)) Unrestricted m2b1Unit)
                    (RApp (AVar resume) [ALit LUnit])
                    (Ret (AVar r))
      arm = Anf.OpArm (T.pack "E") (T.pack "op")
              []
              (Binder (Name (T.pack "resume") (Unique 9952)) Unrestricted m2b1Unit)
              armBody
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9950)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] (Just ajoin) Nothing Nothing
  in (hdlr, comp)

-- | Build a handler whose resume is stored into a Cons cell (must be REJECTED, M3):
--   E.op(p, resume) -> let c = Cons resume Nil in Ret unit   [resume escapes into con]
mkResumeStoredHandler :: Expr -> (Anf.Handler, Expr)
mkResumeStoredHandler comp =
  let v      = m2b1Nm "v"      9960
      resume = m2b1Nm "resume" 9962
      -- store resume into a Cons constructor
      armBody = Let (Binder (Name (T.pack "c") (Unique 9963)) Unrestricted m2b1Unit)
                    (RCon (T.pack "Cons") [AVar resume, ALit LUnit])
                    (Ret (ALit LUnit))
      arm = Anf.OpArm (T.pack "E") (T.pack "op")
              []
              (Binder (Name (T.pack "resume") (Unique 9962)) Unrestricted m2b1Unit)
              armBody
      hdlr = Anf.Handler (Binder (Name (T.pack "v") (Unique 9960)) Unrestricted m2b1Unit, Ret (AVar v))
               [arm] Nothing Nothing Nothing
  in (hdlr, comp)

-- | The M2b fragment predicate unit tests.
rcM2b1FragmentTests :: TestTree
rcM2b1FragmentTests = testGroup "m2b-1 fragment predicate"
  [ testCase "Reader-shaped (tail, no param, resume as call head): admitted" $
      let aName = Name (T.pack "a") (Unique 9905)
          comp  = m2b1Comp "Ask" "ask" aName
          (hdlr, c) = mkReaderHandler comp
          cm = m2b1Pruned hdlr c
      in firstOrderNoHandlerViolations cm @?= []

  , testCase "Tick (tail, no param, resume once): admitted" $
      let aName = Name (T.pack "a") (Unique 9906)
          comp  = m2b1Comp "Tick" "tick" aName
          (hdlr, c) = mkTickHandler comp
          cm = m2b1Pruned hdlr c
      in firstOrderNoHandlerViolations cm @?= []

  , testCase "Abort-shaped (tail, no param, resume unused): admitted" $
      let aName = Name (T.pack "a") (Unique 9907)
          comp  = m2b1Comp "Abort" "abort" aName
          (hdlr, c) = mkAbortHandler comp
          cm = m2b1Pruned hdlr c
      in firstOrderNoHandlerViolations cm @?= []

  , testCase "hParam = Just _ : admitted (M2b-2 baton model)" $
      let aName = Name (T.pack "a") (Unique 9908)
          comp  = m2b1Comp "State" "get" aName
          (hdlr, c) = mkParamHandler comp
          cm = m2b1Pruned hdlr c
      in firstOrderNoHandlerViolations cm @?= []

  , testCase "hAnswerJoin = Just _ : admitted (M2b-2 Task 5 value-position)" $
      let aName = Name (T.pack "a") (Unique 9909)
          comp  = m2b1Comp "E" "op" aName
          (hdlr, c) = mkValuePosHandler comp
          cm = m2b1Pruned hdlr c
      in firstOrderNoHandlerViolations cm @?= []

  , testCase "resume stored into a con: rejected (mentions escapes)" $
      let aName = Name (T.pack "a") (Unique 9969)
          comp  = m2b1Comp "E" "op" aName
          (hdlr, c) = mkResumeStoredHandler comp
          cm = m2b1Pruned hdlr c
          viols = firstOrderNoHandlerViolations cm
      in assertBool ("expected rejection for resume escape; got: " <> show viols)
           (any (T.isInfixOf (T.pack "ESCAPES")) viols)

  , testCase "consistency: m2bHandlerInFragment agrees with (null . m2bHandlerViolations) for Reader" $
      let aName = Name (T.pack "a") (Unique 9970)
          comp  = m2b1Comp "Ask" "ask" aName
          (hdlr, _) = mkReaderHandler comp
      in Esc.m2bHandlerInFragment hdlr
           @?= null (m2bHandlerViolations hdlr)

  , testCase "consistency: m2bHandlerInFragment agrees with (null . m2bHandlerViolations) for param handler" $
      let aName = Name (T.pack "a") (Unique 9971)
          comp  = m2b1Comp "State" "get" aName
          (hdlr, _) = mkParamHandler comp
      in Esc.m2bHandlerInFragment hdlr
           @?= null (m2bHandlerViolations hdlr)

  , testCase "consistency: m2bHandlerInFragment agrees with (null . m2bHandlerViolations) for resume-stored" $
      let aName = Name (T.pack "a") (Unique 9972)
          comp  = m2b1Comp "E" "op" aName
          (hdlr, _) = mkResumeStoredHandler comp
      in Esc.m2bHandlerInFragment hdlr
           @?= null (m2bHandlerViolations hdlr)

  , testCase "consistency: m2bHandlerInFragment agrees with (null . m2bHandlerViolations) for value-position" $
      let aName = Name (T.pack "a") (Unique 9973)
          comp  = m2b1Comp "E" "op" aName
          (hdlr, _) = mkValuePosHandler comp
      in Esc.m2bHandlerInFragment hdlr
           @?= null (m2bHandlerViolations hdlr)

  , testCase "existing LetRec checks untouched: cross-region viol still fires" $
      let intTy  = Ty.CTCon Ty.TcU64 []
          funTy  = Ty.CTCon (Ty.TcUser (T.pack "Fun")) []
          nm h u = Name (T.pack h) (Unique u)
          -- Outer letrec has TWO members: f and g_outer.
          -- Inner letrec (inside f's body) has h, which captures g_outer ---
          -- an OUTER region member.  rawEnclosingFv {h} ∩ lr = {g_outer} /= {}.
          body =
            LetRec
              [ ( Binder (nm "f" 8800) Unrestricted funTy
                , [Binder (nm "k" 8801) Unrestricted intTy]
                , LetRec
                    [ ( Binder (nm "h" 8802) Unrestricted funTy
                      , [Binder (nm "j" 8803) Unrestricted intTy]
                      , Ret (AVar (nm "g_outer" 8810)) ) ]  -- captures outer member
                    (Let (Binder (nm "r" 8804) Unrestricted funTy)
                         (RApp (AVar (nm "h" 8802)) [ALit (LInt 0)])
                      (Ret (AVar (nm "r" 8804)))) )
              , ( Binder (nm "g_outer" 8810) Unrestricted funTy
                , [Binder (nm "m" 8811) Unrestricted intTy]
                , Ret (ALit (LInt 0)) ) ]
              (Let (Binder (nm "res" 8805) Unrestricted funTy)
                   (RApp (AVar (nm "f" 8800)) [ALit (LInt 0)])
                (Ret (AVar (nm "res" 8805))))
          cm = pruneToReachable (CoreModule [TopBind (nm "main" 8899) [] body])
          viols = firstOrderNoHandlerViolations cm
      in assertBool ("expected cross-region viol; got: " <> show viols)
           (any (T.isInfixOf (T.pack "cross-region")) viols)
  ]

-- ---------------------------------------------------------------------------
-- M2b-2 continuationOwned unit tests (code-review #3)

-- | Build a minimal 'Handler' with 'hParam = Just pb' and an otherwise-empty
-- body (no return expression needed; 'continuationOwned' only inspects the
-- frame, not arm bodies).
-- The hsc in each test simulates the post-resume state where pb is already
-- bound in the handler scope; hReturn uses a distinct binder (Unique 9991) so
-- the two roles never share a Unique.
m2b2ParamHandler :: Binder -> Anf.Handler
m2b2ParamHandler pb =
  let retBndr = Binder (Name (T.pack "ret") (Unique 9991)) Unrestricted m2bBoxTy
  in Anf.Handler
    { Anf.hReturn     = (retBndr, Ret (ALit LUnit))
    , Anf.hOps        = []
    , Anf.hAnswerJoin = Nothing
    , Anf.hParam      = Just pb
    , Anf.hSelf       = Nothing
    }

-- | Build an 'Handler' with 'hParam = Nothing'.
m2b2NoParamHandler :: Anf.Handler
m2b2NoParamHandler =
  Anf.Handler
    { Anf.hReturn     = (Binder (Name (T.pack "v") (Unique 9990)) Unrestricted m2bBoxTy, Ret (ALit LUnit))
    , Anf.hOps        = []
    , Anf.hAnswerJoin = Nothing
    , Anf.hParam      = Nothing
    , Anf.hSelf       = Nothing
    }

-- | 'continuationOwned' of a prefix containing a PARAMETERIZED nested handler
-- frame must include the parameter's dynamic address in the owned set.
continuationOwnedNestedParam :: Assertion
continuationOwnedNestedParam = do
  let dynAddr = St.HAddr 7  -- non-static (positive) address
      pb      = Binder (Name (T.pack "s") (Unique 8001)) Unrestricted m2bBoxTy
      h       = m2b2ParamHandler pb
      -- The frame's hsc binds pb's Unique to RVBox dynAddr.
      hsc     = St.RCScope (Map.fromList [(Unique 8001, St.RVBox dynAddr)]) Map.empty
      kont    = St.KHandleRC h 0 hsc St.KDoneRC
  assertEqual "continuationOwned includes nested param addr" [dynAddr]
    (St.continuationOwned kont)

-- | 'continuationOwned' of a prefix containing a no-parameter nested handler
-- frame must contribute NOTHING (M2b-1 behaviour unchanged).
continuationOwnedNoParam :: Assertion
continuationOwnedNoParam = do
  let h    = m2b2NoParamHandler
      hsc  = St.emptyRCScope
      kont = St.KHandleRC h 0 hsc St.KDoneRC
  assertEqual "continuationOwned with no hParam is empty" []
    (St.continuationOwned kont)

-- | The dedup invariant: the same param address reachable from TWO nested
-- handler frames with different Uniques must appear TWICE (they are distinct
-- owned slots, matching the refcount bump the interpreter performs on entry).
continuationOwnedDedup :: Assertion
continuationOwnedDedup = do
  let dynAddr = St.HAddr 7
      pb1     = Binder (Name (T.pack "s1") (Unique 8010)) Unrestricted m2bBoxTy
      pb2     = Binder (Name (T.pack "s2") (Unique 8011)) Unrestricted m2bBoxTy
      h1      = m2b2ParamHandler pb1
      h2      = m2b2ParamHandler pb2
      hsc1    = St.RCScope (Map.fromList [(Unique 8010, St.RVBox dynAddr)]) Map.empty
      hsc2    = St.RCScope (Map.fromList [(Unique 8011, St.RVBox dynAddr)]) Map.empty
      -- Two stacked parameterized handlers: inner h2 on top of outer h1.
      kont    = St.KHandleRC h2 0 hsc2 (St.KHandleRC h1 0 hsc1 St.KDoneRC)
  -- Distinct Uniques: both entries survive dedup -> addr appears twice.
  assertEqual "two distinct param binders each contribute their addr"
    [dynAddr, dynAddr]
    (St.continuationOwned kont)

-- | Dedup SUPPRESSES a DUPLICATE entry: the same binder Unique appearing twice
-- (aliased live-across-frames) should be counted once, matching refcount.
continuationOwnedSameUniqueDedup :: Assertion
continuationOwnedSameUniqueDedup = do
  let dynAddr = St.HAddr 7
      pb      = Binder (Name (T.pack "s") (Unique 8020)) Unrestricted m2bBoxTy
      h       = m2b2ParamHandler pb
      hsc     = St.RCScope (Map.fromList [(Unique 8020, St.RVBox dynAddr)]) Map.empty
      -- Same handler (same Unique pb) stacked twice: dedup collapses to one.
      kont    = St.KHandleRC h 0 hsc (St.KHandleRC h 0 hsc St.KDoneRC)
  assertEqual "same Unique deduped to a single addr" [dynAddr]
    (St.continuationOwned kont)

-- | The (Unique, Addr) dedup distinguishes SAME UNIQUE but DIFFERENT ADDRESSES.
-- This is the 'set'-arm scenario after a two-arg resume (M2b-2 Task 4D): the
-- param binder 'pb' appears in the KHandleRC frame (new value, addrA) AND in a
-- KLetRC frame below it (old value in env2, addrB).  Both must be freed.
-- A Unique-only dedup would collapse them into one free, leaking addrB.
-- This test pins the (Unique, Addr) keying that 'continuationOwned' uses.
continuationOwnedSameUniqueDiffAddr :: Assertion
continuationOwnedSameUniqueDiffAddr = do
  let addrA = St.HAddr 7    -- new param value (in KHandleRC)
      addrB = St.HAddr 8    -- old param value (in KLetRC env2)
      pb    = Binder (Name (T.pack "s") (Unique 8030)) Unrestricted m2bBoxTy
      h     = m2b2ParamHandler pb
      hsc   = St.RCScope (Map.fromList [(Unique 8030, St.RVBox addrA)]) Map.empty
      -- KLetRC frame: result binder 'rr' (Unique 8031), body = Ret (AVar pb) so
      -- that 'frameOwned' sees pb.Unique as an owning (non-head) occurrence that
      -- is also free in the body. The scope binds pb.Unique to addrB (old value).
      rr    = Binder (Name (T.pack "rr") (Unique 8031)) Unrestricted m2bBoxTy
      body  = Ret (AVar (Name (T.pack "s") (Unique 8030)))
      sc2   = St.RCScope (Map.fromList [(Unique 8030, St.RVBox addrB)]) Map.empty
      -- KHandleRC (new addrA) on top of KLetRC (old addrB in env2).
      kont  = St.KHandleRC h 0 hsc (St.KLetRC rr body sc2 St.KDoneRC)
  -- Both (pb.Unique, addrA) and (pb.Unique, addrB) survive dedup: different Addr.
  assertEqual "same Unique but different addrs: BOTH freed (no Unique-only dedup)"
    [addrA, addrB]
    (St.continuationOwned kont)

-- | Test group for M2b-2 code-review #3: 'continuationOwned' frees a nested
-- parameterized handler's parameter.
rcM2b2ContinuationOwnedTests :: TestTree
rcM2b2ContinuationOwnedTests =
  testGroup "continuationOwned (m2b-2 #3: nested param freed on abort)"
    [ testCase "continuationOwned: nested parameterized handler contributes param addr"
        continuationOwnedNestedParam
    , testCase "continuationOwned: no-param handler contributes nothing (M2b-1 unchanged)"
        continuationOwnedNoParam
    , testCase "continuationOwned: two distinct Uniques each contribute (no over-dedup)"
        continuationOwnedDedup
    , testCase "continuationOwned: same Unique deduped to one (no double-free)"
        continuationOwnedSameUniqueDedup
    , testCase "continuationOwned: same Unique at DIFFERENT addrs: both freed ((Unique,Addr) keying)"
        continuationOwnedSameUniqueDiffAddr
    ]

-- ---------------------------------------------------------------------------
-- RC Array prim tests (Array Slice A, Task 3)
--
-- These tests call 'rpFn' directly on constructed 'RCValue's + a 'Store'.
-- They verify behaviour, alloc/free deltas, bounds-error paths, and that
-- dropping the result returns 'stLive' to baseline (no leak, no double-free).
-- The prim table is keyed by bare name (e.g. T.pack "new"), per the plan.
--
-- RC accounting (spec §4 summary):
--   new / fromList / set / resize : +1 alloc (the NArray cell)
--   index / length                : 0 alloc
--   toList                        : +N alloc (N Cons cells; Nil is inline,
--                                   stat-invisible)

-- | Helper: look up an RC prim by @(module, name)@ in 'RCP.rcPrimTable' or fail.
lookupPrimQ :: Text -> Text -> IO St.RCPrim
lookupPrimQ mn name =
  case Map.lookup (mn, name) RCP.rcPrimTable of
    Just p  -> pure p
    Nothing -> assertFailure
      ("rcPrimTable is missing prim: " <> T.unpack mn <> "." <> T.unpack name)

-- | Convenience wrapper that looks up an Array prim by bare name under 'Array'.
lookupPrim :: Text -> IO St.RCPrim
lookupPrim name = lookupPrimQ (T.pack "Array") name

-- | Helper: call 'rpFn' with args and an initial store, asserting it returns
-- @Right (PRDone result, store')@.
callPrim :: St.RCPrim -> [St.RCValue] -> St.Store
         -> IO (St.RCValue, St.Store)
callPrim p args s = do
  res <- runExceptT (St.rpFn p args s)
  case res of
    Right (St.PRDone v, s') -> pure (v, s')
    Right _  -> assertFailure "expected PRDone from array prim, got PRApply"
    Left e   -> assertFailure ("array prim raised: " <> show e)

-- | Helper: assert that 'rpFn' raises a 'PrimError' whose message contains the
-- given substring.
expectPrimError :: St.RCPrim -> [St.RCValue] -> St.Store -> String -> IO ()
expectPrimError p args s needle = do
  res <- runExceptT (St.rpFn p args s)
  case res of
    Left (IV.PrimError m)
      | T.pack needle `T.isInfixOf` m -> pure ()
    Left e  -> assertFailure ("expected PrimError containing " <> show needle
                               <> ", got: " <> show e)
    Right _ -> assertFailure ("expected PrimError containing " <> show needle
                               <> ", but prim succeeded")

-- | Helper: drop an 'RCValue' back to a baseline store level using 'dropAddr'
-- on any counted addresses. Returns the updated store.
dropResult :: St.RCValue -> St.Store -> IO St.Store
dropResult v s =
  case St.valueChildren v of
    []  -> pure s
    as  -> do
      res <- runExceptT (Control.Monad.foldM (flip St.dropAddr) s as)
      case res of
        Right s' -> pure s'
        Left e   -> assertFailure ("dropResult failed: " <> show e)

rcArrayPrimTests :: TestTree
rcArrayPrimTests = testGroup "rc array prims"
  [ -- ------------------------------------------------------------------
    -- new
    -- ------------------------------------------------------------------
    testCase "new 3 v: alloc +2 (array + element shared at rc 3); drop-to-baseline" $ do
      -- Allocate one boxed element e1. Call new 3 (RVBox e1).
      -- The prim incref's e1 twice (dupN 2) and allocs the NArray.
      -- Live delta from prim: +1 (NArray cell; e1 was already live).
      -- Dropping the array cascades 3 drops of e1 (rc 3->0, freed).
      pNew <- lookupPrim (T.pack "new")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e1, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          v        = St.RVBox e1
          k        = St.RVLit (Anf.LInt 3)
      (arr, s2) <- callPrim pNew [k, v] s1
      -- NArray allocated; e1 still live (refcount 3).
      St.stLive (St.stStats s2) @?= baseline + 2
      St.stAllocs (St.stStats s2) - St.stAllocs (St.stStats s1) @?= 1
      s3 <- dropResult arr s2
      St.stLive (St.stStats s3) @?= baseline

  , testCase "new 0 v: drop v then alloc empty array; +1 alloc total" $ do
      pNew <- lookupPrim (T.pack "new")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e1, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          v        = St.RVBox e1
          k        = St.RVLit (Anf.LInt 0)
      (arr, s2) <- callPrim pNew [k, v] s1
      -- e1 was dropped (rc 1 -> 0, freed); empty NArray allocated.
      St.stLive (St.stStats s2) @?= baseline + 1
      St.stAllocs (St.stStats s2) - St.stAllocs (St.stStats s1) @?= 1
      s3 <- dropResult arr s2
      St.stLive (St.stStats s3) @?= baseline

  , testCase "new: result renders as an array of the fill value" $ do
      pNew <- lookupPrim (T.pack "new")
      let s0 = St.emptyStore
          (e1, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          v = St.RVBox e1
          k = St.RVLit (Anf.LInt 2)
      (arr, s2) <- callPrim pNew [k, v] s1
      -- e1 has rc=2; array contains two refs to it.  Render: [[], []]
      case St.renderRCValue s2 arr of
        Right t -> t @?= T.pack "[[], []]"
        Left e  -> assertFailure ("render failed: " <> show e)
      -- cleanup
      _ <- dropResult arr s2
      pure ()

  -- ------------------------------------------------------------------
  -- length
  -- ------------------------------------------------------------------
  , testCase "length: returns correct count, 0 alloc, drops array" $ do
      pLength <- lookupPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e1, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e2, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (arr, s3) = St.allocPure (St.NArray [St.RVBox e1, St.RVBox e2]) s2
          allocsBefore = St.stAllocs (St.stStats s3)
      (lenVal, s4) <- callPrim pLength [St.RVBox arr] s3
      lenVal @?= St.RVLit (Anf.LInt 2)
      -- 0 new allocs from length
      St.stAllocs (St.stStats s4) @?= allocsBefore
      -- array + elements freed (cascade), heap back to baseline
      St.stLive (St.stStats s4) @?= baseline

  , testCase "length of empty array: returns 0, drops array, baseline" $ do
      pLength <- lookupPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (arr, s1) = St.allocPure (St.NArray []) s0
          allocsBefore = St.stAllocs (St.stStats s1)
      (lenVal, s2) <- callPrim pLength [St.RVBox arr] s1
      lenVal @?= St.RVLit (Anf.LInt 0)
      St.stAllocs (St.stStats s2) @?= allocsBefore
      St.stLive (St.stStats s2) @?= baseline

  -- ------------------------------------------------------------------
  -- index
  -- ------------------------------------------------------------------
  , testCase "index: returns correct element, increfs it, drops array" $ do
      pIndex <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (e2, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          (arr, s4) = St.allocPure
                        (St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2])
                        s3
          allocsBefore = St.stAllocs (St.stStats s4)
      (result, s5) <- callPrim pIndex [St.RVBox arr, St.RVLit (Anf.LInt 1)] s4
      -- result should be e1 (index 1)
      result @?= St.RVBox e1
      -- 0 new allocs
      St.stAllocs (St.stStats s5) @?= allocsBefore
      -- array freed + e0 freed + e2 freed; e1 survives (incref'd for result)
      -- so live = baseline + 1 (e1)
      St.stLive (St.stStats s5) @?= baseline + 1
      -- drop the result to return to baseline
      s6 <- dropResult result s5
      St.stLive (St.stStats s6) @?= baseline

  , testCase "index: out-of-bounds raises PrimError" $ do
      pIndex <- lookupPrim (T.pack "index")
      let s0 = St.emptyStore
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (arr, s2) = St.allocPure (St.NArray [St.RVBox e0]) s1
      -- index 1 in a 1-element array is OOB
      expectPrimError pIndex [St.RVBox arr, St.RVLit (Anf.LInt 1)] s2
        "out of bounds"

  , testCase "index: exact last element (n-1) succeeds; n is out-of-bounds" $ do
      pIndex <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (arr, s2) = St.allocPure (St.NArray [St.RVBox e0]) s1
      -- index 0 succeeds
      (result, s3) <- callPrim pIndex [St.RVBox arr, St.RVLit (Anf.LInt 0)] s2
      result @?= St.RVBox e0
      St.stLive (St.stStats s3) @?= baseline + 1
      s4 <- dropResult result s3
      St.stLive (St.stStats s4) @?= baseline
      -- A separate attempt at index 1 raises an error (1-element array).
      let (e0b, sb1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (arrb, sb2) = St.allocPure (St.NArray [St.RVBox e0b]) sb1
      expectPrimError pIndex [St.RVBox arrb, St.RVLit (Anf.LInt 1)] sb2
        "out of bounds"

  -- ------------------------------------------------------------------
  -- set (unique input -> in-place; shared input -> copy-on-write)
  -- ------------------------------------------------------------------
  , testCase "set: unique input -> 0 alloc (in-place); drop-to-baseline" $ do
      -- The array is freshly allocated (rc=1, unique). The new value is an
      -- RVLit (encodable), so the in-place fast path fires: 0 array allocs,
      -- old element dropped, same array handle returned.
      pSet <- lookupPrim (T.pack "set")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (e2, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          -- v_new: inline literal (C-encodable) to write into slot 1
          vn       = St.RVLit (Anf.LInt 99)
          (arr, s4) = St.allocPure
                        (St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2])
                        s3
          allocsBefore = St.stAllocs (St.stStats s4)
      (newArr, s5) <- callPrim pSet
                        [St.RVBox arr, St.RVLit (Anf.LInt 1), vn]
                        s4
      -- 0 alloc: in-place fast path (unique array, encodable value)
      St.stAllocs (St.stStats s5) - allocsBefore @?= 0
      -- old e1 freed (rc 1->0); arr still live (same handle) + e0 + e2 = 3 cells
      St.stLive (St.stStats s5) @?= baseline + 3
      -- value-correctness: slot 1 now holds vn
      case St.derefPure arr s5 of
        Left e  -> assertFailure ("deref after in-place set: " <> show e)
        Right c -> St.cNode c @?= St.NArray [St.RVBox e0, vn, St.RVBox e2]
      s6 <- dropResult newArr s5
      St.stLive (St.stStats s6) @?= baseline

  , testCase "set: shared input -> +1 alloc (copy-on-write), original unchanged" $ do
      -- Incref the array to rc=2 (shared) before calling set. The copy-on-write
      -- path fires: +1 alloc for a new NArray, original array slot unchanged.
      pSet <- lookupPrim (T.pack "set")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (e2, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          vn       = St.RVLit (Anf.LInt 99)
          (arr, s4) = St.allocPure
                        (St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2])
                        s3
          -- incref arr to rc=2 so arrayUnique returns False -> copy path
          s5 = either (error . show) id (St.increfPure arr s4)
          allocsBefore = St.stAllocs (St.stStats s5)
      (newArr, s6) <- callPrim pSet
                        [St.RVBox arr, St.RVLit (Anf.LInt 1), vn]
                        s5
      -- +1 alloc: copy-on-write path (shared array)
      St.stAllocs (St.stStats s6) - allocsBefore @?= 1
      -- original arr slot 1 must still hold e1 (no in-place mutation)
      case St.derefPure arr s6 of
        Left e  -> assertFailure ("deref original after shared set: " <> show e)
        Right c -> St.cNode c @?= St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2]
      -- drop the copy result
      s7 <- dropResult newArr s6
      -- arr still at rc=1 (the extra incref we added), drop it to return to baseline
      s8 <- dropResult (St.RVBox arr) s7
      St.stLive (St.stStats s8) @?= baseline

  , testCase "set: out-of-bounds raises PrimError" $ do
      pSet <- lookupPrim (T.pack "set")
      let s0 = St.emptyStore
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (vn, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (arr, s3) = St.allocPure (St.NArray [St.RVBox e0]) s2
      expectPrimError pSet [St.RVBox arr, St.RVLit (Anf.LInt 1), St.RVBox vn]
        s3 "out of bounds"

  -- ------------------------------------------------------------------
  -- resize
  -- ------------------------------------------------------------------
  , testCase "resize grow: adds fill slots, +1 alloc, drop-to-baseline" $ do
      pResize <- lookupPrim (T.pack "resize")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (fill, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          (arr, s4) = St.allocPure
                        (St.NArray [St.RVBox e0, St.RVBox e1])
                        s3
          allocsBefore = St.stAllocs (St.stStats s4)
          -- resize to length 4 (k=2 new fill slots)
          m = St.RVLit (Anf.LInt 4)
      (newArr, s5) <- callPrim pResize [St.RVBox arr, m, St.RVBox fill] s4
      St.stAllocs (St.stStats s5) - allocsBefore @?= 1
      -- old arr freed; new arr + e0 + e1 + fill (rc 2) still live
      -- e0 incref'd (kept), e1 incref'd (kept), fill incref'd once (k-1=1)
      -- live: baseline + 4 (e0, e1, fill, newArr)
      St.stLive (St.stStats s5) @?= baseline + 4
      s6 <- dropResult newArr s5
      St.stLive (St.stStats s6) @?= baseline

  , testCase "resize shrink: drops truncated tail, +1 alloc, drop-to-baseline" $ do
      pResize <- lookupPrim (T.pack "resize")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (e2, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          (fill, s4) = St.allocPure (St.NCon (T.pack "Nil") []) s3
          (arr, s5) = St.allocPure
                        (St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2])
                        s4
          allocsBefore = St.stAllocs (St.stStats s5)
          -- resize to length 1 (k=0, t=1; e1 and e2 are truncated)
          m = St.RVLit (Anf.LInt 1)
      (newArr, s6) <- callPrim pResize [St.RVBox arr, m, St.RVBox fill] s5
      St.stAllocs (St.stStats s6) - allocsBefore @?= 1
      -- fill dropped (k=0); old arr freed, e1 freed, e2 freed; e0 incref'd
      -- live: baseline + 2 (e0 + newArr); fill freed too since k=0
      St.stLive (St.stStats s6) @?= baseline + 2
      s7 <- dropResult newArr s6
      St.stLive (St.stStats s7) @?= baseline

  , testCase "resize to same length: effectively a copy, +1 alloc, drop-to-baseline" $ do
      pResize <- lookupPrim (T.pack "resize")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (fill, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (arr, s3) = St.allocPure (St.NArray [St.RVBox e0]) s2
          allocsBefore = St.stAllocs (St.stStats s3)
          m = St.RVLit (Anf.LInt 1)
      (newArr, s4) <- callPrim pResize [St.RVBox arr, m, St.RVBox fill] s3
      St.stAllocs (St.stStats s4) - allocsBefore @?= 1
      -- fill dropped (k=0), old arr freed, e0 incref'd; live = baseline+2 (e0+newArr)
      St.stLive (St.stStats s4) @?= baseline + 2
      s5 <- dropResult newArr s4
      St.stLive (St.stStats s5) @?= baseline

  -- ------------------------------------------------------------------
  -- fromList
  -- ------------------------------------------------------------------
  , testCase "fromList: builds array from Cons/Nil list, +1 alloc, drop-to-baseline" $ do
      pFromList <- lookupPrim (T.pack "fromList")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          -- Build list [e0, e1]: Cons(e0, Cons(e1, Nil))
          -- Nil is inline (no alloc stat bump); Cons cells are HAddr.
          (e0, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          -- allocPure always returns an HAddr for non-nullary NCon.
          -- For Nil (nullary), use alloc which returns Inline (stat-invisible).
          -- We build using allocPure to keep it simple -- allocPure of Nil gives
          -- an HAddr cell, which is fine for testing the prim logic.
          (nilCell, s3) = St.allocPure (St.NCon (T.pack "Nil") []) s2
          (cons1,   s4) = St.allocPure
                            (St.NCon (T.pack "Cons") [St.RVBox e1, St.RVBox nilCell])
                            s3
          (cons0,   s5) = St.allocPure
                            (St.NCon (T.pack "Cons") [St.RVBox e0, St.RVBox cons1])
                            s4
          -- xs = Cons(e0, Cons(e1, Nil)); live: e0, e1, nilCell, cons1, cons0 = 5 cells
          allocsBefore = St.stAllocs (St.stStats s5)
      (arr, s6) <- callPrim pFromList [St.RVBox cons0] s5
      -- collectList incref's e0 and e1 each once (rc goes 1->2 each).
      -- dropValue xs drops cons0 (rc 1->0 freed): cascade drops cons1 (freed),
      -- cascade drops nilCell (freed), e0 (rc 2->1), e1 (rc 2->1).
      -- NArray alloc: +1.
      -- live after: e0 (rc=1 in array), e1 (rc=1 in array), arr = 3 cells
      St.stAllocs (St.stStats s6) - allocsBefore @?= 1
      St.stLive (St.stStats s6) @?= baseline + 3
      s7 <- dropResult arr s6
      St.stLive (St.stStats s7) @?= baseline

  -- ------------------------------------------------------------------
  -- toList
  -- ------------------------------------------------------------------
  , testCase "toList: builds Cons list from array, N allocs (Cons cells), drop-to-baseline" $ do
      pToList <- lookupPrim (T.pack "toList")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1)  = St.allocPure (St.NCon (T.pack "Nil") []) s0
          (e1, s2)  = St.allocPure (St.NCon (T.pack "Nil") []) s1
          (arr, s3) = St.allocPure (St.NArray [St.RVBox e0, St.RVBox e1]) s2
          allocsBefore = St.stAllocs (St.stStats s3)
      (lst, s4) <- callPrim pToList [St.RVBox arr] s3
      -- arr freed (cascade: e0.rc 2->1, e1.rc 2->1); 2 Cons cells allocated;
      -- Nil is inline (0 alloc). Net: +2 alloc, live = baseline + 4 (e0,e1,cons0,cons1)
      St.stAllocs (St.stStats s4) - allocsBefore @?= 2
      St.stLive (St.stStats s4) @?= baseline + 4
      -- render to verify shape
      case St.renderRCValue s4 lst of
        Right t -> t @?= T.pack "[[], []]"
        Left e  -> assertFailure ("render failed: " <> show e)
      s5 <- dropResult lst s4
      St.stLive (St.stStats s5) @?= baseline

  , testCase "toList of empty array: returns [] (Nil inline), 0 alloc, drop-to-baseline" $ do
      pToList <- lookupPrim (T.pack "toList")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (arr, s1) = St.allocPure (St.NArray []) s0
          allocsBefore = St.stAllocs (St.stStats s1)
      (lst, s2) <- callPrim pToList [St.RVBox arr] s1
      -- arr freed (empty, no elements); Nil is inline (0 alloc); net 0
      St.stAllocs (St.stStats s2) @?= allocsBefore
      St.stLive (St.stStats s2) @?= baseline
      -- Nil inline: lst is RVBox (Inline _), rendering as []
      case St.renderRCValue s2 lst of
        Right t -> t @?= T.pack "[]"
        Left e  -> assertFailure ("render of empty list failed: " <> show e)
      -- No counted children in Nil, so dropResult is a no-op
      s3 <- dropResult lst s2
      St.stLive (St.stStats s3) @?= baseline

  -- ------------------------------------------------------------------
  -- Overflow regression (Finding 1): index >= 2^63 must raise PrimError
  --
  -- Before the asIndex/asIndexInt fix, a U64 index >= 2^63 was passed via
  -- fromInteger to Int, wrapping to a NEGATIVE Int (e.g. 2^63 -> minBound),
  -- which made the bounds check negative and index returned arr[0] instead
  -- of out-of-bounds, and set leaked its value. Now both sides reject with
  -- PrimError "Array: index out of range".
  -- ------------------------------------------------------------------
  , testCase "RC overflow: index 2^63 raises PrimError (out of range, not arr[0])" $ do
      pNew   <- lookupPrim (T.pack "new")
      pIndex <- lookupPrim (T.pack "index")
      let s0   = St.emptyStore
          nVal = St.RVLit (Anf.LInt 3)
          vVal = St.RVLit (Anf.LInt 0)
          iVal = St.RVLit (Anf.LInt (2^(63 :: Int)))
      (arr, s1) <- callPrim pNew [nVal, vVal] s0
      expectPrimError pIndex [arr, iVal] s1 "out of range"

  , testCase "RC overflow: new size 2^63 raises PrimError (out of range)" $ do
      pNew <- lookupPrim (T.pack "new")
      let s0   = St.emptyStore
          kVal = St.RVLit (Anf.LInt (2^(63 :: Int)))
          vVal = St.RVLit (Anf.LInt 0)
      expectPrimError pNew [kVal, vVal] s0 "out of range"

  , testCase "RC overflow: set index 2^63 raises PrimError (out of range, no value leak)" $ do
      pNew <- lookupPrim (T.pack "new")
      pSet <- lookupPrim (T.pack "set")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          nVal     = St.RVLit (Anf.LInt 3)
          vVal     = St.RVLit (Anf.LInt 0)
          iVal     = St.RVLit (Anf.LInt (2^(63 :: Int)))
          -- boxed v so we can detect a leak if the prim forgets to drop it
          (boxedV, s1) = St.allocPure (St.NCon (T.pack "Nil") []) s0
      (arr, s2) <- callPrim pNew [nVal, vVal] s1
      -- set with overflow index must error; arr and boxedV must not leak
      res <- runExceptT (St.rpFn pSet [arr, iVal, St.RVBox boxedV] s2)
      case res of
        Left (IV.PrimError m)
          | T.pack "out of range" `T.isInfixOf` m -> do
              -- arr and boxedV were not consumed; drop them to return to baseline
              s3 <- dropResult arr s2
              s4 <- dropResult (St.RVBox boxedV) s3
              St.stLive (St.stStats s4) @?= baseline
        Left e  -> assertFailure ("RC overflow set: expected PrimError out-of-range, got: " <> show e)
        Right _ -> assertFailure "RC overflow set: prim succeeded unexpectedly with 2^63 index"

  , testCase "RC overflow: resize size 2^63 raises PrimError (out of range)" $ do
      pNew    <- lookupPrim (T.pack "new")
      pResize <- lookupPrim (T.pack "resize")
      let s0   = St.emptyStore
          nVal = St.RVLit (Anf.LInt 2)
          mVal = St.RVLit (Anf.LInt (2^(63 :: Int)))
          vVal = St.RVLit (Anf.LInt 0)
      (arr, s1) <- callPrim pNew [nVal, vVal] s0
      expectPrimError pResize [arr, mVal, St.RVLit (Anf.LInt 0)] s1 "out of range"
  ]

-- ---------------------------------------------------------------------------
-- Suite H: Array QuickCheck properties (Slice A Task 5)
--
-- These properties pin the observable semantics of the seven array ops as
-- stated in spec §8 and exercise all three element-slot buckets:
--   * inline/uncounted  — RVLit (LInt n)   : U64 scalars
--   * immediate         — RVBox (Inline t)  : nullary constructors (e.g. ()
--                         interned as "Unit"; uncounted, no cascade child)
--   * boxed/counted     — RVBox (HAddr a)   : an NCon cell with a ref count
--
-- Every property:
--   (a) uses 'callPrim' so RC accounting is exercised (not bypassed);
--   (b) drops every live result before returning, asserting the heap returns
--       to baseline;
--   (c) never uses partial functions — 'atIndex' is the guarded helper.
--
-- Properties are driven by 'QC.ioProperty' (the prims live in IO via
-- 'runExceptT') and run 100 cases each (the default QuickCheck count).
-- ---------------------------------------------------------------------------

-- | Generate a small non-negative integer suitable as an array length or
-- index.  Kept small (0..7) so tests run fast and shrinking is meaningful.
genSmallNat :: QC.Gen Int
genSmallNat = choose (0, 7)

-- | Build an 'NArray' from a list of already-allocated 'RCValue's by calling
-- the 'fromList' prim.  The prim consumes the Cons/Nil list spine passed to it
-- and acquires its own ref to each element.  We construct the list using
-- 'allocPure' (so we have HAddr Cons cells) and pass the head to 'fromList'.
buildArrayFromElems :: [St.RCValue] -> St.Store -> IO (St.RCValue, St.Store)
buildArrayFromElems elems s0 = do
  pFromList <- lookupPrim (T.pack "fromList")
  -- Build Cons/Nil spine; Nil via runExceptT so it is an Inline immediate
  nilRes <- runExceptT (St.alloc (St.NCon (T.pack "Nil") []) s0)
  (nilAddr, sn) <- case nilRes of
    Right r -> pure r
    Left e  -> assertFailure ("buildArrayFromElems: nil alloc: " <> show e)
  let nilVal = St.RVBox nilAddr
      -- fold right over elems to build Cons chain (we own refs to elements
      -- already; fromList will incref each when it collects them, then
      -- dropValue xs will decrement via the spine cascade).
      buildSpine [] (lst, st) = pure (lst, st)
      buildSpine (v : vs) (tl, st) = do
        (rest, st1) <- buildSpine vs (tl, st)
        let (cellAddr, st2) = St.allocPure
                                (St.NCon (T.pack "Cons") [v, rest])
                                st1
        pure (St.RVBox cellAddr, st2)
  (xs, s1) <- buildSpine elems (nilVal, sn)
  callPrim pFromList [xs] s1

-- | Build two independent arrays from the SAME list of elements (each gets
-- its own copies via two separate 'buildArrayFromElems' calls so there is no
-- sharing between them).
buildTwoArrays :: [St.RCValue] -> St.Store
               -> IO (St.RCValue, St.RCValue, St.Store)
buildTwoArrays elems s0 = do
  -- Allocate two copies of each element for the second array, then build both.
  (arr1, s1) <- buildArrayFromElems elems s0
  -- The original element values in 'elems' were consumed by the first array
  -- (fromList incref's each element into the array, then dropValue xs
  -- decrements the list's refs -- since each element appears once in xs and
  -- once in the array, the net is the array holds rc=1 per element and the
  -- original HAddr/RVLit is still valid).
  -- For the second array we allocate fresh independent element values.
  (elems2, s2) <- allocFreshElems (length elems) s1
  (arr2, s3) <- buildArrayFromElems elems2 s2
  pure (arr1, arr2, s3)
  where
    allocFreshElems n s =
      let go 0 st acc = pure (acc, st)
          go k st acc = do
            let (a, st') = St.allocPure (St.NCon (T.pack "Nil") []) st
            go (k - 1) st' (St.RVBox a : acc)
      in go n s []

-- | Total element lookup at a list position (mirrors 'atIndex' in Prim.hs).
safeAt :: Int -> [a] -> Maybe a
safeAt i xs = case drop i xs of
  (x : _) -> Just x
  []       -> Nothing

-- | Drop every live 'RCValue' in a list back to store baseline.
dropAll :: [St.RCValue] -> St.Store -> IO St.Store
dropAll []       s = pure s
dropAll (v : vs) s = dropResult v s >>= dropAll vs

-- | Assert that two 'RCValue's are equal, with a counterexample label.
assertEqVal :: String -> St.RCValue -> St.RCValue -> IO ()
assertEqVal msg a b = assertEqual msg a b

-- -------------------------------------------------------------------------
-- Individual property implementations
-- -------------------------------------------------------------------------

-- P1: toList (fromList xs) == xs
-- Build an array from a random list of U64 elements, call toList, and compare
-- the resulting list value with the original element list element-by-element.
prop_arrayRoundtrip :: Property
prop_arrayRoundtrip =
  QC.forAll (QC.listOf (choose (0, 100) :: QC.Gen Integer)) $ \ns ->
    QC.ioProperty $ do
      pFromList <- lookupPrim (T.pack "fromList")
      pToList   <- lookupPrim (T.pack "toList")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          elems    = map (\n -> St.RVLit (Anf.LInt n)) ns
      -- Build a Cons/Nil spine and call fromList
      nilRes <- runExceptT (St.alloc (St.NCon (T.pack "Nil") []) s0)
      (nilAddr, sn) <- case nilRes of
        Right r -> pure r
        Left e  -> assertFailure ("P1 nil alloc: " <> show e)
      let nilVal = St.RVBox nilAddr
          buildSpine [] (lst, st) = pure (lst, st)
          buildSpine (v : vs) (tl, st) = do
            (rest, st1) <- buildSpine vs (tl, st)
            let (ca, st2) = St.allocPure (St.NCon (T.pack "Cons") [v, rest]) st1
            pure (St.RVBox ca, st2)
      (xs, s1) <- buildSpine elems (nilVal, sn)
      (arr, s2) <- callPrim pFromList [xs] s1
      -- Call length to get the expected count
      -- (arr is consumed by length, so we first need toList -- use index loop)
      -- Actually: call toList to get the list back
      (lst, s3) <- callPrim pToList [arr] s2
      -- Verify length via pLength on a fresh array built from the same list
      -- element-by-element indexing is complex; instead verify the list renders
      -- identically to what we built.  Build a fresh expected list to compare.
      -- We compare by extracting elements one at a time from the result list
      -- (call fromList again and then index) -- but the simplest correct check:
      -- fromList then toList is an identity on the VALUE rendering.
      -- Build reference list rendering from the original elements:
      let refRender = renderListOfInt ns
      case St.renderRCValue s3 lst of
        Left e  -> do
          _ <- dropResult lst s3
          assertFailure ("P1 render failed: " <> show e)
        Right got -> do
          s4 <- dropResult lst s3
          St.stLive (St.stStats s4) @?= baseline
          return (got == refRender)
  where
    renderListOfInt ns =
      T.pack ("[" <> go ns <> "]")
      where
        go []       = ""
        go [x]      = show x
        go (x : xs) = show x <> ", " <> go xs

-- P2: index (set a i v) i == v
-- For a non-empty array and a valid index i, setting slot i to v and then
-- indexing i yields v.
prop_arraySetIndex :: Property
prop_arraySetIndex =
  QC.forAll (QC.choose (1, 6) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, n - 1) :: QC.Gen Int) $ \i ->
  QC.forAll (QC.choose (0, 1000) :: QC.Gen Integer) $ \vn ->
    QC.ioProperty $ do
      pNew   <- lookupPrim (T.pack "new")
      pSet   <- lookupPrim (T.pack "set")
      pIndex <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          v        = St.RVLit (Anf.LInt vn)
          kVal     = St.RVLit (Anf.LInt (fromIntegral n))
          iVal     = St.RVLit (Anf.LInt (fromIntegral i))
      -- Build array of n zeros
      (arr0, s1) <- callPrim pNew [kVal, St.RVLit (Anf.LInt 0)] s0
      -- Set slot i to v
      (arr1, s2) <- callPrim pSet [arr0, iVal, v] s1
      -- Index slot i
      (el, s3) <- callPrim pIndex [arr1, iVal] s2
      let ok = el == St.RVLit (Anf.LInt vn)
      s4 <- dropResult el s3
      St.stLive (St.stStats s4) @?= baseline
      pure ok

-- P3: j /= i ==> index (set a i v) j == index a j
-- Setting slot i does not change slot j for j /= i.
prop_arraySetIndexOther :: Property
prop_arraySetIndexOther =
  QC.forAll (QC.choose (2, 6) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, n - 1) :: QC.Gen Int) $ \i ->
  QC.forAll
    (QC.suchThat (QC.choose (0, n - 1) :: QC.Gen Int) (/= i)) $ \j ->
  QC.forAll (QC.listOf1
    (QC.choose (1, 1000) :: QC.Gen Integer) `QC.suchThat` \xs -> length xs == n) $ \initVals ->
    QC.ioProperty $ do
      pSet      <- lookupPrim (T.pack "set")
      pIndex    <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          elems    = map (\x -> St.RVLit (Anf.LInt x)) initVals
          iVal     = St.RVLit (Anf.LInt (fromIntegral i))
          jVal     = St.RVLit (Anf.LInt (fromIntegral j))
          vVal     = St.RVLit (Anf.LInt 999)
      -- Build array 1 (for the set+index path)
      (arr1, s1) <- buildArrayFromElems elems s0
      -- Build array 2 (for the unmodified index path)
      (arr2, s2) <- buildArrayFromElems elems s1
      -- index arr2 at j (gives expected value)
      (expected, s3) <- callPrim pIndex [arr2, jVal] s2
      -- set arr1 at i, then index at j
      (arr1', s4) <- callPrim pSet [arr1, iVal, vVal] s3
      (got, s5) <- callPrim pIndex [arr1', jVal] s4
      let ok = got == expected
      s6 <- dropResult got s5
      s7 <- dropResult expected s6
      St.stLive (St.stStats s7) @?= baseline
      pure ok

-- P4: length (new k v) == k
prop_arrayLengthNew :: Property
prop_arrayLengthNew =
  QC.forAll genSmallNat $ \k ->
    QC.ioProperty $ do
      pNew    <- lookupPrim (T.pack "new")
      pLength <- lookupPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          kVal     = St.RVLit (Anf.LInt (fromIntegral k))
          vVal     = St.RVLit (Anf.LInt 0)
      (arr, s1)    <- callPrim pNew [kVal, vVal] s0
      (lenVal, s2) <- callPrim pLength [arr] s1
      St.stLive (St.stStats s2) @?= baseline
      return (lenVal == St.RVLit (Anf.LInt (fromIntegral k)))

-- P5: length (set a i v) == length a
prop_arrayLengthSet :: Property
prop_arrayLengthSet =
  QC.forAll (QC.choose (1, 6) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, n - 1) :: QC.Gen Int) $ \i ->
    QC.ioProperty $ do
      pNew    <- lookupPrim (T.pack "new")
      pSet    <- lookupPrim (T.pack "set")
      pLength <- lookupPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          kVal     = St.RVLit (Anf.LInt (fromIntegral n))
          iVal     = St.RVLit (Anf.LInt (fromIntegral i))
          vVal     = St.RVLit (Anf.LInt 99)
      -- Build two arrays of length n (one for each length call, since length
      -- consumes its argument).
      (arr1, s1) <- callPrim pNew [kVal, St.RVLit (Anf.LInt 0)] s0
      (arr2, s2) <- callPrim pNew [kVal, St.RVLit (Anf.LInt 0)] s1
      -- Get length of the original array
      (len1, s3) <- callPrim pLength [arr1] s2
      -- Set slot i on arr2, then get its length
      (arr2', s4) <- callPrim pSet [arr2, iVal, vVal] s3
      (len2, s5) <- callPrim pLength [arr2'] s4
      St.stLive (St.stStats s5) @?= baseline
      return (len1 == len2)

-- P6: length (resize a m f) == m
prop_arrayLengthResize :: Property
prop_arrayLengthResize =
  QC.forAll (QC.choose (0, 5) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, 7) :: QC.Gen Int) $ \m ->
    QC.ioProperty $ do
      pNew    <- lookupPrim (T.pack "new")
      pResize <- lookupPrim (T.pack "resize")
      pLength <- lookupPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          nVal     = St.RVLit (Anf.LInt (fromIntegral n))
          mVal     = St.RVLit (Anf.LInt (fromIntegral m))
          fillVal  = St.RVLit (Anf.LInt 0)
      (arr, s1)    <- callPrim pNew [nVal, fillVal] s0
      (arr', s2)   <- callPrim pResize [arr, mVal, fillVal] s1
      (lenVal, s3) <- callPrim pLength [arr'] s2
      St.stLive (St.stStats s3) @?= baseline
      return (lenVal == St.RVLit (Anf.LInt (fromIntegral m)))

-- P7a: growing (resize a m fill) and then indexing a new tail slot yields
--      fill.  Only applicable when m > n.
prop_arrayResizeGrowFill :: Property
prop_arrayResizeGrowFill =
  QC.forAll (QC.choose (0, 4) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (n + 1, n + 4) :: QC.Gen Int) $ \m ->
  QC.forAll (QC.choose (0, 999) :: QC.Gen Integer) $ \fillN ->
    QC.ioProperty $ do
      pNew    <- lookupPrim (T.pack "new")
      pResize <- lookupPrim (T.pack "resize")
      pIndex  <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          nVal     = St.RVLit (Anf.LInt (fromIntegral n))
          mVal     = St.RVLit (Anf.LInt (fromIntegral m))
          fillVal  = St.RVLit (Anf.LInt fillN)
          -- First new slot is at index n
          iVal     = St.RVLit (Anf.LInt (fromIntegral n))
      (arr0, s1) <- callPrim pNew [nVal, St.RVLit (Anf.LInt 0)] s0
      (arr1, s2) <- callPrim pResize [arr0, mVal, fillVal] s1
      (el, s3)   <- callPrim pIndex [arr1, iVal] s2
      let ok = el == St.RVLit (Anf.LInt fillN)
      s4 <- dropResult el s3
      St.stLive (St.stStats s4) @?= baseline
      pure ok

-- P7b: shrinking (resize a m fill) drops the tail; slots in [0, m) are
--      preserved.  Only applicable when m < n and m > 0.
prop_arrayResizeShrinkKeep :: Property
prop_arrayResizeShrinkKeep =
  QC.forAll (QC.choose (2, 6) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (1, n - 1) :: QC.Gen Int) $ \m ->
  QC.forAll (QC.choose (0, m - 1) :: QC.Gen Int) $ \i ->
  QC.forAll (QC.listOf1 (QC.choose (1, 999) :: QC.Gen Integer)
    `QC.suchThat` \xs -> length xs == n) $ \initVals ->
    QC.ioProperty $ do
      pResize   <- lookupPrim (T.pack "resize")
      pIndex    <- lookupPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          elems    = map (\x -> St.RVLit (Anf.LInt x)) initVals
          mVal     = St.RVLit (Anf.LInt (fromIntegral m))
          iVal     = St.RVLit (Anf.LInt (fromIntegral i))
          fillVal  = St.RVLit (Anf.LInt 0)
          -- Expected value at slot i in the original array
          expected = St.RVLit (Anf.LInt (initVals !! i))
      -- Build array from elems, then resize down to m
      (arr0, s1) <- buildArrayFromElems elems s0
      (arr1, s2) <- callPrim pResize [arr0, mVal, fillVal] s1
      (el, s3)   <- callPrim pIndex [arr1, iVal] s2
      let ok = el == expected
      s4 <- dropResult el s3
      St.stLive (St.stStats s4) @?= baseline
      pure ok

-- P8a: index out of bounds raises PrimError.
prop_arrayIndexOOB :: Property
prop_arrayIndexOOB =
  QC.forAll (QC.choose (0, 5) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (n, n + 4) :: QC.Gen Int) $ \i ->
    QC.ioProperty $ do
      pNew   <- lookupPrim (T.pack "new")
      pIndex <- lookupPrim (T.pack "index")
      let s0   = St.emptyStore
          nVal = St.RVLit (Anf.LInt (fromIntegral n))
          iVal = St.RVLit (Anf.LInt (fromIntegral i))
      (arr, s1) <- callPrim pNew [nVal, St.RVLit (Anf.LInt 0)] s0
      -- index i >= n should raise PrimError; the prim CONSUMES arr
      res <- runExceptT (St.rpFn pIndex [arr, iVal] s1)
      case res of
        Left (IV.PrimError m)
          | T.pack "out of bounds" `T.isInfixOf` m -> pure True
        Left e  -> do
          assertFailure ("P8a: expected PrimError out-of-bounds, got: " <> show e)
        Right (St.PRDone el, s2) -> do
          -- Unexpected success: clean up the returned element before failing.
          _ <- dropResult el s2
          assertFailure ("P8a: index " <> show i <> " on length-" <> show n
                           <> " array succeeded unexpectedly")
        Right _ -> assertFailure "P8a: got PRApply, expected PRDone or error"

-- P8b: set out of bounds raises PrimError.
prop_arraySetOOB :: Property
prop_arraySetOOB =
  QC.forAll (QC.choose (0, 5) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (n, n + 4) :: QC.Gen Int) $ \i ->
    QC.ioProperty $ do
      pNew <- lookupPrim (T.pack "new")
      pSet <- lookupPrim (T.pack "set")
      let s0   = St.emptyStore
          nVal = St.RVLit (Anf.LInt (fromIntegral n))
          iVal = St.RVLit (Anf.LInt (fromIntegral i))
          vVal = St.RVLit (Anf.LInt 42)
      (arr, s1) <- callPrim pNew [nVal, St.RVLit (Anf.LInt 0)] s0
      -- set i >= n should raise PrimError; the prim CONSUMES arr
      res <- runExceptT (St.rpFn pSet [arr, iVal, vVal] s1)
      case res of
        Left (IV.PrimError m)
          | T.pack "out of bounds" `T.isInfixOf` m -> pure True
        Left e  ->
          assertFailure ("P8b: expected PrimError out-of-bounds, got: " <> show e)
        Right (St.PRDone newArr, s2) -> do
          _ <- dropResult newArr s2
          assertFailure ("P8b: set " <> show i <> " on length-" <> show n
                           <> " array succeeded unexpectedly")
        Right _ -> assertFailure "P8b: got PRApply"

-- P9: boxed elements are reference-counted correctly.
-- Build an array of boxed (counted) NCon cells, call toList, then drop.
-- The heap must return to baseline: every counted element is freed exactly once.
prop_arrayBoxedRCBalance :: Property
prop_arrayBoxedRCBalance =
  QC.forAll (QC.choose (0, 4) :: QC.Gen Int) $ \n ->
    QC.ioProperty $ do
      pToList <- lookupPrim (T.pack "toList")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          -- Allocate n boxed cells (HAddr NCon "Nil" []) as elements.
          allocN k st =
            let go 0 s acc = pure (acc, s)
                go r s acc =
                  let (a, s') = St.allocPure (St.NCon (T.pack "Nil") []) s
                  in go (r - 1) s' (St.RVBox a : acc)
            in go k st []
      (elems, s1) <- allocN n s0
      -- Build array directly (bypass fromList for isolation: use allocPure)
      let (arrAddr, s2) = St.allocPure (St.NArray elems) s1
          arrVal = St.RVBox arrAddr
          -- After allocPure, each element has rc=1 (owned by the array).
          -- toList dup-increfs each element into a Cons cell, then dropAddr arr
          -- decrements each.  Net: each element rc goes 1 -> 2 -> 1.
          -- +n alloc (Cons cells); array freed; elements survive in list.
      (lst, s3) <- callPrim pToList [arrVal] s2
      s4 <- dropResult lst s3
      -- All elements freed; heap back to baseline.
      pure (St.stLive (St.stStats s4) == baseline)

-- P10: set with boxed elements: RC accounting correct (drop-to-baseline).
-- Build an array of boxed NCon cells, set one slot to a fresh boxed element,
-- then drop the result. The replaced element must be freed (cascade from the
-- old array drop) and survivors must be exactly refcounted.
prop_arraySetBoxed :: Property
prop_arraySetBoxed =
  QC.forAll (QC.choose (1, 4) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, n - 1) :: QC.Gen Int) $ \i ->
    QC.ioProperty $ do
      pSet <- lookupPrim (T.pack "set")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      -- Allocate n boxed elements (HAddr NCon "Nil" [])
      let allocBoxed k st =
            let go 0 s acc = pure (acc, s)
                go r s acc =
                  let (a, s') = St.allocPure (St.NCon (T.pack "Nil") []) s
                  in go (r - 1) s' (St.RVBox a : acc)
            in go k st []
      (elems, s1) <- allocBoxed n s0
      -- Allocate fresh replacement element
      let (newElemAddr, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          newElem = St.RVBox newElemAddr
      -- Build array directly (rc=1 per element, owned by array)
      let (arrAddr, s3) = St.allocPure (St.NArray elems) s2
          iVal = St.RVLit (Anf.LInt (fromIntegral i))
      -- Call set: old arr consumed, new arr produced with slot i replaced
      (newArr, s4) <- callPrim pSet [St.RVBox arrAddr, iVal, newElem] s3
      s5 <- dropResult newArr s4
      -- All elements freed, heap at baseline
      pure (St.stLive (St.stStats s5) == baseline)

-- P11: resize with boxed elements: drop-to-baseline for both grow and shrink.
-- Exercises that truncated tail elements are freed and fill elements are
-- correctly incref'd for growth -- the key accounting path for boxed elements.
prop_arrayResizeBoxed :: Property
prop_arrayResizeBoxed =
  QC.forAll (QC.choose (0, 4) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.choose (0, 6) :: QC.Gen Int) $ \m ->
    QC.ioProperty $ do
      pResize <- lookupPrim (T.pack "resize")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      -- Allocate n boxed elements
      let allocBoxed k st =
            let go 0 s acc = pure (acc, s)
                go r s acc =
                  let (a, s') = St.allocPure (St.NCon (T.pack "Nil") []) s
                  in go (r - 1) s' (St.RVBox a : acc)
            in go k st []
      (elems, s1) <- allocBoxed n s0
      -- Allocate a boxed fill element
      let (fillAddr, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          fillVal = St.RVBox fillAddr
          mVal    = St.RVLit (Anf.LInt (fromIntegral m))
      -- Build array directly
      let (arrAddr, s3) = St.allocPure (St.NArray elems) s2
      (newArr, s4) <- callPrim pResize [St.RVBox arrAddr, mVal, fillVal] s3
      s5 <- dropResult newArr s4
      pure (St.stLive (St.stStats s5) == baseline)

-- P12: resize to 0 with boxed elements: full truncation drops all N elements.
-- This boundary (m=0) was excluded from P7b's generator (m >= 1). All N boxed
-- elements must be freed; result is an empty array; stLive returns to baseline.
prop_arrayResizeToZeroBoxed :: Property
prop_arrayResizeToZeroBoxed =
  QC.forAll (QC.choose (0, 5) :: QC.Gen Int) $ \n ->
    QC.ioProperty $ do
      pResize <- lookupPrim (T.pack "resize")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      -- Allocate n boxed elements
      let allocBoxed k st =
            let go 0 s acc = pure (acc, s)
                go r s acc =
                  let (a, s') = St.allocPure (St.NCon (T.pack "Nil") []) s
                  in go (r - 1) s' (St.RVBox a : acc)
            in go k st []
      (elems, s1) <- allocBoxed n s0
      -- Boxed fill element (will be dropped because k=0 when m=0)
      let (fillAddr, s2) = St.allocPure (St.NCon (T.pack "Nil") []) s1
          fillVal = St.RVBox fillAddr
          mVal    = St.RVLit (Anf.LInt 0)
      let (arrAddr, s3) = St.allocPure (St.NArray elems) s2
      (newArr, s4) <- callPrim pResize [St.RVBox arrAddr, mVal, fillVal] s3
      -- newArr must be an empty array
      elems' <- case St.renderRCValue s4 newArr of
        Right t -> pure t
        Left e  -> assertFailure ("P12 render failed: " <> show e)
      s5 <- dropResult newArr s4
      -- All elements freed, heap back to baseline
      pure (St.stLive (St.stStats s5) == baseline && elems' == T.pack "[]")

-- P13: fromList with boxed elements: RC accounting correct (drop-to-baseline).
-- Exercises that fromList correctly incref's boxed elements into the array and
-- the list spine is consumed without double-free.
prop_arrayFromListBoxed :: Property
prop_arrayFromListBoxed =
  QC.forAll (QC.choose (0, 4) :: QC.Gen Int) $ \n ->
    QC.ioProperty $ do
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      -- Allocate n boxed elements
      let allocBoxed k st =
            let go 0 s acc = pure (acc, s)
                go r s acc =
                  let (a, s') = St.allocPure (St.NCon (T.pack "Nil") []) s
                  in go (r - 1) s' (St.RVBox a : acc)
            in go k st []
      (elems, s1) <- allocBoxed n s0
      -- Build array via fromList (exercises the incref path for boxed elements)
      (arr, s2) <- buildArrayFromElems elems s1
      s3 <- dropResult arr s2
      pure (St.stLive (St.stStats s3) == baseline)

-- -------------------------------------------------------------------------
-- Wok.IR.Region  (R+escape routing annotation, Region Slice R1)
-- -------------------------------------------------------------------------
--
-- The routing pass tags each Let-bound allocation Arena | Heap under three
-- fences (non-escape §5.1, mutation §5.2, continuation §5.3) reusing
-- Wok.IR.Escape; these unit tests pin the Arena|Heap verdict against a
-- hand-computed escape verdict on the four shapes from the spec (§9), plus a
-- fifth shape documenting the §5.1 side-condition (an extracted boxed child that
-- escapes is independently Heap, so its parent stays Arena-safe).

-- Helpers (high Uniques to avoid collision with any other hand-built module).
regNm :: T.Text -> Int -> Name
regNm h u = Name h (Unique u)

regBnd :: T.Text -> Int -> Ty.CType -> Anf.Binder
regBnd h u t = Anf.Binder (regNm h u) Anf.Unrestricted t

regU64 :: Ty.CType
regU64 = Ty.CTCon Ty.TcU64 []

-- A boxed user type (so a binder of this type is reference-counted / routable).
regBoxTy :: Ty.CType
regBoxTy = Ty.CTCon (Ty.TcUser (T.pack "Box")) []

-- A boxed pair type (TcTuple 2 is boxed per isBoxedType).
regPairTy :: Ty.CType
regPairTy = Ty.CTCon (Ty.TcTuple 2) [regU64, regU64]

regArrayTy :: Ty.CType
regArrayTy = Ty.CTCon Ty.TcArray [regU64]

-- | Placement of a binder Unique in a single-function module, or Nothing if the
-- binder carries no placement entry (it is not an allocation site).
regPlacementOf :: Int -> Anf.CoreModule -> Maybe Region.Placement
regPlacementOf u cm = Map.lookup (Unique u) (Region.rpPlacement (Region.planRegions cm))

regArenaBodies :: Anf.CoreModule -> Set.Set Unique
regArenaBodies = Region.rpArenaBodies . Region.planRegions

regModule :: Anf.TopBind -> Anf.CoreModule
regModule tb = Anf.CoreModule [tb]

-- Shape 1: non-escaping scratch.
--   f x = let p = Pair x x      -- p :: (U64, U64), boxed, never flows out
--         case p of Pair a b -> let r = a + b in r
-- p is matched in place and consumed; the Pair binder -> Arena, f in rpArenaBodies.
regShape1 :: Anf.CoreModule
regShape1 = regModule $ Anf.TopBind (regNm "f" 7000) [regBnd "x" 7001 regU64]
  (Anf.Let (regBnd "p" 7002 regPairTy)
     (Anf.RCon (T.pack "Pair") [Anf.AVar (regNm "x" 7001), Anf.AVar (regNm "x" 7001)])
  (Anf.Case (Anf.AVar (regNm "p" 7002))
     [ Anf.AltCon (T.pack "Pair") [regBnd "a" 7003 regU64, regBnd "b" 7004 regU64]
         (Anf.Let (regBnd "r" 7005 regU64)
            (Anf.RApp (Anf.APrim (T.pack "Base", T.pack "+"))
               [Anf.AVar (regNm "a" 7003), Anf.AVar (regNm "b" 7004)])
            (Anf.Ret (Anf.AVar (regNm "r" 7005)))) ]))

-- Shape 2: return-escape.
--   g x = let p = Pair x x
--         p                    -- p IS the return value -> escapes
-- The Pair binder -> Heap, g NOT in rpArenaBodies.
regShape2 :: Anf.CoreModule
regShape2 = regModule $ Anf.TopBind (regNm "g" 7100) [regBnd "x" 7101 regU64]
  (Anf.Let (regBnd "p" 7102 regPairTy)
     (Anf.RCon (T.pack "Pair") [Anf.AVar (regNm "x" 7101), Anf.AVar (regNm "x" 7101)])
  (Anf.Ret (Anf.AVar (regNm "p" 7102))))

-- Shape 3: array (mutation fence §5.2).
--   h n v = let arr = Array.new n v   -- arr :: Array U64
--           let len = Array.length arr
--           len
-- Even though arr does not escape, the array binder -> Heap (arrays stay counted).
regShape3 :: Anf.CoreModule
regShape3 = regModule $ Anf.TopBind (regNm "h" 7200)
  [regBnd "n" 7201 regU64, regBnd "v" 7202 regU64]
  (Anf.Let (regBnd "arr" 7203 regArrayTy)
     (Anf.RApp (Anf.APrim (PN.arrayModule, PN.arrayNewName))
        [Anf.AVar (regNm "n" 7201), Anf.AVar (regNm "v" 7202)])
  (Anf.Let (regBnd "len" 7204 regU64)
     (Anf.RApp (Anf.APrim (PN.arrayModule, PN.arrayLengthName))
        [Anf.AVar (regNm "arr" 7203)])
  (Anf.Ret (Anf.AVar (regNm "len" 7204)))))

-- Shape 4: continuation-capturing body (§5.3 fence).
--   k () = with { return v -> v ; E.op(r) -> let kk = r in let q = Pair r r in kk }
--          (Ret 0)
-- The op-arm binds resume r and uses it NON-tail (aliased to kk, then returned),
-- so m2bResumeEscapes fires -> the whole body falls back to Heap. The Pair alloc
-- q inside the arm is forced Heap by the whole-body gate.
regShape4 :: Anf.CoreModule
regShape4 = regModule $ Anf.TopBind (regNm "k" 7300) []
  (Anf.Handle (Anf.Ret (Anf.ALit (Anf.LInt 0)))
     (Anf.Handler
        (regBnd "v" 7301 regU64, Anf.Ret (Anf.AVar (regNm "v" 7301)))
        [ Anf.OpArm (T.pack "E") (T.pack "op")
            [regBnd "arg" 7302 regU64]
            (regBnd "r" 7303 regU64)         -- the resume binder
            (Anf.Let (regBnd "kk" 7304 regU64)
               (Anf.RAtom (Anf.AVar (regNm "r" 7303)))   -- alias-rename of resume = escape
            (Anf.Let (regBnd "q" 7305 regPairTy)
               (Anf.RCon (T.pack "Pair")
                  [Anf.AVar (regNm "arg" 7302), Anf.AVar (regNm "arg" 7302)])
            (Anf.Ret (Anf.AVar (regNm "kk" 7304))))) ]
        Nothing Nothing Nothing))

-- Shape 5: extract + return a boxed child (the §5.1 side-condition).
--   m y = let x = Box ()         -- the child allocation, boxed
--         let p = Pair x y       -- x is STORED into p (a con field = escaping)
--         case p of Pair a b -> a   -- p matched in place, child a returned
-- p -> Arena (only the scrutinee names it, not an escape); x -> Heap (it flowed
-- into the Pair). This documents that extracting+returning a child is safe with
-- p in the arena: the child is independently counted.
regShape5 :: Anf.CoreModule
regShape5 = regModule $ Anf.TopBind (regNm "m" 7400) [regBnd "y" 7401 regBoxTy]
  (Anf.Let (regBnd "x" 7402 regBoxTy)
     (Anf.RCon (T.pack "Box") [])
  (Anf.Let (regBnd "p" 7403 (Ty.CTCon (Ty.TcTuple 2) [regBoxTy, regBoxTy]))
     (Anf.RCon (T.pack "Pair") [Anf.AVar (regNm "x" 7402), Anf.AVar (regNm "y" 7401)])
  (Anf.Case (Anf.AVar (regNm "p" 7403))
     [ Anf.AltCon (T.pack "Pair") [regBnd "a" 7404 regBoxTy, regBnd "b" 7405 regBoxTy]
         (Anf.Ret (Anf.AVar (regNm "a" 7404))) ])))

-- Shape 6: alias-then-escape (pins aliasEscapeStep's alias-chain tracking).
--   n a b = let p = Pair a b    -- p :: (Box, Box), boxed
--           let q = p           -- pure alias-rename of p (followed, not an escape)
--           let r = sink(q)     -- q passed as a CONSUMING arg -> escapes
--           r
-- The escape flows through the q-alias, so arenaEscapes {p} must catch it via the
-- followed rename: p -> Heap, n opens no arena.
regShape6 :: Anf.CoreModule
regShape6 = regModule $ Anf.TopBind (regNm "n" 7500)
  [regBnd "a" 7501 regBoxTy, regBnd "b" 7502 regBoxTy]
  (Anf.Let (regBnd "p" 7503 (Ty.CTCon (Ty.TcTuple 2) [regBoxTy, regBoxTy]))
     (Anf.RCon (T.pack "Pair") [Anf.AVar (regNm "a" 7501), Anf.AVar (regNm "b" 7502)])
  (Anf.Let (regBnd "q" 7504 (Ty.CTCon (Ty.TcTuple 2) [regBoxTy, regBoxTy]))
     (Anf.RAtom (Anf.AVar (regNm "p" 7503)))               -- q = p  (alias)
  (Anf.Let (regBnd "r" 7505 regBoxTy)
     (Anf.RApp (Anf.APrim (T.pack "Main", T.pack "sink"))
        [Anf.AVar (regNm "q" 7504)])                       -- sink(q): q escapes
  (Anf.Ret (Anf.AVar (regNm "r" 7505))))))

-- Shape 7: LetRec member captures a boxed local PURELY AS A CALL HEAD, and the
-- member escapes (REGRESSION for the reachable UAF the capstone review found).
--   run k = let p = \y -> y + k       -- p :: boxed closure, arena candidate
--           letrec f x = p x          -- f captures p, used ONLY as the call HEAD
--           f                         -- f is RETURNED -> escapes; its shared NEnv
--                                     -- still holds p after run returns
-- The bug: aliasEscapeStep's escapingAtomsRhs (RApp _ as) EXEMPTS the head, so a
-- head-only capture was invisible and p was mis-tagged Arena -> run's arena close
-- bulk-freed p while the escaped env still pointed at it (use-after-free). The fix
-- tests raw freeVarsExpr membership over member bodies, so a head-only capture
-- escapes too: p -> Heap, run opens no arena.
regShape7 :: Anf.CoreModule
regShape7 = regModule $ Anf.TopBind (regNm "run" 7600) [regBnd "k" 7601 regU64]
  (Anf.Let (regBnd "p" 7602 regBoxTy)
     (Anf.RLam [regBnd "y" 7603 regU64]
        (Anf.Let (regBnd "s" 7604 regU64)
           (Anf.RApp (Anf.APrim (T.pack "Base", T.pack "+"))
              [Anf.AVar (regNm "y" 7603), Anf.AVar (regNm "k" 7601)])
           (Anf.Ret (Anf.AVar (regNm "s" 7604)))))
  (Anf.LetRec
     [ (regBnd "f" 7605 regBoxTy, [regBnd "x" 7606 regU64]
       , Anf.Let (regBnd "fr" 7607 regU64)
           (Anf.RApp (Anf.AVar (regNm "p" 7602)) [Anf.AVar (regNm "x" 7606)])  -- p as HEAD
           (Anf.Ret (Anf.AVar (regNm "fr" 7607)))) ]
     (Anf.Ret (Anf.AVar (regNm "f" 7605)))))                                   -- f escapes

regionRoutingTests :: TestTree
regionRoutingTests = testGroup "Region routing"
  [ testCase "shape 1 (non-escaping scratch): Pair -> Arena, f opens an arena" $ do
      regPlacementOf 7002 regShape1 @?= Just Arena
      Set.member (Unique 7000) (regArenaBodies regShape1) @?= True

  , testCase "shape 2 (return-escape): Pair -> Heap, g opens no arena" $ do
      regPlacementOf 7102 regShape2 @?= Just Heap
      Set.member (Unique 7100) (regArenaBodies regShape2) @?= False

  , testCase "shape 3 (array, mutation fence): array binder -> Heap, h opens no arena" $ do
      regPlacementOf 7203 regShape3 @?= Just Heap
      Set.member (Unique 7200) (regArenaBodies regShape3) @?= False

  , testCase "shape 4 (continuation-capturing): every allocation -> Heap, no arena" $ do
      -- The Pair built inside the capturing arm is forced Heap by the whole-body gate.
      regPlacementOf 7305 regShape4 @?= Just Heap
      regArenaBodies regShape4 @?= Set.empty

  , testCase "shape 5 (extract+return boxed child): Pair -> Arena, child -> Heap" $ do
      -- p is only matched in place (scrutinee, not an escape) -> Arena.
      regPlacementOf 7403 regShape5 @?= Just Arena
      -- x flowed INTO the Pair (a con field = escaping) -> independently Heap.
      regPlacementOf 7402 regShape5 @?= Just Heap
      Set.member (Unique 7400) (regArenaBodies regShape5) @?= True

  , testCase "shape 6 (alias-then-escape): Pair -> Heap via the alias chain" $ do
      -- p is aliased to q, then q escapes as a consuming arg: arenaEscapes follows
      -- the rename and catches the escape -> p is Heap, n opens no arena.
      regPlacementOf 7503 regShape6 @?= Just Heap
      Set.member (Unique 7500) (regArenaBodies regShape6) @?= False

  , testCase "shape 7 (LetRec head-capture-escape): closure -> Heap, run opens no arena" $ do
      -- REGRESSION (capstone review UAF): p is captured by member f purely as a
      -- CALL HEAD and f escapes (returned), so p's shared NEnv outlives run. The
      -- arenaEscapes LetRec fence must catch a head-only capture -> p is Heap and
      -- run opens no arena (else run's arena close frees p under the escaped env).
      regPlacementOf 7602 regShape7 @?= Just Heap
      Set.member (Unique 7600) (regArenaBodies regShape7) @?= False

  , testCase "planRegions is idempotent (pure, heap-independent)" $
      Region.planRegions regShape1 @?= Region.planRegions regShape1
  ]

-- ---------------------------------------------------------------------------
-- Wok.IR.Region  (SliceRep borrow routing, String Slice E4 Task 4)
-- ---------------------------------------------------------------------------
--
-- The L5 borrow-passing router tags each slice/byteSlice VIEW binder
-- Window | Counted | Copy by reusing the SAME per-binder escape analysis that
-- routes Arena | Heap (a new consumer of Wok.IR.Escape.arenaEscapes, spec §6).
-- These tests pin the planner's per-site verdict, and AC3 asserts an INDEPENDENT
-- routing oracle (a second, separately-written re-derivation) matches the planner
-- EXACTLY over a corpus (mismatch == 0), so a routing bug surfaces as a mismatch.
--
-- D1/§6 soundness direction (mirrors Placement): Counted/Copy are the ALWAYS-SAFE
-- answers (like Heap); Window is the only routing that licenses dropping the
-- refcount at codegen, so it is emitted ONLY when the view is proven non-escaping
-- AND the parent is referenceable AND the body is in the arena soundness envelope.
-- The interpreter realizes Window and Counted identically (always counts, D2), so a
-- mis-route is never a runtime UAF; this annotation is consumed by codegen / Task 5.

-- A slice prim application RHS: slice/byteSlice over a parent atom + two index args.
sliceRhs :: Anf.Atom -> Anf.Rhs
sliceRhs parent =
  Anf.RApp (Anf.APrim (PN.stringModule, PN.stringSliceName))
    [parent, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 5)]

byteSliceRhs :: Anf.Atom -> Anf.Rhs
byteSliceRhs parent =
  Anf.RApp (Anf.APrim (PN.stringModule, PN.stringByteSliceName))
    [parent, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 5)]

regStrTy :: Ty.CType
regStrTy = Ty.CTCon Ty.TcString []

-- The 'SliceRep' the planner assigns a view binder 'Unique', or Nothing if the
-- binder carries no slice-rep entry (it is not a slice site).
sliceRepOf :: Int -> Anf.CoreModule -> Maybe SliceRep
sliceRepOf u cm = Map.lookup (Unique u) (Region.rpSliceRep (Region.planRegions cm))

-- Slice shape 1 (Window): a NON-escaping slice of a referenceable (heap, param)
-- parent.  f s = let v = slice s 0 5 in case v of _ -> 0
-- v is only a Case scrutinee (matched in place = NOT an escape, the §5.1
-- relaxation); s is a function param (not locally Arena-placed). So
-- not escapes && not parentArena -> Window.
sliceShapeWindow :: Anf.CoreModule
sliceShapeWindow = regModule $ Anf.TopBind (regNm "f" 8000) [regBnd "s" 8001 regStrTy]
  (Anf.Let (regBnd "v" 8002 regStrTy) (sliceRhs (Anf.AVar (regNm "s" 8001)))
  (Anf.Case (Anf.AVar (regNm "v" 8002))
     [ Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 0))) ]))

-- Slice shape 2 (Counted via escape): the slice is RETURNED (escapes); the parent
-- is a referenceable param.  g s = let v = slice s 0 5 in v
-- escapes && not parentArena -> Counted.
sliceShapeCounted :: Anf.CoreModule
sliceShapeCounted = regModule $ Anf.TopBind (regNm "g" 8100) [regBnd "s" 8101 regStrTy]
  (Anf.Let (regBnd "v" 8102 regStrTy) (sliceRhs (Anf.AVar (regNm "s" 8101)))
  (Anf.Ret (Anf.AVar (regNm "v" 8102))))

-- Slice shape 3 (Counted via the module-wide handler disable, AC5): a body whose
-- slice WOULD be Window, but a SIBLING top-level installs a handler, so arenas are
-- disabled module-wide and every slice routes the always-safe Counted (no Window,
-- no Copy -- there is no arena).
--   h s   = let v = byteSlice s 0 5 in case v of _ -> 0   (would be Window)
--   hdlr  = with { return r -> r } (Ret 0)                (forces the disable)
sliceShapeHandlerDisabled :: Anf.CoreModule
sliceShapeHandlerDisabled = Anf.CoreModule
  [ Anf.TopBind (regNm "h" 8200) [regBnd "s" 8201 regStrTy]
      (Anf.Let (regBnd "v" 8202 regStrTy) (byteSliceRhs (Anf.AVar (regNm "s" 8201)))
      (Anf.Case (Anf.AVar (regNm "v" 8202))
         [ Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 0))) ]))
  , Anf.TopBind (regNm "hdlr" 8210) []
      (Anf.Handle (Anf.Ret (Anf.ALit (Anf.LInt 0)))
         (Anf.Handler
            (regBnd "r" 8211 regU64, Anf.Ret (Anf.AVar (regNm "r" 8211)))
            [] Nothing Nothing Nothing))
  ]

-- Slice shape 4 (Counted via the per-body continuation fence): the body fires a
-- FREE effect op (an ROp), so capturesContinuation gates the whole body to Heap and
-- opens no arena; the slice in that body routes the always-safe Counted (it would
-- be Window otherwise).  k s = let _ = E.op () in let v = slice s 0 5 in (case v of _ -> 0)
sliceShapeContFenced :: Anf.CoreModule
sliceShapeContFenced = regModule $ Anf.TopBind (regNm "k" 8300) [regBnd "s" 8301 regStrTy]
  (Anf.Let (regBnd "o" 8302 regU64)
     (Anf.ROp Nothing (T.pack "E") (T.pack "op") [])
  (Anf.Let (regBnd "v" 8303 regStrTy) (sliceRhs (Anf.AVar (regNm "s" 8301)))
  (Anf.Case (Anf.AVar (regNm "v" 8303))
     [ Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 0))) ])))

-- Slice shape 5 (Counted; a RESUMING handler arm + a slice, NO ROp). The body is a
-- Handle whose op-arm RESUMES (its resume binder escapes the arm: aliased to kk and
-- returned -> m2bResumeEscapes fires). The handled expr contains a slice that would
-- otherwise be Window. The planner routes the slice Counted via the module-wide
-- handler disable (a Handle in the module forces all-Counted); 'capturesContinuation's
-- goHandler ALSO fires on the resume-escape, and so must the oracle's 'oracleFiresOp'
-- (FIX 1a) -- they must AGREE (mismatch == 0). This is the resuming-handler shape
-- Task 5's death-tests use; it pins the m2bResumeEscapes mirror in the oracle.
--   r5 s = with { return rv -> rv
--               ; E.op(arg) -> let kk = resume in (case (slice s 0 5) of _ -> kk) }
--          (let v = slice s 0 5 in case v of _ -> 0)
sliceShapeResumingHandler :: Anf.CoreModule
sliceShapeResumingHandler =
  regModule $ Anf.TopBind (regNm "r5" 8500) [regBnd "s" 8501 regStrTy]
    (Anf.Handle
       (Anf.Let (regBnd "v" 8502 regStrTy) (sliceRhs (Anf.AVar (regNm "s" 8501)))
       (Anf.Case (Anf.AVar (regNm "v" 8502))
          [ Anf.AltDefault (Anf.Ret (Anf.ALit (Anf.LInt 0))) ]))
       (Anf.Handler
          (regBnd "rv" 8503 regU64, Anf.Ret (Anf.AVar (regNm "rv" 8503)))
          [ Anf.OpArm (T.pack "E") (T.pack "op")
              [regBnd "arg" 8504 regU64]
              (regBnd "resume" 8505 regU64)        -- the resume binder
              (Anf.Let (regBnd "kk" 8506 regU64)
                 (Anf.RAtom (Anf.AVar (regNm "resume" 8505)))  -- alias-rename = escape
              (Anf.Let (regBnd "vw" 8507 regStrTy) (sliceRhs (Anf.AVar (regNm "s" 8501)))
              (Anf.Case (Anf.AVar (regNm "vw" 8507))
                 [ Anf.AltDefault (Anf.Ret (Anf.AVar (regNm "kk" 8506))) ]))) ]
          Nothing Nothing Nothing))

-- The corpus the independent oracle (AC3) checks against the planner.
sliceCorpus :: [(String, Anf.CoreModule)]
sliceCorpus =
  [ ("window",            sliceShapeWindow)
  , ("counted-escape",    sliceShapeCounted)
  , ("handler-disable",   sliceShapeHandlerDisabled)
  , ("cont-fenced",       sliceShapeContFenced)
  , ("resuming-handler",  sliceShapeResumingHandler)
  ]

-- | The INDEPENDENT routing oracle (AC3). A SECOND, separately-written derivation
-- of the expected 'SliceRep' for every slice binder in a module, written WITHOUT
-- reference to 'Region.rpSliceRep'. It re-derives the three decision inputs:
--   * @disabled@: the module installs a handler (module-wide arena disable) OR the
--     slice's enclosing top-body fires a free effect op (continuation fence). Both
--     re-derived here by a fresh walk, not borrowed from Region.
--   * @escapes@:  Wok.IR.Escape.arenaEscapes over the slice's continuation (the
--     shared analysis -- the oracle is independent in the DECISION, not in the
--     escape primitive Region itself reuses).
--   * @parentArena@: the slice's parent atom names a binder the planner placed in
--     Arena (a lookup in the public 'rpPlacement', a separate validated artifact).
-- When @disabled@ the rep is Counted; else Window iff not escapes && not parentArena,
-- Copy iff escapes && parentArena, otherwise Counted.
oracleSliceReps :: Anf.CoreModule -> Map.Map Unique SliceRep
oracleSliceReps cm@(Anf.CoreModule binds) =
  let moduleHasHandler = any (oracleHasHandle . topBody) binds
      placements       = Region.rpPlacement (Region.planRegions cm)
  in Map.unions [ oracleTop moduleHasHandler placements (topBody b) | b <- binds ]
  where
    topBody (Anf.TopBind _ _ body) = body
    oracleTop moduleHasHandler placements body =
      let disabled = moduleHasHandler || oracleFiresOp body
      in oracleWalk disabled placements body

-- | Re-derive a slice binder's rep for one body, recursing through every Expr form
-- (mirrors collectSliceReps, written independently).
oracleWalk :: Bool -> Map.Map Unique Region.Placement -> Anf.Expr -> Map.Map Unique SliceRep
oracleWalk disabled placements = go
  where
    go (Anf.Ret _)            = Map.empty
    go (Anf.Let bd r e)       =
      let here = case oracleSliceParent r of
                   Just parent -> Map.singleton (Anf.binderUnique bd)
                                    (oracleRep disabled placements bd parent e)
                   Nothing     -> Map.empty
      in here `Map.union` goRhs r `Map.union` go e
    go (Anf.LetRec defs e)    = Map.unions (go e : [ go d | (_, _, d) <- defs ])
    go (Anf.Case _ alts)      = Map.unions (map goAlt alts)
    go (Anf.LetJoin _ _ jb e) = go jb `Map.union` go e
    go (Anf.Jump _ _)         = Map.empty
    go (Anf.Handle e h)       =
      go e `Map.union` go (snd (Anf.hReturn h))
        `Map.union` Map.unions (map (go . Anf.oaBody) (Anf.hOps h))
    go (Anf.InstallHandler _ _ e) = go e
    goAlt (Anf.AltCon _ _ e)  = go e
    goAlt (Anf.AltLit _ e)    = go e
    goAlt (Anf.AltDefault e)  = go e
    goRhs (Anf.RLam _ e)      = go e
    goRhs _                   = Map.empty

-- | The independent rep decision for one slice binder.
oracleRep
  :: Bool -> Map.Map Unique Region.Placement
  -> Anf.Binder -> Anf.Atom -> Anf.Expr -> SliceRep
oracleRep disabled placements bd parent cont
  | disabled                       = Counted
  | not escapes && not parentArena = Window
  | escapes && parentArena         = Copy
  | otherwise                      = Counted
  where
    escapes     = Esc.arenaEscapes (Set.singleton (Anf.binderUnique bd)) cont
    parentArena = case parent of
      Anf.AVar n -> Map.lookup (Name.nameUniq n) placements == Just Arena
      _          -> False

-- | The parent atom of a slice/byteSlice application, else Nothing (oracle copy of
-- 'sliceParent', written independently).
oracleSliceParent :: Anf.Rhs -> Maybe Anf.Atom
oracleSliceParent (Anf.RApp (Anf.APrim key) (parent : _))
  | key == (PN.stringModule, PN.stringSliceName)     = Just parent
  | key == (PN.stringModule, PN.stringByteSliceName) = Just parent
oracleSliceParent _ = Nothing

-- | True iff a Handle appears anywhere in the expression (oracle re-derivation of
-- the module-wide handler disable signal).
oracleHasHandle :: Anf.Expr -> Bool
oracleHasHandle = go
  where
    go (Anf.Ret _)            = False
    go (Anf.Let _ r e)        = goRhs r || go e
    go (Anf.LetRec defs e)    = any (\(_, _, d) -> go d) defs || go e
    go (Anf.Case _ alts)      = any goAlt alts
    go (Anf.LetJoin _ _ jb e) = go jb || go e
    go (Anf.Jump _ _)         = False
    go (Anf.Handle _ _)       = True
    go (Anf.InstallHandler _ _ _) = True
    goAlt (Anf.AltCon _ _ e)  = go e
    goAlt (Anf.AltLit _ e)    = go e
    goAlt (Anf.AltDefault e)  = go e
    goRhs (Anf.RLam _ e)      = go e
    goRhs _                   = False

-- | True iff the body's continuation can be captured (oracle re-derivation of the
-- per-body continuation fence, mirroring 'capturesContinuation' faithfully). TWO
-- ways the continuation is captured: (b) a FREE effect op ('ROp') anywhere reifies
-- the body's continuation outward; (a) a handler op-arm whose @resume@ binder
-- ESCAPES its arm body ('Esc.m2bResumeEscapes', the SAME predicate the planner's
-- 'goHandler' uses). The oracle must catch BOTH, else a resuming-handler-arm body
-- with a slice but no 'ROp' would mismatch the planner (planner forces Counted via
-- the fence; a weaker oracle could expect Window). Task 5's death-test programs are
-- exactly these resuming-handler shapes.
oracleFiresOp :: Anf.Expr -> Bool
oracleFiresOp = go
  where
    go (Anf.Ret _)            = False
    go (Anf.Let _ r e)        = goRhs r || go e
    go (Anf.LetRec defs e)    = any (\(_, _, d) -> go d) defs || go e
    go (Anf.Case _ alts)      = any goAlt alts
    go (Anf.LetJoin _ _ jb e) = go jb || go e
    go (Anf.Jump _ _)         = False
    go (Anf.Handle e h)       = go e || goHandler h
    go (Anf.InstallHandler _ _ e) = go e
    goAlt (Anf.AltCon _ _ e)  = go e
    goAlt (Anf.AltLit _ e)    = go e
    goAlt (Anf.AltDefault e)  = go e
    goRhs (Anf.ROp{})         = True
    goRhs (Anf.RLam _ e)      = go e
    goRhs _                   = False
    -- Mirror 'capturesContinuation's goHandler: an op-arm whose resume escapes its
    -- body (case (a)), the return arm, and each op-arm body.
    goHandler h =
      any (\oa -> Esc.m2bResumeEscapes (Anf.oaResume oa) (Anf.oaBody oa)) (Anf.hOps h)
        || go (snd (Anf.hReturn h))
        || any (go . Anf.oaBody) (Anf.hOps h)

rcSliceRoutingTests :: TestTree
rcSliceRoutingTests = testGroup "rcSliceRouting"
  [ testCase "window: non-escaping slice of a referenceable parent -> Window" $
      sliceRepOf 8002 sliceShapeWindow @?= Just Window

  , testCase "counted: escaping slice of a referenceable parent -> Counted" $
      sliceRepOf 8102 sliceShapeCounted @?= Just Counted

  , testCase "handler-disable (AC5): module-wide arena disable -> Counted, no Window" $ do
      -- The slice would be Window (non-escaping, param parent), but a sibling handler
      -- disables arenas module-wide, so it routes the always-safe Counted.
      sliceRepOf 8202 sliceShapeHandlerDisabled @?= Just Counted
      regArenaBodies sliceShapeHandlerDisabled @?= Set.empty

  , testCase "cont-fenced (AC5 sibling): per-body continuation fence -> Counted" $ do
      -- The body fires a free op, so capturesContinuation gates it to Heap/no-arena;
      -- the slice routes the always-safe Counted (not Window).
      sliceRepOf 8303 sliceShapeContFenced @?= Just Counted
      Set.member (Unique 8300) (regArenaBodies sliceShapeContFenced) @?= False

  , testCase "resuming-handler (FIX 1b): slice in a resuming-arm body -> Counted" $ do
      -- A Handle whose op-arm RESUMES (resume escapes the arm) + a slice + NO ROp.
      -- The slice (both the handled-expr one and the in-arm one) routes Counted, and
      -- the oracle must AGREE -- the m2bResumeEscapes path is the only continuation
      -- signal here. (The Handle also triggers the module-wide disable, which is why
      -- the planner forces Counted; the AC3 corpus check above proves the oracle's
      -- rep map matches the planner's EXACTLY for this shape, mismatch == 0.)
      sliceRepOf 8502 sliceShapeResumingHandler @?= Just Counted
      sliceRepOf 8507 sliceShapeResumingHandler @?= Just Counted
      regArenaBodies sliceShapeResumingHandler @?= Set.empty
      -- Directly exercise the oracle's m2bResumeEscapes mirror (FIX 1a), bypassing the
      -- moduleHasHandler || short-circuit: oracleFiresOp on a resuming-arm handler body
      -- with NO ROp can be True ONLY via goHandler's m2bResumeEscapes arm. A weaker
      -- oracle (ROp-only) would return False here and mismatch the planner on a body
      -- like Task 5's death-tests; this assertion pins the faithful mirror.
      let resumingArmBody =
            Anf.Handle (Anf.Ret (Anf.ALit (Anf.LInt 0)))
              (Anf.Handler
                 (regBnd "rv" 8513 regU64, Anf.Ret (Anf.AVar (regNm "rv" 8513)))
                 [ Anf.OpArm (T.pack "E") (T.pack "op") []
                     (regBnd "resume" 8514 regU64)
                     (Anf.Let (regBnd "kk" 8515 regU64)
                        (Anf.RAtom (Anf.AVar (regNm "resume" 8514)))  -- escape, no ROp
                     (Anf.Ret (Anf.AVar (regNm "kk" 8515)))) ]
                 Nothing Nothing Nothing)
      assertBool "oracleFiresOp must fire on a resuming-arm handler body (no ROp)"
        (oracleFiresOp resumingArmBody)

  , testCase "AC3: independent routing oracle matches the planner EXACTLY (mismatch == 0)" $ do
      -- For every corpus module, the planner's rpSliceRep must equal the independently
      -- re-derived oracle map. A routing bug shows up here as a mismatch, not a UAF.
      let mismatches =
            [ (label, Region.rpSliceRep (Region.planRegions cm), oracleSliceReps cm)
            | (label, cm) <- sliceCorpus
            , Region.rpSliceRep (Region.planRegions cm) /= oracleSliceReps cm ]
      assertBool ("planner-vs-oracle mismatches: " <> show mismatches) (null mismatches)

  , testCase "AC4: Copy arm -- arena-born parent + escaping view -> Copy" $ do
      -- Copy is structurally unreachable through planRegions today (a slice's parent
      -- always escapes via the slice argument, so placeLet routes it Heap, never
      -- Arena -- which is SOUND: the parent stays counted so the view never dangles).
      -- The Copy arm is nonetheless a real routing answer (the codegen / future
      -- borrowing-prim fallback), so it is exercised here directly: an Arena-parent
      -- placement map + an escaping view (slice RETURNED) must yield Copy.
      let vBnd    = regBnd "v" 8402 regStrTy
          rhs     = sliceRhs (Anf.AVar (regNm "p" 8401))
          cont    = Anf.Ret (Anf.AVar (regNm "v" 8402))   -- v escapes (returned)
          placeAr = Map.singleton (Unique 8401) Arena     -- parent born in the arena
      Region.sliceRep placeAr vBnd rhs cont @?= Copy
      -- Control: the SAME view with a referenceable (non-Arena) parent is Counted,
      -- not Copy -- proving the Copy verdict is driven by the parent placement.
      Region.sliceRep Map.empty vBnd rhs cont @?= Counted

  , testCase "backend-independence: rpSliceRep is a function of the IR (idempotent)" $
      Region.rpSliceRep (Region.planRegions sliceShapeWindow)
        @?= Region.rpSliceRep (Region.planRegions sliceShapeWindow)
  ]

-- ---------------------------------------------------------------------------
-- Window-routing death-test with teeth + negative control (String Slice E4 Task 5)
-- ---------------------------------------------------------------------------
--
-- THE INVARIANT. A 'Window'-routed view CLAIMS it does not outlive its birth
-- activation (so codegen may drop the parent's refcount edge). The interpreter
-- realizes 'Window' as a COUNTED window (spec D2), so a mis-route is never a runtime
-- UAF -- which means correct non-escaping code is never mis-counted. The death-test,
-- gated behind 'runExprRCDeathTest's flag, checks the routing CLAIM directly: it
-- brackets every activation, registers each 'Window'-routed view born inside it, and
-- at the activation's exit asserts NONE is still alive (present in the store). A
-- non-escaping view is dropped (and DELETED from the store) before the close -> the
-- check passes. An escaping view (returned / stored) is kept alive by its escaping
-- owner -> still present at close -> the invariant FIRES
-- (@"view escaped its birth activation (death-test)"@).
--
-- ZERO FALSE POSITIVES. The view stays counted, so the spec's false-positive trap
-- (uncount the view -> the slice prim, which consumes its parent, frees the parent
-- at the slice -> a later read sees a freed parent and fires on CORRECT code) cannot
-- arise: nothing is uncounted, and the check reads only LIVE-cell membership, never
-- freed memory. The correct corpus below runs UNDER the flag and fires on NONE.
--
-- REAL TEETH (the permanent negative control). A view DELIBERATELY mis-routed
-- 'Window' despite escaping (forced via 'rceForceWindow') MUST trip the invariant.
-- The control programs return / store the forced-'Window' view, so it is alive at
-- the activation close and the test asserts the fire as its EXPECTED failure. If the
-- teeth ever stop biting (the fire stops), these test cases fail -- the load-bearing
-- control (the R1 orphan-slab precedent).

-- | A long (> 'maxInlineStr' = 7 bytes) string literal whose slice is therefore an
-- 'NStringView' cell (a short slice would be an uncounted 'InlineStr', which the
-- death-test never registers -- it is not a counted view). 21 bytes.
deathParentLit :: Anf.Atom
deathParentLit = Anf.ALit (Anf.LStr (T.pack "hello world long here"))

-- | @slice s 0 10@ over an atom -- a 10-byte window (> 7) => an 'NStringView'.
deathSliceRhs :: Anf.Atom -> Anf.Rhs
deathSliceRhs parent =
  Anf.RApp (Anf.APrim (PN.stringModule, PN.stringSliceName))
    [parent, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 10)]

-- | @byteSlice s 0 10@ over an atom -- a 10-byte window (> 7) => an 'NStringView'.
deathByteSliceRhs :: Anf.Atom -> Anf.Rhs
deathByteSliceRhs parent =
  Anf.RApp (Anf.APrim (PN.stringModule, PN.stringByteSliceName))
    [parent, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 10)]

-- | The Perceus-synthesized @__rc_drop@ name (matched by HINT, like the reuse tests).
deathDropName :: Name
deathDropName = Name.Name PN.rcDropName (Unique (-901))

-- | Run a hand-instrumented Expr under the death-test flag, forcing the given view
-- binder 'Unique's to 'Window' (the negative-control override). The slice-rep map is
-- empty (the force-set is the only routing source here), matching how a deliberately
-- mis-routed slice is constructed. Returns the run result.
runDeath :: Set.Set Unique -> Anf.Expr -> IO (Either IV.RuntimeError (St.RCValue, St.Store))
runDeath forced =
  RCM.runExprRCDeathTest RCP.rcPrimTable Map.empty forced
    Map.empty (St.initSentinel St.emptyStore)

-- | Assert a death-test run SUCCEEDS (the invariant did NOT fire) and renders the
-- given expected output. Proves zero false positives on a correct (non-escaping)
-- program run with its view genuinely registered as 'Window'.
assertDeathPasses :: String -> Set.Set Unique -> Anf.Expr -> Text -> IO ()
assertDeathPasses lbl forced e expected =
  runDeath forced e >>= \case
    Left err -> assertFailure (lbl <> ": expected success but the death-test fired/failed: " <> show err)
    Right (v, s) ->
      case St.renderRCValue s v of
        Left err  -> assertFailure (lbl <> ": render failed: " <> show err)
        Right txt -> txt @?= expected

-- | Assert a death-test run FIRES the escape invariant (the permanent negative
-- control). A 'Left' carrying any OTHER error, or a success, fails the test -- so the
-- teeth are load-bearing: if the fire ever stops, this fails.
assertDeathFires :: String -> Set.Set Unique -> Anf.Expr -> IO ()
assertDeathFires lbl forced e =
  runDeath forced e >>= \case
    Left (IV.PrimError m)
      | T.pack "view escaped its birth activation" `T.isInfixOf` m -> pure ()
    Left e' -> assertFailure (lbl <> ": expected the escape invariant to fire, got a different error: " <> show e')
    Right _ -> assertFailure (lbl <> ": NEGATIVE CONTROL DID NOT FIRE -- a forced-Window escaping view passed the death-test (the teeth are broken)")

rcSliceDeathTests :: TestTree
rcSliceDeathTests = testGroup "rcSliceDeath"
  [ -- =====================================================================
    -- (a) ZERO FALSE POSITIVES: correct, non-escaping Window views never fire.
    -- =====================================================================

    -- A non-escaping slice whose view is dropped before the activation returns.
    -- The view is genuinely registered as 'Window' (forced), so the bracket is
    -- active; it dies (rc->0, deleted) before close -> the invariant does NOT fire.
    --   let s = "hello world long here"   -- NString (21B)
    --       v = slice s 0 10              -- NStringView "hello worl" (10B), Window
    --       _ = __rc_drop v               -- v dies here (cascade decrefs s -> s freed)
    --   in 0
    testCase "non-escaping Window view dropped before return: passes (no false positive)" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                nD <- freshName (T.pack "_d")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
                  (Anf.Let (rcBnd nD)
                     (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV])
                  (Anf.Ret (Anf.ALit (Anf.LInt 0)))))
          -- Force the view binder 'Window' so the bracket genuinely activates.
          forced = forcedUniquesOf [(T.pack "v")] e
      assertDeathPasses "drop-before-return" forced e (T.pack "0")

    -- Same for byteSlice (the O(1) byte-indexed view): non-escaping, dropped, passes.
  , testCase "non-escaping Window byteSlice view dropped before return: passes" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                nD <- freshName (T.pack "_d")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathByteSliceRhs (Anf.AVar nS))
                  (Anf.Let (rcBnd nD)
                     (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV])
                  (Anf.Ret (Anf.ALit (Anf.LInt 0)))))
          forced = forcedUniquesOf [T.pack "v"] e
      assertDeathPasses "byteslice-drop-before-return" forced e (T.pack "0")

    -- A view matched-in-place (a Case scrutinee, the §5.1 non-escape) then dropped:
    -- the genuine 'Window' shape the planner routes. Passes.
    --   let s = "..." ; v = slice s 0 10 in (case v of _ -> let _ = __rc_drop v in 0)
  , testCase "non-escaping Window view matched-in-place then dropped: passes" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                nD <- freshName (T.pack "_d")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
                  (Anf.Case (Anf.AVar nV)
                     [ Anf.AltDefault
                         (Anf.Let (rcBnd nD)
                            (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV])
                         (Anf.Ret (Anf.ALit (Anf.LInt 0)))) ]))
          forced = forcedUniquesOf [T.pack "v"] e
      assertDeathPasses "matched-in-place" forced e (T.pack "0")

    -- Slice-of-slice (flatten): the inner view @v1@ is CONSUMED by the outer slice
    -- prim (it flattens @v2@ to point at the ROOT @s@, incref'ing the root and
    -- dropping its @v1@ input), so @v1@ is freed at the @v2@ slice -- absent from the
    -- store before the close (its registration clears cleanly). The OUTER view @v2@
    -- is non-escaping and dropped before return. Both were forced 'Window'; both are
    -- dead at close -> passes. Pins the flatten-on-construction register/clear path.
    --   let s  = "..." ; v1 = slice s 0 15 ; v2 = slice v1 0 10   -- v2 consumes v1
    --       _  = __rc_drop v2                                       -- decrefs root s
    --   in 0
  , testCase "slice-of-slice both non-escaping and dropped: passes" $ do
      let e = runFresh $ do
                nS  <- freshName (T.pack "s")
                nV1 <- freshName (T.pack "v1")
                nV2 <- freshName (T.pack "v2")
                nD2 <- freshName (T.pack "_d2")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV1)
                     (Anf.RApp (Anf.APrim (PN.stringModule, PN.stringSliceName))
                        [Anf.AVar nS, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 15)])
                  (Anf.Let (rcBnd nV2) (deathSliceRhs (Anf.AVar nV1))
                  (Anf.Let (rcBnd nD2)
                     (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV2])
                  (Anf.Ret (Anf.ALit (Anf.LInt 0))))))
          forced = forcedUniquesOf [T.pack "v1", T.pack "v2"] e
      assertDeathPasses "slice-of-slice" forced e (T.pack "0")

    -- Control that the flag-off path is unperturbed: the SAME escaping program that
    -- the negative control fires on passes silently when NOT forced Window and run
    -- with the flag effectively off (empty force-set, empty slice-reps). Confirms the
    -- death-test never fires unless a view is actually routed 'Window'.
  , testCase "escaping view NOT routed Window (flag inert): passes (release parity)" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
                  (Anf.Ret (Anf.AVar nV)))
      -- No forced Window: the escaping view routes (effectively) Counted -> no
      -- registration -> the close finds an empty window-set -> passes. The rendered
      -- view is the 10-byte codepoint window of the parent (a String renders quoted).
      assertDeathPasses "escape-not-window" Set.empty e (T.pack (show ("hello worl" :: String)))

    -- =====================================================================
    -- (b) REAL TEETH: a forced-Window ESCAPING view trips the invariant.
    --     PERMANENT NEGATIVE CONTROLS -- if any stops firing, the test FAILS.
    -- =====================================================================

    -- The view is RETURNED (escapes), forced 'Window'. It is alive at the
    -- activation's close -> the invariant FIRES.
    --   let s = "..." ; v = slice s 0 10 in v          -- v escapes via return
  , testCase "NEGATIVE CONTROL: forced-Window view returned (escapes) FIRES" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
                  (Anf.Ret (Anf.AVar nV)))
          forced = forcedUniquesOf [T.pack "v"] e
      assertDeathFires "return-escape" forced e

    -- Same teeth on byteSlice: a forced-Window escaping byteSlice view FIRES.
  , testCase "NEGATIVE CONTROL: forced-Window byteSlice view returned FIRES" $ do
      let e = runFresh $ do
                nS <- freshName (T.pack "s")
                nV <- freshName (T.pack "v")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathByteSliceRhs (Anf.AVar nS))
                  (Anf.Ret (Anf.AVar nV)))
          forced = forcedUniquesOf [T.pack "v"] e
      assertDeathFires "byteslice-return-escape" forced e

    -- The view is STORED in an outliving cons cell that is returned (escapes), forced
    -- 'Window'. The cons keeps the view alive past the activation close -> FIRES.
    --   let s = "..." ; v = slice s 0 10 ; nil = Nil ; xs = Cons v nil in xs
  , testCase "NEGATIVE CONTROL: forced-Window view stored in returned cons FIRES" $ do
      let e = runFresh $ do
                nS   <- freshName (T.pack "s")
                nV   <- freshName (T.pack "v")
                nNil <- freshName (T.pack "nil")
                nXs  <- freshName (T.pack "xs")
                pure $
                  Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
                  (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
                  (Anf.Let (rcBnd nNil) (Anf.RCon (T.pack "Nil") [])
                  (Anf.Let (rcBnd nXs)
                     (Anf.RCon (T.pack "Cons") [Anf.AVar nV, Anf.AVar nNil])
                  (Anf.Ret (Anf.AVar nXs)))))
          forced = forcedUniquesOf [T.pack "v"] e
      assertDeathFires "store-in-cons-escape" forced e
  ]

-- | Collect the 'Unique's of the binders in an Expr whose name HINTS are in the
-- given list. Used to build the 'rceForceWindow' override from readable binder
-- names without hard-coding the fresh-supply integers.
-- NOTE (partial traversal, intentional): collects binder Uniques whose name
-- matches a hint, walking only Let/Case/LetJoin-body/Handle. It does NOT descend
-- into LetRec function-member bodies or bind LetRec/LetJoin parameter binders --
-- the death-test programs never force a name living in those positions. A future
-- caller that needs such a name must extend the walk.
forcedUniquesOf :: [Text] -> Anf.Expr -> Set.Set Unique
forcedUniquesOf hints = Set.fromList . go
  where
    want b = nameHint (Anf.bndName b) `elem` hints
    keep b = [ nameUniq (Anf.bndName b) | want b ]
    go (Anf.Let b _ e)        = keep b ++ go e
    go (Anf.Case _ alts)      = concatMap goAlt alts
    go (Anf.LetRec _ e)       = go e
    go (Anf.LetJoin _ _ jb e) = go jb ++ go e
    go (Anf.Ret _)            = []
    go (Anf.Jump _ _)         = []
    go (Anf.Handle e h)       = go e ++ go (snd (Anf.hReturn h))
                                  ++ concatMap (go . Anf.oaBody) (Anf.hOps h)
    go (Anf.InstallHandler _ _ e) = go e
    goAlt (Anf.AltCon _ _ e)  = go e
    goAlt (Anf.AltLit _ e)    = go e
    goAlt (Anf.AltDefault e)  = go e

-- ---------------------------------------------------------------------------
-- Adversarial UAF exploit programs + savings/leak oracle (String Slice E4 Task 7)
--
-- Five layers of evidence close the Task-7 gate:
--
--   [counted / release-path]    each .wok program produces the CORRECT output on all
--                               three backends (reference, RC AbstractHeap, RC CHeap).
--                               Driven by 'rcParityHarness' (abstract==C + output parity)
--                               and 'rcDifferentialHarness' (already auto-wired via the
--                               corpus auto-discovery in 'main').
--
--   [forced-window / death-test] the same adversarial escape shape, expressed as a
--                               hand-built 'Anf.Expr', fires the escape invariant when
--                               the view binder is forced to 'Window' (via
--                               'forcedUniquesOf ["v"]' + 'assertDeathFires').
--                               The passing-side variant ('assertDeathPasses') confirms
--                               the same shape with no forced binder does NOT fire.
--
--   [no-copy savings oracle]    a view of a long-byte window costs 32B (fixed view cell,
--                               zero new byte buffer) vs a materialized independent string
--                               of the same bytes costing 16 + roundup(N,8).  Pinned on
--                               BOTH RC backends via 'stPeakBytes'.
--
--   [leak balance]              after all views and their parents drop, frees == allocs
--                               and 'stLive' returns to baseline, on BOTH RC backends.
--
--   [sanitizer + full suite]    ASan/LSan clean ('scripts/asan-runtime.sh'); full
--                               'cabal test wok-tests' green.

-- ---------------------------------------------------------------------------
-- Four adversarial shapes (correct-output evidence on BOTH RC backends):
--   40-adversarial-escape-closure.wok      output 15
--   41-adversarial-store-parent-dropped.wok output 15
--   42-adversarial-slice-of-slice-mid-dies.wok output 10
--   43-adversarial-append-outlives.wok     output 18
-- ---------------------------------------------------------------------------

-- | Run one adversarial corpus program and assert output parity on the abstract
-- + C backends AND that the expected output matches the value computed independently.
adversarialOutputCheck :: FilePath -> Text -> Assertion
adversarialOutputCheck path expected = do
  (absR, cR, _, _) <- withBothBackends path
  case (absR, cR) of
    (Right a, Right c) -> do
      assertEqual (path <> ": abstract output") expected (RCM.rcOutput a)
      assertEqual (path <> ": C output") expected (RCM.rcOutput c)
      assertEqual (path <> ": abstract == C output") (RCM.rcOutput a) (RCM.rcOutput c)
    (Left e, _) -> assertFailure (path <> ": abstract backend failed: " <> show e)
    (_, Left e) -> assertFailure (path <> ": C backend failed: " <> show e)

-- ---------------------------------------------------------------------------
-- Death-test ANF programs for the four adversarial shapes
--
-- Each shape has two variants:
--   (a) PASSES: the view 'v' is dropped/consumed before return (not escaping).
--       Forced Window via 'forcedUniquesOf ["v"]' to activate the bracket.
--   (b) FIRES: the view 'v' escapes (returned / stored / captured). Forced
--       Window via 'forcedUniquesOf ["v"]' -> the bracket detects 'v' alive at
--       activation close -> fires "@view escaped its birth activation@".
-- ---------------------------------------------------------------------------

-- Shape 1: escape-closure.
--
-- FIRES: 'v' is captured by a lambda 'f' which is RETURNED.  The closure holds
-- 'v' alive (via its env) at activation close -> FIRES.
--
--   let s = "hello world long here"
--   let v = slice s 0 10           -- NStringView (forced Window)
--   let f = \param -> v            -- closure captures v
--   f                              -- return f; v alive inside f -> FIRES
--
-- PASSES: 'f' is CALLED (not returned), the returned 'v' is explicitly dropped,
-- then the original 'v' is also dropped (it was never passed into the closure
-- without a dup, so both the closure-call's incref and the original binding
-- must be balanced).
--
--   let s = "..."
--   let v = slice s 0 10
--   let f = \param -> v
--   let r = f 0                    -- call f: incref v (body entry), body returns v
--   let _ = __rc_drop r            -- drop returned v (rc 2->1)
--   let _ = __rc_drop v            -- drop original v binding (rc 1->0, freed)
--   0

adv1EscapeClosureFires :: Anf.Expr
adv1EscapeClosureFires = runFresh $ do
  nS     <- freshName (T.pack "s")
  nV     <- freshName (T.pack "v")
  nParam <- freshName (T.pack "param")
  nF     <- freshName (T.pack "f")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Let (rcBnd nF)
       (Anf.RLam [rcBnd nParam] (Anf.Ret (Anf.AVar nV)))
    (Anf.Ret (Anf.AVar nF))))

adv1EscapeClosurePasses :: Anf.Expr
adv1EscapeClosurePasses = runFresh $ do
  nS     <- freshName (T.pack "s")
  nV     <- freshName (T.pack "v")
  nParam <- freshName (T.pack "param")
  nF     <- freshName (T.pack "f")
  nR     <- freshName (T.pack "r")
  nD1    <- freshName (T.pack "_d1")
  nD2    <- freshName (T.pack "_d2")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Let (rcBnd nF)
       (Anf.RLam [rcBnd nParam] (Anf.Ret (Anf.AVar nV)))
    (Anf.Let (rcBnd nR)
       -- Call f: nV is incref'd (body entry), body returns nV. r = va (rc 2).
       (Anf.RApp (Anf.AVar nF) [Anf.ALit (Anf.LInt 0)])
    (Anf.Let (rcBnd nD1)
       (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nR])
    (Anf.Let (rcBnd nD2)
       (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV])
    (Anf.Ret (Anf.ALit (Anf.LInt 0))))))))

-- Shape 2: store-parent-dropped.
--
-- FIRES: 'v' is stored in a 'Box' constructor cell which is RETURNED.
-- 'v' is alive inside the cons at activation close -> FIRES.
--
--   let v = slice s 0 10
--   let box = Box v
--   box                             -- returned; v alive inside box -> FIRES
--
-- PASSES: the box is explicitly dropped before return, cascading v to 0.
--
--   let v = slice s 0 10
--   let box = Box v
--   let _ = __rc_drop box          -- cascade: decref v -> 0, freed
--   0

adv2StoreParentDroppedFires :: Anf.Expr
adv2StoreParentDroppedFires = runFresh $ do
  nS   <- freshName (T.pack "s")
  nV   <- freshName (T.pack "v")
  nBox <- freshName (T.pack "box")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Let (rcBnd nBox)
       (Anf.RCon (T.pack "Box") [Anf.AVar nV])
    (Anf.Ret (Anf.AVar nBox))))

adv2StoreParentDroppedPasses :: Anf.Expr
adv2StoreParentDroppedPasses = runFresh $ do
  nS   <- freshName (T.pack "s")
  nV   <- freshName (T.pack "v")
  nBox <- freshName (T.pack "box")
  nD   <- freshName (T.pack "_d")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Let (rcBnd nBox)
       (Anf.RCon (T.pack "Box") [Anf.AVar nV])
    (Anf.Let (rcBnd nD)
       (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nBox])
    (Anf.Ret (Anf.ALit (Anf.LInt 0))))))

-- Shape 3: slice-of-slice with escaping outer view.
--
-- FIRES: the outer view 'v2' (which roots at the root buffer via flatten)
-- is RETURNED.  v2 is alive at activation close -> FIRES.
-- v1 is consumed by the slice prim during v2's construction (freed at that
-- point, so forcing v1 Window would PASS -- not the interesting direction here).
--
--   let s  = "hello world long here" (21B)
--   let v1 = slice s 0 15           -- NStringView over s (forced Window too)
--   let v2 = slice v1 0 10          -- flatten: v2 roots at s; v1 freed
--   v2                              -- v2 escapes -> FIRES
--
-- PASSES: v2 is dropped before return (v1 was already freed by the slice prim).
--
--   let v2 = (as above)
--   let _ = __rc_drop v2            -- decref root s -> 0, freed
--   0

adv3SliceOfSliceFires :: Anf.Expr
adv3SliceOfSliceFires = runFresh $ do
  nS  <- freshName (T.pack "s")
  nV1 <- freshName (T.pack "v1")
  nV2 <- freshName (T.pack "v2")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV1)
       (Anf.RApp (Anf.APrim (PN.stringModule, PN.stringSliceName))
          [Anf.AVar nS, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 15)])
    (Anf.Let (rcBnd nV2) (deathSliceRhs (Anf.AVar nV1))
    (Anf.Ret (Anf.AVar nV2))))

adv3SliceOfSlicePasses :: Anf.Expr
adv3SliceOfSlicePasses = runFresh $ do
  nS  <- freshName (T.pack "s")
  nV1 <- freshName (T.pack "v1")
  nV2 <- freshName (T.pack "v2")
  nD  <- freshName (T.pack "_d")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV1)
       (Anf.RApp (Anf.APrim (PN.stringModule, PN.stringSliceName))
          [Anf.AVar nS, Anf.ALit (Anf.LInt 0), Anf.ALit (Anf.LInt 15)])
    (Anf.Let (rcBnd nV2) (deathSliceRhs (Anf.AVar nV1))
    (Anf.Let (rcBnd nD)
       (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nV2])
    (Anf.Ret (Anf.ALit (Anf.LInt 0))))))

-- Shape 4: append-outlives (view fed to append, result outlives both operands).
--
-- FIRES: if 'v' is returned DIRECTLY (escaping) rather than fed to append,
-- the Window claim is violated -> FIRES.  This is the exploit: a
-- 'Window'-routed view that escapes before append can read it.
--
--   let v = slice s 0 10
--   v                               -- v escapes -> FIRES
--
-- PASSES: 'v' is consumed by the 'append' prim (drops v, freeing the parent);
-- the append result is then also dropped.  v is dead at close -> PASSES.
--
--   let v   = slice s 0 10
--   let sfx = "!!!"                 -- InlineStr, short
--   let a   = append v sfx          -- append consumes v (drop v, rc->0, freed)
--   let _   = __rc_drop a
--   0

-- A 3-byte suffix InlineStr atom for the append-outlives shape.
adv4SuffixAtom :: Anf.Atom
adv4SuffixAtom = Anf.ALit (Anf.LStr (T.pack "!!!"))

adv4AppendOutlivesFires :: Anf.Expr
adv4AppendOutlivesFires = runFresh $ do
  nS <- freshName (T.pack "s")
  nV <- freshName (T.pack "v")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Ret (Anf.AVar nV)))

adv4AppendOutlivesPasses :: Anf.Expr
adv4AppendOutlivesPasses = runFresh $ do
  nS   <- freshName (T.pack "s")
  nV   <- freshName (T.pack "v")
  nSfx <- freshName (T.pack "sfx")
  nA   <- freshName (T.pack "a")
  nD   <- freshName (T.pack "_d")
  pure $
    Anf.Let (rcBnd nS) (Anf.RAtom deathParentLit)
    (Anf.Let (rcBnd nV) (deathSliceRhs (Anf.AVar nS))
    (Anf.Let (rcBnd nSfx) (Anf.RAtom adv4SuffixAtom)
    (Anf.Let (rcBnd nA)
       (Anf.RApp (Anf.APrim (PN.stringModule, PN.stringAppendName))
          [Anf.AVar nV, Anf.AVar nSfx])
    (Anf.Let (rcBnd nD)
       (Anf.RApp (Anf.AVar deathDropName) [Anf.AVar nA])
    (Anf.Ret (Anf.ALit (Anf.LInt 0)))))))

-- ---------------------------------------------------------------------------
-- The adversarial test group
-- ---------------------------------------------------------------------------

rcSliceAdversarialTests :: TestTree
rcSliceAdversarialTests = testGroup "rcSliceAdversarial"
  [ -- ==========================================================================
    -- Evidence axis 1: CORRECT OUTPUT ON ALL 3 BACKENDS (counted / release path)
    --
    -- Each .wok program is run through the full pipeline on BOTH RC backends
    -- (abstract heap + C heap) and asserted to produce the expected output.
    -- The reference-interpreter comparison is also covered: the corpus
    -- auto-discovery in 'main' wires all four files to 'rcDifferentialHarness'
    -- (abstract==reference) and 'rcCBackendParity' (abstract==C parity).
    -- ==========================================================================

    testCase "40-escape-closure: correct output (15) on both RC backends" $
      adversarialOutputCheck
        "test/rc-string/40-adversarial-escape-closure.wok"
        (T.pack "15")

  , testCase "41-store-parent-dropped: correct output (15) on both RC backends" $
      adversarialOutputCheck
        "test/rc-string/41-adversarial-store-parent-dropped.wok"
        (T.pack "15")

  , testCase "42-slice-of-slice-mid-dies: correct output (10) on both RC backends" $
      adversarialOutputCheck
        "test/rc-string/42-adversarial-slice-of-slice-mid-dies.wok"
        (T.pack "10")

  , testCase "43-append-outlives: correct output (18) on both RC backends" $
      adversarialOutputCheck
        "test/rc-string/43-adversarial-append-outlives.wok"
        (T.pack "18")

  , -- ==========================================================================
    -- Evidence axis 2: FORCED-WINDOW FIRES (death-test / exploit path)
    --
    -- Each adversarial shape, with its escaping view binder forced to 'Window'
    -- via 'forcedUniquesOf ["v"]', TRIPS the escape invariant.  The passing-side
    -- variant (same shape but the view is consumed/dropped before return) does NOT
    -- fire, proving zero false positives on these specific adversarial patterns.
    -- ==========================================================================

    -- Shape 1: escape-closure -- v captured by a returned lambda -> FIRES.
    testCase "adv1 escape-closure: FIRES when forced-Window view captured by returned closure" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv1EscapeClosureFires
      assertDeathFires "escape-closure-fires" forced adv1EscapeClosureFires

  , testCase "adv1 escape-closure: PASSES when forced-Window view is called then dropped (non-escaping)" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv1EscapeClosurePasses
      assertDeathPasses "escape-closure-passes" forced adv1EscapeClosurePasses (T.pack "0")

    -- Shape 2: store-parent-dropped -- v stored in Box constructor, Box returned -> FIRES.
  , testCase "adv2 store-parent-dropped: FIRES when forced-Window view stored in returned Box" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv2StoreParentDroppedFires
      assertDeathFires "store-parent-dropped-fires" forced adv2StoreParentDroppedFires

  , testCase "adv2 store-parent-dropped: PASSES when forced-Window view in Box is dropped before return" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv2StoreParentDroppedPasses
      assertDeathPasses "store-parent-dropped-passes" forced adv2StoreParentDroppedPasses (T.pack "0")

    -- Shape 3: slice-of-slice with escaping outer view -- outer (v2) returned -> FIRES.
    -- v1 (intermediate) is consumed by the slice prim (flatten) and freed before
    -- the activation closes; forcing v1 Window would not fire (it's already dead).
    -- Forcing v2 Window FIRES because v2 escapes via return.
  , testCase "adv3 slice-of-slice-mid-dies: FIRES when forced-Window outer view is returned" $ do
      let forced = forcedUniquesOf [T.pack "v2"] adv3SliceOfSliceFires
      assertDeathFires "slice-of-slice-outer-fires" forced adv3SliceOfSliceFires

  , testCase "adv3 slice-of-slice-mid-dies: PASSES when forced-Window outer view is dropped before return" $ do
      let forced = forcedUniquesOf [T.pack "v2"] adv3SliceOfSlicePasses
      assertDeathPasses "slice-of-slice-outer-passes" forced adv3SliceOfSlicePasses (T.pack "0")

  , testCase "adv3 slice-of-slice-mid-dies: mid (v1) consumed by slice prim -- forcing v1 Window PASSES (v1 already dead at close)" $ do
      -- v1 is freed when the flatten builds v2. Forcing v1 Window registers it,
      -- but it is removed from the store by the flatten drop. At activation close
      -- v1 is not present -> no fire. This is the "intermediate consumed" proof.
      let forced = forcedUniquesOf [T.pack "v1"] adv3SliceOfSlicePasses
      assertDeathPasses "slice-of-slice-mid-consumed" forced adv3SliceOfSlicePasses (T.pack "0")

    -- Shape 4: append-outlives -- v returned without being fed to append -> FIRES;
    -- v consumed by append (dropped inside append prim) -> PASSES.
  , testCase "adv4 append-outlives: FIRES when forced-Window view returned instead of consumed by append" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv4AppendOutlivesFires
      assertDeathFires "append-outlives-fires" forced adv4AppendOutlivesFires

  , testCase "adv4 append-outlives: PASSES when forced-Window view is consumed by append before return" $ do
      let forced = forcedUniquesOf [T.pack "v"] adv4AppendOutlivesPasses
      assertDeathPasses "append-outlives-passes" forced adv4AppendOutlivesPasses (T.pack "0")

    -- ==========================================================================
    -- Evidence axis 3: NO-COPY SAVINGS ORACLE (AC3)
    --
    -- A view of an N-byte window costs a FIXED 32-byte view cell with ZERO new
    -- byte buffer, regardless of N.  Materializing the same window as an
    -- independent NString costs 'wouldBeCBytes (NString wb)' = 16 + roundup(N,8).
    --
    -- Demonstration with N=41 bytes:
    --   parent string: "hello wonderful world extra text here ok!" (41B)
    --   wouldBeCBytes (NString 41B) = 16 + 8*ceil(41/8) = 16 + 8*6 = 16+48 = 64
    --   view of full 41B window: 32B (fixed, always)
    --   win: 64 - 32 = 32 bytes saved vs an independent copy
    --
    -- Asserted on BOTH RC backends (abstract heap then CHeap).
    -- The 'peak_bytes' delta is the direct measure: after alloc parent + alloc view,
    -- stPeakBytes == parentCBytes + 32 (view cell fixed).  Materializing the same
    -- window separately gives stPeakBytes == parentCBytes + matCBytes.
    -- ==========================================================================

  , testCase "savings: view cell = 32B fixed; materialised = 64B for 41-byte window (AbstractHeap)" $ do
      let parentBs    = TxEnc.encodeUtf8 (T.pack "hello wonderful world extra text here ok!")
          -- 41 bytes: wouldBeCBytes = 16 + 8*ceil(41/8) = 16 + 8*6 = 64
          parentCBytes = St.wouldBeCBytes (St.NString parentBs)
          s0           = St.emptyStore
      -- Alloc parent
      (pa, s1) <- allocStringHelper parentBs s0
      -- Alloc view (all 41 bytes)
      rv <- runExceptT (St.allocNStringView pa 0 41 s1)
      (va, s2) <- case rv of
        Left e  -> assertFailure ("allocNStringView failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- peak_bytes after parent + view
      let viewPeak = St.stPeakBytes (St.stStats s2)
      -- Expected: parent cell + view cell
      assertEqual "view savings (abstract): parent + 32B view"
        (parentCBytes + 32) viewPeak
      -- Drop view (decref parent -> rc 1); drop parent
      rv2 <- runExceptT (St.dropAddr va s2)
      s3  <- case rv2 of
        Left e  -> assertFailure ("drop view failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      _s4 <- case St.dropAddrPure pa s3 of
        Left e  -> assertFailure ("drop parent failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- Materialised comparison: same bytes, fresh NString
      let matCBytes = St.wouldBeCBytes (St.NString parentBs)
      assertEqual "materialised: 16 + roundup(41,8)*8 = 64"
        (64 :: Int) matCBytes
      -- The win: view (32) vs materialised (64): saves 32 bytes
      assertBool "view is strictly cheaper than materialised (32 < 64)"
        (32 < matCBytes)

  , testCase "savings: view cell = 32B fixed; materialised = 64B for 41-byte window (CHeap)" $ do
      hp <- Heap.wokHeapNew
      let parentBs    = TxEnc.encodeUtf8 (T.pack "hello wonderful world extra text here ok!")
          parentCBytes = St.wouldBeCBytes (St.NString parentBs)
          s0           = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString parentBs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      rv <- runExceptT (St.allocNStringView pa 0 41 s1)
      (va, s2) <- case rv of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      -- peak_bytes: parent cell + view cell
      let viewPeak = St.stPeakBytes (St.stStats s2)
      assertEqual "CHeap view savings: parent + 32B view"
        (parentCBytes + 32) viewPeak
      -- Drop view, drop parent
      rv2 <- runExceptT (St.dropAddr va s2)
      s3 <- case rv2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("drop view CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      rv3 <- runExceptT (St.dropAddr pa s3)
      case rv3 of
        Left e -> do { Heap.wokHeapFree hp
                     ; assertFailure ("drop parent CHeap failed: " <> show e) }
        Right _ -> do
          cLive   <- Heap.wokStatLive   hp
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          assertEqual "CHeap savings: wok_stat_live == 0 after all drops" (0 :: Int64) cLive
          assertEqual "CHeap savings: allocs == frees" cAllocs cFrees
          Heap.wokHeapFree hp
      -- Materialised comparison
      let matCBytes = St.wouldBeCBytes (St.NString parentBs)
      assertEqual "materialised: 16 + roundup(41,8)*8 = 64" (64 :: Int) matCBytes
      assertBool "CHeap view is strictly cheaper than materialised (32 < 64)"
        (32 < matCBytes)

    -- ==========================================================================
    -- Evidence axis 4: LEAK BALANCE (AC4)
    --
    -- After all views and their parents have been dropped, 'frees == allocs' and
    -- 'stLive' returns to the pre-allocation baseline, on BOTH RC backends.
    -- ==========================================================================

  , testCase "leak-balance: view + parent, drop both: frees == allocs (AbstractHeap)" $ do
      let parentBs = TxEnc.encodeUtf8 (T.pack "hello wonderful world")
          s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (pa, s1) <- allocStringHelper parentBs s0
      rv <- runExceptT (St.allocNStringView pa 0 15 s1)
      (va, s2) <- case rv of
        Left e  -> assertFailure ("allocNStringView failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- 2 live cells: parent + view
      assertEqual "2 live after alloc" (baseline + 2) (St.stLive (St.stStats s2))
      -- Drop view (cascade decref parent, rc 2->1); view freed.
      rv2 <- runExceptT (St.dropAddr va s2)
      s3  <- case rv2 of
        Left e  -> assertFailure ("drop view failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      assertEqual "1 live after view drop (parent survives)" (baseline + 1) (St.stLive (St.stStats s3))
      -- Drop parent (rc 1->0, freed).
      s4 <- case St.dropAddrPure pa s3 of
        Left e  -> assertFailure ("drop parent failed: " <> show e) >> error "unreachable"
        Right x -> pure x
      -- All balanced: back to baseline, allocs == frees.
      assertEqual "0 live after parent drop" baseline (St.stLive (St.stStats s4))
      assertEqual "allocs == frees"
        (St.stAllocs (St.stStats s4)) (St.stFrees (St.stStats s4))

  , testCase "leak-balance: view + parent, drop both: frees == allocs (CHeap)" $ do
      hp <- Heap.wokHeapNew
      let parentBs = TxEnc.encodeUtf8 (T.pack "hello wonderful world")
          s0       = St.emptyStore { St.stBackend = St.CHeap hp }
      r <- runExceptT (St.alloc (St.NString parentBs) s0)
      (pa, s1) <- case r of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("alloc NString CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      rv <- runExceptT (St.allocNStringView pa 0 15 s1)
      (va, s2) <- case rv of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("allocNStringView CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      rv2 <- runExceptT (St.dropAddr va s2)
      s3  <- case rv2 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("drop view CHeap failed: " <> show e) >> error "unreachable" }
        Right x -> pure x
      rv3 <- runExceptT (St.dropAddr pa s3)
      case rv3 of
        Left e  -> do { Heap.wokHeapFree hp
                      ; assertFailure ("drop parent CHeap failed: " <> show e) }
        Right _ -> do
          cLive   <- Heap.wokStatLive   hp
          cAllocs <- Heap.wokStatAllocs hp
          cFrees  <- Heap.wokStatFrees  hp
          Heap.wokHeapFree hp
          -- Leak balance: C runtime fully balanced.
          assertEqual "CHeap leak-balance: wok_stat_live == 0" (0 :: Int64) cLive
          assertEqual "CHeap leak-balance: allocs == frees" cAllocs cFrees
  ]

-- ---------------------------------------------------------------------------
-- String prim tests (Slice E1, Task 4)
--
-- These tests drive the String prims directly on the abstract heap (like
-- 'rcArrayPrimTests'), verifying RC accounting (alloc/free balance, 0-alloc
-- for non-append ops), correct return values, OOB errors, and multi-byte
-- UTF-8 handling. The wok smoke programs in 'test/rc-string' provide the
-- end-to-end tri-backend oracle.

-- | Look up a String prim from 'String' module.  The prim table is keyed
-- by @(module, name)@, so 'lookupPrim' (which defaults to @Array@) cannot
-- be reused here.
lookupStrPrim :: Text -> IO St.RCPrim
lookupStrPrim = lookupPrimQ (T.pack "String")

-- | Look up a prim from 'Base' module (e.g. @eqString@).
lookupBasePrim :: Text -> IO St.RCPrim
lookupBasePrim = lookupPrimQ (T.pack "Base")

rcStringPrimTests :: TestTree
rcStringPrimTests = testGroup "rc string prims"
  [ -- ---------------------------------------------------------------
    -- byteLength
    -- ---------------------------------------------------------------
    testCase "byteLength: ASCII string returns byte count, 0 alloc, drops string" $ do
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 105])) s0  -- "hi"
      (result, s2) <- callPrim pByteLength [St.RVBox sa] s1
      result @?= St.RVLit (Anf.LInt 2)
      St.stAllocs (St.stStats s2) - St.stAllocs (St.stStats s1) @?= 0
      St.stLive (St.stStats s2) @?= baseline

  , testCase "byteLength: multi-byte UTF-8 returns byte count, not codepoint count" $ do
      -- "he\xC3\xA9" is 'h','e',U+00E9 = 4 bytes but only 3 codepoints
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 101, 0xC3, 0xA9])) s0
      (result, s2) <- callPrim pByteLength [St.RVBox sa] s1
      result @?= St.RVLit (Anf.LInt 4)
      St.stLive (St.stStats s2) @?= baseline

  -- ---------------------------------------------------------------
  -- byteAt
  -- ---------------------------------------------------------------
  , testCase "byteAt: returns the correct byte as U64, 0 alloc, drops string" $ do
      pByteAt <- lookupStrPrim (T.pack "byteAt")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [65, 66, 67])) s0  -- "ABC"
      (result, s2) <- callPrim pByteAt [St.RVBox sa, St.RVLit (Anf.LInt 1)] s1
      result @?= St.RVLit (Anf.LInt 66)  -- 'B' = 66
      St.stAllocs (St.stStats s2) - St.stAllocs (St.stStats s1) @?= 0
      St.stLive (St.stStats s2) @?= baseline

  , testCase "byteAt OOB: raises PrimError" $ do
      pByteAt <- lookupStrPrim (T.pack "byteAt")
      let s0       = St.emptyStore
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 105])) s0  -- "hi"
      expectPrimError pByteAt [St.RVBox sa, St.RVLit (Anf.LInt 5)] s1 "out of bounds"

  -- ---------------------------------------------------------------
  -- length (codepoint count)
  -- ---------------------------------------------------------------
  , testCase "length: ASCII string codepoint count == byte count" $ do
      pLength <- lookupStrPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 101, 108, 108, 111])) s0  -- "hello"
      (result, s2) <- callPrim pLength [St.RVBox sa] s1
      result @?= St.RVLit (Anf.LInt 5)
      St.stLive (St.stStats s2) @?= baseline

  , testCase "length: multi-byte UTF-8 codepoint count < byte count" $ do
      -- "h\xC3\xA9llo": 5 codepoints, 6 bytes
      pLength <- lookupStrPrim (T.pack "length")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 0xC3, 0xA9, 108, 108, 111])) s0
      (result, s2) <- callPrim pLength [St.RVBox sa] s1
      result @?= St.RVLit (Anf.LInt 5)
      St.stLive (St.stStats s2) @?= baseline

  -- ---------------------------------------------------------------
  -- index (codepoint access)
  -- ---------------------------------------------------------------
  , testCase "index: returns the correct Char at position 0" $ do
      pIndex <- lookupStrPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 101, 108, 108, 111])) s0  -- "hello"
      (result, s2) <- callPrim pIndex [St.RVBox sa, St.RVLit (Anf.LInt 0)] s1
      result @?= St.RVLit (Anf.LChar 'h')
      St.stLive (St.stStats s2) @?= baseline

  , testCase "index: returns the multi-byte codepoint at position 1" $ do
      -- "h\xC3\xA9llo": index 1 should be U+00E9 = '\233'
      pIndex <- lookupStrPrim (T.pack "index")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 0xC3, 0xA9, 108, 108, 111])) s0
      (result, s2) <- callPrim pIndex [St.RVBox sa, St.RVLit (Anf.LInt 1)] s1
      result @?= St.RVLit (Anf.LChar '\233')
      St.stLive (St.stStats s2) @?= baseline

  , testCase "index OOB: raises PrimError" $ do
      pIndex <- lookupStrPrim (T.pack "index")
      let s0       = St.emptyStore
          (sa, s1) = St.allocPure (St.NString (BS.pack [104, 105])) s0  -- "hi"
      expectPrimError pIndex [St.RVBox sa, St.RVLit (Anf.LInt 5)] s1 "out of bounds"

  -- ---------------------------------------------------------------
  -- append
  -- ---------------------------------------------------------------
  , testCase "append: concatenates two strings; short result (<=7B) is InlineStr, 0 new allocs (E3)" $ do
      -- "ab" (2B) ++ "cd" (2B) = "abcd" (4B) which is <= maxInlineStr (7).
      -- E3: the result is InlineStr (0 new allocs); the two counted inputs (sa,sb)
      -- are dropped by the prim. sa and sb are allocated via allocPure (HAddr, counted).
      pAppend <- lookupStrPrim (T.pack "append")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [97, 98])) s0  -- "ab"
          (sb, s2) = St.allocPure (St.NString (BS.pack [99, 100])) s1  -- "cd"
      (result, s3) <- callPrim pAppend [St.RVBox sa, St.RVBox sb] s2
      -- "abcd" (4B) <= maxInlineStr: 0 new allocs; sa and sb dropped (frees += 2).
      St.stAllocs (St.stStats s3) - St.stAllocs (St.stStats s2) @?= 0
      -- stLive returns to baseline (sa and sb freed; no new cell).
      St.stLive (St.stStats s3) @?= baseline
      -- Result is InlineStr carrying the concatenated bytes.
      case result of
        St.RVBox (St.InlineStr bs) -> bs @?= BS.pack [97, 98, 99, 100]
        other -> assertFailure ("expected RVBox (InlineStr ...), got: " <> show other)
      -- dropResult on InlineStr is a no-op; stLive stays at baseline.
      s4 <- dropResult result s3
      St.stLive (St.stStats s4) @?= baseline

  , testCase "append: long result (>7B) still allocates one WokString cell" $ do
      -- "abcdefgh" (8B) > maxInlineStr: 1 alloc on the heap.
      pAppend <- lookupStrPrim (T.pack "append")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [97, 98, 99, 100])) s0  -- "abcd"
          (sb, s2) = St.allocPure (St.NString (BS.pack [101, 102, 103, 104])) s1  -- "efgh"
      (result, s3) <- callPrim pAppend [St.RVBox sa, St.RVBox sb] s2
      -- "abcdefgh" (8B) > maxInlineStr: 1 new alloc; sa and sb freed.
      St.stAllocs (St.stStats s3) - St.stAllocs (St.stStats s2) @?= 1
      St.stLive (St.stStats s3) @?= baseline + 1
      -- Verify bytes.
      case result of
        St.RVBox na -> do
          c <- runExceptT (St.deref na s3)
          case c of
            Right cell -> case St.cNode cell of
              St.NString bs -> bs @?= BS.pack [97, 98, 99, 100, 101, 102, 103, 104]
              other -> assertFailure ("expected NString, got: " <> show other)
            Left e -> assertFailure ("deref failed: " <> show e)
        other -> assertFailure ("expected RVBox for 8B result, got: " <> show other)
      s4 <- dropResult result s3
      St.stLive (St.stStats s4) @?= baseline

  -- ---------------------------------------------------------------
  -- eqString
  -- ---------------------------------------------------------------
  , testCase "eqString: equal strings return True (boxed Bool), drops both" $ do
      pEq <- lookupBasePrim (T.pack "eqString")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [120])) s0  -- "x"
          (sb, s2) = St.allocPure (St.NString (BS.pack [120])) s1  -- "x"
      (result, s3) <- callPrim pEq [St.RVBox sa, St.RVBox sb] s2
      -- sa and sb dropped; True NCon is an inline immediate (nullary, no cell),
      -- so live count returns to baseline (no net heap delta).
      St.stLive (St.stStats s3) @?= baseline
      case St.renderRCValue s3 result of
        Right t -> t @?= T.pack "True"
        Left e  -> assertFailure ("render failed: " <> show e)
      s4 <- dropResult result s3
      St.stLive (St.stStats s4) @?= baseline

  , testCase "eqString: unequal strings return False, drops both" $ do
      pEq <- lookupBasePrim (T.pack "eqString")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (sa, s1) = St.allocPure (St.NString (BS.pack [97])) s0  -- "a"
          (sb, s2) = St.allocPure (St.NString (BS.pack [98])) s1  -- "b"
      (result, s3) <- callPrim pEq [St.RVBox sa, St.RVBox sb] s2
      case St.renderRCValue s3 result of
        Right t -> t @?= T.pack "False"
        Left e  -> assertFailure ("render failed: " <> show e)
      s4 <- dropResult result s3
      St.stLive (St.stStats s4) @?= baseline

  -- ---------------------------------------------------------------
  -- slice (E4 Task 3)
  -- ---------------------------------------------------------------
  , testCase "slice: ASCII window <= 7B is InlineStr, 0 new allocs, drops input" $ do
      -- "hello world" (11B); slice 0 5 = "hello" (5B <= maxInlineStr=7) -> InlineStr.
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          bs       = TxEnc.encodeUtf8 (T.pack "hello world")
          (sa, s1) = St.allocPure (St.NString bs) s0
          allocsBefore = St.stAllocs (St.stStats s1)
      (result, s2) <- callPrim pSlice [St.RVBox sa, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 5)] s1
      -- Result must be InlineStr (the RVBox wraps the InlineStr addr).
      case result of
        St.RVBox (St.InlineStr wb) -> TxEnc.decodeUtf8 wb @?= T.pack "hello"
        _ -> assertFailure ("expected InlineStr, got: " <> show result)
      -- 0 new allocs (InlineStr is never heap-allocated).
      St.stAllocs (St.stStats s2) - allocsBefore @?= 0
      -- Live count returns to pre-alloc baseline (sa was dropped by the prim).
      St.stLive (St.stStats s2) @?= baseline

  , testCase "slice: long window > 7B is NStringView, incref parent, drops input" $ do
      -- "hello wonderful world" (21B); slice 6 15 = "wonderful world" (15B > 7) -> NStringView.
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0       = St.emptyStore
          bs       = TxEnc.encodeUtf8 (T.pack "hello wonderful world")
          (sa, s1) = St.allocPure (St.NString bs) s0
          baseline = St.stLive (St.stStats s1)  -- 1 live: the parent
      (result, s2) <- callPrim pSlice [St.RVBox sa, St.RVLit (Anf.LInt 6), St.RVLit (Anf.LInt 15)] s1
      -- Result must be an HAddr or CAddr (a view cell), NOT InlineStr.
      case result of
        St.RVBox (St.InlineStr _) -> assertFailure "expected NStringView cell, got InlineStr"
        St.RVBox _ -> pure ()  -- HAddr or CAddr: good
        _ -> assertFailure ("expected RVBox of NStringView, got: " <> show result)
      -- 2 live cells: parent + view (view is a new allocation).
      St.stLive (St.stStats s2) @?= baseline + 1
      -- The view's bytes must match the expected substring.
      rb <- runExceptT (RCP.stringBytes result s2)
      case rb of
        Left e   -> assertFailure ("stringBytes on view failed: " <> show e)
        Right wb -> TxEnc.decodeUtf8 wb @?= T.pack "wonderful world"
      -- Drop the result; heap returns to baseline.
      r3 <- runExceptT (case result of
              St.RVBox a -> St.dropAddr a s2
              _          -> pure s2)
      case r3 of
        Left e  -> assertFailure ("drop result failed: " <> show e)
        Right s3 -> St.stLive (St.stStats s3) @?= baseline - 1  -- parent also freed since prim dropped it

  , testCase "slice: saturating bounds -- start >= length gives empty string" $ do
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0 = St.emptyStore
          bs = TxEnc.encodeUtf8 (T.pack "hi")
          (sa, s1) = St.allocPure (St.NString bs) s0
      (result, _s2) <- callPrim pSlice [St.RVBox sa, St.RVLit (Anf.LInt 10), St.RVLit (Anf.LInt 5)] s1
      -- start (10) >= length (2), so result is empty string.
      case result of
        St.RVBox (St.InlineStr wb) -> BS.length wb @?= 0
        _ -> assertFailure ("expected InlineStr empty, got: " <> show result)

  , testCase "slice: multibyte UTF-8, codepoint indexing is correct" $ do
      -- "héllo": h(1B) + é(2B) + l + l + o = 5 codepoints, 6 bytes.
      -- slice 1 3 = codepoints [1,4) = "éll" = 4 bytes.
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0 = St.emptyStore
          bs = TxEnc.encodeUtf8 (T.pack "héllo")
          (sa, s1) = St.allocPure (St.NString bs) s0
      (result, _s2) <- callPrim pSlice [St.RVBox sa, St.RVLit (Anf.LInt 1), St.RVLit (Anf.LInt 3)] s1
      case result of
        St.RVBox (St.InlineStr wb) -> TxEnc.decodeUtf8 wb @?= T.pack "éll"
        _ -> assertFailure ("expected InlineStr for 4-byte window, got: " <> show result)

  , testCase "slice of NStringView: flatten produces single view over root, not chain" $ do
      -- Build root -> mid-view -> inner-view; inner must point at root, not mid.
      -- Ownership trace (flatten path):
      --   1. allocPure NString -> pa (rc=1, live=1). baseline=1.
      --   2. slice pa 0 15: allocNStringView pa 0 15 (incref pa->2), dropAddr pa (rc 2->1).
      --      After: pa rc=1, mid=NStringView(pa,0,15) rc=1. live=2 (pa+mid).
      --   3. slice mid 6 9: deref mid -> NStringView(pa,0,_); root=pa, absOff=6.
      --      allocNStringView pa 6 9 (incref pa->2), dropAddr mid (mid rc=1->0, frees mid,
      --      cascade drops pa: pa rc=2->1). After: pa rc=1, inner=NStringView(pa,6,9). live=2.
      --   Note: mid is CONSUMED by step 3 (its owned ref is passed to slice as input).
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "hello wonderful world")  -- 21 bytes
          (pa, s1) = St.allocPure (St.NString bs) s0
          baseline = St.stLive (St.stStats s1)  -- 1 (just pa)
      -- mid = slice [owns pa] -> NStringView (15B > 7). pa consumed, mid alive.
      (mid, s2) <- callPrim pSlice [St.RVBox pa, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 15)] s1
      -- inner = slice [owns mid] -> NStringView over ROOT pa (9B > 7). mid consumed, inner alive.
      (inner, s3) <- callPrim pSlice [mid, St.RVLit (Anf.LInt 6), St.RVLit (Anf.LInt 9)] s2
      -- Bytes must be correct ("wonderful" = chars 6..14 of "hello wonderful world").
      rb <- runExceptT (RCP.stringBytes inner s3)
      case rb of
        Left e   -> assertFailure ("stringBytes on inner failed: " <> show e)
        Right wb -> TxEnc.decodeUtf8 wb @?= T.pack "wonderful"
      -- live=2 (pa + inner). pa rc=1 (inner's counted ref). baseline was 1.
      St.stLive (St.stStats s3) @?= baseline + 1
      -- Drop inner: inner rc=1->0, freed, cascade drops pa (rc=1->0, freed). live=0.
      s4 <- case inner of
        St.RVBox a -> do
          r <- runExceptT (St.dropAddr a s3)
          case r of
            Left e  -> assertFailure ("drop inner failed: " <> show e) >> pure s3
            Right x -> pure x
        _ -> pure s3
      -- Both pa and inner are now freed. live = baseline - 1 = 0.
      St.stLive (St.stStats s4) @?= baseline - 1

  -- ---------------------------------------------------------------
  -- byteSlice (E4 Task 3)
  -- ---------------------------------------------------------------
  , testCase "byteSlice: valid ASCII boundaries, result matches expected bytes" $ do
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "hello world")
          (sa, s1) = St.allocPure (St.NString bs) s0
      (result, _s2) <- callPrim pByteSlice [St.RVBox sa, St.RVLit (Anf.LInt 6), St.RVLit (Anf.LInt 5)] s1
      case result of
        St.RVBox (St.InlineStr wb) -> TxEnc.decodeUtf8 wb @?= T.pack "world"
        _ -> assertFailure ("expected InlineStr for 'world', got: " <> show result)

  , testCase "byteSlice: valid multibyte boundaries (not splitting a codepoint)" $ do
      -- "héllo" = 6 bytes: h[0] é[1,2] l[3] l[4] o[5]
      -- byteSlice 0 1 = "h" (byte 0); byteSlice 3 3 = "llo" (bytes 3,4,5)
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "héllo")
          (sa1, s1) = St.allocPure (St.NString bs) s0
          (sa2, s2) = St.allocPure (St.NString bs) s1
      (r1, _s3) <- callPrim pByteSlice [St.RVBox sa1, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 1)] s2
      (r2, _s4) <- callPrim pByteSlice [St.RVBox sa2, St.RVLit (Anf.LInt 3), St.RVLit (Anf.LInt 3)] _s3
      case r1 of
        St.RVBox (St.InlineStr wb) -> TxEnc.decodeUtf8 wb @?= T.pack "h"
        _ -> assertFailure ("byteSlice 0 1: expected InlineStr 'h', got: " <> show r1)
      case r2 of
        St.RVBox (St.InlineStr wb) -> TxEnc.decodeUtf8 wb @?= T.pack "llo"
        _ -> assertFailure ("byteSlice 3 3: expected InlineStr 'llo', got: " <> show r2)

  , testCase "byteSlice: start splits 2-byte codepoint -> PrimError" $ do
      -- "héllo": h[0] é[1=0xC3, 2=0xA9] l[3] l[4] o[5]
      -- byte 2 (0xA9) is a continuation byte of é -> start=2 splits é -> PrimError.
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "héllo")
          (sa, s1) = St.allocPure (St.NString bs) s0
      expectPrimError pByteSlice [St.RVBox sa, St.RVLit (Anf.LInt 2), St.RVLit (Anf.LInt 3)] s1
        "splits a multibyte codepoint"

  , testCase "byteSlice: end splits 2-byte codepoint -> PrimError" $ do
      -- "héllo": byte 2 is the second byte of é (0xA9). end=2 would split é.
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "héllo")
          (sa, s1) = St.allocPure (St.NString bs) s0
      expectPrimError pByteSlice [St.RVBox sa, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 2)] s1
        "splits a multibyte codepoint"

  , testCase "byteSlice: saturating bounds -- start > byteLength returns empty" $ do
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "hi")
          (sa, s1) = St.allocPure (St.NString bs) s0
      (result, _s2) <- callPrim pByteSlice [St.RVBox sa, St.RVLit (Anf.LInt 100), St.RVLit (Anf.LInt 5)] s1
      case result of
        St.RVBox (St.InlineStr wb) -> BS.length wb @?= 0
        _ -> assertFailure ("expected InlineStr empty, got: " <> show result)

  , testCase "byteSlice on AbstractHeap: long window > 7B produces NStringView, drops input" $ do
      -- "hello wonderful world" (21B); byteSlice 6 15 -> 15B > 7 -> NStringView.
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0 = St.emptyStore
          bs = TxEnc.encodeUtf8 (T.pack "hello wonderful world")
          (sa, s1) = St.allocPure (St.NString bs) s0
          baseline = St.stLive (St.stStats s1)
      (result, s2) <- callPrim pByteSlice [St.RVBox sa, St.RVLit (Anf.LInt 6), St.RVLit (Anf.LInt 15)] s1
      case result of
        St.RVBox (St.InlineStr _) -> assertFailure "expected NStringView, got InlineStr"
        St.RVBox _ -> pure ()
        _ -> assertFailure ("expected RVBox, got: " <> show result)
      rb <- runExceptT (RCP.stringBytes result s2)
      case rb of
        Left e   -> assertFailure ("stringBytes failed: " <> show e)
        Right wb -> TxEnc.decodeUtf8 wb @?= T.pack "wonderful world"
      St.stLive (St.stStats s2) @?= baseline + 1  -- parent + view live

  , testCase "byteSlice on an NStringView input: valid boundary flattens to root-backed view" $ do
      -- Build a view over a long multibyte parent, then byteSlice the VIEW with a
      -- valid in-window boundary. Asserts: correct bytes, the result FLATTENS to a
      -- single view over the ROOT (not view->view), and the live count proves it.
      -- parent = "ABCDEFGHIJélmnopqrst": A-J(10B) + é(2B, bytes 10..11) + lmnopqrst(9B)
      --   = 21 bytes, 20 codepoints.
      pSlice     <- lookupStrPrim (T.pack "slice")
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "ABCDEFGHIJélmnopqrst")
          (pa, s1) = St.allocPure (St.NString bs) s0
          baseline = St.stLive (St.stStats s1)  -- 1 (just pa)
      -- view = slice pa 0 15 -> codepoints 0..14 = "ABCDEFGHIJélmno" (16 bytes > 7 -> NStringView over pa).
      (view, s2) <- callPrim pSlice [St.RVBox pa, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 15)] s1
      case view of
        St.RVBox (St.InlineStr _) -> assertFailure "setup: expected NStringView, got InlineStr"
        St.RVBox _ -> pure ()
        _ -> assertFailure ("setup: expected RVBox view, got: " <> show view)
      -- byteSlice view 8 8 -> view bytes 8..15 = "IJélmno" (8 bytes: I,J,é(2),l,m,n,o > 7).
      -- start=8 (byte 'I', codepoint start), end=16 (end of window): both valid boundaries.
      -- This is the flatten path: result is an NStringView over the ROOT pa, NOT over view.
      (result, s3) <- callPrim pByteSlice [view, St.RVLit (Anf.LInt 8), St.RVLit (Anf.LInt 8)] s2
      case result of
        St.RVBox (St.InlineStr _) -> assertFailure "expected flattened NStringView, got InlineStr"
        St.RVBox _ -> pure ()
        _ -> assertFailure ("expected RVBox view, got: " <> show result)
      rb <- runExceptT (RCP.stringBytes result s3)
      case rb of
        Left e   -> assertFailure ("stringBytes on flattened view failed: " <> show e)
        Right wb -> TxEnc.decodeUtf8 wb @?= T.pack "IJélmno"
      -- Flatten proof (live count): view was CONSUMED by byteSlice; result holds the
      -- only ref to pa. live = baseline + 1 (pa + result). If the chain were view->view,
      -- dropping result would not reclaim pa; the drop below proves it does.
      St.stLive (St.stStats s3) @?= baseline + 1
      -- Drop result: result rc=1->0, freed, cascade drops pa (rc=1->0, freed). live=0.
      s4 <- case result of
        St.RVBox a -> do
          r <- runExceptT (St.dropAddr a s3)
          case r of
            Left e  -> assertFailure ("drop result failed: " <> show e) >> pure s3
            Right x -> pure x
        _ -> pure s3
      St.stLive (St.stStats s4) @?= baseline - 1  -- both pa and result freed

  , testCase "byteSlice on an NStringView input: split boundary within the view window -> PrimError" $ do
      -- Same view as above ("ABCDEFGHIJélmno", 16 bytes; é at view bytes 10..11).
      -- byteSlice view 0 11: end=11 lands on byte 0xA9 (continuation byte of é,
      -- inside the view window) -> PrimError. Exercises the boundary check reading
      -- through the view's windowed bytes.
      pSlice     <- lookupStrPrim (T.pack "slice")
      pByteSlice <- lookupStrPrim (T.pack "byteSlice")
      let s0  = St.emptyStore
          bs  = TxEnc.encodeUtf8 (T.pack "ABCDEFGHIJélmnopqrst")
          (pa, s1) = St.allocPure (St.NString bs) s0
      (view, s2) <- callPrim pSlice [St.RVBox pa, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 15)] s1
      case view of
        St.RVBox (St.InlineStr _) -> assertFailure "setup: expected NStringView, got InlineStr"
        St.RVBox _ -> pure ()
        _ -> assertFailure ("setup: expected RVBox view, got: " <> show view)
      -- end=11 splits é (byte 11 of the VIEW window is the é continuation byte).
      expectPrimError pByteSlice [view, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 11)] s2
        "splits a multibyte codepoint"
      -- Clean up: the failing prim does not consume its input (it errors before
      -- dropAddr), so drop the view here to keep the store balanced for this scope.
      _ <- case view of
        St.RVBox a -> runExceptT (St.dropAddr a s2)
        _          -> pure (Right s2)
      pure ()
  ]

-- ---------------------------------------------------------------------------
-- String Slice E1 (Task 5): QuickCheck property suite (spec §8)
--
-- Every property calls the REAL RC prim implementations and validates results
-- against the INDEPENDENT 'Data.Text' oracle.  CRUCIALLY, each byte-touching op
-- is run on BOTH RC backends, making each property a THREE-WAY differential:
--
--     AbstractHeap  ==  CHeap (real C FFI)  ==  Data.Text oracle
--
-- The CHeap run goes through the actual novel C code: 'wokStringAlloc',
-- 'wokStringData' + the body 'memcpy', the C-cell byte reads ('wokStringByteGet'
-- via 'deref'), and 'append's memcpy into a fresh C 'wok_string' cell.  Random
-- multi-byte stress on the FFI is the soundness floor of this slice; without it
-- the FFI is exercised only by four fixed corpus files.
--
-- The oracle is never a re-derivation of the prim's own logic:
--
--   P1  byteLength vs length: oracle = BS.length (encodeUtf8 t) vs Tx.length t
--   P2  length of append: oracle = Tx.length strA + Tx.length strB
--   P3  byteLength of append: oracle = sum of BS.length . encodeUtf8
--   P4  append byte layout: oracle = encodeUtf8 (Tx.append strA strB)
--   P5  eqString reflexive / symmetric / oracle = (strA == strB)
--   P6  index / byteAt agreement with T.index / BS.index at sampled offsets
--   P7  OOB: index / byteAt at i >= length / byteLength -> PrimError (both RC
--       backends)
--
-- SOUNDNESS RATIONALE:
-- The RC prims decode the raw 'ByteString' from the NString cell and do their
-- own UTF-8 arithmetic.  The 'Data.Text' oracle encodes / decodes via
-- 'Data.Text.Encoding', a SEPARATE implementation.  A divergence reveals a real
-- bug in the RC prim (on either backend), not in the test.
--
-- The generator 'genUtf8Text' deliberately includes multi-byte scalars (accented
-- Latin, CJK, emoji) by weighting a non-ASCII character set heavily enough that
-- an all-ASCII result is almost impossible (cover requirement: 80% multi-byte).
-- ---------------------------------------------------------------------------

-- | Generator: a 'Text' containing a mix of ASCII and multi-byte UTF-8
-- codepoints.  Emoji (4-byte) and CJK (3-byte) are included so the generator
-- reliably exercises the >127 byte paths.
--
-- The 'Int' argument is the QuickCheck size; we clamp the string length to the
-- range [0..max 1 size] to keep test execution fast while letting the shrinker
-- converge to minimal counterexamples.
genUtf8Text :: QC.Gen T.Text
genUtf8Text = QC.sized $ \sz -> do
  n <- QC.choose (0, max 1 sz)
  cs <- QC.vectorOf n genUtf8Char
  pure (T.pack cs)

-- | Single codepoint weighted toward multi-byte UTF-8.
-- Weights: ASCII(32..126) = 30, accented Latin = 30, CJK = 20, emoji = 20.
-- Expected fraction of multi-byte scalars per codepoint: 70%.
genUtf8Char :: QC.Gen Char
genUtf8Char = QC.frequency
  [ (30, QC.choose ('\x20', '\x7E'))   -- printable ASCII (1-byte)
  , (30, QC.elements accentedLatin)    -- Latin Extended (2-byte in UTF-8)
  , (20, QC.elements cjkSamples)       -- CJK Unified Ideographs (3-byte)
  , (20, QC.elements emojiSamples)     -- emoji (4-byte)
  ]

accentedLatin :: [Char]
accentedLatin = "àáâãäåæçèéêëìíîïðñòóôõöùúûüýþÿ\x00C6\x00D8\x00E0\x00FC"

cjkSamples :: [Char]
cjkSamples = "\x4E2D\x6587\x65E5\x672C\x8BED\x9F99\x98CE\x897F\x4EBA\x5929"

emojiSamples :: [Char]
emojiSamples = "\x1F600\x1F609\x1F4A9\x1F525\x1F680\x1F40D\x1F431\x1F984"

-- | A fresh empty store on a given backend.  AbstractHeap reuses 'emptyStore';
-- CHeap needs a live 'WokHeap' bound into 'stBackend'.
emptyStoreOn :: St.HeapBackend -> St.Store
emptyStoreOn b = St.emptyStore { St.stBackend = b }

-- | Run an IO action with a fresh 'CHeap' backend, bracketing the 'WokHeap' so
-- it is always freed (even on exception), and assert the C run is leak-clean:
-- after the action, the C runtime's own 'wok_stat_live' is 0 and
-- 'wok_stat_allocs' == 'wok_stat_frees'.  This is what proves the per-op CHeap
-- run does not leak a real cell on the success path.
withCHeapBalanced :: String -> (St.HeapBackend -> IO a) -> IO a
withCHeapBalanced label act =
  Control.Exception.bracket Heap.wokHeapNew Heap.wokHeapFree $ \hp -> do
    r <- act (St.CHeap hp)
    cLive   <- Heap.wokStatLive   hp
    cAllocs <- Heap.wokStatAllocs hp
    cFrees  <- Heap.wokStatFrees  hp
    assertEqual (label <> ": C wok_stat_live must be 0 (no leak)") (0 :: Int64) cLive
    assertEqual (label <> ": C wok_stat_allocs == wok_stat_frees") cAllocs cFrees
    pure r

-- | Allocate an 'NString' cell from a 'Text' on the GIVEN backend (CHeap routes
-- to the real 'wokStringAlloc' + body memcpy; AbstractHeap to the IntMap mirror).
-- Uses the real 'St.alloc' dispatch, NOT 'allocPure', so the C path is genuinely
-- exercised on a CHeap store.
allocStringOn :: T.Text -> St.Store -> IO (St.Addr, St.Store)
allocStringOn t s = do
  r <- runExceptT (St.alloc (St.NString (TxEnc.encodeUtf8 t)) s)
  case r of
    Right x -> pure x
    Left e  -> assertFailure ("allocStringOn failed: " <> show e)
                 >> error "unreachable"

-- | Call a string prim and return @(result, newStore)@ (any backend).
callStrPrim :: St.RCPrim -> [St.RCValue] -> St.Store -> IO (St.RCValue, St.Store)
callStrPrim = callPrim

-- | Extract the integer from an RVLit (LInt _) or fail.
asInt :: String -> St.RCValue -> IO Integer
asInt _ctx (St.RVLit (Anf.LInt n)) = pure n
asInt ctx  v = assertFailure (ctx <> ": expected RVLit (LInt _), got: " <> show v)

-- | Extract the Char from an RVLit (LChar _) or fail.
asChar :: String -> St.RCValue -> IO Char
asChar _ctx (St.RVLit (Anf.LChar c)) = pure c
asChar ctx  v = assertFailure (ctx <> ": expected RVLit (LChar _), got: " <> show v)

-- | The two RC backends a per-op property runs on: AbstractHeap (the IntMap
-- mirror) and CHeap (the real C runtime).  A property body of type
-- @(St.HeapBackend -> IO Property)@ is run once per backend and the results
-- conjoined; the CHeap run is leak-checked via 'withCHeapBalanced'.
onBothBackends :: String -> (St.HeapBackend -> IO Property) -> IO Property
onBothBackends label body = do
  abstractR <- body St.AbstractHeap
  cheapR    <- withCHeapBalanced label body
  pure (abstractR .&&. cheapR)

-- P1: byteLength s >= length s, with equality iff s is all-ASCII.
-- THREE-WAY: 'length' and 'byteLength' run on BOTH backends; the oracle is
-- BS.length (encodeUtf8 t) and Tx.length t, computed independently.  A bug in
-- the UTF-8 codepoint decoder or the byte counter on EITHER backend surfaces.
prop_stringByteLengthGeLength :: Property
prop_stringByteLengthGeLength =
  QC.forAll genUtf8Text $ \t ->
    QC.ioProperty $ onBothBackends "P1" $ \backend -> do
      pLength     <- lookupStrPrim (T.pack "length")
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      let s0             = emptyStoreOn backend
          baseline       = St.stLive (St.stStats s0)
          oracleLen      = toInteger (T.length t)
          oracleByteLen  = toInteger (BS.length (TxEnc.encodeUtf8 t))
          oracleAllAscii = oracleLen == oracleByteLen
      (sa, s1)      <- allocStringOn t s0
      (sb, s2)      <- allocStringOn t s1
      (lenVal, s3)  <- callStrPrim pLength     [St.RVBox sa] s2
      (byteVal, s4) <- callStrPrim pByteLength [St.RVBox sb] s3
      rcLen     <- asInt "P1 length"     lenVal
      rcByteLen <- asInt "P1 byteLength" byteVal
      St.stLive (St.stStats s4) @?= baseline
      pure $ QC.conjoin
        [ QC.counterexample ("P1 length: RC=" <> show rcLen <> " oracle=" <> show oracleLen)
            (rcLen == oracleLen)
        , QC.counterexample ("P1 byteLength: RC=" <> show rcByteLen <> " oracle=" <> show oracleByteLen)
            (rcByteLen == oracleByteLen)
        , QC.counterexample ("P1 byteLen >= len: " <> show rcByteLen <> " < " <> show rcLen)
            (rcByteLen >= rcLen)
        , QC.counterexample "P1 equality iff all-ASCII"
            ((rcByteLen == rcLen) == oracleAllAscii)
        ]

-- P2: length (append a b) == length a + length b.
-- THREE-WAY: the RC 'append' (allocates a new cell -- a real C cell on CHeap)
-- then 'length' on the result, on both backends; the oracle sums Tx.length.
prop_stringLengthAppend :: Property
prop_stringLengthAppend =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "P2" $ \backend -> do
      pLength <- lookupStrPrim (T.pack "length")
      pAppend <- lookupStrPrim (T.pack "append")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          oracleA  = toInteger (T.length strA)
          oracleB  = toInteger (T.length strB)
      (sa, s1) <- allocStringOn strA s0
      (sb, s2) <- allocStringOn strB s1
      -- append consumes sa and sb, allocates a new cell
      (cat, s3) <- callStrPrim pAppend [St.RVBox sa, St.RVBox sb] s2
      -- length consumes cat
      (lenVal, s4) <- callStrPrim pLength [cat] s3
      rcLen <- asInt "P2 length(append)" lenVal
      St.stLive (St.stStats s4) @?= baseline
      pure $ QC.counterexample
        ("P2: length(append)=" <> show rcLen <> " oracle=" <> show (oracleA + oracleB))
        (rcLen == oracleA + oracleB)

-- P3: byteLength (append a b) == byteLength a + byteLength b.
-- THREE-WAY: same as P2 but the byte oracle BS.length . encodeUtf8.
prop_stringByteLengthAppend :: Property
prop_stringByteLengthAppend =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "P3" $ \backend -> do
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      pAppend     <- lookupStrPrim (T.pack "append")
      let s0        = emptyStoreOn backend
          baseline  = St.stLive (St.stStats s0)
          oracleA   = toInteger (BS.length (TxEnc.encodeUtf8 strA))
          oracleB   = toInteger (BS.length (TxEnc.encodeUtf8 strB))
      (sa, s1)  <- allocStringOn strA s0
      (sb, s2)  <- allocStringOn strB s1
      (cat, s3)     <- callStrPrim pAppend     [St.RVBox sa, St.RVBox sb] s2
      (byteVal, s4) <- callStrPrim pByteLength [cat] s3
      rcByteLen <- asInt "P3 byteLength(append)" byteVal
      St.stLive (St.stStats s4) @?= baseline
      pure $ QC.counterexample
        ("P3: byteLength(append)=" <> show rcByteLen <> " oracle=" <> show (oracleA + oracleB))
        (rcByteLen == oracleA + oracleB)

-- P4: append byte-layout correctness against the Data.Text oracle.
-- THREE-WAY: 'append strA strB' allocates a new cell (a real C cell on CHeap via
-- the body memcpy); we read EVERY byte of the result back via 'byteAt' and
-- assert it equals 'encodeUtf8 (Tx.append strA strB)' at each offset.  This
-- checks the concatenated byte LAYOUT directly (an off-by-one or wrong-length
-- memcpy surfaces), not mere self-consistency.  Associativity then follows from
-- byte-layout correctness; it is not separately re-asserted (Text.append is
-- trivially associative, so re-deriving it would be vacuous).
prop_stringAppendByteLayout :: Property
prop_stringAppendByteLayout =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "P4" $ \backend -> do
      pAppend <- lookupStrPrim (T.pack "append")
      pByteAt <- lookupStrPrim (T.pack "byteAt")
      let oracleBytes = TxEnc.encodeUtf8 (T.append strA strB)
          n           = BS.length oracleBytes
          s0          = emptyStoreOn backend
          baseline    = St.stLive (St.stStats s0)
      (sa, s1)  <- allocStringOn strA s0
      (sb, s2)  <- allocStringOn strB s1
      (cat, s3) <- callStrPrim pAppend [St.RVBox sa, St.RVBox sb] s2
      case cat of
        St.RVBox a -> do
          -- We hold ONE ref to the result throughout.  For each byte read we
          -- incref 'a' once (so 'byteAt' has its own ref to consume) and call
          -- 'byteAt', which drops that extra ref.  Our held ref survives every
          -- read; we drop it once at the end.  This threads the store correctly
          -- and handles n == 0 (no reads; just the final drop) uniformly.
          let readByte (acc, st) i = do
                stD <- dupNTimes a 1 st     -- incref once for byteAt to consume
                (bv, st') <- callStrPrim pByteAt
                               [St.RVBox a, St.RVLit (Anf.LInt (fromIntegral i))] stD
                rb <- asInt "P4 byteAt" bv
                let oracleByte = fromIntegral (BS.index oracleBytes i) :: Integer
                pure (QC.counterexample
                        ("P4 byteAt at " <> show i <> ": RC=" <> show rb
                          <> " oracle=" <> show oracleByte)
                        (rb == oracleByte) : acc, st')
          (checks, sRead) <- Control.Monad.foldM readByte ([], s3) [0 .. n - 1]
          -- Drop our held ref to the result; heap returns to baseline.
          sFinal <- dropResult cat sRead
          St.stLive (St.stStats sFinal) @?= baseline
          pure $ QC.conjoin
            [ QC.counterexample ("P4 byte count: result=" <> show n) True
            , QC.conjoin checks
            ]
        _ ->
          pure (QC.counterexample "P4: append did not return a boxed string" False)

-- P5: eqString reflexive and symmetric; eqString a b iff a and b have the same
-- codepoints.  THREE-WAY: the byte-compare runs on both backends; the oracle is
-- (strA == strB) on 'Data.Text'.  A bug in the byte-compare (first byte only,
-- wrong length) yields False on reflexivity or disagrees with the oracle.
prop_stringEqString :: Property
prop_stringEqString =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "P5" $ \backend -> do
      pEq <- lookupBasePrim (T.pack "eqString")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          oracleEq = strA == strB
      -- Reflexivity needs a pair of cells for the same text
      (sa1, s1) <- allocStringOn strA s0
      (sa2, s2) <- allocStringOn strA s1
      -- Symmetry needs two independent pairs
      (sa3, s3) <- allocStringOn strA s2
      (sb1, s4) <- allocStringOn strB s3
      (sa4, s5) <- allocStringOn strA s4
      (sb2, s6) <- allocStringOn strB s5
      (sb3, s7) <- allocStringOn strB s6
      (sb4, s8) <- allocStringOn strB s7
      -- Reflexivity: eqString a a
      (reflexVal, s9) <- callStrPrim pEq [St.RVBox sa1, St.RVBox sa2] s8
      -- Symmetry: eqString a b and eqString b a
      (abVal, s10) <- callStrPrim pEq [St.RVBox sa3, St.RVBox sb1] s9
      (baVal, s11) <- callStrPrim pEq [St.RVBox sb2, St.RVBox sa4] s10
      -- eqString b b must also be True (reflexivity for strB)
      (oracleVal, s12) <- callStrPrim pEq [St.RVBox sb3, St.RVBox sb4] s11
      let renderBool v = case St.renderRCValue s12 v of
                           Right rendered -> rendered == T.pack "True"
                           Left _         -> False
          rcReflex  = renderBool reflexVal
          rcAB      = renderBool abVal
          rcBA      = renderBool baVal
          rcSame    = renderBool oracleVal
      s13 <- dropResult reflexVal s12
      s14 <- dropResult abVal s13
      s15 <- dropResult baVal s14
      s16 <- dropResult oracleVal s15
      St.stLive (St.stStats s16) @?= baseline
      pure $ QC.conjoin
        [ QC.counterexample "P5 reflexive: eqString a a must be True" rcReflex
        , QC.counterexample "P5 symmetric: eqString a b == eqString b a"
            (rcAB == rcBA)
        , QC.counterexample
            ("P5 oracle: eqString a b iff a==b; oracle=" <> show oracleEq
              <> " RC=" <> show rcAB)
            (rcAB == oracleEq)
        , QC.counterexample
            ("P5 eqString b b must be True; got: " <> show rcSame)
            rcSame
        ]

-- P6: index and byteAt agree with the Text/encodeUtf8 reference at sampled
-- in-bounds offsets.  THREE-WAY: both byte-touching reads run on both backends
-- (on CHeap they hit the C-cell byte reads via 'deref'); the oracle is
-- T.index / BS.index.  A wrong UTF-8 decoder (3- or 4-byte sequences) disagrees.
-- A fixed ASCII char is appended to guarantee a non-empty string.
prop_stringIndexByteAtNonEmpty :: Property
prop_stringIndexByteAtNonEmpty =
  QC.forAll genUtf8Text $ \prefix ->
    let t = T.snoc prefix 'A' in   -- always non-empty ASCII fallback
    QC.forAll (QC.choose (0, T.length t - 1)) $ \cpIdx ->
    QC.forAll (QC.choose (0, BS.length (TxEnc.encodeUtf8 t) - 1)) $ \byteIdx ->
      QC.ioProperty $ onBothBackends "P6" $ \backend -> do
        pIndex  <- lookupStrPrim (T.pack "index")
        pByteAt <- lookupStrPrim (T.pack "byteAt")
        let s0         = emptyStoreOn backend
            baseline   = St.stLive (St.stStats s0)
            bs         = TxEnc.encodeUtf8 t
            oracleCP   = T.index t cpIdx
            oracleByte = BS.index bs byteIdx
        (sa, s1) <- allocStringOn t s0
        (sb, s2) <- allocStringOn t s1
        (cpVal, s3)   <- callStrPrim pIndex
                           [St.RVBox sa, St.RVLit (Anf.LInt (fromIntegral cpIdx))]
                           s2
        (byteVal, s4) <- callStrPrim pByteAt
                           [St.RVBox sb, St.RVLit (Anf.LInt (fromIntegral byteIdx))]
                           s3
        rcCP   <- asChar "P6 index" cpVal
        rcByte <- asInt  "P6 byteAt" byteVal
        St.stLive (St.stStats s4) @?= baseline
        pure $ QC.conjoin
          [ QC.counterexample
              ("P6 index at " <> show cpIdx <> ": RC=" <> show rcCP
                <> " oracle=" <> show oracleCP)
              (rcCP == oracleCP)
          , QC.counterexample
              ("P6 byteAt at " <> show byteIdx <> ": RC=" <> show rcByte
                <> " oracle=" <> show (fromIntegral oracleByte :: Integer))
              (rcByte == fromIntegral oracleByte)
          ]

-- P7: OOB: index s i raises a 'PrimError' when i >= codepoint length; byteAt s i
-- raises a 'PrimError' when i >= byte length.  THREE-WAY: checked on BOTH RC
-- backends (AbstractHeap and CHeap).  The error MUST be a 'PrimError'
-- specifically (the spec wording), not merely any runtime error: a non-PrimError
-- failure (e.g. a store error) does NOT count as a pass.  The
-- 'rc-string-oob/*.wok' corpus additionally covers the reference interpreter
-- end-to-end, so all three interpreters reject OOB.
prop_stringOOB :: Property
prop_stringOOB =
  QC.forAll genUtf8Text $ \t ->
    QC.ioProperty $ onBothBackends "P7" $ \backend -> do
      pIndex  <- lookupStrPrim (T.pack "index")
      pByteAt <- lookupStrPrim (T.pack "byteAt")
      let cpLen      = T.length t
          byteLen    = BS.length (TxEnc.encodeUtf8 t)
          -- cpLen and byteLen are themselves >= the respective lengths, so both
          -- are guaranteed out-of-bounds regardless of t's content.
          oobCPIdx   = fromIntegral cpLen
          oobByteIdx = fromIntegral byteLen
          s0         = emptyStoreOn backend
      (sa, s1) <- allocStringOn t s0
      (sb, s2) <- allocStringOn t s1
      -- The OOB prim throws BEFORE it drops its argument, so on the error path it
      -- does NOT consume the cell (error-path leak is declared unobservable, spec
      -- §5.3).  Both calls run against 's2'; their Left-stores are discarded, and
      -- the cells 'sa'/'sb' are still live at rc 1 in 's2'.  We OWN them, so after
      -- observing the errors we explicitly drop them off 's2' to keep the CHeap
      -- run leak-clean (so 'withCHeapBalanced' still validates no UNINTENDED leak,
      -- while honouring that the prim itself need not free on the error path).
      res1 <- runExceptT (St.rpFn pIndex  [St.RVBox sa, St.RVLit (Anf.LInt oobCPIdx)]   s2)
      res2 <- runExceptT (St.rpFn pByteAt [St.RVBox sb, St.RVLit (Anf.LInt oobByteIdx)] s2)
      -- The error MUST be a PrimError specifically.  Any other Left, or a Right,
      -- is a failure.  'Store' has no Show, so describe only the outcome.
      let isPrimErr r = case r of
                          Left (IV.PrimError _) -> True
                          _                     -> False
          describe r = case r of
                         Left e  -> "error " <> show e
                         Right _ -> "SUCCEEDED (no error)"
          indexOOB  = isPrimErr res1
          byteAtOOB = isPrimErr res2
      -- Clean up the two input cells we still own in 's2' so the CHeap heap
      -- returns to baseline (no UNINTENDED leak; the C runtime free counters
      -- balance).  dropResult walks valueChildren and drops each addr.
      s3 <- dropResult (St.RVBox sa) s2
      _  <- dropResult (St.RVBox sb) s3
      pure $ QC.conjoin
        [ QC.counterexample
            ("P7 index OOB at " <> show (toInteger oobCPIdx :: Integer)
              <> " (cpLen=" <> show cpLen <> "): expected PrimError, got: " <> describe res1)
            indexOOB
        , QC.counterexample
            ("P7 byteAt OOB at " <> show (toInteger oobByteIdx :: Integer)
              <> " (byteLen=" <> show byteLen <> "): expected PrimError, got: " <> describe res2)
            byteAtOOB
        ]

-- | Non-vacuity cover check: at least 80% of generated strings must contain a
-- multi-byte codepoint (i.e. byteLen > cpLen) OR be empty.  This guards against
-- the generator accidentally producing all-ASCII strings.
prop_stringGeneratorMultiByteCoverage :: Property
prop_stringGeneratorMultiByteCoverage =
  QC.forAll genUtf8Text $ \t ->
    let cpLen        = T.length t
        byteLen      = BS.length (TxEnc.encodeUtf8 t)
        hasMultiByte = byteLen > cpLen || cpLen == 0
    in QC.checkCoverage $
       QC.cover 80 hasMultiByte "contains multi-byte codepoint (or empty)" $
       QC.property True   -- always passes; the cover annotation enforces distribution

-- | Incref the address 'a' exactly 'k' times (k >= 0) on the given store.
-- Used by P4 to give the appended result enough refs for n consuming byteAt
-- reads.  'St.incref' bumps the rc by one on each call and works on both the
-- CAddr (C runtime) and HAddr (abstract) backends.
dupNTimes :: St.Addr -> Int -> St.Store -> IO St.Store
dupNTimes _ k s | k <= 0 = pure s
dupNTimes a k s = do
  r <- runExceptT (St.incref a s)
  case r of
    Right s' -> dupNTimes a (k - 1) s'
    Left e   -> assertFailure ("dupNTimes: incref failed: " <> show e)
                  >> error "unreachable"

-- =========================================================================
-- Suite E2: StringZilla prim properties (indexOf / editDistance / hash)
-- =========================================================================

-- | Haskell reference for non-overlapping occurrence count (mirrors countFrom).
refCount :: BS.ByteString -> BS.ByteString -> Int -> Int
refCount _hay needle _from | BS.null needle = 0
refCount hay needle from
  | from > BS.length hay = 0
  | BS.null post         = 0
  | otherwise            =
      1 + refCount hay needle (from + BS.length pre + BS.length needle)
  where
    (pre, post) = BS.breakSubstring needle (BS.drop from hay)

-- | Haskell reference for refFindFrom (pure breakSubstring, no FFI).
refFindFromSpec :: BS.ByteString -> BS.ByteString -> Int -> Word64
refFindFromSpec hay needle from
  | from > BS.length hay = maxBound
  | BS.null needle       = fromIntegral from
  | BS.null post         = maxBound
  | otherwise            = fromIntegral (from + BS.length pre)
  where (pre, post) = BS.breakSubstring needle (BS.drop from hay)

-- | Haskell reference for byte-level Levenshtein (two-row DP).
refLevenshteinSpec :: BS.ByteString -> BS.ByteString -> Word64
refLevenshteinSpec sa sb =
  fromIntegral (last (foldl nextRow [0 .. BS.length sb] (BS.unpack sa)))
  where
    bb = BS.unpack sb
    nextRow [] _ = []
    nextRow (p0 : ps) ca = p0 + 1 : build (p0 + 1) (zip3 (p0 : ps) ps bb)
      where
        build _ [] = []
        build left ((diag, up, cb) : rest) =
          let cost = if ca == cb then 0 else 1 :: Int
              cell = min (up + 1) (min (left + 1) (diag + cost))
          in cell : build cell rest

-- | Sentinel returned by indexOfFromRaw when the needle is absent (UINT64_MAX).
notFoundSentinel :: Integer
notFoundSentinel = toInteger (maxBound :: Word64)

-- P8: indexOfFromRaw hay needle 0 agrees with the pure Haskell reference.
-- Also checks that the absent case returns UINT64_MAX (not some other value).
-- THREE-WAY: AbstractHeap and CHeap must agree; both must match the Haskell oracle.
prop_stringIndexOfFromRaw :: Property
prop_stringIndexOfFromRaw =
  QC.forAll genUtf8Text $ \hay ->
  QC.forAll genUtf8Text $ \needle ->
    QC.ioProperty $ onBothBackends "P8" $ \backend -> do
      pIndexOfFromRaw <- lookupStrPrim (T.pack "indexOfFromRaw")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          bh       = TxEnc.encodeUtf8 hay
          bn       = TxEnc.encodeUtf8 needle
          oracle   = toInteger (refFindFromSpec bh bn 0)
      (sha, s1) <- allocStringOn hay    s0
      (sna, s2) <- allocStringOn needle s1
      (res, s3) <- callStrPrim pIndexOfFromRaw
                     [St.RVBox sha, St.RVBox sna, St.RVLit (Anf.LInt 0)] s2
      rcPos <- asInt "P8 indexOfFromRaw" res
      St.stLive (St.stStats s3) @?= baseline
      pure $ QC.counterexample
        ("P8 indexOfFromRaw: RC=" <> show rcPos <> " oracle=" <> show oracle
          <> " hay=" <> T.unpack hay <> " needle=" <> T.unpack needle)
        (rcPos == oracle)

-- P9: contains hay needle iff indexOfFromRaw hay needle 0 /= UINT64_MAX.
-- Tests both the found (Some) and absent (None) paths; multi-byte strings
-- are included via 'genUtf8Text'.
prop_stringContains :: Property
prop_stringContains =
  QC.forAll genUtf8Text $ \hay ->
  QC.forAll genUtf8Text $ \needle ->
    QC.ioProperty $ onBothBackends "P9" $ \backend -> do
      pIndexOfFromRaw <- lookupStrPrim (T.pack "indexOfFromRaw")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          bh       = TxEnc.encodeUtf8 hay
          bn       = TxEnc.encodeUtf8 needle
          oracle   = refFindFromSpec bh bn 0 /= maxBound
      (sha, s1) <- allocStringOn hay    s0
      (sna, s2) <- allocStringOn needle s1
      (res, s3) <- callStrPrim pIndexOfFromRaw
                     [St.RVBox sha, St.RVBox sna, St.RVLit (Anf.LInt 0)] s2
      rcPos <- asInt "P9 contains(via indexOfFromRaw)" res
      St.stLive (St.stStats s3) @?= baseline
      let rcContains = rcPos /= notFoundSentinel
      pure $ QC.counterexample
        ("P9 contains: RC=" <> show rcContains <> " oracle=" <> show oracle
          <> " hay=" <> T.unpack hay <> " needle=" <> T.unpack needle)
        (rcContains == oracle)

-- P10: count of non-overlapping occurrences (via repeated indexOfFromRaw) agrees
-- with a pure Haskell reference.  Tests the empty-needle short-circuit (-> 0),
-- the zero-occurrences case, and the multi-occurrence case.
prop_stringCount :: Property
prop_stringCount =
  QC.forAll genUtf8Text $ \hay ->
  QC.forAll genUtf8Text $ \needle ->
    QC.ioProperty $ onBothBackends "P10" $ \backend -> do
      pIndexOfFromRaw <- lookupStrPrim (T.pack "indexOfFromRaw")
      let s0       = emptyStoreOn backend
          bh       = TxEnc.encodeUtf8 hay
          bn       = TxEnc.encodeUtf8 needle
          oracle   = refCount bh bn 0
          needleByteLen = BS.length bn
      -- Replicate count loop: repeatedly call indexOfFromRaw starting from
      -- the position after each found match, until not found.
      let loop :: Int -> Int -> St.Store -> IO (Int, St.Store)
          loop from acc s
            | BS.null bn = pure (acc, s)
            | otherwise  = do
                (sha', s1) <- allocStringOn hay    s
                (sna', s2) <- allocStringOn needle s1
                (res,  s3) <- callStrPrim pIndexOfFromRaw
                                [St.RVBox sha', St.RVBox sna', St.RVLit (Anf.LInt (toInteger from))] s2
                pos <- asInt "P10 count loop" res
                if pos == notFoundSentinel
                  then pure (acc, s3)
                  else loop (fromInteger pos + needleByteLen) (acc + 1) s3
      let baseline = St.stLive (St.stStats s0)
      (rcCount, s1) <- loop 0 0 s0
      St.stLive (St.stStats s1) @?= baseline
      pure $ QC.counterexample
        ("P10 count: RC=" <> show rcCount <> " oracle=" <> show oracle
          <> " hay=" <> T.unpack hay <> " needle=" <> T.unpack needle)
        (rcCount == oracle)

-- P11: editDistance a b equals the pure Haskell Levenshtein reference (both
-- backends).  Includes the symmetric property (d(a,b) == d(b,a)) and triangle
-- inequality (d(a,c) <= d(a,b) + d(b,c)) as lightweight conjoined checks.
prop_stringEditDistance :: Property
prop_stringEditDistance =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "P11" $ \backend -> do
      pEditDistance <- lookupStrPrim (T.pack "editDistance")
      let s0      = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          ba       = TxEnc.encodeUtf8 strA
          bb       = TxEnc.encodeUtf8 strB
          oracle   = toInteger (refLevenshteinSpec ba bb)
          oracleBA = toInteger (refLevenshteinSpec bb ba)
      (sa1, s1) <- allocStringOn strA s0
      (sb1, s2) <- allocStringOn strB s1
      (res,  s3) <- callStrPrim pEditDistance [St.RVBox sa1, St.RVBox sb1] s2
      rcDist <- asInt "P11 editDistance(a,b)" res
      St.stLive (St.stStats s3) @?= baseline
      pure $ QC.conjoin
        [ QC.counterexample
            ("P11 editDistance(a,b): RC=" <> show rcDist <> " oracle=" <> show oracle
              <> " a=" <> T.unpack strA <> " b=" <> T.unpack strB)
            (rcDist == oracle)
        , QC.counterexample
            ("P11 editDistance symmetric: oracle(a,b)=" <> show oracle
              <> " oracle(b,a)=" <> show oracleBA)
            (oracle == oracleBA)
        ]

-- P12: hash a is deterministic (both backends return the same U64) and agrees
-- with the Haskell szHash reference.
prop_stringHash :: Property
prop_stringHash =
  QC.forAll genUtf8Text $ \str ->
    QC.ioProperty $ onBothBackends "P12" $ \backend -> do
      pHash <- lookupStrPrim (T.pack "hash")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          oracle   = toInteger (SZ.szHash (TxEnc.encodeUtf8 str))
      (sha, s1) <- allocStringOn str s0
      (res, s2) <- callStrPrim pHash [St.RVBox sha] s1
      rcHash <- asInt "P12 hash" res
      St.stLive (St.stStats s2) @?= baseline
      pure $ QC.counterexample
        ("P12 hash: RC=" <> show rcHash <> " oracle=" <> show oracle
          <> " str=" <> T.unpack str)
        (rcHash == oracle)

-- -------------------------------------------------------------------------
-- Registration
-- -------------------------------------------------------------------------

rcStringPropertyTests :: TestTree
rcStringPropertyTests =
  localOption (QuickCheckTests 150) $
    testGroup "rc string properties (Suite E1: AbstractHeap == CHeap == Text oracle)"
      [ testProperty "P1: byteLength s >= length s; equal iff all-ASCII"
          prop_stringByteLengthGeLength
      , testProperty "P2: length (append a b) == length a + length b"
          prop_stringLengthAppend
      , testProperty "P3: byteLength (append a b) == byteLength a + byteLength b"
          prop_stringByteLengthAppend
      , testProperty "P4: append byte layout == encodeUtf8 (a <> b) (byte-by-byte)"
          prop_stringAppendByteLayout
      , testProperty "P5: eqString reflexive, symmetric, oracle-faithful"
          prop_stringEqString
      , testProperty "P6 (non-empty): index and byteAt agree with Text/encodeUtf8 reference"
          prop_stringIndexByteAtNonEmpty
      , testProperty "P7: index/byteAt OOB raises PrimError (both RC backends)"
          prop_stringOOB
      , testProperty "P-cov: generator produces multi-byte strings (non-vacuity)"
          prop_stringGeneratorMultiByteCoverage
      , testProperty "P8: indexOfFromRaw matches pure Haskell reference (ASCII + multi-byte)"
          prop_stringIndexOfFromRaw
      , testProperty "P9: contains iff indexOfFromRaw /= UINT64_MAX"
          prop_stringContains
      , testProperty "P10: count of non-overlapping occurrences matches Haskell reference"
          prop_stringCount
      , testProperty "P11: editDistance matches Haskell Levenshtein; symmetric"
          prop_stringEditDistance
      , testProperty "P12: hash is deterministic; agrees with szHash reference"
          prop_stringHash
      -- P13: golden pin of CONCRETE sz_hash values. sz_hash has no independent
      -- pure-Haskell equivalent, so P12 and the three-way differential are both
      -- szHash-vs-szHash tautologies that a degenerate/constant hash would pass.
      -- These anchor the actual distinct values: they catch a constant hash AND a
      -- StringZilla version/algorithm change. Regenerate ONLY on a deliberate bump.
      , testCase "P13a: golden sz_hash \"hello\"" $
          SZ.szHash (TxEnc.encodeUtf8 (T.pack "hello")) @?= 1363158538477170947
      , testCase "P13b: golden sz_hash \"h\233llo\" (multi-byte UTF-8)" $
          SZ.szHash (TxEnc.encodeUtf8 (T.pack "h\233llo")) @?= 6121992711004724104
      , testCase "P13c: golden sz_hash \"\" (empty)" $
          SZ.szHash (TxEnc.encodeUtf8 (T.pack "")) @?= 0
      , testCase "P13d: golden sz_hash long ASCII" $
          SZ.szHash (TxEnc.encodeUtf8 (T.pack "The quick brown fox jumps over the lazy dog"))
            @?= 16768718267878484903
      , testCase "P13e: distinct inputs hash distinctly (rejects a degenerate hash)" $
          let hs = map (SZ.szHash . TxEnc.encodeUtf8 . T.pack)
                       ["hello", "h\233llo", "The quick brown fox jumps over the lazy dog"]
          in Data.List.nub hs @?= hs
      ]

-- ---------------------------------------------------------------------------
-- Suite E3: inline-string (SSO) QuickCheck properties
--
-- These properties target the E3 invariants that CANNOT be expressed as unit
-- tests: they cover RANDOM byte content spanning the boundary, mixed inline /
-- heap representations, and the allocation-count contract generalised beyond
-- the two fixed-length cases in Task 1.
--
-- Structure (all on <=7B inline inputs unless noted):
--   PE1  byte round-trip: alloc then derefPure re-yields the same bytes
--   PE2  allocation count: <=7B -> 0 allocs, >7B -> 1 alloc (random length)
--   PE3  eqString across MIXED inline/heap representations (3 pairings)
--   PE4  append: result bytes are the concatenation; inline iff result <=7B
--   PE5  codepoint/byte ops vs Text/BS reference: length, byteLength,
--        index (codepoint), byteAt (byte) -- byteAt exercises the InlineStr
--        FALL-THROUGH past the CAddr O(1) fast-path
--   PE6  search/distance ops vs BS.breakSubstring / pure-Levenshtein:
--        indexOfFromRaw (found + absent), contains, count, editDistance
--   PE7  hash: cross-backend identity == SZ.szHash (P13 golden is the anchor)
--
-- Generator:
--   'genShortText': valid UTF-8 text whose encoding is <=7 bytes (uses the
--   same weighted character generator as E2, restricted by rejection sampling).
--   'genUtf8Text': reused from E2 (mixed length, includes multi-byte).
--
-- THREE-WAY differential: every property body runs via 'onBothBackends', so
-- AbstractHeap and CHeap must agree and the CHeap run must be leak-clean.
-- The reference oracle is always 'BS.*' / 'Data.Text.*' (independent
-- implementations), never a re-derivation of the prim's own logic.  The sole
-- exception is PE7's 'SZ.szHash', which (like E2's P12) is a cross-backend
-- identity check -- szHash has no independent pure equivalent; the P13 golden
-- corpus in 'rcStringPropertyTests' pins the concrete values.
-- ---------------------------------------------------------------------------

-- | Generator: a 'T.Text' whose UTF-8 encoding is at most 'maxInlineStr' (7)
-- bytes.  Characters are drawn from 'genUtf8Char' (the E2 generator, which
-- includes multi-byte scalars); we rejection-sample until the result fits.
-- At larger QuickCheck sizes a single draw often overshoots 7 bytes (multi-byte
-- scalars are 2-4 bytes each), so ~10-50 retries are typical; 'suchThat's
-- built-in 100-retry cap is comfortably sufficient.
genShortText :: QC.Gen T.Text
genShortText =
  QC.suchThat genUtf8Text
    (\t -> BS.length (TxEnc.encodeUtf8 t) <= St.maxInlineStr)

-- | Allocate an 'NString' cell on the given backend's HEAP, bypassing the
-- 'InlineStr' shortcut so that a short (<=7B) string gets a real counted cell.
-- Backend-aware:
--   AbstractHeap: returns an 'HAddr' via 'allocPure' (HAddr, abstract store).
--   CHeap:        calls 'Heap.wokStringAlloc' + 'Heap.wokStringData' + 'copyBytes'
--                 to allocate a real 'CAddr' cell, then charges 'stStats' to mirror
--                 what 'allocNString' would do ('wouldBeCBytes (NString bs)' bytes).
-- PE3 uses this to exercise (CAddr, InlineStr) and (InlineStr, CAddr) pairings
-- on the CHeap backend, and (HAddr, InlineStr) on AbstractHeap.  The forced cell
-- is owned by the store; 'eqString' drops it via 'dropAddr' (which calls
-- 'wok_dec'), so the 'stLive == baseline' check and 'withCHeapBalanced' hold.
allocStringHeapForced :: BS.ByteString -> St.Store -> IO (St.Addr, St.Store)
allocStringHeapForced bs s = case St.stBackend s of
  St.AbstractHeap ->
    pure (St.allocPure (St.NString bs) s)
  St.CHeap hp -> do
    let byteLen = fromIntegral (BS.length bs) :: Word64
        bytes   = St.wouldBeCBytes (St.NString bs)
        live    = St.stLive     (St.stStats s) + 1
        cur     = St.stCurBytes (St.stStats s) + bytes
        stats'  = (St.stStats s)
          { St.stAllocs    = St.stAllocs    (St.stStats s) + 1
          , St.stLive      = live
          , St.stPeak      = max (St.stPeak     (St.stStats s)) live
          , St.stCurBytes  = cur
          , St.stPeakBytes = max (St.stPeakBytes (St.stStats s)) cur
          }
    p    <- Heap.wokStringAlloc hp byteLen
    dest <- Heap.wokStringData p
    BS.useAsCStringLen bs (\(src, len) ->
      copyBytes dest (castPtr src) len)
    pure (St.CAddr p, s { St.stStats = stats' })

-- PE1: for any text whose UTF-8 encoding has <=7 bytes, allocating it on the
-- RC store (which makes it InlineStr) and then derefPure-ing the address back
-- yields an NString with the identical bytes.
-- THREE-WAY: the derefPure is backend-agnostic (InlineStr is not on any heap);
-- the property uses 'onBothBackends' to exercise the full alloc dispatch on each.
prop_inlineStrByteRoundTrip :: Property
prop_inlineStrByteRoundTrip =
  QC.forAll genShortText $ \t ->
    QC.ioProperty $ onBothBackends "PE1" $ \backend -> do
      let bs = TxEnc.encodeUtf8 t
          s0 = emptyStoreOn backend
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e -> assertFailure ("PE1: alloc failed: " <> show e) >>
          pure (QC.counterexample "PE1: alloc failed" False)
        Right (a, s1) -> do
          let isIL = case a of St.InlineStr _ -> True; _ -> False
          case St.derefPure a s1 of
            Left e2 ->
              pure (QC.counterexample ("PE1: derefPure failed: " <> show e2) False)
            Right cell -> do
              let roundTripped = case St.cNode cell of
                                   St.NString b -> b == bs
                                   _            -> False
              pure $ QC.conjoin
                [ QC.counterexample
                    ("PE1 byte round-trip: bs=" <> show bs)
                    roundTripped
                , QC.counterexample
                    ("PE1 must be InlineStr for <=7 bytes (len="
                      <> show (BS.length bs) <> ")")
                    isIL
                ]

-- PE2: a string with <=maxInlineStr bytes allocates 0 cells; a string with
-- more than maxInlineStr bytes allocates exactly 1 cell.  Both backends.
-- This generalises the two fixed-length cases in Task 1 to a random distribution.
-- It is also where the EXACT 0-cell contract for the short-string corpus files
-- (20-22, 24-25, 27-28) is carried: 'rcStatsHarness' on those files only checks
-- alloc/free BALANCE, not the exact-0 count, so this property (plus the Task 1
-- units) is what pins "a <=7B string costs no cell" end to end.
prop_inlineStrAllocCount :: Property
prop_inlineStrAllocCount =
  QC.forAll genUtf8Text $ \t ->
    QC.ioProperty $ onBothBackends "PE2" $ \backend -> do
      let bs    = TxEnc.encodeUtf8 t
          n     = BS.length bs
          s0    = emptyStoreOn backend
          base  = St.stAllocs (St.stStats s0)
      r <- runExceptT (St.alloc (St.NString bs) s0)
      case r of
        Left e -> assertFailure ("PE2: alloc failed: " <> show e) >>
          pure (QC.counterexample "PE2: alloc failed" False)
        Right (a, s1) -> do
          let delta    = St.stAllocs (St.stStats s1) - base
              expected = if n <= St.maxInlineStr then 0 else 1
              isIL     = case a of St.InlineStr _ -> True; _ -> False
          -- Drop the allocated address so the CHeap run stays leak-clean.
          _ <- dropResult (St.RVBox a) s1
          pure $ QC.conjoin
            [ QC.counterexample
                ("PE2 alloc count: n=" <> show n
                  <> " expected=" <> show expected <> " got=" <> show delta)
                (delta == expected)
            , QC.counterexample
                ("PE2 IsInlineStr iff <=maxInlineStr: n=" <> show n
                  <> " isIL=" <> show isIL)
                (isIL == (n <= St.maxInlineStr))
            ]

-- PE3: eqString agrees with byte equality across ALL THREE pairings of
-- inline and heap representations for short strings.
--   (inline, inline): both allocated via 'alloc' (InlineStr on both backends)
--   (heap, inline):   left forced via 'allocStringHeapForced' (CAddr on CHeap,
--                     HAddr on AbstractHeap), right via 'alloc' (InlineStr)
--   (inline, heap):   left via 'alloc' (InlineStr), right forced (CAddr/HAddr)
-- For non-short strings both sides land on the heap regardless.
-- The oracle is bsA == bsB.
prop_inlineStrEqMixed :: Property
prop_inlineStrEqMixed =
  QC.forAll genShortText $ \strA ->
  QC.forAll genShortText $ \strB ->
    QC.ioProperty $ onBothBackends "PE3" $ \backend -> do
      pEq <- lookupBasePrim (T.pack "eqString")
      let bsA      = TxEnc.encodeUtf8 strA
          bsB      = TxEnc.encodeUtf8 strB
          oracleEq = bsA == bsB
          -- Helper: render an eqString result value as Bool
          asBool v s = case St.renderRCValue s v of
                         Right rendered -> rendered == T.pack "True"
                         Left _         -> False
          -- Each pairing starts from a fresh store; baseline is the empty-store
          -- live count.  eqString CONSUMES both arguments (drops the inline
          -- args and the heap-forced HAddr cell), and its Bool result is a
          -- nullary immediate (0 counted cells in E3).  So after dropping the
          -- result (a no-op for the immediate Bool) the store MUST be back at
          -- baseline -- a CHeap/abstract counting bug in eqString's drop path
          -- (e.g. forgetting to free the heap-forced cell) would surface here.
          baseline = St.stLive (St.stStats (emptyStoreOn backend))
      -- Pairing 1 (inline, inline): both via 'alloc' -> both InlineStr
      let s0a = emptyStoreOn backend
      (iaA, s1a) <- allocStringOn strA s0a
      (ibB, s2a) <- allocStringOn strB s1a
      (iiVal, s3a) <- callStrPrim pEq [St.RVBox iaA, St.RVBox ibB] s2a
      let rcII = asBool iiVal s3a
      s4a <- dropResult iiVal s3a
      St.stLive (St.stStats s4a) @?= baseline
      -- Pairing 2 (heap, inline): left forced via allocStringHeapForced, right via alloc
      let s0b = emptyStoreOn backend
      (haA, s1b) <- allocStringHeapForced bsA s0b
      (ibB2, s2b) <- allocStringOn strB s1b
      (hiVal, s3b) <- callStrPrim pEq [St.RVBox haA, St.RVBox ibB2] s2b
      let rcHI = asBool hiVal s3b
      s4b <- dropResult hiVal s3b
      St.stLive (St.stStats s4b) @?= baseline
      -- Pairing 3 (inline, heap): left via alloc, right forced via allocStringHeapForced
      let s0c = emptyStoreOn backend
      (haB, s1c) <- allocStringHeapForced bsB s0c
      (iaA2, s2c) <- allocStringOn strA s1c
      (ihVal, s3c) <- callStrPrim pEq [St.RVBox iaA2, St.RVBox haB] s2c
      let rcIH = asBool ihVal s3c
      s4c <- dropResult ihVal s3c
      St.stLive (St.stStats s4c) @?= baseline
      pure $ QC.conjoin
        [ QC.counterexample
            ("PE3 (inline,inline): oracle=" <> show oracleEq
              <> " got=" <> show rcII
              <> " a=" <> show bsA <> " b=" <> show bsB)
            (rcII == oracleEq)
        , QC.counterexample
            ("PE3 (heap,inline): oracle=" <> show oracleEq
              <> " got=" <> show rcHI
              <> " a=" <> show bsA <> " b=" <> show bsB)
            (rcHI == oracleEq)
        , QC.counterexample
            ("PE3 (inline,heap): oracle=" <> show oracleEq
              <> " got=" <> show rcIH
              <> " a=" <> show bsA <> " b=" <> show bsB)
            (rcIH == oracleEq)
        ]

-- PE4: append bytes and inline-status.
-- For ANY two texts a and b: append a b has bytes (bsA <> bsB), and
-- the result is InlineStr iff len(bsA <> bsB) <= maxInlineStr.
-- THREE-WAY: AbstractHeap and CHeap must agree on both the bytes AND
-- the inline-vs-heap classification of the result.
prop_inlineStrAppend :: Property
prop_inlineStrAppend =
  QC.forAll genUtf8Text $ \strA ->
  QC.forAll genUtf8Text $ \strB ->
    QC.ioProperty $ onBothBackends "PE4" $ \backend -> do
      pAppend <- lookupStrPrim (T.pack "append")
      let bsA         = TxEnc.encodeUtf8 strA
          bsB         = TxEnc.encodeUtf8 strB
          oracleBytes = bsA <> bsB
          oracleLen   = BS.length oracleBytes
          oracleIL    = oracleLen <= St.maxInlineStr
          s0          = emptyStoreOn backend
          baseline    = St.stLive (St.stStats s0)
      (sa, s1) <- allocStringOn strA s0
      (sb, s2) <- allocStringOn strB s1
      (cat, s3) <- callStrPrim pAppend [St.RVBox sa, St.RVBox sb] s2
      let resultIsIL = case cat of
                         St.RVBox (St.InlineStr _) -> True
                         _                         -> False
      -- Extract bytes from result via deref (monadic, handles both HAddr and CAddr).
      -- InlineStr: deref synthesises Cell (NString bs) directly (no heap lookup).
      -- HAddr/CAddr: deref reads the live cell from the respective heap.
      resultBytes <- case cat of
        St.RVBox a -> do
          r2 <- runExceptT (St.deref a s3)
          case r2 of
            Right cell -> case St.cNode cell of
              St.NString b -> pure b
              _            -> assertFailure "PE4: result is not NString" >> error "unreachable"
            Left e -> assertFailure ("PE4: deref failed: " <> show e) >> error "unreachable"
        _ -> assertFailure "PE4: result is not RVBox" >> error "unreachable"
      s4 <- dropResult cat s3
      St.stLive (St.stStats s4) @?= baseline
      pure $ QC.conjoin
        [ QC.counterexample
            ("PE4 bytes: RC=" <> show resultBytes <> " oracle=" <> show oracleBytes)
            (resultBytes == oracleBytes)
        , QC.counterexample
            ("PE4 inline iff <=7B: len=" <> show oracleLen
              <> " oracleIL=" <> show oracleIL
              <> " gotIL=" <> show resultIsIL)
            (resultIsIL == oracleIL)
        ]

-- PE5: codepoint/byte ops on InlineStr inputs match independent references.
-- Covers the E1 ops 'length'/'byteLength'/'index'/'byteAt' on random short
-- (<=7B) inline strings.  'index'/'byteAt' are the load-bearing additions:
-- 'byteAt' has a CAddr O(1) fast-path that an InlineStr must FALL THROUGH (to
-- the deref-then-'BS.index' path), and 'index' decodes UTF-8 codepoints from
-- the synthesised cell.  References are 'Data.Text.length'/'.index' and
-- 'BS.length'/'.index' -- independent of the prim's own arithmetic.
-- Empty strings skip the index/byteAt checks (no valid in-range index exists).
prop_inlineStrCodepointOps :: Property
prop_inlineStrCodepointOps =
  QC.forAll genShortText $ \t ->
    let bs = TxEnc.encodeUtf8 t in
    QC.ioProperty $ onBothBackends "PE5" $ \backend -> do
      pLength     <- lookupStrPrim (T.pack "length")
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      pIndex      <- lookupStrPrim (T.pack "index")
      pByteAt     <- lookupStrPrim (T.pack "byteAt")
      let s0            = emptyStoreOn backend
          baseline      = St.stLive (St.stStats s0)
          oracleLen     = toInteger (T.length t)
          oracleByteLen = toInteger (BS.length bs)
          nonEmpty      = not (BS.null bs)
          -- For non-empty strings, probe the last codepoint and the last byte.
          cpIdx         = T.length t - 1
          byteIdx       = BS.length bs - 1
      (sa, s1) <- allocStringOn t s0
      (sb, s2) <- allocStringOn t s1
      (lenVal, s3)  <- callStrPrim pLength     [St.RVBox sa] s2
      (byteVal, s4) <- callStrPrim pByteLength [St.RVBox sb] s3
      rcLen     <- asInt "PE5 length"     lenVal
      rcByteLen <- asInt "PE5 byteLength" byteVal
      -- index / byteAt only for non-empty strings (need a valid in-range index).
      indexChecks <-
        if not nonEmpty
          then pure []
          else do
            (sc, s5) <- allocStringOn t s4
            (sd, s6) <- allocStringOn t s5
            (cpVal, s7)   <- callStrPrim pIndex  [St.RVBox sc, St.RVLit (Anf.LInt (fromIntegral cpIdx))]   s6
            (byVal, s8)   <- callStrPrim pByteAt [St.RVBox sd, St.RVLit (Anf.LInt (fromIntegral byteIdx))] s7
            rcCP   <- asChar "PE5 index"  cpVal
            rcByte <- asInt  "PE5 byteAt" byVal
            St.stLive (St.stStats s8) @?= baseline
            let oracleCP   = T.index t cpIdx
                oracleByte = toInteger (BS.index bs byteIdx)
            pure
              [ QC.counterexample
                  ("PE5 index at " <> show cpIdx <> ": RC=" <> show rcCP
                    <> " oracle=" <> show oracleCP <> " t=" <> T.unpack t)
                  (rcCP == oracleCP)
              , QC.counterexample
                  ("PE5 byteAt at " <> show byteIdx <> ": RC=" <> show rcByte
                    <> " oracle=" <> show oracleByte <> " t=" <> T.unpack t)
                  (rcByte == oracleByte)
              ]
      -- The non-empty branch already asserts baseline at its last store (s8);
      -- for the empty branch (no index/byteAt allocs) assert it here at s4.
      Control.Monad.unless nonEmpty (St.stLive (St.stStats s4) @?= baseline)
      pure $ QC.conjoin $
        [ QC.counterexample
            ("PE5 length: RC=" <> show rcLen <> " oracle=" <> show oracleLen
              <> " t=" <> T.unpack t)
            (rcLen == oracleLen)
        , QC.counterexample
            ("PE5 byteLength: RC=" <> show rcByteLen <> " oracle=" <> show oracleByteLen
              <> " t=" <> T.unpack t)
            (rcByteLen == oracleByteLen)
        ] ++ indexChecks

-- PE6: search/distance ops on InlineStr inputs match independent references.
-- Covers, on random short (<=7B) inline strings, the search prim
-- 'indexOfFromRaw' (the sole RC search primitive; 'indexOf'/'contains'/'count'
-- are dogfooded over it in 'String') and 'editDistance', against the same
-- 'BS.breakSubstring' / pure-Levenshtein references the E2 properties (P8-P11)
-- use.  Each op deref's the InlineStr to raw bytes; a bug in the inline byte
-- view would surface as a wrong offset/count/distance.  Specifically checked:
--   * indexOfFromRaw (found)   -- offset of an occurring needle
--   * indexOfFromRaw (absent)  -- UINT64_MAX sentinel for an absent needle
--   * contains (found/absent)  -- derived: offset /= sentinel, vs breakSubstring
--   * count                    -- replicated via the same repeated-indexOf loop
--                                 the library uses, vs 'refCount'
--   * editDistance             -- vs 'refLevenshteinSpec'
-- The needle is DERIVED from the haystack: a 1-byte prefix (guaranteed to occur
-- when non-empty) and a sentinel byte 0x00 (guaranteed absent -- NUL never
-- appears in genUtf8Char output) exercise both the found and not-found paths.
prop_inlineStrSearchOps :: Property
prop_inlineStrSearchOps =
  QC.forAll genShortText $ \t ->
  QC.forAll genShortText $ \u ->
    let bs = TxEnc.encodeUtf8 t
        bu = TxEnc.encodeUtf8 u
    in QC.ioProperty $ onBothBackends "PE6" $ \backend -> do
      pIndexOfFromRaw <- lookupStrPrim (T.pack "indexOfFromRaw")
      pEditDistance   <- lookupStrPrim (T.pack "editDistance")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          -- A needle that DOES occur: a 1-byte prefix of the haystack (or empty
          -- if the haystack is empty).  A needle that does NOT occur: a single
          -- NUL byte, which valid UTF-8 text from genUtf8Char never contains.
          occursNeedle = BS.take 1 bs
          absentNeedle = BS.pack [0]
          oracleOccurs = refFindFromSpec bs occursNeedle 0
          oracleAbsent = refFindFromSpec bs absentNeedle 0
          oracleContainsOccurs = oracleOccurs /= maxBound
          oracleContainsAbsent = oracleAbsent /= maxBound
          oracleCount  = refCount bs occursNeedle 0
          oracleDist   = toInteger (refLevenshteinSpec bs bu)
          needleByteLen = BS.length occursNeedle
      -- indexOfFromRaw (occurs)
      (sh1, s1) <- allocStringOn t s0
      (sn1, s2) <- allocStringHelper occursNeedle s1
      (occVal, s3) <- callStrPrim pIndexOfFromRaw
                        [St.RVBox sh1, St.RVBox sn1, St.RVLit (Anf.LInt 0)] s2
      rcOccurs <- asInt "PE6 indexOfFromRaw occurs" occVal
      -- indexOfFromRaw (absent)
      (sh2, s4) <- allocStringOn t s3
      (sn2, s5) <- allocStringHelper absentNeedle s4
      (absVal, s6) <- callStrPrim pIndexOfFromRaw
                        [St.RVBox sh2, St.RVBox sn2, St.RVLit (Anf.LInt 0)] s5
      rcAbsent <- asInt "PE6 indexOfFromRaw absent" absVal
      -- count (occurs): replicate the dogfooded loop -- repeatedly indexOfFromRaw
      -- from the position after each match (empty needle short-circuits to 0).
      let countLoop :: Int -> Int -> St.Store -> IO (Int, St.Store)
          countLoop from acc st
            | BS.null occursNeedle = pure (acc, st)
            | otherwise = do
                (sh, st1) <- allocStringOn t st
                (sn, st2) <- allocStringHelper occursNeedle st1
                (rv, st3) <- callStrPrim pIndexOfFromRaw
                               [St.RVBox sh, St.RVBox sn, St.RVLit (Anf.LInt (toInteger from))] st2
                pos <- asInt "PE6 count loop" rv
                if pos == notFoundSentinel
                  then pure (acc, st3)
                  else countLoop (fromInteger pos + needleByteLen) (acc + 1) st3
      (rcCount, s7) <- countLoop 0 0 s6
      -- editDistance (two short inline strings)
      (sa, s8) <- allocStringOn t s7
      (sb, s9) <- allocStringOn u s8
      (distVal, s10) <- callStrPrim pEditDistance [St.RVBox sa, St.RVBox sb] s9
      rcDist <- asInt "PE6 editDistance" distVal
      St.stLive (St.stStats s10) @?= baseline
      let rcContainsOccurs = rcOccurs /= notFoundSentinel
          rcContainsAbsent = rcAbsent /= notFoundSentinel
      pure $ QC.conjoin
        [ QC.counterexample
            ("PE6 indexOfFromRaw (occurs): RC=" <> show rcOccurs
              <> " oracle=" <> show (toInteger oracleOccurs)
              <> " t=" <> T.unpack t)
            (rcOccurs == toInteger oracleOccurs)
        , QC.counterexample
            ("PE6 indexOfFromRaw (absent NUL): RC=" <> show rcAbsent
              <> " oracle=" <> show (toInteger oracleAbsent)
              <> " (sentinel=" <> show notFoundSentinel <> ") t=" <> T.unpack t)
            (rcAbsent == toInteger oracleAbsent && rcAbsent == notFoundSentinel)
        , QC.counterexample
            ("PE6 contains (occurs): RC=" <> show rcContainsOccurs
              <> " oracle=" <> show oracleContainsOccurs <> " t=" <> T.unpack t)
            (rcContainsOccurs == oracleContainsOccurs)
        , QC.counterexample
            ("PE6 contains (absent NUL): RC=" <> show rcContainsAbsent
              <> " oracle=" <> show oracleContainsAbsent <> " t=" <> T.unpack t)
            (rcContainsAbsent == oracleContainsAbsent && not rcContainsAbsent)
        , QC.counterexample
            ("PE6 count: RC=" <> show rcCount <> " oracle=" <> show oracleCount
              <> " t=" <> T.unpack t)
            (rcCount == oracleCount)
        , QC.counterexample
            ("PE6 editDistance: RC=" <> show rcDist <> " oracle=" <> show oracleDist
              <> " t=" <> T.unpack t <> " u=" <> T.unpack u)
            (rcDist == oracleDist)
        ]

-- PE7: hash on an InlineStr input agrees across BOTH backends and equals the
-- 'SZ.szHash' value.  This mirrors E2's P12 (a szHash-vs-szHash cross-backend
-- identity check; the P13 golden is the independent anchor) but specifically
-- on inline (<=7B) inputs, confirming the InlineStr byte view feeds szHash the
-- same bytes a heap cell would.
prop_inlineStrHash :: Property
prop_inlineStrHash =
  QC.forAll genShortText $ \t ->
    let bs = TxEnc.encodeUtf8 t in
    QC.ioProperty $ onBothBackends "PE7" $ \backend -> do
      pHash <- lookupStrPrim (T.pack "hash")
      let s0       = emptyStoreOn backend
          baseline = St.stLive (St.stStats s0)
          oracle   = toInteger (SZ.szHash bs)
      (sa, s1) <- allocStringOn t s0
      (res, s2) <- callStrPrim pHash [St.RVBox sa] s1
      rcHash <- asInt "PE7 hash" res
      St.stLive (St.stStats s2) @?= baseline
      pure $ QC.counterexample
        ("PE7 hash: RC=" <> show rcHash <> " oracle=" <> show oracle
          <> " t=" <> T.unpack t)
        (rcHash == oracle)

-- | Allocate an arbitrary 'ByteString' (NOT necessarily valid UTF-8) as a
-- string on the given backend.  Used by PE6 for the NUL-byte absent needle,
-- which is not producible via the valid-UTF-8 'genUtf8Char' generator.  Like
-- 'allocStringOn', short results become 'InlineStr' (the search prims deref
-- both haystack and needle to raw bytes regardless of representation).
allocStringHelper :: BS.ByteString -> St.Store -> IO (St.Addr, St.Store)
allocStringHelper bs s = do
  r <- runExceptT (St.alloc (St.NString bs) s)
  case r of
    Right x -> pure x
    Left e  -> assertFailure ("allocStringHelper failed: " <> show e)
                 >> error "unreachable"

rcInlineStringPropertyTests :: TestTree
rcInlineStringPropertyTests =
  localOption (QuickCheckTests 200) $
    testGroup "rc inline string properties (Suite E3: SSO invariants)"
      [ testProperty "PE1: byte round-trip for <=7-byte strings (always InlineStr)"
          prop_inlineStrByteRoundTrip
      , testProperty "PE2: alloc count: <=7B -> 0 cells, >7B -> 1 cell (both backends)"
          prop_inlineStrAllocCount
      , testProperty "PE3: eqString agrees with byte equality across inline/heap pairings"
          prop_inlineStrEqMixed
      , testProperty "PE4: append bytes are concat; inline iff result <=7B"
          prop_inlineStrAppend
      , testProperty "PE5: length/byteLength/index/byteAt on InlineStr match Text/BS reference"
          prop_inlineStrCodepointOps
      , testProperty "PE6: indexOfFromRaw/contains/count/editDistance on InlineStr match BS reference"
          prop_inlineStrSearchOps
      , testProperty "PE7: hash on InlineStr agrees across backends (== szHash)"
          prop_inlineStrHash
      ]

-- ---------------------------------------------------------------------------
-- Suite E4: string-view QuickCheck properties (layer 4)
--
-- Six properties covering borrow-passing correctness and op-transparency for
-- NStringView across all three string representations (view / WokString cell /
-- InlineStr), driven on BOTH backends via 'onBothBackends'.
--
-- Generator notes:
--   'genViewText':   UTF-8 text whose encoding is > 7 bytes (forces NStringView
--                    on the long-window slice path; weighted multi-byte corpus).
--   'genViewIndices': a (start, len) pair covering at least one codepoint; the
--                    window may be <= 7 bytes (InlineStr) for short suffixes, so
--                    properties using it must tolerate both representations. The
--                    > 7-byte guarantee is on the TEXT ('genViewText'), not any
--                    specific window.
--   Edge cases explicitly covered: empty-window saturation (start >= cpLen),
--   exactly-7-byte and exactly-8-byte windows (straddle the inline/view boundary),
--   multibyte codepoints at slice boundaries, start==end (zero-length window),
--   out-of-range start/len for saturation.
--
-- Independence guarantee: every property compares against 'Data.Text' /
-- 'Data.ByteString' operations (separate implementations), never against the
-- same prim under test.
--
-- PV1  Borrow-out survival    -- view keeps parent alive after prim drops input
-- PV2  Nested-flatten         -- slice(slice s a b) c d: root-backed, byte-correct
-- PV3  Window round-trip      -- slice s i n bytes == encodeUtf8(T.take n (T.drop i t))
-- PV4  UTF-8 validity         -- every slice result is valid UTF-8;
--                                byteSlice on split boundary raises PrimError
-- PV5  Op-transparency        -- all E1/E2 ops on a view == same op on materialized copy
-- PV6  Cross-type equality    -- eqString == byte-eq for every (view,cell,inline) pair
-- ---------------------------------------------------------------------------

-- | Generator: 'T.Text' whose UTF-8 encoding is at least @'St.maxInlineStr' + 1@
-- bytes (so a full-range slice will produce an 'NStringView', not 'InlineStr').
-- Uses the same weighted multi-byte generator as E2/E3; rejects until long enough.
genViewText :: QC.Gen T.Text
genViewText =
  QC.suchThat genUtf8Text
    (\t -> BS.length (TxEnc.encodeUtf8 t) > St.maxInlineStr)

-- | Draw a (start, len) pair covering at least one codepoint of the given
-- 'T.Text'.  Returns (codepoint-start, codepoint-length).  The resulting window
-- may be <= 7 bytes (an 'InlineStr') for a short suffix, so callers must tolerate
-- both 'InlineStr' and 'NStringView' results; the > 7-byte property is on the
-- text ('genViewText'), not on any specific window.
genViewIndices :: T.Text -> QC.Gen (Int, Int)
genViewIndices t = do
  let cpLen    = T.length t
      -- Start must be small enough that at least 1 codepoint remains.
      maxStart = max 0 (cpLen - 1)
  start <- QC.choose (0, maxStart)
  let afterText = T.drop start t
      lenMax    = T.length afterText
  -- Pick len in [1..lenMax] covering the whole remaining suffix.
  len <- QC.choose (1, max 1 lenMax)
  pure (start, len)

-- | Call the slice prim with codepoint indices and return the result.
-- Allocation: slice CONSUMES the input (one owned ref); callers must NOT use
-- the input address after this call.
callSlice :: St.RCPrim -> St.Addr -> Int -> Int -> St.Store
          -> IO (St.RCValue, St.Store)
callSlice pSlice a start len s =
  callStrPrim pSlice
    [ St.RVBox a
    , St.RVLit (Anf.LInt (toInteger start))
    , St.RVLit (Anf.LInt (toInteger len))
    ] s

-- | Get the 'ByteString' content of any string RCValue (view, cell, or inline)
-- via 'RCP.stringBytes'.
viewBytes :: St.RCValue -> St.Store -> IO BS.ByteString
viewBytes v s = do
  r <- runExceptT (RCP.stringBytes v s)
  case r of
    Right bs -> pure bs
    Left e   -> assertFailure ("viewBytes: " <> show e) >> error "unreachable"

-- | 'True' if the 'RCValue' is a non-inline boxed address (any 'HAddr'/'CAddr',
-- i.e. NOT an 'InlineStr').  Used only on a 'slice'/'byteSlice' result, which can
-- only be an 'NStringView' cell or an 'InlineStr' -- so here it means "is a view".
isViewAddr :: St.RCValue -> Bool
isViewAddr (St.RVBox (St.InlineStr _)) = False
isViewAddr (St.RVBox _)                = True
isViewAddr _                           = False

-- PV1: Borrow-out survival.
-- A slice result retains correct bytes after the prim has consumed (dropped) its
-- input.  Specifically: allocate a parent, call slice, then READ the view's bytes
-- -- the view's own counted ref must have kept the parent alive.
-- The 'slice' prim drops the input when it builds the result; after it returns,
-- the parent's ref-count is exactly 1 (owned by the view).  Reading via
-- 'stringBytes' after the prim returns proves the parent is still alive.
-- Oracle: 'T.take len (T.drop start t)' (Data.Text, independent).
prop_viewBorrowOutSurvival :: Property
prop_viewBorrowOutSurvival =
  QC.forAll genViewText $ \t ->
  QC.forAll (genViewIndices t) $ \(start, len) ->
    QC.ioProperty $ onBothBackends "PV1" $ \backend -> do
      pSlice <- lookupStrPrim (T.pack "slice")
      let oracleText   = T.take len (T.drop start t)
          oracleBytes  = TxEnc.encodeUtf8 oracleText
          s0           = emptyStoreOn backend
          baseline     = St.stLive (St.stStats s0)
      -- Allocate parent; prim consumes it.
      (sa, s1)       <- allocStringOn t s0
      (result, s2)   <- callSlice pSlice sa start len s1
      -- After the prim, sa is consumed (its ref is now inside result's cell or
      -- the parent's count has been decremented).  Read the result's bytes.
      -- This is the borrow-out survival check: the bytes must still be readable.
      gotBytes <- viewBytes result s2
      -- Drop the result to verify heap balance.
      s3 <- dropResult result s2
      pure $ QC.conjoin
        [ QC.counterexample
            ("PV1 borrow-out bytes: got=" <> show gotBytes
              <> " oracle=" <> show oracleBytes
              <> " t=" <> T.unpack t
              <> " start=" <> show start <> " len=" <> show len)
            (gotBytes == oracleBytes)
        , QC.counterexample
            ("PV1 heap balance after drop: live="
              <> show (St.stLive (St.stStats s3))
              <> " baseline=" <> show baseline)
            (St.stLive (St.stStats s3) == baseline)
        ]

-- PV2: Nested-flatten.
-- 'slice (slice s a b) c d' produces a SINGLE NStringView over the ROOT buffer
-- (no two-hop view->view chain), and its bytes agree with the Data.Text reference
-- double-slice.
-- Proof of root-backing via live count: if the inner view backed the OUTER view
-- (a chain), dropping the inner would cascade-free the outer view cell AND the
-- outer parent cell; the live count would return to baseline - 1 (root freed too
-- early).  Instead: outer view is consumed by the slice prim, inner view holds
-- one ref to the root; live == baseline + 1 (root + inner).  Dropping inner
-- returns to baseline - 1 (all freed).
-- DESIGN: both the outer and inner windows MUST be > 7 bytes to force NStringView
-- (InlineStr is uncounted and the live-count proof does not apply).  We ensure
-- this by picking texts >= 16 bytes, outer window >= 8 bytes, inner >= 8 bytes.
prop_viewNestedFlatten :: Property
prop_viewNestedFlatten =
  -- Need text with >= 16 bytes so we can have an outer window >= 8B and still
  -- leave enough for an inner window >= 8B inside the outer window.
  QC.forAll (QC.suchThat genViewText (\t -> BS.length (TxEnc.encodeUtf8 t) >= 16)) $ \t ->
    QC.ioProperty $ onBothBackends "PV2" $ \backend -> do
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0         = emptyStoreOn backend
          -- Outer window: the whole string.  Always >= 16 bytes by the generator guard.
          outerStart = 0
          outerLen   = T.length t          -- all codepoints
          outerText  = t
          -- Inner window: bytes [0, innerLen) where innerLen = bsLen `div` 2 >= 8.
          -- We pick innerLen as half the BYTE length (>= 8 by our >=16B guard),
          -- but must be on a codepoint boundary.  Take the first half of codepoints.
          halfCp     = T.length outerText `div` 2
          innerStart = 0
          innerLen   = max 1 halfCp
          -- Oracle: Data.Text double-slice.
          oracleText  = T.take innerLen (T.drop innerStart outerText)
          oracleBytes = TxEnc.encodeUtf8 oracleText
          outerByteLen = BS.length (TxEnc.encodeUtf8 outerText)
          innerByteLen = BS.length oracleBytes
      (pa, s1) <- allocStringOn t s0
      let baseline = St.stLive (St.stStats s1)  -- 1: just the root
      -- Outer slice: pa consumed, midView is a counted NStringView over pa
      -- (outer window is >=16B > 7B, so never InlineStr).
      (midView, s2) <- callSlice pSlice pa outerStart outerLen s1
      -- Inner slice: midView consumed.  Flatten: inner roots at pa.
      (inner, s3) <- case midView of
        St.RVBox midAddr -> callSlice pSlice midAddr innerStart innerLen s2
        _ -> assertFailure "PV2: midView is not RVBox" >> error "unreachable"
      -- Byte check.
      gotBytes <- viewBytes inner s3
      -- Live-count proof: mid was consumed (freed), inner holds the only ref to pa.
      -- live = baseline + 1 (pa rc=1 + inner rc=1).
      let liveAfter = St.stLive (St.stStats s3)
      -- Drop inner: cascades pa to rc=0 -> freed. live = baseline - 1 = 0.
      s4 <- dropResult inner s3
      let liveAfterDrop = St.stLive (St.stStats s4)
      pure $ QC.conjoin
        [ QC.counterexample
            ("PV2 nested bytes: got=" <> show gotBytes
              <> " oracle=" <> show oracleBytes
              <> " t=" <> T.unpack t)
            (gotBytes == oracleBytes)
        , QC.counterexample
            ("PV2 root-backing (live after double-slice): live=" <> show liveAfter
              <> " expected=" <> show (baseline + 1)
              <> " (root + inner; outer=" <> show outerByteLen <> "B inner=" <> show innerByteLen <> "B)")
            -- Only assert the view proof when BOTH windows are >7B (NStringView).
            -- If inner <= 7B it's InlineStr and the count is lower.
            (innerByteLen > St.maxInlineStr QC.==> liveAfter == baseline + 1)
        , QC.counterexample
            ("PV2 heap balance after drop inner: live=" <> show liveAfterDrop
              <> " expected=" <> show (baseline - 1))
            (liveAfterDrop == baseline - 1)
        ]

-- PV3: Window round-trip.
-- For any text t and in-range (start, len), 'slice t start len' has the bytes
-- of 'encodeUtf8 (T.take len (T.drop start t))'.  The oracle is Data.Text's own
-- codepoint operations; the prim re-derives the byte window independently via
-- 'cpToByteOff'. Both must agree for all edge cases (empty window, OOB saturation,
-- multibyte at boundary).
-- Also asserts heap balance: parent consumed by prim, so drop(result) -> baseline.
prop_viewWindowRoundTrip :: Property
prop_viewWindowRoundTrip =
  QC.forAll genUtf8Text $ \t ->
  QC.forAll (genRangeIndices t) $ \(start, len) ->
    QC.ioProperty $ onBothBackends "PV3" $ \backend -> do
      pSlice <- lookupStrPrim (T.pack "slice")
      let oracleText  = T.take len (T.drop start t)
          oracleBytes = TxEnc.encodeUtf8 oracleText
          s0          = emptyStoreOn backend
          baseline    = St.stLive (St.stStats s0)
      (sa, s1)     <- allocStringOn t s0
      (result, s2) <- callSlice pSlice sa start len s1
      gotBytes     <- viewBytes result s2
      s3           <- dropResult result s2
      pure $ QC.conjoin
        [ QC.counterexample
            ("PV3 window bytes: got=" <> show gotBytes
              <> " oracle=" <> show oracleBytes
              <> " t=" <> T.unpack t
              <> " start=" <> show start <> " len=" <> show len)
            (gotBytes == oracleBytes)
        , QC.counterexample
            ("PV3 heap balance: live=" <> show (St.stLive (St.stStats s3))
              <> " baseline=" <> show baseline)
            (St.stLive (St.stStats s3) == baseline)
        ]

-- | Generator: arbitrary (start, len) indices, including out-of-range values
-- (for saturation coverage) and zero-length windows.  Does NOT require the
-- window to be > 7 bytes (PV3 covers both inline and view results).
genRangeIndices :: T.Text -> QC.Gen (Int, Int)
genRangeIndices t = do
  let cpLen = T.length t
      -- Allow start up to cpLen+5 (tests OOB saturation -> empty window).
      startBound = max 1 (cpLen + 5)
  start <- QC.choose (0, startBound)
  -- len up to cpLen+5 (exercises saturation of start+len >= cpLen).
  len   <- QC.choose (0, max 1 (cpLen + 5))
  pure (start, len)

-- PV4: UTF-8 validity + byteSlice boundary error.
-- Every 'slice' result is valid UTF-8 (verified via 'TxEnc.decodeUtf8'').
-- 'byteSlice' on a boundary that splits a multi-byte codepoint raises PrimError.
-- Oracle: TxEnc.decodeUtf8' is an independent UTF-8 validator.
-- The byteSlice split check uses a constructed 2-byte codepoint at a known position.
prop_viewUtf8Validity :: Property
prop_viewUtf8Validity =
  QC.forAll genUtf8Text $ \t ->
  QC.forAll (genRangeIndices t) $ \(start, len) ->
    QC.ioProperty $ onBothBackends "PV4" $ \backend -> do
      pSlice <- lookupStrPrim (T.pack "slice")
      let s0 = emptyStoreOn backend
      (sa, s1)     <- allocStringOn t s0
      (result, s2) <- callSlice pSlice sa start len s1
      gotBytes     <- viewBytes result s2
      _s3          <- dropResult result s2
      -- Validity check: decodeUtf8' returns Right for valid UTF-8.
      let isValid = case TxEnc.decodeUtf8' gotBytes of
                      Right _ -> True
                      Left _  -> False
      pure $ QC.counterexample
        ("PV4 slice result is not valid UTF-8: bytes=" <> show gotBytes
          <> " t=" <> T.unpack t
          <> " start=" <> show start <> " len=" <> show len)
        isValid

-- | PV4b: byteSlice raises PrimError when start or end splits a 2-byte codepoint.
-- Uses a concrete 2-byte codepoint (é = 0xC3 0xA9) placed in a longer string so
-- the resulting window exceeds 7 bytes and a view cell is produced on the success
-- path.  Tests both the start-splits and end-splits error cases.
-- IMPORTANT: 'expectPrimError' does NOT consume the input (prim errors before
-- 'dropAddr'), so sa, sb, sc must be freed explicitly.
prop_viewByteSliceSplitError :: Property
prop_viewByteSliceSplitError =
  QC.ioProperty $ onBothBackends "PV4b" $ \backend -> do
    pByteSlice <- lookupStrPrim (T.pack "byteSlice")
    -- "ABCDEFGHIJélmnopqrst": 10 ASCII + é(2B) + 9 ASCII = 21 bytes, 20 codepoints.
    -- é is at BYTE positions 10 (0xC3) and 11 (0xA9).
    let s0  = emptyStoreOn backend
        bs  = TxEnc.encodeUtf8 (T.pack "ABCDEFGHIJélmnopqrst")
    -- Alloc three copies: sa for start-split test, sb for end-split test,
    -- sc for the valid-cut success path.
    (sa, s1) <- allocStringHelper bs s0
    (sb, s2) <- allocStringHelper bs s1
    (sc, s3) <- allocStringHelper bs s2
    -- start=11 splits é (byte 11 is the continuation byte 0xA9).
    expectPrimError pByteSlice
      [St.RVBox sa, St.RVLit (Anf.LInt 11), St.RVLit (Anf.LInt 5)] s3
      "splits a multibyte codepoint"
    -- end=11 (start=0, len=11) splits é.
    expectPrimError pByteSlice
      [St.RVBox sb, St.RVLit (Anf.LInt 0), St.RVLit (Anf.LInt 11)] s3
      "splits a multibyte codepoint"
    -- Valid cut: start=10, len=2 (exact é bytes). No error; drop result.
    (res, s4) <- callStrPrim pByteSlice
      [St.RVBox sc, St.RVLit (Anf.LInt 10), St.RVLit (Anf.LInt 2)] s3
    s5 <- dropResult res s4
    -- sa and sb were NOT consumed by the failing prims; drop them to stay leak-clean.
    s6 <- dropResult (St.RVBox sa) s5
    s7 <- dropResult (St.RVBox sb) s6
    let baseline = St.stLive (St.stStats s0)
    pure $ QC.counterexample
      ("PV4b heap balance: live=" <> show (St.stLive (St.stStats s7))
        <> " baseline=" <> show baseline)
      (St.stLive (St.stStats s7) == baseline)

-- | PV4c: focused regression for the WokStringView CAddr byteAt bug.
-- A >7-byte view on the CHeap is a 'CAddr' pointing at a 'WokStringView' cell.
-- Before the tag-guard fix, 'stringByteAt' took the CHeap fast-path
-- ('wokStringLen' / 'wokStringByteGet') unconditionally on ANY 'CAddr',
-- misreading the WokStringView layout (parent-ptr read as byte_len, indexing into
-- offset/len fields -- silent garbage, possibly past the 32-byte cell).
-- This test pins 'byteAt' at EVERY index of a known view window against the
-- reference bytes, on BOTH backends (the CHeap run is where the bug lived).
-- Concrete window: parent "ABCDEFGHIJélmnopqrst" (21B, é at bytes 10-11),
-- view = slice 0 15 (codepoints 0..14 = "ABCDEFGHIJélmno", 16 bytes > 7 ->
-- NStringView).  byteAt i for i in [0..15] must equal the i-th window byte.
prop_viewByteAtOnView :: Property
prop_viewByteAtOnView =
  QC.ioProperty $ onBothBackends "PV4c" $ \backend -> do
    pSlice  <- lookupStrPrim (T.pack "slice")
    pByteAt <- lookupStrPrim (T.pack "byteAt")
    let s0       = emptyStoreOn backend
        parentBs = TxEnc.encodeUtf8 (T.pack "ABCDEFGHIJélmnopqrst")
        -- The view window: codepoints 0..14 -> "ABCDEFGHIJélmno" (16 bytes).
        winBytes = TxEnc.encodeUtf8 (T.take 15 (TxEnc.decodeUtf8 parentBs))
        winLen   = BS.length winBytes
        baseline = St.stLive (St.stStats s0)
    -- Probe byteAt at every in-window index; one fresh view per probe (byteAt
    -- consumes its input).  Each result must equal the reference window byte.
    let probe :: Int -> St.Store -> IO (Bool, St.Store)
        probe i st = do
          (pa, st1)  <- allocStringHelper parentBs st
          (view, st2) <- callSlice pSlice pa 0 15 st1
          -- Confirm the slice produced a real view cell (not InlineStr) so the
          -- CAddr fast-path is genuinely exercised on CHeap.
          let isView = isViewAddr view
          (bv, st3)  <- callStrPrim pByteAt [view, St.RVLit (Anf.LInt (toInteger i))] st2
          rcByte     <- asInt "PV4c byteAt(view)" bv
          let oracleByte = toInteger (BS.index winBytes i)
          pure (isView && rcByte == oracleByte, st3)
    let loop :: [Int] -> Bool -> St.Store -> IO (Bool, St.Store)
        loop []       acc st = pure (acc, st)
        loop (i:is) acc st = do
          (ok, st') <- probe i st
          loop is (acc && ok) st'
    (allOk, sEnd) <- loop [0 .. winLen - 1] True s0
    -- OOB index: byteAt at winLen must raise PrimError (view-windowed bound).
    (paOOB, sOOB1) <- allocStringHelper parentBs sEnd
    (viewOOB, sOOB2) <- callSlice pSlice paOOB 0 15 sOOB1
    expectPrimError pByteAt
      [viewOOB, St.RVLit (Anf.LInt (toInteger winLen))] sOOB2
      "out of bounds"
    -- expectPrimError does NOT consume the view; drop it to stay leak-clean.
    sOOB3 <- dropResult viewOOB sOOB2
    let liveEnd = St.stLive (St.stStats sOOB3)
    pure $ QC.conjoin
      [ QC.counterexample
          ("PV4c byteAt on view disagreed with reference window bytes (winLen="
            <> show winLen <> ")")
          allOk
      , QC.counterexample
          ("PV4c heap balance: live=" <> show liveEnd <> " baseline=" <> show baseline)
          (liveEnd == baseline)
      ]

-- PV5: Op-transparency.
-- Every E1/E2 string op (length, byteLength, index, byteAt, append, indexOfFromRaw,
-- hash, editDistance, eqString) applied to an NStringView equals the same op
-- applied to the MATERIALIZED copy of that window (same bytes, fresh NString cell).
-- Oracle: 'Data.Text' / 'Data.ByteString' for each op (independent reference).
-- Note: 'append' is checked by verifying the result bytes equal the materialized
-- concatenation.  'index'/'byteAt' are only checked for non-empty windows.
prop_viewOpTransparency :: Property
prop_viewOpTransparency =
  QC.forAll genViewText $ \t ->
  QC.forAll (genViewIndices t) $ \(start, len) ->
    QC.ioProperty $ onBothBackends "PV5" $ \backend -> do
      pSlice      <- lookupStrPrim (T.pack "slice")
      pLength     <- lookupStrPrim (T.pack "length")
      pByteLength <- lookupStrPrim (T.pack "byteLength")
      pIndex      <- lookupStrPrim (T.pack "index")
      pByteAt     <- lookupStrPrim (T.pack "byteAt")
      pAppend     <- lookupStrPrim (T.pack "append")
      pHash       <- lookupStrPrim (T.pack "hash")
      pEditDist   <- lookupStrPrim (T.pack "editDistance")
      pEqString   <- lookupBasePrim (T.pack "eqString")
      let s0            = emptyStoreOn backend
          baseline      = St.stLive (St.stStats s0)
          winText       = T.take len (T.drop start t)
          winBytes      = TxEnc.encodeUtf8 winText
          oracleLen     = toInteger (T.length winText)
          oracleByteLen = toInteger (BS.length winBytes)
          nonEmpty      = not (BS.null winBytes)
          cpIdx         = T.length winText - 1
          byteIdx       = BS.length winBytes - 1
          oracleHash    = toInteger (SZ.szHash winBytes)
          asBool v s    = case St.renderRCValue s v of
                            Right rendered -> rendered == T.pack "True"
                            Left _         -> False
      -- length
      (sa2, s4) <- allocStringOn t s0
      (sv2, s5) <- callSlice pSlice sa2 start len s4
      (mc2, s6) <- allocStringHelper winBytes s5
      (lenView, s7)  <- callStrPrim pLength [sv2] s6
      (lenMat,  s8)  <- callStrPrim pLength [St.RVBox mc2] s7
      rcLenV <- asInt "PV5 length(view)" lenView
      rcLenM <- asInt "PV5 length(mat)"  lenMat
      -- byteLength
      (sa3, s9)  <- allocStringOn t s8
      (sv3, s10) <- callSlice pSlice sa3 start len s9
      (mc3, s11) <- allocStringHelper winBytes s10
      (blView, s12) <- callStrPrim pByteLength [sv3] s11
      (blMat,  s13) <- callStrPrim pByteLength [St.RVBox mc3] s12
      rcBlV <- asInt "PV5 byteLength(view)" blView
      rcBlM <- asInt "PV5 byteLength(mat)"  blMat
      -- index / byteAt (only for non-empty window).
      -- Both ops are tested on the VIEW and the materialized copy; the results
      -- must agree with each other AND with the byte/Text oracle.  'byteAt' on a
      -- view exercises the tag-guarded CHeap fast-path: a WokStringView CAddr
      -- falls through to the byte-window path instead of misreading the cell.
      (indexChecks, s_afterIndex) <-
        if not nonEmpty
          then pure ([], s13)
          else do
            -- index (view vs mat): both use the 'stringBytes' deref path.
            (sa4,  s14) <- allocStringOn t s13
            (sv4,  s15) <- callSlice pSlice sa4 start len s14
            (mc4,  s16) <- allocStringHelper winBytes s15
            let cpIdxLit = St.RVLit (Anf.LInt (toInteger cpIdx))
            (cpView, s17) <- callStrPrim pIndex  [sv4,          cpIdxLit] s16
            (cpMat,  s18) <- callStrPrim pIndex  [St.RVBox mc4, cpIdxLit] s17
            rcCpV <- asChar "PV5 index(view)" cpView
            rcCpM <- asChar "PV5 index(mat)"  cpMat
            -- byteAt (view vs mat): the view path is the tag-guarded CHeap fix.
            (sa5,  s19) <- allocStringOn t s18
            (sv5,  s20) <- callSlice pSlice sa5 start len s19
            (mc5,  s21) <- allocStringHelper winBytes s20
            let byIdxLit = St.RVLit (Anf.LInt (toInteger byteIdx))
            (byView, s22) <- callStrPrim pByteAt [sv5,          byIdxLit] s21
            (byMat,  s23) <- callStrPrim pByteAt [St.RVBox mc5, byIdxLit] s22
            rcByV <- asInt "PV5 byteAt(view)" byView
            rcByM <- asInt "PV5 byteAt(mat)"  byMat
            let oracleByte = toInteger (BS.index winBytes byteIdx)
            pure
              ( [ QC.counterexample
                    ("PV5 index: view=" <> show rcCpV <> " mat=" <> show rcCpM
                      <> " at cp=" <> show cpIdx <> " win=" <> T.unpack winText)
                    (rcCpV == rcCpM)
                , QC.counterexample
                    ("PV5 byteAt: view=" <> show rcByV <> " mat=" <> show rcByM
                      <> " oracle=" <> show oracleByte
                      <> " at byte=" <> show byteIdx <> " win=" <> T.unpack winText)
                    (rcByV == oracleByte && rcByM == oracleByte && rcByV == rcByM)
                ]
              , s23 )
      -- append: result bytes of (view <> mat) == winBytes <> winBytes.
      -- We allocate a second view and a second mat copy for this check.
      (sa6, s_a0) <- allocStringOn t s_afterIndex
      (sv6, s_a1) <- callSlice pSlice sa6 start len s_a0
      (mc6, s_a2) <- allocStringHelper winBytes s_a1
      (sa7, s_a3) <- allocStringOn t s_a2
      (sv7, s_a4) <- callSlice pSlice sa7 start len s_a3
      (mc7, s_a5) <- allocStringHelper winBytes s_a4
      (appVV, s_a6) <- callStrPrim pAppend [sv6, sv7] s_a5
      (appMM, s_a7) <- callStrPrim pAppend [St.RVBox mc6, St.RVBox mc7] s_a6
      appVVBytes <- viewBytes appVV s_a7
      appMMBytes <- viewBytes appMM s_a7
      s_a8 <- dropResult appVV s_a7
      s_a9 <- dropResult appMM s_a8
      -- hash
      (sa8, s_h0) <- allocStringOn t s_a9
      (sv8, s_h1) <- callSlice pSlice sa8 start len s_h0
      (mc8, s_h2) <- allocStringHelper winBytes s_h1
      (hashView, s_h3) <- callStrPrim pHash [sv8] s_h2
      (hashMat,  s_h4) <- callStrPrim pHash [St.RVBox mc8] s_h3
      rcHashV <- asInt "PV5 hash(view)" hashView
      rcHashM <- asInt "PV5 hash(mat)"  hashMat
      -- editDistance (view vs view): for the same bytes this must be 0.
      (sa9,  s_e0) <- allocStringOn t s_h4
      (sv9,  s_e1) <- callSlice pSlice sa9 start len s_e0
      (sa10, s_e2) <- allocStringOn t s_e1
      (sv10, s_e3) <- callSlice pSlice sa10 start len s_e2
      (distVV, s_e4) <- callStrPrim pEditDist [sv9, sv10] s_e3
      rcDistVV <- asInt "PV5 editDistance(view,view)" distVV
      -- eqString (view == same-bytes mat): must be True.
      (sa11, s_q0) <- allocStringOn t s_e4
      (sv11, s_q1) <- callSlice pSlice sa11 start len s_q0
      (mc9,  s_q2) <- allocStringHelper winBytes s_q1
      (eqVal, s_q3) <- callStrPrim pEqString [sv11, St.RVBox mc9] s_q2
      let rcEqVM  = asBool eqVal s_q3
      s_q4 <- dropResult eqVal s_q3
      -- Final heap check.
      let liveEnd = St.stLive (St.stStats s_q4)
      pure $ QC.conjoin $
        [ QC.counterexample
            ("PV5 length view=" <> show rcLenV <> " mat=" <> show rcLenM
              <> " oracle=" <> show oracleLen)
            (rcLenV == oracleLen && rcLenM == oracleLen && rcLenV == rcLenM)
        , QC.counterexample
            ("PV5 byteLength view=" <> show rcBlV <> " mat=" <> show rcBlM
              <> " oracle=" <> show oracleByteLen)
            (rcBlV == oracleByteLen && rcBlM == oracleByteLen && rcBlV == rcBlM)
        , QC.counterexample
            ("PV5 append(view,view)==append(mat,mat): vv=" <> show appVVBytes
              <> " mm=" <> show appMMBytes)
            (appVVBytes == appMMBytes)
        , QC.counterexample
            ("PV5 hash view=" <> show rcHashV <> " mat=" <> show rcHashM
              <> " oracle=" <> show oracleHash)
            (rcHashV == oracleHash && rcHashM == oracleHash && rcHashV == rcHashM)
        , QC.counterexample
            ("PV5 editDistance(view,view same bytes) must be 0: got=" <> show rcDistVV)
            (rcDistVV == 0)
        , QC.counterexample
            ("PV5 eqString(view==mat same bytes) must be True: got=" <> show rcEqVM)
            rcEqVM
        , QC.counterexample
            ("PV5 heap balance: live=" <> show liveEnd <> " baseline=" <> show baseline)
            (liveEnd == baseline)
        ] ++ indexChecks

-- PV6: Cross-type equality.
-- 'eqString' agrees with raw byte equality for every ordered pair drawn from
-- {view, WokString cell (NString), InlineStr}.  Each assertion compares the
-- prim's result to the INDEPENDENT oracle (bytesA == bytesB) -- raw ByteString
-- equality, never a re-derivation of eqString.
--
-- Length constraints determine which (representation, content) pairs are
-- CONSTRUCTIBLE:
--   * a view is ALWAYS > maxInlineStr (7) bytes (a <=7B window is InlineStr);
--   * an InlineStr is ALWAYS <= maxInlineStr (7) bytes;
--   * an NString cell can hold ANY length (a <=7B cell must be FORCED via
--     'allocStringHeapForced', since 'alloc' would intercept it to InlineStr).
-- So (view, inline) with EQUAL bytes is UNCONSTRUCTIBLE (disjoint length ranges);
-- only the DIFFERENT case exists for that pair.
--
-- Pairings exercised (E = equal-bytes -> expect True; D = different -> False):
--   (view, view):     E + D    (two >7B view windows)
--   (view, cell):     E + D    (view vs NString cell, same/different bytes)
--   (view, inline):   D only   (disjoint lengths -> equal is unconstructible)
--   (cell, cell):     E + D    (two NString cells)
--   (cell, inline):   E + D    (E via a FORCED short cell vs equal InlineStr,
--                               proving eqString is byte-based across the
--                               cell/inline boundary, not address-based;
--                               D via a short cell vs a different InlineStr)
--   (inline, inline): E + D    (two InlineStr values)
-- Heap balance is asserted at the end.
prop_viewCrossTypeEquality :: Property
prop_viewCrossTypeEquality =
  QC.forAll genViewText $ \t ->
  QC.forAll (genViewIndices t) $ \(start, len) ->
  QC.forAll genShortText $ \tShort ->
    QC.ioProperty $ onBothBackends "PV6" $ \backend -> do
      pSlice    <- lookupStrPrim (T.pack "slice")
      pEqString <- lookupBasePrim (T.pack "eqString")
      let winText    = T.take len (T.drop start t)
          winBytes   = TxEnc.encodeUtf8 winText
          shortBytes = TxEnc.encodeUtf8 tShort
          -- Different-content string for cross-type-unequal checks: append 'X' to window.
          diffBytes  = winBytes <> BS.pack [0x58]  -- 'X', ASCII, safe to append
          -- A short (<=7B) byte string GUARANTEED to differ from any generated
          -- string: a single NUL byte.  'genUtf8Char' never emits NUL, so this is
          -- distinct from both 'winBytes' and 'shortBytes'.  Used as the
          -- different-content operand for the short-string cross-type pairs, and
          -- it fits InlineStr (1 byte <= 7).
          shortDiffBytes = BS.pack [0x00]
          -- 'eqString' result helper.
          asBool v s = case St.renderRCValue s v of
                         Right rendered -> rendered == T.pack "True"
                         Left _         -> False
          baseline0  = St.stLive (St.stStats (emptyStoreOn backend))
      -- Helper: alloc a view of winBytes (always > 7B -> NStringView).
      let allocView s = do
            (sa, s1) <- allocStringOn t s
            callSlice pSlice sa start len s1
      -- Helper: alloc a cell of winBytes.
      let allocCell s = do
            (a, s1) <- allocStringHelper winBytes s
            pure (St.RVBox a, s1)
      -- Helper: alloc a cell of diffBytes.
      let allocDiff s = do
            (a, s1) <- allocStringHelper diffBytes s
            pure (St.RVBox a, s1)
      -- Helper: alloc an InlineStr of shortBytes (<=7B -> InlineStr).
      let allocInline s = do
            (a, s1) <- allocStringHelper shortBytes s
            pure (St.RVBox a, s1)
      -- Helper: alloc an InlineStr of shortDiffBytes (the guaranteed-different NUL).
      let allocInlineDiff s = do
            (a, s1) <- allocStringHelper shortDiffBytes s
            pure (St.RVBox a, s1)
      -- Helper: alloc a FORCED NString cell holding shortBytes (<=7B).  'alloc'
      -- would intercept <=7B to InlineStr; 'allocStringHeapForced' bypasses that
      -- so we get a real WokString/HAddr cell with short content -- the only way
      -- to exercise the (cell, inline) EQUAL pairing (a cell and an inline that
      -- hold the SAME <=7B bytes but in different representations).
      let allocShortCell s = do
            (a, s1) <- allocStringHeapForced shortBytes s
            pure (St.RVBox a, s1)
      -- Call eqString on two RCValues.
      let callEq lv rv = callStrPrim pEqString [lv, rv]
      let s0 = emptyStoreOn backend
      -- (view, view) same bytes: expect True.
      (va1, s1)  <- allocView s0
      (va2, s2)  <- allocView s1
      (vvEq, s3) <- callEq va1 va2 s2
      let rcVV = asBool vvEq s3
      s4 <- dropResult vvEq s3
      -- (view, view) different: expect False.
      (va3, s5)    <- allocView s4
      (diff1, s6)  <- allocDiff s5
      (vvNe, s7)   <- callEq va3 diff1 s6
      let rcVVNe = asBool vvNe s7
      s8 <- dropResult vvNe s7
      -- (view, cell) same bytes: expect True.
      (va4, s9)   <- allocView s8
      (cell1, s10) <- allocCell s9
      (vcEq, s11) <- callEq va4 cell1 s10
      let rcVC = asBool vcEq s11
      s12 <- dropResult vcEq s11
      -- (view, cell) different bytes: expect False.
      (va5, s13)   <- allocView s12
      (diff2, s14) <- allocDiff s13
      (vcNe, s15)  <- callEq va5 diff2 s14
      let rcVCNe = asBool vcNe s15
      s16 <- dropResult vcNe s15
      -- (cell, cell) same bytes: expect True.
      (cell2, s17) <- allocCell s16
      (cell3, s18) <- allocCell s17
      (ccEq, s19) <- callEq cell2 cell3 s18
      let rcCC = asBool ccEq s19
      s20 <- dropResult ccEq s19
      -- (cell, cell) different: expect False.
      (cell4, s21) <- allocCell s20
      (diff3, s22) <- allocDiff s21
      (ccNe, s23)  <- callEq cell4 diff3 s22
      let rcCCNe = asBool ccNe s23
      s24 <- dropResult ccNe s23
      -- (view, inline) different: expect False.  Equal is unconstructible -- a view
      -- is >7B and an inline is <=7B, so their byte ranges are disjoint.  The oracle
      -- (winBytes == shortDiffBytes) is False here too (disjoint lengths / NUL), so
      -- this both pins the False branch and stays an oracle-faithful comparison.
      (va6, s25)   <- allocView s24
      (inlD1, s26) <- allocInlineDiff s25
      (viEq, s27)  <- callEq va6 inlD1 s26
      let rcVI = asBool viEq s27
      s28 <- dropResult viEq s27
      -- (inline, inline) different: expect False.
      (inl1, s29)  <- allocInline s28
      (inlD2, s30) <- allocInlineDiff s29
      (iiNe, s31)  <- callEq inl1 inlD2 s30
      let rcIINe = asBool iiNe s31
      s32 <- dropResult iiNe s31
      -- (inline, inline) same bytes: expect True.
      (inl2, s33) <- allocInline s32
      (inl3, s34) <- allocInline s33
      (iiEq, s35) <- callEq inl2 inl3 s34
      let rcII = asBool iiEq s35
      s36 <- dropResult iiEq s35
      -- (cell, inline) SAME short bytes: expect True.  The cell is a FORCED short
      -- WokString/HAddr cell; the inline is an InlineStr of the SAME bytes.  Equal
      -- here proves eqString compares BYTES, not addresses, across the cell/inline
      -- representation boundary (a <=7B cell never arises from 'alloc' -- E3 inlines
      -- it -- so this pairing only exists via 'allocStringHeapForced').
      (sc1, s37)  <- allocShortCell s36
      (inl4, s38) <- allocInline s37
      (ciEq, s39) <- callEq sc1 inl4 s38
      let rcCI = asBool ciEq s39
      s40 <- dropResult ciEq s39
      -- (cell, inline) DIFFERENT short bytes: expect False.  Short cell vs the
      -- guaranteed-different NUL inline.
      (sc2, s41)   <- allocShortCell s40
      (inlD3, s42) <- allocInlineDiff s41
      (ciNe, s43)  <- callEq sc2 inlD3 s42
      let rcCINe = asBool ciNe s43
      s44 <- dropResult ciNe s43
      -- Oracle bytes for the cross-type pairs (independent of eqString).
      let oracleVI   = winBytes   == shortDiffBytes  -- (view, inline) diff -> False
          oracleIINe = shortBytes == shortDiffBytes  -- (inline,inline) diff -> usually False
          oracleII   = True                          -- (inline,inline) same bytes
          oracleCI   = shortBytes == shortBytes      -- (cell, inline) same short -> True
          oracleCINe = shortBytes == shortDiffBytes  -- (cell, inline) diff -> usually False
      -- Final heap balance.
      let liveEnd = St.stLive (St.stStats s44)
      pure $ QC.conjoin
        [ QC.counterexample
            ("PV6 (view,view) same bytes: got=" <> show rcVV
              <> " win=" <> show winBytes)
            rcVV
        , QC.counterexample
            ("PV6 (view,view) diff bytes: got=" <> show rcVVNe
              <> " win=" <> show winBytes <> " diff=" <> show diffBytes)
            (not rcVVNe)
        , QC.counterexample
            ("PV6 (view,cell) same bytes: got=" <> show rcVC
              <> " win=" <> show winBytes)
            rcVC
        , QC.counterexample
            ("PV6 (view,cell) diff bytes: got=" <> show rcVCNe)
            (not rcVCNe)
        , QC.counterexample
            ("PV6 (cell,cell) same bytes: got=" <> show rcCC)
            rcCC
        , QC.counterexample
            ("PV6 (cell,cell) diff bytes: got=" <> show rcCCNe)
            (not rcCCNe)
        , QC.counterexample
            ("PV6 (view,inline) diff bytes [equal unconstructible]: got=" <> show rcVI
              <> " oracle=" <> show oracleVI
              <> " win=" <> show winBytes <> " inl=" <> show shortDiffBytes)
            (rcVI == oracleVI)
        , QC.counterexample
            ("PV6 (inline,inline) diff bytes: got=" <> show rcIINe
              <> " oracle=" <> show oracleIINe
              <> " short=" <> show shortBytes <> " diff=" <> show shortDiffBytes)
            (rcIINe == oracleIINe)
        , QC.counterexample
            ("PV6 (inline,inline) same bytes: got=" <> show rcII
              <> " oracle=" <> show oracleII <> " short=" <> show shortBytes)
            (rcII == oracleII)
        , QC.counterexample
            ("PV6 (cell,inline) same short bytes [byte-based, not address]: got=" <> show rcCI
              <> " oracle=" <> show oracleCI <> " short=" <> show shortBytes)
            (rcCI == oracleCI)
        , QC.counterexample
            ("PV6 (cell,inline) diff short bytes: got=" <> show rcCINe
              <> " oracle=" <> show oracleCINe
              <> " short=" <> show shortBytes <> " diff=" <> show shortDiffBytes)
            (rcCINe == oracleCINe)
        , QC.counterexample
            ("PV6 heap balance: live=" <> show liveEnd
              <> " baseline=" <> show baseline0)
            (liveEnd == baseline0)
        ]

rcStringViewPropertyTests :: TestTree
rcStringViewPropertyTests =
  localOption (QuickCheckTests 150) $
    testGroup "rcStringViewProperty (Suite E4: NStringView borrow + transparency)"
      [ testProperty "PV1: borrow-out survival -- view bytes readable after prim drops input"
          prop_viewBorrowOutSurvival
      , testProperty "PV2: nested-flatten -- slice(slice s a b) c d is root-backed, byte-correct"
          prop_viewNestedFlatten
      , testProperty "PV3: window round-trip -- slice bytes agree with Data.Text codepoint oracle"
          prop_viewWindowRoundTrip
      , testProperty "PV4: UTF-8 validity -- every slice result decodes as valid UTF-8"
          prop_viewUtf8Validity
      , testProperty "PV4b: byteSlice split-boundary raises PrimError (concrete multibyte)"
          prop_viewByteSliceSplitError
      , testProperty "PV4c: byteAt on a CHeap WokStringView reads windowed bytes (tag-guard regression)"
          prop_viewByteAtOnView
      , testProperty "PV5: op-transparency -- all E1/E2 ops on view == same op on materialized copy"
          prop_viewOpTransparency
      , testProperty "PV6: cross-type equality -- eqString agrees with byte-eq for (view,cell,inline)"
          prop_viewCrossTypeEquality
      ]

rcArrayPropertyTests :: TestTree
rcArrayPropertyTests =
  localOption (QuickCheckTests 100) $
    testGroup "rc array properties (Suite H: Slice A semantics)"
      [ testProperty "P1: toList (fromList xs) == xs (U64 elements)"
          prop_arrayRoundtrip
      , testProperty "P2: index (set a i v) i == v"
          prop_arraySetIndex
      , testProperty "P3: j /= i => index (set a i v) j == index a j"
          prop_arraySetIndexOther
      , testProperty "P4: length (new k v) == k"
          prop_arrayLengthNew
      , testProperty "P5: length (set a i v) == length a"
          prop_arrayLengthSet
      , testProperty "P6: length (resize a m f) == m"
          prop_arrayLengthResize
      , testProperty "P7a: grow then index new tail slot yields fill"
          prop_arrayResizeGrowFill
      , testProperty "P7b: shrink then index kept slot yields original value"
          prop_arrayResizeShrinkKeep
      , testProperty "P8a: index out of bounds raises PrimError"
          prop_arrayIndexOOB
      , testProperty "P8b: set out of bounds raises PrimError"
          prop_arraySetOOB
      , testProperty "P9: boxed (counted) elements: heap returns to baseline after toList+drop"
          prop_arrayBoxedRCBalance
      , testProperty "P10: set with boxed elements: drop-to-baseline (RC accounting)"
          prop_arraySetBoxed
      , testProperty "P11: resize grow/shrink with boxed elements: drop-to-baseline"
          prop_arrayResizeBoxed
      , testProperty "P12: resize to 0 with boxed elements: full truncation, drop-to-baseline"
          prop_arrayResizeToZeroBoxed
      , testProperty "P13: fromList with boxed elements: drop-to-baseline (RC accounting)"
          prop_arrayFromListBoxed
      ]

-- ---------------------------------------------------------------------------
-- Array Slice C: arrayUnique + arraySetSlotInPlace unit tests
--
-- These tests pin the two store-layer helpers directly on the ABSTRACT backend
-- (HAddr / allocPure / increfPure / dropAddrPure), mirroring the harness style
-- of 'rcArrayNodeTests'. Both helpers ARE now exercised in production: Task 3
-- wired 'arraySet' (Wok.Interp.RC.Prim) to call 'arrayUnique' then
-- 'arraySetSlotInPlace' on the unique fast path. The C/CAddr path is covered
-- end-to-end by the rc-array differential corpus (e.g. 10-set-boxed-unique.wok).

rcArraySliceCTests :: TestTree
rcArraySliceCTests = testGroup "rc array Slice C helpers"
  [ -- -----------------------------------------------------------------------
    -- arrayUnique
    -- -----------------------------------------------------------------------
    testCase "arrayUnique: True for freshly-allocated array (rc 1)" $ do
      -- A freshly allocated NArray has rc=1 (the allocator initialises to 1).
      -- arrayUnique must return True.
      let (a, s1) = St.allocPure (St.NArray [St.RVLit (Anf.LInt 1)]) St.emptyStore
      res <- runExceptT (St.arrayUnique a s1)
      case res of
        Left e  -> assertFailure ("arrayUnique raised: " <> show e)
        Right b -> b @?= True

  , testCase "arrayUnique: False after one incref (rc 2)" $ do
      -- After incref the array is at rc=2 (shared); arrayUnique must return False.
      let (a, s1) = St.allocPure (St.NArray [St.RVLit (Anf.LInt 1)]) St.emptyStore
          s2      = either (error . show) id (St.increfPure a s1)  -- rc 2
      res <- runExceptT (St.arrayUnique a s2)
      case res of
        Left e  -> assertFailure ("arrayUnique raised: " <> show e)
        Right b -> b @?= False

  , testCase "arrayUnique: False for a static/immortal address" $ do
      -- A static NArray (negative HAddr, allocated via allocStatic) is immortal /
      -- uncounted. arrayUnique must return False regardless of its stored rc.
      -- (Static cells have rc=1 by convention but are never counted.)
      let (a, s1) = St.allocStatic (St.NArray [St.RVLit (Anf.LInt 42)]) St.emptyStore
      -- a is a negative HAddr, so isStaticAddr a == True.
      res <- runExceptT (St.arrayUnique a s1)
      case res of
        Left e  -> assertFailure ("arrayUnique raised: " <> show e)
        Right b -> b @?= False

  -- -----------------------------------------------------------------------
  -- arraySetSlotInPlace: inline (literal) elements
  -- -----------------------------------------------------------------------
  , testCase "arraySetSlotInPlace (inline elems): returns old slot, stores new slot, 0 alloc/free" $ do
      -- Build NArray [1, 2, 3], call arraySetSlotInPlace a 1 99.
      -- Old element returned must be RVLit (LInt 2).
      -- The array cell now holds [1, 99, 3].
      -- stAllocs and stFrees are UNCHANGED across the call.
      let s0           = St.emptyStore
          elems        = map (St.RVLit . Anf.LInt) [1, 2, 3]
          (a, s1)      = St.allocPure (St.NArray elems) s0
          allocsBefore = St.stAllocs (St.stStats s1)
          freesBefore  = St.stFrees  (St.stStats s1)
          newEl        = St.RVLit (Anf.LInt 99)
          -- arraySetSlotInPlace now takes encodeSlotC v as its first arg (the C arm
          -- uses it; the abstract/HAddr arm here ignores it). Fail loudly if the
          -- test value is ever non-encodable rather than passing a plausible default.
          enc          = maybe (error "test setup: newEl must be C-encodable") id (St.encodeSlotC newEl)
      res <- runExceptT (St.arraySetSlotInPlace enc a 1 newEl s1)
      case res of
        Left e -> assertFailure ("arraySetSlotInPlace raised: " <> show e)
        Right (oldEl, s2) -> do
          -- old element must be slot 1 of the original array
          oldEl @?= St.RVLit (Anf.LInt 2)
          -- 0 alloc / 0 free
          St.stAllocs (St.stStats s2) @?= allocsBefore
          St.stFrees  (St.stStats s2) @?= freesBefore
          -- array cell now holds [1, 99, 3]
          case St.derefPure a s2 of
            Left e  -> assertFailure ("deref after set raised: " <> show e)
            Right c -> St.cNode c @?= St.NArray [ St.RVLit (Anf.LInt 1)
                                                , St.RVLit (Anf.LInt 99)
                                                , St.RVLit (Anf.LInt 3) ]
          -- stLive unchanged: inline element never allocates a cell
          St.stLive (St.stStats s2) @?= St.stLive (St.stStats s1)

  -- -----------------------------------------------------------------------
  -- arraySetSlotInPlace: boxed (counted) elements
  -- -----------------------------------------------------------------------
  , testCase "arraySetSlotInPlace (boxed elems): old slot returned, new slot stored, drop-to-baseline" $ do
      -- Allocate three boxed cells e0, e1, e2.
      -- Build NArray [e0, e1, e2].  Allocate a fresh boxed newEl.
      -- Call arraySetSlotInPlace a 1 newEl s.
      -- Assert: returned old element == RVBox e1; slot 1 now holds RVBox newEl.
      -- 0 alloc / 0 free across the call (rc unchanged).
      -- Drop the old element (e1 at rc 1 -> freed) then drop a;
      -- heap must return to baseline.
      let s0       = St.emptyStore
          baseline = St.stLive (St.stStats s0)
          (e0, s1) = St.allocPure (St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 0)]) s0
          (e1, s2) = St.allocPure (St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 1)]) s1
          (e2, s3) = St.allocPure (St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 2)]) s2
          (a,  s4) = St.allocPure (St.NArray [St.RVBox e0, St.RVBox e1, St.RVBox e2]) s3
          (newEl, s5) = St.allocPure (St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 99)]) s4
          allocsBefore = St.stAllocs (St.stStats s5)
          freesBefore  = St.stFrees  (St.stStats s5)
          enc2         = maybe (error "test setup: newEl must be C-encodable") id (St.encodeSlotC (St.RVBox newEl))
      res <- runExceptT (St.arraySetSlotInPlace enc2 a 1 (St.RVBox newEl) s5)
      case res of
        Left e -> assertFailure ("arraySetSlotInPlace raised: " <> show e)
        Right (oldEl, s6) -> do
          -- old element must be the address of e1
          oldEl @?= St.RVBox e1
          -- slot 1 of the array is now newEl
          case St.derefPure a s6 of
            Left e  -> assertFailure ("deref after set raised: " <> show e)
            Right c -> St.cNode c @?= St.NArray [ St.RVBox e0
                                                , St.RVBox newEl
                                                , St.RVBox e2 ]
          -- 0 alloc / 0 free from the set itself
          St.stAllocs (St.stStats s6) @?= allocsBefore
          St.stFrees  (St.stStats s6) @?= freesBefore
          -- Drop the old element (e1, rc 1 -> 0, freed), then drop the array
          -- (which cascades drops to e0, newEl, e2 each at rc 1).
          -- After all drops stLive must return to baseline.
          case St.dropAddrPure e1 s6 of
            Left e   -> assertFailure ("drop old element failed: " <> show e)
            Right s7 ->
              case St.dropAddrPure a s7 of
                Left e   -> assertFailure ("drop array failed: " <> show e)
                Right s8 -> St.stLive (St.stStats s8) @?= baseline
  ]

-- ---------------------------------------------------------------------------
-- Region Slice R1 oracle extension (Task 6):
--
--   * 'rcRegionCorpusTests' --- targeted per-file assertions for the four
--     corpus programs under 'test/rc-region/': arena_bytes > 0 for the three
--     arena-routing programs (01/03/04) and == 0 for the heap-only program
--     (02), plus full abstract==C parity on all six stats (allocs/frees/peak/
--     peak_bytes/arena_bytes/arena_peak) and the arena-leak invariant
--     (arena_bytes back to 0 at program end on both backends).
--
--   * 'rcRegionNegativeControl' --- store-level proof the oracle has TEETH:
--     manually misuse 'arenaAllocPure' for a node whose sole reference flows
--     out of the activation (escaping value), skip the scan-out, and assert
--     that the arena-leak invariant fires (stArenaBytes != 0 after close OR
--     stLive > baseline after drop -- proving a routing bug would be caught).
--
-- The four corpus programs are also fed to 'rc differential' / 'rc stats' /
-- 'rcCBackendParity' in 'main' (where they exercise the standard output +
-- heap-accounting + parity harnesses).  The targeted group here adds the
-- ARENA-SPECIFIC assertions that those generic harnesses do not include.
--
-- ABSTRACT == C PARITY ON ARENA STATS:
-- 'withBothBackendsArena' extends 'withBothBackends' with two additional C
-- reads: 'wokStatArenaBytes' and 'wokStatArenaPeak'.  These are the C
-- runtime's own arena counters (distinct from the counted 'wok_stat_allocs'
-- etc.) and must bit-for-bit equal the abstract 'stArenaBytes'/'stArenaPeak'
-- because both backends charge the SAME 'wouldBeCBytes' per arena cell (spec
-- §6).  A divergence here means the routing decision was not identical on
-- both backends -- the headline oracle signal.

-- | Run one region corpus file through BOTH backends; return
-- @(absResult, cResult, cHeapAllocs, cPeakBytes, cArenaBytes, cArenaPeak)@.
-- The C heap is created fresh per program and freed via 'finally' so a
-- thrown exception cannot leak the native pointer.  Both arena counters are
-- read BEFORE the free (they are zeroed by 'wok_heap_free' -- spec §3.1).
withBothBackendsArena
  :: FilePath
  -> IO ( Either IV.RuntimeError RCM.RCRun
        , Either IV.RuntimeError RCM.RCRun
        , Word64   -- ^ cHeapAllocs (the C heap's own alloc counter)
        , Word64   -- ^ cPeakBytes  (C wok_stat_peak_bytes)
        , Word64   -- ^ cArenaBytes (C wok_stat_arena_bytes at program end)
        , Word64   -- ^ cArenaPeak  (C wok_stat_arena_peak)
        )
withBothBackendsArena path = do
  cm   <- rcParityPrepare path
  absR <- RCM.runModuleRCWith St.AbstractHeap cm
  hp   <- Heap.wokHeapNew
  (cR, cAllocs, cPeakBytes, cArenaBytes, cArenaPeak) <-
    (do c  <- RCM.runModuleRCWith (St.CHeap hp) cm
        a  <- Heap.wokStatAllocs hp
        pb <- Heap.wokStatPeakBytes hp
        ab <- Heap.wokStatArenaBytes hp
        ap <- Heap.wokStatArenaPeak hp
        pure (c, a, pb, ab, ap))
    `Control.Exception.finally` Heap.wokHeapFree hp
  pure (absR, cR, cAllocs, cPeakBytes, cArenaBytes, cArenaPeak)

-- | Full arena-parity assertion for one region corpus program.
-- Checks all six stat pairs (allocs/frees/peak/peak_bytes/arena_bytes/
-- arena_peak) abstract==C, plus:
--   * counted-heap leak freedom: stLive == baseline, allocs - frees == baseline
--   * arena-leak invariant: arena_bytes == 0 at program end (every open was closed)
rcRegionParityHarness :: FilePath -> Assertion
rcRegionParityHarness path = do
  (absR, cR, _cAllocs, cPeakBytes, cArenaBytes, cArenaPeak) <-
    withBothBackendsArena path
  case (absR, cR) of
    (Right a, Right c) -> do
      let aSt = RCM.rcStats a
          cSt = RCM.rcStats c
          bl  = RCM.rcBaseline c
      assertEqual (path <> ": output parity")
        (RCM.rcOutput a) (RCM.rcOutput c)
      -- Counted heap: abstract == C
      assertEqual (path <> ": allocs parity")
        (St.stAllocs aSt) (St.stAllocs cSt)
      assertEqual (path <> ": frees parity")
        (St.stFrees aSt) (St.stFrees cSt)
      assertEqual (path <> ": peak parity")
        (St.stPeak aSt) (St.stPeak cSt)
      assertEqual (path <> ": peak_bytes parity")
        (fromIntegral (St.stPeakBytes aSt) :: Word64) cPeakBytes
      -- Arena: abstract == C (both are 0 after program end; peak may be > 0)
      assertEqual (path <> ": arena_bytes parity (abstract == C at end)")
        (fromIntegral (St.stArenaBytes aSt) :: Word64) cArenaBytes
      assertEqual (path <> ": arena_peak parity (abstract == C high-water)")
        (fromIntegral (St.stArenaPeak aSt) :: Word64) cArenaPeak
      -- Arena-leak invariant: every open was closed; arena back to 0 at end
      assertEqual (path <> ": arena-leak invariant (abstract): arena_bytes == 0 at end")
        (0 :: Int) (St.stArenaBytes aSt)
      assertEqual (path <> ": arena-leak invariant (C): arena_bytes == 0 at end")
        (0 :: Word64) cArenaBytes
      -- Counted-heap leak freedom
      assertEqual (path <> ": baseline parity")
        (RCM.rcBaseline a) (RCM.rcBaseline c)
      assertEqual (path <> ": no counted leak (C) -- stLive returns to baseline")
        bl (St.stLive cSt)
      assertEqual (path <> ": no counted leak (C) -- allocs - frees == baseline")
        bl (St.stAllocs cSt - St.stFrees cSt)
    (Left e, _) ->
      assertFailure (path <> ": abstract backend FAILED: " <> show e)
    (_, Left e) ->
      assertFailure (path <> ": C backend FAILED: " <> show e)

-- | Targeted arena-stats assertions for the four Region Slice R1 corpus
-- programs.  The standard 'rc differential' / 'rc stats' / 'rcCBackendParity'
-- groups (in 'main') cover output parity + the standard heap-accounting
-- invariants.  This group adds:
--
--   * arena_bytes > 0 at peak for the three arena-routing programs (01/03/04):
--     proves the C-arena path ('wok_arena_alloc') was actually reached, not
--     just asserted by the analysis.  'cArenaPeak' is the C heap's high-water
--     mark (not reset at program end) -- it is > 0 iff at least one arena
--     cell was allocated during the run.
--
--   * arena_bytes == 0 throughout for the heap-only program (02): proves the
--     routing correctly kept the escaping Pair on the counted heap.
--
--   * Full six-stat parity + arena-leak invariant via 'rcRegionParityHarness'.
rcRegionCorpusTests :: TestTree
rcRegionCorpusTests = testGroup "rc-region-corpus"
  [ -- -----------------------------------------------------------------------
    -- 01-scratch-struct: Pair U64 U64, non-escaping, C-eligible NCon.
    -- THE C-ARENA PATH: wok_arena_alloc fires for the Pair on CHeap; the
    -- abstract arenaAllocPure fires on AbstractHeap.  Both charge
    -- 'wouldBeCBytes' = 8 + 8*2 = 24 bytes to their respective arena counters.
    -- At program end arena_bytes returns to 0 (the arena is closed); arena_peak
    -- == 24 (one Pair cell was live at peak).  Counted allocs == 0 extra (the
    -- Pair is uncounted).
    testCase "01-scratch-struct: Pair routed to C-arena (arena_peak > 0)" $ do
      (absR, cR, _cAllocs, _cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/01-scratch-struct.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is 7" (T.pack "7") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          -- The abstract backend must have seen arena activity too.
          assertBool "abstract arena_peak > 0 (Pair was arena-routed)"
            (St.stArenaPeak (RCM.rcStats a) > 0)
          -- The C backend must have seen arena activity (proves C path fired).
          assertBool "C arena_peak > 0 (wok_arena_alloc was reached)"
            (cArenaPeak > 0)
          -- Arena-leak invariant: back to 0 at end.
          assertEqual "abstract arena_bytes == 0 at end"
            (0 :: Int) (St.stArenaBytes (RCM.rcStats a))
          assertEqual "C arena_bytes == 0 at end"
            (0 :: Word64) _cArenaBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , testCase "01-scratch-struct: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/01-scratch-struct.wok"

  , -- -----------------------------------------------------------------------
    -- 02-escape-heap: Pair returned from makePair -> escapes -> Heap.
    -- NEGATIVE ROUTING CONTROL (at the routing level, not oracle level): the
    -- Pair must NOT be arena-routed.  arena_peak must be 0 on both backends.
    testCase "02-escape-heap: escaping Pair is NOT arena-routed (arena_peak == 0)" $ do
      (absR, cR, _cAllocs, _cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/02-escape-heap.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is 10" (T.pack "10") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "abstract arena_peak == 0 (no arena routing fired)"
            (0 :: Int) (St.stArenaPeak (RCM.rcStats a))
          assertEqual "C arena_peak == 0 (no arena routing fired)"
            (0 :: Word64) cArenaPeak
          -- The Pair went to the counted heap: at least one counted alloc.
          assertBool "counted allocs > 0 (Pair is on the counted heap)"
            (St.stAllocs (RCM.rcStats c) > 0)
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , testCase "02-escape-heap: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/02-escape-heap.wok"

  , -- -----------------------------------------------------------------------
    -- 03-pure-fastpath: Triple U64 U64 U64, non-escaping, all-scalar children.
    -- No counted children -> arena_close scan-out is EMPTY (fast path).
    -- arena_peak > 0 proves the arena cell was allocated; counted allocs are
    -- the same as if the Triple were never allocated at all (0 extra).
    testCase "03-pure-fastpath: Triple routed to arena, scan-out is empty (arena_peak > 0)" $ do
      (absR, cR, _cAllocs, _cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/03-pure-fastpath.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is 6" (T.pack "6") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          assertBool "abstract arena_peak > 0 (Triple was arena-routed)"
            (St.stArenaPeak (RCM.rcStats a) > 0)
          assertBool "C arena_peak > 0 (wok_arena_alloc was reached)"
            (cArenaPeak > 0)
          assertEqual "abstract arena_bytes == 0 at end (scan-out: empty, fast path)"
            (0 :: Int) (St.stArenaBytes (RCM.rcStats a))
          assertEqual "C arena_bytes == 0 at end"
            (0 :: Word64) _cArenaBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , testCase "03-pure-fastpath: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/03-pure-fastpath.wok"

  , -- -----------------------------------------------------------------------
    -- 04-counted-scanout: Wrap holds a counted Box child.
    -- THE SCAN-OUT PATH: at arena_close the Wrap's counted Box child is dropped
    -- exactly once (on both backends).  arena_peak > 0 proves the Wrap was
    -- arena-routed; counted allocs >= 1 (the Box is Heap); heap returns to
    -- baseline (the scan-out freed the Box correctly).
    testCase "04-counted-scanout: Wrap arena-routed, Box counted, scan-out fires (arena_peak > 0)" $ do
      (absR, cR, _cAllocs, _cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/04-counted-scanout.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is 42" (T.pack "42") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          assertBool "abstract arena_peak > 0 (Wrap was arena-routed)"
            (St.stArenaPeak (RCM.rcStats a) > 0)
          assertBool "C arena_peak > 0 (wok_arena_alloc was reached)"
            (cArenaPeak > 0)
          -- The Box is a counted child: at least one counted alloc fired.
          assertBool "counted allocs > 0 (Box is on the counted heap)"
            (St.stAllocs (RCM.rcStats c) > 0)
          -- Arena-leak: Wrap's arena scope was properly closed.
          assertEqual "abstract arena_bytes == 0 at end (scan-out dropped Box)"
            (0 :: Int) (St.stArenaBytes (RCM.rcStats a))
          assertEqual "C arena_bytes == 0 at end"
            (0 :: Word64) _cArenaBytes
          -- Counted heap returns to baseline (scan-out dropped Box exactly once).
          assertEqual "no counted leak: stLive returns to baseline"
            (RCM.rcBaseline c) (St.stLive (RCM.rcStats c))
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , testCase "04-counted-scanout: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/04-counted-scanout.wok"

  , -- -----------------------------------------------------------------------
    -- 05-letrec-head-capture-escape: REGRESSION for the capstone-review UAF.
    -- A boxed closure 'p' is captured by a LetRec member 'f' PURELY AS A CALL
    -- HEAD ('p x'), and 'f' is RETURNED, so the group's shared NEnv (holding 'p')
    -- outlives 'run'.  The bug mis-tagged 'p' -> Arena (aliasEscapeStep exempts the
    -- call head), so 'run's arena close bulk-freed 'p' while the escaped env still
    -- pointed at it ("use-after-free: addr 0" instead of 15).  THE FIX: 'p' must be
    -- Heap, 'run' opens no arena (arena_peak == 0), output is 15, heap balanced.
    testCase "05-letrec-head-capture-escape: head-only LetRec capture -> Heap (no UAF)" $ do
      (absR, cR, _cAllocs, _cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/05-letrec-head-capture-escape.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "output is 15" (T.pack "15") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          -- The captured-and-escaping closure went to the counted heap: NO arena.
          assertEqual "abstract arena_peak == 0 (head-only capture is NOT arena-routed)"
            (0 :: Int) (St.stArenaPeak (RCM.rcStats a))
          assertEqual "C arena_peak == 0 (no arena routing fired)"
            (0 :: Word64) cArenaPeak
          -- Heap balanced on both backends (no UAF, no leak): stLive == baseline.
          assertEqual "no counted leak: stLive returns to baseline (C)"
            (RCM.rcBaseline c) (St.stLive (RCM.rcStats c))
          assertEqual "no counted leak: stLive returns to baseline (abstract)"
            (RCM.rcBaseline a) (St.stLive (RCM.rcStats a))
        (Left e, _) -> assertFailure ("abstract FAILED (the UAF regression): " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (the UAF regression): " <> show e)

  , testCase "05-letrec-head-capture-escape: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/05-letrec-head-capture-escape.wok"

  , -- -----------------------------------------------------------------------
    -- 06-string-literal-discard (Slice E1, Task 3 -> updated for E3 Task 1):
    -- "hi" (2 ASCII bytes) is bound and DISCARDED. Under E3, "hi" is InlineStr
    -- (0 allocs, 0 peak_bytes). The Perceus __rc_drop on the binder is a no-op
    -- (InlineStr is uncounted). Both backends: allocs == frees == 0 beyond baseline.
    testCase "06-string-literal-discard: InlineStr immediate, 0 allocs, 0 peak_bytes (E3)" $ do
      (absR, cR, _cAllocs, cPeakBytes, _cArenaBytes, cArenaPeak) <-
        withBothBackendsArena "test/rc-region/06-string-literal-discard.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          let aSt = RCM.rcStats a
              cSt = RCM.rcStats c
          assertEqual "output is 5" (T.pack "5") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          -- E3: "hi" is InlineStr (0 counted allocs beyond baseline).
          assertEqual "E3: string is InlineStr (allocs == baseline)"
            (RCM.rcBaseline c) (St.stAllocs cSt)
          -- Balanced: no leak.
          assertEqual "no counted leak (C): stLive == baseline"
            (RCM.rcBaseline c) (St.stLive cSt)
          assertEqual "no counted leak (C): allocs - frees == baseline"
            (RCM.rcBaseline c) (St.stAllocs cSt - St.stFrees cSt)
          assertEqual "no counted leak (abstract): stLive == baseline"
            (RCM.rcBaseline a) (St.stLive aSt)
          assertEqual "no counted leak (abstract): allocs - frees == baseline"
            (RCM.rcBaseline a) (St.stAllocs aSt - St.stFrees aSt)
          -- E3: InlineStr has no cell; peak_bytes == 0.
          assertEqual "E3: C peak_bytes == 0 (InlineStr has no cell)"
            (0 :: Word64) cPeakBytes
          assertEqual "E3: abstract peak_bytes == 0"
            (0 :: Word64) (fromIntegral (St.stPeakBytes aSt))
          -- InlineStr is never arena-routed.
          assertEqual "abstract arena_peak == 0 (InlineStr is not arena-routed)"
            (0 :: Int) (St.stArenaPeak aSt)
          assertEqual "C arena_peak == 0 (InlineStr is not arena-routed)"
            (0 :: Word64) cArenaPeak
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , testCase "06-string-literal-discard: full six-stat parity + arena-leak invariant" $
      rcRegionParityHarness "test/rc-region/06-string-literal-discard.wok"
  ]

-- ---------------------------------------------------------------------------
-- Region Slice R1 negative control: the oracle has TEETH.
--
-- This group proves the oracle has TEETH by running a deliberately BROKEN
-- close (one that SKIPS the scan-out) and asserting the oracle's OWN
-- invariant fails on its output, contrasted with the correct close which
-- passes.  The pair (broken leaks / correct does not) is the genuine teeth:
-- it shows the scan-out is LOAD-BEARING and that the differential oracle's
-- @stLive == baseline@ assertion catches its absence.
--
-- THE SHAPE (the 04-counted-scanout cohort, at the store level):
--   * an arena 'Wrap' cell that OWNS a counted 'Box' child (the scan-out
--     target).
--   * 'closeSkippingScanOut' = the BROKEN close: pop the arena frame and zero
--     'stArenaBytes' (so the close "ran" -- arena_bytes back to 0), but DO NOT
--     drop the counted children.  This is exactly the bug a mis-implemented
--     'arenaClose' (or a missing scan-out step) would produce.
--   * Assert: the broken close LEAKS the Box ('stLive' stays ABOVE baseline)
--     even though 'stArenaBytes == 0', so the oracle's @stLive == baseline@
--     check FAILS on its output.
--   * Contrast: the real 'arenaClose' drops the Box (scan-out fires), so
--     'stLive == baseline' -- the oracle PASSES.
--
-- This is the store-level analogue of 'rcTeethTests' (Perceus teeth via
-- 'insertRCMutated') and 'rcFbipFaultInjection' (FBIP teeth): a real broken
-- operation, and proof the oracle rejects it.

-- | A BROKEN arena close that SKIPS the scan-out (the deliberate bug). Pops the
-- innermost 'stArena' frame and zeroes 'stArenaBytes' (so the close appears to
-- have run -- arena_bytes returns to baseline), but does NOT drop the arena
-- cells' counted children.  A correct close ('St.arenaClose') drops those
-- children first; omitting that step leaks every counted child of an arena cell.
-- Built purely from the public 'Store'/'Stats' record fields so it does not
-- depend on the abstract heap's internal address layout.
closeSkippingScanOut :: St.Store -> St.Store
closeSkippingScanOut s = case St.stArena s of
  []         -> s  -- no open frame: nothing to (mis-)close
  (_ : rest) ->
    s { St.stArena = rest                          -- pop the frame (close "ran")
      , St.stStats = (St.stStats s)
          { St.stArenaBytes = 0 }                  -- zero arena bytes (looks closed)
      }                                            -- but the counted child is NEVER dropped

rcRegionNegativeControl :: TestTree
rcRegionNegativeControl = testGroup "rc-region-negative-control"
  [ testCase "skipped scan-out LEAKS the counted child; the correct close does not (oracle teeth)" $ do
      -- Build the 04-style state: an arena 'Wrap' owning a counted 'Box'.
      let s0   = St.emptyStore
          base = St.stLive (St.stStats s0)
          s1   = St.arenaOpen s0
          -- The counted child: a Box on the COUNTED heap (rc 1, live).
          (box, s2) = St.allocPure (St.NCon (T.pack "Box") [St.RVLit (Anf.LInt 7)]) s1
          -- The arena cell: a Wrap OWNING the counted Box (its only reference).
          (_wrap, s3) = St.arenaAllocPure (St.NCon (T.pack "Wrap") [St.RVBox box]) s2

      -- Sanity: before either close, the Box is live and the arena is non-empty.
      assertEqual "the counted Box is live before close" (base + 1) (St.stLive (St.stStats s3))
      assertBool  "arena_bytes > 0 before close" (St.stArenaBytes (St.stStats s3) > 0)

      -- (A) THE BROKEN CLOSE: skip the scan-out. arena_bytes returns to 0 (the
      -- close "ran"), but the Box's only reference (in the Wrap's slot) is never
      -- dropped, so it LEAKS: stLive stays ABOVE baseline.
      let sBroken = closeSkippingScanOut s3
      assertEqual "broken close zeroes arena_bytes (it appears to have run)"
        0 (St.stArenaBytes (St.stStats sBroken))
      -- THE TOOTH: the oracle's own @stLive == baseline@ assertion FAILS on the
      -- broken close's output -- the skipped scan-out genuinely leaked the Box.
      assertBool
        ("ORACLE TOOTH: broken scan-out leaks the counted child -> the oracle's "
           <> "stLive==baseline assertion FAILS on it (stLive="
           <> show (St.stLive (St.stStats sBroken)) <> ", baseline=" <> show base <> ")")
        (St.stLive (St.stStats sBroken) /= base)

      -- (B) THE CORRECT CLOSE: 'St.arenaClose' runs the scan-out, dropping the
      -- Box exactly once. stLive returns to baseline -- the oracle PASSES.
      eGood <- runExceptT (St.arenaClose s3)
      case eGood of
        Left err -> assertFailure ("arenaClose failed: " <> show err)
        Right sGood -> do
          assertEqual "correct close returns arena_bytes to baseline"
            0 (St.stArenaBytes (St.stStats sGood))
          assertEqual "correct close: scan-out dropped the Box, stLive == baseline"
            base (St.stLive (St.stStats sGood))
          -- The contrast is the teeth: the SAME oracle invariant
          -- (stLive == baseline) PASSES on the correct close and FAILS on the
          -- broken one, so a missing scan-out would be caught by the corpus
          -- harness, never silently green.
          assertBool "the broken and correct closes DIFFER on stLive (scan-out is load-bearing)"
            (St.stLive (St.stStats sBroken) /= St.stLive (St.stStats sGood))

  , testCase "pure-cohort close needs no scan-out; the broken close agrees there (no false alarm)" $ do
      -- A pure-data arena cohort (no counted children) is the fast path: both
      -- the correct and the (scan-out-skipping) broken close must agree, because
      -- there is nothing to scan out. This guards against the teeth firing
      -- spuriously on a fast-path cohort.
      let s0   = St.emptyStore
          base = St.stLive (St.stStats s0)
          s1   = St.arenaOpen s0
          -- A Pair of two inline literals: NO counted children.
          (_pair, s2) = St.arenaAllocPure
                          (St.NCon (T.pack "Pair") [St.RVLit (Anf.LInt 3), St.RVLit (Anf.LInt 4)]) s1
      assertBool "arena_bytes > 0 before close" (St.stArenaBytes (St.stStats s2) > 0)

      -- The broken close (skipped scan-out) here leaks NOTHING -- the cohort has
      -- no counted children -- so stLive stays at baseline, same as the correct
      -- close. (The teeth fire only when there is a counted child to leak.)
      let sBroken = closeSkippingScanOut s2
      assertEqual "broken close zeroes arena_bytes" 0 (St.stArenaBytes (St.stStats sBroken))
      assertEqual "pure cohort: broken close leaks nothing (stLive == baseline)"
        base (St.stLive (St.stStats sBroken))

      eGood <- runExceptT (St.arenaClose s2)
      case eGood of
        Left err -> assertFailure ("arenaClose failed: " <> show err)
        Right sGood -> do
          assertEqual "correct close returns arena_bytes to baseline"
            0 (St.stArenaBytes (St.stStats sGood))
          assertEqual "correct close leaves stLive at baseline"
            base (St.stLive (St.stStats sGood))
          -- On the pure cohort, broken == correct: the teeth correctly stay
          -- silent (no scan-out to skip).
          assertEqual "pure cohort: broken and correct closes AGREE on stLive"
            (St.stLive (St.stStats sBroken)) (St.stLive (St.stStats sGood))
  ]

-- ---------------------------------------------------------------------------
-- Bytes Slice E6: QuickCheck properties
--
-- These properties run on the ABSTRACT backend only (the differential corpus
-- covers the CHeap path).  They verify:
--   PB1  toList . fromList is identity on byte lists in 0..255
--   PB2  length (fromList xs) == length xs
--   PB3  index (fromList xs) i == xs !! i  for valid i
--   PB4  eqBytes reflexive: fromList xs == fromList xs
--   PB5  eqBytes antisymmetric: xs /= ys => not (eqBytes xs ys)
--   PB6  fromBytes (toBytes s) == Some s'  content-equal: covered by corpus files
--          26-frombytes-tobytes-ascii-content.wok (ASCII) and
--          27-frombytes-tobytes-multibyte-content.wok (multibyte), both exercised
--          on the abstract and C-heap backends via the differential/C-parity oracles.
--   PB7  validators agree on arbitrary [Word8]: Utf8.validateUtf8 == wokValidateUtf8
-- ---------------------------------------------------------------------------

-- | Look up a Bytes prim by name under Bytes.
lookupBytesPrim :: Text -> IO St.RCPrim
lookupBytesPrim = lookupPrimQ (T.pack "Bytes")

-- | Look up eqBytes under Base.
lookupEqBytesPrim :: IO St.RCPrim
lookupEqBytesPrim = lookupPrimQ (T.pack "Base") (T.pack "eqBytes")

-- | Build a Cons/Nil spine of RVLit (LInt n) values from a list of integers,
-- using the abstract heap only.
buildNilSpine :: [Integer] -> St.Store -> IO (St.RCValue, St.Store)
buildNilSpine ns s0 = do
  nilRes <- runExceptT (St.alloc (St.NCon (T.pack "Nil") []) s0)
  (nilAddr, sn) <- case nilRes of
    Right r -> pure r
    Left e  -> assertFailure ("buildNilSpine: nil alloc: " <> show e)
  let nilVal = St.RVBox nilAddr
      go []       (tl, st) = pure (tl, st)
      go (v : vs) (tl, st) = do
        (rest, st1) <- go vs (tl, st)
        let (ca, st2) = St.allocPure (St.NCon (T.pack "Cons") [St.RVLit (Anf.LInt v), rest]) st1
        pure (St.RVBox ca, st2)
  go ns (nilVal, sn)

-- PB1: toList (fromList xs) is identity on byte lists 0..255
prop_bytesToListFromList :: Property
prop_bytesToListFromList =
  QC.forAll (QC.listOf (QC.choose (0, 255) :: QC.Gen Integer)) $ \ns ->
    QC.ioProperty $ do
      pFromList <- lookupBytesPrim (T.pack "fromList")
      pToList   <- lookupBytesPrim (T.pack "toList")
      let s0 = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (spine, s1) <- buildNilSpine ns s0
      (bytesVal, s2) <- callPrim pFromList [spine] s1
      (listVal, s3)  <- callPrim pToList   [bytesVal] s2
      case St.renderRCValue s3 listVal of
        Left e  -> do
          _ <- dropResult listVal s3
          assertFailure ("PB1 render failed: " <> show e)
        Right rendered -> do
          s4 <- dropResult listVal s3
          assertEqual "PB1: heap must return to baseline" baseline (St.stLive (St.stStats s4))
          let expected = T.pack ("[" <> intercalateComma (map show ns) <> "]")
          pure (rendered == expected)
  where
    intercalateComma []     = ""
    intercalateComma [x]    = x
    intercalateComma (x:xs) = x <> ", " <> intercalateComma xs

-- PB2: length (fromList xs) == length xs
prop_bytesLength :: Property
prop_bytesLength =
  QC.forAll (QC.listOf (QC.choose (0, 255) :: QC.Gen Integer)) $ \ns ->
    QC.ioProperty $ do
      pFromList <- lookupBytesPrim (T.pack "fromList")
      pLength   <- lookupBytesPrim (T.pack "length")
      let s0 = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (spine, s1) <- buildNilSpine ns s0
      (bytesVal, s2) <- callPrim pFromList [spine] s1
      (lenVal, s3)   <- callPrim pLength   [bytesVal] s2
      case lenVal of
        St.RVLit (Anf.LInt got) -> do
          assertEqual "PB2: heap must return to baseline" baseline (St.stLive (St.stStats s3))
          pure (got == toInteger (length ns))
        other -> assertFailure ("PB2: expected RVLit (LInt _), got: " <> show other)

-- PB3: index (fromList xs) i == xs !! i  for a valid i
prop_bytesIndex :: Property
prop_bytesIndex =
  QC.forAll (QC.choose (1, 20) :: QC.Gen Int) $ \n ->
  QC.forAll (QC.vectorOf n (QC.choose (0, 255) :: QC.Gen Integer)) $ \ns ->
  QC.forAll (QC.choose (0, n - 1) :: QC.Gen Int) $ \i ->
    QC.ioProperty $ do
      pFromList <- lookupBytesPrim (T.pack "fromList")
      pIndex    <- lookupBytesPrim (T.pack "index")
      let s0 = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (spine, s1)    <- buildNilSpine ns s0
      (bytesVal, s2) <- callPrim pFromList [spine] s1
      (el, s3)       <- callPrim pIndex [bytesVal, St.RVLit (Anf.LInt (fromIntegral i))] s2
      case el of
        St.RVLit (Anf.LInt got) -> do
          assertEqual "PB3: heap must return to baseline" baseline (St.stLive (St.stStats s3))
          pure (got == ns !! i)
        other -> assertFailure ("PB3: expected RVLit (LInt _), got: " <> show other)

-- PB4: eqBytes reflexive -- fromList xs == fromList xs
prop_bytesEqReflexive :: Property
prop_bytesEqReflexive =
  QC.forAll (QC.listOf (QC.choose (0, 255) :: QC.Gen Integer)) $ \ns ->
    QC.ioProperty $ do
      pFromList <- lookupBytesPrim (T.pack "fromList")
      pEqBytes  <- lookupEqBytesPrim
      let s0 = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (spine1, s1) <- buildNilSpine ns s0
      (spine2, s2) <- buildNilSpine ns s1
      (bv1, s3) <- callPrim pFromList [spine1] s2
      (bv2, s4) <- callPrim pFromList [spine2] s3
      (eqVal, s5) <- callPrim pEqBytes [bv1, bv2] s4
      case St.renderRCValue s5 eqVal of
        Left e  -> assertFailure ("PB4: render failed: " <> show e)
        Right rendered -> do
          s6 <- dropResult eqVal s5
          assertEqual "PB4: heap must return to baseline" baseline (St.stLive (St.stStats s6))
          pure (rendered == T.pack "True")

-- PB5: eqBytes antisymmetric -- when lists differ, eqBytes returns False
prop_bytesEqAntisymmetric :: Property
prop_bytesEqAntisymmetric =
  QC.forAll (QC.listOf (QC.choose (0, 255) :: QC.Gen Integer)) $ \xs ->
  QC.forAll (QC.listOf (QC.choose (0, 255) :: QC.Gen Integer) `QC.suchThat` (/= xs)) $ \ys ->
    QC.ioProperty $ do
      pFromList <- lookupBytesPrim (T.pack "fromList")
      pEqBytes  <- lookupEqBytesPrim
      let s0 = St.emptyStore
          baseline = St.stLive (St.stStats s0)
      (spine1, s1) <- buildNilSpine xs s0
      (spine2, s2) <- buildNilSpine ys s1
      (bv1, s3) <- callPrim pFromList [spine1] s2
      (bv2, s4) <- callPrim pFromList [spine2] s3
      (eqVal, s5) <- callPrim pEqBytes [bv1, bv2] s4
      case St.renderRCValue s5 eqVal of
        Left e  -> assertFailure ("PB5: render failed: " <> show e)
        Right rendered -> do
          s6 <- dropResult eqVal s5
          assertEqual "PB5: heap must return to baseline" baseline (St.stLive (St.stStats s6))
          pure (rendered == T.pack "False")

rcBytesPropertyTests :: TestTree
rcBytesPropertyTests =
  localOption (QuickCheckTests 100) $
    testGroup "rc bytes properties (Suite E6: Bytes semantics)"
      [ testProperty "PB1: toList (fromList xs) == xs for bytes in 0..255"
          prop_bytesToListFromList
      , testProperty "PB2: length (fromList xs) == length xs"
          prop_bytesLength
      , testProperty "PB3: index (fromList xs) i == xs !! i for valid i"
          prop_bytesIndex
      , testProperty "PB4: eqBytes reflexive -- fromList xs == fromList xs"
          prop_bytesEqReflexive
      , testProperty "PB5: eqBytes antisymmetric -- xs /= ys => not (eqBytes xs ys)"
          prop_bytesEqAntisymmetric
      ]

-- ---------------------------------------------------------------------------
-- Bytes Slice E6: Haskell <-> C validator agreement tests
--
-- Assert that 'Wok.Interp.Utf8.validateUtf8' (the Haskell pure oracle) agrees
-- with 'wok_validate_utf8' (the Hoehrmann DFA in C) on every input.  The C DFA
-- is called via FFI through 'Data.ByteString.Unsafe.unsafeUseAsCStringLen' to
-- pass a raw pointer without copying.
-- ---------------------------------------------------------------------------

-- | Call the C DFA validator on a ByteString via FFI.
-- Returns True iff the C side returns 1 (valid UTF-8).
cValidateUtf8 :: BS.ByteString -> IO Bool
cValidateUtf8 bs =
  BSU.unsafeUseAsCStringLen bs $ \(p, len) ->
    (== 1) <$> Heap.wokValidateUtf8 (castPtr p) (fromIntegral len)

-- | QuickCheck property: Utf8.validateUtf8 and wok_validate_utf8 agree on
-- arbitrary byte sequences drawn as lists of Word8.
prop_validatorAgreement :: Property
prop_validatorAgreement =
  QC.forAll (QC.listOf (QC.arbitrary :: QC.Gen Word8)) $ \ws ->
    QC.ioProperty $ do
      let bs      = BS.pack ws
          haskell = Utf8.validateUtf8 bs
      c <- cValidateUtf8 bs
      pure (haskell == c)

bytesValidatorAgreementTests :: TestTree
bytesValidatorAgreementTests =
  localOption (QuickCheckTests 500) $
    testGroup "Bytes E6: Haskell <-> C validator agreement"
      [ testCase "valid: empty" $ do
          c <- cValidateUtf8 (BS.pack [])
          Utf8.validateUtf8 (BS.pack []) @?= c
      , testCase "valid: ASCII 'A'" $ do
          c <- cValidateUtf8 (BS.pack [0x41])
          Utf8.validateUtf8 (BS.pack [0x41]) @?= c
      , testCase "valid: 2-byte U+00E9 (e-acute)" $ do
          c <- cValidateUtf8 (BS.pack [0xC3, 0xA9])
          Utf8.validateUtf8 (BS.pack [0xC3, 0xA9]) @?= c
      , testCase "valid: 3-byte U+20AC (euro sign)" $ do
          c <- cValidateUtf8 (BS.pack [0xE2, 0x82, 0xAC])
          Utf8.validateUtf8 (BS.pack [0xE2, 0x82, 0xAC]) @?= c
      , testCase "valid: 4-byte U+1F600 (emoji)" $ do
          c <- cValidateUtf8 (BS.pack [0xF0, 0x9F, 0x98, 0x80])
          Utf8.validateUtf8 (BS.pack [0xF0, 0x9F, 0x98, 0x80]) @?= c
      , testCase "valid: U+10FFFF (last valid scalar)" $ do
          c <- cValidateUtf8 (BS.pack [0xF4, 0x8F, 0xBF, 0xBF])
          Utf8.validateUtf8 (BS.pack [0xF4, 0x8F, 0xBF, 0xBF]) @?= c
      , testCase "invalid: overlong NUL (0xC0, 0x80)" $ do
          c <- cValidateUtf8 (BS.pack [0xC0, 0x80])
          Utf8.validateUtf8 (BS.pack [0xC0, 0x80]) @?= c
      , testCase "invalid: lone continuation byte (0x80)" $ do
          c <- cValidateUtf8 (BS.pack [0x80])
          Utf8.validateUtf8 (BS.pack [0x80]) @?= c
      , testCase "invalid: above U+10FFFF (0xF7,0xBF,0xBF,0xBF)" $ do
          c <- cValidateUtf8 (BS.pack [0xF7, 0xBF, 0xBF, 0xBF])
          Utf8.validateUtf8 (BS.pack [0xF7, 0xBF, 0xBF, 0xBF]) @?= c
      , testCase "invalid: lone surrogate U+D800 (0xED,0xA0,0x80)" $ do
          c <- cValidateUtf8 (BS.pack [0xED, 0xA0, 0x80])
          Utf8.validateUtf8 (BS.pack [0xED, 0xA0, 0x80]) @?= c
      , testCase "invalid: truncated 3-byte (0xE2, 0x82)" $ do
          c <- cValidateUtf8 (BS.pack [0xE2, 0x82])
          Utf8.validateUtf8 (BS.pack [0xE2, 0x82]) @?= c
      , testProperty "PV-agree: validateUtf8 == wok_validate_utf8 on arbitrary [Word8]"
          prop_validatorAgreement
      ]

-- ---------------------------------------------------------------------------
-- FFI bytes-in Slice 1: zero-copy saving pin (Task 4)
--
-- Pins the oracle-checked charge of each byte-handling cell to a CONCRETE value
-- at the STORE level (single alloc on a fresh AbstractHeap store; stCurBytes
-- after one allocPure from baseline 0 IS that alloc's charge). For several n,
-- using the same demoPattern the producers use:
--   (1) adopt: chargeOf (NForeignBytes bs) == 24  (fixed WokForeignBytes handle,
--       constant regardless of n; the buffer is off-heap so only the handle is
--       counted).
--   (2) copy : chargeOf (NBytes bs) == 16 + 8*ceil(n/8)  (header 16B + 8-byte-
--       rounded inline body).
--
-- Both sides are pinned to literal arithmetic recomputed inline (NOT via
-- 'wouldBeCBytes') so that a regression in either charge formula is caught --
-- asserting only the difference would be a tautology (chargeCopy ==
-- wouldBeCBytes (NBytes bs) by construction, so chargeCopy - chargeAdopt with
-- expectedSaving = wouldBeCBytes (NBytes bs) - 24 reduces to X-24 == X-24).
--
-- The zero-copy win: adopt's fixed 24B beats copy's 16+8*ceil(n/8) once n>=9.
-- For n<9 (e.g. n=0 -> 16, n=5 -> 24) the 24B handle dominates, so adoption is
-- NOT smaller -- the pin is on the byte formula per n, not on the sign of a
-- "saving". n=0/5 are kept as edge cases of the rounding formula.
-- ---------------------------------------------------------------------------

rcFfiBytesZeroCopySavingPin :: TestTree
rcFfiBytesZeroCopySavingPin = testGroup "zero-copy saving pin" $
  [ testCase ("n=" <> show n <> ": NForeignBytes charges 24B fixed") $ do
      let bs      = Utf8.demoPattern n
          s0      = St.emptyStore
          (_, s1) = St.allocPure (St.NForeignBytes bs) s0
      St.stCurBytes (St.stStats s1) @?= (24 :: Int)
  | n <- [0, 5, 10, 64, 100]
  ] ++
  [ testCase ("n=" <> show n <> ": NBytes charges 16 + 8*ceil(n/8), adopt fixed 24B") $ do
      let bs          = Utf8.demoPattern n
          s0          = St.emptyStore
          (_, sCopy)  = St.allocPure (St.NBytes bs) s0
          (_, sAdopt) = St.allocPure (St.NForeignBytes bs) s0
          chargeCopy  = St.stCurBytes (St.stStats sCopy)
          chargeAdopt = St.stCurBytes (St.stStats sAdopt)
      -- Pin BOTH sides to concrete values (formula recomputed inline as a
      -- literal expression, NOT via wouldBeCBytes), so a regression in the
      -- NBytes charge formula is caught.
      chargeAdopt @?= (24 :: Int)
      chargeCopy  @?= 16 + 8 * ((BS.length bs + 7) `div` 8)
  | n <- [0, 5, 10, 64, 100]
  ]

-- ---------------------------------------------------------------------------
-- FFI bytes-in Slice 1: soundness death tests (Task 5)
--
-- Two targeted assertions that prove the adopt path is safe under sharing and
-- under activation-escape, complementing the automatic corpus combinators.
--
-- (a) Dup/drop double-free guard.
--     '07-soundness-dup-share.wok' binds ONE adopted Bytes to 'b' and uses it
--     twice ('length b' and 'index b 0').  Both prims CONSUME their Bytes arg
--     (each calls 'dropAddr' after reading).  Perceus therefore inserts a dup
--     (rc 1->2) before the first use, then the two drops bring rc 2->1->0 and
--     fire the foreign free exactly once.  If the free fired more than once the
--     libc run would abort (heap corruption / SIGABRT).  The 'rc-c-backend-
--     parity' combinator in the auto-run corpus is the live guard: it passes
--     iff the CHeap run returns 'Right' and stats match the abstract run.
--     This test adds an explicit assertion on the output ('8') so the mechanism
--     is self-documenting; the parity oracle is what makes it a death test.
--
-- (b) Region-escape / early-free (UAF) regression guard.
--     '08-soundness-escape-return.wok' builds an adopted Bytes in a helper
--     ('makeIt') and returns it.  The value escapes the helper's activation.
--     If it were ever freed early (e.g. at the helper's return), 'length' in
--     'main' would be a use-after-free; on the CHeap / malloc-UAF-oracle
--     backend that would corrupt or abort, breaking the three-backend output
--     parity.  The meaningful assertion is therefore the output (== 8) across
--     all three backends: the escaping adopted Bytes is read correctly after it
--     has crossed the activation boundary, so it was not freed early.
--
--     NOTE: this test does NOT exercise the arena fence at runtime.  Adopted
--     Bytes is produced by a prim call ('RApp'), never by an 'isAlloc' RHS, so
--     the binder never reaches 'placeLet' / the 'isStringBinder' fence -- it is
--     unconditionally counted-Heap regardless of the fence.  Asserting
--     'arena_peak == 0' here would be vacuous (true with or without the fence),
--     so it is deliberately omitted.  The TcBytes fence is defence-in-depth for
--     a hypothetical future Bytes-producing alloc RHS (see Region.hs).
--
-- (c) Leak-balance.
--     The 'rc stats' group (auto-run via 'findByExtension') calls
--     'rcStatsHarness' on every '.wok' file in 'test/rc-ffi-bytes/'.
--     'rcStatsHarness' asserts 'stLive == rcBaseline' (return to the immortal
--     baseline, i.e. no leak) for the abstract-heap run.  The 'rc-c-backend-
--     parity' group asserts 'stLive == rcBaseline' for the C-heap run too.
--     Both new files are therefore automatically leak-balanced by the existing
--     combinators; no additional assertion is needed here.
-- ---------------------------------------------------------------------------

rcFfiBytesSoundness :: TestTree
rcFfiBytesSoundness = testGroup "ffi bytes soundness"
  [ -- -----------------------------------------------------------------------
    -- (a) Dup/drop double-free guard.
    -- Asserts correct output (8) through BOTH backends.  The CHeap run is the
    -- live double-free guard: a spurious free would crash libc before this
    -- assertion could ever be reached.
    testCase "07-soundness-dup-share: dup+drop gives correct output (double-free would abort)" $ do
      (absR, cR, _cAllocs, _cPeakBytes) <-
        withBothBackends "test/rc-ffi-bytes/07-soundness-dup-share.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 8 (length + index)"
            (T.pack "8") (RCM.rcOutput a)
          assertEqual "C output == 8 (double-free-free on libc)"
            (T.pack "8") (RCM.rcOutput c)
          assertEqual "output parity"
            (RCM.rcOutput a) (RCM.rcOutput c)
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible double-free): " <> show e)

  , -- -----------------------------------------------------------------------
    -- (b) Region-escape / early-free (UAF) regression guard.
    -- The adopted Bytes escapes its defining activation (returned from makeIt).
    -- The meaningful guard is the three-backend output parity (== 8): if the
    -- escaping value were freed early, the CHeap / malloc-UAF-oracle run would
    -- corrupt or abort and this parity would fail.  No arena assertion: the
    -- adopt path is a prim call, never an isAlloc RHS, so it never reaches the
    -- arena fence (arena_peak == 0 would be vacuous; see the (b) note above).
    testCase "08-soundness-escape-return: escaping adopted Bytes read correctly (no early free)" $ do
      (absR, cR, _cAllocs, _cPeakBytes) <-
        withBothBackends "test/rc-ffi-bytes/08-soundness-escape-return.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 8 (escape UAF would corrupt)"
            (T.pack "8") (RCM.rcOutput a)
          assertEqual "C output == 8 (escape UAF would corrupt)"
            (T.pack "8") (RCM.rcOutput c)
          assertEqual "output parity"
            (RCM.rcOutput a) (RCM.rcOutput c)
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible escape UAF): " <> show e)
  ]

-- ---------------------------------------------------------------------------
-- FFI Slice 4 Task 3: wok_bytes_fnv1a (FNV-1a) cross-check.
-- Verifies that the C implementation of FNV-1a matches the Haskell reference.
-- ---------------------------------------------------------------------------

rcBytesChecksumTests :: TestTree
rcBytesChecksumTests = testGroup "ffi bytes checksum (slice 4 task 3)"
  [ testCase "wok_bytes_fnv1a: FNV-1a matches referenceFNV1a" $ do
      hp <- Heap.wokHeapNew
      let testData = BS.pack [0, 1, 2, 3, 255]
      cellPtr <- Heap.wokBytesAlloc hp (fromIntegral (BS.length testData))
      -- Fill the cell with test data
      dataPtr <- Heap.wokBytesData cellPtr
      BS.useAsCString testData $ \cstr ->
        copyBytes (castPtr dataPtr) (castPtr cstr) (BS.length testData)
      -- Call the C checksum function
      cChecksum <- Heap.wokBytesFnv1a cellPtr
      -- Compute the expected value using the Haskell reference
      let expectedChecksum = FM.referenceFNV1a testData
      -- Assert C result matches Haskell reference
      assertEqual
        "C wok_bytes_fnv1a == Haskell referenceFNV1a"
        expectedChecksum
        cChecksum
      -- Clean up: drop the cell (rc -> 0), free it, then free the heap.
      rc0 <- Heap.wokDec cellPtr
      assertEqual "rc at zero before free" (0 :: Word64) rc0
      Heap.wokFree hp cellPtr
      Heap.wokHeapFree hp
  ]

-- ---------------------------------------------------------------------------
-- Task 5 (FFI Slice 2): foreign-call IR elaboration + reference execution.
-- The reference backend executes pure Haskell models of the blessed symbols;
-- the wok programs have type 'U64 with IO' or 'Bytes with IO' for 'main'.
-- The IO ground effect is never handled; the interpreter evaluates the body
-- directly (IO is a no-op in the reference machine).
-- ---------------------------------------------------------------------------

foreignReferenceTests :: TestTree
foreignReferenceTests = testGroup "foreign reference"
  [ -- AC1: memchr finds the byte at index 1 (0-based).
    -- Libc.memchr [65,66,67] 66 3  =>  1
    testCase "memchr: byte present, returns index" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
        , "main = Libc.memchr (fromList [65, 66, 67]) 66 3"
        ]
      result @?= Right (T.pack "1")

  , -- AC2: memchr does not find the byte; returns n (= 3).
    -- Libc.memchr [65,66,67] 99 3  =>  3
    testCase "memchr: byte absent, returns n" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
        , "main = Libc.memchr (fromList [65, 66, 67]) 99 3"
        ]
      result @?= Right (T.pack "3")

  , -- AC3: strndup copies up to n bytes; n < length, no NUL, so the n-byte prefix.
    -- Libc.strndup [1,2,3,4] 2  =>  fromList [1,2]
    testCase "strndup: n < length, no NUL, returns prefix" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  owned strndup : Bytes -> U64 -> Bytes with IO"
        , "main = Libc.strndup (fromList [1, 2, 3, 4]) 2"
        ]
      result @?= Right (T.pack "Bytes[1,2]")

  , -- AC4: strndup with n >= length, no NUL, returns full buffer.
    -- Libc.strndup [1,2,3,4] 10  =>  fromList [1,2,3,4]
    testCase "strndup: n >= length, no NUL, returns full buffer" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  owned strndup : Bytes -> U64 -> Bytes with IO"
        , "main = Libc.strndup (fromList [1, 2, 3, 4]) 10"
        ]
      result @?= Right (T.pack "Bytes[1,2,3,4]")

  , -- AC5: strndup STOPS at the first NUL even when n spans past it. Exercises
    -- the defining 'BS.takeWhile (/= 0)' branch of foreignStrndup.
    -- Libc.strndup [1,0,3,4] 4  =>  fromList [1]
    testCase "strndup: NUL before n, truncates at NUL" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  owned strndup : Bytes -> U64 -> Bytes with IO"
        , "main = Libc.strndup (fromList [1, 0, 3, 4]) 4"
        ]
      result @?= Right (T.pack "Bytes[1]")

  , -- AC6: pure model regression for huge n (>= 2^63).
    -- Before the fix, fromIntegral (2^63 :: Word64) :: Int wrapped NEGATIVE
    -- and BS.take negative returned empty, diverging from the CHeap path.
    -- After the fix the clamp min n len is computed in the Word64 domain, so
    -- a huge n is treated as n >= length and the full prefix is returned.
    -- Libc.strndup [1,2,3] (2^63)  =>  fromList [1,2,3]
    testCase "strndup pure model: huge n (>= 2^63) returns full buffer, not empty" $ do
      let buf = BS.pack [1, 2, 3]
          hugeN = 2 ^ (63 :: Int) :: Word64
      FM.foreignStrndup buf hugeN @?= buf

  , -- AC7: interpreter-level regression for huge n (2^63).
    -- Exercises the reference backend + the fix end-to-end.
    -- Libc.strndup [1,2,3] 9223372036854775808  =>  Bytes[1,2,3]
    testCase "strndup: n = 2^63 (huge), returns full buffer via interpreter" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  owned strndup : Bytes -> U64 -> Bytes with IO"
        , "main = Libc.strndup (fromList [1, 2, 3]) 9223372036854775808"
        ]
      result @?= Right (T.pack "Bytes[1,2,3]")
  ]

-- ---------------------------------------------------------------------------
-- FFI Slice 2 Task 6: 3-backend parity for real libc memchr/strndup + borrow-out.
--
-- The oracle enforces:
--   (a) OUTPUT parity: reference == RC-abstract == RC-CHeap for each case.
--   (b) PEAK_BYTES parity: abstract stPeakBytes == C wok_stat_peak_bytes.
--   (c) ADOPT SAVING pin: a strndup result of length L charges 24 B (the
--       WokForeignBytes handle) on BOTH backends, and that is LESS than the
--       NBytes copy charge (16 + 8*ceil(L/8)).
--   (d) NForeignBytes arg (06): strndup's adopted result passes as a memchr arg;
--       rcReadBytes and rcBorrowCHeapPtr both handle the 0xFFFB tag.
--
-- For the corpus files, 'withBothBackends' drives the abstract and C-heap backends;
-- the reference interpreter provides the third-backend oracle for output.
-- ---------------------------------------------------------------------------

rcFfiForeignParity :: TestTree
rcFfiForeignParity = testGroup "3-backend parity + adopt saving pin"
  [ -- -------------------------------------------------------------------
    -- (a) memchr: byte present (output = 1)
    testCase "01-memchr-present: 3-backend output parity" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/01-memchr-present.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 1" (T.pack "1") (RCM.rcOutput a)
          assertEqual "C output == 1"        (T.pack "1") (RCM.rcOutput c)
          assertEqual "output parity"        (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (a) memchr: byte absent (output = 3, the clamped n)
    testCase "02-memchr-absent: 3-backend output parity (absent sentinel == n)" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/02-memchr-absent.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 3" (T.pack "3") (RCM.rcOutput a)
          assertEqual "C output == 3"        (T.pack "3") (RCM.rcOutput c)
          assertEqual "output parity"        (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (b) strndup prefix: n < length, no NUL => Bytes[1,2]; adopt charges 24 B
    testCase "03-strndup-prefix: 3-backend parity + adopt 24 B handle" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/03-strndup-prefix.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == Bytes[1,2]" (T.pack "Bytes[1,2]") (RCM.rcOutput a)
          assertEqual "C output == Bytes[1,2]"        (T.pack "Bytes[1,2]") (RCM.rcOutput c)
          assertEqual "output parity"                 (RCM.rcOutput a)      (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
          -- Pin: the strndup result (2 bytes) is adopted into a 24 B handle.
          -- Derive BOTH charges from the actual store model (St.allocPure), then
          -- compare each against an independent expected constant (NOT the same
          -- code path under test). At length 2 the charges coincide (24 B), so the
          -- meaningful saving is exercised by the 100-byte pin below.
          let resultBs    = BS.pack [1, 2]
              (_, sAdopt) = St.allocPure (St.NForeignBytes resultBs) St.emptyStore
              (_, sCopy)  = St.allocPure (St.NBytes resultBs)        St.emptyStore
          assertEqual "strndup result=2 bytes: adopt charge == 24 B (handle)"
            (24 :: Int) (St.stPeakBytes (St.stStats sAdopt))
          assertEqual "strndup result=2 bytes: copy charge == 24 B (16 + 8*ceil(2/8))"
            (24 :: Int) (St.stPeakBytes (St.stStats sCopy))
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (b) strndup full: n >= length, no NUL => Bytes[1,2,3,4]
    -- This is the key adopt saving case: 4 bytes copied = 24 B (NBytes 4);
    -- 4 bytes adopted = 24 B handle. Same charge here; pin both.
    testCase "04-strndup-full: 3-backend parity" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/04-strndup-full.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == Bytes[1,2,3,4]" (T.pack "Bytes[1,2,3,4]") (RCM.rcOutput a)
          assertEqual "C output == Bytes[1,2,3,4]"        (T.pack "Bytes[1,2,3,4]") (RCM.rcOutput c)
          assertEqual "output parity"                     (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (b) strndup NUL-truncate: strndup [1,0,3,4] 4 => Bytes[1] (1 byte)
    -- The adopt saving vs copy for 1 byte:
    --   NBytes 1 => 16 + 8*ceil(1/8) = 16 + 8 = 24 B
    --   NForeignBytes 1 => 24 B (fixed handle; buffer is off-heap)
    -- Saving = 0 B here (both 24 B). This is correct: the saving grows with length.
    testCase "05-strndup-nul: 3-backend parity + NUL-truncate sentinel" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/05-strndup-nul.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == Bytes[1]" (T.pack "Bytes[1]") (RCM.rcOutput a)
          assertEqual "C output == Bytes[1]"        (T.pack "Bytes[1]") (RCM.rcOutput c)
          assertEqual "output parity"               (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (c) ADOPT SAVING PIN: for a large buffer (length 100), pin the concrete
    -- charge difference between an adopt (24 B) and an equivalent copy (NBytes).
    -- This is the Slice-1 §4.6 zero-copy-saving invariant, de-tautologized.
    -- Length 100 bytes: NBytes charges 16 + 8*ceil(100/8) = 16 + 8*13 = 16 + 104 = 120 B.
    -- NForeignBytes charges 24 B. Saving = 96 B.
    testCase "adopt saving pin: 100-byte result => 24 B handle vs 120 B copy" $ do
      let l            = 100
          adoptCharge  = 24 :: Int
          copyCharge   = 16 + 8 * ((l + 7) `div` 8)   -- = 16 + 8*13 = 120
          saving       = copyCharge - adoptCharge       -- = 96
      adoptCharge @?= (24 :: Int)
      copyCharge  @?= (120 :: Int)
      saving      @?= (96 :: Int)
      -- Verify via the abstract store model (not a file run, to keep it fast).
      let bs      = BS.replicate l 0x41   -- 100 'A' bytes
          s0      = St.emptyStore
          (_, sCopy)  = St.allocPure (St.NBytes bs)        s0
          (_, sAdopt) = St.allocPure (St.NForeignBytes bs) s0
      St.stPeakBytes (St.stStats sCopy)  @?= copyCharge
      St.stPeakBytes (St.stStats sAdopt) @?= adoptCharge

  , -- -------------------------------------------------------------------
    -- (d) NForeignBytes arg: 06-memchr-on-adopted passes an adopted Bytes as
    -- the memchr argument. rcReadBytes and rcBorrowCHeapPtr must handle 0xFFFB.
    testCase "06-memchr-on-adopted: NForeignBytes arg handled by both backends" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/06-memchr-on-adopted.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          -- strndup [1,2,3,4] 4 => [1,2,3,4]; memchr for byte=3 in 4 bytes => index 2
          assertEqual "abstract output == 2" (T.pack "2") (RCM.rcOutput a)
          assertEqual "C output == 2"        (T.pack "2") (RCM.rcOutput c)
          assertEqual "output parity"        (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (e) HEAP-OVERREAD REGRESSION: strndup [1,2,3] 10 with NO zero byte and
    -- n (10) > length (3). The CHeap scan MUST be clamped to the buffer length
    -- (min n argLen), so real c_strndup never reads past the wok buffer and
    -- returns exactly the FULL buffer Bytes[1,2,3] -- matching the model, which
    -- clamps via BS.take (never reads past the buffer end).
    --
    -- WHAT THIS PINS: the CLAMPED, correct behavior (result == full buffer,
    -- length == argLen == 3, identical across all 3 backends). A regression that
    -- returns MORE than argLen bytes (an unclamped scan landing on a non-NUL run
    -- of trailing heap memory) makes the CHeap output diverge and trips this
    -- parity assertion.
    -- WHAT THIS DOES NOT PIN: the overread itself is undefined behavior whose
    -- VALUE-level visibility is non-deterministic (if the bytes immediately after
    -- the buffer happen to be NUL, an unclamped strndup stops at the boundary and
    -- the output coincidentally matches). The memory-safety guarantee against the
    -- overread is the ASan death-test in Task 7; this is the logical complement.
    testCase "07-strndup-overrun: clamp to buffer len (no overread)" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/07-strndup-overrun.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == Bytes[1,2,3] (clamped)" (T.pack "Bytes[1,2,3]") (RCM.rcOutput a)
          assertEqual "C output == Bytes[1,2,3] (clamped, no overread)" (T.pack "Bytes[1,2,3]") (RCM.rcOutput c)
          assertEqual "output parity (clamp == model)" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)

  , -- -------------------------------------------------------------------
    -- (e) Adopt dup/drop: strndup result shared across two uses.
    -- Perceus inserts a dup (rc 1->2) before the second use and two drops
    -- (2->1->0) at the two consuming sites; libc free fires at rc=0.
    -- A double-free would abort the CHeap run before this assertion is
    -- reached. MUTATION-CONFIRMED: temporarily injecting `free(p)` right
    -- after adoptCHeapPtr (src/Wok/Interp/RC/Machine.hs) caused a SIGABRT
    -- (macOS libc double-free detection) that killed the test process before
    -- any result was reported; the injection was reverted.
    testCase "08-strndup-dup-share: adopt dup+drop frees once (double-free would abort)" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/08-strndup-dup-share.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 14 (length 4 + index 0 = 10)"
            (T.pack "14") (RCM.rcOutput a)
          assertEqual "C output == 14 (double-free-free on libc malloc)"
            (T.pack "14") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible double-free): " <> show e)

  , -- -------------------------------------------------------------------
    -- (f) Borrow-out lifetime: memchr borrows `b`, `b` survives + is used again.
    -- Perceus dups `b` before memchr (rc 1->2) and drops the borrow-copy inside
    -- the dispatch (rc 2->1). `length b` then consumes the last ref (rc 1->0).
    -- A UAF (borrow consuming the original) would corrupt `b`'s byte data;
    -- the CHeap run would crash or produce a wrong answer. 3-backend parity
    -- pins that the lent buffer is intact after the call.
    testCase "09-borrow-lifetime: borrowed Bytes intact after memchr call" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/09-borrow-lifetime.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          -- memchr [65,66,67] 65 3 => 0 (found at index 0); length [65,66,67] => 3
          -- 0 + 3 = 3
          assertEqual "abstract output == 3 (borrow + length)"
            (T.pack "3") (RCM.rcOutput a)
          assertEqual "C output == 3 (borrow intact, no UAF)"
            (T.pack "3") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible borrow UAF): " <> show e)

  , -- -------------------------------------------------------------------
    -- (g) Huge-n clamp regression: n = 2^63 must NOT wrap to negative in Int
    -- and must return the full buffer, not empty. Pins the Word64-domain clamp
    -- fix in foreignStrndup / the abstract model (the CHeap path already
    -- clamped correctly, so this checks the abstract backend now agrees).
    testCase "10-strndup-huge-n: n = 2^63 clamped to buffer len, returns full buffer" $ do
      (absR, cR, _, cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/10-strndup-huge-n.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == Bytes[1,2,3] (clamped, not empty)"
            (T.pack "Bytes[1,2,3]") (RCM.rcOutput a)
          assertEqual "C output == Bytes[1,2,3] (huge-n clamp)"
            (T.pack "Bytes[1,2,3]") (RCM.rcOutput c)
          assertEqual "output parity (models agree on huge n)"
            (RCM.rcOutput a) (RCM.rcOutput c)
          assertEqual "peak_bytes parity"
            (fromIntegral (St.stPeakBytes (RCM.rcStats a)) :: Word64) cPeakBytes
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED: " <> show e)
  ]

-- ---------------------------------------------------------------------------
-- FFI Slice 2 Task 7: soundness tests with mutation-confirmed death teeth.
--
-- These tests cover the ADOPT and BORROW-OUT paths through the CHeap backend:
--
-- (a) ADOPT DUP/DROP double-free guard (08-strndup-dup-share).
--     A strndup result is shared across two consuming uses; Perceus inserts a
--     dup (rc 1->2) and the two drops (2->1->0) fire libc free exactly once.
--     The CHeap run is the live guard: a double-free aborts before the
--     assertion is reached. MUTATION-CONFIRMED: injecting `free(p)` right
--     after adoptCHeapPtr in src/Wok/Interp/RC/Machine.hs (strndup/CHeap arm)
--     caused an immediate SIGABRT (macOS libc double-free detection) on the
--     CHeap run; the process died before any test result was printed. The
--     injection was reverted and confirmed clean (3 of 3 tests pass).
--
-- (b) BORROW-OUT lifetime (09-borrow-lifetime).
--     Covered inline in rcFfiForeignParity as case (f); the 3-backend output
--     parity IS the UAF guard. Included here for the dedicated soundness
--     commentary.
--
-- SANITIZER COVERAGE (honest statement):
-- The borrow-out and adopt paths run under the slab allocator (no redzones) in
-- the default `cabal test`. An overread past a slab-internal buffer would land
-- in intra-slab memory and be invisible. The STANDALONE C lifecycle tests
-- (wok_rc_test.c / wok_arena_test.c) under ASan+WOK_RC_MALLOC cover:
--   - WokForeignBytes alloc/free cycle + libc free at rc-zero + LSan negative control
-- THE HASKELL INTERP BORROW-OUT PATH IS NOW ALSO COVERED:
--   `bash scripts/asan-runtime.sh interp` runs the full rc-ffi-foreign corpus
--   through the wok RC interpreter under ASan+WOK_RC_MALLOC (cabal flag asan).
--   POSITIVE: the corpus runs CLEAN (no ASan reports on the clamped path).
--   NEGATIVE CONTROL (mutation-confirmed): flag ffi-noclamp-negctrl drops the
--   scan clamp; asan-overrun-probe.wok (8-byte no-zero buffer, n=128) crosses
--   the cell redzone and aborts, proving the clamp gate has teeth.
--   The residual documented in earlier revisions is NOW CLOSED.
-- ---------------------------------------------------------------------------

rcFfiForeignSoundness :: TestTree
rcFfiForeignSoundness = testGroup "ffi foreign soundness"
  [ -- -----------------------------------------------------------------------
    -- (a) Adopt dup/drop double-free guard.
    -- The CHeap run IS the live double-free detector. MUTATION-CONFIRMED:
    -- see module comment above for the observed SIGABRT and reverted injection.
    testCase "08-strndup-dup-share: adopt dup+drop frees once (double-free guard)" $ do
      (absR, cR, _, _cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/08-strndup-dup-share.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 14" (T.pack "14") (RCM.rcOutput a)
          assertEqual "C output == 14 (no double-free)" (T.pack "14") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible double-free): " <> show e)

  , -- -----------------------------------------------------------------------
    -- (b) Borrow-out lifetime: borrowed Bytes survives the call and is correct.
    testCase "09-borrow-lifetime: borrowed Bytes intact after memchr call" $ do
      (absR, cR, _, _cPeakBytes) <-
        withBothBackends "test/rc-ffi-foreign/09-borrow-lifetime.wok"
      case (absR, cR) of
        (Right a, Right c) -> do
          assertEqual "abstract output == 3" (T.pack "3") (RCM.rcOutput a)
          assertEqual "C output == 3 (borrow intact)" (T.pack "3") (RCM.rcOutput c)
          assertEqual "output parity" (RCM.rcOutput a) (RCM.rcOutput c)
        (Left e, _) -> assertFailure ("abstract FAILED: " <> show e)
        (_, Left e) -> assertFailure ("C FAILED (possible borrow UAF): " <> show e)
  ]

-- ---------------------------------------------------------------------------
-- FFI Slice 2 Task 7: end-to-end IO discharge tests.
--
-- A foreign-calling program at entry has IO in its effect row. The reference
-- interpreter treats IO as a ground effect (no handler needed; discharged by
-- running the program). These tests verify:
--   (1) A program calling a foreign function typechecks and runs to a value.
--   (2) A function calling a foreign function WITHOUT a `with IO` signature
--       annotation is rejected (UndischargedEffect / RowMismatch).
-- ---------------------------------------------------------------------------

foreignIoDischargeTests :: TestTree
foreignIoDischargeTests = testGroup "foreign IO discharge"
  [ -- AC1: end-to-end IO -- a foreign-calling `main` typechecks and runs.
    -- Libc.memchr [65,66,67] 66 3  =>  1 (byte 66 at index 1).
    -- IO is ground: the reference interpreter evaluates the body directly.
    testCase "memchr at entry: IO ground effect, typechecks and runs to value" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
        , "main = Libc.memchr (fromList [65, 66, 67]) 66 3"
        ]
      result @?= Right (T.pack "1")

  , -- AC2: end-to-end IO with strndup -- adopted result runs and renders correctly.
    testCase "strndup at entry: IO ground effect, adopted Bytes renders" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Bytes"
        , "foreign module Libc \"c\" free \"free\" where"
        , "  owned strndup : Bytes -> U64 -> Bytes with IO"
        , "main = Libc.strndup (fromList [1, 2, 3]) 3"
        ]
      result @?= Right (T.pack "Bytes[1,2,3]")

  , -- AC3: a caller without `with IO` that calls a foreign function is rejected.
    -- The foreign call introduces IO into the caller's row; if the caller is
    -- declared pure (no `with IO`), the undischarged IO is a type error.
    testCase "caller without `with IO` sig calling foreign fn: rejected (UndischargedEffect)" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "-- declared pure but body introduces IO -- must be rejected"
             , "pure_caller : Bytes -> U64"
             , "pure_caller b = Libc.memchr b 65 3"
             ]
             "pure_caller" of
        Left err ->
          assertBool ("expected UndischargedEffect or RowMismatch, got: " ++ err)
            (  "UndischargedEffect" `Data.List.isInfixOf` err
            || "RowMismatch"        `Data.List.isInfixOf` err )
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , -- AC4: IO-handler rejection -- a with-handler targeting the ground IO is
    -- rejected (IOEffectNotHandleable). Regression pin: confirming the foreign-
    -- module declaration does not bypass the IO-handler gate.
    testCase "with-handler over IO in foreign-module context: rejected (IOEffectNotHandleable)" $
      case schemeOf
             [ "foreign module Libc \"c\" free \"free\" where"
             , "  memchr : Bytes -> U64 -> U64 -> U64 with IO"
             , "bad_handler x ="
             , "  with IO { return v -> v }"
             , "  x"
             ]
             "bad_handler" of
        Left err ->
          assertBool ("expected IOEffectNotHandleable, got: " ++ err)
            ("IOEffectNotHandleable" `Data.List.isInfixOf` err)
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)

  , -- AC5 (FFI Slice 3 Task 4): end-to-end IO with the borrow disposition --
    -- a `Demo.lendBuffer`-calling `main` typechecks and runs, with `Borrow`
    -- and the foreign module declared via `import Borrow` (the prelude),
    -- exactly the surface a real user program would use. buf[i] = i & 0xFF,
    -- so byteAt (Demo.lendBuffer 8) 5 = 5.
    testCase "Demo.lendBuffer at entry: IO ground effect, typechecks and runs to value" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Borrow"
        , "main = byteAt (Demo.lendBuffer 8) 5"
        ]
      result @?= Right (T.pack "5")

  , -- AC6: a caller without `with IO` that calls Demo.lendBuffer is rejected,
    -- mirroring AC3 for the borrow disposition. The Borrow result is consumed
    -- locally (never escapes pure_caller), so the only failure is the
    -- undischarged IO row, not a CarrierEscape. Uses 'runSourceWith' (the
    -- real loader, resolving `import Borrow`) rather than 'schemeOf'
    -- (which seeds 'Builtins.initialEnv' directly with no import
    -- resolution): `Borrow` and `Demo` are prelude-declared, not builtins.
    testCase "caller without `with IO` sig calling Demo.lendBuffer: rejected (UndischargedEffect)" $ do
      result <- runSourceWith Pipeline.elaborateProgram $ T.unlines
        [ "module Main"
        , "import Borrow"
        , "pure_caller : U64 -> U64"
        , "pure_caller n = length (Demo.lendBuffer n)"
        , "main = pure_caller 8"
        ]
      case result of
        Left err ->
          assertBool ("expected UndischargedEffect or RowMismatch, got: " ++ err)
            (  "UndischargedEffect" `Data.List.isInfixOf` err
            || "RowMismatch"        `Data.List.isInfixOf` err )
        Right s  -> assertFailure ("expected rejection, got: " ++ T.unpack s)
  ]
